dofile("helper_init.lua")
hotkeyHelperStatus = false
_G.hotkeyHelperStatus = hotkeyHelperStatus
helperConfigDefaults = nil

-- Spell lookup cache: Spells.getSpellByWords/getSpellByName are called every
-- helper tick by healing/shooter rules, but the spell table is immutable for
-- the session. Cache the lookup (storing `false` for misses so they aren't
-- repeated). Invalidated on logout in offline().
-- Stored as globals (no chunk-level `local`) to avoid pushing helper.lua's
-- main function past Lua's 200-active-local limit.
_G._spellWordsCache = _G._spellWordsCache or {}
_G.getCachedSpell = _G.getCachedSpell or function(words)
    if not words or words == "" then return nil end
    local cache = _G._spellWordsCache
    local cached = cache[words]
    if cached ~= nil then
        return cached or nil
    end
    if not Spells then return nil end
    local spell = nil
    if Spells.getSpellByWords then
        spell = Spells.getSpellByWords(words)
    end
    if not spell and Spells.getSpellByName then
        spell = Spells.getSpellByName(words)
    end
    cache[words] = spell or false
    return spell
end

_G.cavebotStartTime = _G.cavebotStartTime or nil
_G.cavebotManualStop = _G.cavebotManualStop or true
_G.debugPopupConfig = _G.debugPopupConfig or { x = 0, y = 100, bgOpacity = 0 }
_G.debugOpacityPopup = nil

-- ============================================================================
-- HELPER-STYLED DIALOG WRAPPERS
-- ============================================================================
function helperDisplayGeneralBox(title, message, buttons, onEnterCallback, onEscapeCallback)
    local staticSizes = {
        width = { max = 916, min = 116 },
        height = { min = 56, max = 616 }
    }
    local currentSizes = { width = 0, height = 0 }

    local messageBox = g_ui.createWidget('HelperMessageBoxWindow', rootWidget)
    applyOpacityToWindow(messageBox)

    -- HelperMessageBoxWindow is a plain NewMainWindow (UIWindow), NOT a UIMessageBox,
    -- so it has no :ok()/:cancel(). Every button callback below starts with
    -- messageBox:ok(), which was raising "attempt to call method 'ok' (a nil value)"
    -- and aborting the callback before its real action (saveProfile, etc.) ran --
    -- making every profile dialog button silently do nothing. Provide them here:
    -- destroy() closes the dialog and the modal manager's onDestroy hook restores
    -- the helper.
    messageBox.ok = function(self)
        if self and not self:isDestroyed() then self:destroy() end
    end
    messageBox.cancel = messageBox.ok

    -- Title is drawn natively by the window (text-align: top in the style puts it
    -- on the title bar). A child Label anchored to parent.top fell below the
    -- padding-top, landing inside the content area instead of the title bar.
    messageBox:setText(title)

    messageBox.content = messageBox:getChildById('content')

    local avgCharWidth = 7
    local maxContentWidth = staticSizes.width.max - 32
    local maxCharsPerLine = math.floor(maxContentWidth / avgCharWidth)
    if maxCharsPerLine < 40 then maxCharsPerLine = 40 end
    if maxCharsPerLine > 100 then maxCharsPerLine = 100 end

    messageBox.content:setText(message)
    messageBox.content:resizeToText()
    messageBox.content:resize(messageBox.content:getWidth(), messageBox.content:getHeight())
    currentSizes.width = currentSizes.width + messageBox.content:getWidth() + 32

    messageBox.holder = messageBox:getChildById('holder')

    local totalButtonWidth = 0
    local buttonHeight = 20
    for i = 1, #buttons do
        local button = g_ui.createWidget('HelperButton', messageBox.holder)
        button:setWidth(math.max(48, 10 + (string.len(buttons[i].text) * 8)))
        button:setHeight(20)
        button:setText(buttons[i].text)
        connect(button, { onClick = buttons[i].callback })
        button:addAnchor(AnchorTop, 'parent', AnchorTop)
        buttonHeight = button:getHeight()
        totalButtonWidth = totalButtonWidth + button:getWidth()
        if i == 1 then
            button:addAnchor(AnchorRight, 'parent', AnchorRight)
        else
            button:addAnchor(AnchorRight, 'prev', AnchorLeft)
            button:setMarginRight(10)
            totalButtonWidth = totalButtonWidth + 10
        end
    end

    -- Height must mirror the HelperMessageBoxWindow layout exactly. The window's
    -- padding-top (the title bar) and the content's margin-top (which reserves
    -- room for the title label) used to be ignored, leaving the window ~17px too
    -- short: the holder (anchored to parent.bottom) collapsed and the buttons
    -- overflowed past the clickable area. Sum, top to bottom:
    --   padding-top + content margin-top + content + separator block
    --   (margin-top 10 + height 2 + margin-bottom 4) + holder margin-top
    --   + button + padding-bottom
    local separatorBlock = 16
    currentSizes.height =
        messageBox:getPaddingTop() +
        messageBox.content:getMarginTop() +
        messageBox.content:getHeight() +
        separatorBlock +
        messageBox.holder:getMarginTop() +
        buttonHeight +
        messageBox:getPaddingBottom()

    local minWidthForButtons = totalButtonWidth + 50
    currentSizes.width = math.max(currentSizes.width, minWidthForButtons)

    messageBox:setWidth(math.min(staticSizes.width.max, math.max(staticSizes.width.min, currentSizes.width)))
    messageBox:setHeight(math.min(staticSizes.height.max, math.max(staticSizes.height.min, currentSizes.height)))

    if onEnterCallback then
        connect(messageBox, { onEnter = onEnterCallback })
    end
    if onEscapeCallback then
        connect(messageBox, { onEscape = onEscapeCallback })
    end

    -- Integrate with modal manager to hide helper while dialog is open
    if _G.helperModalEnter then
        _G.helperModalEnter(messageBox, { inputLock = false })
    end

    return messageBox
end

-- HelperUIInputBox: same API as UIInputBox but uses helper-styled widgets
HelperUIInputBox = extends(UIWindow, 'HelperUIInputBox')

function HelperUIInputBox.create(title, okCallback, cancelCallback)
    local inputBox = HelperUIInputBox.internalCreate()
    inputBox:setText(title)
    inputBox.inputs = {}
    inputBox.onEnter = function()
        local results = {}
        for _, func in pairs(inputBox.inputs) do
            table.insert(results, func())
        end
        okCallback(unpack(results))
        inputBox:destroy()
    end
    inputBox.onEscape = function()
        if cancelCallback then cancelCallback() end
        inputBox:destroy()
    end
    return inputBox
end

function HelperUIInputBox:addLabel(text)
    local label = g_ui.createWidget('HelperInputBoxLabel', self)
    label:setText(text)
    return label
end

function HelperUIInputBox:addLineEdit(labelText, defaultText, maxLength)
    if labelText then self:addLabel(labelText) end
    local lineEdit = g_ui.createWidget('HelperInputBoxLineEdit', self)
    if defaultText then lineEdit:setText(defaultText) end
    if maxLength then lineEdit:setMaxLength(maxLength) end
    table.insert(self.inputs, function() return lineEdit:getText() end)
    return lineEdit
end

function HelperUIInputBox:addTextEdit(labelText, defaultText, maxLength, visibleLines)
    if labelText then self:addLabel(labelText) end
    local textEdit = g_ui.createWidget('HelperInputBoxTextEdit', self)
    if defaultText then textEdit:setText(defaultText) end
    if maxLength then textEdit:setMaxLength(maxLength) end
    visibleLines = visibleLines or 1
    textEdit:setHeight(textEdit:getHeight() * visibleLines)
    table.insert(self.inputs, function() return textEdit:getText() end)
    return textEdit
end

function HelperUIInputBox:addCheckBox(text, checked)
    local checkBox = g_ui.createWidget('HelperInputBoxCheckBox', self)
    checkBox:setText(text)
    checkBox:setChecked(checked)
    table.insert(self.inputs, function() return checkBox:isChecked() end)
    return checkBox
end

function HelperUIInputBox:addComboBox(labelText, ...)
    if labelText then self:addLabel(labelText) end
    local comboBox = g_ui.createWidget('HelperInputBoxComboBox', self)
    local options = { ... }
    for i = 1, #options do comboBox:addOption(options[i]) end
    table.insert(self.inputs, function() return comboBox:getCurrentOption() end)
    return comboBox
end

function HelperUIInputBox:addSpinBox(labelText, minimum, maximum, value, step)
    if labelText then self:addLabel(labelText) end
    local spinBox = g_ui.createWidget('HelperInputBoxSpinBox', self)
    spinBox:setMinimum(minimum)
    spinBox:setMaximum(maximum)
    spinBox:setValue(value)
    spinBox:setStep(step)
    table.insert(self.inputs, function() return spinBox:getValue() end)
    return spinBox
end

function HelperUIInputBox:display(okButtonText, cancelButtonText)
    okButtonText = okButtonText or tr('Ok')
    cancelButtonText = cancelButtonText or tr('Cancel')
    local buttonsWidget = g_ui.createWidget('HelperInputBoxButtonsPanel', self)
    local okButton = g_ui.createWidget('HelperInputBoxButton', buttonsWidget)
    okButton:setText(okButtonText)
    okButton.onClick = self.onEnter
    local cancelButton = g_ui.createWidget('HelperInputBoxButton', buttonsWidget)
    cancelButton:setText(cancelButtonText)
    cancelButton.onClick = self.onEscape
    buttonsWidget:setHeight(okButton:getHeight())
    rootWidget:addChild(self)
    self:setStyle('HelperInputBoxWindow')

    -- Integrate with modal manager to hide helper while input box is open
    if _G.helperModalEnter then
        _G.helperModalEnter(self, { inputLock = false })
    end
end

