-- Enforce runtime pause when global helper is disabled, without changing user toggles/config.
local function applyGlobalHelperRuntimeState()
    local recorder = hunting_recorderModule or
        (_G and _G.hunting_recorderModule) or
        (modules and modules.game_helper and modules.game_helper.hunting_recorderModule)

    if hotkeyHelperStatus then
        if recorder and recorder.resumeCavebotIfNeeded then
            scheduleEvent(function()
                if hotkeyHelperStatus then
                    pcall(function()
                        recorder.resumeCavebotIfNeeded()
                    end)
                end
            end, 100)
        end
        return
    end

    -- Pause cavebot runtime without changing checkbox/config state.
    if recorder and recorder.walking and recorder.stopWalk then
        pcall(function()
            recorder.stopWalk(true) -- automatic stop: keep manual-stop state untouched
        end)
    end
    if cavebotWalker and cavebotWalker.stop then
        pcall(function()
            cavebotWalker.stop()
        end)
    end
end

-- Clear all shooter debug widgets
local function clearShooterDebugWidgets()
    for _, widget in ipairs(shooterDebugWidgets) do
        if widget and widget.destroy then
            widget:destroy()
        end
    end
    shooterDebugWidgets = {}
end

local function scheduleDebugWidgetsClear()
    -- Cancel previous scheduled clear if any
    if shooterDebugClearEvent then
        removeEvent(shooterDebugClearEvent)
        shooterDebugClearEvent = nil
    end
    -- Schedule clear after 1 second
    shooterDebugClearEvent = scheduleEvent(function()
        clearShooterDebugWidgets()
        shooterDebugClearEvent = nil
    end, 1000)
end

-- Direction colors for debug visualization (different color per direction)
local directionColors = {
    [Directions.North] = { bg = '#0000FF30', border = '#0000FF', name = 'N' }, -- Blue
    [Directions.East]  = { bg = '#FFFF0030', border = '#FFFF00', name = 'E' }, -- Yellow
    [Directions.South] = { bg = '#FF00FF30', border = '#FF00FF', name = 'S' }, -- Magenta
    [Directions.West]  = { bg = '#00FFFF30', border = '#00FFFF', name = 'W' }, -- Cyan
}

-- Create a debug widget on a tile
local function createShooterDebugWidget(position, hasCreature, direction)
    local tile = g_map.getTile(position)
    if not tile then return end

    -- Use fixed tile size for better visibility
    local tileSize = 64

    local widget = g_ui.createWidget('UIWidget')
    widget.shooterDebugPosition = { x = position.x, y = position.y, z = position.z }
    widget:setSize({ width = tileSize, height = tileSize })
    widget:setPhantom(true)
    widget:setFocusable(false)
    widget:setBorderWidth(2)
    widget:setTextAlign(AlignCenter)

    if widget.setFont then
        widget:setFont('verdana-11px-monochrome')
    end

    local colors = directionColors[direction] or { bg = '#FF000030', border = '#FF0000', name = '?' }

    if hasCreature then
        -- Green for tiles with monsters
        widget:setBackgroundColor('#00FF0060')
        widget:setBorderColor('#00FF00')
        widget:setText('HIT')
        widget:setColor('#00FF00')
    else
        -- Direction-specific color for empty tiles
        widget:setBackgroundColor(colors.bg)
        widget:setBorderColor(colors.border)
        widget:setText(colors.name)
        widget:setColor(colors.border)
    end

    tile:attachWidget(widget)
    table.insert(shooterDebugWidgets, widget)
end

-- ============================================================================
-- LURE DEBUG VISUAL SYSTEM
-- ============================================================================

local function clearLureDebugWidgets()
    for _, widget in ipairs(lureDebugWidgets) do
        if widget and widget.destroy then
            pcall(function() widget:destroy() end)
        end
    end
    lureDebugWidgets = {}
end

local function createLureDebugWidget(position, widgetType, text, inRange, isFollowing, isAhead)
    local tile = g_map.getTile(position)
    if not tile then return end

    local tileSize = 64
    local widget = g_ui.createWidget('UIWidget')
    widget:setSize({ width = tileSize, height = tileSize })
    widget:setPhantom(true)
    widget:setFocusable(false)
    widget:setTextAlign(AlignCenter)

    if widget.setFont then
        widget:setFont('verdana-11px-monochrome')
    end

    if widgetType == "range" then
        -- Lure range boundary - just a thin blue line (border only, no background)
        widget:setBackgroundColor('#00000000')
        widget:setBorderWidth(1)
        widget:setBorderColor('#0066FF')
    elseif widgetType == "monster_wait" then
        -- Outside lure zone, not on path → cavebot will wait. Red.
        widget:setBorderWidth(2)
        widget:setBackgroundColor('#FF000060')
        widget:setBorderColor('#FF0000')
        widget:setText('WAIT')
        widget:setColor('#FF0000')
    elseif widgetType == "monster_ignore" then
        -- Creature on the ignored list → never gates. Gray.
        widget:setBorderWidth(2)
        widget:setBackgroundColor('#80808050')
        widget:setBorderColor('#A0A0A0')
        widget:setText('IGNORE')
        widget:setColor('#D0D0D0')
    elseif widgetType == "monster_onpath" then
        -- Outside lure zone but near a future waypoint → cavebot will naturally
        -- engage as it progresses. Green.
        widget:setBorderWidth(2)
        widget:setBackgroundColor('#00A00060')
        widget:setBorderColor('#00C800')
        widget:setText('ON PATH')
        widget:setColor('#66FF66')
    elseif widgetType == "monster_out" then
        -- Back-compat alias for anyone still calling the old label.
        widget:setBorderWidth(2)
        widget:setBackgroundColor('#FF000060')
        widget:setBorderColor('#FF0000')
        widget:setText('WAIT')
        widget:setColor('#FF0000')
    end

    tile:attachWidget(widget)
    table.insert(lureDebugWidgets, widget)
end

local function updateLureDebugVisual()
    clearLureDebugWidgets()

    -- Check if lure debug is enabled
    local recorder = nil
    if _G and _G.hunting_recorderModule then
        recorder = _G.hunting_recorderModule
    elseif modules.game_helper and modules.game_helper.hunting_recorderModule then
        recorder = modules.game_helper.hunting_recorderModule
    end

    if not recorder or not recorder.getCurrentCavebotData then
        return
    end

    local cavebotData = recorder.getCurrentCavebotData()
    if not cavebotData or not cavebotData.config or not cavebotData.config.lureDebug then
        return
    end

    local player = g_game.getLocalPlayer()
    if not player then return end

    local pos = player:getPosition()
    if not pos then return end

    -- Get lure range config
    local rangeX = math.min(6, cavebotData.config.lureCheckRangeX or 6)
    local rangeY = math.min(4, cavebotData.config.lureCheckRangeY or 4)

    -- Player position not shown in debug mode

    -- Draw lure range boundary as a single rectangle
    local tile = g_map.getTile(pos)
    if tile then
        local tileSize = 64
        local totalWidth = (rangeX * 2 + 1) * tileSize
        local totalHeight = (rangeY * 2 + 1) * tileSize

        local widget = g_ui.createWidget('UIWidget')
        widget:setSize({ width = totalWidth, height = totalHeight })
        widget:setMarginLeft(-rangeX * tileSize)
        widget:setMarginTop(-rangeY * tileSize)
        widget:setPhantom(true)
        widget:setFocusable(false)
        widget:setBackgroundColor('#00000000')
        widget:setBorderWidth(2)
        widget:setBorderColor('#0066FF')

        tile:attachWidget(widget)
        table.insert(lureDebugWidgets, widget)
    end

    -- Draw monsters with their status
    -- OPTIMIZATION: Use CreatureCache instead of getSpectators
    local cachedMonsters = CreatureCache.getMonsters()
    if cachedMonsters then
        -- (was: a getDebugInfo() call whose result was discarded — it built the
        -- full ~30-field debug table every lure-debug refresh for nothing.
        -- Removed; nextDirection was never consumed.)

        -- OPTIMIZATION: Build ignored hashmap for O(1) lookup
        local ignoredCreatures = cavebotData.config.ignoredCreatures or {}
        local ignoredMap = {}
        for _, ignored in ipairs(ignoredCreatures) do
            ignoredMap[ignored:lower()] = true
        end

        -- Future waypoint corridor: used only to distinguish ON PATH from
        -- WAIT/other-labels when the cavebot wouldn't wait for this mob.
        local futureWaypoints = {}
        local waypointRadius = 4
        local lureExt = CaveBot and CaveBot.Extensions and CaveBot.Extensions.lure
        if lureExt and lureExt.getNextFutureWaypoints then
            local lookAhead = cavebotData.config.lureWaypointLookAhead or 10
            futureWaypoints = lureExt.getNextFutureWaypoints(lookAhead) or {}
            waypointRadius = cavebotData.config.lureWaypointRadius or 4
        end
        local isOnPath = function(cPos)
            if #futureWaypoints == 0 or not lureExt or not lureExt.isCreatureInWaypointDirection then
                return false
            end
            return lureExt.isCreatureInWaypointDirection(pos, cPos, futureWaypoints, waypointRadius)
        end

        -- WAIT label must be 1:1 with `shouldWaitLure`'s per-creature decision
        -- so the HUD never claims the bot will wait when it actually won't.
        local wouldWait = function(cPos)
            if not lureExt or not lureExt.wouldWaitFor then return false end
            return lureExt.wouldWaitFor(pos, cPos)
        end

        -- Viewport cap: don't draw widgets for mobs off-screen (user can't see
        -- them and doesn't want the bot considering them either).
        local viewportX, viewportY = 7, 5
        if ScreenGrid and ScreenGrid.getConfig then
            local cfg = ScreenGrid.getConfig()
            viewportX, viewportY = cfg.rangeX or viewportX, cfg.rangeY or viewportY
        end

        for _, entry in ipairs(cachedMonsters) do
            local creature = entry.creature
            local cPos = entry.position
            if cPos and cPos.z == pos.z then
                local dx = math.abs(cPos.x - pos.x)
                local dy = math.abs(cPos.y - pos.y)
                local onScreen = dx <= viewportX and dy <= viewportY
                if onScreen then
                    local creatureName = creature:getName():lower()
                    local isIgnored = ignoredMap[creatureName] or false

                    if isIgnored then
                        createLureDebugWidget(cPos, "monster_ignore", "", false, false, false)
                    else
                        local inRange = dx <= rangeX and dy <= rangeY
                        if not inRange then
                            if wouldWait(cPos) then
                                createLureDebugWidget(cPos, "monster_wait", "", false, false, false)
                            elseif isOnPath(cPos) then
                                createLureDebugWidget(cPos, "monster_onpath", "", false, false, false)
                            end
                        end
                        -- Inside the lure zone: no widget — bot fights it.
                    end
                end
            end
        end
    end
end

local function startLureDebugVisual()
    if lureDebugUpdateEvent then
        removeEvent(lureDebugUpdateEvent)
    end

    local function update()
        updateLureDebugVisual()
        lureDebugUpdateEvent = scheduleEvent(update, 200)
    end

    update()
end

local function stopLureDebugVisual()
    if lureDebugUpdateEvent then
        removeEvent(lureDebugUpdateEvent)
        lureDebugUpdateEvent = nil
    end
    clearLureDebugWidgets()
end

-- Export functions
_G.startLureDebugVisual = startLureDebugVisual
_G.stopLureDebugVisual = stopLureDebugVisual
_G.updateLureDebugVisual = updateLureDebugVisual

-- Protection Zone Auto-Disable System
