local ENERGY_RING_UNEQUIPPED_ID = 3051
local ENERGY_RING_EQUIPPED_ID = 3088

local autoTargetModes = {
    ["A"] = 1,  -- Closest
    ["B"] = 2,  -- Farthest
    ["C"] = 3,  -- Lowest Health
    ["D"] = 4,  -- Highest Health
    ["E"] = 5,  -- Best AoE (most monsters hit)
    ["F"] = 6,  -- Closest Lowest Health
    ["G"] = 7,  -- Closest Highest Health
    ["H"] = 8,  -- Farthest Lowest Health
