-- Cache for spell area data from player_spells.json.
-- Exposed (module-global) so the character list can pre-warm the parse
-- during char selection, eliminating the JSON read cost from helper.online().
function loadSpellAreas()
    if spellAreasLoaded then
        return spellAreaCache
    end

    local ok, jsonData = pcall(g_resources.readFileContents, '/modules/gamelib/player_spells.json')
    if not ok then return {} end
    if not jsonData or jsonData == '' then
        return {}
    end

    local success, spellList = pcall(json.decode, jsonData)
    if not success or not spellList then
        return {}
    end

    -- Build cache: spellId -> area data
    for _, spellData in ipairs(spellList) do
        if spellData.id then
            if spellData.area then
                spellAreaCache[spellData.id] = spellData.area
            end
            if type(spellData.range) == "number" and spellData.range > 0 then
                spellRangeCache[spellData.id] = spellData.range
            end
        end
    end

    spellAreasLoaded = true
    return spellAreaCache
end

-- Reply handler for extended opcode 206: the server sends the player's REAL vocation
-- id (vocations.xml), which the login protocol can't carry (it collapses Elite Knight
-- and Titan Knight to the same client-id 11). Mirror the server's vocation-sized
-- exori gran (Fierce Berserk) in the local spell DB so any SpellInfo.area consumer
-- agrees with the shooter override in getSpellAreaType: Titan (id 14) -> 5x5
-- AREA_SQUARE2X2, base/elite -> 3x3 AREA_CIRCLE1X1.
function onHelperRealVocation(protocol, opcode, buffer)
    helperRealVocationId = tonumber(buffer)

    local fierce = SpellInfo and SpellInfo.Default and SpellInfo.Default["Fierce Berserk"]
    if fierce then
        if helperRealVocationId == TITAN_KNIGHT_VOCATION_ID then
            fierce.area = SpellAreas.AREA_SQUARE2X2
        else
            fierce.area = SpellAreas.AREA_CIRCLE1X1
        end
    end
end

-- Ask the server (extended opcode 206) for the real vocation id. Called shortly
-- after login; the reply lands in onHelperRealVocation.
function requestRealVocation()
    local proto = g_game.getProtocolGame and g_game.getProtocolGame()
    if not proto then return end
    pcall(function() proto:sendExtendedOpcode(REAL_VOCATION_OPCODE, "") end)
end

-- Safe wrapper for setInputLockWidget function
local function safeSetInputLockWidget(widget)
    if g_client and g_client.setInputLockWidget then
        g_client.setInputLockWidget(widget)
    end
end

-- ============================================================================
-- MODAL MANAGER
-- Centralizes popup open/close to ensure helperWindow hides while any popup
-- is open and restores correctly, including nested popup flows.
-- ============================================================================
local modalStack = {}

local function modalEnter(window, opts)
    if not window then return end
    opts = opts or {}

    local entry = {
        window = window,
        helperWasVisible = false,
        parentWindow = nil,
        inputLock = opts.inputLock ~= false -- default true
    }

    -- If there is a previous modal on the stack, record it as parent
    if #modalStack > 0 then
        local top = modalStack[#modalStack]
        entry.parentWindow = top.window
        -- Hide the parent popup so only the new one is visible
        if top.window and not top.window:isDestroyed() then
            top.window:hide()
        end
    else
        -- First modal: check if helper is visible, hide it
        if helper and not helper:isDestroyed() and helper:isVisible() then
            entry.helperWasVisible = true
            helper:hide()
        end
    end

    table.insert(modalStack, entry)

    -- Apply input lock
    if entry.inputLock then
        safeSetInputLockWidget(window)
    end

    -- Register onDestroy as safety net to always clean up.
    -- onDestroy may be a single function OR a table of slots (when handlers
    -- were attached via connect()), so route it through signalcall.
    local originalOnDestroy = window.onDestroy
    window.onDestroy = function(self)
        if originalOnDestroy then
            signalcall(originalOnDestroy, self or window)
        end
        if modalExit then
            modalExit(window)
        end
    end
end

function modalExit(window)
    if not window then return end

    -- Find and remove this window from the stack
    local removedEntry = nil
    local removedIndex = nil
    for i = #modalStack, 1, -1 do
        if modalStack[i].window == window then
            removedEntry = modalStack[i]
            removedIndex = i
            table.remove(modalStack, i)
            break
        end
    end

    if not removedEntry then return end

    -- Clear input lock
    safeSetInputLockWidget(nil)

    -- If there are still modals on the stack, show the top one (parent)
    if #modalStack > 0 then
        local top = modalStack[#modalStack]
        if top.window and not top.window:isDestroyed() then
            top.window:show()
            top.window:raise()
            top.window:focus()
            if top.inputLock then
                safeSetInputLockWidget(top.window)
            end
        end
    else
        -- Stack is empty: restore helper if it was visible before the first modal
        if removedEntry.helperWasVisible then
            if helper and not helper:isDestroyed() then
                helper:show()
            end
        end
    end
end

-- Expose for hunting_recorder and other scripts in the module
_G.helperModalEnter = modalEnter
_G.helperModalExit = modalExit

local function deepCopy(original)
    if type(original) ~= "table" then
        return original
    end
    local copy = {}
    for k, v in pairs(original) do
        if type(v) == "table" then
            copy[k] = deepCopy(v)
        else
            copy[k] = v
        end
    end
    return copy
end

local function ensureHealingSlots(config)
    if type(config) ~= "table" then
        return
    end

    if type(config.spells) ~= "table" then
        config.spells = {}
    end
    for i = #config.spells + 1, 4 do
        config.spells[i] = { id = 0, percent = 80, priority = 1, orderPriority = i }
    end
    for i = 1, 4 do
        if type(config.spells[i]) ~= "table" then
            config.spells[i] = { id = 0, percent = 80, priority = 1, orderPriority = i }
        else
            if config.spells[i].id == nil then
                config.spells[i].id = 0
            end
            if config.spells[i].percent == nil then
                config.spells[i].percent = 80
            end
            if config.spells[i].priority == nil then
                config.spells[i].priority = 1
            end
            if config.spells[i].orderPriority == nil then
                config.spells[i].orderPriority = i
            end
        end
    end

    if type(config.potions) ~= "table" then
        config.potions = {}
    end
    for i = #config.potions + 1, 4 do
        local defaultPriority = (i <= 2) and 1 or 2
        config.potions[i] = { id = 0, percent = 50, priority = defaultPriority, orderPriority = i }
    end
    for i = 1, 4 do
        if type(config.potions[i]) ~= "table" then
            local defaultPriority = (i <= 2) and 1 or 2
            config.potions[i] = { id = 0, percent = 50, priority = defaultPriority, orderPriority = i }
        else
            if config.potions[i].id == nil then
                config.potions[i].id = 0
            end
            if config.potions[i].percent == nil then
                config.potions[i].percent = 50
            end
            if config.potions[i].priority == nil then
                local defaultPriority = (i <= 2) and 1 or 2
                config.potions[i].priority = defaultPriority
            end
            if config.potions[i].orderPriority == nil then
                config.potions[i].orderPriority = i
            end
        end
    end
end

HEALING_DEFAULT_RULE_COUNT = 0
HEALING_ROW_DOUBLE_CLICK_MS = 500
ROW_MOUSE_RELEASE_GUARD_MS = 45

function shouldIgnoreDuplicatedRowMouseRelease(row, mouseButton, nowMs)
    if not row then
        return false
    end

    local now = tonumber(nowMs) or g_clock.millis()
    local lastMs = tonumber(row._lastMouseReleaseHandledMs) or 0
    local lastButton = row._lastMouseReleaseHandledButton
    if lastMs > 0 and (now - lastMs) >= 0 and (now - lastMs) <= ROW_MOUSE_RELEASE_GUARD_MS and lastButton == mouseButton then
        return true
    end

    row._lastMouseReleaseHandledMs = now
    row._lastMouseReleaseHandledButton = mouseButton
    return false
end

function trimHealingText(text)
    local result = tostring(text or "")
    result = result:gsub("%s+", " ")
    result = result:gsub("^%s+", "")
    result = result:gsub("%s+$", "")
    return result
end

function createDefaultHealingRule(slotIndex)
    return {
        enabled = true,
        actionType = "Spell",
        spellWords = "",
        spellParameter = "",
        itemId = 0,
        itemCount = 0,
        whenMetric1 = "HP%",
        whenOperator1 = "<=",
        whenValue1 = 80,
        joinMode = "none",
        whenMetric2 = "HP%",
        whenOperator2 = "<=",
        whenValue2 = 100,
        manaMin = 0,
        conditionDrunk = false,
        conditionRooted = false,
        conditionFeared = false,
        dontCastIfTargetingMonster = false,
        dontUseIfTarget = false,
        orderPriority = tonumber(slotIndex) or 1
    }
end

function normalizeHealingMetric(metric)
    local value = tostring(metric or "")
    if value == "MP%" then
        return "MP%"
    end
    return "HP%"
end

function normalizeHealingOperator(operatorText)
    local value = tostring(operatorText or "")
    if value == "<" or value == "<=" or value == ">" or value == ">=" or value == "==" then
        return value
    end
    if value == "=" then
        return "=="
    end
    return "<="
end

function normalizeHealingJoinMode(joinMode)
    local value = tostring(joinMode or ""):lower()
    if value == "and" or value == "or" or value == "none" then
        return value
    end
    return "none"
end

function normalizeHealingActionType(actionType)
    local value = tostring(actionType or "")
    if value == "Item" then
        return "Item"
    end
    return "Spell"
end

function isHpOnlyHealingRuleItem(itemId)
    return (tonumber(itemId) or 0) == 3160
end

function ensureHealingRule(rule, slotIndex)
    if type(rule) ~= "table" then
        return createDefaultHealingRule(slotIndex)
    end

    local defaults = createDefaultHealingRule(slotIndex)
    for key, value in pairs(defaults) do
        if rule[key] == nil then
            rule[key] = value
        end
    end

    rule.enabled = coerceConfigBool(rule.enabled, defaults.enabled)
    rule.actionType = normalizeHealingActionType(rule.actionType)
    rule.spellWords = trimHealingText(rule.spellWords or "")
    rule.spellParameter = trimHealingText(rule.spellParameter or "")
    rule.itemId = tonumber(rule.itemId) or 0
    rule.itemCount = tonumber(rule.itemCount) or 0
    if rule.itemCount < 0 then
        rule.itemCount = 0
    end

    rule.whenMetric1 = normalizeHealingMetric(rule.whenMetric1)
    rule.whenOperator1 = normalizeHealingOperator(rule.whenOperator1)
    rule.whenValue1 = tonumber(rule.whenValue1) or defaults.whenValue1

    rule.joinMode = normalizeHealingJoinMode(rule.joinMode)
    rule.whenMetric2 = normalizeHealingMetric(rule.whenMetric2)
    rule.whenOperator2 = normalizeHealingOperator(rule.whenOperator2)
    rule.whenValue2 = tonumber(rule.whenValue2) or defaults.whenValue2

    rule.manaMin = tonumber(rule.manaMin) or 0
    if rule.manaMin < 0 then
        rule.manaMin = 0
    end

    rule.conditionDrunk = rule.conditionDrunk == true
    rule.conditionRooted = rule.conditionRooted == true
    rule.conditionFeared = rule.conditionFeared == true
    rule.dontCastIfTargetingMonster = rule.dontCastIfTargetingMonster == true
    rule.dontUseIfTarget = rule.dontUseIfTarget == true
    rule.orderPriority = tonumber(rule.orderPriority) or (tonumber(slotIndex) or 1)

    return rule
end

function migrateLegacyHealingRulesFromFixedSlots()
    if type(helperConfig) ~= "table" then
        return
    end

    local migrated = {}

    local legacySpells = helperConfig.spells or {}
    for index, spellConfig in ipairs(legacySpells) do
        local spellId = tonumber(spellConfig and spellConfig.id) or 0
        if spellId > 0 then
            local words = ""
            local spellData = Spells.getSpellByClientId(spellId)
            if spellData and spellData.words then
                words = tostring(spellData.words)
            end
            local metric = (tonumber(spellConfig.priority) == 2) and "MP%" or "HP%"
            table.insert(migrated, ensureHealingRule({
                enabled = true,
                actionType = "Spell",
                spellWords = words,
                itemId = 0,
                whenMetric1 = metric,
                whenOperator1 = "<=",
                whenValue1 = tonumber(spellConfig.percent) or 80,
                joinMode = "none",
                whenMetric2 = metric,
                whenOperator2 = "<=",
                whenValue2 = 100,
                manaMin = 0,
                orderPriority = tonumber(spellConfig.orderPriority) or index
            }, #migrated + 1))
        end
    end

    local legacyPotions = helperConfig.potions or {}
    for index, potionConfig in ipairs(legacyPotions) do
        local potionId = tonumber(potionConfig and potionConfig.id) or 0
        if potionId > 0 then
            local metric = (tonumber(potionConfig.priority) == 2) and "MP%" or "HP%"
            table.insert(migrated, ensureHealingRule({
                enabled = true,
                actionType = "Item",
                spellWords = "",
                itemId = potionId,
                whenMetric1 = metric,
                whenOperator1 = "<=",
                whenValue1 = tonumber(potionConfig.percent) or 50,
                joinMode = "none",
                whenMetric2 = metric,
                whenOperator2 = "<=",
                whenValue2 = 100,
                manaMin = 0,
                orderPriority = tonumber(potionConfig.orderPriority) or index
            }, #migrated + 1))
        end
    end

    if #migrated > 0 then
        table.sort(migrated, function(a, b)
            local aOrder = tonumber(a.orderPriority) or 999
            local bOrder = tonumber(b.orderPriority) or 999
            if aOrder == bOrder then
                return (tonumber(a.whenValue1) or 100) < (tonumber(b.whenValue1) or 100)
            end
            return aOrder < bOrder
        end)
        helperConfig.healingRules = migrated
    else
        helperConfig.healingRules = {}
    end
end

function ensureHealingRulesConfig(minEntriesWhenMissing)
    if type(helperConfig) ~= "table" then
        return
    end

    local rules = helperConfig.healingRules
    local wasMissing = type(rules) ~= "table"
    if wasMissing then
        rules = {}
    end

    for i = 1, #rules do
        rules[i] = ensureHealingRule(rules[i], i)
    end

    helperConfig.healingRules = rules

    if #rules == 0 and wasMissing then
        migrateLegacyHealingRulesFromFixedSlots()
        rules = helperConfig.healingRules or {}
    end

    if #rules == 0 and minEntriesWhenMissing and minEntriesWhenMissing > 0 then
        for i = 1, minEntriesWhenMissing do
            table.insert(rules, ensureHealingRule(createDefaultHealingRule(i), i))
        end
        helperConfig.healingRules = rules
    end
end

function isHealingRuleComplete(ruleConfig)
    if type(ruleConfig) ~= "table" then
        return false
    end
    local rule = ensureHealingRule(ruleConfig, 1)
    if rule.actionType == "Item" then
        return (tonumber(rule.itemId) or 0) > 0
    end
    return trimHealingText(rule.spellWords) ~= ""
end

function getHealingRuleMetricCurrentValue(metric, healthPercent, manaPercent)
    if normalizeHealingMetric(metric) == "MP%" then
        return tonumber(manaPercent) or 0
    end
    return tonumber(healthPercent) or 0
end

function evaluateHealingRuleComparator(leftValue, operatorText, rightValue)
    local left = tonumber(leftValue) or 0
    local right = tonumber(rightValue) or 0
    local op = normalizeHealingOperator(operatorText)
    if op == "<" then
        return left < right
    elseif op == "<=" then
        return left <= right
    elseif op == ">" then
        return left > right
    elseif op == ">=" then
        return left >= right
    elseif op == "==" then
        return left == right
    end
    return left <= right
end

function isHealingRuleStatusConditionAllowed(rule, player)
    if not player then
        return false
    end

    local states = player:getStates() or 0
    if rule.conditionDrunk and bit.band(states, PlayerStates.Drunk) == 0 then
        return false
    end
    if rule.conditionRooted and bit.band(states, PlayerStates.Rooted) == 0 then
        return false
    end
    if rule.conditionFeared and bit.band(states, PlayerStates.Feared) == 0 then
        return false
    end
    return true
end

function evaluateHealingRuleTrigger(ruleConfig, healthPercent, manaPercent, currentMana, player)
    local rule = ensureHealingRule(ruleConfig, 1)
    if not rule.enabled then
        return false
    end
    if not isHealingRuleComplete(rule) then
        return false
    end
    if (tonumber(currentMana) or 0) < (tonumber(rule.manaMin) or 0) then
        return false
    end
    if rule.dontCastIfTargetingMonster then
        local target = g_game.getAttackingCreature()
        if target and target.isMonster and target:isMonster() then
            return false
        end
    end
    if rule.dontUseIfTarget and rule.actionType == "Item" then
        local target = g_game.getAttackingCreature()
        if target then
            return false
        end
    end
    if not isHealingRuleStatusConditionAllowed(rule, player) then
        return false
    end

    local metric1 = rule.whenMetric1
    local metric2 = rule.whenMetric2
    if rule.actionType == "Item" and isHpOnlyHealingRuleItem(rule.itemId) then
        metric1 = "HP%"
        metric2 = "HP%"
    end

    local firstValue = getHealingRuleMetricCurrentValue(metric1, healthPercent, manaPercent)
    local firstCheck = evaluateHealingRuleComparator(firstValue, rule.whenOperator1, rule.whenValue1)
    local joinMode = normalizeHealingJoinMode(rule.joinMode)
    if joinMode == "none" then
        return firstCheck
    end

    local secondValue = getHealingRuleMetricCurrentValue(metric2, healthPercent, manaPercent)
    local secondCheck = evaluateHealingRuleComparator(secondValue, rule.whenOperator2, rule.whenValue2)
    if joinMode == "and" then
        return firstCheck and secondCheck
    end
    return firstCheck or secondCheck
end

function castHealingRuleItem(itemId)
    local parsedItemId = tonumber(itemId) or 0
    if parsedItemId <= 0 then
        return false
    end
    local isHpOnlyItem = isHpOnlyHealingRuleItem(parsedItemId)
    local itemCount = getItemCountAnywhere(parsedItemId)
    if itemCount <= 0 then
        itemCount = hasItemInBackpack(parsedItemId)
    end
    if itemCount <= 0 and not isHpOnlyItem then
        return false
    end

    if isHpOnlyItem then
        local player = g_game.getLocalPlayer()
        if not player then
            return false
        end

        local cooldownKey = "healingRuleItem:" .. tostring(parsedItemId)
        local cooldown = getSpellCooldown(cooldownKey)
        if cooldown > g_clock.millis() then
            return false
        end

        -- Predictive multi-use gate only once a real 0xA6 proved the server
        -- sends it (see usePotion); legacy floor otherwise.
        if CastTiming.isActive() and CastTiming.hasMultiUseEcho() then
            if CastTiming.isMultiUseBlocked() then
                return false
            end
        elseif multiUseExDelay > g_clock.millis() then
            return false
        end

        if helperEvents and helperEvents.shooterPotionHoldForRunePeek then
            return false
        end

        -- UH uses explicit "use on yourself".
        helperConfig.magicShooterOnHold = true
        local success = false

        if g_game.getClientVersion and g_game.getClientVersion() < 780 then
            local okUse, useResult = pcall(function()
                return g_game.useInventoryItemWith(parsedItemId, player)
            end)
            success = okUse and useResult ~= false
        end

        if not success then
            local okUse, useResult = pcall(function()
                return g_game.useInventoryItemWith(parsedItemId, player)
            end)
            success = okUse and useResult ~= false
        end

        if not success then
            local okUse, useResult = pcall(function()
                return g_game.useInventoryItemWith(parsedItemId, player, -1)
            end)
            success = okUse and useResult ~= false
        end

        if not success then
            local okUse, useResult = pcall(function()
                return g_game.useInventoryItemWith(parsedItemId, player, 0)
            end)
            success = okUse and useResult ~= false
        end

        if not success then
            local okUse, useResult = pcall(function()
                return g_game.useInventoryItemWith(parsedItemId, player, 1)
            end)
            success = okUse and useResult ~= false
        end

        if not success then
            local okUse, useResult = pcall(function()
                return g_game.useInventoryItem(parsedItemId)
            end)
            success = okUse and useResult ~= false
        end

        -- (fallback findPlayerItem+useWith removido — não funciona com bp fechada;
        -- as tentativas useInventoryItemWith acima já cobrem todos os casos)

        if success then
            CastTiming.notePotionUsed()
            spellsCooldown[cooldownKey] = g_clock.millis() + getEngineIntervalValue("healing")
            multiUseExDelay = g_clock.millis() + getEngineIntervalValue("healing")
        end
        helperConfig.magicShooterOnHold = false
        return success
    end

    return usePotion(parsedItemId)
end

function castHealingRuleSpell(spellWords, spellParameter)
    local words = trimHealingText(spellWords)
    if words == "" then
        return false
    end

    local parameter = trimHealingText(spellParameter or "")

    local spell = getCachedSpell(words)
    if spell and spell.id and spell.id > 0 then
        return castHealingSpell(spell.id, parameter)
    end

    if not g_game.isOnline() then
        return false
    end
    if parameter ~= "" then
        g_game.talk(string.format('%s "%s"', words, parameter), true)
    else
        g_game.talk(words, true)
    end
    return true
end

function processHealingRules(healthPercent, manaPercent, currentMana, player)
    ensureHealingRulesConfig()
    local rules = helperConfig and helperConfig.healingRules or {}
    if type(rules) ~= "table" then
        return false, false
    end
    if #rules == 0 then
        -- Rules table exists (new system), so do not fallback to hidden legacy slots.
        return false, true
    end

    local usedAnyRule = false
    for i = 1, #rules do
        local rule = ensureHealingRule(rules[i], i)
        rules[i] = rule
        if rule.enabled then
            local shouldRunRule = evaluateHealingRuleTrigger(rule, healthPercent, manaPercent, currentMana, player)
            if shouldRunRule then
                local success = false
                if rule.actionType == "Item" then
                    success = castHealingRuleItem(rule.itemId)
                else
                    success = castHealingRuleSpell(rule.spellWords, rule.spellParameter)
                end

                if success then
                    usedAnyRule = true
                end
            end
        end
    end

    return usedAnyRule, true
end

EQUIPMENT_SWAP_DEFAULT_SLOT_COUNT = 0
TIMER_DEFAULT_RULE_COUNT = 0
EQUIPMENT_ROW_DOUBLE_CLICK_MS = 500
TIMER_ROW_DOUBLE_CLICK_MS = 500
TIMER_MAX_INTERVAL_SECONDS = 86400

function createDefaultEquipmentSwapRule(itemType, slotIndex)
    local defaultPercent = 40
    local defaultMode = "below"
    if slotIndex == 1 then
        defaultPercent = 80
        defaultMode = "above"
    end

    return {
        id = 0,
        percent = defaultPercent,
        enabled = false,
        priority = 1,
        mode = defaultMode,
        alwaysEquipIfNone = false,
        equipIfHPBelowEnabled = false,
        equipIfHPBelow = 0,
        equipIfHPAboveEnabled = false,
        equipIfHPAbove = 0,
        equipIfMPBelowEnabled = false,
        equipIfMPBelow = 0,
        equipIfMPAboveEnabled = false,
        equipIfMPAbove = 0,
        slot1Metric = "HP%",
        slot1Operator = "<=",
        slot1Value = 80,
        slot2Metric = "HP%",
        slot2Operator = "<=",
        slot2Value = 0,
        conditionJoinMode = "none",
        conditionUseAnd = false,
        sourceType = "Hotkey",
        actionType = "Equip",
        dontExecuteIfEquipped = false,
        dontExecuteItemId = 0,
        dontExecuteItemIds = { 0, 0 },
        tier = 0,
        conditionDrunk = false,
        conditionRooted = false,
        conditionFeared = false,
        conditionParalyzed = false,
        conditionPz = true,
        conditionNonPz = true,
        conditionDrowning = false,
        conditionUtamoVita = false,
        excludeAmuletIds = { 0, 0 },
        excludeRingIds = { 0, 0 },
        respectEnergyRing = false
    }
end

function coerceConfigBool(value, defaultValue)
    if value == nil then
        return defaultValue == true
    end
    if value == true then
        return true
    end
    if value == false then
        return false
    end

    local valueType = type(value)
    if valueType == "number" then
        return value ~= 0
    end
    if valueType == "string" then
        local lowered = string.lower(value)
        if lowered == "true" or lowered == "1" or lowered == "yes" or lowered == "on" then
            return true
        end
        if lowered == "false" or lowered == "0" or lowered == "no" or lowered == "off" or lowered == "" then
            return false
        end
    end

    return defaultValue == true
end

function ensureEquipmentSwapRule(rule, itemType, slotIndex)
    if type(rule) ~= "table" then
        return createDefaultEquipmentSwapRule(itemType, slotIndex)
    end

    local hasPositional = rule.slot1Metric ~= nil or rule.slot1Operator ~= nil or rule.slot1Value ~= nil
        or rule.slot2Metric ~= nil or rule.slot2Operator ~= nil or rule.slot2Value ~= nil

    local defaults = createDefaultEquipmentSwapRule(itemType, slotIndex)
    for key, value in pairs(defaults) do
        if rule[key] == nil then
            if type(value) == "table" then
                rule[key] = deepCopy(value)
            else
                rule[key] = value
            end
        end
    end

    if type(rule.excludeAmuletIds) ~= "table" then
        rule.excludeAmuletIds = { 0, 0 }
    end
    if type(rule.excludeRingIds) ~= "table" then
        rule.excludeRingIds = { 0, 0 }
    end
    if type(rule.dontExecuteItemIds) ~= "table" then
        rule.dontExecuteItemIds = { tonumber(rule.dontExecuteItemId) or 0, 0 }
    end

    rule.id = tonumber(rule.id) or 0
    -- Dynamic items (rings/amulets with separate equipped/unequipped forms):
    -- normalize the stored id to the unequipped/bag form, since that's the id a
    -- carried copy actually has. Count/equip/display then all use the right id,
    -- and the worn form is still recognized via isDynamicMatch. Auto-migrates
    -- rules that were saved with the equipped-form id. (Same pairing table the
    -- action bar uses: gamelib/dynamic_items.lua.)
    if rule.id > 0 and getUnequippedItemId then
        rule.id = getUnequippedItemId(rule.id) or rule.id
    end
    rule.enabled = coerceConfigBool(rule.enabled, defaults.enabled)
    rule.percent = tonumber(rule.percent) or defaults.percent
    rule.priority = tonumber(rule.priority) or defaults.priority

    rule.alwaysEquipIfNone = rule.alwaysEquipIfNone == true
    rule.equipIfHPBelowEnabled = rule.equipIfHPBelowEnabled == true
    rule.equipIfHPAboveEnabled = rule.equipIfHPAboveEnabled == true
    rule.equipIfMPBelowEnabled = rule.equipIfMPBelowEnabled == true
    rule.equipIfMPAboveEnabled = rule.equipIfMPAboveEnabled == true

    rule.equipIfHPBelow = tonumber(rule.equipIfHPBelow) or 0
    rule.equipIfHPAbove = tonumber(rule.equipIfHPAbove) or 0
    rule.equipIfMPBelow = tonumber(rule.equipIfMPBelow) or 0
    rule.equipIfMPAbove = tonumber(rule.equipIfMPAbove) or 0

    local enabledConditionsCount = 0
    if rule.equipIfHPBelowEnabled then enabledConditionsCount = enabledConditionsCount + 1 end
    if rule.equipIfHPAboveEnabled then enabledConditionsCount = enabledConditionsCount + 1 end
    if rule.equipIfMPBelowEnabled then enabledConditionsCount = enabledConditionsCount + 1 end
    if rule.equipIfMPAboveEnabled then enabledConditionsCount = enabledConditionsCount + 1 end

    local joinModeRaw = tostring(rule.conditionJoinMode or ""):lower()
    if joinModeRaw ~= "none" and joinModeRaw ~= "and" and joinModeRaw ~= "or" then
        if enabledConditionsCount > 1 then
            joinModeRaw = (rule.conditionUseAnd == true) and "and" or "or"
        else
            joinModeRaw = "none"
        end
    end
    rule.conditionJoinMode = joinModeRaw
    rule.conditionUseAnd = joinModeRaw == "and"

    if not hasPositional then
        local legacy = {}
        if rule.equipIfHPBelowEnabled then table.insert(legacy,
                { metric = "HP%", operator = "<=", value = rule.equipIfHPBelow }) end
        if rule.equipIfHPAboveEnabled then table.insert(legacy,
                { metric = "HP%", operator = ">=", value = rule.equipIfHPAbove }) end
        if rule.equipIfMPBelowEnabled then table.insert(legacy,
                { metric = "MP%", operator = "<=", value = rule.equipIfMPBelow }) end
        if rule.equipIfMPAboveEnabled then table.insert(legacy,
                { metric = "MP%", operator = ">=", value = rule.equipIfMPAbove }) end
        if legacy[1] then
            rule.slot1Metric = legacy[1].metric
            rule.slot1Operator = legacy[1].operator
            rule.slot1Value = legacy[1].value
        end
        if legacy[2] then
            rule.slot2Metric = legacy[2].metric
            rule.slot2Operator = legacy[2].operator
            rule.slot2Value = legacy[2].value
        end
    end

    rule.slot1Metric = (rule.slot1Metric == "MP%") and "MP%" or "HP%"
    rule.slot1Operator = (rule.slot1Operator == ">=") and ">=" or "<="
    rule.slot1Value = tonumber(rule.slot1Value) or 0
    rule.slot2Metric = (rule.slot2Metric == "MP%") and "MP%" or "HP%"
    rule.slot2Operator = (rule.slot2Operator == ">=") and ">=" or "<="
    rule.slot2Value = tonumber(rule.slot2Value) or 0
    rule.sourceType = (rule.sourceType == "Backpack") and "Backpack" or "Hotkey"
    rule.actionType = (rule.actionType == "Unequip") and "Unequip" or "Equip"
    rule.dontExecuteIfEquipped = rule.dontExecuteIfEquipped == true
    rule.dontExecuteItemId = tonumber(rule.dontExecuteItemId) or 0
    if rule.dontExecuteItemId < 0 then
        rule.dontExecuteItemId = 0
    end
    for i = 1, 2 do
        rule.dontExecuteItemIds[i] = tonumber(rule.dontExecuteItemIds[i]) or 0
        if rule.dontExecuteItemIds[i] < 0 then
            rule.dontExecuteItemIds[i] = 0
        end
    end
    if rule.dontExecuteItemIds[1] == 0 and rule.dontExecuteItemId > 0 then
        rule.dontExecuteItemIds[1] = rule.dontExecuteItemId
    end
    rule.dontExecuteItemId = rule.dontExecuteItemIds[1] or 0

    rule.tier = tonumber(rule.tier) or 0
    if rule.tier < 0 then
        rule.tier = 0
    end

    rule.conditionDrunk = rule.conditionDrunk == true
    rule.conditionRooted = rule.conditionRooted == true
    rule.conditionFeared = rule.conditionFeared == true
    rule.conditionParalyzed = rule.conditionParalyzed == true
    rule.conditionPz = rule.conditionPz == true
    rule.conditionNonPz = rule.conditionNonPz == true
    rule.conditionDrowning = rule.conditionDrowning == true
    rule.conditionUtamoVita = rule.conditionUtamoVita == true

    for i = 1, 2 do
        rule.excludeAmuletIds[i] = tonumber(rule.excludeAmuletIds[i]) or 0
        rule.excludeRingIds[i] = tonumber(rule.excludeRingIds[i]) or 0
    end

    return rule
end

function ensureEquipmentSwapConfig(minEntriesWhenMissing)
    if type(helperConfig) ~= "table" then
        return
    end

    local function isLegacyDefaultEquipmentRule(rule, slotIndex)
        if type(rule) ~= "table" then
            return false
        end

        local defaults = createDefaultEquipmentSwapRule("legacy", slotIndex)
        for key, defaultValue in pairs(defaults) do
            local value = rule[key]
            if type(defaultValue) == "table" then
                if type(value) ~= "table" then
                    return false
                end
                for i = 1, #defaultValue do
                    if tonumber(value[i]) ~= tonumber(defaultValue[i]) then
                        return false
                    end
                end
            else
                if value ~= defaultValue then
                    return false
                end
            end
        end

        return true
    end

    local function normalizeRules(itemType, configKey)
        local rules = helperConfig[configKey]
        local wasMissing = type(rules) ~= "table"

        if wasMissing then
            rules = {}
        end

        for i = 1, #rules do
            rules[i] = ensureEquipmentSwapRule(rules[i], itemType, i)
        end

        -- Migrate old fixed 2-slot schema that had only empty placeholders.
        if #rules == 2 and
            isLegacyDefaultEquipmentRule(rules[1], 1) and
            isLegacyDefaultEquipmentRule(rules[2], 2) then
            rules = {}
        end

        if wasMissing and minEntriesWhenMissing and minEntriesWhenMissing > 0 then
            for i = 1, minEntriesWhenMissing do
                rules[i] = createDefaultEquipmentSwapRule(itemType, i)
            end
        end

        helperConfig[configKey] = rules
    end

    normalizeRules("amulet", "amulets")
    normalizeRules("ring", "rings")
end

function createDefaultTimerRule(slotIndex)
    return {
        enabled = false,
        interval = 60,
        cooldownUnit = "Minutes",
        actionType = "Item",
        itemId = 0,
        itemCount = 0,
        chatText = "",
        runInPz = true,
        runOutPz = true,
        lastExecution = 0
    }
end

function normalizeTimerCooldownUnit(unitText)
    local text = tostring(unitText or "")
    if text == "Hours" then
        return "Hours"
    end
    if text == "Minutes" then
        return "Minutes"
    end
    if text == "Seconds" then
        return "Seconds"
    end
    return "Minutes"
end

function timerIntervalToUnitValue(intervalSeconds, preferredUnit)
    local seconds = tonumber(intervalSeconds) or 60
    if seconds < 1 then
        seconds = 1
    end

    local unit = normalizeTimerCooldownUnit(preferredUnit)
    if unit == "Hours" then
        if seconds % 3600 == 0 then
            return math.max(1, math.floor(seconds / 3600)), "Hours"
        end
        unit = "Minutes"
    end
    if unit == "Minutes" then
        if seconds % 60 == 0 then
            return math.max(1, math.floor(seconds / 60)), "Minutes"
        end
        unit = "Seconds"
    end

    return seconds, "Seconds"
end

function timerUnitValueToInterval(value, unit)
    local parsedValue = tonumber(value) or 0
    if parsedValue < 1 then
        parsedValue = 1
    end

    local normalizedUnit = normalizeTimerCooldownUnit(unit)
    local multiplier = 1
    if normalizedUnit == "Minutes" then
        multiplier = 60
    elseif normalizedUnit == "Hours" then
        multiplier = 3600
    end

    local total = parsedValue * multiplier
    if total < 1 then
        total = 1
    end
    if total > TIMER_MAX_INTERVAL_SECONDS then
        total = TIMER_MAX_INTERVAL_SECONDS
    end
    return total, normalizedUnit
end

function normalizeTimerActionType(actionType)
    if actionType == "Usar Item" then
        return "Item"
    end
    if actionType == "Enviar Chat" then
        return "Texto"
    end
    if actionType ~= "Item" and actionType ~= "Texto" then
        return "Item"
    end
    return actionType
end

function ensureTimerRule(rule, slotIndex)
    if type(rule) ~= "table" then
        return createDefaultTimerRule(slotIndex)
    end

    local defaults = createDefaultTimerRule(slotIndex)
    for key, value in pairs(defaults) do
        if rule[key] == nil then
            rule[key] = value
        end
    end

    rule.enabled = coerceConfigBool(rule.enabled, defaults.enabled)
    rule.interval = tonumber(rule.interval) or defaults.interval
    if rule.interval < 1 or rule.interval > TIMER_MAX_INTERVAL_SECONDS then
        rule.interval = defaults.interval
    end
    rule.cooldownUnit = normalizeTimerCooldownUnit(rule.cooldownUnit)
    rule.actionType = normalizeTimerActionType(rule.actionType)
    rule.itemId = tonumber(rule.itemId) or 0
    rule.itemCount = tonumber(rule.itemCount) or 0
    if rule.itemCount < 0 then
        rule.itemCount = 0
    end
    rule.chatText = tostring(rule.chatText or "")
    if rule.runInPz == nil then
        rule.runInPz = true
    else
        rule.runInPz = rule.runInPz == true
    end
    if rule.runOutPz == nil then
        rule.runOutPz = true
    else
        rule.runOutPz = rule.runOutPz == true
    end
    rule.lastExecution = tonumber(rule.lastExecution) or 0

    return rule
end

function ensureTimerConfig(minEntriesWhenMissing)
    if type(helperConfig) ~= "table" then
        return
    end

    local rules = helperConfig.timers
    local wasMissing = type(rules) ~= "table"
    if wasMissing then
        rules = {}
    end

    for i = 1, #rules do
        rules[i] = ensureTimerRule(rules[i], i)
    end

    -- Migrate old fixed 5-slot timer schema when all rows are placeholders.
    if #rules == 5 then
        local hasOnlyLegacyDefaults = true
        for i = 1, 5 do
            local defaults = createDefaultTimerRule(i)
            local rule = rules[i]
            if type(rule) ~= "table" then
                hasOnlyLegacyDefaults = false
                break
            end

            for key, defaultValue in pairs(defaults) do
                if rule[key] ~= defaultValue then
                    hasOnlyLegacyDefaults = false
                    break
                end
            end

            if not hasOnlyLegacyDefaults then
                break
            end
        end

        if hasOnlyLegacyDefaults then
            rules = {}
        end
    end

    if wasMissing and minEntriesWhenMissing and minEntriesWhenMissing > 0 then
        for i = 1, minEntriesWhenMissing do
            rules[i] = createDefaultTimerRule(i)
        end
    end

    helperConfig.timers = rules
end

