modulePresetSlotCount = 10
modulePresetNavigationFlagKey = "navigationEnabled"

function getModulePresetSlotName(index)
    return string.format("Preset %d", tonumber(index) or 1)
end

function getModulePresetSlotIndex(presetName)
    local key = tostring(presetName or "")
    local slotIndex = tonumber(key:match("^Preset%s+(%d+)$"))
    if not slotIndex or slotIndex < 1 or slotIndex > modulePresetSlotCount then
        return nil
    end
    return slotIndex
end

function getModulePresetActivationActionName(moduleType, presetName)
    local meta = modulePresetMeta[moduleType]
    local slotIndex = getModulePresetSlotIndex(presetName)
    if not meta or not slotIndex then
        return nil
    end
    return string.format("Activate %s Preset %d", meta.title, slotIndex)
end

function activateModulePresetBySlot(moduleType, slotIndex, hideMessage)
    local parsedIndex = tonumber(slotIndex)
    if not parsedIndex or parsedIndex < 1 or parsedIndex > modulePresetSlotCount then
        return
    end
    loadModulePresetByName(moduleType, getModulePresetSlotName(parsedIndex), hideMessage == true)
end

function getModulePresetDisplayName(moduleType, presetKey)
    local meta = modulePresetMeta[moduleType]
    if not meta or type(helperConfig) ~= "table" then
        return tostring(presetKey or "")
    end

    local key = tostring(presetKey or "")
    if key == "" then
        return ""
    end

    local labels = helperConfig[meta.labelsKey]
    local label = labels and labels[key] or nil
    if type(label) == "string" and label:len() > 0 then
        return label
    end
    return key
end

function getModulePresetUiName(moduleType, presetKey)
    local key = tostring(presetKey or "")
    local label = getModulePresetDisplayName(moduleType, key)
    if key == "" then
        return label
    end
    if not label or label == "" or label == key then
        return key
    end
    return label
end

modulePresetUiSyncDepth = 0
modulePresetApplyDepth = 0

function runWithModulePresetUiSync(callback)
    modulePresetUiSyncDepth = (modulePresetUiSyncDepth or 0) + 1
    local ok, err = pcall(callback)
    modulePresetUiSyncDepth = math.max((modulePresetUiSyncDepth or 1) - 1, 0)
    if not ok then
        error(err)
    end
end

function getPresetPanelRefByType(moduleType)
    local meta = modulePresetMeta[moduleType]
    if not meta then
        return nil
    end

    if moduleType == "shooter" then
        return presetsPanel or (shooterPanel and shooterPanel:recursiveGetChildById(meta.panelId))
    elseif moduleType == "healing" then
        return healingPresetsPanel or (helper and helper:recursiveGetChildById(meta.panelId))
    elseif moduleType == "equipment" then
        return equipmentPresetsPanel or (helper and helper:recursiveGetChildById(meta.panelId))
    elseif moduleType == "targeting" then
        return targetingPresetsPanel or (helper and helper:recursiveGetChildById(meta.panelId))
    end

    return nil
end

function completeModulePresetData(moduleType, presetData, fallbackData)
    local fields = modulePresetFields[moduleType]
    if not fields or type(presetData) ~= "table" or type(fallbackData) ~= "table" then
        return presetData
    end

    for _, key in ipairs(fields) do
        if presetData[key] == nil and fallbackData[key] ~= nil then
            presetData[key] = deepCopy(fallbackData[key])
        end
    end
    return presetData
end

function getPresetComboRefByType(moduleType)
    local panel = getPresetPanelRefByType(moduleType)
    local meta = modulePresetMeta[moduleType]
    if not panel or not meta then
        return nil
    end
    return panel:recursiveGetChildById(meta.comboId)
end

function ensureModulePresetNavigationFlag(presetData)
    if type(presetData) ~= "table" then
        return false
    end

    if presetData[modulePresetNavigationFlagKey] == nil then
        presetData[modulePresetNavigationFlagKey] = true
    else
        presetData[modulePresetNavigationFlagKey] = presetData[modulePresetNavigationFlagKey] == true
    end
    return presetData[modulePresetNavigationFlagKey] == true
end

function getModulePresetNavigationToggleRef(moduleType)
    local panel = getPresetPanelRefByType(moduleType)
    local meta = modulePresetMeta[moduleType]
    if not panel or not meta or type(meta.navigationToggleId) ~= "string" then
        return nil
    end
    return panel:recursiveGetChildById(meta.navigationToggleId)
end

function isModulePresetNavigationEnabled(moduleType, presetName)
    local meta = modulePresetMeta[moduleType]
    if not meta or type(helperConfig) ~= "table" then
        return false
    end

    local profiles = helperConfig[meta.profilesKey]
    if type(profiles) ~= "table" then
        return false
    end

    local key = tostring(presetName or "")
    local preset = profiles[key]
    if type(preset) ~= "table" then
        return false
    end

    return ensureModulePresetNavigationFlag(preset)
end

function setModulePresetNavigationEnabled(moduleType, presetName, enabled)
    local meta = modulePresetMeta[moduleType]
    if not meta or type(helperConfig) ~= "table" then
        return false
    end

    local profiles = helperConfig[meta.profilesKey]
    if type(profiles) ~= "table" then
        return false
    end

    local key = tostring(presetName or "")
    if key == "" then
        return false
    end

    local preset = profiles[key]
    if type(preset) ~= "table" then
        return false
    end

    ensureModulePresetNavigationFlag(preset)
    preset[modulePresetNavigationFlagKey] = enabled == true
    return true
end

function updateModulePresetNavigationToggle(moduleType)
    local meta = modulePresetMeta[moduleType]
    if not meta or type(helperConfig) ~= "table" then
        return
    end

    local toggle = getModulePresetNavigationToggleRef(moduleType)
    if not toggle or not toggle.setChecked then
        return
    end

    local selectedName = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
    local checked = isModulePresetNavigationEnabled(moduleType, selectedName)
    if toggle.isChecked and toggle:isChecked() == checked then
        return
    end

    local oldCallback = toggle.onCheckChange
    toggle.onCheckChange = nil
    toggle:setChecked(checked)
    toggle.onCheckChange = oldCallback
end

function findNextNavigableModulePresetName(moduleType, currentName, direction, names)
    local orderedNames = names or getSortedModulePresetNames(moduleType)
    if type(orderedNames) ~= "table" or #orderedNames == 0 then
        return nil
    end

    local current = tostring(currentName or "")
    local currentIndex = 1
    for i, presetName in ipairs(orderedNames) do
        if presetName == current then
            currentIndex = i
            break
        end
    end

    local step = (tonumber(direction) or 1) >= 0 and 1 or -1
    local candidateIndex = ((currentIndex - 1 + step) % #orderedNames) + 1
    return orderedNames[candidateIndex]
end

function captureModulePresetData(moduleType)
    local fields = modulePresetFields[moduleType]
    if not fields or type(helperConfig) ~= "table" then
        return {}
    end

    local snapshot = {}
    for _, key in ipairs(fields) do
        snapshot[key] = deepCopy(helperConfig[key])
    end
    return snapshot
end

function createEmptyModulePresetData(moduleType)
    if moduleType == "shooter" then
        return {
            spells = {},
            runes = {},
            [modulePresetNavigationFlagKey] = true
        }
    end

    local fields = modulePresetFields[moduleType]
    local snapshot = {}
    if type(fields) == "table" then
        local defaultsSource = helperConfigDefaults or helperConfig or {}
        for _, key in ipairs(fields) do
            snapshot[key] = deepCopy(defaultsSource[key])
        end
    end

    if moduleType == "healing" then
        snapshot.healingRules = {}
    elseif moduleType == "equipment" then
        snapshot.amulets = {}
        snapshot.rings = {}
    elseif moduleType == "targeting" then
        snapshot.ignoredMobs = {}
        snapshot.priorityMobs = {}
    end
    snapshot[modulePresetNavigationFlagKey] = true

    return snapshot
end

function applyModulePresetData(moduleType, presetData)
    if type(helperConfig) ~= "table" or type(presetData) ~= "table" then
        return
    end

    local fields = modulePresetFields[moduleType]
    if not fields then
        return
    end

    for _, key in ipairs(fields) do
        if presetData[key] ~= nil then
            helperConfig[key] = deepCopy(presetData[key])
        end
    end

    if moduleType == "healing" then
        ensureHealingSlots(helperConfig)
        ensureHealingRulesConfig()
    elseif moduleType == "equipment" then
        ensureEquipmentSwapConfig()
    end
end

function ensureModulePresetConfig(moduleType)
    local meta = modulePresetMeta[moduleType]
    if not meta or type(helperConfig) ~= "table" then
        return
    end

    local profiles = helperConfig[meta.profilesKey]
    if type(profiles) ~= "table" then
        profiles = {}
        helperConfig[meta.profilesKey] = profiles
    end

    local labels = helperConfig[meta.labelsKey]
    if type(labels) ~= "table" then
        labels = {}
        helperConfig[meta.labelsKey] = labels
    end

    local hasFixedSlots = true
    for i = 1, modulePresetSlotCount do
        local slotName = getModulePresetSlotName(i)
        if type(profiles[slotName]) ~= "table" then
            hasFixedSlots = false
            break
        end
    end

    if not hasFixedSlots then
        local legacyNames = {}
        for profileName, profileData in pairs(profiles) do
            if type(profileData) == "table" then
                legacyNames[#legacyNames + 1] = profileName
            end
        end
        table.sort(legacyNames, function(a, b)
            if a == "Default" and b ~= "Default" then
                return true
            elseif b == "Default" and a ~= "Default" then
                return false
            end
            return tostring(a) < tostring(b)
        end)

        local selectedLegacy = tostring(helperConfig[meta.selectedKey] or "")
        local mappedSelectedSlot = nil
        local newProfiles = {}
        local newLabels = {}

        for i = 1, modulePresetSlotCount do
            local slotName = getModulePresetSlotName(i)
            local legacyName = legacyNames[i]
            local legacyData = legacyName and profiles[legacyName] or nil
            if type(legacyData) == "table" then
                newProfiles[slotName] = deepCopy(legacyData)
                newLabels[slotName] = tostring(legacyName)
                if tostring(legacyName) == selectedLegacy then
                    mappedSelectedSlot = slotName
                end
            else
                newProfiles[slotName] = createEmptyModulePresetData(moduleType)
                newLabels[slotName] = slotName
            end
        end

        profiles = newProfiles
        labels = newLabels
        helperConfig[meta.profilesKey] = profiles
        helperConfig[meta.labelsKey] = labels
        helperConfig[meta.selectedKey] = mappedSelectedSlot or getModulePresetSlotName(1)
    else
        local normalizedProfiles = {}
        local normalizedLabels = {}
        for i = 1, modulePresetSlotCount do
            local slotName = getModulePresetSlotName(i)
            local profileData = profiles[slotName]
            if type(profileData) ~= "table" then
                profileData = createEmptyModulePresetData(moduleType)
            end
            normalizedProfiles[slotName] = profileData

            local label = labels[slotName]
            if type(label) ~= "string" or label:len() == 0 then
                label = slotName
            end
            normalizedLabels[slotName] = label
        end
        profiles = normalizedProfiles
        labels = normalizedLabels
        helperConfig[meta.profilesKey] = profiles
        helperConfig[meta.labelsKey] = labels
    end

    for i = 1, modulePresetSlotCount do
        local slotName = getModulePresetSlotName(i)
        local profileData = profiles[slotName]
        if type(profileData) ~= "table" then
            profileData = createEmptyModulePresetData(moduleType)
            profiles[slotName] = profileData
        end
        ensureModulePresetNavigationFlag(profileData)
    end

    local fields = modulePresetFields[moduleType]
    if fields then
        local moduleDefaults = createEmptyModulePresetData(moduleType)
        local slotOne = getModulePresetSlotName(1)
        local defaultPreset = profiles[slotOne]
        if type(defaultPreset) ~= "table" then
            defaultPreset = moduleType == "shooter" and deepCopy(defaultShooterProfile) or deepCopy(moduleDefaults)
        end
        defaultPreset = completeModulePresetData(moduleType, defaultPreset, moduleDefaults)
        profiles[slotOne] = defaultPreset

        for i = 1, modulePresetSlotCount do
            local slotName = getModulePresetSlotName(i)
            local profileData = profiles[slotName]
            if type(profileData) ~= "table" then
                profiles[slotName] = deepCopy(moduleDefaults)
            else
                profiles[slotName] = completeModulePresetData(moduleType, profileData, moduleDefaults)
            end
        end
    end

    local selected = tostring(helperConfig[meta.selectedKey] or "")
    if selected == "" or not profiles[selected] then
        for i = 1, modulePresetSlotCount do
            local slotName = getModulePresetSlotName(i)
            if labels[slotName] == selected and profiles[slotName] then
                selected = slotName
                break
            end
        end
    end
    if selected == "" or not profiles[selected] then
        selected = getModulePresetSlotName(1)
    end
    helperConfig[meta.selectedKey] = selected
end

function persistCurrentModulePreset(moduleType)
    local meta = modulePresetMeta[moduleType]
    local fields = modulePresetFields[moduleType]
    if not meta or not fields then
        return
    end

    ensureModulePresetConfig(moduleType)
    local selected = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
    if selected == "" then
        selected = getModulePresetSlotName(1)
        helperConfig[meta.selectedKey] = selected
    end

    local existingPreset = helperConfig[meta.profilesKey][selected]
    local navigationEnabled = true
    if type(existingPreset) == "table" then
        navigationEnabled = ensureModulePresetNavigationFlag(existingPreset)
    end

    local snapshot = captureModulePresetData(moduleType)
    snapshot[modulePresetNavigationFlagKey] = navigationEnabled == true
    helperConfig[meta.profilesKey][selected] = snapshot
end

function getSortedModulePresetNames(moduleType)
    local meta = modulePresetMeta[moduleType]
    if not meta or type(helperConfig) ~= "table" or type(helperConfig[meta.profilesKey]) ~= "table" then
        return {}
    end

    local names = {}
    for i = 1, modulePresetSlotCount do
        local slotName = getModulePresetSlotName(i)
        if helperConfig[meta.profilesKey][slotName] then
            names[#names + 1] = slotName
        end
    end
    return names
end

function loadModulePresetOptions(moduleType, forceRefresh)
    local meta = modulePresetMeta[moduleType]
    if not meta then
        return
    end
    ensureModulePresetConfig(moduleType)

    local combo = getPresetComboRefByType(moduleType)
    if not combo then
        return
    end

    if not forceRefresh then
        if combo.getChildCount and combo:getChildCount() > 0 then
            return
        elseif combo.getOptionsCount and combo:getOptionsCount() > 0 then
            return
        end
    end

    runWithModulePresetUiSync(function()
        if forceRefresh and combo.clearOptions then
            combo:clearOptions()
        end

        local names = getSortedModulePresetNames(moduleType)
        for _, name in ipairs(names) do
            if combo.addOption then
                combo:addOption(getModulePresetUiName(moduleType, name), name)
            end
        end

        local selected = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
        if combo.setCurrentOptionByData then
            combo:setCurrentOptionByData(selected, true)
        elseif combo.setCurrentOption then
            combo:setCurrentOption(getModulePresetUiName(moduleType, selected), true)
        end
    end)
    updateModulePresetNavigationToggle(moduleType)
end

function loadModulePresetByName(moduleType, profileName, hideMessage)
    local meta = modulePresetMeta[moduleType]
    if not meta then
        return
    end

    local targetName = tostring(profileName or getModulePresetSlotName(1))
    ensureModulePresetConfig(moduleType)
    if moduleType ~= "shooter" then
        local currentName = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
        if currentName ~= targetName then
            persistCurrentModulePreset(moduleType)
        end
    end

    local profiles = helperConfig[meta.profilesKey]
    local preset = profiles and profiles[targetName] or nil
    if type(preset) ~= "table" then
        return
    end
    local targetDisplayName = getModulePresetUiName(moduleType, targetName)

    if moduleType == "shooter" then
        helperConfig[meta.selectedKey] = targetName
        loadShooterProfileByName(targetName)
        saveSettings()
        if IconStatsModule and IconStatsModule.updateModulePresetTooltip then
            IconStatsModule.updateModulePresetTooltip("shooter")
        end
        updateModulePresetNavigationToggle(moduleType)
        refreshPresetHotkeyLabelsDeferred()
        if not hideMessage then
            modules.game_textmessage.displayGameMessage(string.format(meta.switchMessage, targetDisplayName))
        end
        return
    end

    modulePresetApplyDepth = (modulePresetApplyDepth or 0) + 1
    local ok, err = pcall(function()
        helperConfig[meta.selectedKey] = targetName
        applyModulePresetData(moduleType, preset)
        local refreshed = refreshModulePresetUi(moduleType)
        if moduleType == "healing" or not refreshed then
            onLoadHelperData()
        end
        saveSettings()
        if IconStatsModule and IconStatsModule.updateModulePresetTooltip then
            IconStatsModule.updateModulePresetTooltip(moduleType)
        end
        updateModulePresetNavigationToggle(moduleType)
        refreshPresetHotkeyLabelsDeferred()

        if not hideMessage then
            modules.game_textmessage.displayGameMessage(string.format(meta.switchMessage, targetDisplayName))
        end
    end)
    modulePresetApplyDepth = math.max((modulePresetApplyDepth or 1) - 1, 0)
    if not ok then
        error(err)
    end
end

function toggleModulePreset(moduleType, widget, hideMessage)
    if (modulePresetUiSyncDepth or 0) > 0 or (modulePresetApplyDepth or 0) > 0 then
        return
    end

    local meta = modulePresetMeta[moduleType]
    if not meta then
        return
    end
    ensureModulePresetConfig(moduleType)

    local selectedName = nil
    if widget and widget.getCurrentOption then
        local current = widget:getCurrentOption()
        selectedName = current and (current.data or current.text) or nil
        if selectedName and type(selectedName) == "string" and not helperConfig[meta.profilesKey][selectedName] then
            local parsedSlot = selectedName:match("^Preset%s+%d+")
            if parsedSlot and helperConfig[meta.profilesKey][parsedSlot] then
                selectedName = parsedSlot
            end
        end
    end

    if selectedName and selectedName ~= "" then
        loadModulePresetByName(moduleType, selectedName, hideMessage == true)
        return
    end

    local combo = getPresetComboRefByType(moduleType)
    local names = getSortedModulePresetNames(moduleType)
    if #names == 0 then
        return
    end

    local currentName = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
    local nextName = findNextNavigableModulePresetName(moduleType, currentName, 1, names)
    if not nextName or nextName == currentName then
        return
    end

    runWithModulePresetUiSync(function()
        if combo and combo.setCurrentOptionByData then
            combo:setCurrentOptionByData(nextName, true)
        elseif combo and combo.setCurrentOption then
            combo:setCurrentOption(getModulePresetUiName(moduleType, nextName), true)
        end
    end)
    loadModulePresetByName(moduleType, nextName, hideMessage == true)
end

function cycleModulePreset(moduleType, direction)
    local meta = modulePresetMeta[moduleType]
    if not meta then
        return
    end
    ensureModulePresetConfig(moduleType)

    local names = getSortedModulePresetNames(moduleType)
    if #names == 0 then
        return
    end

    local currentName = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
    local targetName = findNextNavigableModulePresetName(moduleType, currentName, direction or 1, names)
    if not targetName then
        modules.game_textmessage.displayGameMessage(
            string.format("No %s preset is enabled for previous/next navigation.", string.lower(meta.title))
        )
        return
    end
    if targetName == currentName then
        return
    end

    local combo = getPresetComboRefByType(moduleType)
    runWithModulePresetUiSync(function()
        if combo and combo.setCurrentOptionByData then
            combo:setCurrentOptionByData(targetName, true)
        elseif combo and combo.setCurrentOption then
            combo:setCurrentOption(getModulePresetUiName(moduleType, targetName), true)
        end
    end)
    loadModulePresetByName(moduleType, targetName, true)
    modules.game_textmessage.displayGameMessage(
        string.format(meta.switchMessage, getModulePresetUiName(moduleType, targetName))
    )
end

function refreshModulePresetUi(moduleType)
    if moduleType == "healing" then
        ensureHealingRulesConfig(HEALING_DEFAULT_RULE_COUNT)
        rebuildAllHealingRules()
        return true
    end

    if moduleType == "equipment" then
        local panel = equipmentPanel or (helper and helper:recursiveGetChildById("equipmentPanel"))
        if not panel then
            return false
        end

        ensureEquipmentSwapConfig(EQUIPMENT_SWAP_DEFAULT_SLOT_COUNT)
        rebuildAllEquipmentSwapRules()
        updateAllItemCounts()

        local function safeSetChecked(widgetId, checked)
            local widget = panel:recursiveGetChildById(widgetId)
            if not widget or not widget.setChecked then
                return
            end

            local target = checked == true
            if widget.isChecked and widget:isChecked() == target then
                return
            end

            local oldCallback = widget.onCheckChange
            widget.onCheckChange = nil
            widget:setChecked(target)
            widget.onCheckChange = oldCallback
        end

        safeSetChecked("enableEquipmentSwap", helperConfig.equipmentSwapEnabled == true)
        safeSetChecked("enableTankMode", helperConfig.tankModeEnabled == true)
        safeSetChecked("enableTankModeAmulet", helperConfig.tankModeAmuletEnabled ~= false)
        safeSetChecked("enableTankModeRing", helperConfig.tankModeRingEnabled ~= false)
        safeSetChecked("respectEnergyRing", helperConfig.respectEnergyRing == true)
        safeSetChecked("enableSSATank", helperConfig.ssaTankEnabled == true)
        safeSetChecked("enableMightRing", helperConfig.mightRingEnabled == true)

        local tankModeAmuletButton = panel:recursiveGetChildById("tankModeAmuletButton")
        if tankModeAmuletButton then
            updateTankModeAmuletButton(tankModeAmuletButton, tonumber(helperConfig.tankModeAmuletId) or 3081)
        end

        local tankModeRingButton = panel:recursiveGetChildById("tankModeRingButton")
        if tankModeRingButton then
            updateTankModeRingButton(tankModeRingButton, tonumber(helperConfig.tankModeRingId) or 3048)
        end

        return true
    end

    if moduleType == "targeting" then
        local panel = targetingPanel or (helper and helper:recursiveGetChildById("huntingTargetingContent"))
        if not panel then
            return false
        end

        local function safeSetChecked(widgetId, checked)
            local widget = panel:recursiveGetChildById(widgetId)
            if not widget or not widget.setChecked then
                return
            end

            local target = checked == true
            if widget.isChecked and widget:isChecked() == target then
                return
            end

            local oldCallback = widget.onCheckChange
            widget.onCheckChange = nil
            widget:setChecked(target)
            widget.onCheckChange = oldCallback
        end

        safeSetChecked("enableAutoTarget", helperConfig.autoTargetEnabled == true)
        safeSetChecked("prioritizeBossCheckBox", helperConfig.prioritizeBoss ~= false)

        local ignoredMobsInput = panel:recursiveGetChildById("ignoredMobsInput")
        if ignoredMobsInput then
            ignoredMobsInput:setText(table.concat(helperConfig.ignoredMobs or {}, ", "))
        end

        local priorityMobsInput = panel:recursiveGetChildById("priorityMobsInput")
        if priorityMobsInput then
            priorityMobsInput:setText(table.concat(helperConfig.priorityMobs or {}, ", "))
        end

        safeSetChecked("pauseCavebotOnMobCheck", helperConfig.pauseCavebotOnMobEnabled == true)
        local pauseCavebotOnMobInput = panel:recursiveGetChildById("pauseCavebotOnMobInput")
        if pauseCavebotOnMobInput then
            pauseCavebotOnMobInput:setText(table.concat(helperConfig.pauseCavebotOnMobs or {}, ", "))
        end

        local maxDistanceInput = panel:recursiveGetChildById("maxTargetDistanceInput")
        if maxDistanceInput then
            maxDistanceInput:setText(tostring(tonumber(helperConfig.maxTargetDistance) or 7))
        end

        local attackPositionCombo = panel:recursiveGetChildById("attackPositionCombo")
        if attackPositionCombo and attackPositionCombo.setCurrentIndex then
            attackPositionCombo:setCurrentIndex(tonumber(helperConfig.attackPosition) or 1)
        end

        local attackDistanceInput = panel:recursiveGetChildById("attackDistanceInput")
        if attackDistanceInput then
            attackDistanceInput:setText(tostring(tonumber(helperConfig.attackDistance) or 1))
        end

        local modeText = "A"
        for key, value in pairs(autoTargetModes) do
            if value == helperConfig.autoTargetMode then
                modeText = key
                break
            end
        end
        updateAutoTargetModeDisplay(modeText)
        updateTargetModeButtonStates()
        return true
    end

    return false
end

