-- Alarm system functions (defined before eventTable)
local function getAlarmCheckbox(id)
    if not alarmsPanel then
        return nil
    end
    -- Tentar encontrar no painel principal primeiro
    local checkbox = alarmsPanel:recursiveGetChildById(id)
    if not checkbox then
        -- Tentar encontrar no painel de opcoes
        local alarmOptions = alarmsPanel:recursiveGetChildById("alarmOptions")
        if alarmOptions then
            checkbox = alarmOptions:recursiveGetChildById(id)
        end
    end
    if not checkbox then
        -- Tentar encontrar no painel de lista de alarmes
        local alarmsList = alarmsPanel:recursiveGetChildById("alarmsList")
        if alarmsList then
            checkbox = alarmsList:recursiveGetChildById(id)
        end
    end
    return checkbox
end

local function isAlarmEnabled(id)
    local checkbox = getAlarmCheckbox(id)
    return checkbox and checkbox:isChecked() or false
end

local function getAlarmOption(id)
    if not alarmsPanel then
        return false
    end
    local checkbox = getAlarmCheckbox(id)
    if not checkbox then
        return false
    end
    return checkbox:isChecked()
end

-- Flag para evitar que callbacks sobrescrevam dados durante o carregamento.
-- Nome historico era "alarm data" mas hoje cobre o ciclo inteiro de load
-- de profile. F2.5 expoe versao global pra qualquer callback de widget
-- dinamico (spells, equipment, presets, alarms) checar antes de mexer em
-- helperConfig durante onLoadHelperData.
local isLoadingAlarmData = false

function isProfileLoadingActive()
    return isLoadingAlarmData == true
end

function setProfileLoadingActive(flag)
    isLoadingAlarmData = flag and true or false
end

_G.isProfileLoadingActive  = isProfileLoadingActive
_G.setProfileLoadingActive = setProfileLoadingActive

-- Funcao para atualizar opcoes de alarme em memoria (sem salvar)
local function updateAlarmSettings()
    -- Se estamos carregando dados, nao sobrescrever os valores em memoria
    if isLoadingAlarmData then
        return
    end

    -- Campos validos de alarms (apenas os que sao checkboxes na UI)
    local validAlarmFields = {
        alarmDamageTaken = true,
        alarmLowHealth = true,
        alarmLowHealthThreshold = true,
        alarmMonsterOnScreen = true,
        alarmPlayerOnScreen = true,
        alarmPlayerSkullOnScreen = true,
        alarmPlayerAttack = true,
        alarmEnemyOnScreen = true,
        alarmSoundAlert = true,
        alarmWindowsBarFlash = true
    }

    -- Garantir que helperConfig.alarms existe
    if not helperConfig.alarms then
        helperConfig.alarms = {
            alarmDamageTaken = false,
            alarmLowHealth = false,
            alarmLowHealthThreshold = 50,
            alarmMonsterOnScreen = false,
            alarmPlayerOnScreen = false,
            alarmPlayerSkullOnScreen = false,
            alarmPlayerAttack = false,
            alarmEnemyOnScreen = false,
            alarmSoundAlert = false,
            alarmWindowsBarFlash = false
        }
    end

    -- Se o painel estiver disponivel, atualizar valores dos checkboxes
    if alarmsPanel then
        -- Atualizar estado de todos os checkboxes de alarme em memoria
        local alarmCheckboxes = {
            "alarmDamageTaken",
            "alarmLowHealth",
            "alarmMonsterOnScreen",
            "alarmPlayerOnScreen",
            "alarmPlayerSkullOnScreen",
            "alarmPlayerAttack",
            "alarmEnemyOnScreen",
            "alarmSoundAlert",
            "alarmWindowsBarFlash"
        }

        for _, checkboxId in ipairs(alarmCheckboxes) do
            local checkbox = getAlarmCheckbox(checkboxId)
            if checkbox then
                helperConfig.alarms[checkboxId] = checkbox:isChecked()
            end
        end

        -- Atualizar threshold de low health em memoria
        local lowHealthInput = getAlarmCheckbox("alarmLowHealthInput")
        if lowHealthInput then
            local thresholdText = lowHealthInput:getText()
            local threshold = tonumber(thresholdText) or 0
            helperConfig.alarms.alarmLowHealthThreshold = threshold
        end
    end

    -- Limpar campos invalidos APENAS apos atualizar da UI (para manter valores validos)
    local cleanedAlarms = {}
    for field, value in pairs(helperConfig.alarms) do
        if validAlarmFields[field] then
            cleanedAlarms[field] = value
        end
    end
    helperConfig.alarms = cleanedAlarms
end

-- Funcoes de callback para checkboxes de alarme (apenas atualiza em memoria)
function onAlarmCheckboxChange(checkboxId, checked)
    -- Ignorar callbacks durante o carregamento de dados
    if isLoadingAlarmData then
        return
    end

    if not helperConfig.alarms then
        helperConfig.alarms = {}
    end
    helperConfig.alarms[checkboxId] = checked
    updateAlarmSettings()
end

function onAlarmLowHealthThresholdChange(text)
    -- Ignorar callbacks durante o carregamento de dados
    if isLoadingAlarmData then
        return
    end

    if not helperConfig.alarms then
        helperConfig.alarms = {}
    end
    local threshold = tonumber(text) or 0
    if threshold < 0 then threshold = 0 end
    if threshold > 100 then threshold = 100 end
    helperConfig.alarms.alarmLowHealthThreshold = threshold
    updateAlarmSettings()
end

--- Funcao auxiliar para verificar se o dano veio de um player
local function isDamageFromPlayer(player)
    local damageFromPlayer = false
    local attackerName = "Unknown"
    local localPlayer = player or g_game.getLocalPlayer()

    if not localPlayer then
        return false, "Unknown"
    end

    -- Metodo 1: Verificar battle list (atacantes do player)
    local attackingCreatures = {}
    if localPlayer.getAttackingCreatures then
        attackingCreatures = localPlayer:getAttackingCreatures() or {}
    end

    -- Debug removed for performance: print("[PLAYER-ATTACK-DETECT] Atacantes na battle list: " .. tostring(#attackingCreatures))

    -- Metodo 2: Verificar spectators na tela (players proximos que podem estar atacando)
    local playerPos = localPlayer:getPosition()
    if playerPos then
        local spectators = {}
        if modules.game_interface and modules.game_interface.getMapPanel then
            local mapPanel = modules.game_interface.getMapPanel()
            if mapPanel and mapPanel.getSpectators then
                spectators = mapPanel:getSpectators() or {}
            end
        end
        -- OPTIMIZATION: Use CreatureCache as fallback instead of raw getSpectators
        if #spectators == 0 then
            local cached = CreatureCache.getPlayers()
            for _, entry in ipairs(cached) do
                spectators[#spectators + 1] = entry.creature
            end
        end

        -- Debug removed for performance: print("[PLAYER-ATTACK-DETECT] Spectators na tela: " .. tostring(#spectators))

        -- Verificar se algum player proximo esta atacando
        for _, creature in ipairs(spectators) do
            if creature and creature:isPlayer() and creature ~= localPlayer then
                local creatureName = creature:getName() or "Unknown"
                local creaturePos = creature:getPosition()

                -- Verificar se o player esta proximo (dentro de 10 sqm para range)
                if creaturePos then
                    local dx = math.abs(playerPos.x - creaturePos.x)
                    local dy = math.abs(playerPos.y - creaturePos.y)
                    local dz = math.abs(playerPos.z - creaturePos.z)

                    -- Se esta proximo (ate 10 sqm) e tem skull, provavelmente esta atacando
                    if dz == 0 and dx <= 10 and dy <= 10 then
                        local skull = creature:getSkull() or -1
                        if skull == SkullWhite or skull == SkullRed or skull == SkullBlack or skull == SkullYellow then
                            -- Debug removed for performance
                            damageFromPlayer = true
                            attackerName = creatureName
                            break
                        end
                    end

                    -- Verificar se esta na battle list como atacante
                    for _, attacker in ipairs(attackingCreatures) do
                        if attacker and attacker:getId() == creature:getId() then
                            -- Debug removed for performance
                            damageFromPlayer = true
                            attackerName = creatureName
                            break
                        end
                    end
                end
            end
        end
    end

    -- Metodo 3: Verificar battle list diretamente
    for i, attacker in ipairs(attackingCreatures) do
        if attacker then
            local isPlayer = attacker:isPlayer() or false
            local name = attacker:getName() or "Unknown"
            local skull = attacker:getSkull() or -1
            -- Debug removed for performance
            if isPlayer then
                damageFromPlayer = true
                attackerName = name
                break
            end
        end
    end

    return damageFromPlayer, attackerName
end

local function triggerAlarm(alarmType, cooldown, extraInfo)
    cooldown = cooldown or 2000
    local now = g_clock.millis()
    local lastTime = alarmState.lastAlarmTime[alarmType] or 0

    if now - lastTime < cooldown then
        return
    end

    alarmState.lastAlarmTime[alarmType] = now

    -- Sound Alert - som especifico por tipo de alarme (audio nativo do cliente)
    if getAlarmOption("alarmSoundAlert") and g_sounds then
        -- som proprio do alarme; fallback p/ alarm.wav generico se nao mapeado
        local soundFile = ALARM_SOUNDS[alarmType] or "/sounds/alarm.wav"
        local now = g_clock.millis()
        local soundCooldown = 3000 -- 3s entre repeticoes do MESMO som
        if now - (alarmState.lastSoundTime[soundFile] or 0) >= soundCooldown then
            alarmState.lastSoundTime[soundFile] = now

            -- precarrega no buffer (1x por som) p/ tocar imediato; streaming async
            -- nao e confiavel p/ SFX curto. gain explicito (default da API e 0 = mudo).
            if not alarmState.soundPreloaded[soundFile] then
                pcall(function() g_sounds.preload(soundFile) end)
                alarmState.soundPreloaded[soundFile] = true
            end
            pcall(function()
                g_sounds.play(soundFile, 0, 1.0)
            end)
        end
    end

    -- Trazer a janela do cliente para frente se estiver minimizada/em background
    -- (cooldown de 2 segundos)
    if getAlarmOption("alarmWindowsBarFlash") then
        local now = g_clock.millis()
        local bringToTopCooldown = 2000 -- 2 segundos entre chamadas
        if now - alarmState.lastBringToTopTime >= bringToTopCooldown then
            alarmState.lastBringToTopTime = now

            if g_window then
                pcall(function()
                    if g_window.bringToFront then
                        g_window.bringToFront() -- restaura + foreground + flash (nativo)
                    elseif g_window.flash then
                        g_window.flash()        -- fallback: so pisca a taskbar
                    end
                end)
            end
        end
    end
end

function checkAlarms(player)
    if not alarmsPanel then
        return
    end

    -- Se nao tem player ou nao esta online, pular alarmes
    if not player or not g_game.isOnline() then
        return
    end

    -- Verificar se esta em Protection Zone
    local inPZ = false
    if player.getStates and PlayerStates then
        inPZ = bit.band(player:getStates(), PlayerStates.Pz) > 0
    end

    -- Se estiver em PZ, pular todos os alarmes
    if inPZ then
        return
    end

    -- Low Health check
    if isAlarmEnabled("alarmLowHealth") then
        local healthPercent = (player:getHealth() / player:getMaxHealth()) * 100
        local thresholdInput = getAlarmCheckbox("alarmLowHealthInput")
        if thresholdInput then
            local threshold = tonumber(thresholdInput:getText()) or 0
            if healthPercent <= threshold then
                triggerAlarm("lowHealth", 3000, string.format("HP: %.1f%% (threshold: %d%%)", healthPercent, threshold))
            end
        end
    end

    -- Verificar danos (para ambos os alarmes)
    local currentHealth = player:getHealth()
    local maxHealth = player:getMaxHealth()

    -- Inicializar lastHealth se necessario
    if not alarmState.lastHealth or alarmState.lastHealth == 0 then
        alarmState.lastHealth = currentHealth
    end

    -- Detectar se houve dano
    if currentHealth < alarmState.lastHealth then
        local damage = alarmState.lastHealth - currentHealth
        if damage > 0 then
            -- Alarme 1: Damage Taken (qualquer dano - monstro ou player)
            if isAlarmEnabled("alarmDamageTaken") then
                triggerAlarm("damageTaken", 1000)
            end

            -- Alarme 2: Player Attack (apenas dano de players)
            if isAlarmEnabled("alarmPlayerAttack") then
                local damageFromPlayer, attackerName = isDamageFromPlayer(player)
                if damageFromPlayer then
                    triggerAlarm("playerAttack", 1000)
                end
            end
        end
    end

    -- Sempre atualizar lastHealth
    alarmState.lastHealth = currentHealth

    -- Get creature lists once from cache for all alarm checks
    local checkMonster = isAlarmEnabled("alarmMonsterOnScreen")
    local checkPlayer = isAlarmEnabled("alarmPlayerOnScreen")
    local checkSkull = isAlarmEnabled("alarmPlayerSkullOnScreen")
    local checkEnemy = isAlarmEnabled("alarmEnemyOnScreen")

    -- Only fetch creatures if at least one creature alarm is enabled
    if checkMonster or checkPlayer or checkSkull or checkEnemy then
        -- Monster On Screen check
        if checkMonster then
            local monsters = CreatureCache.getMonsters()
            if #monsters > 0 then
                triggerAlarm("monsterOnScreen", 2000)
            end
        end

        -- Player checks (share the same player list)
        if checkPlayer or checkSkull or checkEnemy then
            local players = CreatureCache.getPlayers()

            -- Player On Screen check
            if checkPlayer and #players > 0 then
                triggerAlarm("playerOnScreen", 2000)
            end

            -- Player Skull On Screen / Enemy On Screen check
            if checkSkull or checkEnemy then
                for _, entry in ipairs(players) do
                    local skull = entry.creature:getSkull()
                    if skull == SkullWhite or skull == SkullRed or skull == SkullBlack or skull == SkullYellow then
                        if checkSkull then
                            triggerAlarm("playerSkullOnScreen", 2000)
                        end
                        if checkEnemy then
                            triggerAlarm("enemyOnScreen", 2000)
                        end
                        break
                    end
                end
            end
        end
    end
end

