-- Checks re-run by CastTiming wakes, in priority order (healing first, same
-- criticality the master cycle uses). Global on purpose: helper.lua's main
-- chunk is at Lua's 200-locals-per-function limit.
CAST_TIMING_WAKE_EVENTS = {
    "checkHealthHealing",
    "checkMana",
    "checkFriendHealing",
    "checkMagicShooter",
    "checkMagicHelper",
}

-- Wake dispatcher for the reactive cast engine (cast_timing.lua): re-runs the
-- timing-sensitive checks the moment a server cooldown is about to expire,
-- instead of waiting for the next polling tick. Defined here (not in
-- cast_timing.lua) so it lexically captures the `timers`/`eventTable` locals.
function castTimingWakeDispatch()
    if not hotkeyHelperStatus or not g_game.isOnline() then
        return
    end
    local wakePlayer = g_game.getLocalPlayer()
    if not wakePlayer or not helperConfig then
        return
    end

    -- Same pre-pass the master cycle runs before checkMagicShooter: decide
    -- whether the shooter potion must yield to a prioritized rune this round.
    if helperEvents then
        local okPeek, hold = pcall(magicShooterPeekHoldPotionBeforePrioritizedRune)
        helperEvents.shooterPotionHoldForRunePeek = (okPeek and hold) or false
    end

    for _, eventName in ipairs(CAST_TIMING_WAKE_EVENTS) do
        local eventData = eventTable[eventName]
        if eventData and type(eventData.action) == "function" then
            -- Reset the polling accumulator so the master cycle doesn't
            -- immediately re-run the same check right after this wake.
            timers[eventName] = 0
            local ok, err = pcall(eventData.action, wakePlayer)
            if not ok and err then
                local errorKey = eventName .. "_error"
                if g_clock.millis() - (timers[errorKey] or 0) > 60000 then
                    pwarning("[castTimingWakeDispatch] erro em " .. eventName .. ": " .. tostring(err))
                    timers[errorKey] = g_clock.millis()
                end
            end
        end
    end
end

ENGINE_INTERVAL_DEFS = {
    { kind = "healing",       default = 50,   events = { "checkHealthHealing", "checkMana" } },
    { kind = "friendHealing", default = 100,  events = { "checkFriendHealing" } },
    { kind = "magicShooter",  default = 100,  events = { "checkMagicShooter" } },
    { kind = "target",        default = 100,  events = { "checkAutoTarget" } },
    { kind = "equipmentSwap", default = 100,  events = { "checkEquipmentSwap" } },
    { kind = "tankMode",      default = 100,  events = { "checkTankMode" } },
    { kind = "tools",         default = 1000, events = { "routineChecks" } },
}

-- Loop floor shared by the master cycle and every per-subsystem interval: rows in
-- Settings > Engine can be dialed all the way down to this, and the master cycle
-- (helperCycleTimer) adapts to the fastest configured row but never ticks below it.
-- Declared WITHOUT `local` on purpose: helper.lua's main chunk is at Lua's
-- 200-locals-per-function limit, so a file-scope local here would overflow it.
ENGINE_MIN_INTERVAL = 20

local _engineDefByKind = {}
for _, def in ipairs(ENGINE_INTERVAL_DEFS) do
    def.min = ENGINE_MIN_INTERVAL
    def.max = def.default * 5
    _engineDefByKind[def.kind] = def
end

function getEngineIntervalDef(kind)
    return _engineDefByKind[kind]
end

local function clampEngineInterval(value, kind)
    local def = _engineDefByKind[kind]
    local minV = def and def.min or 100
    local maxV = def and def.max or 500
    local n = tonumber(value) or minV
    if n < minV then n = minV end
    if n > maxV then n = maxV end
    return n
end

local function getEngineIntervalValue(kind)
    helperConfig.engineIntervals = helperConfig.engineIntervals or {}
    local def = _engineDefByKind[kind]
    if not def then return 100 end
    local stored = helperConfig.engineIntervals[kind]
    if stored == nil then return def.default end
    return clampEngineInterval(stored, kind)
end

function applyEngineIntervalsFromConfig()
    if not eventTable or not helperConfig then return end
    -- Track the fastest configured subsystem so the master loop can match it. Seed at
    -- 50 (the legacy period) so the loop never *slows down* even if every row is raised.
    local minInterval = 50
    for _, def in ipairs(ENGINE_INTERVAL_DEFS) do
        local value = getEngineIntervalValue(def.kind)
        for _, eventName in ipairs(def.events) do
            if eventTable[eventName] then
                eventTable[eventName].interval = value
            end
        end
        if value < minInterval then minInterval = value end
    end
    -- Adaptive master cycle: helperCycleEvent accumulates helperCycleTimer per tick, so
    -- any interval below the loop period is silently capped at it. Tick as fast as the
    -- fastest configured row needs, floored at ENGINE_MIN_INTERVAL. Default configs keep
    -- the exact 50ms cadence (and CPU cost); only opting a row below 50ms speeds it up.
    local newCycle = math.max(ENGINE_MIN_INTERVAL, minInterval)
    if helperEvents and helperEvents.helperCycleTimer ~= newCycle then
        helperEvents.helperCycleTimer = newCycle
        -- Safe to reschedule even from inside helperCycleEvent's own execution: the
        -- dispatcher checks !m_canceled in nextCycle() after execute(), so cancelling the
        -- running cycle here just stops its re-queue and the freshly created one takes over.
        if helperEvents.helperCycleEvent then
            removeEvent(helperEvents.helperCycleEvent)
            helperEvents.helperCycleEvent = cycleEvent(helperCycleEvent, newCycle)
        end
    end

    -- Same triggers (boot pool init, settings UI, config/profile load) also
    -- refresh the reactive cast timing engine config.
    applyCastTimingFromConfig()
end

