local function buildFriendMap(friendList, mapRef)
    local map = {}
    if friendList then
        for _, friend in ipairs(friendList) do
            if friend.enabled and friend.name and friend.name:len() > 0 then
                map[friend.name:lower()] = true
            end
        end
    end
    return map
end

local function getFriendHealMap()
    if _friendHealMapDirty then
        _friendHealMap = buildFriendMap(helperConfig and helperConfig.tiosiofriendList)
        _friendHealMapDirty = false
    end
