local function getDistanceBetween(p1, p2)
    return math.max(math.abs(p1.x - p2.x), math.abs(p1.y - p2.y))
end

local function positionCompare(position1, position2)
    return position1.x == position2.x and position1.y == position2.y and position1.z == position2.z
end

local function playerHasSpell(player, spellId)
    -- Temporariamente retorna true para permitir casting de spells
    -- A verificação real pode ser implementada depois se necessário
    return true
end

local function numberToOrdinal(n)
    local lastDigit = n % 10
    local lastTwoDigits = n % 100
    if lastTwoDigits >= 11 and lastTwoDigits <= 13 then
        return tostring(n) .. "th"
    end
    if lastDigit == 1 then
        return tostring(n) .. "st"
    elseif lastDigit == 2 then
        return tostring(n) .. "nd"
    elseif lastDigit == 3 then
        return tostring(n) .. "rd"
    else
        return tostring(n) .. "th"
    end
end

local function isWithinReach(playerPos, targetPos)
    if type(targetPos) ~= "table" then
        return false
    end

    local deltaX = math.abs(playerPos.x - targetPos.x)
    local deltaY = math.abs(playerPos.y - targetPos.y)
    -- Alcance mais permissivo: 8 tiles em todas as direções
    local withinX = deltaX <= 8
    local withinY = deltaY <= 8
    return withinX and withinY and playerPos.z == targetPos.z
end

local function isPlayerSummon(creature)
    if not creature then
        return false
    end

    if creature.getType then
        local creatureType = creature:getType()
        if creatureType == CreatureTypeSummonOwn or creatureType == CreatureTypeSummonOther then
            return true
        end
    end

    if creature.getMasterId then
        local masterId = creature:getMasterId()
        -- Any creature with a master counts as a summon (incl. monster-owned
        -- summons like Necromancer's necromancer_raise_dead).
        if masterId and masterId > 0 then
            return true
        end
    end

    return false
end

local function onError(message)
    pwarning("Helper Error: " .. tostring(message))
    return false
end

local function translateVocation(vocation)
    if not vocation then
        return 0
    end

    -- Se for número, precisa mapear clientid para spell system id
    if type(vocation) == "number" then
        -- Mapeamento baseado no vocations.xml (clientid -> spell vocation id)
        local vocationMap = {
            [0] = 0,  -- None (clientid=0)
            [1] = 4,  -- Knight (clientid=1) -> spell id 4
            [2] = 3,  -- Paladin (clientid=2) -> spell id 3
            [3] = 1,  -- Sorcerer (clientid=3) -> spell id 1
            [4] = 2,  -- Druid (clientid=4) -> spell id 2
            [5] = 9,  -- Monk (clientid=5) -> spell id 9
            [11] = 8, -- Elite Knight (clientid=11) -> spell id 8
            [12] = 7, -- Royal Paladin (clientid=12) -> spell id 7
            [13] = 5, -- Master Sorcerer (clientid=13) -> spell id 5
            [14] = 6, -- Elder Druid (clientid=14) -> spell id 6
            [15] = 10 -- Exalted Monk (clientid=15) -> spell id 10
        }
        return vocationMap[vocation] or 0
    end

    -- If it's a string, try to convert common vocation names
    local vocationMap = {
        ["None"] = 0,
        ["Sorcerer"] = 1,
        ["Druid"] = 2,
        ["Paladin"] = 3,
        ["Knight"] = 4,
        ["Master Sorcerer"] = 5,
        ["Elder Druid"] = 6,
        ["Royal Paladin"] = 7,
        ["Elite Knight"] = 8,
        ["Monk"] = 9,
        ["Exalted Monk"] = 10
    }
    return vocationMap[vocation] or 0
end

-- getVocation so e bindado no LocalPlayer (C++); outros players na tela sao
-- Creature sem esse metodo (o protocolo nao envia a vocacao deles). Chamar
-- member:getVocation() direto quebrava o checkFriendHealing inteiro. Retorna a
-- vocacao traduzida quando disponivel, senao 0 (getHealPercent usa default p/ 0).
local function getMemberVocation(creature)
    if creature and creature.getVocation then
        return translateVocation(creature:getVocation())
    end
    return 0
end

local function getDefaultTargetMode()
    local player = g_game.getLocalPlayer()
    if not player then
        return autoTargetModes["F"]
    end

    local vocationId = translateVocation(player:getVocation())

    -- Paladin (base=3, promoted=7): modo E
    if vocationId == 3 or vocationId == 7 then
        return autoTargetModes["E"]
    end

    -- Sorcerer (base=1, promoted=5) e Druid (base=2, promoted=6): modo J
    if vocationId == 1 or vocationId == 5 or vocationId == 2 or vocationId == 6 then
        return autoTargetModes["J"]
    end

    -- Monk (base=9, promoted=10): modo K
    if vocationId == 9 or vocationId == 10 then
        return autoTargetModes["K"]
    end

    -- Knight (base=4, promoted=8): modo A
    if vocationId == 4 or vocationId == 8 then
        return autoTargetModes["A"]
    end

    -- Default fallback
    return autoTargetModes["F"]
end

