        scheduleEvent(function()
            applyAllIconStatsVisibility()
        end, 100)
    end)

    if not success then
        g_logger.error("[ERROR] Exception initializing Icon Stats Module: " .. tostring(err))
        iconStats = nil
    end

    player = g_game.getLocalPlayer()
    hide()

    -- Carregar configuracoes de auto-load na inicializacao
    loadAutoLoadSettings()

    helper.contentPanel = helper.contentPanel or helper:getChildById("content")
