        }
    )

    Keybind.new("Helper", "Toggle Helper Status", "", "")
    Keybind.bind(
        "Helper",
        "Toggle Helper Status",
        {
            {
                type = KEY_DOWN,
                callback = function()
                    if IconStatsModule and IconStatsModule.onHelperClick then
                        IconStatsModule.onHelperClick()
                    end
                end
            }
        }
    )

    Keybind.new("Helper", "Toggle Auto Follow", "", "")
    Keybind.bind(
        "Helper",
        "Toggle Auto Follow",
        {
            {
                type = KEY_DOWN,
                callback = function()
                    modules.game_helper.toggleAutoFollowHotkey()
                end
            }
        }
    )

    -- Add Helper button to options panel
    -- Disabled: OT Helper button removed from options panel
    -- if modules.game_mainpanel then
    --     modules.game_mainpanel.addToggleButton(
    --         "helperButton",
    --         tr("OT Helper"),
    --         "/images/options/helperDialog",
    --         toggle,
    --         false,
    --         22
    --     )
    -- end

    if g_game.isOnline() then
        online()
    end

    -- Initialize custom spell timer if Magic Shooter is enabled
    if helperConfig.magicShooterEnabled then
        startCustomSpellTimer()
    end

    -- Start external watchdog to monitor cavebot state (com delay para garantir que modulos estejam carregados)
    scheduleEvent(function()
        if modules and modules.game_helper then
            startExternalWatchdog()
        else
            if externalWatchdog.debug then print(
                "[WATCHDOG-EXTERNO] AVISO: Modulo ainda nao carregado, tentando novamente em 5s") end
            scheduleEvent(function()
                if modules and modules.game_helper then
                    startExternalWatchdog()
                end
            end, 5000)
        end
    end, 2000)

    -- Preload heavy disk-bound state at boot/charlist-idle time. This work is
    -- Pré-aquece apenas loadSpellAreas (char-agnostic, lê
    -- /modules/gamelib/player_spells.json com cache interno). NÃO pré-carrega
    -- loadSettings: ele lê /helper/config.json (ou per-char) e como o char ainda
    -- não está logado, sempre cairia no legacy global — config de outro char
    -- vazaria no helperConfig em memória até online() recarregar. online() agora
    -- sempre chama loadSettings com o char correto.
    if not helperConfigPreloadedAtBoot then
        addEvent(function()
            if helperConfigPreloadedAtBoot then return end
            if g_game.isOnline() then return end
            loadSpellAreas()
            helperConfigPreloadedAtBoot = true
        end)
    end
end

local function clearSession()
    -- Limpar completamente a sessão
    helperSessionState.currentCharacter = nil
    helperSessionState.loadedProfile = nil
    helperSessionState.isSessionActive = false
    helperSessionState.dustLimit = nil
    -- Próximo login pode ser outro char: cache de path/nome precisa ser refeito.
    if invalidateHelperConfigPathCache then invalidateHelperConfigPathCache() end
end

function terminate()
    -- Reset preload state so a subsequent module init (hot reload) re-runs
    -- the deferred preload against fresh state.
    helperConfigPreloadedAtBoot = false

    -- Scripting tab: tear down scripts, folder-watch and the debug window.
    if Scripting and Scripting.terminate then
        pcall(Scripting.terminate)
    end

    -- Auto Follow: stop its events and DROP the cached module. auto_follow.lua
    -- caches itself in _G.AutoFollowModule and is only re-dofile'd when that is
    -- nil; terminateAutoFollow() was defined but never called, so on a hot reload
    -- the stale (pre-fix) module stayed pinned and its monitor/follow loops leaked.
    if modules.game_helper.terminateAutoFollow then
        pcall(modules.game_helper.terminateAutoFollow)
    end

    -- Flush pending auto-save and stop the safety-net tick.
    if stopProfileAutosave then
        stopProfileAutosave({ flush = true })
    end
    _G.flushProfileNow        = nil
    _G.armProfileAutosave     = nil
    _G.isProfileAutosaveArmed = nil

    -- Clear modal stack
    modalStack                = {}
    safeSetInputLockWidget(nil)

    -- Stop external watchdog
    stopExternalWatchdog()

    -- Stop lure debug visual
    stopLureDebugVisual()

    -- Cleanup debug popup
    if _G.debugOpacityPopup then
        _G.debugOpacityPopup:destroy()
        _G.debugOpacityPopup = nil
    end
    if debugPopup then
        debugPopup:destroy()
        debugPopup = nil
    end

    -- Limpar sessão ao fechar o cliente
    clearSession()

    CastTiming.terminate()

    disconnect(
        g_game,
        {
            onGameStart = online,
            onGameEnd = offline,
            onSpellCooldown = onSpellCooldown,
            onSpellGroupCooldown = onSpellGroupCooldown,
            onUpdateSpellArea = onUpdateSpellArea,
            onMultiUseCooldown = onMultiUseCooldown,
            onItemClasses = onHelperItemClasses,
            onOpenExaltationForge = onHelperOpenExaltationForge
        }
    )

    if unregisterMessageMode and MessageModes and helperNeedLearnMessageCallback then
        if MessageModes.Failure then unregisterMessageMode(MessageModes.Failure, helperNeedLearnMessageCallback) end
        if MessageModes.Game then unregisterMessageMode(MessageModes.Game, helperNeedLearnMessageCallback) end
        helperNeedLearnMessageCallback = nil
    end

    disconnect(
        Container,
        {
            onUpdateItem = scheduleUpdateAllItemCounts,
            onAddItem = scheduleUpdateAllItemCounts,
            onRemoveItem = scheduleUpdateAllItemCounts
        }
    )

    disconnect(
        Creature,
        {
            onAppear = onCreatureAppear,
            onDisappear = onCreatureDisappear
        }
    )


    if helper then
        g_keyboard.unbindKeyPress("Tab", toggleNextWindow, helper)
        helper:destroy()
        helper = nil
    end

    if presetHotkeyLabelsRefreshEvent then
        removeEvent(presetHotkeyLabelsRefreshEvent)
        presetHotkeyLabelsRefreshEvent = nil
    end
    if presetHotkeyLabelsRefreshRetryEvent then
        removeEvent(presetHotkeyLabelsRefreshRetryEvent)
        presetHotkeyLabelsRefreshRetryEvent = nil
    end

    -- Stop custom spell timer
    stopCustomSpellTimer()

    -- Parar todos os timers agendados
    stopAllTimers()
    stopTimerRuleCooldownOverlayLoop()
    stopSpellRuleCooldownOverlayLoop()

    if helperEvents.helperCycleEvent then
        removeEvent(helperEvents.helperCycleEvent)
        helperEvents.helperCycleEvent = nil
    end

    -- Remove Helper button from top menu
    if modules.game_mainpanel and modules.game_mainpanel.removeToggleButton then
        modules.game_mainpanel.removeToggleButton("helperButton")
    end
end

function toggle(menuId)
    if not helper then
        return
    end

    if helper:isVisible() then
        -- Closing via toggle uses the same save path as hide().
        hide()
    else
        -- Update player reference if needed
        if not player then
            player = g_game.getLocalPlayer()
        end

        helper:show(true)
        helper:raise()
        helper:focus()
        g_keyboard.bindKeyPress("Tab", toggleNextWindow, helper)
        refreshPresetHotkeyLabelsDeferred()

        -- Atualizar visibilidade da aba Friend Menu baseado na vocacao
        updateFriendMenuVisibility()

        -- Se menuId foi fornecido (atalho), usar ele
        -- Se nao, usar a ultima aba salva apenas da sessao atual
        local menuToLoad
        if menuId then
            -- Atalho: usar menu especifico, nao salvar como ultima aba
            menuToLoad = menuId
        else
            -- Abertura normal: usar ultima aba salva da sessao, ou healingMenu como padrao
            menuToLoad = helperSessionState.lastMenu or "healingMenu"
        end

        scheduleEvent(function()
            loadMenu(menuToLoad)
        end, 100)
        g_settings.set('helper_window_open', true)
        g_settings.save()
    end
end

local function saveCurrentMenuState()
    if helper and helper.contentPanel then
        local sideMenu = helper.contentPanel:getChildById("sideMenu")
        if sideMenu then
            local sideMenuButtons = sideMenu:getChildById("sideMenuButtons")
            if sideMenuButtons then
                local buttons = { "healingMenu", "toolsMenu", "huntingMenu", "equipmentMenu", "friendMenu",
                    "profilesMenu", "settingsMenu" }
                for _, menuId in ipairs(buttons) do
                    local button = sideMenuButtons:getChildById(menuId)
                    if button and button:isChecked() then
                        -- Salvar apenas na sessao, nao no arquivo de configuracao
                        helperSessionState.lastMenu = menuId
                        break
                    end
                end
            end
        end
    end
end

function hide()
    if helper then
        -- Save position and current menu before hiding
        local pos = helper:getPosition()
        if pos then
            helperSessionState.lastPosition = { x = pos.x, y = pos.y }
        end

        saveCurrentMenuState()

        -- Auto-save the active profile when the user closes the helper.
        -- The flush is gated on armed + autoSaveProfileEnabled + profile valid,
        -- and a hash gate skips the write when content hasn't changed.
        if flushProfileNow then
            pcall(flushProfileNow, "helper-close")
        end

        g_keyboard.unbindKeyPress("Tab", toggleNextWindow, helper)
        helper:hide()
        -- saveSettings() -- Removido: não salvar automaticamente ao deslogar
        g_settings.set('helper_window_open', false)
        g_settings.save()
    end
end

function show(menuId)
    if helper then
        -- Update player reference if needed
        if not player then
            player = g_game.getLocalPlayer()
        end

        helper:show(true)
        helper:raise()
        helper:focus()
        refreshPresetHotkeyLabelsDeferred()

        -- Restore last position or center if not available
        if helperSessionState.lastPosition then
            helper:setPosition(helperSessionState.lastPosition)
        else
            -- Centralizar a janela na tela
            local rootWidget = g_ui.getRootWidget()
            if rootWidget then
                local screenSize = rootWidget:getSize()
                local helperSize = helper:getSize()
                local centerX = (screenSize.width - helperSize.width) / 2
                local centerY = (screenSize.height - helperSize.height) / 2 + 50 -- Offset para baixo
                helper:setPosition({ x = math.max(0, centerX), y = math.max(50, centerY) })
            end
        end

        g_keyboard.bindKeyPress("Tab", toggleNextWindow, helper)

        -- Se menuId foi fornecido (atalho), usar ele
        -- Se nao, usar a ultima aba salva apenas da sessao atual
        local menuToLoad
        if menuId then
            -- Atalho: usar menu especifico, nao salvar como ultima aba
            menuToLoad = menuId
        else
            -- Abertura normal: usar ultima aba salva da sessao, ou healingMenu como padrao
            menuToLoad = helperSessionState.lastMenu or "healingMenu"
        end

        scheduleEvent(function()
            loadMenu(menuToLoad)
        end, 100)
    end
end

local function isLureDebugEnabled()
    local recorder = nil
    if _G and _G.hunting_recorderModule then
        recorder = _G.hunting_recorderModule
    elseif modules.game_helper and modules.game_helper.hunting_recorderModule then
        recorder = modules.game_helper.hunting_recorderModule
    end

    if recorder and recorder.getCurrentCavebotData then
        local cavebotData = recorder.getCurrentCavebotData()
        return cavebotData and cavebotData.config and cavebotData.config.lureDebug == true
    end
    return false
end

-- External Watchdog Functions
-- Watchdog externo que monitora o estado do cavebot independentemente
-- Roda a cada 3 segundos e verifica se o cavebot deveria estar rodando mas esta parado
local function externalWatchdogCheck()
    -- DEBUG: Print to confirm watchdog is running
    if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] ===== TICK =====") end

    -- Protecao: verificar se esta online
    if not g_game or not g_game.isOnline or not g_game.isOnline() then
        if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Skipping - not online") end
        return
    end

    -- Protecao: verificar se modulos estao carregados
    if not modules or not modules.game_helper then
        if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Skipping - modules not loaded") end
        return
    end

    -- Global helper disabled: keep cavebot runtime paused without changing toggle state.
    if not hotkeyHelperStatus then
        local recorder = hunting_recorderModule or modules.game_helper.hunting_recorderModule
        if recorder and recorder.walking and recorder.stopWalk then
            pcall(function()
                recorder.stopWalk(true)
            end)
        end
        if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Skipping - helper global disabled") end
        return
    end

    -- DEBUG: Log manual stop state
    if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] cavebotManualStop = " .. tostring(_G.cavebotManualStop)) end

    -- Se usuario parou manualmente, nao fazer nada
    if _G.cavebotManualStop then
        if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Skipping - manual stop is true") end
        return
    end

    -- Verificar se o cavebot deveria estar rodando
    local recorder = hunting_recorderModule or modules.game_helper.hunting_recorderModule
    if not recorder then
        return
    end

    -- Protecao: verificar se a funcao existe
    if not recorder.getWindow then
        return
    end

    -- Se tem waypoints carregados e enable esta marcado mas nao esta andando
    local success, huntingWindow = pcall(recorder.getWindow)
    if not success or not huntingWindow then
        return
    end

    local enableCheckbox = huntingWindow:recursiveGetChildById('enableCaveBot')
    if not enableCheckbox then
        if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Skipping - enableCheckbox not found") end
        return
    end

    local isChecked = enableCheckbox:isChecked()

    if externalWatchdog.debug then
        if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] enableCheckbox:isChecked() = " .. tostring(isChecked)) end
    end

    if isChecked then
        -- Enable esta marcado, verificar estado critico
        local needsRestart = false
        local reason = ""
        local isInValidWaitState = false

        -- Verificar se walker esta parado
        local isWalking = recorder.walking or false
        if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] recorder.walking = " .. tostring(isWalking)) end

        -- Verificar estado do cavebotWalker. Watchdog só lê state/currentWaypoint/
        -- totalWaypoints/isActive, então usa getStatus (leve, sem scan de
        -- spectators nem alocação grande); cai p/ getDebugInfo se ausente.
        local statusFn = cavebotWalker and (cavebotWalker.getStatus or cavebotWalker.getDebugInfo)
        if statusFn then
            local ok, debugInfo = pcall(statusFn)
            if ok and debugInfo then
                if externalWatchdog.debug then
                    print(string.format(
                        "[WATCHDOG-EXTERNO] DebugInfo: State=%s WP=%d/%d isActive=%s waiting=%s waitType=%s",
                        tostring(debugInfo.state),
                        tonumber(debugInfo.currentWaypoint or 0),
                        tonumber(debugInfo.totalWaypoints or 0),
                        tostring(debugInfo.isActive),
                        tostring(debugInfo.isWaitingAction),
                        tostring(debugInfo.waitingActionType)))
                end

                -- Verificar se esta em estado de espera valido (nao precisa restart)
                local validWaitStates = {
                    waiting_lure = true,
                    waiting_mobs_stop = true,
                    stop_to_kill = true,
                    deposit_items = true,
                    withdraw_items = true
                }
                if debugInfo.isWaitingAction and debugInfo.waitingActionType and validWaitStates[debugInfo.waitingActionType] then
                    isInValidWaitState = true
                    if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Em estado de espera valido: " ..
                        tostring(debugInfo.waitingActionType)) end
                end

                -- Se esta em estado de espera valido, nao tentar restart
                if not isInValidWaitState then
                    -- Verificar WP invalido (WP deve ser >= 1)
                    local currentWP = tonumber(debugInfo.currentWaypoint or 0)
                    if currentWP == 0 or not debugInfo.currentWaypoint then
                        needsRestart = true
                        if reason ~= "" then reason = reason .. " + " end
                        reason = reason .. "WP=" .. tostring(currentWP)
                    end

                    -- Verificar estado Idle quando deveria estar ativo
                    if debugInfo.state == "Idle" and debugInfo.totalWaypoints and debugInfo.totalWaypoints > 0 then
                        needsRestart = true
                        if reason ~= "" then reason = reason .. " + " end
                        reason = reason .. "State=Idle"
                    end

                    -- Verificar se walker nao esta ativo quando deveria estar
                    if not debugInfo.isActive then
                        needsRestart = true
                        if reason ~= "" then reason = reason .. " + " end
                        reason = reason .. "isActive=false"
                    end

                    -- Verificar se recorder.walking esta false mas walker deveria estar ativo
                    if not isWalking and debugInfo.totalWaypoints and debugInfo.totalWaypoints > 0 then
                        needsRestart = true
                        if reason ~= "" then reason = reason .. " + " end
                        reason = reason .. "walking=false"
                    end
                end
            else
                if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] ERRO ao chamar getDebugInfo: " ..
                    tostring(debugInfo)) end
            end
        else
            if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] cavebotWalker ou getDebugInfo nao disponivel") end
            -- Se cavebotWalker nao existe mas walking deveria estar true, pode precisar restart
            if not isWalking then
                needsRestart = true
                reason = "walking=false + no cavebotWalker"
            end
        end

        if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] needsRestart = " ..
            tostring(needsRestart) .. " | reason = " .. tostring(reason)) end

        if needsRestart and not isInValidWaitState then
            -- Incrementar contador de falhas
            externalWatchdog.failCount = externalWatchdog.failCount + 1
            if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] failCount = " ..
                tostring(externalWatchdog.failCount)) end

            -- So fazer restart se tiver falhas consecutivas suficientes e cooldown passou
            local currentTime = g_clock.millis()
            local timeSinceLastRestart = currentTime - externalWatchdog.lastRestart

            if externalWatchdog.failCount >= externalWatchdog.maxFailCount and timeSinceLastRestart >= externalWatchdog.restartCooldown then
                if externalWatchdog.debug then
                    print("[WATCHDOG-EXTERNO] ===== ESTADO CRITICO DETECTADO =====")
                    print("[WATCHDOG-EXTERNO] Razao: " .. reason)
                    print("[WATCHDOG-EXTERNO] Falhas consecutivas: " .. tostring(externalWatchdog.failCount))
                    print("[WATCHDOG-EXTERNO] Forcando RESTART do cavebot...")
                end

                externalWatchdog.lastRestart = currentTime
                externalWatchdog.failCount = 0

                -- Tentar restart
                scheduleEvent(function()
                    if hotkeyHelperStatus and g_game.isOnline() and enableCheckbox and enableCheckbox:isChecked() then
                        if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Executando stopWalk + startWalk...") end

                        -- Parar primeiro (passando true = restart automatico, nao marca como manual stop)
                        if recorder.stopWalk then
                            pcall(function()
                                recorder.stopWalk(true) -- true = automatic restart
                            end)
                        end

                        -- Aguardar um pouco e reiniciar
                        scheduleEvent(function()
                            if hotkeyHelperStatus and recorder.startWalk and g_game.isOnline() then
                                local ok, err = pcall(recorder.startWalk)
                                if ok then
                                    if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Restart BEM SUCEDIDO!") end
                                else
                                    if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] ERRO ao startar: " ..
                                        tostring(err)) end
                                end
                            end
                        end, 500)
                    end
                end, 100)
            elseif externalWatchdog.debug then
                print(string.format("[WATCHDOG-EXTERNO] Aguardando mais falhas (%d/%d) ou cooldown (%dms restantes)",
                    externalWatchdog.failCount, externalWatchdog.maxFailCount,
                    math.max(0, externalWatchdog.restartCooldown - timeSinceLastRestart)))
            end
        else
            -- Reset contador se tudo esta ok
            if externalWatchdog.failCount > 0 then
                if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Estado OK, resetando failCount") end
                externalWatchdog.failCount = 0
            end
        end
    end
end

-- Declarar como funcoes globais para serem acessiveis em scheduleEvent
startExternalWatchdog = function()
    if externalWatchdog.event then
        removeEvent(externalWatchdog.event)
    end

    local WATCHDOG_INTERVAL = 3000 -- 3 segundos

    local function watchdogLoop()
        -- Proteger contra erros para nao interromper o watchdog
        local success, err = pcall(externalWatchdogCheck)
        if not success then
            if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] ERRO: " .. tostring(err)) end
        end

        -- Reagendar
        externalWatchdog.event = scheduleEvent(watchdogLoop, WATCHDOG_INTERVAL)
    end

    -- Iniciar o loop
    externalWatchdog.event = scheduleEvent(watchdogLoop, WATCHDOG_INTERVAL)
    if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Iniciado - verificando a cada 3 segundos") end
end

stopExternalWatchdog = function()
    if externalWatchdog.event then
        removeEvent(externalWatchdog.event)
        externalWatchdog.event = nil
        if externalWatchdog.debug then print("[WATCHDOG-EXTERNO] Parado") end
    end
end

-- Debug Popup Functions (AreaInfo-style overlay)
-- Helper: get background color based on opacity setting
function getDebugBgColor(opacity)
    if opacity <= 0 then
        return '#00000000'
    else
        local hex = string.format('%02X', math.floor(opacity * 2.55))
        return '#000000' .. hex
    end
end

debugSavePositionTimer = nil

function saveDebugPosition()
    if not debugPopup then return end
    local pos = debugPopup:getPosition()
    _G.debugPopupConfig.x = pos.x
    _G.debugPopupConfig.y = pos.y
    g_settings.set('cavebotDebugX', pos.x)
    g_settings.set('cavebotDebugY', pos.y)
end

function scheduleSaveDebugPosition()
    if debugSavePositionTimer then
        removeEvent(debugSavePositionTimer)
    end
    debugSavePositionTimer = scheduleEvent(function()
        saveDebugPosition()
        debugSavePositionTimer = nil
    end, 500)
end

function isDebugPopupOffScreen(pos)
    if not debugPopup then return false end
    local rw = g_ui.getRootWidget()
    if not rw then return false end
    local screenW, screenH = rw:getWidth(), rw:getHeight()
    local popupSize = debugPopup:getSize()
    local minVisible = 40
    local titleH = 20
    return (pos.x + popupSize.width <= minVisible) or
        (pos.x >= screenW - minVisible) or
        (pos.y + titleH <= 0) or
        (pos.y >= screenH - titleH)
end

function clampDebugPopupPosition(pos)
    if not debugPopup then return pos end
    local rw = g_ui.getRootWidget()
    if not rw then return pos end
    local screenW, screenH = rw:getWidth(), rw:getHeight()
    local popupSize = debugPopup:getSize()
    local minVisible = 40
    local titleH = 20
    return {
        x = math.max(-(popupSize.width - minVisible), math.min(pos.x, screenW - minVisible)),
        y = math.max(0, math.min(pos.y, screenH - titleH))
    }
end

function restoreDebugPosition()
    if not debugPopup then return end
    local x = _G.debugPopupConfig.x
    local y = _G.debugPopupConfig.y

    local savedX = g_settings.getNumber('cavebotDebugX')
    local savedY = g_settings.getNumber('cavebotDebugY')
    if savedX and savedX > 0 then x = savedX end
    if savedY and savedY > 0 then y = savedY end

    local savedOpacity = g_settings.getNumber('cavebotDebugBgOpacity')
    if savedOpacity and savedOpacity >= 0 then
        _G.debugPopupConfig.bgOpacity = savedOpacity
    end

    -- Se nenhuma posicao salva, posicionar no canto direito
    if x <= 0 then
        local rootWidget = g_ui.getRootWidget()
        if rootWidget then
            local screenSize = rootWidget:getSize()
            local popupSize = debugPopup:getSize()
            x = screenSize.width - popupSize.width - 10
        end
    end

    -- Se a posicao restaurada cair fora da tela util, voltar para a default
    if isDebugPopupOffScreen({ x = x, y = y }) then
        local rootWidget = g_ui.getRootWidget()
        if rootWidget then
            local screenSize = rootWidget:getSize()
            local popupSize = debugPopup:getSize()
            x = screenSize.width - popupSize.width - 10
            y = 100
        else
            x, y = 0, 100
        end
        _G.debugPopupConfig.x = 0
        _G.debugPopupConfig.y = 100
        g_settings.set('cavebotDebugX', 0)
        g_settings.set('cavebotDebugY', 100)
    end

    debugPopup:setPosition({ x = x, y = y })
    debugPopup:setBackgroundColor(getDebugBgColor(_G.debugPopupConfig.bgOpacity))
end

function resetDebugPosition()
    g_settings.set('cavebotDebugX', 0)
    g_settings.set('cavebotDebugY', 100)
    _G.debugPopupConfig.x = 0
    _G.debugPopupConfig.y = 100
    if debugPopup then
        restoreDebugPosition()
    end
end

function initDebugPopupWidget()
    if debugPopup then return true end

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then return false end

    debugPopup = g_ui.createWidget('CavebotDebugWindow', rootWidget)
    if not debugPopup then return false end
    applyOpacityToWindow(debugPopup)

    -- Configurar drag handler (salvar posicao ao mover)
    debugPopup.onGeometryChange = function()
        scheduleSaveDebugPosition()
    end

    -- Estado do hover e timer para delay
    local hoverState = false
    local hoverHideTimer = nil

    local function showHoverEffect()
        local dragArea = debugPopup:getChildById('dragArea')
        if not dragArea then return end
        local dragHandle1 = dragArea:getChildById('dragHandle1')
        local dragHandle2 = dragArea:getChildById('dragHandle2')
        local configButton = dragArea:getChildById('configButton')
        if dragHandle1 then dragHandle1:setVisible(true) end
        if dragHandle2 then dragHandle2:setVisible(true) end
        if configButton then configButton:setVisible(true) end
        debugPopup:setBackgroundColor('#000000AA')
    end

    local function hideHoverEffect()
        local dragArea = debugPopup:getChildById('dragArea')
        if not dragArea then return end
        local dragHandle1 = dragArea:getChildById('dragHandle1')
        local dragHandle2 = dragArea:getChildById('dragHandle2')
        local configButton = dragArea:getChildById('configButton')
        if dragHandle1 then dragHandle1:setVisible(false) end
        if dragHandle2 then dragHandle2:setVisible(false) end
        if configButton then configButton:setVisible(false) end
        debugPopup:setBackgroundColor(getDebugBgColor(_G.debugPopupConfig.bgOpacity))
    end

    local function handleHoverChange(hovered)
        if hovered then
            if hoverHideTimer then
                removeEvent(hoverHideTimer)
                hoverHideTimer = nil
            end
            hoverState = true
            showHoverEffect()
        else
            if hoverHideTimer then
                removeEvent(hoverHideTimer)
            end
            hoverHideTimer = scheduleEvent(function()
                hoverState = false
                hideHoverEffect()
                hoverHideTimer = nil
            end, 50)
        end
    end

    -- Hover no window
    debugPopup.onHoverChange = function(widget, hovered)
        handleHoverChange(hovered)
    end

    -- Configurar dragArea para drag manual (mover janela pai)
    local dragArea = debugPopup:getChildById('dragArea')
    if dragArea then
        dragArea.onHoverChange = function(widget, hovered)
            handleHoverChange(hovered)
        end

        local isDragging = false
        local dragStartPos = nil
        local windowStartPos = nil

        dragArea.onMousePress = function(widget, mousePos, button)
            if button == MouseLeftButton then
                isDragging = true
                dragStartPos = mousePos
                windowStartPos = debugPopup:getPosition()
                widget:grabMouse()
                return true
            end
            return false
        end

        dragArea.onMouseRelease = function(widget, mousePos, button)
            if button == MouseLeftButton and isDragging then
                isDragging = false
                dragStartPos = nil
                windowStartPos = nil
                widget:ungrabMouse()
                if debugPopup and not debugPopup:isDestroyed() then
                    local pos = debugPopup:getPosition()
                    if isDebugPopupOffScreen(pos) then
                        resetDebugPosition()
                    end
                end
                return true
            end
            return false
        end

        dragArea.onMouseMove = function(widget, mousePos, mouseMoved)
            if isDragging and dragStartPos and windowStartPos then
                local delta = {
                    x = mousePos.x - dragStartPos.x,
                    y = mousePos.y - dragStartPos.y
                }
                local newPos = {
                    x = windowStartPos.x + delta.x,
                    y = windowStartPos.y + delta.y
                }
                debugPopup:setPosition(clampDebugPopupPosition(newPos))
                return true
            end
            return false
        end

        -- Config button: left-click opens config menu
        local configButton = dragArea:getChildById('configButton')
        if configButton then
            configButton.onMousePress = function(widget, mousePos, button)
                if button == MouseLeftButton then
                    return true
                end
                return false
            end

            configButton.onMouseRelease = function(widget, mousePos, button)
                if button == MouseLeftButton then
                    showDebugOpacityConfig()
                    return true
                end
                return false
            end

            configButton.onHoverChange = function(widget, hovered)
                handleHoverChange(hovered)
            end

            -- Restaurar estado minimizado
            if _G.debugPopupConfig.minimized then
                local contentPanel = debugPopup:getChildById('contentPanel')
                if contentPanel then
                    contentPanel:setVisible(false)
                    debugPopup:setSize({ width = 220, height = 38 })
                end
            end
        end
    end

    -- Restaurar posicao e opacidade
    restoreDebugPosition()
    debugPopup:hide()
    return true
end

function showDebugOpacityConfig()
    if _G.debugOpacityPopup then
        _G.debugOpacityPopup:destroy()
        _G.debugOpacityPopup = nil
    end

    local popup = g_ui.createWidget('HelperPopupMenu')
    _G.debugOpacityPopup = popup

    local opacityLevels = {
        { label = "Transparent", value = 0 },
        { label = "30%",         value = 30 },
        { label = "50%",         value = 50 },
        { label = "70%",         value = 70 },
        { label = "90%",         value = 90 }
    }

    -- Hide/Show option
    local contentPanel = debugPopup and debugPopup:getChildById('contentPanel')
    local isMinimized = contentPanel and not contentPanel:isVisible()
    local hideLabel = isMinimized and "Show Info" or "Hide Info"
    popup:addOption(hideLabel, function()
        if not debugPopup then return end
        local cp = debugPopup:getChildById('contentPanel')
        if not cp then return end
        local minimized = not cp:isVisible()
        if minimized then
            cp:setVisible(true)
            debugPopup:setSize({ width = 220, height = 340 })
        else
            cp:setVisible(false)
            debugPopup:setSize({ width = 220, height = 38 })
        end
        _G.debugPopupConfig.minimized = not minimized
    end)

    -- Reset Profit option
    popup:addOption("Reset Profit", function()
        if hunting_recorderModule and hunting_recorderModule.resetGoldBalanceSession then
            hunting_recorderModule.resetGoldBalanceSession()
        end
    end)

    popup:addSeparator()

    for _, level in ipairs(opacityLevels) do
        local prefix = ""
        if _G.debugPopupConfig.bgOpacity == level.value then
            prefix = "* "
        end
        popup:addOption(prefix .. level.label, function()
            _G.debugPopupConfig.bgOpacity = level.value
            if debugPopup then
                debugPopup:setBackgroundColor(getDebugBgColor(level.value))
            end
            g_settings.set('cavebotDebugBgOpacity', level.value)
        end)
    end

    popup:display()
end

function showDebugPopup()
    if not initDebugPopupWidget() then return end

    if not debugPopup:isVisible() then
        debugPopup:show()
        debugPopup:raise()
    end

    -- Start update event
    if not debugUpdateEvent then
        updateDebugPopup()
        debugUpdateEvent = scheduleEvent(updateDebugPopup, 500)
    end
end

function hideDebugPopup()
    if debugPopup then
        debugPopup:hide()
    end

    if debugUpdateEvent then
        removeEvent(debugUpdateEvent)
        debugUpdateEvent = nil
    end
end

function ensureDebugPopupVisible()
    if debugPopup and debugPopup:isVisible() then return end
    showDebugPopup()
end

function isDebugPopupVisible()
    return debugPopup and debugPopup:isVisible() or false
end

-- Auto show/hide debug popup based on cavebot running state
function updateDebugPopupVisibility()
    if not g_game.isOnline() then
        hideDebugPopup()
        return
    end

    -- Cavebot ligado = _G.cavebotManualStop == false
    local cavebotRunning = not _G.cavebotManualStop
    if cavebotRunning then
        showDebugPopup()
    else
        hideDebugPopup()
    end
end

function updateDebugPopup()
    if not debugPopup or not debugPopup:isVisible() then
        if debugUpdateEvent then
            removeEvent(debugUpdateEvent)
            debugUpdateEvent = nil
        end
        return
    end

    -- Update current time (HH:MM:SS)
    pcall(function()
        local currentTimeLabel = debugPopup:recursiveGetChildById('currentTimeLabel')
        if currentTimeLabel then
            local timeStr = os.date('%H:%M:%S')
            currentTimeLabel:setText('Time: ' .. timeStr)
        end
    end)

    -- Update running time
    pcall(function()
        local runningTimeLabel = debugPopup:recursiveGetChildById('runningTimeLabel')
        if runningTimeLabel then
            if _G.cavebotStartTime and not _G.cavebotManualStop then
                local elapsed = os.time() - _G.cavebotStartTime
                local hours = math.floor(elapsed / 3600)
                local minutes = math.floor((elapsed % 3600) / 60)
                local seconds = elapsed % 60
                runningTimeLabel:setText(string.format('Running Time: %02d:%02d:%02d', hours, minutes, seconds))
            else
                runningTimeLabel:setText('Running Time: 00:00:00')
            end
        end
    end)

    -- Update profit label
    pcall(function()
        local profitLabel = debugPopup:recursiveGetChildById('profitLabel')
        if profitLabel and hunting_recorderModule then
            hunting_recorderModule.updateProfitLabel(profitLabel)
        end
    end)

    if not cavebotWalker or not cavebotWalker.getDebugInfo then
        debugUpdateEvent = scheduleEvent(updateDebugPopup, 500)
        return
    end

    -- Protecao contra crashes durante disconnect
    local success, debugInfo = pcall(cavebotWalker.getDebugInfo)
    if not success or not debugInfo then
        debugUpdateEvent = scheduleEvent(updateDebugPopup, 500)
        return
    end

    -- Update state with color
    local stateLabel = debugPopup:recursiveGetChildById('stateLabel')
    if stateLabel then
        local stateColor = '#c0c0c0'
        if debugInfo.state == 'Walking' then
            stateColor = '#00ff00'
        elseif debugInfo.state == 'Waiting' then
            stateColor = '#ffff00'
        elseif debugInfo.state == 'Luring' then
            stateColor = '#ff8800'
        elseif debugInfo.state == 'Avoiding' then
            stateColor = '#ff3333'
        end
        stateLabel:setText('State: ' .. debugInfo.state)
        stateLabel:setColor(stateColor)
    end

    -- Update waypoint
    local waypointLabel = debugPopup:recursiveGetChildById('waypointLabel')
    if waypointLabel then
        waypointLabel:setText(string.format('WP: %d/%d', debugInfo.currentWaypoint or 0, debugInfo.totalWaypoints or 0))
    end

    -- Update current action name
    local actionLabel = debugPopup:recursiveGetChildById('actionLabel')
    if actionLabel then
        local actionName = debugInfo.currentActionName or '-'
        actionLabel:setText('Action: ' .. actionName)
    end

    -- Update current action value (truncate if too long)
    local actionValueLabel = debugPopup:recursiveGetChildById('actionValueLabel')
    if actionValueLabel then
        local actionValue = debugInfo.currentActionValue or '-'
        if #actionValue > 25 then
            actionValue = actionValue:sub(1, 22) .. '...'
        end
        actionValueLabel:setText('Value: ' .. actionValue)
    end

    -- Update lure mode
    local lureModeLabel = debugPopup:recursiveGetChildById('lureModeLabel')
    if lureModeLabel then
        local lureText = debugInfo.isLureMode and 'ON' or 'OFF'
        local lureColor = debugInfo.isLureMode and '#00ff00' or '#ff0000'
        lureModeLabel:setText('Lure Mode: ' .. lureText)
        lureModeLabel:setColor(lureColor)
    end

    -- Update avoid mode
    local avoidModeLabel = debugPopup:recursiveGetChildById('avoidModeLabel')
    if avoidModeLabel then
        local avoidText = debugInfo.isAvoidMode and 'ON' or 'OFF'
        local avoidColor = debugInfo.isAvoidMode and '#00ff00' or '#ff0000'
        avoidModeLabel:setText('Avoid Mode: ' .. avoidText)
        avoidModeLabel:setColor(avoidColor)
    end

    -- Update avoid details
    local avoidDetailsLabel = debugPopup:recursiveGetChildById('avoidDetailsLabel')
    if avoidDetailsLabel then
        local avoidCount = debugInfo.avoidObstacles or debugInfo.creaturesAround or 0
        avoidDetailsLabel:setText(string.format('Avoid: %d/%d SQM: %d',
            avoidCount,
            debugInfo.creaturesToAvoid or 0,
            debugInfo.trapDistance or 0))
    end

    -- Update mobs on screen
    local mobsOnScreenLabel = debugPopup:recursiveGetChildById('mobsOnScreenLabel')
    if mobsOnScreenLabel then
        mobsOnScreenLabel:setText('Mobs On Screen: ' .. debugInfo.mobsOnScreen)
    end

    -- Update mobs to stop
    local mobsToStopLabel = debugPopup:recursiveGetChildById('mobsToStopLabel')
    if mobsToStopLabel then
        mobsToStopLabel:setText('Mobs To Stop: ' .. debugInfo.mobsToStop)
    end

    -- Update mobs to walk
    local mobsToWalkLabel = debugPopup:recursiveGetChildById('mobsToWalkLabel')
    if mobsToWalkLabel then
        mobsToWalkLabel:setText('Mobs To Walk: ' .. debugInfo.mobsToWalk)
    end

    -- Update waiting mobs
    local waitingMobsLabel = debugPopup:recursiveGetChildById('waitingMobsLabel')
    if waitingMobsLabel then
        waitingMobsLabel:setText('Waiting Mobs: ' .. debugInfo.waitingMobs)
    end

    -- Update ignored mobs
    local ignoredMobsLabel = debugPopup:recursiveGetChildById('ignoredMobsLabel')
    if ignoredMobsLabel then
        ignoredMobsLabel:setText('Ignored Mobs: ' .. (debugInfo.ignoredMobs or 0))
    end

    -- Schedule next update
    debugUpdateEvent = scheduleEvent(updateDebugPopup, 500)
end

function helperCycleEvent()
    -- Skip entirely when helper is disabled to avoid unnecessary CPU usage
    if not hotkeyHelperStatus then
        return
    end
    if not g_game.isOnline() then
        return
    end
    local player = g_game.getLocalPlayer()
    if not player then
        return
    end
    if not helperConfig then
        return
    end

    -- A cada 1s verificar se entrou em area restrita e desligar cavebot
    if helperEvents and (g_clock.millis() - (helperEvents.restrictedAreaLastCheck or 0)) >= 1000 then
        helperEvents.restrictedAreaLastCheck = g_clock.millis()
        disableCavebotIfInRestrictedArea()
    end

    -- A cada 1s reforcar Force Presets do cavebot (Targeting / Magic Shooter)
    if helperEvents and (g_clock.millis() - (helperEvents.forcePresetLastCheck or 0)) >= 1000 then
        helperEvents.forcePresetLastCheck = g_clock.millis()
        pcall(enforceCavebotForcePresets)
    end

    -- Begin time-budgeted cycle
    helperEvents.cycleStartTime = g_clock.millis()
    helperEvents.tasksThisCycle = 0
    helperEvents.shooterPotionHoldForRunePeek = false

    -- Process events by priority: critical first, then normal, then heavy with budget
    -- OPTIMIZATION: Reuse pre-allocated tables instead of creating new ones every cycle
    local criticalEvents = _criticalEvents
    local normalEvents = _normalEvents
    local heavyEvents = _heavyEvents
    -- Clear bucket counters (reuse memory, no GC)
    local nCritical, nNormal, nHeavy = 0, 0, 0

    -- OPTIMIZATION: Initialize pool on first run (lazy init)
    if _eventEntryPoolSize == 0 then initEventEntryPool() end

    -- Iterate pre-built pool instead of pairs(eventTable) — avoids hash traversal
    for i = 1, _eventEntryPoolSize do
        local entry = _eventEntryPool[i]
        local eventName = entry.name
        if timers[eventName] then
            timers[eventName] = timers[eventName] + helperEvents.helperCycleTimer
            if timers[eventName] >= entry.data.interval then
                local priority = helperEvents.eventPriority[eventName] or "normal"
                if priority == "critical" then
                    nCritical = nCritical + 1
                    criticalEvents[nCritical] = entry
                elseif priority == "heavy" then
                    nHeavy = nHeavy + 1
                    heavyEvents[nHeavy] = entry
                else
                    nNormal = nNormal + 1
                    normalEvents[nNormal] = entry
                end
            end
        end
    end
    -- Trim excess from previous cycle
    for i = nCritical + 1, #criticalEvents do criticalEvents[i] = nil end
    for i = nNormal + 1, #normalEvents do normalEvents[i] = nil end
    for i = nHeavy + 1, #heavyEvents do heavyEvents[i] = nil end

    for i = 1, nNormal do
        if normalEvents[i].name == "checkMagicShooter" then
            helperEvents.shooterPotionHoldForRunePeek = magicShooterPeekHoldPotionBeforePrioritizedRune()
            break
        end
    end

    -- Helper function to execute an event
    local function executeEvent(eventName, eventData)
        timers[eventName] = 0
        local func = eventData.action
        if func and type(func) == "function" then
            local ok, err = pcall(func, player)
            if not ok and err then
                -- Avoid error loops - only print error once per minute per event
                local errorKey = eventName .. "_error"
                local lastError = timers[errorKey] or 0
                if g_clock.millis() - lastError > 60000 then
                    pwarning("[helperCycleEvent] erro em " .. eventName .. ": " .. tostring(err))
                    timers[errorKey] = g_clock.millis()
                end
            end
        end
    end

    -- Check if we have time budget for heavy tasks
    local function hasTimeBudget()
        local elapsed = g_clock.millis() - helperEvents.cycleStartTime
        return elapsed < helperEvents.maxTimePerCycle and helperEvents.tasksThisCycle < helperEvents.maxTasksPerCycle
    end

    -- prioritizeOverPotion is a potion-only inhibitor: shooterPotionHoldForRunePeek
    -- (set above) blocks usePotion/castHealingRuleItem in the critical heal pass.
    -- Healing spells stay un-gated, so we run criticals first and let the shooter
    -- fire as a normal event afterwards — same cycle, without delaying heal cast.

    -- 1. Always run critical events (health/mana - fast and essential)
    for _, event in ipairs(criticalEvents) do
        executeEvent(event.name, event.data)
    end

    -- 2. Run normal events
    for _, event in ipairs(normalEvents) do
        executeEvent(event.name, event.data)
    end

    -- 3. Run heavy events only if we have time budget
    -- Process any deferred events first (from previous cycles)
    local pendingHeavy = {}
    for _, event in ipairs(helperEvents.deferredEvents) do
        table.insert(pendingHeavy, event)
    end
    helperEvents.deferredEvents = {}

    -- Add new heavy events
    for _, event in ipairs(heavyEvents) do
        table.insert(pendingHeavy, event)
    end

    -- Process heavy events with budget
    for _, event in ipairs(pendingHeavy) do
        if hasTimeBudget() then
            executeEvent(event.name, event.data)
            helperEvents.tasksThisCycle = helperEvents.tasksThisCycle + 1
        else
            -- Defer to next cycle, but don't let events pile up too much
            if #helperEvents.deferredEvents < 4 then
                table.insert(helperEvents.deferredEvents, event)
            else
                -- Force execute to prevent starvation
                executeEvent(event.name, event.data)
            end
        end
    end

    -- End cycle
    helperEvents.cycleStartTime = 0

    -- F1.2: refresh dirty flag a cada ~1s (throttled internamente).
    -- Calculo de fingerprint do helperConfig fica abaixo de 1ms em configs tipicas.
    if recomputeProfileDirty then
        pcall(recomputeProfileDirty)
    end
end

-- Alarm system functions (removidas duplicatas - funcoes ja definidas acima)

function updateFriendMenuVisibility()
    if not player or not helper then
        return
    end

    local vocationId = translateVocation(player:getVocation())
    local sideMenu = helper.contentPanel and helper.contentPanel:getChildById("sideMenu")
    local sideMenuButtons = sideMenu and sideMenu:getChildById("sideMenuButtons")
    local friendMenuButton = sideMenuButtons and sideMenuButtons:getChildById("friendMenu")

    if friendMenuButton then
        -- Mostrar aba para: Druid, Sorcerer, Paladin e Monk
        if vocationId == VOCATION_DRUID or vocationId == VOCATION_SORCERER or
            vocationId == VOCATION_PALADIN or vocationId == VOCATION_MONK then
            friendMenuButton:setVisible(true)
            friendMenuButton:setEnabled(true)
        else
            -- Esconder apenas para Knight
            friendMenuButton:setVisible(false)
            friendMenuButton:setEnabled(false)
        end
    end
end

function modules.game_helper.selectHealingSubTab(tabId)
    local selectedTab = tostring(tabId or "healing")
    local validTabs = {
        healing = true,
        magicShield = true,
        energyRing = true
    }

    if not validTabs[selectedTab] then
        selectedTab = "healing"
    end
    helperSessionState.lastHealingSubTab = selectedTab

    if not healingPanel then
        return
    end

    -- Content panels visibility
    local healingPresetsContent = healingPanel:getChildById("healingPresetsPanel")
    local healingContent = healingPanel:getChildById("healingPanel")
    local shieldContent = healingPanel:getChildById("shieldHelperPanel")
    local energyRingContent = healingPanel:getChildById("energyRingPanel")

    local showHealing = selectedTab == "healing"
    local showMagicShield = selectedTab == "magicShield"
    local showEnergyRing = selectedTab == "energyRing"

    if healingPresetsContent then
        healingPresetsContent:setVisible(showHealing)
    end
    if healingContent then
        healingContent:setVisible(showHealing)
    end
    if shieldContent then
        shieldContent:setVisible(showMagicShield)
    end
    if energyRingContent then
        energyRingContent:setVisible(showEnergyRing)
    end

    -- Update tab button checked states
    local tabButtons = {
        healing = "healingSubTabHealing",
        magicShield = "healingSubTabMagicShield",
        energyRing = "healingSubTabEnergyRing"
    }
    for tabName, buttonId in pairs(tabButtons) do
        local button = healingPanel:recursiveGetChildById(buttonId)
        if button then
            local isActive = tabName == selectedTab
            button:setChecked(isActive)
            markActiveButton(button, isActive)
        end
    end
end

function modules.game_helper.selectToolsSubTab(tabId)
    local selectedTab = tostring(tabId or "toolsHelper")
    local validTabs = {
        toolsHelper = true,
        party = true,
        extras = true,
        timer = true,
        alarms = true
    }

    if not validTabs[selectedTab] then
        selectedTab = "toolsHelper"
    end
    helperSessionState.lastToolsSubTab = selectedTab

