        return
    end

    local toolsHelperContent = toolsPanel:getChildById("toolsPanel")
    local partyContent = toolsPanel:getChildById("PartyManagementPanel")
    local extrasContent = toolsPanel:getChildById("SpyFollowPanel")
    local equipContent = toolsPanel:getChildById("equipPanel")
    local timerContent = toolsPanel:getChildById("timerPanel")
    local alarmsContent = toolsPanel:getChildById("alarmsPanel")

    local showToolsHelper = selectedTab == "toolsHelper"
    local showParty = selectedTab == "party"
    local showExtras = selectedTab == "extras"
    local showTimer = selectedTab == "timer"
    local showAlarms = selectedTab == "alarms"

    if toolsHelperContent then
        toolsHelperContent:setVisible(showToolsHelper)
    end
    if partyContent then
        partyContent:setVisible(showParty)
    end
    if extrasContent then
        extrasContent:setVisible(showExtras)
    end
    if equipContent then
        equipContent:setVisible(showToolsHelper and FULLHELPER)
    end
    if timerContent then
        timerContent:setVisible(showTimer)
    end
    if alarmsContent then
        alarmsContent:setVisible(showAlarms)
    end

    local tabButtons = {
        toolsHelper = "toolsSubTabToolsHelper",
        party = "toolsSubTabParty",
        extras = "toolsSubTabExtras",
        timer = "toolsSubTabTimer",
        alarms = "toolsSubTabAlarms"
    }
    for tabName, buttonId in pairs(tabButtons) do
        local button = toolsPanel:recursiveGetChildById(buttonId)
        if button then
            local isActive = tabName == selectedTab
            button:setChecked(isActive)
            markActiveButton(button, isActive)
        end
    end

    if showTimer then
        initializeTimers()
    end
end

function modules.game_helper.selectSettingsSubTab(tabId)
    local selectedTab = tostring(tabId or "general")
    if selectedTab ~= "general" and selectedTab ~= "iconStats" and selectedTab ~= "engine" then
        selectedTab = "general"
    end
    helperSessionState.lastSettingsSubTab = selectedTab

    if not settingsPanel then
        return
    end

    local generalContent = settingsPanel:recursiveGetChildById("settingsGeneralContent")
    local iconStatsContent = settingsPanel:recursiveGetChildById("settingsIconStatsContent")
    local engineContent = settingsPanel:recursiveGetChildById("settingsEngineContent")

    local showGeneral = selectedTab == "general"
    local showIconStats = selectedTab == "iconStats"
    local showEngine = selectedTab == "engine"

    if generalContent then
        generalContent:setVisible(showGeneral)
    end
    if iconStatsContent then
        iconStatsContent:setVisible(showIconStats)
    end
    if engineContent then
        if not showEngine and engineContent:isVisible() then
            for _, def in ipairs(ENGINE_INTERVAL_DEFS) do
                local input = settingsPanel:recursiveGetChildById("engineInput_" .. def.kind)
                if input then
                    modules.game_helper.commitEngineIntervalInput(input, def.kind)
                end
            end
            local leadInput = settingsPanel:recursiveGetChildById("castTimingLeadInput")
            if leadInput then
                modules.game_helper.commitCastTimingLeadInput(leadInput)
            end
        end
        engineContent:setVisible(showEngine)
        if showEngine then
            refreshEngineSettingsUI()
        end
    end

    local tabButtons = {
        general = "settingsSubTabGeneral",
        iconStats = "settingsSubTabIconStats",
        engine = "settingsSubTabEngine"
    }
    for tabName, buttonId in pairs(tabButtons) do
        local button = settingsPanel:recursiveGetChildById(buttonId)
        if button then
            local isActive = tabName == selectedTab
            button:setChecked(isActive)
            markActiveButton(button, isActive)
        end
    end
end

local function getEngineInputForKind(kind)
    if not settingsPanel then return nil end
    return settingsPanel:recursiveGetChildById("engineInput_" .. kind)
end

function refreshEngineSettingsUI()
    if not settingsPanel then return end
    for _, def in ipairs(ENGINE_INTERVAL_DEFS) do
        local input = getEngineInputForKind(def.kind)
        if input then
            input:setText(tostring(getEngineIntervalValue(def.kind)))
        end
    end
    refreshCastTimingSettingsUI()
end

function modules.game_helper.setEngineInterval(kind, value)
    if not _engineDefByKind[kind] then return end
    helperConfig.engineIntervals = helperConfig.engineIntervals or {}
    helperConfig.engineIntervals[kind] = clampEngineInterval(value, kind)
    applyEngineIntervalsFromConfig()
    saveSettings()
    if armProfileAutosave and not helperSessionState.loadedProfileReadOnly then armProfileAutosave() end
end

function modules.game_helper.handleEngineKeyPress(widget, kind, keyCode)
    if keyCode == nil then return end
    if (KeyEnter and keyCode == KeyEnter) or (KeyReturn and keyCode == KeyReturn) then
        modules.game_helper.commitEngineIntervalInput(widget, kind)
    end
end

function modules.game_helper.commitEngineIntervalInput(widget, kind)
    if not widget then return end
    local def = _engineDefByKind[kind]
    if not def then return end
    local text = widget:getText() or ""
    local n = tonumber(text)
    if not n then n = def.default end
    local clamped = clampEngineInterval(n, kind)
    widget:setText(tostring(clamped))
    modules.game_helper.setEngineInterval(kind, clamped)
end

function modules.game_helper.onEngineIntervalTextChanged(widget, kind)
    if not widget then return end
    if not _engineDefByKind[kind] then return end
    local n = tonumber(widget:getText() or "")
    if not n then return end
    helperConfig.engineIntervals = helperConfig.engineIntervals or {}
    helperConfig.engineIntervals[kind] = clampEngineInterval(n, kind)
    applyEngineIntervalsFromConfig()
    if armProfileAutosave and not helperSessionState.loadedProfileReadOnly then armProfileAutosave() end
end

-- ===== Reactive Cast Timing settings (cast_timing.lua engine) =====

function getCastTimingConfig()
    helperConfig.castTiming = helperConfig.castTiming or {}
    local conf = helperConfig.castTiming
    if conf.enabled == nil then conf.enabled = true end
    local pct = tonumber(conf.leadPct) or 90
    if pct < 0 then pct = 0 end
    if pct > 100 then pct = 100 end
    conf.leadPct = pct
    return conf
end

function applyCastTimingFromConfig()
    if not helperConfig then return end
    CastTiming.configure(getCastTimingConfig())
end

function refreshCastTimingSettingsUI()
    if not settingsPanel then return end
    local conf = getCastTimingConfig()
    local checkbox = settingsPanel:recursiveGetChildById("castTimingEnabled")
    if checkbox then
        checkbox:setChecked(conf.enabled == true)
    end
    local input = settingsPanel:recursiveGetChildById("castTimingLeadInput")
    if input then
        input:setText(tostring(conf.leadPct))
    end
end

function modules.game_helper.onCastTimingEnabledChange(checked)
    local conf = getCastTimingConfig()
    conf.enabled = checked == true
    applyCastTimingFromConfig()
    saveSettings()
    if armProfileAutosave and not helperSessionState.loadedProfileReadOnly then armProfileAutosave() end
end

function modules.game_helper.commitCastTimingLeadInput(widget)
    if not widget then return end
    local conf = getCastTimingConfig()
    local n = tonumber(widget:getText() or "")
    if not n then n = 90 end
    if n < 0 then n = 0 end
    if n > 100 then n = 100 end
    widget:setText(tostring(n))
    conf.leadPct = n
    applyCastTimingFromConfig()
    saveSettings()
    if armProfileAutosave and not helperSessionState.loadedProfileReadOnly then armProfileAutosave() end
end

function modules.game_helper.handleCastTimingLeadKeyPress(widget, keyCode)
    if keyCode == nil then return end
    if (KeyEnter and keyCode == KeyEnter) or (KeyReturn and keyCode == KeyReturn) then
        modules.game_helper.commitCastTimingLeadInput(widget)
    end
end

function modules.game_helper.selectEquipmentSubTab(tabId)
    local selectedTab = tostring(tabId or "equipments")
    if selectedTab ~= "equipments" and selectedTab ~= "tankMode" then
        selectedTab = "equipments"
    end
    helperSessionState.lastEquipmentSubTab = selectedTab

    if not equipmentPanel then
        return
    end

    local presetsPanel = equipmentPanel:getChildById("equipmentPresetsPanel")
    local swapPanel = equipmentPanel:getChildById("equipmentSwapPanel")
    local tankPanel = equipmentPanel:getChildById("tankModePanel")

    local showEquipments = selectedTab == "equipments"
    local showTank = selectedTab == "tankMode"

    if presetsPanel then presetsPanel:setVisible(showEquipments) end
    if swapPanel then swapPanel:setVisible(showEquipments) end
    if tankPanel then tankPanel:setVisible(showTank) end

    local tabButtons = {
        equipments = "equipmentSubTabEquipments",
        tankMode = "equipmentSubTabTankMode"
    }
    for tabName, buttonId in pairs(tabButtons) do
        local button = equipmentPanel:recursiveGetChildById(buttonId)
        if button then
            local isActive = tabName == selectedTab
            button:setChecked(isActive)
            markActiveButton(button, isActive)
        end
    end
end

function modules.game_helper.selectHuntingSubTab(tabId)
    local selectedTab = tostring(tabId or "targeting")
    local validTabs = {
        targeting = true,
        shooter = true,
        cavebot = true
    }

    if not validTabs[selectedTab] then
        selectedTab = "targeting"
    end
    helperSessionState.lastHuntingSubTab = selectedTab

    if not huntingPanel then
        return
    end

    local player = g_game.getLocalPlayer()
    local vocationId = 0
    if player then
        vocationId = translateVocation(player:getVocation())
    end

    -- Hide all hunting sub-panels
    if targetingPanel then targetingPanel:setVisible(false) end
    if shooterPanel then shooterPanel:setVisible(false) end
    if cavePanel then cavePanel:setVisible(false) end

    -- Show selected panel
    if selectedTab == "targeting" then
        if targetingPanel then targetingPanel:setVisible(true) end

        -- Hide all vocation panels first
        if knightHelperPanel then knightHelperPanel:setVisible(false) end
        if mageHelperPanel then mageHelperPanel:setVisible(false) end
        if paladinHelperPanel then paladinHelperPanel:setVisible(false) end
        if monkHelperPanel then monkHelperPanel:setVisible(false) end

        -- Show only the current vocation panel
        if vocationId == VOCATION_KNIGHT and knightHelperPanel then
            knightHelperPanel:setVisible(true)
        elseif vocationId == VOCATION_SORCERER and mageHelperPanel then
            mageHelperPanel:setVisible(true)
        elseif vocationId == VOCATION_PALADIN and paladinHelperPanel then
            paladinHelperPanel:setVisible(true)
        elseif vocationId == VOCATION_MONK and monkHelperPanel then
            monkHelperPanel:setVisible(true)
        end

        -- Set default maxTargetDistance if not already set
        if not helperConfig.maxTargetDistance or helperConfig.maxTargetDistance == 0 then
            helperConfig.maxTargetDistance = 7
        end

        -- Update the UI field
        local maxDistanceInput = targetingPanel and targetingPanel:recursiveGetChildById("maxTargetDistanceInput")
        if maxDistanceInput then
            maxDistanceInput:setText(tostring(helperConfig.maxTargetDistance or 7))
        end

        -- Update prioritize boss checkbox
        local prioritizeBossCheckBox = targetingPanel and targetingPanel:recursiveGetChildById("prioritizeBossCheckBox")
        if prioritizeBossCheckBox then
            prioritizeBossCheckBox:setChecked(helperConfig.prioritizeBoss ~= false)
        end
    elseif selectedTab == "shooter" then
        if shooterPanel then
            resetMenu(shooterPanel)
            shooterPanel:setVisible(true)
        end

        rebuildAllShooterRules()

        if shooterPanel and vocationId then
            viewMenu(shooterPanel, vocationId)
        end

        -- Refresh shooter preset hotkey labels
        refreshIconStatsKeyLabels()
    elseif selectedTab == "cavebot" then
        if cavePanel then cavePanel:setVisible(true) end
    end

    -- Update tab button checked states
    local tabButtons = {
        targeting = "huntingSubTabTargeting",
        shooter = "huntingSubTabShooter",
        cavebot = "huntingSubTabCavebot"
    }
    for tabName, buttonId in pairs(tabButtons) do
        local button = huntingPanel:recursiveGetChildById(buttonId)
        if button then
            local isActive = tabName == selectedTab
            button:setChecked(isActive)
            markActiveButton(button, isActive)
        end
    end
end

function online()
    if _G.LoginProfiler then _G.LoginProfiler.mark("game_helper online() begin") end

    local benchmark = _G.profileHelperModule and g_clock.millis() or 0
    local lastStep = benchmark
    local function logStep(name)
        if not _G.profileHelperModule then return end
        local now = g_clock.millis()
        local elapsed = now - lastStep
        if elapsed > (_G.profileThresholdMs or 50) then
            g_logger.warning(string.format("[HELPER PROFILE] %s: %dms", name, elapsed))
        end
        lastStep = now
    end

    player = g_game.getLocalPlayer()
    monkVirtueMode = nil
    monkVirtuePendingMode = nil
    monkVirtuePendingUntil = 0

    -- Initialize alarm state
    if player then
        alarmState.lastHealth = player:getHealth()
        alarmState.disconnectedDetected = false
        alarmState.playerAttackDetected = false
    end

    -- Load spell areas from player_spells.json
    loadSpellAreas()
    logStep("loadSpellAreas")

    -- Real vocation (extended opcode 206): the login protocol can't tell a Titan Knight
    -- from an Elite Knight (both send client-id 11), so register the reply handler, reset
    -- the cached id, and ask the server. The answer sizes the Titan's larger exori gran AoE.
    helperRealVocationId = nil
    pcall(function() ProtocolGame.unregisterExtendedOpcode(REAL_VOCATION_OPCODE) end)
    ProtocolGame.registerExtendedOpcode(REAL_VOCATION_OPCODE, onHelperRealVocation)
    scheduleEvent(requestRealVocation, 1000)
    logStep("requestRealVocation")

    -- Auto Follow PathSharing (extended opcode 220): register the cross-floor relay
    -- handler EAGERLY so this player can be FOLLOWED (become a leader) even before
    -- ever opening Auto Follow. Without it, a leader who never touched Auto Follow
    -- would drop the follower's subscribe packet and Via A (teleport/stairs following)
    -- silently wouldn't work. initAutoFollow() loads the module; getPathSharing() runs
    -- PathSharing.init(), which re-registers the opcode on each login (idempotent).
    modules.game_helper.initAutoFollow()
    if _G.AutoFollowModule and _G.AutoFollowModule.getPathSharing then
        pcall(function() _G.AutoFollowModule.getPathSharing() end)
    end
    logStep("initPathSharing")

    -- Ensure helperConfig is initialized
    if not helperConfig then
        pwarning("helperConfig not initialized, using defaults")
        return
    end

    -- Re-apply the Magic Shield Helper icons now that we are online. init() runs
    -- during loadModules, BEFORE appearances.dat is loaded, so setItemId(35563)
    -- on the Magic Potion slot resolved against an empty dat table (isValidDatId
    -- false) and got zeroed, leaving the slot blank. By online() the dat is loaded,
    -- so re-running the setup binds a valid client id. Idempotent for the spell icons.
    setupShieldHelperSpellIcons()

    -- Bind ESC to cancel hold attack target (must run before snapshot-restore early return below)
    local gameRootPanel = modules.game_interface and modules.game_interface.getRootPanel()
    if gameRootPanel then
        g_keyboard.bindKeyDown("Escape", handleHoldAttackEscapeKey, gameRootPanel)
    end

    local characterName = player:getName()

    -- Continuidade de sessao ao relogar (queda/!fps): o estado vivo dos toggles de
    -- automacao sobrevive em memoria (offline() nao limpa helperConfig). Capturamos a
    -- intencao AGORA -- antes de snapshot/reset/profile mexerem em helperConfig -- para
    -- religar cavebot/shooter/targeting no fim, independente do caminho de login. So
    -- vale para o MESMO char (estado de outro char nao deve vazar no relog).
    local relogSameChar = helperSessionState.currentCharacter == characterName
    local relogWanted = relogSameChar and {
        cavebot = helperConfig.cavebotHelperEnabled == true,
        shooter = helperConfig.magicShooterEnabled == true,
        target  = helperConfig.autoTargetEnabled == true,
    } or nil

    -- CASO 1: MESMO PERSONAGEM RELOGANDO COM SNAPSHOT VÁLIDO
    -- Apenas restaurar snapshot se auto-load estiver habilitado
    -- Se auto-load estiver desabilitado, sempre abrir profile em branco
    if helperSessionState.isSessionActive and
        helperSessionState.currentCharacter == characterName and
        helperSessionState.hasValidSnapshot and
        helperSessionSnapshot and
        helperSessionSnapshot.characterName == characterName then
        -- Carregar apenas metadados do config.json (sem resetar)
        loadSettingsMinimal()

        -- Verificar se auto-load está habilitado antes de restaurar snapshot
        if helperConfig.autoLoadProfileEnabled ~= true then
            -- Auto-load desabilitado: limpar snapshot e continuar para login normal
            clearSessionSnapshot()
            -- Fallthrough para login normal com profile em branco
        elseif restoreSessionSnapshot() then
            -- Recarregar UI com os dados restaurados
            scheduleEvent(function()
                isLoadingAlarmData = true
                onLoadHelperData()
            end, 50)

            -- Restart helper cycle
            if not helperEvents.helperCycleEvent then
                helperEvents.helperCycleEvent = cycleEvent(helperCycleEvent, helperEvents.helperCycleTimer or 100)
            end

            -- Restaurar hotkeyHelperStatus (necessario para timers e demais funcoes)
            hotkeyHelperStatus = true
            _G.hotkeyHelperStatus = hotkeyHelperStatus

            -- Restart timer execution loop se houver timers ativos
            if helperConfig.timerEnabled and hasActiveTimerRules() then
                startTimerExecutionLoop()
            end

            -- Show icon stats if enabled
            if IconStatsModule and IconStatsModule.onLogin then
                IconStatsModule.onLogin()
            end

            modules.game_textmessage.displayGameMessage("Session restored for " .. characterName)

            startProfileAutosave()
            -- Snapshot carries the previously-loaded profile data, so we
            -- can auto-save again from this session.
            if armProfileAutosave and helperSessionState.loadedProfile and helperSessionState.loadedProfile ~= ""
                and not helperSessionState.loadedProfileReadOnly then
                armProfileAutosave()
            end

            -- Relog: religa cavebot/shooter/targeting (le helperConfig, ja restaurado
            -- pelo snapshot). Delay para rodar depois de onLoadHelperData/syncUIWithConfig
            -- e do resume automatico do cavebot (onGameStart do recorder, ~500ms).
            scheduleEvent(function() reapplyAutomationAfterRelog() end, 700)

            if _G.LoginProfiler then _G.LoginProfiler.mark("game_helper online() end (snapshot-restore path)") end
            return
        else
            -- Fallthrough para login normal
        end
    end

    -- CASO 2: PERSONAGEM DIFERENTE OU SEM SNAPSHOT - FAZER LOGIN COMPLETO
    -- Limpar sessão anterior
    helperSessionState.currentCharacter = characterName
    helperSessionState.loadedProfile = nil
    helperSessionState.loadedProfileReadOnly = false
    helperSessionState.isSessionActive = false

    -- Limpar snapshot antigo (personagem diferente)
    clearSessionSnapshot()
    logStep("clearSessionSnapshot")

    reset()
    logStep("reset")

    -- First login since boot? init() already populated helperConfig from
    -- /helper/config.json via the deferred preload. Skip the redundant ~70-120ms
    -- rebuild + disk read. Re-logins after this point flip the flag back and
    -- go through the full loadSettings path so file edits made mid-session
    -- (autosave, manual config edits) are picked up.
    -- Boot preload no longer loads helper config (only spell areas), so
    -- loadSettings() must always run here with the now-known char name.
    -- This guarantees a fresh read from the per-char file (or legacy on
    -- first session) without carrying stale data from another char.
    helperConfigPreloadedAtBoot = false
    loadSettings()
    logStep("loadSettings")
    loadProfileOptions()
    logStep("loadProfileOptions")

    -- Auto carregar profile ao logar
    -- Auto-load profile apenas se estiver explicitamente habilitado
    if helperConfig.autoLoadProfileEnabled == true then
        -- IMPORTANTE: Neste ponto, estamos em uma NOVA SESSÃO (não é restore de snapshot)
        -- O loadSettings() já resetou tudo, então SEMPRE devemos recarregar o profile
        -- A lógica de "mesmo personagem sem recarregar" só se aplica ao restore de snapshot acima

        local profileToLoad = nil

        -- Vocation auto-load was removed; always load by character name.
        do
            -- Buscar na lista de profiles carregados
            if helperConfig.profiles then
                for profileName, _ in pairs(helperConfig.profiles) do
                    if profileName == characterName then
                        profileToLoad = profileName
                        break
                    end
                end
            end

            -- Se nao encontrou, tentar carregar do arquivo
            if not profileToLoad then
                local profileFile = "/helper/profiles/" .. characterName .. ".json"
                if g_resources.fileExists(profileFile) then
                    profileToLoad = characterName
                end
            end
        end

        if profileToLoad then
            -- Carregar profile do arquivo
            local profile = loadProfileFromFile(profileToLoad)
            if profile then
                helperConfig.selectedProfile = profileToLoad
                helperConfig.profiles[profileToLoad] = profile

                -- Sobrepor TODAS as configs do helper com as do profile
                for k, v in pairs(profile) do
                    if k ~= "profiles" and k ~= "selectedProfile" and k ~= "autoLoadProfileEnabled" and
                        k ~= "autoLoadProfileType" and k ~= "holdAttackTargetId" and k ~= "holdAttackTargetName" and
                        k ~= "iconStats" then
                        helperConfig[k] = deepCopy(v)
                    end
                end

                ensureHealingSlots(helperConfig)
                ensureEquipmentSwapConfig(EQUIPMENT_SWAP_DEFAULT_SLOT_COUNT)
                ensureTimerConfig(TIMER_DEFAULT_RULE_COUNT)

                -- Load condition settings from profile
                if profile.conditionSettings and modules.game_healthcircle and modules.game_healthcircle.importConditionSettings then
                    modules.game_healthcircle.importConditionSettings(profile.conditionSettings)
                end

                -- Guardar nome do personagem que carregou este profile
                helperConfig.lastProfileLoadedByCharacter = characterName

                -- Registrar sessão ativa
                helperSessionState.currentCharacter = characterName
                helperSessionState.loadedProfile = profileToLoad
                helperSessionState.isSessionActive = true

                -- F3.1: profiles "global-*" (template de vocacao) sao
                -- COMPARTILHADOS entre todos os chars da mesma vocacao.
                -- Armar autosave aqui faria o ultimo char a deslogar
                -- sobrescrever o trabalho dos outros. Mantemos como template
                -- read-only ate o usuario clicar Save explicitamente.
                local isVocationTemplate = type(profileToLoad) == "string"
                    and profileToLoad:sub(1, 7) == "global-"
                if isVocationTemplate then
                    pcall(function()
                        g_logger.info(_profileSaveInfo.prefix ..
                            " loaded trigger=autoload-vocation profile=" .. tostring(profileToLoad) ..
                            " mode=template-readonly")
                        modules.game_textmessage.displayGameMessage(
                            "Vocation profile loaded (shared template). Click Save to commit changes.")
                    end)
                    -- NAO arma autosave para nao escrever por cima do template.
                    helperSessionState.loadedProfileReadOnly = true
                else
                    helperSessionState.loadedProfileReadOnly = false
                    -- Semeia o baseline do autosave a partir do arquivo do profile
                    -- proprio ANTES de armar. Sem isso _lastSavedProfileName fica nil
                    -- e o flush "profile-switch" de um Load posterior nao bate no
                    -- guard F3.2 -> gravava a config atual por cima do profile que
                    -- voce so queria LER (bug do "Load limpou o profile lido").
                    if startProfileAutosave then
                        startProfileAutosave()
                    end
                    if armProfileAutosave then
                        armProfileAutosave()
                    end
                    pcall(function()
                        g_logger.info(_profileSaveInfo.prefix ..
                            " loaded trigger=autoload-" ..
                            tostring(helperConfig.autoLoadProfileType or "?") ..
                            " profile=" .. tostring(profileToLoad))
                    end)
                end
                if markProfileLoadedClean then
                    markProfileLoadedClean()
                end

                modules.game_textmessage.displayGameMessage("Profile auto-loaded: " .. profileToLoad)
            else
                -- Failed to load profile, fallback to last selected or defaults

                -- Tentar carregar o último profile selecionado como fallback
                if helperConfig.selectedProfile and helperConfig.selectedProfile ~= "" and helperConfig.selectedProfile ~= profileToLoad then
                    local fallbackProfile = loadProfileFromFile(helperConfig.selectedProfile)
                    if fallbackProfile then
                        helperConfig.profiles[helperConfig.selectedProfile] = fallbackProfile
                        for k, v in pairs(fallbackProfile) do
                            if k ~= "profiles" and k ~= "selectedProfile" and k ~= "autoLoadProfileEnabled" and
                                k ~= "autoLoadProfileType" and k ~= "holdAttackTargetId" and k ~= "holdAttackTargetName" then
                                helperConfig[k] = deepCopy(v)
                            end
                        end
                        ensureHealingSlots(helperConfig)
                        ensureEquipmentSwapConfig(EQUIPMENT_SWAP_DEFAULT_SLOT_COUNT)
                        ensureTimerConfig(TIMER_DEFAULT_RULE_COUNT)
                        -- Load condition settings from fallback profile
                        if fallbackProfile.conditionSettings and modules.game_healthcircle and modules.game_healthcircle.importConditionSettings then
                            modules.game_healthcircle.importConditionSettings(fallbackProfile.conditionSettings)
                        end
                        helperSessionState.loadedProfileReadOnly = false
                        if startProfileAutosave then
                            startProfileAutosave()
                        end
                        if armProfileAutosave then
                            armProfileAutosave()
                        end
                        if markProfileLoadedClean then
                            markProfileLoadedClean()
                        end
                        pcall(function()
                            g_logger.info(_profileSaveInfo.prefix ..
                                " loaded trigger=autoload-fallback profile=" ..
                                tostring(helperConfig.selectedProfile))
                        end)
                    else
                        resetConfigToDefaults()
                    end
                else
                    resetConfigToDefaults()
                end
            end
        else
            -- Auto-load on + criterio sem match (by name: nenhum profile com
            -- o nome do char / by vocation: sem template "global-<voc>").
            -- Comportamento espelha o botao New: profile limpo, sem herdar
            -- selectedProfile de outro character.
            resetConfigToDefaults()
            helperConfig.selectedProfile = ""
            helperSessionState.loadedProfile = ""
            helperSessionState.loadedProfileReadOnly = false
            pcall(function()
                g_logger.info(_profileSaveInfo.prefix ..
                    " autoload-missing trigger=" ..
                    tostring(helperConfig.autoLoadProfileType or "?") ..
                    " character=" .. tostring(characterName) ..
                    " result=blank-profile")
            end)
            modules.game_textmessage.displayGameMessage(
                htr("No matching profile for auto-load. Starting with blank profile."))
        end
    else
        -- Auto-load desabilitado: sempre abrir profile em branco ao relogar/trocar vocacao
        resetConfigToDefaults()
        helperConfig.selectedProfile = ""
        modules.game_textmessage.displayGameMessage(htr("Auto-load disabled: starting with blank profile"))
    end

    -- F1.1: NUNCA armar autosave aqui. Se chegamos neste ponto sem profile
    -- carregado, helperConfig contem apenas defaults. Armar autosave faria
    -- o proximo flush (logout/close/profile-switch) gravar defaults por cima
    -- de um JSON existente com o nome do personagem -- bug classico de
    -- "perdi meu profile pronto".
    -- O autosave so deve armar quando um profile foi explicitamente carregado
    -- ou salvo pelo usuario.
    if (not helperConfig.selectedProfile or helperConfig.selectedProfile == "")
        and characterName and characterName ~= "" then
        helperSessionState.loadedProfile = ""
    end

    -- Aplicar modo de target padrao baseado na vocacao se nao houver configuracao salva
    if not helperConfig.autoTargetMode or helperConfig.autoTargetMode == autoTargetModes["F"] then
        local defaultMode = getDefaultTargetMode()
        if defaultMode ~= autoTargetModes["F"] then
            helperConfig.autoTargetMode = defaultMode
        end
    end

    -- Setar flag ANTES de chamar onLoadHelperData para garantir que callbacks nao sobrescrevam os dados
    isLoadingAlarmData = true
    onLoadHelperData()

    -- Janelas do helper usam fundo transparente (padrao)
    applyOpacityToWindow(helper)
    applyOpacityToWindow(iconStats)

    -- Enable helper status automatically on login
    hotkeyHelperStatus = true
    _G.hotkeyHelperStatus = hotkeyHelperStatus -- Atualizar referencia global
    scheduleEvent(function()
        updateHelperStatusUI()
    end, 100)

    -- Resetar UI se nao carregou profile (para limpar spells/potions anteriores)
    if not helperConfig.autoLoadProfileEnabled or not helperConfig.selectedProfile or helperConfig.selectedProfile == "" then
        scheduleEvent(function()
            if reset then
                reset()
            end
        end, 100)
    end
    loadFriendListToUI()

    -- Atualizar lista de profiles
    if profilesPanel then
        refreshProfilesList()
    end

    -- Note: Friend lists are now persistent and loaded from config
    -- helperConfig.friendhealing and helperConfig.gransiohealing are loaded from saved settings

    helperConfig.currentLockedTargetId = 0
    if helperEvents.helperCycleEvent then
        removeEvent(helperEvents.helperCycleEvent)
        helperEvents.helperCycleEvent = nil
    end

    helperEvents.helperCycleEvent = cycleEvent(helperCycleEvent, helperEvents.helperCycleTimer)

    resetPartyPanel()

    -- Atualizar icone de blessings apos um pequeno delay para garantir que o inventario esteja carregado
    scheduleEvent(function()
        pcall(updateBlessingsIcon)
    end, 500)

    -- Atualizar contagens de itens apos um pequeno delay para garantir que o inventario esteja carregado
    scheduleEvent(function()
        pcall(updateAllItemCounts)
        pcall(updatePortableToolsState)
    end, 600)

    -- Auto-start timers se estiverem habilitados no config (sem precisar abrir a aba Timer)
    if helperConfig.timerEnabled and helperConfig.timers then
        for i = 1, #helperConfig.timers do
            if helperConfig.timers[i] and helperConfig.timers[i].enabled then
                startTimer(i)
            end
        end
        startTimerRuleCooldownOverlayLoop()
    end

    -- Atualizar visibilidade da aba Friend Menu baseado na vocacao
    updateFriendMenuVisibility()

    -- Restore icon stats visibility on login (delayed to ensure all UI and config is fully initialized)
    scheduleEvent(function()
        if IconStatsModule and IconStatsModule.onLogin then
            IconStatsModule.onLogin()
        end
    end, 500)

    -- Start network diagnostics monitor
    if NetDiag and NetDiag.start then
        pcall(NetDiag.start)
    end

    -- Bind ESC key to cancel hold attack target
    local gameRootPanel = modules.game_interface and modules.game_interface.getRootPanel()
    if gameRootPanel then
        g_keyboard.bindKeyDown("Escape", handleHoldAttackEscapeKey, gameRootPanel)
    end

    if _G.profileHelperModule then
        local totalTime = g_clock.millis() - benchmark
        g_logger.warning(string.format("[HELPER PROFILE] online() TOTAL: %dms", totalTime))
    end

    if _G.LoginProfiler then _G.LoginProfiler.mark("game_helper online() end (full-load path)") end

    startProfileAutosave()

    -- Scripting tab: build the API and reload last session's scripts.
    if Scripting and Scripting.online then
        pcall(Scripting.online)
    end

    -- Restaurar janela do Helper se estava aberta ao fechar o client
    scheduleEvent(function()
        if helper and g_settings.getBoolean('helper_window_open') and not helper:isVisible() then
            toggle()
        end
    end, 400)

    -- Relog do mesmo char que caiu no login completo (sem snapshot restaurado, ex.:
    -- sem profile com o nome do char): reset/profile zeraram os toggles de sessao.
    -- Religa cavebot/shooter/targeting que estavam ON antes da queda, usando a
    -- intencao capturada no topo. Delay para rodar depois do reset agendado (100ms),
    -- de onLoadHelperData e do resume automatico do cavebot (~500ms).
    if relogWanted and (relogWanted.cavebot or relogWanted.shooter or relogWanted.target) then
        scheduleEvent(function() reapplyAutomationAfterRelog(relogWanted) end, 700)
    end
end

function offline()
    -- Spell lookup cache is keyed by words; the spell DB can differ between
    -- worlds (different servers / vocations) so drop it on logout.
    _spellWordsCache = {}

    -- Real-vocation extended opcode: drop the receiver and cached id on logout; a
    -- different character may have a different (real) vocation.
    pcall(function() ProtocolGame.unregisterExtendedOpcode(REAL_VOCATION_OPCODE) end)
    helperRealVocationId = nil

    -- Unbind ESC key for hold attack
    local gameRootPanel = modules.game_interface and modules.game_interface.getRootPanel()
    if gameRootPanel then
        g_keyboard.unbindKeyDown("Escape", handleHoldAttackEscapeKey, gameRootPanel)
    end

    -- Flush pending auto-save synchronously before the socket closes.
    stopProfileAutosave({ flush = true })

    -- Salvar configs globais de auto-load antes de deslogar
    saveAutoLoadSettings()

    -- CAPTURAR SNAPSHOT ANTES DE PAUSAR
    captureSessionSnapshot()
    monkVirtueMode = nil
    monkVirtuePendingMode = nil
    monkVirtuePendingUntil = 0

    -- NÃO fazer clear em nada - apenas pausar temporariamente

    -- Parar eventos do helper
    if helperEvents.helperCycleEvent then
        removeEvent(helperEvents.helperCycleEvent)
        helperEvents.helperCycleEvent = nil
    end

    -- Parar loop de execução dos timers (os timers em si permanecem registrados para restaurar ao relogar)
    stopTimerExecutionLoop()

    -- Reset PZ state temporariamente
    isInPZ = false

    -- Hide icon stats on logout
    if IconStatsModule and IconStatsModule.onLogout then
        IconStatsModule.onLogout()
    end

    -- Stop network diagnostics monitor
    if NetDiag and NetDiag.stop then
        pcall(NetDiag.stop)
    end

    -- Hide debug popup on logout
    hideDebugPopup()

    hide()

    -- NÃO limpar a sessão - manter para o próximo login
    -- NÃO limpar presets, waypoints, configurações, etc.
    -- helperSessionState mantém o personagem e profile carregado
    -- helperSessionSnapshot agora contém TODOS os toggles

    -- Scripting tab: stop every script's timers/events/HUDs and persist.
    if Scripting and Scripting.offline then
        pcall(Scripting.offline)
    end

    player = nil
end

-- ==================== SNAPSHOT SYSTEM ====================
-- Sistema de captura e restauração de estado completo da sessão

function captureSessionSnapshot()
    local player = g_game.getLocalPlayer()
    if not player then
        g_logger.warning("[Helper] Não é possível capturar snapshot sem player")
        return false
    end

    local characterName = player:getName()

    helperSessionSnapshot = {
        characterName = characterName,
        capturedAt = os.time(),

        -- TOGGLES PRINCIPAIS
        healingEnabled = helperConfig.healingEnabled or false,
        autoHealingEnabled = helperConfig.autoHealingEnabled or false,
        healFriendEnabled = helperConfig.healFriendEnabled or false,
        equipmentEnabled = helperConfig.equipmentEnabled or false,
        tankModeEnabled = helperConfig.tankModeEnabled or false,

        magicShooterEnabled = helperConfig.magicShooterEnabled or false,
        magicShooterOnHold = helperConfig.magicShooterOnHold or false,
        autoTargetEnabled = helperConfig.autoTargetEnabled or false,
        autoTargetMode = helperConfig.autoTargetMode,
        magicHelperEnabled = helperConfig.magicHelperEnabled or false,

        -- CAVEBOT - CRÍTICO!
        cavebotHelperEnabled = helperConfig.cavebotHelperEnabled or false,

        timerEnabled = helperConfig.timerEnabled or false,
        autoEatFood = helperConfig.autoEatFood or false,
        autoPortableTrader = helperConfig.autoPortableTrader or false,
        portableTraderCapThreshold = helperConfig.portableTraderCapThreshold or 1000,
        energyRingEnabled = helperConfig.energyRingEnabled or false,

        -- UTILITY SPELLS
        utamoVitaEnabled = helperConfig.utamoVitaEnabled or false,
        exanaVitaEnabled = helperConfig.exanaVitaEnabled or false,
        exetaampresEnabled = helperConfig.exetaampresEnabled or false,
        exetaresEnabled = helperConfig.exetaresEnabled or false,
        utamotempoEnabled = helperConfig.utamotempoEnabled or false,
        utitotempoEnabled = helperConfig.utitotempoEnabled or false,
        exorimoeEnabled = helperConfig.exorimoeEnabled or false,
        exorikorEnabled = helperConfig.exorikorEnabled or false,
        utitotemposanEnabled = helperConfig.utitotemposanEnabled or false,
        exanaampresEnabled = helperConfig.exanaampresEnabled or false,
        utevogravsanEnabled = helperConfig.utevogravsanEnabled or false,
        utamotioEnabled = helperConfig.utamotioEnabled or false,
        utevoniaEnabled = helperConfig.utevoniaEnabled or false,
        exorimasresEnabled = helperConfig.exorimasresEnabled or false,
        autoVirtuesEnabled = helperConfig.autoVirtuesEnabled or false,
        utevospiritusEnabled = helperConfig.utevospiritusEnabled or false,
        utitopugnusEnabled = helperConfig.utitopugnusEnabled or false,

        -- TANK MODE SPECIFIC
        ssaTankEnabled = helperConfig.ssaTankEnabled or false,
        mightRingEnabled = helperConfig.mightRingEnabled or false,
        tankModeAmuletEnabled = helperConfig.tankModeAmuletEnabled ~= false,
        tankModeRingEnabled = helperConfig.tankModeRingEnabled ~= false,
        respectEnergyRing = helperConfig.respectEnergyRing or false,
        tankModeAmuletId = helperConfig.tankModeAmuletId or 3081,
        tankModeRingId = helperConfig.tankModeRingId or 3048,


        -- PROFILE INFO
        loadedProfile = helperSessionState.loadedProfile,
        loadedProfileReadOnly = helperSessionState.loadedProfileReadOnly,
        selectedProfile = helperConfig.selectedProfile,

        -- LOCKED TARGET
        currentLockedTargetId = helperConfig.currentLockedTargetId or 0
    }

    helperSessionState.hasValidSnapshot = true

    return true
end

function restoreSessionSnapshot()
    if not helperSessionSnapshot then
        return false
    end

    local player = g_game.getLocalPlayer()
    if not player then
        return false
    end

    local characterName = player:getName()

    -- Validar se o snapshot é do mesmo personagem
    if helperSessionSnapshot.characterName ~= characterName then
        -- F3.3: snapshot de outro char nao pode pintar por cima do profile atual.
        pcall(function()
            g_logger.warning(_profileSaveInfo.prefix ..
                " snapshot discarded: snapshotChar=" ..
                tostring(helperSessionSnapshot.characterName) ..
                " currentChar=" .. tostring(characterName))
        end)
        clearSessionSnapshot()
        return false
    end

    -- F3.3: se o profile carregado e um template "global-*", snapshot toggles
    -- restaurariam estado do char antigo por cima das defaults do template.
    -- Recusa e marca profile como dirty (o usuario decide salvar).
    if type(helperConfig.selectedProfile) == "string" and
        helperConfig.selectedProfile:sub(1, 7) == "global-" and
        helperSessionSnapshot.selectedProfile ~= helperConfig.selectedProfile then
        pcall(function()
            g_logger.info(_profileSaveInfo.prefix ..
                " snapshot skipped: active=" .. tostring(helperConfig.selectedProfile) ..
                " snapshot=" .. tostring(helperSessionSnapshot.selectedProfile) ..
                " reason=vocation-template-protected")
        end)
        clearSessionSnapshot()
        return false
    end

    -- RESTAURAR TOGGLES NO helperConfig
    helperConfig.healingEnabled = helperSessionSnapshot.healingEnabled
    helperConfig.autoHealingEnabled = helperSessionSnapshot.autoHealingEnabled
    helperConfig.healFriendEnabled = helperSessionSnapshot.healFriendEnabled
    helperConfig.equipmentEnabled = helperSessionSnapshot.equipmentEnabled
    helperConfig.tankModeEnabled = helperSessionSnapshot.tankModeEnabled

    helperConfig.magicShooterEnabled = helperSessionSnapshot.magicShooterEnabled
    helperConfig.magicShooterOnHold = helperSessionSnapshot.magicShooterOnHold
    helperConfig.autoTargetEnabled = helperSessionSnapshot.autoTargetEnabled
    helperConfig.autoTargetMode = helperSessionSnapshot.autoTargetMode or getDefaultTargetMode()
    helperConfig.magicHelperEnabled = helperSessionSnapshot.magicHelperEnabled

    -- CAVEBOT - RESTAURAR!
    helperConfig.cavebotHelperEnabled = helperSessionSnapshot.cavebotHelperEnabled

    helperConfig.timerEnabled = helperSessionSnapshot.timerEnabled
    helperConfig.autoEatFood = helperSessionSnapshot.autoEatFood
    helperConfig.autoPortableTrader = helperSessionSnapshot.autoPortableTrader
    helperConfig.portableTraderCapThreshold = helperSessionSnapshot.portableTraderCapThreshold or 1000
    helperConfig.energyRingEnabled = helperSessionSnapshot.energyRingEnabled or false

    -- UTILITY SPELLS
    helperConfig.utamoVitaEnabled = helperSessionSnapshot.utamoVitaEnabled
    helperConfig.exanaVitaEnabled = helperSessionSnapshot.exanaVitaEnabled
    helperConfig.exetaampresEnabled = helperSessionSnapshot.exetaampresEnabled
    helperConfig.exetaresEnabled = helperSessionSnapshot.exetaresEnabled
    helperConfig.utamotempoEnabled = helperSessionSnapshot.utamotempoEnabled
    helperConfig.utitotempoEnabled = helperSessionSnapshot.utitotempoEnabled
    helperConfig.exorimoeEnabled = helperSessionSnapshot.exorimoeEnabled
    helperConfig.exorikorEnabled = helperSessionSnapshot.exorikorEnabled
    helperConfig.utitotemposanEnabled = helperSessionSnapshot.utitotemposanEnabled
    helperConfig.exanaampresEnabled = helperSessionSnapshot.exanaampresEnabled
    helperConfig.utevogravsanEnabled = helperSessionSnapshot.utevogravsanEnabled
    helperConfig.utamotioEnabled = helperSessionSnapshot.utamotioEnabled
    helperConfig.utevoniaEnabled = helperSessionSnapshot.utevoniaEnabled
    helperConfig.exorimasresEnabled = helperSessionSnapshot.exorimasresEnabled
    helperConfig.autoVirtuesEnabled = helperSessionSnapshot.autoVirtuesEnabled or false
    helperConfig.utevospiritusEnabled = helperSessionSnapshot.utevospiritusEnabled or false
    helperConfig.utitopugnusEnabled = helperSessionSnapshot.utitopugnusEnabled or false

    -- TANK MODE
    helperConfig.ssaTankEnabled = helperSessionSnapshot.ssaTankEnabled
    helperConfig.mightRingEnabled = helperSessionSnapshot.mightRingEnabled
    helperConfig.tankModeAmuletEnabled = helperSessionSnapshot.tankModeAmuletEnabled ~= false
    helperConfig.tankModeRingEnabled = helperSessionSnapshot.tankModeRingEnabled ~= false
    helperConfig.tankModeAmuletId = helperSessionSnapshot.tankModeAmuletId or 3081
    helperConfig.tankModeRingId = helperSessionSnapshot.tankModeRingId or 3048
    helperConfig.respectEnergyRing = helperSessionSnapshot.respectEnergyRing


    -- LOCKED TARGET
    helperConfig.currentLockedTargetId = helperSessionSnapshot.currentLockedTargetId or 0

    -- PROFILE INFO
    helperConfig.selectedProfile = helperSessionSnapshot.selectedProfile or ""

    -- ATUALIZAR UI PARA REFLETIR O ESTADO RESTAURADO
    scheduleEvent(function()
        syncUIWithConfig()
    end, 100)

    return true
end

function syncUIWithConfig()
    -- Helper function para setar checkboxes sem triggerar callbacks
    local function setCheckboxState(widget, checked)
        if not widget then
            return
        end
        if widget:isChecked() == checked then
            return
        end
        local oldCallback = widget.onCheckChange
        widget.onCheckChange = nil
        widget:setChecked(checked)
        widget.onCheckChange = oldCallback
    end

    -- SYNC HEALING
    if healingPanel then
        setCheckboxState(healingPanel:recursiveGetChildById("enableAutoHealing"),
            helperConfig.autoHealingEnabled == true)
        refreshEnergyRingUI()
    end

    -- SYNC FRIEND HEAL
    if friendHealPanel then
        setCheckboxState(friendHealPanel:recursiveGetChildById("enableAllFriendHealing"),
            helperConfig.healFriendEnabled == true)
    end

    -- SYNC SHOOTER/TARGETING
    if shooterPanel then
        local enableButtons = shooterPanel:recursiveGetChildById("enableButtons")
        if enableButtons then
            setCheckboxState(enableButtons:recursiveGetChildById("enableMagicShooter"),
                helperConfig.magicShooterEnabled == true)
        end
    end

    if targetingPanel then
        local enableAutoTargetTargeting = targetingPanel:recursiveGetChildById("enableAutoTargetTargeting")
        if enableAutoTargetTargeting then
            setCheckboxState(enableAutoTargetTargeting,
                helperConfig.autoTargetEnabled == true)
        end
    end

    -- SYNC EQUIPMENT/TANK MODE
    if equipmentPanel then
        setCheckboxState(equipmentPanel:recursiveGetChildById("enableEquipmentSwap"),
            helperConfig.equipmentSwapEnabled == true)
        setCheckboxState(equipmentPanel:recursiveGetChildById("enableTankMode"),
            helperConfig.tankModeEnabled == true)
        setCheckboxState(equipmentPanel:recursiveGetChildById("enableTankModeAmulet"),
            helperConfig.tankModeAmuletEnabled ~= false)
        setCheckboxState(equipmentPanel:recursiveGetChildById("enableTankModeRing"),
            helperConfig.tankModeRingEnabled ~= false)
        setCheckboxState(equipmentPanel:recursiveGetChildById("respectEnergyRing"),
            helperConfig.respectEnergyRing == true)
        rebuildAllEquipmentSwapRules()
        updateAllItemCounts()
    end

    -- SYNC CAVEBOT
    local cavePanel = helper and helper.contentPanel and
    helper.contentPanel:recursiveGetChildById("huntingCavebotContent")
    if cavePanel then
        local cavebotCheckbox = cavePanel:recursiveGetChildById("enableCaveBot")
        if cavebotCheckbox then
            setCheckboxState(cavebotCheckbox, helperConfig.cavebotHelperEnabled == true)
        end
    end

    -- SYNC PARTY MANAGEMENT
    if helper and helper.contentPanel then
        local partyManagementContent = helper.contentPanel:recursiveGetChildById("partyManagementContent")
        if partyManagementContent and helperConfig.partyManagement then
            -- Invite Party checkboxes
            if helperConfig.partyManagement.inviteParty then
                setCheckboxState(partyManagementContent:recursiveGetChildById("invitePartyAll"),
                    helperConfig.partyManagement.inviteParty.all == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("invitePartyVip"),
                    helperConfig.partyManagement.inviteParty.vip == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("invitePartyGuild"),
                    helperConfig.partyManagement.inviteParty.guild == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("invitePartyFriend"),
                    helperConfig.partyManagement.inviteParty.friend == true)
            end
            -- Auto Accept Party checkboxes
            if helperConfig.partyManagement.autoAcceptParty then
                setCheckboxState(partyManagementContent:recursiveGetChildById("autoAcceptPartyAll"),
                    helperConfig.partyManagement.autoAcceptParty.all == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("autoAcceptPartyVip"),
                    helperConfig.partyManagement.autoAcceptParty.vip == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("autoAcceptPartyGuild"),
                    helperConfig.partyManagement.autoAcceptParty.guild == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("autoAcceptPartyFriend"),
                    helperConfig.partyManagement.autoAcceptParty.friend == true)
            end
        end
    end
    modules.game_helper.refreshPartyManagementFriendLists()

    -- UPDATE ICON STATS (se disponível)
    if IconStatsModule then
        if IconStatsModule.updateHealingIcon then
            IconStatsModule.updateHealingIcon(helperConfig.autoHealingEnabled)
        end
        if IconStatsModule.updateShooterIcon then
            IconStatsModule.updateShooterIcon(helperConfig.magicShooterEnabled)
        end
        if IconStatsModule.updateTargetingIcon then
            IconStatsModule.updateTargetingIcon(helperConfig.autoTargetEnabled)
        end
        if IconStatsModule.updateCavebotIcon then
            IconStatsModule.updateCavebotIcon(helperConfig.cavebotHelperEnabled)
        end
    end
end

function clearSessionSnapshot()
    helperSessionSnapshot = nil
    helperSessionState.hasValidSnapshot = false
end

-- Continuidade de sessao ao relogar (queda ou !fps): religa cavebot/shooter/targeting
-- que estavam ON antes da desconexao. Necessario porque a ativacao REAL de cada
-- sistema e imperativa e NAO volta so por restaurar o flag em helperConfig:
--   * Targeting (checkAutoTarget): evento estatico do helperCycleEvent, gated pelo
--     flag -> volta sozinho. So restauramos flag/checkbox/UI.
--   * Shooter (checkMagicShooter): idem para o tiro principal, MAS o timer de
--     custom-spells e iniciado a parte por startCustomSpellTimer() no toggle.
--   * Cavebot: o walker e imperativo (startWalk). Usamos resumeCavebotIfNeeded(), o
--     mecanismo oficial de religar no relog -- idempotente: se o walker ja voltou
--     (path snapshot, onde o resume automatico de onGameStart ja rodou) vira no-op;
--     caso contrario (login completo, flag tinha sido zerado pelo reset) faz startWalk.
-- `wanted` (opcional) = { cavebot=, shooter=, target= } captura a intencao ANTES de
-- reset/profile zerarem helperConfig. Sem ele, le o estado atual de helperConfig
-- (usado no path de snapshot, ja restaurado). Idempotente: so liga, nunca inverte.
function reapplyAutomationAfterRelog(wanted)
    if not g_game.isOnline() or not helperConfig then
        return
    end
    if not wanted then
        wanted = {
            cavebot = helperConfig.cavebotHelperEnabled == true,
            shooter = helperConfig.magicShooterEnabled == true,
            target  = helperConfig.autoTargetEnabled == true,
        }
    end
    if not (wanted.cavebot or wanted.shooter or wanted.target) then
        return
    end

    -- Marca um checkbox como ON sem disparar onCheckChange (a ativacao real e feita
    -- explicitamente abaixo; deixar o callback rodar reentraria nos toggles/reset).
    local function markChecked(widget)
        if not widget or widget:isChecked() then return end
        local cb = widget.onCheckChange
        widget.onCheckChange = nil
        widget:setChecked(true)
        widget.onCheckChange = cb
    end

    -- TARGETING: volta sozinho via cycle; restaura flag/checkbox/UI.
    if wanted.target then
        helperConfig.autoTargetEnabled = true
        if targetingPanel then
            markChecked(targetingPanel:recursiveGetChildById("enableAutoTarget"))
        end
        if HelperTrackerModule and HelperTrackerModule.updateTargetStatus then
            pcall(HelperTrackerModule.updateTargetStatus, true)
        end
        if IconStatsModule and IconStatsModule.updateTargetingIcon then
            pcall(IconStatsModule.updateTargetingIcon, true)
        end
    end

    -- SHOOTER: tiro principal volta via cycle; reinicia o timer de custom-spells.
    if wanted.shooter then
        helperConfig.magicShooterEnabled = true
        local cb = (shooterPanel and shooterPanel:recursiveGetChildById("enableMagicShooter"))
            or (enableButtons and enableButtons:recursiveGetChildById("enableMagicShooter"))
        markChecked(cb)
        if startCustomSpellTimer then
            pcall(startCustomSpellTimer)
        end
        if HelperTrackerModule and HelperTrackerModule.updateShooterStatus then
            pcall(HelperTrackerModule.updateShooterStatus, true)
        end
        if IconStatsModule and IconStatsModule.updateShooterIcon then
            pcall(IconStatsModule.updateShooterIcon, true)
        end
    end

    -- CAVEBOT: religa via mecanismo oficial (idempotente, ver nota acima).
    if wanted.cavebot then
        helperConfig.cavebotHelperEnabled = true
        local cavePanel = helper and helper.contentPanel
            and helper.contentPanel:recursiveGetChildById("huntingCavebotContent")
        if cavePanel then
            markChecked(cavePanel:recursiveGetChildById("enableCaveBot"))
        end
        local recorder = hunting_recorderModule
            or (_G and _G.hunting_recorderModule)
            or (modules.game_helper and modules.game_helper.hunting_recorderModule)
        if recorder and recorder.resumeCavebotIfNeeded then
            pcall(recorder.resumeCavebotIfNeeded)
        end
        if IconStatsModule and IconStatsModule.updateCavebotIcon then
            pcall(IconStatsModule.updateCavebotIcon, true)
        end
    end
end

-- ==================== END SNAPSHOT SYSTEM ====================

function round(n)
    return n % 1 >= 0.5 and math.ceil(n) or math.floor(n)
end

function setupShieldHelperSpellIcons()
    if not healingPanel then
        g_logger.info("[SHIELD-ICON] abort: healingPanel is nil")
        return
    end
    local shieldPanel = healingPanel:getChildById("shieldHelperPanel")
    if not shieldPanel then
        g_logger.info("[SHIELD-ICON] abort: shieldHelperPanel is nil")
        return
    end

    -- Set the Magic Potion icon FIRST and independently of the spell-icon lookups
    -- below. getHealingSpellIconData() can raise before the spell cache is ready; in
    -- the old ordering that error aborted this whole function *before* the item id was
    -- applied, leaving the slot blank. Setting it up front removes that shared fate.
    local magicPotionIcon = shieldPanel:recursiveGetChildById("magicPotionIcon")
    if magicPotionIcon then
        magicPotionIcon:setItemId(35563)
        magicPotionIcon:setTooltip("Magic Potion")
        -- TEMP diagnostics (remove once confirmed): prove the id took and the widget
        -- is laid out + visible. Read these in KoliseuClient.log after a helper reload.
        pcall(function()
            g_logger.info(string.format(
                "[SHIELD-ICON] magicPotionIcon ok: itemId=%s visible=%s size=%dx%d pos=%d,%d",
                tostring(magicPotionIcon:getItemId()),
                tostring(magicPotionIcon:isVisible()),
                magicPotionIcon:getWidth(), magicPotionIcon:getHeight(),
                magicPotionIcon:getX(), magicPotionIcon:getY()))
        end)
    else
        g_logger.info("[SHIELD-ICON] magicPotionIcon widget NOT FOUND under shieldHelperPanel")
    end

    local function applyIcon(widgetId, words, tooltip)
        local icon = shieldPanel:recursiveGetChildById(widgetId)
        if not icon then return end
        local ok, source, clip = pcall(getHealingSpellIconData, words)
        if ok and source and clip then
            icon:setImageSource(source)
            icon:setImageClip(clip)
            icon:setTooltip(tooltip)
        else
            icon:hide()
        end
    end

    applyIcon("utamoVitaIcon", "utamo vita", "Utamo Vita")
    applyIcon("exanaVitaIcon", "exana vita", "Exana Vita")
end

function tickShieldHelperCooldown(progressRect, duration)
    if not progressRect or progressRect:isDestroyed() then
        return
    end
    progressRect:setPercent(progressRect:getPercent() + 10000 / duration)
    if progressRect:getPercent() < 100 then
        removeEvent(progressRect.event)
        progressRect.event = scheduleEvent(function()
            tickShieldHelperCooldown(progressRect, duration)
        end, 100)
    else
        if progressRect and not progressRect:isDestroyed() then
            progressRect:destroy()
        end
    end
end

function refreshShieldHelperCooldownOverlay(spellId, delay)
    if not healingPanel or not healingPanel:isVisible() then return end
    local shieldPanel = healingPanel:getChildById("shieldHelperPanel")
    if not shieldPanel then return end

    local iconWidget
    if spellId == 44 then
        iconWidget = shieldPanel:recursiveGetChildById("utamoVitaIcon")
    elseif spellId == 245 then
        iconWidget = shieldPanel:recursiveGetChildById("exanaVitaIcon")
    end
    if not iconWidget or not iconWidget:isVisible() then return end

    local existing = iconWidget:getChildById("shieldHelperCdProgress")
    if existing then
        removeEvent(existing.event)
        if not existing:isDestroyed() then
            existing:destroy()
        end
    end

    local progressRect = g_ui.createWidget('SpellProgressRect', iconWidget)
    progressRect:setId("shieldHelperCdProgress")
    progressRect:fill('parent')
    progressRect:setPercent(0)
    tickShieldHelperCooldown(progressRect, delay)
end

function updateShooterCooldown(progressRect, duration, spellId, count)
    progressRect:setPercent(progressRect:getPercent() + 10000 / duration)
    local cd = round(duration - (progressRect:getPercent() * duration / 100)) / 1000
    if cd > 0 then
        progressRect:setText(cd .. 's')
    end

    if progressRect:getPercent() < 100 then
        removeEvent(progressRect.event)
        progressRect.event = scheduleEvent(function()
            updateShooterCooldown(progressRect, duration, spellId, count + 1)
        end, 100)
    else
        if progressRect and not progressRect:isDestroyed() then
            progressRect:destroy()
            progressRect = nil
        end
    end
end

function updateHealingCooldown(progressRect, duration, spellId, count)
    progressRect:setPercent(progressRect:getPercent() + 10000 / duration)
    local cd = round(duration - (progressRect:getPercent() * duration / 100)) / 1000
    if cd > 0 then
        progressRect:setText(cd .. 's')
    end

    if progressRect:getPercent() < 100 then
        removeEvent(progressRect.event)
        progressRect.event = scheduleEvent(function()
            updateHealingCooldown(progressRect, duration, spellId, count + 1)
        end, 100)
    else
        if progressRect and not progressRect:isDestroyed() then
            progressRect:destroy()
            progressRect = nil
        end
    end
end

function onSpellCooldown(spellId, delay)
    spellsCooldown[spellId] = g_clock.millis() + delay
    if helperEvents then
        helperEvents.spellCooldownDurations = helperEvents.spellCooldownDurations or {}
        helperEvents.spellCooldownStartedAt = helperEvents.spellCooldownStartedAt or {}
        helperEvents.spellCooldownDurations[spellId] = tonumber(delay) or 0
        helperEvents.spellCooldownStartedAt[spellId] = g_clock.millis()
    end

    updateSpellCdDebugWidget(spellId, delay)

    -- If server sends a long cooldown (>2s), it means the spell was successfully cast
    -- Clear the no-area spell backoff so it can be cast again after the real cooldown expires
    -- (reactive mode clears it on ANY real echo — see cast_timing.lua, which unlike this
    -- handler is never reached by the local optimistic echoes).
    if delay > 2000 and noAreaSpellAttempts[spellId] then
        noAreaSpellAttempts[spellId] = nil
    end

    -- Atualizar cooldown na aba shooter
    if shooterPanel and shooterPanel:isVisible() then
        local spell, profile, spellName = Spells.getSpellByIcon(spellId)
        if spell then
            local shooterProfile = getShooterProfile()
            if shooterProfile then
                for slotIndex, spellConfig in ipairs(shooterProfile.spells) do
                    if spellConfig.id > 0 then
                        local spellData = Spells.getSpellByClientId(spellConfig.id)
                        if spellData and (spellData.id == spell.id or spellData.words == spell.words or (spell.clientId and spell.clientId == spellConfig.id)) then
                            local button = shooterPanel:recursiveGetChildById("attackSpellButton" .. (slotIndex - 1))
                            if button then
                                local progressRect = button:recursiveGetChildById('progress' .. spell.id)
                                if not progressRect then
                                    progressRect = g_ui.createWidget('SpellProgressRect', button)
                                    progressRect:setId('progress' .. spell.id)
                                    progressRect:fill('parent')
                                    progressRect:setFont('verdana-11px-rounded')
                                else
                                    progressRect:setPercent(0)
                                end

                                local duration = delay
                                progressRect:setPercent(0)
                                updateShooterCooldown(progressRect, duration, spell.id, 0)
                                break
                            end
                        end
                    end
                end
            end
        end
    end

    -- Atualizar cooldown na aba healing
    if healingPanel and healingPanel:isVisible() then
        local spell, profile, spellName = Spells.getSpellByIcon(spellId)
        if spell then
            for slotIndex, spellConfig in ipairs(helperConfig.spells) do
                if spellConfig.id > 0 then
                    local spellData = Spells.getSpellByClientId(spellConfig.id)
                    if spellData and (spellData.id == spell.id or spellData.words == spell.words or (spell.clientId and spell.clientId == spellConfig.id)) then
                        local button = healingPanel:recursiveGetChildById("spellButton" .. (slotIndex - 1))
                        if button then
                            local progressRect = button:recursiveGetChildById('progress' .. spell.id)
                            if not progressRect then
                                progressRect = g_ui.createWidget('SpellProgressRect', button)
                                progressRect:setId('progress' .. spell.id)
                                progressRect:fill('parent')
                                progressRect:setFont('verdana-11px-rounded')
                            else
                                progressRect:setPercent(0)
                            end

                            local duration = delay
                            progressRect:setPercent(0)
                            updateHealingCooldown(progressRect, duration, spell.id, 0)
                            break
                        end
                    end
                end
            end
        end
    end

    if spellId == 44 or spellId == 245 then
        refreshShieldHelperCooldownOverlay(spellId, delay)
    end

    refreshAllHealingRuleCooldownOverlays()
    refreshAllShooterRuleCooldownOverlays()
    startSpellRuleCooldownOverlayLoop()
end

local CD_DEBUG_GROUP_NAMES = {
    [1] = "attack",
    [2] = "healing",
    [3] = "support"
}

local function tickCdDebug(progressRect, duration)
    if not progressRect or progressRect:isDestroyed() then
        return
    end
    progressRect:setPercent(progressRect:getPercent() + 10000 / duration)
    if progressRect:getPercent() < 100 then
        removeEvent(progressRect.event)
        progressRect.event = scheduleEvent(function()
            tickCdDebug(progressRect, duration)
        end, 100)
    else
        if progressRect.icon and not progressRect.icon:isDestroyed() then
            progressRect.icon:setOn(false)
        end
    end
end

local function updateCdDebugWidget(groupId, delay)
    if not shooterPanel then return end
    local key = CD_DEBUG_GROUP_NAMES[groupId]
    if not key then return end
    local icon = shooterPanel:recursiveGetChildById(key .. "CdDebugIcon")
    if not icon then return end
    local progressRect = shooterPanel:recursiveGetChildById(key .. "CdDebugProgress")
    if not progressRect then return end
    icon:setOn(true)
    progressRect.icon = icon
    removeEvent(progressRect.event)
    progressRect:setPercent(0)
    tickCdDebug(progressRect, delay)
end

function onSpellGroupCooldown(groupId, delay)
    groupsCooldown[groupId] = g_clock.millis() + delay
    updateCdDebugWidget(groupId, delay)
end

function destroySpellCdDebugIcon(progressRect)
    if not progressRect or progressRect:isDestroyed() then return end
    removeEvent(progressRect.event)
    if progressRect.icon and not progressRect.icon:isDestroyed() then
        progressRect.icon:destroy()
    end
end

function tickSpellCdDebug(progressRect, duration)
    if not progressRect or progressRect:isDestroyed() then
        return
    end
    progressRect:setPercent(progressRect:getPercent() + 10000 / duration)
    if progressRect:getPercent() < 100 then
        removeEvent(progressRect.event)
        progressRect.event = scheduleEvent(function()
            tickSpellCdDebug(progressRect, duration)
        end, 100)
    else
        destroySpellCdDebugIcon(progressRect)
    end
end

function createOrUpdateSpellCdIcon(panel, widgetId, source, clip, spellName, delay)
    if not panel or panel:isDestroyed() then return end
    local icon = panel:getChildById(widgetId)
    if not icon then
        icon = g_ui.createWidget("HelperSpellCdIcon", panel)
        icon:setId(widgetId)
    end
    icon:setImageSource(source)
    icon:setImageClip(clip)
    icon:setTooltip(spellName)

    local progressRect = icon:getChildById("progress")
    if not progressRect then
        progressRect = g_ui.createWidget("HelperSpellCdProgress", icon)
        progressRect:setId("progress")
        progressRect:fill("parent")
    end
    progressRect.icon = icon
    removeEvent(progressRect.event)
    progressRect:setPercent(0)
    tickSpellCdDebug(progressRect, delay)
end

function updateSpellCdDebugWidget(spellId, delay)
    local spell, profile, spellName = Spells.getSpellByIcon(spellId)
    if not spellName or not profile then return end
    local clientIconId = Spells.getClientId(spellName)
    if not clientIconId then return end
    local spellSettings = SpelllistSettings[profile]
    if not spellSettings or not spellSettings.iconsFolder then return end
    local clip = Spells.getImageClipNormal(clientIconId, profile)
    if not clip then return end

    local source = spellSettings.iconsFolder
    local widgetId = "spellCdIcon_" .. tostring(spellId)

    if shooterPanel then
        local panel = shooterPanel:recursiveGetChildById("spellCdDebugPanel")
        if panel then
            createOrUpdateSpellCdIcon(panel, widgetId, source, clip, spellName, delay)
        end
    end
end

function onMultiUseCooldown(time)
    multiUseExDelay = g_clock.millis() + time
    if helperEvents then
        helperEvents.multiUseExStartedAt = g_clock.millis()
        helperEvents.multiUseExDuration = tonumber(time) or 0
    end
    refreshAllShooterRuleCooldownOverlays()
    startSpellRuleCooldownOverlayLoop()
end

function getItemCooldownTiming(nowMs)
    local now = tonumber(nowMs) or g_clock.millis()
    local endTime = tonumber(multiUseExDelay) or 0
    if endTime <= now then return nil end

    local duration = 0
    local startedAt = now
    if helperEvents then
        duration = tonumber(helperEvents.multiUseExDuration) or 0
        startedAt = tonumber(helperEvents.multiUseExStartedAt) or now
    end

    if duration <= 0 then
        duration = endTime - now
        startedAt = now
    end

    local elapsed = now - startedAt
    if elapsed < 0 then
        elapsed = 0
    elseif elapsed > duration then
        elapsed = duration
    end

    local percent = (elapsed * 100) / math.max(duration, 1)
    if percent < 0 then
        percent = 0
    elseif percent > 100 then
        percent = 100
    end

    return { percent = percent, remaining = endTime - now, duration = duration }
end

function onUpdateSpellArea(energyWaveEnlarged)
    -- KoliseuOT: Energy Wave is a fixed AREA_BURST3 disc (self-target), not the global
    -- directional wave that the Wheel "enlarged" perk grows. Pin it to BURST3 so a stray
    -- onUpdateSpellArea signal can't revert it to a squarewave.
    SpellInfo.Default["Energy Wave"].area = SpellAreas.AREA_BURST3
end

