function resetMenu(menu)
    for i, widget in ipairs(menu:getChildren()) do
        widget:setVisible(false)
    end
end

function markActiveButton(button, active)
    if not button then return end
    if not button._baseText then
        button._baseText = button:getText()
    end
    button:setText(button._baseText)
    if active then
        button:setColor("#ffffff")
    else
        button:setColor("#c0c0c0")
    end
end

function parseMenuItem(obj, data)
    if not obj or not data then
        return
    end

    if obj then
        if data.text then
            obj:setText(data.text)
        end
        if data.tooltip then
            obj:setTooltip(data.tooltip)
        end
        if data.state ~= nil then
            obj:setVisible(data.state)
        end
    end
end

function viewMenu(menu, vocationId)
    if not menu then
        return
    end

    local config = menuConfigs[menu:getId()]

    if not config then
        return
    end

    if not config[vocationId] then
        if config[VOCATION_OTHERS] then
            for i = 1, #config[VOCATION_OTHERS] do
                local menuItem = config[VOCATION_OTHERS][i]
                if menuItem and menuItem.id and menu[menuItem.id] then
                    parseMenuItem(menu[menuItem.id], menuItem)
                end
            end
        end
        return
    end

    if config[vocationId] then
        for i = 1, #config[vocationId] do
            local menuItem = config[vocationId][i]
            if menuItem then
                if menuItem.id then
                    if menu[menuItem.id] then
                        menu[menuItem.id]:setVisible(menuItem.state)
                    end
                elseif menuItem.recursiveId then
                    if menuItem.numered then
                        for idx = 0, menuItem.numered do
                            local obj = menu:recursiveGetChildById(menuItem.recursiveId .. idx)
                            parseMenuItem(obj, menuItem)
                        end
                    else
                        local obj = menu:recursiveGetChildById(menuItem.recursiveId)
                        parseMenuItem(obj, menuItem)
                    end
                end
            end
        end
    end
end

function toggleMinHarmonyColumn(visible)
    if not shooterPanel or shooterPanel:isDestroyed() then
        return
    end
    rebuildAllShooterRules()
    updateShooterSettingsPopupHarmonyState()
end

function loadMenu(menuId)
    if not helper or not helper.contentPanel then
        return
    end

    local sideMenu = helper.contentPanel:getChildById("sideMenu")
    if not sideMenu then
        return
    end

    local sideMenuButtons = sideMenu:getChildById("sideMenuButtons")
    if not sideMenuButtons then
        return
    end

    local buttons = {
        healMenuButton = "healingMenu",
        toolsMenuButton = "toolsMenu",
        huntingMenuButton = "huntingMenu",
        equipmentMenuButton = "equipmentMenu",
        friendMenuButton = "friendMenu",
        profilesMenuButton = "profilesMenu",
        settingsMenuButton = "settingsMenu",
        scriptingMenuButton = "scriptingMenu"
    }

    for buttonName, buttonId in pairs(buttons) do
        local button = sideMenuButtons:getChildById(buttonId)
        if button then
            button:setChecked(false)
            markActiveButton(button, false)
        end
    end

    local selectedButton = sideMenuButtons:getChildById(menuId)
    if selectedButton then
        selectedButton:setChecked(true)
        markActiveButton(selectedButton, true)
    end

    local vocationId = 0
    if player then
        vocationId = translateVocation(player:getVocation())
    end

    -- Helper: hide all main content panels
    local allPanels = { healingPanel, toolsPanel, huntingPanel, equipmentPanel, friendHealPanel, profilesPanel,
        settingsPanel, scriptingPanel }
    for _, panel in ipairs(allPanels) do
        if panel then panel:hide() end
    end

    if menuId == "healingMenu" then
        if healingPanel then
            resetMenu(healingPanel)
            healingPanel:show()
            healingPanel:setVisible(true)
        end
        if healingPanel and vocationId then
            viewMenu(healingPanel, vocationId)

            -- Sub-tab bar: visible for vocations that have Magic Shield or Energy Ring
            local subTabBar = healingPanel:recursiveGetChildById("healingSubTabBar")
            local subTabMagicShield = healingPanel:recursiveGetChildById("healingSubTabMagicShield")
            local subTabEnergyRing = healingPanel:recursiveGetChildById("healingSubTabEnergyRing")

            local hasMagicShield = (vocationId == VOCATION_SORCERER or vocationId == VOCATION_DRUID)
            local hasEnergyRing = (vocationId == VOCATION_PALADIN or vocationId == VOCATION_MONK)
            local hasSubTabs = hasMagicShield or hasEnergyRing

            if subTabBar then
                subTabBar:setVisible(hasSubTabs)
            end
            if subTabMagicShield then
                subTabMagicShield:setVisible(hasMagicShield)
            end
            if subTabEnergyRing then
                subTabEnergyRing:setVisible(hasEnergyRing)
            end

            -- Adjust healing table height when sub-tab bar is visible
            local healingTablePanel = healingPanel:getChildById("healingPanel")
            if healingTablePanel then
                healingTablePanel:setHeight(hasSubTabs and 480 or 504)
            end


            if hasSubTabs then
                -- Validate saved sub-tab is still valid for this vocation
                local lastTab = helperSessionState.lastHealingSubTab or "healing"
                if lastTab == "magicShield" and not hasMagicShield then
                    lastTab = "healing"
                elseif lastTab == "energyRing" and not hasEnergyRing then
                    lastTab = "healing"
                end
                modules.game_helper.selectHealingSubTab(lastTab)
            else
                -- Knight/Others: no sub-tabs, just show healing content directly
                local healingPresetsContent = healingPanel:getChildById("healingPresetsPanel")
                local healingContent = healingPanel:getChildById("healingPanel")
                local shieldContent = healingPanel:getChildById("shieldHelperPanel")
                local energyRingContent = healingPanel:getChildById("energyRingPanel")
                if healingPresetsContent then healingPresetsContent:setVisible(true) end
                if healingContent then healingContent:setVisible(true) end
                if shieldContent then shieldContent:setVisible(false) end
                if energyRingContent then energyRingContent:setVisible(false) end
            end
        end
    elseif menuId == "toolsMenu" then
        if toolsPanel then
            toolsPanel:show(true)
            modules.game_helper.selectToolsSubTab(helperSessionState.lastToolsSubTab or "toolsHelper")
        end
        refreshIconStatsKeyLabels()
    elseif menuId == "huntingMenu" then
        if huntingPanel then
            huntingPanel:show(true)
            modules.game_helper.selectHuntingSubTab(helperSessionState.lastHuntingSubTab or "targeting")
        end
    elseif menuId == "equipmentMenu" then
        if equipmentPanel then
            equipmentPanel:show(true)
            modules.game_helper.selectEquipmentSubTab(helperSessionState.lastEquipmentSubTab or "equipments")
        end
    elseif menuId == "friendMenu" then
        if friendHealPanel then
            friendHealPanel:show(true)

            --[[ Controlar visibilidade de paineis baseado na vocacao:
                 - Druid/Elder Druid: Exura Sio + Exura Gran Sio
                 - Sorcerer: UH Rune Panel
                 - Paladin: UH Rune Panel
                 - Monk: Exura Tio Sio
                 - Knight: Aba oculta
            --]]

            local sioSpellPanel = friendHealPanel:recursiveGetChildById("sioSpellPanel")
            local granSioSpellPanel = friendHealPanel:recursiveGetChildById("granSioSpellPanel")

            if friendHealingPanel then
                -- Exura Sio: Apenas Druid
                if vocationId == VOCATION_DRUID then
                    friendHealingPanel:setVisible(true)
                    if sioSpellPanel then
                        sioSpellPanel:setVisible(true)
                        local sioTitle = sioSpellPanel:recursiveGetChildById("sioSpellTitle")
                        if sioTitle then sioTitle:setText(tr('Select Sio Spell')) end
                    end
                    loadSioSpellButton(false)
                else
                    friendHealingPanel:setVisible(false)
                    if sioSpellPanel then sioSpellPanel:setVisible(false) end
                end
            end

            if granSioPanel then
                -- Exura Gran Sio: Apenas Druid
                if vocationId == VOCATION_DRUID then
                    granSioPanel:setVisible(true)
                    if granSioSpellPanel then
                        granSioSpellPanel:setVisible(true)
                        local granTitle = granSioSpellPanel:recursiveGetChildById("granSioSpellTitle")
                        if granTitle then granTitle:setText(tr('Select Gran Sio Spell')) end
                    end
                    loadSioSpellButton(true)
                else
                    granSioPanel:setVisible(false)
                    if granSioSpellPanel then granSioSpellPanel:setVisible(false) end
                end
            end

            if tioSioPanel then
                -- Exura Tio Sio: Monk (9) e Exalted Monk (10)
                if vocationId == VOCATION_MONK or vocationId == 9 then
                    tioSioPanel:setVisible(true)
                else
                    tioSioPanel:setVisible(false)
                end
            end

            if uhRunePanel then
                -- UH Rune Panel: Sorcerer e Paladin
                if vocationId == VOCATION_SORCERER or vocationId == VOCATION_PALADIN then
                    uhRunePanel:setVisible(true)
                else
                    uhRunePanel:setVisible(false)
                end
            end
        end
    elseif menuId == "profilesMenu" then
        if profilesPanel then
            -- Carregar configuracoes de auto-load antes de mostrar o painel
            loadAutoLoadSettings()

            profilesPanel:show(true)
            scheduleEvent(function()
                refreshProfilesList()
            end, 100)

            -- Atualizar checkboxes de auto-load
            scheduleEvent(function()
                local enableAutoLoad = profilesPanel:recursiveGetChildById("enableAutoLoadProfile")
                if enableAutoLoad then
                    enableAutoLoad:setChecked(helperConfig.autoLoadProfileEnabled == true)
                end

                local enableAutoSave = profilesPanel:recursiveGetChildById("enableAutoSaveProfile")
                if enableAutoSave then
                    enableAutoSave:setChecked(helperConfig.autoSaveProfileEnabled ~= false)
                end

                -- Vocation profiles removed: "By Character Name" is the only auto-load option.
                if not autoLoadRadioGroup then
                    local autoLoadByName = profilesPanel:recursiveGetChildById("autoLoadByName")
                    if autoLoadByName then
                        autoLoadRadioGroup = UIRadioGroup.create()
                        autoLoadRadioGroup:addWidget(autoLoadByName)
                        autoLoadByName:setVisible(true)
                    end
                end

                local autoLoadByName = profilesPanel:recursiveGetChildById("autoLoadByName")
                if autoLoadByName and autoLoadRadioGroup then
                    autoLoadRadioGroup:selectWidget(autoLoadByName)
                end
            end, 50)
        end
    elseif menuId == "settingsMenu" then
        if settingsPanel then
            settingsPanel:show(true)
            modules.game_helper.selectSettingsSubTab(helperSessionState.lastSettingsSubTab or "general")
            refreshIconStatsCheckboxes()
            refreshStatsBarCheckboxes()
        end
    elseif menuId == "scriptingMenu" then
        if scriptingPanel then
            scriptingPanel:show(true)
        end
        if Scripting and Scripting.showPanel then
            pcall(Scripting.showPanel)
        end
    end
end

function onCreatureAppear(creature)
    if creature:isPlayer() then
        return
    end
    if creature:getHealthPercent() <= 0 then
        return
    end
    if isPlayerSummon(creature) then
        return
    end

    -- Check hold attack target
    checkHoldAttackOnCreatureAppear(creature)

    if not spectators[creature:getId()] and creature:isMonster() then
        spectators[creature:getId()] = creature

        -- Check if this creature is in the ranged monsters list
        local creatureName = creature:getName()
        if creatureName and rangedMonsterNames[creatureName] then
            rangedCreatures[creature:getId()] = {
                firstSeen = g_clock.millis(),
                creature = creature
            }
        end
    end
end

function onCreatureDisappear(creature)
    if spectators[creature:getId()] then
        spectators[creature:getId()] = nil
    end
    -- Clean up ranged tracking
    if rangedCreatures[creature:getId()] then
        rangedCreatures[creature:getId()] = nil
    end
    -- Clear hold attack if the creature died (health is 0)
    if helperConfig and helperConfig.holdAttackTargetId and helperConfig.holdAttackTargetId > 0 and creature:getId() == helperConfig.holdAttackTargetId then
        if creature:getHealthPercent() <= 0 then
            clearHoldAttackTarget()
        end
    end
end

--

--[[ Events ]]
local function toggleAssignSpellWindow()
    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return false
    end

    local existingWindow = rootWidget:recursiveGetChildById("assignSpellWindow")
    if existingWindow and not existingWindow:isDestroyed() then
        safeSetInputLockWidget(nil)
        if helper then
            helper:show(true)
        end
        existingWindow:destroy()
        return true
    end

    return false
end

function assignTrainingSpell(button, mode)
    if toggleAssignSpellWindow() then
        return true
    end

    local modeType = "training"
    if type(mode) == "string" then
        modeType = mode
    elseif mode then
        modeType = "haste"
    end

    local isHaste = modeType == "haste"
    local isCureParalyze = modeType == "cureParalyze"

    local radio = UIRadioGroup.create()
    local window = g_ui.loadUI("styles/spell", g_ui.getRootWidget())
    if not window then
        return true
    end
    applyOpacityToWindow(window)

    window:show(true)
    window:raise()
    window:focus()
    safeSetInputLockWidget(window)
    helper:hide()

    local windowHeader = "Assign Training Spell"
    if isHaste then
        windowHeader = "Assign Haste Spell"
    elseif isCureParalyze then
        windowHeader = "Assign Cure Paralyze Spell"
    end
    window:setText(windowHeader)

    local playerVocation = player and translateVocation(player:getVocation()) or 0

    for profileName, spells in pairs(SpellInfo) do
        for spellName, spellData in pairs(spells) do
            if type(spellData) ~= 'table' or not spellData.id then goto continue end
            if isHaste and (not hasteWhiteList[playerVocation] or not table.contains(hasteWhiteList[playerVocation], spellData.id)) then
                goto continue
            end

            if not isHaste then
                -- Para training spells, aceitar uma variedade maior de spells
                local isValidSpell = false

                if isCureParalyze then
                    -- Healing spells (Group 2 or Healing category)
                    local groups = Spells.getGroupIds(spellData)
                    if table.contains(groups, 2) then
                        isValidSpell = true
                    end

                    if not isValidSpell and spellData.category == "Healing" then
                        isValidSpell = true
                    end

                    -- Haste spells per vocation
                    if not isValidSpell and hasteWhiteList[playerVocation] and table.contains(hasteWhiteList[playerVocation], spellData.id) then
                        isValidSpell = true
                    end
                end

                if not isCureParalyze then
                    -- Verificar por grupos
                    -- spellData.group e um MAPA {groupId = cooldown}, nao um array; usar
                    -- getGroupIds (pairs) para extrair os ids. ipairs sobre {[3]=2000} nao
                    -- itera nada e deixava spells de suporte puras (ex: utana vid) de fora.
                    if spellData.group then
                        local groups = Spells.getGroupIds(spellData)
                        for _, groupId in ipairs(groups) do
                            if groupId == 1 or groupId == 2 or groupId == 3 then -- Ataque, Cura, Suporte
                                isValidSpell = true
                                break
                            end
                        end
                    end

                    -- Verificar por palavras mágicas (spells de ataque, cura, suporte)
                    if not isValidSpell and spellData.words then
                        local words = string.lower(spellData.words)
                        if
                            string.find(words, "exori") or string.find(words, "adori") or string.find(words, "exevo") or
                            string.find(words, "exura") or
                            string.find(words, "utani") or
                            string.find(words, "utevo") or
                            string.find(words, "frigo") or
                            string.find(words, "flam") or
                            string.find(words, "terra") or
                            string.find(words, "mort") or
                            string.find(words, "vis") or
                            string.find(words, "gran")
                        then
                            isValidSpell = true
                        end
                    end

                    -- Verificar por categoria/tipo
                    if
                        not isValidSpell and
                        (spellData.category == "Attack" or spellData.category == "Healing" or
                            spellData.category == "Support")
                    then
                        isValidSpell = true
                    end
                end

                if not isValidSpell then
                    goto continue
                end
            end

            if not isHaste and not isCureParalyze and hasteWhiteList[playerVocation] and table.contains(hasteWhiteList[playerVocation], spellData.id) then
                goto continue
            end

            if table.contains(spellData.vocations, playerVocation) and not ignoredTrainingSpells[spellData.id] then
                local widget = g_ui.createWidget("SpellPreview", window.contentPanel.spellList)
                local spellId = SpellIcons[spellData.icon][1]

                radio:addWidget(widget)
                widget:setId(spellData.id)
                widget:setText(spellName .. "\n" .. spellData.words)
                widget.voc = spellData.vocations
                widget.source = SpelllistSettings[profileName].iconsFolder
                widget.clip = Spells.getImageClipNormal(spellId, profileName)
                widget.image:setImageSource(widget.source)
                widget.image:setImageClip(widget.clip)

                if spellData.level then
                    widget.levelLabel:setVisible(true)
                    widget.levelLabel:setText(string.format("Level: %d", spellData.level))
                end

                -- Determinar grupo primário do spell de forma segura
                local primaryGroup = -1
                if spellData.group then
                    if type(spellData.group) == "table" and #spellData.group > 0 then
                        primaryGroup = spellData.group[1]
                    elseif type(spellData.group) == "number" and spellData.group > 0 then
                        primaryGroup = spellData.group
                    end
                elseif spellData.groupType then
                    primaryGroup = spellData.groupType
                end

                if primaryGroup ~= -1 then
                    local offSet = 1
                    if primaryGroup == 2 then
                        offSet = (23 * (primaryGroup - 1))
                    elseif primaryGroup == 3 then
                        offSet = (23 * (primaryGroup - 1)) - 1
                    end
                    widget.imageGroup:setImageClip(offSet .. " 25 20 20")
                    widget.imageGroup:setVisible(true)
                end
            end

            ::continue::
        end
    end

    -- Order the spell list
    local widgets = window.contentPanel.spellList:getChildren()
    table.sort(
        widgets,
        function(a, b)
            return a:getText() < b:getText()
        end
    )
    for i, widget in ipairs(widgets) do
        window.contentPanel.spellList:moveChildToIndex(widget, i)
    end

    -- Callback of radio
    radio.onSelectionChange = function(widget, selected)
        if selected then
            window.contentPanel.preview:setText(selected:getText())
            window.contentPanel.preview.image:setImageSource(selected.source)
            window.contentPanel.preview.image:setImageClip(selected.clip)
            window.contentPanel.paramLabel:setOn(selected.param)
            window.contentPanel.paramText:setEnabled(selected.param)
            window.contentPanel.paramText:clearText()
            window.contentPanel.spellList:ensureChildVisible(widget)
        end
    end

    if window.contentPanel.spellList:getChildren() then
        radio:selectWidget(window.contentPanel.spellList:getChildren()[1])
    end

    local okFunc = function(destroy)
        local selected = radio:getSelectedWidget()
        if not selected then
            return
        end

        local spellIcon = selected.source
        local spellClip = selected.clip
        local spellId = selected:getId()
        local spellName = selected:getText():match("^(.-)\n")
        local spellWords = selected:getText():match("\n(.+)")

        local slotID = tonumber(button:getId():match("%d+"))
        if isHaste then
            helperConfig.haste[1].id = tonumber(spellId)
        elseif isCureParalyze then
            helperConfig.cureParalyze[1].id = tonumber(spellId)
        else
            helperConfig.training[1].id = tonumber(spellId)
            if helperConfig.training[1].percent == 0 then
                helperConfig.training[1].percent = 100
                updateTrainingPercent("spellTrainingButton0", helperConfig.training[1].percent)
            end
        end

        safeSetInputLockWidget(nil)
        button:setImageSource(spellIcon)
        button:setImageClip(spellClip)
        button:setBorderColorTop("#1b1b1b")
        button:setBorderColorLeft("#1b1b1b")
        button:setBorderColorRight("#757575")
        button:setBorderColorBottom("#757575")
        button:setBorderWidth(1)
        button:setTooltip("Spell: " .. spellName .. "\nWords: " .. spellWords)

        if destroy then
            helper:show(true)
            window:destroy()
        end
    end

    local cancelFunc = function()
        helper:show(true)
        safeSetInputLockWidget(nil)
        window:destroy()
    end

    window.contentPanel.buttonOk.onClick = function()
        okFunc(true)
    end
    window.contentPanel.buttonApply.onClick = function()
        okFunc(false)
    end
    window.contentPanel.buttonClose.onClick = cancelFunc
    window.contentPanel.onEnter = function()
        okFunc(true)
    end
    window.onEscape = cancelFunc
end

local function invalidPresetName(name)
    if helperConfig.shooterProfiles[name] then
        return true, "There is already a preset with this name."
    elseif name:len() == 0 then
        return true, "The name cannot be empty."
    elseif name:len() > 22 then
        return true, "The name cannot be longer than 22 characters."
    elseif name:match("[^%w]") then
        return true, "The name cannot contain special characters or spaces."
    end
    return false
end

function invalidModulePresetName(moduleType, name, currentPresetKey)
    local meta = modulePresetMeta[moduleType]
    if not meta or type(helperConfig) ~= "table" then
        return true, "Preset module is unavailable."
    end

    local text = tostring(name or "")
    if text:len() == 0 then
        return true, "The name cannot be empty."
    elseif text:len() > 22 then
        return true, "The name cannot be longer than 22 characters."
    elseif text:match("[^%w]") then
        return true, "The name cannot contain special characters or spaces."
    end

    local labels = helperConfig[meta.labelsKey] or {}
    local currentKey = tostring(currentPresetKey or "")
    for presetKey, label in pairs(labels) do
        if tostring(presetKey) ~= currentKey and tostring(label) == text then
            return true, "There is already a preset with this name."
        end
    end

    return false
end

function openModulePresetRenameOrAddWindow(moduleType, isRename)
    local meta = modulePresetMeta[moduleType]
    if not meta then
        return
    end
    ensureModulePresetConfig(moduleType)

    if shooterPresetWindow and not shooterPresetWindow:isDestroyed() then
        shooterPresetWindow:destroy()
        shooterPresetWindow = nil
        return
    end

    local radio = UIRadioGroup.create()
    local window = g_ui.loadUI("styles/shooterPreset", g_ui.getRootWidget())
    if not window then
        return true
    end

    shooterPresetWindow = window
    applyOpacityToWindow(window)
    window.onDestroy = function()
        shooterPresetWindow = nil
    end

    if not isRename then
        modules.game_textmessage.displayGameMessage(
            string.format("%s presets are fixed from 1 to %d.", meta.title, modulePresetSlotCount)
        )
        if window and not window:isDestroyed() then
            window:destroy()
        end
        shooterPresetWindow = nil
        return
    end

    local combo = getPresetComboRefByType(moduleType)
    local selectedPreset = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))

    window:setText(string.format("Rename %s preset", string.lower(meta.title)))
    window.contentPanel.target:setText(getModulePresetDisplayName(moduleType, selectedPreset))

    window:show(true)
    window:raise()
    window:focus()
    window.contentPanel.target:focus()
    modalEnter(window)

    local onWrite = function()
        local warning = window.contentPanel.warning
        local text = window.contentPanel.target:getText()
        local invalid, message = invalidModulePresetName(moduleType, text, selectedPreset)
        if invalid then
            warning:setVisible(true)
            warning:setTooltip(message)
        elseif not invalid and warning:isVisible() then
            warning:setVisible(false)
            warning:setTooltip("")
        end
    end

    local renameConfirm = function()
        local input = window.contentPanel.target:getText()
        local currentLabel = getModulePresetDisplayName(moduleType, selectedPreset)
        if input == currentLabel then
            return
        end

        if invalidModulePresetName(moduleType, input, selectedPreset) then
            return
        end

        if type(helperConfig[meta.labelsKey]) ~= "table" then
            helperConfig[meta.labelsKey] = {}
        end
        helperConfig[meta.labelsKey][selectedPreset] = input

        loadModulePresetOptions(moduleType, true)
        runWithModulePresetUiSync(function()
            if combo and combo.setCurrentOptionByData then
                combo:setCurrentOptionByData(selectedPreset, true)
            elseif combo and combo.setCurrentOption then
                combo:setCurrentOption(getModulePresetUiName(moduleType, selectedPreset), true)
            end
        end)

        saveSettings()
        if IconStatsModule and IconStatsModule.updateModulePresetTooltip then
            IconStatsModule.updateModulePresetTooltip(moduleType)
        end
        window:destroy()
    end

    local cancel = function()
        window:destroy()
    end

    window.contentPanel.cancelButton.onClick = cancel
    window.onEscape = cancel
    window.contentPanel.target.onTextChange = function()
        onWrite()
    end
    window.contentPanel.okButton.onClick = function()
        renameConfirm()
    end
    window.contentPanel.onEnter = function()
        renameConfirm()
    end
end

function sendRenameOrAddWindow(isRename)
    openModulePresetRenameOrAddWindow("shooter", isRename)
end

function assignSpell(button, groupName, groups, tableToAssign)
    if toggleAssignSpellWindow() then
        return true
    end

    local radio = UIRadioGroup.create()

    local window = g_ui.loadUI("styles/spell", g_ui.getRootWidget())
    if not window then
        return true
    end
    applyOpacityToWindow(window)

    window:show(true)
    window:raise()
    window:focus()
    safeSetInputLockWidget(window)
    helper:hide()

    window:setText("Assign " .. groupName .. " Spell")

    local profile = getShooterProfile()
    local playerVocation = translateVocation(player:getVocation())

    -- Carregando spells de healing para vocação: " .. playerVocation
    local spellCount = 0

    for profileName, spells in pairs(SpellInfo) do
        if type(spells) ~= "table" then goto continue_profile end
        for spellName, spellData in pairs(spells) do
            if type(spellData) ~= 'table' or not spellData.id then goto continue_spell end
            local groupIds = Spells.getGroupIds(spellData)
            local function containsAnyGroup(groups, targetGroups)
                for _, group in ipairs(targetGroups) do
                    if table.contains(groups, group) then
                        return true
                    end
                end
                return false
            end

            if
                containsAnyGroup(groupIds, groups) and table.contains(spellData.vocations, playerVocation) and
                not ignoredSpellsIds[spellData.id]
            then
                spellCount = spellCount + 1
                local widget = g_ui.createWidget("SpellPreview", window.contentPanel.spellList)
                local spellId = SpellIcons[spellData.icon][1]
                radio:addWidget(widget)
                widget:setId(spellData.id)
                widget:setText(spellName .. "\n" .. spellData.words)
                widget.voc = spellData.vocations
                widget.source = SpelllistSettings[profileName].iconsFolder
                widget.clip = Spells.getImageClipNormal(spellId, profileName)
                widget.image:setImageSource(widget.source)
                widget.image:setImageClip(widget.clip)

                if spellData.level then
                    widget.levelLabel:setVisible(true)
                    widget.levelLabel:setText(string.format("Level: %d", spellData.level))
                end

                -- Definir grupo visual baseado nos grupos da spell
                if groupIds and #groupIds > 0 then
                    local primaryGroup = groupIds[1]
                    local offSet = 1
                    if primaryGroup == 2 then
                        offSet = (23 * (primaryGroup - 1))
                    elseif primaryGroup == 3 then
                        offSet = (23 * (primaryGroup - 1)) - 1
                    end
                    widget.imageGroup:setImageClip(offSet .. " 25 20 20")
                    widget.imageGroup:setVisible(true)
                end
            end
            ::continue_spell::
        end
        ::continue_profile::
    end

    -- Total spells encontradas: " .. spellCount

    -- sort alphabetically
    local widgets = window.contentPanel.spellList:getChildren()
    table.sort(
        widgets,
        function(a, b)
            return a:getText() < b:getText()
        end
    )
    for i, widget in ipairs(widgets) do
        window.contentPanel.spellList:moveChildToIndex(widget, i)
    end

    -- callback
    radio.onSelectionChange = function(widget, selected)
        if selected then
            window.contentPanel.preview:setText(selected:getText())
            window.contentPanel.preview.image:setImageSource(selected.source)
            window.contentPanel.preview.image:setImageClip(selected.clip)
            window.contentPanel.paramLabel:setOn(selected.param)
            window.contentPanel.paramText:setEnabled(selected.param)
            window.contentPanel.paramText:clearText()
            window.contentPanel.spellList:ensureChildVisible(widget)
        end
    end

    if window.contentPanel.spellList:getChildren() then
        radio:selectWidget(window.contentPanel.spellList:getChildren()[1])
    end

    window:recursiveGetChildById("tick"):setChecked(true)
    window:recursiveGetChildById("tick"):setEnabled(false)

    local okFunc = function(destroy)
        local selected = radio:getSelectedWidget()
        if not selected then
            return
        end

        local profile = getShooterProfile()
        local spellIcon = selected.source
        local spellClip = selected.clip
        local spellId = selected:getId()
        local spellName = selected:getText():match("^(.-)\n") or selected:getText()
        local spellWords = selected:getText():match("\n(.+)") or ""

        local slotID = tonumber(button:getId():match("%d+"))
        if button:getId():find("attackSpellButton") then
            profile.spells[slotID + 1].id = tonumber(spellId)
        else
            tableToAssign[slotID + 1].id = tonumber(spellId)
        end

        button:setImageSource(spellIcon)
        button:setImageClip(spellClip)
        button:setText("")
        button:setTooltip("Spell: " .. spellName .. "\nWords: " .. spellWords)

        -- Atualiza o ícone de info para spells normais
        updateSpellInfoIcon(button, spellName, spellWords)

        -- Configurar botao de prioridade para healing spells
        if button:getId():find("spellButton") and groupName == "Healing" then
            if not tableToAssign[slotID + 1].priority then
                tableToAssign[slotID + 1].priority = 1
            end
            if not tableToAssign[slotID + 1].orderPriority then
                tableToAssign[slotID + 1].orderPriority = slotID + 1
            end
            local priorityButton = healingPanel:recursiveGetChildById("spellPriority" .. slotID)
            if priorityButton then
                if tableToAssign[slotID + 1].priority == 2 then
                    priorityButton:setImageSource("/images/skin/show-gui-help-blue")
                    priorityButton:setTooltip("This spell is healing mana...")
                    priorityButton.actionId = 2
                else
                    priorityButton:setImageSource("/images/ui/show-gui-help-orange.png")
                    priorityButton:setTooltip("This spell is healing health...")
                    priorityButton.actionId = 1
                end
            end
            local orderPriorityCombo = healingPanel:recursiveGetChildById("spellOrderPriority" .. slotID)
            if orderPriorityCombo then
                local orderPriority = tableToAssign[slotID + 1].orderPriority or (slotID + 1)
                local priorityText = ""
                if orderPriority == 1 then
                    priorityText = "1st"
                elseif orderPriority == 2 then
                    priorityText = "2nd"
                elseif orderPriority == 3 then
                    priorityText = "3rd"
                elseif orderPriority == 4 then
                    priorityText = "4th"
                else
                    priorityText = "1st"
                end
                orderPriorityCombo:setCurrentOption(priorityText)
            end
        end

        safeSetInputLockWidget(nil)
        if destroy then
            window:destroy()
        end

        if button:getId():find("attackSpellButton") then
            local creaturesMin = shooterPanel:recursiveGetChildById("countMinCreature" .. slotID)
            local forceCast = shooterPanel:recursiveGetChildById("conditionSetting" .. slotID)
            local selfCast = shooterPanel:recursiveGetChildById("selfCast" .. slotID)
            local spell = Spells.getSpellByClientId(tonumber(spellId))
            if spell then
                -- Percentual de mana agora e 100% automatico, nao precisa mais configuracao
                if table.contains(bothCastTypeSpells, spell.id) then -- divine grenade self cast
                    if not selfCast then
                        selfCast = g_ui.createWidget("CheckBox", creaturesMin:getParent())
                        local style = {
                            ["width"] = 12,
                            ["anchors.top"] = "countMinCreature" .. slotID .. ".top",
                            ["anchors.left"] = "countMinCreature" .. slotID .. ".right",
                            ["margin-top"] = 6,
                            ["margin-left"] = 5
                        }
                        selfCast:mergeStyle(style)
                        selfCast:setId("selfCast" .. slotID)
                        selfCast:setTooltip("Cast on yourself")
                        selfCast:setVisible(true)
                        selfCast.onCheckChange = function()
                            toggleSelfCast(selfCast:getId():match("%d+"), selfCast:isChecked())
                        end
                    end
                end
                if selfCast and not table.contains(bothCastTypeSpells, spell.id) then
                    profile.spells[slotID + 1].selfCast = false
                    selfCast:destroy()
                end
                if
                    (spell.range and spell.range > 0 and not spell.area) and
                    not table.contains(bothCastTypeSpells, spell.id)
                then
                    profile.spells[slotID + 1].creatures = 1
                    creaturesMin:setCurrentOption("1+")
                    creaturesMin:disable()
                    if forceCast then
                        forceCast:setChecked(profile.spells[slotID + 1].forceCast)
                        forceCast:setVisible(true)
                    end
                else
                    creaturesMin:enable()
                    if forceCast then
                        forceCast:setChecked(false)
                        forceCast:setVisible(false)
                        profile.spells[slotID + 1].forceCast = false
                    end
                end
            end
        end
        if destroy then
            helper:show()
            window:destroy()
        end
    end

    local cancelFunc = function()
        helper:show()
        safeSetInputLockWidget(nil)
        window:destroy()
    end

    window.contentPanel.buttonOk.onClick = function()
        okFunc(true)
    end
    window.contentPanel.buttonApply.onClick = function()
        okFunc(false)
    end
    window.contentPanel.buttonClose.onClick = cancelFunc
    window.contentPanel.onEnter = function()
        okFunc(true)
    end
    window.onEscape = cancelFunc
end

-- Variáveis globais para o assign text
local customSpellAssignWindow = nil
local customSpellTargetButton = nil
local customSpellSlotID = nil

function assignCustomSpellText(button)
    local profile = getShooterProfile()
    local slotID = tonumber(button:getId():match("%d+"))

    -- Armazena referências globais
    customSpellTargetButton = button
    customSpellSlotID = slotID

    -- Abre a janela usando o mesmo sistema do actionbar
    openCustomSpellAssignWindow()
end

function openCustomSpellAssignWindow()
    -- Fecha janela anterior se existir
    if customSpellAssignWindow then
        customSpellAssignWindow:destroy()
        customSpellAssignWindow = nil
    end

    -- Carrega a janela do OTUI
    customSpellAssignWindow = g_ui.displayUI('custom_spell')
    applyOpacityToWindow(customSpellAssignWindow)

    customSpellAssignWindow.onDestroy = function()
        customSpellAssignWindow = nil
    end

    -- Pré-preenche campos se já existe spell customizado
    local profile = getShooterProfile()
    local textEdit = customSpellAssignWindow:recursiveGetChildById('textToSendTextEdit')
    local cooldownEdit = customSpellAssignWindow:recursiveGetChildById('cooldownTextEdit')

    if profile.spells[customSpellSlotID + 1].id == -1 and profile.spells[customSpellSlotID + 1].customText then
        textEdit:setText(profile.spells[customSpellSlotID + 1].customText)
        if profile.spells[customSpellSlotID + 1].cooldown then
            cooldownEdit:setText(tostring(profile.spells[customSpellSlotID + 1].cooldown))
        end
    end

    -- Foco no primeiro campo
    textEdit:focus()
    modalEnter(customSpellAssignWindow)
end

function closeCustomSpellAssignWindow()
    if customSpellAssignWindow then
        customSpellAssignWindow:hide()
        customSpellAssignWindow:destroy()
        customSpellAssignWindow = nil
    end
    customSpellTargetButton = nil
    customSpellSlotID = nil
end

function customSpellAssignAccept()
    local textEdit = customSpellAssignWindow:recursiveGetChildById('textToSendTextEdit')
    local cooldownEdit = customSpellAssignWindow:recursiveGetChildById('cooldownTextEdit')
    local text = textEdit:getText()
    local cooldownText = cooldownEdit:getText()

    if text == '' then
        closeCustomSpellAssignWindow()
        return
    end

    text = text:trim():lower()
    local cooldown = tonumber(cooldownText) or 2000 -- Default 2 segundos se inválido
    local profile = getShooterProfile()

    -- Configura o spell customizado
    profile.spells[customSpellSlotID + 1].id = -1
    profile.spells[customSpellSlotID + 1].customText = text
    profile.spells[customSpellSlotID + 1].cooldown = cooldown
    profile.spells[customSpellSlotID + 1].percent = 80
    profile.spells[customSpellSlotID + 1].creatures = 1
    profile.spells[customSpellSlotID + 1].forceCast = false
    profile.spells[customSpellSlotID + 1].selfCast = false
    profile.spells[customSpellSlotID + 1].enabled = true

    -- Atualiza a aparência do botão
    customSpellTargetButton:setImageSource("customspells.png")
    customSpellTargetButton:setImageClip("0 0 32 32")
    customSpellTargetButton:setTooltip("Custom Spell: " .. text .. " (CD: " .. cooldown .. "ms)")

    -- Mostra o ícone de info para custom spells
    local infoButton = helper:recursiveGetChildById("spellInfoButton" .. customSpellSlotID)
    if infoButton then
        infoButton:setVisible(true)
        infoButton:setTooltip("Custom Spell: " .. text .. " (Cooldown: " .. cooldown .. "ms)")
    end

    closeCustomSpellAssignWindow()
end

function assignRune(button, groupName, groups, tableToAssign)
    mouseGrabberWidget:grabMouse()
    helper:hide()
    g_mouse.pushCursor("target")
