        [57144] = true, -- Lvl250K Amanece Rune
        [57145] = true, -- Lvl300K Meridian Rune
        [60137] = true, -- Reborn Rune
        [60138] = true  -- Gran Reborn Rune
    }

    -- Accept runes if found in spell system OR if it's a known rune ID
    if rune or knownRunes[runeId] then
        if rune and rune.vocations and not table.contains(rune.vocations, translateVocation(player:getVocation())) then
            modules.game_textmessage.displayFailureMessage(tr("Your vocation can not use this rune."))
            return true
        end
        updateRuneButton(button, runeId, rune)
    else
        modules.game_textmessage.displayFailureMessage(tr("Invalid rune!"))
    end
end

function updateRuneButton(button, runeId, rune)
    button:setImageSource("/images/ui/item")

    if not button:getChildById("runeItem") then
        local itemWidget = g_ui.createWidget("RuneItem", button)
        itemWidget:setId("runeItem")
    end

    local itemWidget = button:getChildById("runeItem")
    itemWidget:setItemId(runeId)

    -- Set tooltip with rune info, handle nil rune
    local runeName = rune and rune.name or ("Rune ID: " .. runeId)
    local targetType = rune and (rune.area and "(Area Target)" or "(Single Target)") or "(Unknown Target)"
    button:setTooltip(string.format(runeName .. " %s", targetType))

    local profile = getShooterProfile()
    local buttonId = button:getId()
    local slotID = tonumber(buttonId:match("%d+"))
    local creaturesMin = runePanel:recursiveGetChildById("countMinCreature" .. slotID)
    local forceCast = runePanel:recursiveGetChildById("conditionSetting" .. slotID)

    profile.runes[slotID + 1].id = runeId
    profile.runes[slotID + 1].creatures = profile.runes[slotID + 1].creatures

    local runeSpell = nil
    if Spells.getRuneSpellByItem then
        runeSpell = Spells.getRuneSpellByItem(runeId)
    elseif Spells.getSpellByClientId then
        runeSpell = Spells.getSpellByClientId(runeId)
    end
    if runeSpell and not runeSpell.area then
        creaturesMin:setCurrentOption("1+")
        creaturesMin:disable()
        forceCast:setChecked(profile.runes[slotID + 1].forceCast)
        forceCast:setVisible(true)
        profile.runes[slotID + 1].creatures = 1
        return
    end
    profile.runes[slotID + 1].forceCast = false
    forceCast:setChecked(false)
    forceCast:setVisible(false)
    creaturesMin:enable()
end

function getPotionInfoById(itemId)
    for _, potion in pairs(potionWhitelist) do
        if itemId == potion.id then
            return true, potion.name
        end
    end
    return false, "Unknown Potion"
end

function isHealthPotion(potionId, config)
    -- Se tem config com priority, usa a configuração do usuário
    if config and config.priority then
        -- priority 1 = curar por health
        if config.priority == 1 then
            return true
        end
        -- priority 2 = curar por mana (não é health potion)
        if config.priority == 2 then
            return false
        end
    end

    -- Fallback: usa a whitelist padrão
    for _, potion in ipairs(potionWhitelist) do
        if potion.id == potionId and (potion.type == "health" or potion.type == "spirit") then
            return true
        end
    end
    return false
end

function isManaPotion(potionId, config)
    -- Se tem config com priority, usa a configuração do usuário
    if config and config.priority then
        -- priority 2 = curar por mana
        if config.priority == 2 then
            return true
        end
        -- priority 1 = curar por health (não é mana potion)
        if config.priority == 1 then
            return false
        end
    end

    -- Fallback: usa a whitelist padrão
    for _, potion in ipairs(potionWhitelist) do
        if potion.id == potionId and (potion.type == "mana" or potion.type == "spirit") then
            return true
        end
    end
    return false
end

function usePotion(potionId)
    local player = g_game.getLocalPlayer()
    if not player then
        return false
    end

    local cooldownKey = "healingPotion:" .. tostring(potionId)
    local cooldown = getSpellCooldown(cooldownKey)
    if cooldown > g_clock.millis() then
        return false
    end

    -- Predictive multi-use gate only once a real 0xA6 proved the server sends
    -- it; until then the legacy local exhaust floor prevents spam-drinking.
    if CastTiming.isActive() and CastTiming.hasMultiUseEcho() then
        if CastTiming.isMultiUseBlocked() then
            return false
        end
    elseif multiUseExDelay > g_clock.millis() then
        return false
    end

    if helperEvents and helperEvents.shooterPotionHoldForRunePeek then
        return false
    end

    helperConfig.magicShooterOnHold = true

    -- Usa direto pelo ID (funciona como hotkey, não precisa container aberto)
    local success = pcall(function()
        g_game.useInventoryItemWith(potionId, player, -1)
    end)

    if success then
        CastTiming.notePotionUsed()
        spellsCooldown[cooldownKey] = g_clock.millis() + getEngineIntervalValue("magicShooter")
        multiUseExDelay = g_clock.millis() + getEngineIntervalValue("magicShooter")
    end

    helperConfig.magicShooterOnHold = false
    return success
end

function assignPotionEvent(button)
    mouseGrabberWidget:grabMouse()
    helper:hide()
    g_mouse.pushCursor("target")
    mouseGrabberWidget.onMouseRelease = function(self, mousePosition, mouseButton)
        onAssignPotion(self, mousePosition, mouseButton, button)
    end
end

function onAssignPotion(self, mousePosition, mouseButton, button)
    mouseGrabberWidget:ungrabMouse()
    helper:show()
    g_mouse.popCursor("target")
    mouseGrabberWidget.onMouseRelease = nil

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return true
    end

    local clickedWidget = rootWidget:recursiveGetChildByPos(mousePosition, false)
    if not clickedWidget then
        return true
    end

    local potionId = 0
    if clickedWidget:getClassName() == "UIItem" and not clickedWidget:isVirtual() then
        local item = clickedWidget:getItem()
        if item then
            potionId = item:getId()
        end
    elseif clickedWidget:getClassName() == "UIGameMap" then
        local tile = clickedWidget:getTile(mousePosition)
        if tile then
            local topUseThing = tile:getTopUseThing()
            if topUseThing then
                potionId = topUseThing:getId()
            end
        end
    end

    local isPotion, potionName = getPotionInfoById(potionId)
    if isPotion then
        updatePotionButton(button, potionId, potionName)
    else
        modules.game_textmessage.displayFailureMessage(tr("Invalid potion!"))
    end
end

function updatePotionButton(button, potionId, potionName)
    button:setImageSource("/images/ui/item")

    if not button:getChildById("potionItem") then
        local itemWidget = g_ui.createWidget("PotionItem", button)
        itemWidget:setId("potionItem")
    end

    local itemWidget = button:getChildById("potionItem")
    itemWidget:setItemId(potionId)
    itemWidget:setTooltip(potionName)

    local buttonId = button:getId()
    local slotID = tonumber(buttonId:match("%d+"))
    helperConfig.potions[slotID + 1].id = potionId
    helperConfig.potions[slotID + 1].percent = helperConfig.potions[slotID + 1].percent

    -- Inicializar priority se nao existir
    if not helperConfig.potions[slotID + 1].priority then
        helperConfig.potions[slotID + 1].priority = 1
    end
    if not helperConfig.potions[slotID + 1].orderPriority then
        helperConfig.potions[slotID + 1].orderPriority = slotID + 1
    end

    -- Configurar botao de prioridade
    local priorityButton = healingPanel:recursiveGetChildById("priority" .. slotID)
    if priorityButton then
        if helperConfig.potions[slotID + 1].priority == 2 then
            priorityButton:setImageSource("/images/skin/show-gui-help-blue")
            priorityButton:setTooltip("This potion is healing mana...")
            priorityButton.actionId = 2
        else
            priorityButton:setImageSource("/images/ui/show-gui-help-orange.png")
            priorityButton:setTooltip("This potion is healing health...")
            priorityButton.actionId = 1
        end
    end

    -- Configurar ComboBox de prioridade numérica
    local orderPriorityCombo = healingPanel:recursiveGetChildById("potionOrderPriority" .. slotID)
    if orderPriorityCombo then
        local orderPriority = helperConfig.potions[slotID + 1].orderPriority or (slotID + 1)
        local priorityText = ""
        if orderPriority == 1 then
            priorityText = "1st"
        elseif orderPriority == 2 then
            priorityText = "2nd"
        elseif orderPriority == 3 then
            priorityText = "3rd"
        elseif orderPriority == 4 then
            priorityText = "4th"
        else
            priorityText = "1st"
        end
        orderPriorityCombo:setCurrentOption(priorityText)
    end

    -- Atualizar contagem
    updateAllItemCounts()
end

-- Total owned across both dynamic forms (bag/unequipped + worn/equipped), so a
-- rule's count reflects the item even when only the worn variant is present.
function getEquipmentVariantCount(itemId)
    local total = getItemCountAnywhere(itemId) or 0
    local pair = getDynamicPairId and getDynamicPairId(itemId)
    if pair and pair ~= itemId then
        total = total + (getItemCountAnywhere(pair) or 0)
    end
    return total
end

-- Equip an item for an equipment-swap slot. cooldownKey is the spellsCooldown
-- bucket. Returns true when it handled the request (so the caller treats the
-- tick as consumed). The server resolves any copy via backpack + ring/amulet
-- pouches + reward pouch.
local function dispatchEquipForSlot(player, itemId, cooldownKey)
    if g_game.equipItemId then
        g_game.equipItemId(itemId, 0)
    else
        local item = Item.create(itemId)
        if item then
            g_game.equipItem(item)
        end
    end
    spellsCooldown[cooldownKey] = g_clock.millis() + getEngineIntervalValue("equipmentSwap")
    return true
end

function pushAmulet(amuletId)
    local player = g_game.getLocalPlayer()
    if not player then
        return
    end

    -- Tank Mode tem prioridade: bloquear apenas se o caller esta tentando equipar
    -- um amuleto DIFERENTE do escolhido pro tank mode (o proprio tank mode passa).
    if helperConfig.tankModeEnabled and helperConfig.tankModeAmuletEnabled ~= false then
        local tankModeAmuletId = helperConfig.tankModeAmuletId or 3081
        if tankModeAmuletId and tankModeAmuletId > 0 and amuletId ~= tankModeAmuletId then
            return
        end
    end

    if spellsCooldown["amulet"] and spellsCooldown["amulet"] > g_clock.millis() then
        return true
    end

    local slotAmulet = player:getInventoryItem(2)
    if slotAmulet then
        local equippedId = slotAmulet:getId()
        if equippedId == amuletId or isDynamicMatch(amuletId, equippedId) then
            return true
        end
    end

    -- Só envia equip se o player realmente tem o amuleto em qualquer lugar
    -- (inclui bp fechada via cache do server). Sem isto, perdíamos o tick
    -- para outras regras de swap quando o item preferido não estava no inv.
    if getItemCountAnywhere and (getItemCountAnywhere(amuletId) or 0) <= 0 then
        return
    end

    return dispatchEquipForSlot(player, amuletId, "amulet")
end

function getEquipmentRuleMeta(itemType)
    if itemType == "amulet" then
        return {
            configKey = "amulets",
            rulesListId = "equipmentRulesList",
            buttonPrefix = "amuletButton",
            enablePrefix = "enableAmulet",
            countPrefix = "amuletItemCount",
            itemWidgetId = "amuletItem"
        }
    elseif itemType == "ring" then
        return {
            configKey = "rings",
            rulesListId = "equipmentRulesList",
            buttonPrefix = "ringButton",
            enablePrefix = "enableRing",
            countPrefix = "ringItemCount",
            itemWidgetId = "ringItem"
        }
    end

    return nil
end

