function getEquipmentRulesListWidget(itemType)
    if not equipmentPanel then
        return nil
    end
    return equipmentPanel:recursiveGetChildById("equipmentRulesList")
end

function setEquipmentRuleEnabledByIndex(itemType, zeroIndex, enabledState)
    local meta = getEquipmentRuleMeta(itemType)
    if not meta then
        return
    end
    if type(helperConfig) ~= "table" then
        return
    end

    ensureEquipmentSwapConfig()

    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1

    local rules = helperConfig[meta.configKey] or {}
    local rule = rules[index]
    if type(rule) ~= "table" then
        return
    end

    local checked = enabledState == true
    if itemType == "amulet" then
        modules.game_helper.onEnableAmuletChanger(meta.enablePrefix .. (index - 1), checked)
    else
        modules.game_helper.onEnableRingChanger(meta.enablePrefix .. (index - 1), checked)
    end
end

function modules.game_helper.toggleEquipmentRuleEnabled(itemType, zeroIndex, explicitState)
    local meta = getEquipmentRuleMeta(itemType)
    if not meta then
        return
    end
    if type(helperConfig) ~= "table" then
        return
    end

    ensureEquipmentSwapConfig()

    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1

    local rules = helperConfig[meta.configKey] or {}
    local rule = rules[index]
    if type(rule) ~= "table" then
        return
    end

    local newState = explicitState
    if newState == nil then
        newState = not (rule.enabled == true)
    end
    setEquipmentRuleEnabledByIndex(itemType, index - 1, newState == true)

    if equipmentPanel then
        local row = equipmentPanel:recursiveGetChildById(itemType .. "RuleRow" .. (index - 1))
        if row then
            row.ruleEnabledState = newState == true
            setRuleRowEnabledIcon(row, newState == true)
        end
    end
end

function modules.game_helper.moveEquipmentRule(itemType, zeroIndex, direction)
    local meta = getEquipmentRuleMeta(itemType)
    if not meta then
        return
    end
    if type(helperConfig) ~= "table" then
        return
    end

    ensureEquipmentSwapConfig()

    local fromIndex = tonumber(zeroIndex)
    local offset = tonumber(direction)
    if not fromIndex or not offset or offset == 0 then
        return
    end

    fromIndex = fromIndex + 1
    local rules = helperConfig[meta.configKey] or {}
    local toIndex = fromIndex + offset

    if fromIndex < 1 or fromIndex > #rules or toIndex < 1 or toIndex > #rules then
        return
    end

    local movedRule = table.remove(rules, fromIndex)
    table.insert(rules, toIndex, movedRule)
    helperConfig[meta.configKey] = rules

    if equipmentSettingsPopup and not equipmentSettingsPopup:isDestroyed() and equipmentSettingsPopup.itemType == itemType then
        equipmentSettingsPopup:destroy()
        equipmentSettingsPopup = nil
    end

    rebuildEquipmentSwapRules(itemType)
    updateAllItemCounts()
    saveSettings()
end

function modules.game_helper.duplicateEquipmentRule(itemType, zeroIndex)
    local meta = getEquipmentRuleMeta(itemType)
    if not meta then
        return
    end
    if type(helperConfig) ~= "table" then
        return
    end

    ensureEquipmentSwapConfig()

    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1

    local rules = helperConfig[meta.configKey] or {}
    local sourceRule = rules[index]
    if type(sourceRule) ~= "table" then
        return
    end

    local clonedRule = ensureEquipmentSwapRule(deepCopy(sourceRule), itemType, index + 1)
    table.insert(rules, index + 1, clonedRule)
    helperConfig[meta.configKey] = rules

    rebuildAllEquipmentSwapRules()
    updateAllItemCounts()
    saveSettings()
end

function modules.game_helper.openEquipmentRuleContextMenu(itemType, zeroIndex, mousePos)
    local meta = getEquipmentRuleMeta(itemType)
    if not meta then
        return
    end
    if type(helperConfig) ~= "table" then
        return
    end

    ensureEquipmentSwapConfig()

    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1

    local rules = helperConfig[meta.configKey] or {}
    local rule = rules[index]
    if type(rule) ~= "table" then
        return
    end

    local menu = g_ui.createWidget("HelperPopupMenu")
    menu:setGameMenu(true)

    if index > 1 then
        menu:addOption(tr("Move Up"), function()
            modules.game_helper.moveEquipmentRule(itemType, index - 1, -1)
        end)
    end
    if index < #rules then
        menu:addOption(tr("Move Down"), function()
            modules.game_helper.moveEquipmentRule(itemType, index - 1, 1)
        end)
    end

    menu:addOption(tr("Edit"), function()
        modules.game_helper.openEquipmentSettingsPopup(itemType, index - 1)
    end)
    menu:addOption(tr("Duplicate"), function()
        modules.game_helper.duplicateEquipmentRule(itemType, index - 1)
    end)
    menu:addOption(tr("Delete"), function()
        confirmDeleteRule(tr("equipment"), function()
            modules.game_helper.removeEquipmentRule(itemType, index - 1)
        end)
    end)
    menu:addOption(rule.enabled and tr("Disable") or tr("Enable"), function()
        modules.game_helper.toggleEquipmentRuleEnabled(itemType, index - 1, not (rule.enabled == true))
    end)

    menu:display(mousePos or g_window.getMousePosition())
end

function equipmentRuleHasTriggerCondition(rule)
    if type(rule) ~= "table" then
        return false
    end

    return rule.alwaysEquipIfNone == true or
        rule.equipIfHPBelowEnabled == true or
        rule.equipIfHPAboveEnabled == true or
        rule.equipIfMPBelowEnabled == true or
        rule.equipIfMPAboveEnabled == true
end

function getEquipmentRuleTriggerChecks(rule, healthPercent, manaPercent)
    local checks = {}
    if rule.equipIfHPBelowEnabled == true then
        table.insert(checks, healthPercent <= (rule.equipIfHPBelow or 0))
    end
    if rule.equipIfHPAboveEnabled == true then
        table.insert(checks, healthPercent >= (rule.equipIfHPAbove or 0))
    end
    if rule.equipIfMPBelowEnabled == true then
        table.insert(checks, manaPercent <= (rule.equipIfMPBelow or 0))
    end
    if rule.equipIfMPAboveEnabled == true then
        table.insert(checks, manaPercent >= (rule.equipIfMPAbove or 0))
    end
    return checks
end

function evaluateEquipmentRuleTrigger(rule, healthPercent, manaPercent)
    local checks = getEquipmentRuleTriggerChecks(rule, healthPercent, manaPercent)
    if #checks == 0 then
        return false
    end

    local joinMode = tostring(rule.conditionJoinMode or ""):lower()
    if joinMode ~= "and" and joinMode ~= "or" and joinMode ~= "none" then
        joinMode = (rule.conditionUseAnd == true) and "and" or "or"
    end

    if joinMode == "none" then
        return checks[1] == true
    end

    if joinMode == "and" and #checks > 1 then
        for _, ok in ipairs(checks) do
            if not ok then
                return false
            end
        end
        return true
    end

    for _, ok in ipairs(checks) do
        if ok then
            return true
        end
    end
    return false
end

function evaluateEquipmentRuleStatusConditions(rule, player)
    if type(rule) ~= "table" then
        return true
    end

    local hasAnyStatusCondition =
        rule.conditionDrunk == true or
        rule.conditionRooted == true or
        rule.conditionFeared == true or
        rule.conditionParalyzed == true or
        rule.conditionPz == true or
        rule.conditionNonPz == true or
        rule.conditionDrowning == true or
        rule.conditionUtamoVita == true

    if not hasAnyStatusCondition then
        return true
    end

    if not player then
        return false
    end

    local states = 0
    if player.getStates and type(player.getStates) == "function" then
        states = tonumber(player:getStates()) or 0
    end

    local function hasState(stateFlag)
        if not stateFlag then
            return false
        end
        return bit.band(states, stateFlag) > 0
    end

    local inPz = hasState(PlayerStates and PlayerStates.Pz or nil)
    local requirePz = rule.conditionPz == true
    local requireNonPz = rule.conditionNonPz == true

    -- If both are enabled, treat as "any zone" (no PZ restriction).
    if not (requirePz and requireNonPz) then
        if requirePz and not inPz then
            return false
        end
        if requireNonPz and inPz then
            return false
        end
    end
    if rule.conditionDrunk == true and not hasState(PlayerStates and PlayerStates.Drunk or nil) then
        return false
    end
    if rule.conditionRooted == true and not hasState(PlayerStates and PlayerStates.Rooted or nil) then
        return false
    end
    if rule.conditionFeared == true and not hasState(PlayerStates and PlayerStates.Feared or nil) then
        return false
    end
    if rule.conditionParalyzed == true and not hasState(PlayerStates and PlayerStates.Paralyze or nil) then
        return false
    end
    if rule.conditionDrowning == true and not hasState(PlayerStates and PlayerStates.Drowning or nil) then
        return false
    end

    if rule.conditionUtamoVita == true then
        local hasUtamo = false
        if player.getManaShield and type(player.getManaShield) == "function" then
            local ok, shieldValue = pcall(player.getManaShield, player)
            hasUtamo = ok and (tonumber(shieldValue) or 0) > 0
        end
        if not hasUtamo then
            hasUtamo = hasState(PlayerStates and PlayerStates.ManaShield or nil)
        end
        if not hasUtamo then
            hasUtamo = hasState(PlayerStates and PlayerStates.NewManaShield or nil)
        end
        if not hasUtamo then
            return false
        end
    end

    return true
end

function isEquipmentRuleComplete(rule)
    if type(rule) ~= "table" then
        return false
    end

    local itemId = tonumber(rule.id) or 0
    if itemId <= 0 then
        return false
    end

    return equipmentRuleHasTriggerCondition(rule)
end

function formatEquipmentExcludeList(ids)
    local formatted = {}
    if type(ids) ~= "table" then
        return formatted
    end

    for _, id in ipairs(ids) do
        local parsed = tonumber(id) or 0
        if parsed > 0 then
            table.insert(formatted, resolveHelperItemNameById(parsed))
        end
    end

    return formatted
end

function resolveHelperItemNameById(itemId)
    local parsedItemId = tonumber(itemId) or 0
    if parsedItemId <= 0 then
        return ""
    end

    local itemName = ""
    if g_things and g_things.findItemTypeByClientId then
        local itemType = g_things.findItemTypeByClientId(parsedItemId)
        if itemType and itemType.getClientId and itemType:getClientId() ~= 0 then
            itemName = tostring((itemType.getName and itemType:getName()) or "")
            if itemName == "" and itemType.getMarketData then
                local marketData = itemType:getMarketData()
                if marketData and marketData.name then
                    itemName = tostring(marketData.name)
                end
            end
        end
    end

    if itemName == "" and g_things and g_things.getThingType then
        local thingType = g_things.getThingType(parsedItemId, ThingCategoryItem)
        if thingType and thingType:getId() > 0 then
            itemName = tostring((thingType.getName and thingType:getName()) or "")
            if itemName == "" and thingType.getMarketData then
                local marketData = thingType:getMarketData()
                if marketData and marketData.name then
                    itemName = tostring(marketData.name)
                end
            end
        end
    end

    if itemName == "" then
        itemName = "Unknown Item"
    end

    return itemName
end

function formatHelperItemIdAndName(itemId, itemName)
    local parsedItemId = tonumber(itemId) or 0
    if parsedItemId <= 0 then
        return ""
    end

    local displayName = tostring(itemName or "")
    if displayName == "" or displayName == "Unknown Item" then
        return "ID: " .. tostring(parsedItemId)
    end

    return "ID: " .. tostring(parsedItemId) .. " - " .. displayName
end

function buildEquipmentRuleSummary(itemType, ruleConfig)
    local whenParts = {}
    if ruleConfig.alwaysEquipIfNone == true then
        table.insert(whenParts, itemType == "amulet" and "no amulet equipped" or "no ring equipped")
    end
    if ruleConfig.equipIfHPBelowEnabled == true then
        table.insert(whenParts, "HP<=" .. tostring(ruleConfig.equipIfHPBelow or 0) .. "%")
    end
    if ruleConfig.equipIfHPAboveEnabled == true then
        table.insert(whenParts, "HP>=" .. tostring(ruleConfig.equipIfHPAbove or 0) .. "%")
    end
    if ruleConfig.equipIfMPBelowEnabled == true then
        table.insert(whenParts, "MP<=" .. tostring(ruleConfig.equipIfMPBelow or 0) .. "%")
    end
    if ruleConfig.equipIfMPAboveEnabled == true then
        table.insert(whenParts, "MP>=" .. tostring(ruleConfig.equipIfMPAbove or 0) .. "%")
    end

    local actionPrefix = (ruleConfig.actionType == "Unequip") and "Unequip if " or "Equip if "
    local mainItemName = resolveHelperItemNameById(ruleConfig.id)
    if mainItemName == "" or mainItemName == "Unknown Item" then
        mainItemName = (itemType == "amulet") and "Amulet" or "Ring"
    end
    local summary = mainItemName .. ": " .. actionPrefix
    if #whenParts == 0 then
        summary = summary .. "no condition"
    else
        local joiner = " OR "
        local joinMode = tostring(ruleConfig.conditionJoinMode or ""):lower()
        if joinMode ~= "and" and joinMode ~= "or" and joinMode ~= "none" then
            joinMode = ruleConfig.conditionUseAnd == true and "and" or "or"
        end
        if joinMode == "and" and #whenParts > 1 then
            joiner = " AND "
        end
        summary = summary .. table.concat(whenParts, joiner)
    end

    local extraParts = {}
    if ruleConfig.sourceType == "Backpack" then
        table.insert(extraParts, "from backpack")
    end
    if (tonumber(ruleConfig.tier) or 0) > 0 then
        table.insert(extraParts, "tier " .. tostring(ruleConfig.tier))
    end
    if ruleConfig.dontExecuteIfEquipped == true then
        local blockedNames = {}
        local ids = ruleConfig.dontExecuteItemIds
        if type(ids) ~= "table" then
            ids = { tonumber(ruleConfig.dontExecuteItemId) or 0, 0 }
        end
        for i = 1, 2 do
            local blockedId = tonumber(ids[i]) or 0
            if blockedId > 0 then
                table.insert(blockedNames, resolveHelperItemNameById(blockedId))
            end
        end
        if #blockedNames > 0 then
            table.insert(extraParts, "skip if equipped(" .. table.concat(blockedNames, ",") .. ")")
        end
    end

    local excludeAmulets = formatEquipmentExcludeList(ruleConfig.excludeAmuletIds)
    local excludeRings = formatEquipmentExcludeList(ruleConfig.excludeRingIds)
    if #excludeAmulets > 0 then
        table.insert(extraParts, "skip amulets(" .. table.concat(excludeAmulets, ",") .. ")")
    end
    if #excludeRings > 0 then
        table.insert(extraParts, "skip rings(" .. table.concat(excludeRings, ",") .. ")")
    end
    if itemType == "ring" and ruleConfig.respectEnergyRing == true then
        table.insert(extraParts, "respect energy ring")
    end

    local statusConditions = {}
    if ruleConfig.conditionDrunk == true then table.insert(statusConditions, "drunk") end
    if ruleConfig.conditionRooted == true then table.insert(statusConditions, "rooted") end
    if ruleConfig.conditionFeared == true then table.insert(statusConditions, "feared") end
    if ruleConfig.conditionParalyzed == true then table.insert(statusConditions, "paralyzed") end
    if ruleConfig.conditionPz == true then table.insert(statusConditions, "pz") end
    if ruleConfig.conditionNonPz == true then table.insert(statusConditions, "non-pz") end
    if ruleConfig.conditionDrowning == true then table.insert(statusConditions, "drowning") end
    if ruleConfig.conditionUtamoVita == true then table.insert(statusConditions, "utamo") end
    local statusSummary = ""
    if #statusConditions > 0 then
        statusSummary = "conditions(" .. table.concat(statusConditions, ",") .. ")"
    end

    if #extraParts > 0 then
        summary = summary .. " | " .. table.concat(extraParts, " | ")
    end
    if statusSummary ~= "" then
        summary = summary .. "\n" .. statusSummary
    end

    return summary
end

function pruneIncompleteEquipmentRules()
    if type(helperConfig) ~= "table" then
        return false
    end

    local changed = false
    local ruleSets = {
        { itemType = "amulet", key = "amulets" },
        { itemType = "ring",   key = "rings" }
    }

    for _, set in ipairs(ruleSets) do
        local rules = helperConfig[set.key] or {}
        for i = #rules, 1, -1 do
            rules[i] = ensureEquipmentSwapRule(rules[i], set.itemType, i)
            if not isEquipmentRuleComplete(rules[i]) then
                table.remove(rules, i)
                changed = true
            end
        end
        helperConfig[set.key] = rules
    end

    return changed
end

function getRuleRowBaseColorByOrder(rowOrder)
    local index = tonumber(rowOrder) or 1
    if (index % 2) == 1 then
        return "#0a0a0a"
    end
    return "#12121200"
end

function applyRuleRowBaseColor(row, rowOrder)
    if not row or row:isDestroyed() then
        return
    end
    local baseColor = getRuleRowBaseColorByOrder(rowOrder)
    row._baseBackgroundColor = baseColor
    if row._isSelected ~= true then
        row:setBackgroundColor(baseColor)
    end
end

