function confirmDeleteRule(moduleName, onConfirm)
    if type(onConfirm) ~= "function" then
        return
    end

    local messageBox = nil
    local closeBox = function()
        if messageBox and not messageBox:isDestroyed() then
            messageBox:destroy()
        end
        messageBox = nil
    end

    messageBox = helperDisplayGeneralBox(
        tr("Confirm Delete"),
        tr("Do you want to delete this %s rule?", tostring(moduleName or "module")),
        {
            { text = tr("Cancel"), callback = closeBox },
            {
                text = tr("Delete"),
                callback = function()
                    closeBox()
                    onConfirm()
                end
            }
        },
        closeBox,
        closeBox
    )
end

function getRuleSpellCooldownTiming(spellId, nowMs)
    local parsedSpellId = tonumber(spellId) or 0
    if parsedSpellId <= 0 then
        return nil
    end

    local now = tonumber(nowMs) or g_clock.millis()
    local endTime = tonumber(getSpellCooldown(parsedSpellId)) or 0
    if endTime <= now then
        return nil
    end

    local remaining = endTime - now
    local duration = 0
    local startedAt = now
    if helperEvents then
        helperEvents.spellCooldownDurations = helperEvents.spellCooldownDurations or {}
        helperEvents.spellCooldownStartedAt = helperEvents.spellCooldownStartedAt or {}
        duration = tonumber(helperEvents.spellCooldownDurations[parsedSpellId]) or 0
        startedAt = tonumber(helperEvents.spellCooldownStartedAt[parsedSpellId]) or now
    end

    if duration <= 0 then
        duration = remaining
        startedAt = now
    end

    local elapsed = now - startedAt
    if elapsed < 0 then
        elapsed = 0
    elseif elapsed > duration then
        elapsed = duration
    end

    local percent = (elapsed * 100) / math.max(duration, 1)
    if percent < 0 then
        percent = 0
    elseif percent > 100 then
        percent = 100
    end

    return {
        percent = percent,
        remainingMs = remaining
    }
end

function clearEquipmentRuleSelection()
    if not helperEvents then
        return
    end
    local previous = helperEvents.selectedEquipmentRuleRow
    if previous and not previous:isDestroyed() then
        previous._isSelected = false
        previous:setBackgroundColor(previous._baseBackgroundColor or "#0a0a0a")
    end
