function refreshEquipmentRuleRowColors()
    local rulesList = getEquipmentRulesListWidget("amulet")
    if not rulesList then
        return
    end

    local rowOrder = 0
    local children = rulesList:getChildren() or {}
    for _, child in ipairs(children) do
        local childId = child and child:getId() or ""
        if type(childId) == "string" and (childId:find("amuletRuleRow", 1, true) or childId:find("ringRuleRow", 1, true)) then
            rowOrder = rowOrder + 1
            applyRuleRowBaseColor(child, rowOrder)
        end
    end

    if helperEvents then
        local selected = helperEvents.selectedEquipmentRuleRow
        if selected and not selected:isDestroyed() and selected:getParent() == rulesList then
            selected._isSelected = true
            selected:setBackgroundColor("#ffffff18")
        else
            helperEvents.selectedEquipmentRuleRow = nil
        end
    end
end

function createEquipmentRuleRow(itemType, zeroIndex, ruleConfig, parentRulesList)
    local meta = getEquipmentRuleMeta(itemType)
    if not meta then
        return nil
    end
    ruleConfig = ensureEquipmentSwapRule(ruleConfig, itemType, zeroIndex + 1)

    local rulesList = parentRulesList or getEquipmentRulesListWidget(itemType)
    if not rulesList then
        return nil
    end

    local row = g_ui.createWidget("EquipmentSwapRuleRow", rulesList)
    if not row then
        return nil
    end

    row:setId(itemType .. "RuleRow" .. zeroIndex)
    local rulesListWidth = rulesList:getWidth() or 0
    if rulesListWidth > 0 then
        row:setWidth(math.max(1, rulesListWidth - 2))
    end
    row._isSelected = false
    row.ruleEnabledState = ruleConfig.enabled == true

    local itemButton = row:recursiveGetChildById("itemButton")
    local itemCell = row:recursiveGetChildById("itemCell")
    local statusIcon = row:recursiveGetChildById("statusIcon")
    local idLabel = row:recursiveGetChildById("idLabel")
    local summaryLabel = row:recursiveGetChildById("summaryLabel")
    local settingsButton = row:recursiveGetChildById("settingsButton")
    local removeButton = row:recursiveGetChildById("removeButton")
    local itemCount = row:recursiveGetChildById("itemCount")

    row._lastLeftClickMs = 0
    local function handleRowMouseRelease(self, mousePos, mouseButton)
        local now = g_clock.millis()
        if shouldIgnoreDuplicatedRowMouseRelease(row, mouseButton, now) then
            return true
        end

        selectEquipmentRuleRow(row)
        if mouseButton == MouseRightButton then
            modules.game_helper.openEquipmentRuleContextMenu(itemType, zeroIndex, mousePos)
            return true
        end
        if mouseButton == MouseLeftButton then
            if row._lastLeftClickMs > 0 and (now - row._lastLeftClickMs) <= EQUIPMENT_ROW_DOUBLE_CLICK_MS then
                row._lastLeftClickMs = 0
                modules.game_helper.toggleEquipmentRuleEnabled(itemType, zeroIndex)
                return true
            end
            row._lastLeftClickMs = now
        end
        return false
    end
    row.onMouseRelease = handleRowMouseRelease
    if statusIcon then
        statusIcon.onMouseRelease = handleRowMouseRelease
    end
    if idLabel then
        idLabel:setText(tostring((tonumber(zeroIndex) or 0) + 1))
        idLabel.onMouseRelease = handleRowMouseRelease
    end
    if summaryLabel then
        summaryLabel.onMouseRelease = handleRowMouseRelease
    end

    if itemButton then
        itemButton:setId(meta.buttonPrefix .. zeroIndex)
        itemButton.onMouseRelease = function(self)
            selectEquipmentRuleRow(row)
            updateButton(self)
            return true
        end
        itemButton.onClick = function(self)
            updateButton(self)
        end
        updateButton(itemButton)
        setEquipmentRuleButtonVisual(itemButton, itemType, ruleConfig.id or 0)
    end

    if itemCount then
        itemCount:setId(meta.countPrefix .. zeroIndex)
        itemCount:setVisible(false)
    end

    if summaryLabel then
        local summaryText = buildEquipmentRuleSummary(itemType, ruleConfig)
        summaryLabel:setText(summaryText)
        summaryLabel:setTooltip(summaryText)
        if string.find(summaryText, "\n", 1, true) then
            row:setHeight(44)
        else
            row:setHeight(34)
        end
    end

    setRuleRowEnabledIcon(row, row.ruleEnabledState)

    if settingsButton then
        settingsButton.onMouseRelease = function(self, mousePos, mouseButton)
            selectEquipmentRuleRow(row)
            if mouseButton == MouseRightButton then
                modules.game_helper.openEquipmentRuleContextMenu(itemType, zeroIndex, mousePos)
            end
            return true
        end
        settingsButton.onClick = function()
            modules.game_helper.openEquipmentSettingsPopup(itemType, zeroIndex)
        end
    end

    if removeButton then
        removeButton:setTooltip("Remove rule")
        removeButton.onMouseRelease = function(self, mousePos, mouseButton)
            selectEquipmentRuleRow(row)
            if mouseButton == MouseRightButton then
                modules.game_helper.openEquipmentRuleContextMenu(itemType, zeroIndex, mousePos)
            end
            return true
        end
        removeButton.onClick = function()
            confirmDeleteRule(tr("equipment"), function()
                modules.game_helper.removeEquipmentRule(itemType, zeroIndex)
            end)
        end
    end

    return row
end

function rebuildEquipmentSwapRules(itemType)
    rebuildAllEquipmentSwapRules()
end

function rebuildAllEquipmentSwapRules()
    if type(helperConfig) ~= "table" then
        return
    end

    ensureEquipmentSwapConfig()
    local removedInvalidRules = pruneIncompleteEquipmentRules()

    local rulesList = getEquipmentRulesListWidget("amulet")
    if not rulesList then
        return
    end

    clearEquipmentRuleSelection()
    rulesList:destroyChildren()

    local amuletRules = helperConfig.amulets or {}
    local ringRules = helperConfig.rings or {}

    for idx, rule in ipairs(amuletRules) do
        createEquipmentRuleRow("amulet", idx - 1, rule, rulesList)
    end

    for idx, rule in ipairs(ringRules) do
        createEquipmentRuleRow("ring", idx - 1, rule, rulesList)
    end

    if #amuletRules == 0 and #ringRules == 0 then
        local emptyLabel = g_ui.createWidget("Label", rulesList)
        if emptyLabel then
            emptyLabel:setId("equipmentRulesEmpty")
            emptyLabel:setText("No equipment rules. Click add equipment")
            emptyLabel:setColor("#808080")
            emptyLabel:setFont("verdana-11px-monochrome")
            emptyLabel:setMarginTop(4)
            emptyLabel:setMarginLeft(2)
        end
    end

    rulesList:updateLayout()
    refreshEquipmentRuleRowColors()

    if removedInvalidRules then
        saveSettings()
    end
end

