function resolveHealingItemName(itemId)
    local parsed = tonumber(itemId) or 0
    if parsed <= 0 then
        return ""
    end
    local itemName = ""

    if g_things and g_things.findItemTypeByClientId then
        local itemType = g_things.findItemTypeByClientId(parsed)
        if itemType and itemType.getClientId and itemType:getClientId() ~= 0 then
            itemName = tostring((itemType.getName and itemType:getName()) or "")
            if itemName == "" and itemType.getMarketData then
                local marketData = itemType:getMarketData()
                if marketData and marketData.name then
                    itemName = tostring(marketData.name)
                end
            end
        end
    end

    if itemName == "" and g_things and g_things.getThingType then
        local thingType = g_things.getThingType(parsed, ThingCategoryItem)
        if thingType and thingType:getId() > 0 then
            itemName = tostring((thingType.getName and thingType:getName()) or "")
            if itemName == "" and thingType.getMarketData then
                local marketData = thingType:getMarketData()
                if marketData and marketData.name then
                    itemName = tostring(marketData.name)
                end
            end
        end
    end

    if itemName == "" then
        itemName = "Unknown Item"
    end

    return itemName
end

function resolveHealingSpellName(spellWords)
    local words = trimHealingText(spellWords)
    if words == "" then
        return ""
    end

    local spell = getCachedSpell(words)
    if spell then
        local spellName = tostring(spell.name or "")
        if spellName ~= "" then
            return spellName
        end
    end

    return words
end

function getHealingSpellIconData(spellWords)
    local words = trimHealingText(spellWords)
    if words == "" then
        return nil, nil, ""
    end

    local spell = getCachedSpell(words)
    if not spell then
        return nil, nil, words
    end

    local spellName = tostring(spell.name or "")
    if spellName == "" then
        spellName = words
    end

    if SpellIcons and spell.icon and SpellIcons[spell.icon] and SpelllistSettings then
        local iconData = SpellIcons[spell.icon]
        local spellIconId = iconData and iconData[1] or nil
        local spellProfile = iconData and iconData[3] or "Default"
        if SpelllistSettings[spellProfile] then
            local source = SpelllistSettings[spellProfile].iconsFolder
            local clip = spellIconId and Spells.getImageClip and Spells.getImageClipNormal(spellIconId, spellProfile) or
            nil
            if source and clip then
                return source, clip, spellName
            end
        end
    end

    return nil, nil, spellName
end

function buildHealingRuleWhenSummary(ruleConfig)
    local rule = ensureHealingRule(ruleConfig, 1)
    local left = string.format("%s %s %d", tostring(rule.whenMetric1), tostring(rule.whenOperator1),
        tonumber(rule.whenValue1) or 0)
    local joinMode = normalizeHealingJoinMode(rule.joinMode)
    if joinMode == "none" then
        return left
    end
    local joinText = joinMode == "and" and " AND " or " OR "
    local right = string.format("%s %s %d", tostring(rule.whenMetric2), tostring(rule.whenOperator2),
        tonumber(rule.whenValue2) or 0)
    return left .. joinText .. right
end

function buildHealingRuleRowData(ruleConfig)
    local rule = ensureHealingRule(ruleConfig, 1)
    local whenSummary = buildHealingRuleWhenSummary(rule)
    local nameText = ""
    if rule.actionType == "Item" then
        nameText = resolveHealingItemName(rule.itemId)
    else
        nameText = resolveHealingSpellName(rule.spellWords)
    end
    if nameText == "" then
        nameText = rule.actionType == "Item" and "Unknown Item" or "Unknown Spell"
    end
    local statusParts = {}
    if rule.conditionDrunk then table.insert(statusParts, "drunk") end
    if rule.conditionRooted then table.insert(statusParts, "rooted") end
    if rule.conditionFeared then table.insert(statusParts, "feared") end
    if rule.dontCastIfTargetingMonster then table.insert(statusParts, "no-target") end
    local conditionsText = ""
    if #statusParts > 0 then
        conditionsText = "[" .. table.concat(statusParts, ",") .. "]"
    end
    return nameText, whenSummary, conditionsText
end

function setHealingRuleItemVisual(itemButton, itemCountLabel, ruleConfig)
    if not itemButton then
        return
    end

    local rule = ensureHealingRule(ruleConfig, 1)
    local cell = itemButton:getParent()
    local spellMarker = cell and cell:getChildById("spellMarker") or nil
    local itemWidget = itemButton:getChildById("healingRuleItem")

    if rule.actionType == "Item" then
        if spellMarker then
            spellMarker:setVisible(false)
        end
        local itemId = tonumber(rule.itemId) or 0
        if itemId > 0 then
            itemButton:setImageSource("/images/ui/item")
            itemButton:setImageClip("0 0 34 34")
            if not itemWidget then
                itemWidget = g_ui.createWidget("PotionItem", itemButton)
                if itemWidget then
                    itemWidget:setId("healingRuleItem")
                end
            end
            if itemWidget then
                itemWidget:setItemCount(0)
                itemWidget:setItemId(itemId)
                local itemCount = tonumber(rule.itemCount) or 0
                if itemCount > 1 then
                    itemWidget:setItemCount(itemCount)
                end
            end
            itemButton:setTooltip(resolveHealingItemName(itemId))
        else
            if itemWidget then
                itemWidget:destroy()
            end
            itemButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
            itemButton:setImageClip("0 0 34 34")
            itemButton:setTooltip("")
        end
    else
        if itemWidget then
            itemWidget:destroy()
        end
        local iconSource, iconClip, spellName = getHealingSpellIconData(rule.spellWords)
        if iconSource and iconClip then
            if spellMarker then
                spellMarker:setVisible(false)
            end
            itemButton:setImageSource(iconSource)
            itemButton:setImageClip(iconClip)
            itemButton:setTooltip(spellName)
        else
            if spellMarker then
                spellMarker:setVisible(true)
            end
            itemButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
            itemButton:setImageClip("0 0 34 34")
            itemButton:setTooltip(resolveHealingSpellName(rule.spellWords))
        end
    end

    if itemCountLabel then
        itemCountLabel:setVisible(false)
    end
end

function getHealingRuleCooldownSpellId(ruleConfig)
    local rule = ensureHealingRule(ruleConfig, 1)
    if rule.actionType ~= "Spell" then
        return 0
    end

    local words = trimHealingText(rule.spellWords)
    if words == "" then
        return 0
    end

    local spell = getCachedSpell(words)

    if type(spell) ~= "table" then
        return 0
    end
    return tonumber(spell.id) or 0
end

function ensureHealingRuleCooldownOverlay(row)
    if not row or row:isDestroyed() then
        return nil
    end

    local itemButton = row:recursiveGetChildById("itemButton")
    if not itemButton then
        return nil
    end

    local overlay = itemButton:getChildById("healingRuleCooldownOverlay")
    if not overlay then
        overlay = g_ui.createWidget("SpellProgressRect", itemButton)
        if not overlay then
            overlay = g_ui.createWidget("UIProgressRect", itemButton)
        end
        if not overlay then
            return nil
        end
        overlay:setId("healingRuleCooldownOverlay")
        overlay:fill("parent")
        overlay:setText("")
        overlay:setPhantom(true)
        overlay:setFocusable(false)
    end

    return overlay
end

function hideHealingRuleCooldownOverlay(row)
    if not row or row:isDestroyed() then
        return
    end
    local itemButton = row:recursiveGetChildById("itemButton")
    if not itemButton then
        return
    end
    local overlay = itemButton:getChildById("healingRuleCooldownOverlay")
    if overlay then
        overlay:setPercent(100)
        overlay:setText("")
        overlay:hide()
    end
end

function updateHealingRuleCooldownOverlay(row, ruleConfig, nowMs)
    if not row or row:isDestroyed() then
        return
    end

    local spellId = getHealingRuleCooldownSpellId(ruleConfig)
    if spellId <= 0 then
        hideHealingRuleCooldownOverlay(row)
        return
    end

    local timing = getRuleSpellCooldownTiming(spellId, nowMs)
    if not timing then
        hideHealingRuleCooldownOverlay(row)
        return
    end

    local overlay = ensureHealingRuleCooldownOverlay(row)
    if not overlay then
        return
    end

    overlay:setPercent(timing.percent or 0)
    overlay:setText("")
    overlay:show()
end

function refreshAllHealingRuleCooldownOverlays()
    local rulesList = getHealingRulesListWidget()
    if not rulesList or not helperConfig then
        return
    end

    local now = g_clock.millis()
    local rules = helperConfig.healingRules or {}
    for i = 1, #rules do
        local row = rulesList:recursiveGetChildById("healingRuleRow" .. tostring(i))
        if row then
            updateHealingRuleCooldownOverlay(row, rules[i], now)
        end
    end
end

function createHealingRuleRow(zeroIndex, ruleConfig, parentRulesList)
    local rulesList = parentRulesList or getHealingRulesListWidget()
    if not rulesList then
        return nil
    end

    local row = g_ui.createWidget("HealingRuleRow", rulesList)
    if not row then
        return nil
    end

    local index = (tonumber(zeroIndex) or 0) + 1
    local normalizedRule = ensureHealingRule(ruleConfig, index)
    row:setId("healingRuleRow" .. tostring(index))
    row._isSelected = false
    row._lastLeftClickMs = 0

    local rulesListWidth = rulesList:getWidth() or 0
    if rulesListWidth > 0 then
        row:setWidth(math.max(1, rulesListWidth - 2))
    end

    local idLabel = row:recursiveGetChildById("idLabel")
    local statusIcon = row:recursiveGetChildById("statusIcon")
    local itemButton = row:recursiveGetChildById("itemButton")
    local itemCountLabel = row:recursiveGetChildById("itemCount")
    local nameLabel = row:recursiveGetChildById("nameLabel")
    local whenLabel = row:recursiveGetChildById("whenLabel")
    local settingsButton = row:recursiveGetChildById("settingsButton")
    local removeButton = row:recursiveGetChildById("removeButton")

    row.ruleNameText, row.ruleWhenText, row.ruleConditionsText = buildHealingRuleRowData(normalizedRule)
    row.ruleEnabledState = normalizedRule.enabled == true

    if idLabel then
        idLabel:setText(tostring(index))
    end
    if nameLabel then
        nameLabel:setText(row.ruleNameText)
        nameLabel:setTooltip(row.ruleNameText)
    end
    if whenLabel then
        local rowText = row.ruleWhenText or ""
        if row.ruleConditionsText and row.ruleConditionsText ~= "" then
            rowText = rowText .. "\n" .. row.ruleConditionsText
            row:setHeight(44)
        else
            row:setHeight(34)
        end
        whenLabel:setText(rowText)
        whenLabel:setTooltip(rowText)
    end
    setRuleRowEnabledIcon(row, row.ruleEnabledState)
    setHealingRuleItemVisual(itemButton, itemCountLabel, normalizedRule)
    updateHealingRuleCooldownOverlay(row, normalizedRule)

    local function onRowMouseRelease(self, mousePos, mouseButton)
        local now = g_clock.millis()
        if shouldIgnoreDuplicatedRowMouseRelease(row, mouseButton, now) then
            return true
        end

        selectHealingRuleRow(row)
        if mouseButton == MouseRightButton then
            modules.game_helper.openHealingRuleContextMenu(zeroIndex, mousePos)
            return true
        end
        if mouseButton == MouseLeftButton then
            if row._lastLeftClickMs > 0 and (now - row._lastLeftClickMs) <= HEALING_ROW_DOUBLE_CLICK_MS then
                row._lastLeftClickMs = 0
                modules.game_helper.toggleHealingRuleEnabled(zeroIndex)
                return true
            end
            row._lastLeftClickMs = now
        end
        return false
    end

    row.onMouseRelease = onRowMouseRelease
    if idLabel then idLabel.onMouseRelease = onRowMouseRelease end
    if statusIcon then statusIcon.onMouseRelease = onRowMouseRelease end
    if nameLabel then nameLabel.onMouseRelease = onRowMouseRelease end
    if whenLabel then whenLabel.onMouseRelease = onRowMouseRelease end

    if itemButton then
        itemButton.onMouseRelease = function(self, mousePos, mouseButton)
            if mouseButton == MouseRightButton then
                modules.game_helper.openHealingRuleContextMenu(zeroIndex, mousePos)
                return true
            end
            return onRowMouseRelease(self, mousePos, mouseButton)
        end
        itemButton.onClick = function()
            modules.game_helper.editHealingRule(zeroIndex)
        end
    end

    if settingsButton then
        settingsButton.onMouseRelease = function(self, mousePos, mouseButton)
            selectHealingRuleRow(row)
            if mouseButton == MouseRightButton then
                modules.game_helper.openHealingRuleContextMenu(zeroIndex, mousePos)
            end
            return true
        end
        settingsButton.onClick = function()
            modules.game_helper.editHealingRule(zeroIndex)
        end
    end

    if removeButton then
        removeButton.onMouseRelease = function(self, mousePos, mouseButton)
            selectHealingRuleRow(row)
            if mouseButton == MouseRightButton then
                modules.game_helper.openHealingRuleContextMenu(zeroIndex, mousePos)
            end
            return true
        end
        removeButton.onClick = function()
            confirmDeleteRule(tr("healing"), function()
                modules.game_helper.removeHealingRule(zeroIndex)
            end)
        end
    end

    return row
end

function rebuildAllHealingRules()
    if type(helperConfig) ~= "table" then
        return
    end

    ensureHealingRulesConfig(HEALING_DEFAULT_RULE_COUNT)
    local rulesList = getHealingRulesListWidget()
    if not rulesList then
        return
    end

    clearHealingRuleSelection()
    rulesList:destroyChildren()

    local rules = helperConfig.healingRules or {}
    for i = 1, #rules do
        helperConfig.healingRules[i] = ensureHealingRule(rules[i], i)
        createHealingRuleRow(i - 1, helperConfig.healingRules[i], rulesList)
    end

    if #rules == 0 then
        local emptyLabel = g_ui.createWidget("Label", rulesList)
        if emptyLabel then
            emptyLabel:setId("healingRulesEmpty")
            emptyLabel:setText("No healing rules. Click add healing")
            emptyLabel:setColor("#808080")
            emptyLabel:setFont("verdana-11px-monochrome")
            emptyLabel:setMarginTop(4)
            emptyLabel:setMarginLeft(2)
        end
    end

    rulesList:updateLayout()
    refreshHealingRuleRowColors()
    refreshAllHealingRuleCooldownOverlays()
    startSpellRuleCooldownOverlayLoop()
end

function modules.game_helper.toggleHealingRuleEnabled(zeroIndex, explicitState)
    ensureHealingRulesConfig()
    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1
    local rules = helperConfig.healingRules or {}
    if not rules[index] then
        return
    end

    local newState = explicitState
    if newState == nil then
        newState = not (rules[index].enabled == true)
    end
    rules[index].enabled = newState == true
    helperConfig.healingRules = rules

    local row = getHealingRulesListWidget() and
    getHealingRulesListWidget():recursiveGetChildById("healingRuleRow" .. index) or nil
    if row then
        row.ruleEnabledState = newState == true
        setRuleRowEnabledIcon(row, newState == true)
    end

    saveSettings()
end

function modules.game_helper.moveHealingRule(zeroIndex, direction)
    ensureHealingRulesConfig()
    local fromIndex = tonumber(zeroIndex)
    local offset = tonumber(direction)
    if not fromIndex or not offset or offset == 0 then
        return
    end
    fromIndex = fromIndex + 1
    local rules = helperConfig.healingRules or {}
    local toIndex = fromIndex + offset
    if fromIndex < 1 or fromIndex > #rules or toIndex < 1 or toIndex > #rules then
        return
    end

    local moved = table.remove(rules, fromIndex)
    table.insert(rules, toIndex, moved)
    for i = 1, #rules do
        rules[i] = ensureHealingRule(rules[i], i)
        rules[i].orderPriority = i
    end
    helperConfig.healingRules = rules

    rebuildAllHealingRules()
    saveSettings()
end

function modules.game_helper.removeHealingRule(zeroIndex)
    ensureHealingRulesConfig()
    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1
    local rules = helperConfig.healingRules or {}
    if index < 1 or index > #rules then
        return
    end

    table.remove(rules, index)
    for i = 1, #rules do
        rules[i] = ensureHealingRule(rules[i], i)
        rules[i].orderPriority = i
    end
    helperConfig.healingRules = rules

    rebuildAllHealingRules()
    saveSettings()
end

function modules.game_helper.duplicateHealingRule(zeroIndex)
    ensureHealingRulesConfig()
    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1

    local rules = helperConfig.healingRules or {}
    local sourceRule = rules[index]
    if type(sourceRule) ~= "table" then
        return
    end

    local clonedRule = ensureHealingRule(deepCopy(sourceRule), index + 1)
    table.insert(rules, index + 1, clonedRule)
    for i = 1, #rules do
        rules[i] = ensureHealingRule(rules[i], i)
        rules[i].orderPriority = i
    end
    helperConfig.healingRules = rules

    rebuildAllHealingRules()
    saveSettings()
end

function modules.game_helper.editHealingRule(zeroIndex)
    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    modules.game_helper.openHealingSettingsPopup(index, nil, false)
end

function modules.game_helper.openHealingRuleContextMenu(zeroIndex, mousePos)
    ensureHealingRulesConfig()
    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1

    local rules = helperConfig.healingRules or {}
    local rule = rules[index]
    if type(rule) ~= "table" then
        return
    end

    local menu = g_ui.createWidget("HelperPopupMenu")
    menu:setGameMenu(true)

    if index > 1 then
        menu:addOption(tr("Move Up"), function()
            modules.game_helper.moveHealingRule(index - 1, -1)
        end)
    end
    if index < #rules then
        menu:addOption(tr("Move Down"), function()
            modules.game_helper.moveHealingRule(index - 1, 1)
        end)
    end

    menu:addOption(tr("Edit"), function()
        modules.game_helper.editHealingRule(index - 1)
    end)
    menu:addOption(tr("Duplicate"), function()
        modules.game_helper.duplicateHealingRule(index - 1)
    end)
    menu:addOption(tr("Delete"), function()
        confirmDeleteRule(tr("healing"), function()
            modules.game_helper.removeHealingRule(index - 1)
        end)
    end)
    menu:addOption(rule.enabled and tr("Disable") or tr("Enable"), function()
        modules.game_helper.toggleHealingRuleEnabled(index - 1, not (rule.enabled == true))
    end)

    menu:display(mousePos or g_window.getMousePosition())
end

function modules.game_helper.addHealingRule(initialRule)
    ensureHealingRulesConfig()
    local nextIndex = #((helperConfig and helperConfig.healingRules) or {}) + 1
    local newRule = ensureHealingRule(initialRule or createDefaultHealingRule(nextIndex), nextIndex)
    newRule.enabled = true
    modules.game_helper.openHealingSettingsPopup(nil, newRule, true)
end

function modules.game_helper.openAddHealingRulePopup()
    modules.game_helper.addHealingRule(createDefaultHealingRule((#((helperConfig and helperConfig.healingRules) or {})) +
    1))
end

function getHealingSettingsPopupWidget()
    if healingSettingsPopup and healingSettingsPopup:isDestroyed() then
        healingSettingsPopup = nil
    end
    if healingSettingsPopup then
        return healingSettingsPopup
    end

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return nil
    end

    local popup = rootWidget:recursiveGetChildById("healingSettingsPopup")
    if popup and not popup:isDestroyed() then
        healingSettingsPopup = popup
    end
    return healingSettingsPopup
end

function getHealingPopupComboText(combo, fallback)
    if not combo then
        return fallback
    end
    local current = combo:getCurrentOption()
    if not current or not current.text then
        return fallback
    end
    local text = tostring(current.text)
    if text == "" then
        return fallback
    end
    return text
end

function setHealingPopupComboValue(combo, desiredText, fallbackText)
    if not combo then
        return
    end
    combo:setCurrentOption(desiredText or fallbackText)
    local current = combo:getCurrentOption()
    if not current and fallbackText then
        combo:setCurrentOption(fallbackText)
    end
end

function updateHealingPopupSecondConditionState()
    local popup = getHealingSettingsPopupWidget()
    if not popup then
        return
    end

    local joinModeCombo = popup:recursiveGetChildById("joinModeCombo")
    local metric2Combo = popup:recursiveGetChildById("metric2Combo")
    local op2Combo = popup:recursiveGetChildById("op2Combo")
    local value2Input = popup:recursiveGetChildById("value2Input")

    local joinText = string.lower(getHealingPopupComboText(joinModeCombo, "None"))
    local secondEnabled = joinText ~= "none"

    if metric2Combo then
        metric2Combo:setVisible(secondEnabled)
        metric2Combo:setEnabled(secondEnabled)
    end
    if op2Combo then
        op2Combo:setVisible(secondEnabled)
        op2Combo:setEnabled(secondEnabled)
    end
    if value2Input then
        value2Input:setVisible(secondEnabled)
        value2Input:setEnabled(secondEnabled)
    end
end

function refreshHealingPopupItemButtonVisual()
    local popup = getHealingSettingsPopupWidget()
    if not popup then
        return
    end

    local itemButton = popup:recursiveGetChildById("itemPreviewButton")
    local itemInput = popup:recursiveGetChildById("itemIdInput")
    if not itemButton then
        return
    end

    local itemId = tonumber(popup._itemId) or 0
    if itemInput then
        local targetText = itemId > 0 and tostring(itemId) or ""
        local currentText = itemInput:getText() or ""
        if currentText ~= targetText then
            local oldOnTextChange = itemInput.onTextChange
            itemInput.onTextChange = nil
            itemInput:setText(targetText)
            itemInput.onTextChange = oldOnTextChange
        end
    end

    local itemWidget = itemButton:getChildById("healingPopupItem")
    if itemId > 0 then
        itemButton:setImageSource("/images/ui/item")
        if not itemWidget then
            itemWidget = g_ui.createWidget("PotionItem", itemButton)
            if itemWidget then
                itemWidget:setId("healingPopupItem")
            end
        end

        if itemWidget then
            itemWidget:setItemCount(0)
            itemWidget:setItemId(itemId)
        end

        local itemName = resolveHealingItemName(itemId)
        itemButton:setTooltip(itemName)
        if itemInput then
            itemInput:setTooltip(itemName)
        end
    else
        if itemWidget then
            itemWidget:destroy()
        end
        itemButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
        itemButton:setTooltip("")
        if itemInput then
            itemInput:setTooltip("")
        end
    end
end

function modules.game_helper.setHealingPopupItemId(itemId, itemCount)
    local popup = getHealingSettingsPopupWidget()
    if not popup then
        return
    end

    local parsedItemId = tonumber(itemId) or 0
    if parsedItemId < 0 then
        parsedItemId = 0
    end

    local parsedCount = tonumber(itemCount) or 1
    if parsedItemId <= 0 then
        parsedCount = 0
    elseif parsedCount < 1 then
        parsedCount = 1
    end

    popup._itemId = parsedItemId
    popup._itemCount = parsedCount
    if type(popup._draftRule) ~= "table" then
        popup._draftRule = createDefaultHealingRule(1)
    end
    popup._draftRule.itemId = parsedItemId
    popup._draftRule.itemCount = parsedCount

    if parsedItemId > 0 then
        modules.game_helper.selectHealingPopupActionTab("item")
    end

    refreshHealingPopupItemButtonVisual()
end

function modules.game_helper.removeHealingPopupItem()
    modules.game_helper.setHealingPopupItemId(0, 0)
end

function modules.game_helper.onHealingPopupItemDrop(targetWidget, draggedWidget, mousePos)
    local popup = getHealingSettingsPopupWidget()
    if not popup then
        return false
    end

    local draggedItemId = getEquipmentPopupDraggedItemId(draggedWidget, mousePos)
    if draggedItemId <= 0 then
        return false
    end

    modules.game_helper.setHealingPopupItemId(draggedItemId, 1)
    return true
end

function modules.game_helper.startHealingPopupItemSelection()
    if not mouseGrabberWidget then
        return
    end

    local popup = getHealingSettingsPopupWidget()
    mouseGrabberWidget:grabMouse()
    if popup then
        popup:hide()
    end
    g_mouse.pushCursor("target")

    mouseGrabberWidget.onMouseRelease = function(self, mousePosition, mouseButton)
        if mouseGrabberWidget then
            mouseGrabberWidget:ungrabMouse()
            mouseGrabberWidget.onMouseRelease = nil
        end
        if popup and not popup:isDestroyed() then
            popup:show()
        end
        g_mouse.popCursor("target")

        if mouseButton ~= MouseLeftButton then
            return true
        end

        local rootWidget = g_ui.getRootWidget()
        if not rootWidget then
            return true
        end

        local clickedWidget = rootWidget:recursiveGetChildByPos(mousePosition, false)
        if not clickedWidget then
            return true
        end

        local item = nil
        if clickedWidget:getClassName() == "UIItem" and not clickedWidget:isVirtual() then
            item = clickedWidget:getItem()
        elseif clickedWidget:getClassName() == "UIGameMap" then
            local tile = clickedWidget:getTile(mousePosition)
            if tile then
                local topUseThing = tile:getTopUseThing()
                if topUseThing and topUseThing:isItem() then
                    item = topUseThing
                end
            end
        end

        if not item then
            modules.game_textmessage.displayFailureMessage(tr("Invalid item!"))
            return true
        end

        modules.game_helper.setHealingPopupItemId(item:getId(), item:getCount())
        return true
    end
end

function modules.game_helper.openHealingPopupItemMenu(button, mousePos)
    local popup = getHealingSettingsPopupWidget()
    if not popup then
        return
    end

    local currentItemId = tonumber(popup._itemId) or 0
    local menu = g_ui.createWidget("HelperPopupMenu")
    menu:setGameMenu(true)
    menu:addOption(tr("Select Item"), function()
        modules.game_helper.startHealingPopupItemSelection()
    end)
    menu:addOption(tr("Assign ID"), function()
        openAssignItemIdWindow(button, "healingPopupItem")
    end)
    menu:addOption(tr("Assign List"), function()
        openAssignItemListWindow(button, "healingPopupItem")
    end)
    if currentItemId > 0 then
        menu:addOption(tr("Remove"), function()
            modules.game_helper.removeHealingPopupItem()
        end)
    end
    menu:display(mousePos or g_window.getMousePosition())
end

function getHealingPopupCurrentSpellWords(popup)
    if not popup or popup:isDestroyed() then
        return ""
    end
    local fromPopup = trimHealingText(popup._spellWords or "")
    if fromPopup ~= "" then
        return fromPopup
    end
    if type(popup._draftRule) == "table" then
        return trimHealingText(popup._draftRule.spellWords or "")
    end
    return ""
end

function refreshHealingPopupSpellSelectionVisual()
    local popup = getHealingSettingsPopupWidget()
    if not popup then
        return
    end

    local spellButton = popup:recursiveGetChildById("spellSelectButton")
    local spellPreviewButton = popup:recursiveGetChildById("spellPreviewButton")
    if not spellButton then
        return
    end

    local words = getHealingPopupCurrentSpellWords(popup)
    if words == "" then
        spellButton:setText("Select Spell")
        spellButton:setTooltip("")
        if spellPreviewButton then
            spellPreviewButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
            spellPreviewButton:setImageClip("0 0 34 34")
            spellPreviewButton:setTooltip("")
        end
        return
    end

    local spell = getCachedSpell(words)
    local spellName = words
    if spell and spell.name and tostring(spell.name) ~= "" then
        spellName = tostring(spell.name)
    end

    local buttonText = spellName
    if #buttonText > 20 then
        buttonText = string.sub(buttonText, 1, 17) .. "..."
    end

    local iconSource, iconClip = getHealingSpellIconData(words)

    spellButton:setText(buttonText)
    spellButton:setTooltip("Spell: " .. spellName .. "\nWords: " .. words)
    if spellPreviewButton then
        if iconSource and iconClip then
            spellPreviewButton:setImageSource(iconSource)
            spellPreviewButton:setImageClip(iconClip)
        else
            spellPreviewButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
            spellPreviewButton:setImageClip("0 0 34 34")
        end
        spellPreviewButton:setTooltip("Spell: " .. spellName .. "\nWords: " .. words)
    end
end

function modules.game_helper.openHealingPopupSpellSelector()
    local popup = getHealingSettingsPopupWidget()
    if not popup then
        return
    end

    if toggleAssignSpellWindow() then
        return
    end

    local playerObj = g_game.getLocalPlayer()
    if not playerObj then
        modules.game_textmessage.displayFailureMessage(tr("Player not available."))
        return
    end

    if not SpellInfo then
        modules.game_textmessage.displayFailureMessage(tr("Spell list unavailable."))
        return
    end

    local window = g_ui.loadUI("styles/spell", g_ui.getRootWidget())
    if not window then
        modules.game_textmessage.displayFailureMessage(tr("Failed to open spell list."))
        return
    end
    applyOpacityToWindow(window)

    local playerVocation = translateVocation(playerObj:getVocation())
    local currentWords = getHealingPopupCurrentSpellWords(popup)
    local radio = UIRadioGroup.create()
    local preselectedWidget = nil
    local spellCount = 0

    window:show(true)
    window:raise()
    window:focus()
    window:setText("Assign Healing Spell")
    safeSetInputLockWidget(window)
    popup:hide()

    local tickCheck = window:recursiveGetChildById("tick")
    if tickCheck then
        tickCheck:setChecked(true)
        tickCheck:setEnabled(false)
    end

    local applyButton = window:recursiveGetChildById("buttonApply")
    if applyButton then
        applyButton:setVisible(false)
    end

    for profileName, spells in pairs(SpellInfo) do
        if type(spells) ~= "table" then goto continue_healing_profile end
        for spellName, spellData in pairs(spells) do
            if type(spellData) ~= 'table' or not spellData.id then goto continue_healing_popup_spell end
            local spellVocations = spellData and spellData.vocations or {}
            if not table.contains(spellVocations, playerVocation) then
                goto continue_healing_popup_spell
            end

            local groupIds = Spells.getGroupIds(spellData)
            local isHealingSpell = table.contains(groupIds, 2)
            if not isHealingSpell then
                local category = string.lower(tostring(spellData.category or ""))
                isHealingSpell = category == "healing"
            end
            if not isHealingSpell then
                goto continue_healing_popup_spell
            end

            local words = trimHealingText(spellData.words or "")
            if words == "" then
                goto continue_healing_popup_spell
            end

            local widget = g_ui.createWidget("SpellPreview", window.contentPanel.spellList)
            if not widget then
                goto continue_healing_popup_spell
            end

            local spellIconId = nil
            if SpellIcons and spellData.icon and SpellIcons[spellData.icon] then
                spellIconId = SpellIcons[spellData.icon][1]
            end

            local displayName = tostring(spellData.name or spellName or words)
            if displayName == "" then
                displayName = words
            end

            radio:addWidget(widget)
            widget:setId(tonumber(spellData.id) or 0)
            widget:setText(displayName .. "\n" .. words)
            widget.spellWords = words
            widget.spellName = displayName
            -- Spells whose words end in "sio" cast on a named target (e.g. exura sancto sio "Player")
            widget.param = string.match(words:lower(), "%ssio$") ~= nil or words:lower() == "sio"
            widget.source = SpelllistSettings and SpelllistSettings[profileName] and
            SpelllistSettings[profileName].iconsFolder or ""
            widget.clip = spellIconId and Spells.getImageClip and Spells.getImageClipNormal(spellIconId, profileName) or
            nil
            if widget.source and widget.source ~= "" then
                widget.image:setImageSource(widget.source)
            end
            if widget.clip then
                widget.image:setImageClip(widget.clip)
            end

            if spellData.level then
                widget.levelLabel:setVisible(true)
                widget.levelLabel:setText(string.format("Level: %d", tonumber(spellData.level) or 0))
            end

            if groupIds and #groupIds > 0 then
                local primaryGroup = groupIds[1]
                local offSet = 1
                if primaryGroup == 2 then
                    offSet = 23
                elseif primaryGroup == 3 then
                    offSet = 45
                end
                widget.imageGroup:setImageClip(offSet .. " 25 20 20")
                widget.imageGroup:setVisible(true)
            end

            spellCount = spellCount + 1
            if currentWords ~= "" and words == currentWords then
                preselectedWidget = widget
            end

            ::continue_healing_popup_spell::
        end
        ::continue_healing_profile::
    end

    if spellCount == 0 then
        modules.game_textmessage.displayFailureMessage(tr("No healing spells found for your vocation."))
        safeSetInputLockWidget(nil)
        popup:show()
        window:destroy()
        return
    end

    local widgets = window.contentPanel.spellList:getChildren()
    table.sort(widgets, function(a, b)
        return a:getText() < b:getText()
    end)
    for i, widget in ipairs(widgets) do
        window.contentPanel.spellList:moveChildToIndex(widget, i)
    end

    -- Read the currently stored parameter (if any) so we can restore it when the preselected spell is re-selected
    local currentParameter = ""
    do
        local existingPopup = getHealingSettingsPopupWidget()
        if existingPopup and type(existingPopup._draftRule) == "table" then
            currentParameter = trimHealingText(existingPopup._draftRule.spellParameter or "")
        end
    end

    radio.onSelectionChange = function(widget, selected)
        if selected then
            window.contentPanel.preview:setText(selected:getText())
            window.contentPanel.preview.image:setImageSource(selected.source or "")
            if selected.clip then
                window.contentPanel.preview.image:setImageClip(selected.clip)
            end
            local hasParam = selected.param == true
            window.contentPanel.paramLabel:setOn(hasParam)
            window.contentPanel.paramText:setEnabled(hasParam)
            window.contentPanel.paramText:clearText()
            -- Restore saved parameter if user is re-selecting the spell currently stored in the rule
            if hasParam and selected == preselectedWidget and currentParameter ~= "" then
                window.contentPanel.paramText:setText(currentParameter)
            end
            window.contentPanel.spellList:ensureChildVisible(widget)
        end
    end

    if preselectedWidget then
        radio:selectWidget(preselectedWidget)
    elseif widgets and #widgets > 0 then
        radio:selectWidget(widgets[1])
    end

    local function closeSelector()
        safeSetInputLockWidget(nil)
        if popup and not popup:isDestroyed() then
            popup:show()
            popup:raise()
            popup:focus()
        end
        if window and not window:isDestroyed() then
            window:destroy()
        end
    end

    local function confirmSelection(closeAfter)
        local selected = radio:getSelectedWidget()
        if not selected then
            modules.game_textmessage.displayFailureMessage(tr("Select a spell."))
            return
        end

        local selectedWords = trimHealingText(selected.spellWords or selected:getText():match("\n(.+)") or "")
        if selectedWords == "" then
            modules.game_textmessage.displayFailureMessage(tr("Invalid spell selection."))
            return
        end

        local selectedParameter = ""
        if selected.param == true and window.contentPanel.paramText:isEnabled() then
            selectedParameter = trimHealingText(window.contentPanel.paramText:getText() or "")
        end

        local currentPopup = getHealingSettingsPopupWidget()
        if currentPopup and not currentPopup:isDestroyed() then
            currentPopup._spellWords = selectedWords
            if type(currentPopup._draftRule) ~= "table" then
                currentPopup._draftRule = createDefaultHealingRule(1)
            end
            currentPopup._draftRule.spellWords = selectedWords
            currentPopup._draftRule.spellParameter = selectedParameter
            currentPopup._draftRule.actionType = "Spell"
            currentPopup._itemId = 0
            currentPopup._itemCount = 0
            currentPopup._draftRule.itemId = 0
            currentPopup._draftRule.itemCount = 0

            modules.game_helper.selectHealingPopupActionTab("spell")
            refreshHealingPopupSpellSelectionVisual()
            refreshHealingPopupItemButtonVisual()
        end

        if closeAfter then
            closeSelector()
        end
    end

    local cancelButton = window:recursiveGetChildById("buttonClose")
    local okButton = window:recursiveGetChildById("buttonOk")

    if okButton then
        okButton.onClick = function()
            confirmSelection(true)
        end
    end
    if cancelButton then
        cancelButton.onClick = closeSelector
    end
    window.contentPanel.onEnter = function()
        confirmSelection(true)
    end
    window.onEscape = closeSelector
end

function modules.game_helper.selectHealingPopupActionTab(tabId)
    local popup = getHealingSettingsPopupWidget()
    if not popup then
        return
    end

    local isSpell = tabId ~= "item"
    local spellPanel = popup:recursiveGetChildById("spellPanel")
    local itemPanel = popup:recursiveGetChildById("itemPanel")
    local tabSpell = popup:recursiveGetChildById("actionTabSpell")
    local tabItem = popup:recursiveGetChildById("actionTabItem")

    if spellPanel then spellPanel:setVisible(isSpell) end
    if itemPanel then itemPanel:setVisible(not isSpell) end

    if tabSpell then
        tabSpell:setChecked(isSpell)
        markActiveButton(tabSpell, isSpell)
    end
    if tabItem then
        tabItem:setChecked(not isSpell)
        markActiveButton(tabItem, not isSpell)
    end

    -- Update conditionsLabel anchor to follow the visible panel
    local conditionsLabel = popup:recursiveGetChildById("conditionsLabel")
    local anchorPanel = isSpell and spellPanel or itemPanel
    if conditionsLabel and anchorPanel then
        conditionsLabel:removeAnchor(AnchorTop)
        conditionsLabel:addAnchor(AnchorTop, anchorPanel:getId(), AnchorBottom)
    end

    if type(popup._draftRule) ~= "table" then
        popup._draftRule = createDefaultHealingRule(1)
    end
    popup._draftRule.actionType = isSpell and "Spell" or "Item"
end

function bindHealingSettingsPopupHandlers(window)
    if not window or window:isDestroyed() then
        return
    end
    if window._healingPopupHandlersBound then
        return
    end

    local metric1Combo = window:recursiveGetChildById("metric1Combo")
    local joinModeCombo = window:recursiveGetChildById("joinModeCombo")
    local metric2Combo = window:recursiveGetChildById("metric2Combo")
    local op1Combo = window:recursiveGetChildById("op1Combo")
    local op2Combo = window:recursiveGetChildById("op2Combo")
    local value1Input = window:recursiveGetChildById("value1Input")
    local value2Input = window:recursiveGetChildById("value2Input")
    local spellSelectButton = window:recursiveGetChildById("spellSelectButton")
    local spellPreviewButton = window:recursiveGetChildById("spellPreviewButton")
    local itemIdInput = window:recursiveGetChildById("itemIdInput")
    local itemButton = window:recursiveGetChildById("itemPreviewButton")

    local function fillOptions(combo, options)
        if not combo then
            return
        end
        combo:clearOptions()
        for _, option in ipairs(options) do
            combo:addOption(option)
        end
    end

    fillOptions(metric1Combo, { "HP%", "MP%" })
    fillOptions(metric2Combo, { "HP%", "MP%" })
    fillOptions(joinModeCombo, { "None", "AND", "OR" })
    fillOptions(op1Combo, { "<=", "<", ">=", ">", "==" })
    fillOptions(op2Combo, { "<=", "<", ">=", ">", "==" })

    if joinModeCombo then
        joinModeCombo.onOptionChange = function()
            updateHealingPopupSecondConditionState()
        end
    end

    local function bindNumericInput(inputWidget, clampMin, clampMax)
        if not inputWidget then
            return
        end
        inputWidget.onTextChange = function(self)
            local currentText = self:getText() or ""
            local sanitized = currentText:gsub("[^0-9]", "")
            if sanitized ~= currentText then
                self:setText(sanitized)
                if self.setCursorPos then self:setCursorPos(-1) end
            end
            scheduleNumericInputClamp(self, clampMin, clampMax, nil, nil)
        end
        inputWidget.onFocusChange = function(self)
            if self:isFocused() then
                return
            end
            cancelNumericInputClamp(self)
            local value = tonumber(self:getText() or "")
            if not value and clampMin then
                self:setText(tostring(clampMin))
                return
            end
            if not value then
                return
            end
            if clampMin and value < clampMin then
                value = clampMin
            end
            if clampMax and value > clampMax then
                value = clampMax
            end
            self:setText(tostring(value))
        end
    end

    bindNumericInput(value1Input, 0, 100)
    bindNumericInput(value2Input, 0, 100)
    bindNumericInput(itemIdInput, 0, nil)

    if spellSelectButton then
        spellSelectButton.onMouseRelease = function(self, mousePos, mouseButton)
            if mouseButton ~= MouseLeftButton and mouseButton ~= MouseRightButton then
                return false
            end
            modules.game_helper.openHealingPopupSpellSelector()
            return true
        end
    end

    if spellPreviewButton then
        spellPreviewButton.onMouseRelease = function(self, mousePos, mouseButton)
            if mouseButton ~= MouseLeftButton and mouseButton ~= MouseRightButton then
                return false
            end
            modules.game_helper.openHealingPopupSpellSelector()
            return true
        end
    end

    if itemIdInput then
        itemIdInput.onTextChange = function(self)
            local text = self:getText() or ""
            local sanitized = text:gsub("[^0-9]", "")
            if sanitized ~= text then
                self:setText(sanitized)
                if self.setCursorPos then self:setCursorPos(-1) end
            end
            scheduleNumericInputClamp(self, 0, 99999, nil, nil)
            local itemId = tonumber(self:getText() or "") or 0
            modules.game_helper.setHealingPopupItemId(itemId, itemId > 0 and 1 or 0)
        end
        itemIdInput.onDrop = function(self, draggedWidget, mousePos)
            return modules.game_helper.onHealingPopupItemDrop(self, draggedWidget, mousePos)
        end
    end

    if itemButton then
        itemButton.onDrop = function(self, draggedWidget, mousePos)
            return modules.game_helper.onHealingPopupItemDrop(self, draggedWidget, mousePos)
        end
        itemButton.onMouseRelease = function(self, mousePos, mouseButton)
            if mouseButton ~= MouseLeftButton and mouseButton ~= MouseRightButton then
                return false
            end

            local draggingWidget = g_ui.getDraggingWidget()
            if mouseButton == MouseLeftButton and draggingWidget and modules.game_helper.onHealingPopupItemDrop(self, draggingWidget, mousePos) then
                return true
            end

            modules.game_helper.openHealingPopupItemMenu(self, mousePos)
            return true
        end
    end

    window._healingPopupHandlersBound = true
end

function refreshHealingSettingsPopup()
    local popup = getHealingSettingsPopupWidget()
    if not popup then
        return
    end

    if type(popup._draftRule) ~= "table" then
        popup._draftRule = createDefaultHealingRule(1)
    end
    popup._draftRule = ensureHealingRule(popup._draftRule, (tonumber(popup.healingIndex) or 0) + 1)

    local titleLabel = popup:recursiveGetChildById("popupTitleLabel")
    if titleLabel then
        titleLabel:setText(popup.isNewRule and "Add Healing" or "Edit Healing")
    end

    local saveButton = popup:recursiveGetChildById("saveButton")
    if saveButton then
        saveButton:setText(popup.isNewRule and "Add" or "Save")
    end

    setHealingPopupComboValue(popup:recursiveGetChildById("metric1Combo"), popup._draftRule.whenMetric1, "HP%")
    setHealingPopupComboValue(popup:recursiveGetChildById("op1Combo"), popup._draftRule.whenOperator1, "<=")
    local value1Input = popup:recursiveGetChildById("value1Input")
    if value1Input then
        value1Input:setText(tostring(tonumber(popup._draftRule.whenValue1) or 80))
    end

    local joinText = "None"
    if popup._draftRule.joinMode == "and" then
        joinText = "AND"
    elseif popup._draftRule.joinMode == "or" then
        joinText = "OR"
    end
    setHealingPopupComboValue(popup:recursiveGetChildById("joinModeCombo"), joinText, "None")
    setHealingPopupComboValue(popup:recursiveGetChildById("metric2Combo"), popup._draftRule.whenMetric2, "HP%")
    setHealingPopupComboValue(popup:recursiveGetChildById("op2Combo"), popup._draftRule.whenOperator2, "<=")
    local value2Input = popup:recursiveGetChildById("value2Input")
    if value2Input then
        value2Input:setText(tostring(tonumber(popup._draftRule.whenValue2) or 100))
    end

    popup._spellWords = trimHealingText(popup._draftRule.spellWords or "")
    refreshHealingPopupSpellSelectionVisual()

    local activeTab = popup._draftRule.actionType == "Item" and "item" or "spell"
    modules.game_helper.selectHealingPopupActionTab(activeTab)

    local conditionDrunkCheck = popup:recursiveGetChildById("conditionDrunkCheck")
    if conditionDrunkCheck then
        conditionDrunkCheck:setChecked(popup._draftRule.conditionDrunk == true)
    end
    local conditionRootedCheck = popup:recursiveGetChildById("conditionRootedCheck")
    if conditionRootedCheck then
        conditionRootedCheck:setChecked(popup._draftRule.conditionRooted == true)
    end
    local conditionFearedCheck = popup:recursiveGetChildById("conditionFearedCheck")
    if conditionFearedCheck then
        conditionFearedCheck:setChecked(popup._draftRule.conditionFeared == true)
    end
    local dontTargetCheck = popup:recursiveGetChildById("dontCastIfTargetingMonsterCheck")
    if dontTargetCheck then
        dontTargetCheck:setChecked(popup._draftRule.dontCastIfTargetingMonster == true)
    end
    local dontUseIfTargetCheck = popup:recursiveGetChildById("dontUseIfTargetCheck")
    if dontUseIfTargetCheck then
        dontUseIfTargetCheck:setChecked(popup._draftRule.dontUseIfTarget == true)
    end

    popup._itemId = tonumber(popup._draftRule.itemId) or 0
    popup._itemCount = tonumber(popup._draftRule.itemCount) or 0
    refreshHealingPopupItemButtonVisual()
    updateHealingPopupSecondConditionState()
end

function modules.game_helper.closeHealingSettingsPopup()
    if healingSettingsPopup and not healingSettingsPopup:isDestroyed() then
        healingSettingsPopup:destroy()
        healingSettingsPopup = nil
    end
end

function modules.game_helper.saveHealingSettingsPopup()
    ensureHealingRulesConfig()

    local popup = getHealingSettingsPopupWidget()
    if not popup then
        return
    end

    local metric1 = normalizeHealingMetric(getHealingPopupComboText(popup:recursiveGetChildById("metric1Combo"), "HP%"))
    local op1 = normalizeHealingOperator(getHealingPopupComboText(popup:recursiveGetChildById("op1Combo"), "<="))
    local value1 = tonumber((popup:recursiveGetChildById("value1Input") and popup:recursiveGetChildById("value1Input"):getText()) or
    "")
    local joinRaw = string.lower(getHealingPopupComboText(popup:recursiveGetChildById("joinModeCombo"), "None"))
    local joinMode = normalizeHealingJoinMode(joinRaw)
    local metric2 = normalizeHealingMetric(getHealingPopupComboText(popup:recursiveGetChildById("metric2Combo"), "HP%"))
    local op2 = normalizeHealingOperator(getHealingPopupComboText(popup:recursiveGetChildById("op2Combo"), "<="))
    local value2 = tonumber((popup:recursiveGetChildById("value2Input") and popup:recursiveGetChildById("value2Input"):getText()) or
    "")
    local spellWords = trimHealingText(popup._spellWords or
    (type(popup._draftRule) == "table" and popup._draftRule.spellWords or ""))
    local manaMin = 0

    local actionType = normalizeHealingActionType(type(popup._draftRule) == "table" and popup._draftRule.actionType or
    "Spell")
    local itemPanel = popup:recursiveGetChildById("itemPanel")
    if itemPanel and itemPanel:isVisible() then
        actionType = "Item"
    else
        actionType = "Spell"
    end

    if not value1 then
        modules.game_textmessage.displayFailureMessage(tr("Fill first condition value."))
        return
    end

    if joinMode ~= "none" and not value2 then
        modules.game_textmessage.displayFailureMessage(tr("Fill second condition value."))
        return
    end

    if value2 == nil then
        local previousValue2 = type(popup._draftRule) == "table" and tonumber(popup._draftRule.whenValue2) or nil
        value2 = previousValue2 or 0
    end

    local itemId = tonumber(popup._itemId) or 0
    if actionType == "Item" then
        if itemId <= 0 then
            modules.game_textmessage.displayFailureMessage(tr("Select an item for healing rule."))
            return
        end
        if isHpOnlyHealingRuleItem(itemId) then
            metric1 = "HP%"
            metric2 = "HP%"
        end
        spellWords = ""
    else
        if spellWords == "" then
            modules.game_textmessage.displayFailureMessage(tr("Select a spell for healing rule."))
            return
        end
        itemId = 0
    end

    local conditionDrunkCheck = popup:recursiveGetChildById("conditionDrunkCheck")
    local conditionRootedCheck = popup:recursiveGetChildById("conditionRootedCheck")
    local conditionFearedCheck = popup:recursiveGetChildById("conditionFearedCheck")
    local dontTargetCheck = popup:recursiveGetChildById("dontCastIfTargetingMonsterCheck")
    local dontUseIfTargetCheck = popup:recursiveGetChildById("dontUseIfTargetCheck")

    local rules = helperConfig.healingRules or {}
    local targetIndex = nil
    if popup.healingIndex ~= nil then
        targetIndex = tonumber(popup.healingIndex) + 1
    end
    local slotIndex = targetIndex or (#rules + 1)

    local rule = ensureHealingRule(deepCopy(popup._draftRule or createDefaultHealingRule(slotIndex)), slotIndex)
    rule.actionType = actionType
    rule.spellWords = spellWords
    rule.spellParameter = actionType == "Spell" and
    trimHealingText(popup._draftRule and popup._draftRule.spellParameter or "") or ""
    rule.itemId = itemId
    rule.itemCount = itemId > 0 and 1 or 0
    rule.whenMetric1 = metric1
    rule.whenOperator1 = op1
    rule.whenValue1 = value1
    rule.joinMode = joinMode
    rule.whenMetric2 = metric2
    rule.whenOperator2 = op2
    rule.whenValue2 = value2
    rule.manaMin = manaMin
    rule.conditionDrunk = conditionDrunkCheck and conditionDrunkCheck:isChecked() or false
    rule.conditionRooted = conditionRootedCheck and conditionRootedCheck:isChecked() or false
    rule.conditionFeared = conditionFearedCheck and conditionFearedCheck:isChecked() or false
    rule.dontCastIfTargetingMonster = dontTargetCheck and dontTargetCheck:isChecked() or false
    rule.dontUseIfTarget = dontUseIfTargetCheck and dontUseIfTargetCheck:isChecked() or false

    if targetIndex and rules[targetIndex] then
        local previousEnabled = popup._previousEnabledState
        if previousEnabled == nil then
            previousEnabled = rules[targetIndex].enabled == true
        end
        rule.enabled = previousEnabled == true
        rules[targetIndex] = ensureHealingRule(rule, targetIndex)
    else
        rule.enabled = true
        table.insert(rules, ensureHealingRule(rule, #rules + 1))
    end

    for i = 1, #rules do
        rules[i] = ensureHealingRule(rules[i], i)
        rules[i].orderPriority = i
    end
    helperConfig.healingRules = rules

    saveSettings()
    rebuildAllHealingRules()
    modules.game_helper.closeHealingSettingsPopup()
end

function modules.game_helper.openHealingSettingsPopup(zeroIndex, initialRule, isNewRule)
    if healingSettingsPopup and not healingSettingsPopup:isDestroyed() then
        healingSettingsPopup:destroy()
        healingSettingsPopup = nil
    end

    ensureHealingRulesConfig()

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        modules.game_textmessage.displayFailureMessage(htr("Failed to get root widget."))
        return
    end

    local window = g_ui.loadUI("/mods/game_helper/styles/healing_settings_popup.otui", rootWidget)
    if not window then
        modules.game_textmessage.displayFailureMessage(htr("Failed to load healing settings popup."))
        return
    end

    healingSettingsPopup = window
    applyOpacityToWindow(window)
    window.healingIndex = nil
    window.isNewRule = isNewRule == true
    window._previousEnabledState = true

    local parsedZeroIndex = tonumber(zeroIndex)
    if parsedZeroIndex ~= nil then
        local idx = parsedZeroIndex + 1
        if helperConfig.healingRules and helperConfig.healingRules[idx] then
            window.healingIndex = parsedZeroIndex
            window._draftRule = deepCopy(ensureHealingRule(helperConfig.healingRules[idx], idx))
            window._previousEnabledState = helperConfig.healingRules[idx].enabled == true
            window.isNewRule = false
        end
    end

    if type(window._draftRule) ~= "table" then
        local rules = helperConfig.healingRules or {}
        local slotIndex = #rules + 1
        window._draftRule = deepCopy(ensureHealingRule(initialRule or createDefaultHealingRule(slotIndex), slotIndex))
        window._draftRule.enabled = true
        window._previousEnabledState = true
        window.isNewRule = true
    end

    bindHealingSettingsPopupHandlers(window)

    window.onDestroy = function()
        healingSettingsPopup = nil
    end

    refreshHealingSettingsPopup()

    local screenSize = rootWidget:getSize()
    local popupSize = window:getSize()
    local centerX = (screenSize.width - popupSize.width) / 2
    local centerY = (screenSize.height - popupSize.height) / 2
    window:setPosition({ x = math.max(0, centerX), y = math.max(0, centerY) })

    window:show()
    window:raise()
    window:focus()
    modalEnter(window)
end

function modules.game_helper.finishAddEquipmentRuleSelection(self, mousePosition, mouseButton)
    if mouseGrabberWidget then
        mouseGrabberWidget:ungrabMouse()
        mouseGrabberWidget.onMouseRelease = nil
    end
    if helper then
        helper:show()
    end
    g_mouse.popCursor("target")

    if mouseButton ~= MouseLeftButton then
        return true
    end

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return true
    end

    local clickedWidget = rootWidget:recursiveGetChildByPos(mousePosition, false)
    if not clickedWidget then
        return true
    end

    local item = nil
    if clickedWidget:getClassName() == "UIItem" and not clickedWidget:isVirtual() then
        item = clickedWidget:getItem()
    elseif clickedWidget:getClassName() == "UIGameMap" then
        local tile = clickedWidget:getTile(mousePosition)
        if tile then
            local topUseThing = tile:getTopUseThing()
            if topUseThing and topUseThing:isItem() then
                item = topUseThing
            end
        end
    end

    if not item then
        modules.game_textmessage.displayFailureMessage(tr("Select an amulet or ring item."))
        return true
    end

    local ruleType = resolveEquipmentRuleTypeByItemId(item:getId())

    if not ruleType then
        modules.game_textmessage.displayFailureMessage(tr("Item must be amulet or ring."))
        return true
    end

    modules.game_helper.addEquipmentRule(ruleType, item:getId())
    return true
end

function modules.game_helper.startAddEquipmentRuleSelection()
    if not mouseGrabberWidget then
        return
    end

    mouseGrabberWidget:grabMouse()
    if helper then
        helper:hide()
    end
    g_mouse.pushCursor("target")
    mouseGrabberWidget.onMouseRelease = function(self, mousePosition, mouseButton)
        modules.game_helper.finishAddEquipmentRuleSelection(self, mousePosition, mouseButton)
    end
end

function modules.game_helper.addEquipmentRule(itemType, initialItemId)
    if type(helperConfig) ~= "table" then
        return
    end

    ensureEquipmentSwapConfig()

    local parsedItemId = tonumber(initialItemId) or 0

    local resolvedItemType = nil
    if parsedItemId > 0 then
        resolvedItemType = resolveEquipmentRuleTypeByItemId(parsedItemId)
        if not resolvedItemType then
            modules.game_textmessage.displayFailureMessage(tr("Item must be amulet or ring."))
            return
        end
    end

    if not itemType then
        itemType = resolvedItemType or "amulet"
    end
    if resolvedItemType then
        itemType = resolvedItemType
    end

    local meta = getEquipmentRuleMeta(itemType)
    if not meta then
        return
    end

    local rules = helperConfig[meta.configKey] or {}
    local newRule = createDefaultEquipmentSwapRule(itemType, #rules + 1)
    newRule.enabled = true
    if parsedItemId > 0 then
        newRule.id = parsedItemId
    end
    if not equipmentRuleHasTriggerCondition(newRule) then
        newRule.equipIfHPBelowEnabled = true
        newRule.equipIfHPBelow = 50
        newRule.slot1Metric = "HP%"
        newRule.slot1Operator = "<="
        newRule.slot1Value = 50
    end
    table.insert(rules, newRule)
    helperConfig[meta.configKey] = rules

    local hasInitialItem = parsedItemId > 0
    if hasInitialItem then
        rebuildAllEquipmentSwapRules()
        updateAllItemCounts()
    end
    modules.game_helper.openEquipmentSettingsPopup(itemType, #rules - 1, true)
    if hasInitialItem then
        saveSettings()
    end
end

function modules.game_helper.removeEquipmentRule(itemType, zeroIndex)
    local meta = getEquipmentRuleMeta(itemType)
    if not meta then
        return
    end
    if type(helperConfig) ~= "table" then
        return
    end

    ensureEquipmentSwapConfig()

    local rules = helperConfig[meta.configKey] or {}
    local index = tonumber(zeroIndex)
    if not index then
        return
    end

    index = index + 1
    if not rules[index] then
        return
    end

    table.remove(rules, index)
    helperConfig[meta.configKey] = rules

    if equipmentSettingsPopup and not equipmentSettingsPopup:isDestroyed() and equipmentSettingsPopup.itemType == itemType then
        equipmentSettingsPopup:destroy()
        equipmentSettingsPopup = nil
    end

    rebuildAllEquipmentSwapRules()
    updateAllItemCounts()
    saveSettings()
end

function assignAmuletEvent(button)
    mouseGrabberWidget:grabMouse()
    helper:hide()
    g_mouse.pushCursor("target")
    mouseGrabberWidget.onMouseRelease = function(self, mousePosition, mouseButton)
        onAssignAmulet(self, mousePosition, mouseButton, button)
    end
end

function onAssignAmulet(self, mousePosition, mouseButton, button)
    mouseGrabberWidget:ungrabMouse()
    helper:show()
    g_mouse.popCursor("target")
    mouseGrabberWidget.onMouseRelease = nil

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return true
    end

    local clickedWidget = rootWidget:recursiveGetChildByPos(mousePosition, false)
    if not clickedWidget then
        return true
    end

    local item = nil
    if clickedWidget:getClassName() == "UIItem" and not clickedWidget:isVirtual() then
        item = clickedWidget:getItem()
    elseif clickedWidget:getClassName() == "UIGameMap" then
        local tile = clickedWidget:getTile(mousePosition)
        if tile then
            local topUseThing = tile:getTopUseThing()
            if topUseThing and topUseThing:isItem() then
                item = topUseThing
            end
        end
    end

    if not item then
        modules.game_textmessage.displayFailureMessage(tr("Invalid amulet!"))
        return false
    end

    local itemType = g_things.getThingType(item:getId(), ThingCategoryItem)
    if not itemType then
        modules.game_textmessage.displayFailureMessage(tr("Invalid amulet!"))
        return false
    end

    local slotAmulet = 2
    if itemType:getClothSlot() ~= slotAmulet then
        modules.game_textmessage.displayFailureMessage(tr("Invalid amulet!"))
        return false
    end

    updateAmuletButton(button, item:getId())
    return true
end

function updateAmuletPercent(buttonId, newPercent)
    local buttonIndex = string.match(buttonId, "%d+")
    buttonIndex = tonumber(buttonIndex)

    local config = helperConfig.amulets[buttonIndex + 1]
    local step = getPercentStep()
    local minValue = 1
    local maxValue = 99

    -- Verificar se equipmentSwapPanel existe antes de acessar
    if not equipmentPanel then
        return
    end

    local equipmentSwapPanel = equipmentPanel:recursiveGetChildById("equipmentSwapPanel")
    if not equipmentSwapPanel then
        return
    end

    local firstPanel = equipmentSwapPanel:recursiveGetChildById("firstPanel")
    if not firstPanel then
        return
    end

    if string.find(buttonId, "add") then
        local newValue = math.min(config.percent + step, maxValue)
        if newValue == config.percent then
            firstPanel:recursiveGetChildById("addPercentButton" .. buttonIndex):setEnabled(false)
            return
        end

        firstPanel:recursiveGetChildById("rmvPercentButton" .. buttonIndex):setEnabled(true)
        config.percent = newValue
        local label = firstPanel:recursiveGetChildById("amuletPercentLabel" .. buttonIndex)
        label:setText(config.percent .. "%")

        if config.percent >= maxValue then
            firstPanel:recursiveGetChildById("addPercentButton" .. buttonIndex):setEnabled(false)
        end
    elseif string.find(buttonId, "rmv") then
        local newValue = math.max(config.percent - step, minValue)
        if newValue == config.percent then
            firstPanel:recursiveGetChildById("rmvPercentButton" .. buttonIndex):setEnabled(false)
            return
        end

        firstPanel:recursiveGetChildById("addPercentButton" .. buttonIndex):setEnabled(true)
        config.percent = newValue
        local label = firstPanel:recursiveGetChildById("amuletPercentLabel" .. buttonIndex)
        label:setText(config.percent .. "%")

        if config.percent <= minValue then
            firstPanel:recursiveGetChildById("rmvPercentButton" .. buttonIndex):setEnabled(false)
        end
    end
end

function updateAmuletButton(button, amuletId)
    ensureEquipmentSwapConfig()

    if not button:getChildById("amuletItem") then
        local itemWidget = g_ui.createWidget("EquipmentItem", button)
        if itemWidget then
            itemWidget:setId("amuletItem")
        end
    end

    local itemWidget = button:getChildById("amuletItem")
    if itemWidget then
        itemWidget:setItemId(amuletId)
    end
    button:setImageSource("/images/ui/item")
    button:setTooltip("Item ID: " .. tostring(amuletId))

    local buttonId = button:getId()
    local slotID = tonumber(buttonId:match("%d+"))
    if not slotID then
        return
    end

    if not helperConfig.amulets[slotID + 1] then
        helperConfig.amulets[slotID + 1] = createDefaultEquipmentSwapRule("amulet", slotID + 1)
    end

    local config = helperConfig.amulets[slotID + 1]
    config.id = amuletId
    config.percent = config.percent or 80
    config.enabled = config.enabled or false
    config.priority = config.priority or 1
    config.mode = config.mode or (slotID == 0 and "above" or "below")
    if not equipmentRuleHasTriggerCondition(config) then
        config.equipIfHPBelowEnabled = true
        config.equipIfHPBelow = 50
        config.slot1Metric = "HP%"
        config.slot1Operator = "<="
        config.slot1Value = 50
    end

    -- Atualizar contagem
    updateAllItemCounts()
end

function modules.game_helper.onEnableAmuletChanger(buttonId, checked)
    ensureEquipmentSwapConfig()

    -- Extrair o numero do final do ID (enableAmulet0 -> 0, enableAmulet1 -> 1)
    local slotIndex = tonumber(buttonId:match("enableAmulet(%d+)$"))
    if not slotIndex then
        -- Tentar padrao alternativo caso o ID seja diferente
        slotIndex = tonumber(buttonId:match("%d+"))
        if not slotIndex then
            g_logger.error("onEnableAmuletChanger: Nao foi possivel extrair slotIndex de buttonId: " ..
            tostring(buttonId))
            return
        end
    end

    if helperConfig.amulets and helperConfig.amulets[slotIndex + 1] then
        helperConfig.amulets[slotIndex + 1].enabled = checked
    else
        helperConfig.amulets[slotIndex + 1] = createDefaultEquipmentSwapRule("amulet", slotIndex + 1)
        helperConfig.amulets[slotIndex + 1].enabled = checked
    end

    saveSettings()
end

function isDynamicMatch(helperId, equippedId)
    return helperId == equippedId
end

function pushRing(ringId)
    local player = g_game.getLocalPlayer()
    if not player then
        return
    end

    -- Tank Mode tem prioridade: bloquear apenas se o caller esta tentando equipar
    -- um ring DIFERENTE do escolhido pro tank mode. O Energy Ring (regra HP/MP da aba
    -- Healing) so fura esse lock quando "Keep Energy Ring" (respectEnergyRing) estiver
    -- LIGADO; desligado, o tank ring tem prioridade e o energy ring e bloqueado aqui.
    if helperConfig.tankModeEnabled and helperConfig.tankModeRingEnabled ~= false then
        local tankModeRingId = helperConfig.tankModeRingId or 3048
        if tankModeRingId and tankModeRingId > 0 and ringId ~= tankModeRingId then
            local energyRingHasPriority = helperConfig.respectEnergyRing == true
                and (ringId == ENERGY_RING_EQUIPPED_ID
                    or ringId == ENERGY_RING_UNEQUIPPED_ID
                    or isDynamicMatch(ENERGY_RING_EQUIPPED_ID, ringId))
            if not energyRingHasPriority then
                return
            end
        end
    end

    if spellsCooldown["ring"] and spellsCooldown["ring"] > g_clock.millis() then
        return true
    end

    local slotRing = player:getInventoryItem(9)
    if slotRing then
        local equippedId = slotRing:getId()
        if equippedId == ringId or isDynamicMatch(ringId, equippedId) then
            return true
        end
    end

    -- Só envia equip se o player realmente tem o anel em qualquer lugar
    -- (inclui bp fechada via cache do server) — vale também para Energy Ring,
    -- que já vinha checando antes mas reforça aqui pra blindar o caminho.
    if getItemCountAnywhere and (getItemCountAnywhere(ringId) or 0) <= 0 then
        return
    end

    return dispatchEquipForSlot(player, ringId, "ring")
end

function getContainerInventorySlot(container)
    if not container or not container.getContainerItem then
        return 0
    end

    local containerItem = container:getContainerItem()
    if not containerItem or not containerItem.getPosition then
        return 0
    end

    local pos = containerItem:getPosition()
    if not pos or pos.x ~= 65535 then
        return 0
    end

    return tonumber(pos.y) or 0
end

RING_POUCH_ID = 60265
AMULET_POUCH_ID = 60266

function getAccessoryPouchIdForSlot(slotIndex)
    if slotIndex == InventorySlotNeck then
        return AMULET_POUCH_ID
    elseif slotIndex == InventorySlotFinger then
        return RING_POUCH_ID
    end
    return 0
end

function findOpenContainerAtInventorySlot(slotIndex)
    local containers = g_game.getContainers()
    if not containers then return nil end
    for _, container in pairs(containers) do
        if container and container.getContainerItem then
            local containerItem = container:getContainerItem()
            if containerItem and containerItem.getPosition then
                local pos = containerItem:getPosition()
                if pos and pos.x == 65535 and pos.y == slotIndex then
                    return container
                end
            end
        end
    end
    return nil
end

-- Considera "equipado" se o item esta no slot OU dentro da pouch aberta no slot (Amulet/Ring Pouch)
function isAccessoryRuleEquipped(slotItem, slotIndex, ruleId)
    if not ruleId or ruleId <= 0 or not slotItem then
        return false
    end

    local equippedId = slotItem:getId()
    if equippedId == ruleId or isDynamicMatch(ruleId, equippedId) then
        return true
    end

    local pouchId = getAccessoryPouchIdForSlot(slotIndex)
    if pouchId <= 0 or equippedId ~= pouchId then
        return false
    end

    local container = findOpenContainerAtInventorySlot(slotIndex)
    if not container or not container.getItems then
        return false
    end

    local items = container:getItems()
    if not items then return false end
    for _, it in pairs(items) do
        if it then
            local itId = it:getId()
            if itId == ruleId or isDynamicMatch(ruleId, itId) then
                return true
            end
        end
    end
    return false
end

function isUnequipContainerBlockedByName(container)
    if not container or not container.getName then
        return false
    end

    local name = string.lower(container:getName() or "")
    return string.find(name, "inbox", 1, true) ~= nil or
        string.find(name, "reward", 1, true) ~= nil
end

function getFirstFreeContainerSlotPosition(container)
    if not container or not container.getCapacity or not container.getItem or not container.getSlotPosition then
        return nil
    end

    local capacity = tonumber(container:getCapacity()) or 0
    if capacity <= 0 then
        return nil
    end

    for slot = 0, capacity - 1 do
        local slotItem = container:getItem(slot)
        if not slotItem then
            return container:getSlotPosition(slot)
        end
    end

    return nil
end

function getBestUnequipDestinationPosition()
    local containers = g_game.getContainers()
    if type(containers) ~= "table" then
        return nil
    end

    local bestPos = nil
    local bestRank = 999
    local bestContainerId = 999999

    for _, container in pairs(containers) do
        if not isUnequipContainerBlockedByName(container) then
            local freePos = getFirstFreeContainerSlotPosition(container)
            if freePos then
                local slot = getContainerInventorySlot(container)
                local rank = 90
                if slot == InventorySlotBack then
                    rank = 10 -- Main backpack container
                elseif container.hasParent and not container:hasParent() then
                    rank = 20 -- Other root containers
                else
                    rank = 30 -- Nested containers
                end

                local containerId = 999999
                if container.getId then
                    containerId = tonumber(container:getId()) or 999999
                end

                if rank < bestRank or (rank == bestRank and containerId < bestContainerId) then
                    bestRank = rank
                    bestContainerId = containerId
                    bestPos = freePos
                end
            end
        end
    end

    return bestPos
end

function moveEquippedItemToBackpack(slotIndex, cooldownKey)
    local player = g_game.getLocalPlayer()
    if not player then
        return false
    end

    if spellsCooldown[cooldownKey] and spellsCooldown[cooldownKey] > g_clock.millis() then
        return true
    end

    local equippedItem = player:getInventoryItem(slotIndex)
    if not equippedItem then
        return true
    end

    local preferredPos = getBestUnequipDestinationPosition()
    if not preferredPos then
        -- Sem container aberto com slot livre. Nao mover: o fallback antigo
        -- usava player:getPosition() como destino, o que jogava o item no chao.
        spellsCooldown[cooldownKey] = g_clock.millis() + getEngineIntervalValue("equipmentSwap")
        return false
    end

    g_game.move(equippedItem, preferredPos, 1)
    spellsCooldown[cooldownKey] = g_clock.millis() + getEngineIntervalValue("equipmentSwap")
    return true
end

function popAmulet()
    return moveEquippedItemToBackpack(InventorySlotNeck, "amulet")
end

function popRing()
    return moveEquippedItemToBackpack(InventorySlotFinger, "ring")
end

