function createExcludeAmuletMenu(index)
    -- Tentar buscar o popup de diferentes formas
    local popup = equipmentSettingsPopup
    if not popup or popup:isDestroyed() then
        -- Tentar buscar pelo rootWidget
        local rootWidget = g_ui.getRootWidget()
        if rootWidget then
            popup = rootWidget:recursiveGetChildById("equipmentSettingsPopup")
        end
    end

    if not popup or popup:isDestroyed() then
        return true
    end

    local button = popup:recursiveGetChildById("excludeAmuletButton" .. index)
    if not button then
        return true
    end

    local menu = g_ui.createWidget('HelperPopupMenu')
    menu:setGameMenu(true)

    menu:addOption(tr('Select Item'), function()
        assignExcludeAmuletEvent(button, index)
    end)

    menu:addOption(tr('Assign ID'), function()
        openAssignItemIdWindow(button, "excludeAmulet")
    end)

    menu:addOption(tr('Assign List'), function()
        openAssignItemListWindow(button, "excludeAmulet")
    end)

    if button:getChildById("excludeAmuletItem" .. index) then
        menu:addOption(tr('Remove Item'), function()
            removeExcludeAmuletItem(button, index)
        end)
    end

    local mousePos = g_window.getMousePosition()
    menu:display(mousePos)
    return true
end

function removeExcludeAmuletItem(button, index)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local itemType = equipmentSettingsPopup.itemType
    local popupIndex = equipmentSettingsPopup.itemIndex

    if not itemType or popupIndex == nil then
        return
    end

    local config = nil
    if itemType == "amulet" then
        config = helperConfig.amulets[popupIndex + 1]
    elseif itemType == "ring" then
        config = helperConfig.rings[popupIndex + 1]
    end

    if not config then
        return
    end

    if not config.excludeAmuletIds then
        config.excludeAmuletIds = { 0, 0 }
    end

    config.excludeAmuletIds[index + 1] = 0
    button:setImageSource("/images/game/actionbar/slot-actionbar.png")
    local itemWidget = button:getChildById("excludeAmuletItem" .. index)
    if itemWidget then
        itemWidget:destroy()
    end

    saveSettings()
end

