        end)
    end

    local mousePos = g_window.getMousePosition()
    menu:display(mousePos)
    return true
end

function removeExcludeRingItem(button, index)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local itemType = equipmentSettingsPopup.itemType
    local popupIndex = equipmentSettingsPopup.itemIndex

    if not itemType or popupIndex == nil then
        return
    end

    local config = nil
    if itemType == "amulet" then
        config = helperConfig.amulets[popupIndex + 1]
    elseif itemType == "ring" then
        config = helperConfig.rings[popupIndex + 1]
    end

    if not config then
        return
    end

    if not config.excludeRingIds then
        config.excludeRingIds = { 0, 0 }
    end

    config.excludeRingIds[index + 1] = 0
    button:setImageSource("/images/game/actionbar/slot-actionbar.png")
    local itemWidget = button:getChildById("excludeRingItem" .. index)
    if itemWidget then
        itemWidget:destroy()
    end

    saveSettings()
end

function updateExcludeRingButton(button, index)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local itemType = equipmentSettingsPopup.itemType
    local popupIndex = equipmentSettingsPopup.itemIndex

    if not itemType or popupIndex == nil then
        return
    end

    local config = nil
    if itemType == "amulet" then
        config = helperConfig.amulets[popupIndex + 1]
    elseif itemType == "ring" then
        config = helperConfig.rings[popupIndex + 1]
    end

    if not config then
        return
    end

    if not config.excludeRingIds then
        config.excludeRingIds = { 0, 0 }
    end

    if button:getChildById("excludeRingItem" .. index) then
        -- Remover item
        config.excludeRingIds[index + 1] = 0
        button:setImageSource("/images/game/actionbar/slot-actionbar.png")
        local itemWidget = button:getChildById("excludeRingItem" .. index)
        if itemWidget then
            itemWidget:destroy()
        end
    else
        -- Adicionar item
        assignExcludeRingEvent(button, index)
    end

    saveSettings()
end

function assignExcludeRingEvent(button, index)
    local mouseGrabberWidget = modules.game_helper.getMouseGrabberWidget()
    if not mouseGrabberWidget then
        return
    end

    mouseGrabberWidget:grabMouse()
    if equipmentSettingsPopup then
        equipmentSettingsPopup:hide()
    end
    g_mouse.pushCursor("target")
    mouseGrabberWidget.onMouseRelease = function(self, mousePosition, mouseButton)
        onAssignExcludeRing(self, mousePosition, mouseButton, button, index)
    end
end

function onAssignExcludeRing(self, mousePosition, mouseButton, button, index)
    local mouseGrabberWidget = modules.game_helper.getMouseGrabberWidget()
    if not mouseGrabberWidget then
        return true
    end

    mouseGrabberWidget:ungrabMouse()
    if equipmentSettingsPopup then
        equipmentSettingsPopup:show()
    end
    g_mouse.popCursor("target")
    mouseGrabberWidget.onMouseRelease = nil

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return true
    end

    local clickedWidget = rootWidget:recursiveGetChildByPos(mousePosition, false)
    if not clickedWidget then
        return true
    end

    local item = nil
    if clickedWidget:getClassName() == "UIItem" and not clickedWidget:isVirtual() then
        item = clickedWidget:getItem()
    elseif clickedWidget:getClassName() == "UIGameMap" then
        local tile = clickedWidget:getTile(mousePosition)
        if tile then
            local topUseThing = tile:getTopUseThing()
            if topUseThing and topUseThing:isItem() then
                item = topUseThing
            end
        end
    end

    if not item then
        modules.game_textmessage.displayFailureMessage(tr("Invalid ring!"))
        return false
    end

    local itemType = g_things.getThingType(item:getId(), ThingCategoryItem)
    if not itemType then
        modules.game_textmessage.displayFailureMessage(tr("Invalid ring!"))
        return false
    end

    local slotRing = 9
    if itemType:getClothSlot() ~= slotRing then
        modules.game_textmessage.displayFailureMessage(tr("Invalid ring!"))
        return false
    end

    local itemId = item:getId()
    button:setImageSource("/images/ui/item")

    if not button:getChildById("excludeRingItem" .. index) then
        local itemWidget = g_ui.createWidget("RuneItem", button)
        itemWidget:setId("excludeRingItem" .. index)
        itemWidget:setSize({ width = 32, height = 32 })
    end

    local itemWidget = button:getChildById("excludeRingItem" .. index)
    if itemWidget then
        itemWidget:setItemId(itemId)
    end

    local popupItemType = equipmentSettingsPopup.itemType
    local popupIndex = equipmentSettingsPopup.itemIndex

    if popupItemType == "amulet" then
        local config = helperConfig.amulets[popupIndex + 1]
        if config then
            if not config.excludeRingIds then
                config.excludeRingIds = { 0, 0 }
            end
            config.excludeRingIds[index + 1] = itemId
        end
    elseif popupItemType == "ring" then
        local config = helperConfig.rings[popupIndex + 1]
        if config then
            if not config.excludeRingIds then
                config.excludeRingIds = { 0, 0 }
            end
            config.excludeRingIds[index + 1] = itemId
        end
    end

    saveSettings()
    return true
end

function updateRingPercent(buttonId, newPercent)
    local buttonIndex = string.match(buttonId, "%d+")
    buttonIndex = tonumber(buttonIndex)
    local config = helperConfig.rings[buttonIndex + 1]
    local step = getPercentStep()
    local minValue = 1
    local maxValue = 99

    -- Verificar se equipmentSwapPanel existe antes de acessar
    if not equipmentPanel then
        return
    end

    local equipmentSwapPanel = equipmentPanel:recursiveGetChildById("equipmentSwapPanel")
    if not equipmentSwapPanel then
        return
    end

    local secondPanel = equipmentSwapPanel:recursiveGetChildById("secondPanel")
    if not secondPanel then
        return
    end

    if string.find(buttonId, "add") then
        local newValue = math.min(config.percent + step, maxValue)
        if newValue == config.percent then
            secondPanel:recursiveGetChildById("addPercentButton" .. buttonIndex):setEnabled(false)
            return
        end

        secondPanel:recursiveGetChildById("rmvPercentButton" .. buttonIndex):setEnabled(true)
        config.percent = newValue
        local label = secondPanel:recursiveGetChildById("ringPercentLabel" .. buttonIndex)
        label:setText(config.percent .. "%")

        if config.percent >= maxValue then
            secondPanel:recursiveGetChildById("addPercentButton" .. buttonIndex):setEnabled(false)
        end
    elseif string.find(buttonId, "rmv") then
        local newValue = math.max(config.percent - step, minValue)
        if newValue == config.percent then
            secondPanel:recursiveGetChildById("rmvPercentButton" .. buttonIndex):setEnabled(false)
            return
        end

        secondPanel:recursiveGetChildById("addPercentButton" .. buttonIndex):setEnabled(true)
        config.percent = newValue
        local label = secondPanel:recursiveGetChildById("ringPercentLabel" .. buttonIndex)
        label:setText(config.percent .. "%")

        if config.percent <= minValue then
            secondPanel:recursiveGetChildById("rmvPercentButton" .. buttonIndex):setEnabled(false)
        end
    end
end

function updateRingButton(button, ringId)
    ensureEquipmentSwapConfig()

    if not button:getChildById("ringItem") then
        local itemWidget = g_ui.createWidget("EquipmentItem", button)
        if itemWidget then
            itemWidget:setId("ringItem")
        end
    end

    local itemWidget = button:getChildById("ringItem")
    if itemWidget then
        itemWidget:setItemId(ringId)
    end
    button:setImageSource("/images/ui/item")
    button:setTooltip("Item ID: " .. tostring(ringId))

    local buttonId = button:getId()
    local slotID = tonumber(buttonId:match("%d+"))
    if not slotID then
        return
    end

    if not helperConfig.rings[slotID + 1] then
        helperConfig.rings[slotID + 1] = createDefaultEquipmentSwapRule("ring", slotID + 1)
    end

    local config = helperConfig.rings[slotID + 1]
    config.id = ringId
    config.percent = config.percent or 80
    config.enabled = config.enabled or false
    config.priority = config.priority or 1
    config.mode = config.mode or (slotID == 0 and "above" or "below")
    if not equipmentRuleHasTriggerCondition(config) then
        config.equipIfHPBelowEnabled = true
        config.equipIfHPBelow = 50
        config.slot1Metric = "HP%"
        config.slot1Operator = "<="
        config.slot1Value = 50
    end

    -- Atualizar contagem
    updateAllItemCounts()
end

function modules.game_helper.onEnableRingChanger(buttonId, checked)
    ensureEquipmentSwapConfig()

    -- Extrair o numero do final do ID (enableRing0 -> 0, enableRing1 -> 1)
    local slotIndex = tonumber(buttonId:match("enableRing(%d+)$"))
    if not slotIndex then
        -- Tentar padrao alternativo caso o ID seja diferente
        slotIndex = tonumber(buttonId:match("%d+"))
        if not slotIndex then
            g_logger.error("onEnableRingChanger: Nao foi possivel extrair slotIndex de buttonId: " .. tostring(buttonId))
            return
        end
    end

    if helperConfig.rings and helperConfig.rings[slotIndex + 1] then
        helperConfig.rings[slotIndex + 1].enabled = checked
    else
        helperConfig.rings[slotIndex + 1] = createDefaultEquipmentSwapRule("ring", slotIndex + 1)
        helperConfig.rings[slotIndex + 1].enabled = checked
    end

    saveSettings()
end

function modules.game_helper.onEnableEquipmentSwap(checked)
    helperConfig.equipmentSwapEnabled = checked

    -- Update the checkbox UI
    if equipmentPanel then
        local equipmentSwapCheckbox = equipmentPanel:recursiveGetChildById("enableEquipmentSwap")
        if equipmentSwapCheckbox then
            equipmentSwapCheckbox:setChecked(checked)
        end
    end

    -- Update icon stats window
    if IconStatsModule and IconStatsModule.updateEquipmentIcon then
        IconStatsModule.updateEquipmentIcon(checked)
    end

    -- Save settings
    saveSettings()
end

