function resetPartyPanel()
    if not healingPanel or not friendHealPanel then
        return
    end

    local sioPanel = friendHealPanel:recursiveGetChildById("friendHealingPanel")
    local granSioPanel = friendHealPanel:recursiveGetChildById("granSioPanel")

    if not sioPanel or not granSioPanel then
        return
    end

    local player = g_game.getLocalPlayer()
    if not player then
        if friendListWidget then
            friendListWidget:destroyChildren()
        end
        if granListWidget then
            granListWidget:destroyChildren()
        end

        -- Reset friend healing config
        local enableSio = sioPanel:recursiveGetChildById("enableSio0")
        if enableSio then
            enableSio:setChecked(false)
        end

        helperConfig.friendhealing[1].name = ""
        helperConfig.friendhealing[1].percent = 0
        helperConfig.friendhealing[1].enabled = false

        -- Reset gran sio config
        local granEnableSio = granSioPanel:recursiveGetChildById("enableSio0")
        if granEnableSio then
            granEnableSio:setChecked(false)
        end

        helperConfig.gransiohealing[1].name = ""
        helperConfig.gransiohealing[1].percent = 0
        helperConfig.gransiohealing[1].enabled = false

        return
    end
end

function manageSioSettings(activate, index)
    if not healingPanel or not friendHealPanel then
        return
    end

    local sioPanel = friendHealPanel:recursiveGetChildById("friendHealingPanel")
    if not sioPanel then
        return
    end

    local enableSio = sioPanel:recursiveGetChildById("enableSio" .. index)
    if enableSio and not activate then
        enableSio:setChecked(false)
    end
end

function manageGranSioSettings(activate, index)
    if not healingPanel or not friendHealPanel then
        return
    end

    local granSioPanel = friendHealPanel:recursiveGetChildById("granSioPanel")
    if not granSioPanel then
        return
    end

    local enableSio = granSioPanel:recursiveGetChildById("enableSio" .. index)
    if enableSio and not activate then
        enableSio:setChecked(false)
    end
end

