        helperConfig.uhhealingVocationPriority = {}
    end
    helperConfig.uhhealingVocationPriority[tostring(vocationId)] = tonumber(priority)
    saveSettings()
end

function onUHFriendListTextChange(text)
    if not helperConfig.uhfriendList then
        helperConfig.uhfriendList = {}
    end

    local names = {}
    for line in text:gmatch("[^\r\n]+") do
        local trimmed = line:match("^%s*(.-)%s*$")
        if trimmed and trimmed ~= "" then
            table.insert(names, trimmed)
        end
    end

    helperConfig.uhfriendList = {}
    for i, name in ipairs(names) do
        if i > MAX_FRIENDS then
            break
        end
        helperConfig.uhfriendList[i] = { name = name, percent = 90, enabled = true }
    end
    saveSettings()
end

