-- Bot functions
function updateHealingPercent(buttonId, newPercent)
    local buttonIndex = string.match(buttonId, "%d+")
    if not buttonIndex then
        return
    end

    buttonIndex = tonumber(buttonIndex)
    local config = helperConfig.spells[buttonIndex + 1]
    local step = getPercentStep()
    local minValue = 1
    local maxValue = 99
    if string.find(buttonId, "add") then
        local newValue = math.min(config.percent + step, maxValue)
        if newValue == config.percent then
            healingPanel:recursiveGetChildById("addPercentButton" .. buttonIndex):setEnabled(false)
            return
        end

        healingPanel:recursiveGetChildById("rmvPercentButton" .. buttonIndex):setEnabled(true)
        config.percent = newValue
        local label = healingPanel:recursiveGetChildById("spellPercentLabel" .. buttonIndex)
        label:setText(config.percent .. "%")

        if config.percent >= maxValue then
            healingPanel:recursiveGetChildById("addPercentButton" .. buttonIndex):setEnabled(false)
        end
    elseif string.find(buttonId, "rmv") then
        local newValue = math.max(config.percent - step, minValue)
        if newValue == config.percent then
            healingPanel:recursiveGetChildById("rmvPercentButton" .. buttonIndex):setEnabled(false)
            return
        end

        healingPanel:recursiveGetChildById("addPercentButton" .. buttonIndex):setEnabled(true)
        config.percent = newValue
        local label = healingPanel:recursiveGetChildById("spellPercentLabel" .. buttonIndex)
        label:setText(config.percent .. "%")

        if config.percent <= minValue then
            healingPanel:recursiveGetChildById("rmvPercentButton" .. buttonIndex):setEnabled(false)
        end
    end

    cachedSpells = table.copy(helperConfig.spells)
    table.sort(
        cachedSpells,
        function(a, b)
            return a.percent < b.percent
        end
    )
end

-- Delay (ms) que o input numerico espera o usuario parar de digitar antes de aplicar o clamp min/max
NUMERIC_INPUT_DEBOUNCE_MS = 1000

-- Cancela qualquer clamp agendado no widget (use ao fechar popup ou no blur)
function cancelNumericInputClamp(widget)
    if not widget then return end
    if widget._numericClampEvent then
        removeEvent(widget._numericClampEvent)
        widget._numericClampEvent = nil
    end
end

-- Agenda clamp visual apos o usuario parar de digitar.
-- Se ao disparar o texto estiver vazio/invalido e defaultVal nao for nil, aplica defaultVal.
-- onClampFinish(clampedValue, widget) e chamado somente quando o clamp altera o texto.
function scheduleNumericInputClamp(widget, minVal, maxVal, defaultVal, onClampFinish)
    if not widget then return end
    if widget._numericClampEvent then
        removeEvent(widget._numericClampEvent)
        widget._numericClampEvent = nil
    end
    widget._numericClampEvent = scheduleEvent(function()
        widget._numericClampEvent = nil
        if not widget or (widget.isDestroyed and widget:isDestroyed()) then return end

        local text = widget:getText() or ""
        local value = tonumber(text)

        if value == nil then
            if defaultVal ~= nil then
                widget:setText(tostring(defaultVal))
                if widget.setCursorPos then widget:setCursorPos(-1) end
                if onClampFinish then onClampFinish(defaultVal, widget) end
            end
            return
        end

        local clamped = value
        if minVal ~= nil and clamped < minVal then clamped = minVal end
        if maxVal ~= nil and clamped > maxVal then clamped = maxVal end

        if clamped ~= value then
            widget:setText(tostring(clamped))
            if widget.setCursorPos then widget:setCursorPos(-1) end
            if onClampFinish then onClampFinish(clamped, widget) end
        end
    end, NUMERIC_INPUT_DEBOUNCE_MS)
end

-- Sanitiza chars nao-numericos em cada keystroke (mantem digitacao bloqueada para letras/simbolos)
-- e agenda o clamp min/max via debounce, para nao truncar valores intermediarios enquanto o usuario digita.
-- Retorna o valor parseado (sem clamp) ou nil se vazio/invalido — side effects devem clampar internamente.
function validatePercentInput(widget, minVal, maxVal, defaultVal)
    if not widget then return nil end

    minVal = minVal or 0
    maxVal = maxVal or 100
    defaultVal = defaultVal or 80

    local text = widget:getText() or ""
    local sanitized = text:gsub("[^0-9]", "")

    if sanitized ~= text then
        widget:setText(sanitized)
        if widget.setCursorPos then widget:setCursorPos(-1) end
    end

    scheduleNumericInputClamp(widget, minVal, maxVal, defaultVal, nil)

    if sanitized == "" then
        return nil
    end

    return tonumber(sanitized)
end

