function updateRuneShooterCreatures(name, index, creatures)
    local profile = getShooterProfile()
    if not profile then
        return
    end
    local slot = (tonumber(index) or 0) + 1
    if not profile.runes[slot] then
        profile.runes[slot] = ensureShooterRuneRule({}, slot)
    end
    -- creatures ja vem como texto completo da opcao ("1" ou "1+", "2+", etc)
    local optionText = creatures or "1+"

    -- Se for "1" (sem +), salvar como -1 (exato)
    -- Se for "1+" ou outro numero com +, salvar como numero positivo (ou mais)
    if optionText == "1" then
        profile.runes[slot].creatures = -1
    else
        local num = tonumber(optionText:match("%d+"))
        profile.runes[slot].creatures = num or 1
    end
end

