function castHealingSpell(spellId, spellParameter)
    if not spellId or spellId == 0 then
        return false
    end

    local player = g_game.getLocalPlayer()
    if not player then
        return false
    end

    local spell = Spells.getSpellByClientId(tonumber(spellId))
    if not spell or spell.id == 0 then
        return false
    end

    if (isSpellOnCooldown(spell)) then
        return false
    end

    if spell.mana and spell.mana > 0 then
        if player:getMana() < spell.mana then
            return false
        end
    end

    if spell.soul and spell.soul > 0 then
        if player:getSoul() < spell.soul then
            return false
        end

        if spell.source and not hasItemInBackpack(spell.source) then
            return false
        end
    end

    local parameter = trimHealingText(spellParameter or "")
    if parameter ~= "" then
        g_game.talk(string.format('%s "%s"', spell.words, parameter), true)
    else
        g_game.talk(spell.words, true)
    end
    CastTiming.noteSpellCastSent(spell)

    return true
end

-- Energy Ring is an "alternative tool": it swaps an energy ring in/out of the ring
-- slot based on HP/MP and has its OWN enable toggle (energyRingEnabled). It must NOT
-- depend on the master Auto Healing gate, so it lives in its own function (run from
-- the healing cycle BEFORE the auto-healing early-return) instead of nested inside
-- checkHealthHealing's auto-healing-gated body.
function checkEnergyRing()
    if not isEnergyRingHelperActive() then
        return
    end

    local player = g_game.getLocalPlayer()
    if not player or not g_game.isOnline() then
        return
    end

    local maxHealth = player:getMaxHealth()
    if not maxHealth or maxHealth <= 0 then
        return
    end
    local maxMana = player:getMaxMana()
    local healthPercent = (player:getHealth() / maxHealth) * 100
    local manaPercent = maxMana > 0 and (player:getMana() / maxMana) * 100 or 0
    local now = g_clock.millis()

    local config = helperConfig.energyRing or {}
    local function clampPercent(value, fallback)
        local number = tonumber(value)
        if not number then
            return fallback or 0
        end
        if number < 0 then
            return 0
        end
        if number > 100 then
            return 100
        end
        return number
    end

    local healthToEquip = clampPercent(config.healthToEquip, 0)
    local healthToDeequip = clampPercent(config.healthToDeequip, 100)
    local minManaToEquip = clampPercent(config.minManaToEquip, 0)
    local manaToEquip = clampPercent(config.manaToEquip, 0)
    if manaToEquip >= minManaToEquip then
        manaToEquip = math.max(0, minManaToEquip - 1)
    end

    local ringSlot = player:getInventoryItem(9)
    local ringId = ringSlot and ringSlot:getId() or 0
    local hasEnergyRing = ringId == ENERGY_RING_EQUIPPED_ID or
        ringId == ENERGY_RING_UNEQUIPPED_ID or
        isDynamicMatch(ENERGY_RING_EQUIPPED_ID, ringId)
    local shouldEquip = healthPercent <= healthToEquip and manaPercent >= minManaToEquip
    local shouldDeequip = healthPercent >= healthToDeequip or manaPercent <= manaToEquip
    local hasManaShield = false
    if player.getManaShield and type(player.getManaShield) == "function" then
        hasManaShield = player:getManaShield() > 0
    else
        hasManaShield = player:hasState(PlayerStates.ManaShield) or false
    end

    local function logEnergyRing(action, attemptId)
        helperConfig.energyRingLog = helperConfig.energyRingLog or {
            time = 0,
            ringId = -1,
            action = "",
            attemptId = -1
        }
        local nowMillis = g_clock.millis()
        if nowMillis - helperConfig.energyRingLog.time < 1000 and
            helperConfig.energyRingLog.ringId == ringId and
            helperConfig.energyRingLog.action == action and
            helperConfig.energyRingLog.attemptId == (attemptId or -1) then
            return
        end
        helperConfig.energyRingLog.time = nowMillis
        helperConfig.energyRingLog.ringId = ringId
        helperConfig.energyRingLog.action = action
        helperConfig.energyRingLog.attemptId = attemptId or -1
    end

    local function equipActionbarItem(itemId)
        local item = Item.create(itemId)
        if not item then
            return false
        end
        g_game.equipItem(item)
        return true
    end

    local function attemptEnergyRingDeequip(actionLabel)
        if not ringSlot or ringId <= 0 then
            logEnergyRing(actionLabel .. "_no_slot", ringId)
            return
        end
        if spellsCooldown["ring"] and spellsCooldown["ring"] > now then
            logEnergyRing(actionLabel .. "_cooldown", ringId)
            return
        end

        local attempted = equipActionbarItem(ringId)
        spellsCooldown["ring"] = now + getEngineIntervalValue("healing")

        if attempted then
            logEnergyRing(actionLabel .. "_equip", ringId)
        else
            logEnergyRing(actionLabel .. "_failed", ringId)
        end
    end

    if hasManaShield and shouldEquip then
        logEnergyRing("equip_skipped_mana_shield", ENERGY_RING_UNEQUIPPED_ID)
    elseif hasManaShield and shouldDeequip then
        attemptEnergyRingDeequip("deequip_mana_shield")
    elseif shouldEquip and not hasEnergyRing then
        logEnergyRing("equip_request", ENERGY_RING_UNEQUIPPED_ID)
        if hasItemInBackpack(ENERGY_RING_UNEQUIPPED_ID) > 0 then
            pushRing(ENERGY_RING_UNEQUIPPED_ID)
        end
    elseif hasEnergyRing and ringSlot then
        if shouldDeequip then
            attemptEnergyRingDeequip("deequip_request")
        else
            logEnergyRing("keep_equipped", ringId)
        end
    end
end

function checkHealthHealing()
    if not hotkeyHelperStatus then
        return false
    end

    -- Energy Ring is an alternative tool with its own toggle; it must run even when
    -- Auto Healing is OFF, so evaluate it before the auto-healing gate below.
    checkEnergyRing()

    -- Check if auto healing is enabled
    local autoHealingActive = helperConfig and helperConfig.autoHealingEnabled

    if not autoHealingActive then
        return false
    end

    local player = g_game.getLocalPlayer()
    if not player or not g_game.isOnline() then
        return false
    end

    local health, maxHealth = player:getHealth(), player:getMaxHealth()
    local mana, maxMana = player:getMana(), player:getMaxMana()
    local healthPercent = (health / maxHealth) * 100
    local manaPercent = maxMana > 0 and (mana / maxMana) * 100 or 0
    local initialHealthPercent = healthPercent

    local now = g_clock.millis()

    helperConfig = helperConfig or {}

    if not helperConfig.initialized then
        helperConfig.lastUtamo = 0
        helperConfig.lastExana = 0
        helperConfig.lastMagicPotion = 0
        helperConfig.initialized = true
    end

    local function sanitizeCooldown(value, currentTime)
        if not value or value < 0 or value > currentTime then
            return 0
        end
        return value
    end

    helperConfig.lastUtamo = sanitizeCooldown(helperConfig.lastUtamo, now)
    helperConfig.lastExana = sanitizeCooldown(helperConfig.lastExana, now)
    helperConfig.lastMagicPotion = sanitizeCooldown(helperConfig.lastMagicPotion, now)

    -- Reactive mode: the server cooldowns (0xA4/0xA6) govern the pace; these
    -- local delays shrink to a retry floor so a lost echo can't retry-storm.
    -- The potion floor only shrinks once a real 0xA6 proved the server sends
    -- the multi-use delay, otherwise it would spam-drink (see usePotion).
    local reactiveTiming = CastTiming.isActive()
    local utamoDelay = reactiveTiming and 200 or 500
    local exanaDelay = reactiveTiming and 200 or 800
    local magicPotionDelay = (reactiveTiming and CastTiming.hasMultiUseEcho()) and 200 or 1000

    -- Check mana shield state (used by multiple features)
    local hasManaShield = false
    if player.getManaShield and type(player.getManaShield) == "function" then
        hasManaShield = player:getManaShield() > 0
    else
        hasManaShield = player:hasState(PlayerStates.ManaShield) or false
    end

    local magicPotionReady = (now - helperConfig.lastMagicPotion) >= magicPotionDelay
    local magicPotionHpThreshold = helperConfig.magicPotionHpPercent or 30

    -- Auto Utamo Vita (spell)
    local utamoSpellCooldown = 2000 -- utamo vita spell cooldown in ms
    local utamoActive = isUtamoHelperActive()
    local utamoConfig = helperConfig.utamo and helperConfig.utamo[1]
    local utamoPercent = utamoConfig and utamoConfig.percent or 80

    if utamoActive then
        local utamoPlayer = g_game.getLocalPlayer()
        local utamoStates = utamoPlayer and utamoPlayer:getStates() or 0
        local utamoIsRooted = bit.band(utamoStates, PlayerStates.Rooted) > 0
        local utamoIsFeared = bit.band(utamoStates, PlayerStates.Feared) > 0
        local utamoCondition = false
        if helperConfig.utamoVitaUseWhenRooted and utamoIsRooted then
            utamoCondition = true
        end
        if helperConfig.utamoVitaUseWhenFeared and utamoIsFeared then
            utamoCondition = true
        end

        local hpTriggered = utamoConfig and initialHealthPercent <= utamoPercent

        local renewTriggered = false
        if helperConfig.utamoVitaRenewOnShield and hasManaShield and utamoPlayer then
            local maxShield = 0
            local currentShield = 0
            if utamoPlayer.getMaxManaShield and type(utamoPlayer.getMaxManaShield) == "function" then
                maxShield = utamoPlayer:getMaxManaShield()
            end
            if utamoPlayer.getManaShield and type(utamoPlayer.getManaShield) == "function" then
                currentShield = utamoPlayer:getManaShield()
            end
            if maxShield > 0 and currentShield > 0 then
                local shieldPercent = (currentShield / maxShield) * 100
                local threshold = helperConfig.utamoVitaRenewShieldPercent or 30
                if shieldPercent < threshold then
                    renewTriggered = true
                end
            end
        end

        local shouldCast = renewTriggered or ((utamoCondition or hpTriggered) and not hasManaShield)
        if shouldCast then
            local utamoReady = (now - helperConfig.lastUtamo) >= utamoDelay
            if utamoReady then
                local utamoSpell = getCachedSpell("utamo vita")
                if utamoSpell and not isSpellOnCooldown(utamoSpell) then
                    g_game.talk("utamo vita", true)
                    CastTiming.noteSpellCastSent(utamoSpell)
                    helperConfig.lastUtamo = now
                end
            end
        end
    end

    -- Magic Potion (standalone feature)
    local magicPotionEnabled = isMagicPotionActive()

    if magicPotionEnabled and magicPotionReady then
        local player = g_game.getLocalPlayer()
        local playerStates = player and player:getStates() or 0
        local isRooted = bit.band(playerStates, PlayerStates.Rooted) > 0
        local isFeared = bit.band(playerStates, PlayerStates.Feared) > 0

        local shouldUse = false
        local conditionTrigger = false
        local renewTrigger = false

        if helperConfig.magicPotionUseWhenRooted and isRooted then
            conditionTrigger = true
        end
        if helperConfig.magicPotionUseWhenFeared and isFeared then
            conditionTrigger = true
        end

        if helperConfig.magicPotionRenewOnUtamoShield and hasManaShield then
            local maxShield = 0
            local currentShield = 0

            if player.getMaxManaShield and type(player.getMaxManaShield) == "function" then
                maxShield = player:getMaxManaShield()
            end

            if player.getManaShield and type(player.getManaShield) == "function" then
                currentShield = player:getManaShield()
            end

            if maxShield > 0 and currentShield > 0 then
                local shieldPercent = (currentShield / maxShield) * 100
                local utamoShieldThreshold = helperConfig.magicPotionUtamoShieldPercent or 30
                if shieldPercent < utamoShieldThreshold then
                    renewTrigger = true
                end
            end
        end

        -- Feared/Rooted trigger só vale sem shield ativo; senão a poção é desperdiçada sobre o utamo.
        local useCondition = (conditionTrigger and not hasManaShield) or renewTrigger

        if useCondition or (initialHealthPercent <= magicPotionHpThreshold and not hasManaShield) then
            if helperConfig.magicPotionOnlyOnVitaCD then
                -- Only use when utamo vita spell was recently cast and is on cooldown
                local timeSinceUtamo = now - helperConfig.lastUtamo
                local utamoOnCooldown = timeSinceUtamo > 0 and timeSinceUtamo < utamoSpellCooldown
                if utamoOnCooldown then
                    shouldUse = true
                end
            else
                -- Use anytime condition is met or HP is below threshold
                shouldUse = true
            end
        end

        if shouldUse then
            local used = useMagicPotion()
            if used then
                helperConfig.lastMagicPotion = now
            end
        end
    end

    -- Auto Exana Vita (remove mana shield when HP is high enough)
    if isExanaHelperActive() then
        local config = helperConfig.exana[1]
        if config and healthPercent >= config.percent then
            if hasManaShield and now - helperConfig.lastExana >= exanaDelay then
                local utamoReady = true
                if helperConfig.exanaVitaWaitUtamoCD then
                    -- Only drop the shield when Utamo Vita is off cooldown,
                    -- so the player can immediately reapply it if HP drops again.
                    -- Check the real spell cooldown so manual casts also count.
                    local utamoSpell = getCachedSpell("utamo vita")
                    if utamoSpell and isSpellOnCooldown(utamoSpell) then
                        utamoReady = false
                    end
                end
                if utamoReady then
                    local exanaSpell = getCachedSpell("exana vita")
                    if exanaSpell and not isSpellOnCooldown(exanaSpell) then
                        g_game.talk("exana vita", true)
                        CastTiming.noteSpellCastSent(exanaSpell)
                        helperConfig.lastExana = now
                    end
                end
            end
        end
    end

    -- Energy Ring moved to its own checkEnergyRing() (decoupled from Auto Healing).

    local usedHealingRule, hasHealingRules = processHealingRules(healthPercent, manaPercent, mana, player)
    if hasHealingRules then
        return usedHealingRule
    end

    -- Fallback to legacy fixed slots only when no dynamic healing rules exist
    if autoHealingActive then
        -- OPTIMIZATION: Use cached sorted potion list (only re-sorts when config changes)
        local prioritizedPotions = getCachedPotionSort()

        -- Use health potions when health is low
        for _, potion in ipairs(prioritizedPotions) do
            if hasItemInBackpack(potion.id) and healthPercent <= potion.percent then
                -- Passa o config para considerar o priority
                if isHealthPotion(potion.id, potion) then
                    usePotion(potion.id)
                end
            end
        end

        -- OPTIMIZATION: Use cached sorted spell list (only re-sorts when config changes)
        local prioritizedSpells = getCachedSpellSort()

        for _, spell in ipairs(prioritizedSpells) do
            if ignoredSpellsIds[spell.id] then
                goto skipSpell
            end

            if healthPercent <= spell.percent then
                castHealingSpell(spell.id)
            end

            ::skipSpell::
        end
    end
end

-- NOTE: Amulet/Ring swap foi movido para checkEquipmentSwap (evento independente)

eventTable.checkHealthHealing.action = checkHealthHealing

function isEquipmentRuleBlockedByEquippedItem(rule, slotAmulet, slotRing)
    if type(rule) ~= "table" then
        return false
    end
    if rule.dontExecuteIfEquipped ~= true then
        return false
    end

    local blockedIds = {}
    local configuredIds = rule.dontExecuteItemIds
    if type(configuredIds) ~= "table" then
        configuredIds = { tonumber(rule.dontExecuteItemId) or 0, 0 }
    end

    for i = 1, 2 do
        local blockedItemId = tonumber(configuredIds[i]) or 0
        if blockedItemId > 0 then
            table.insert(blockedIds, blockedItemId)
        end
    end

    if #blockedIds == 0 then
        return false
    end

    for _, blockedItemId in ipairs(blockedIds) do
        if slotAmulet then
            local equippedAmuletId = slotAmulet:getId()
            if equippedAmuletId == blockedItemId or isDynamicMatch(blockedItemId, equippedAmuletId) then
                return true
            end
        end

        if slotRing then
            local equippedRingId = slotRing:getId()
            if equippedRingId == blockedItemId or isDynamicMatch(blockedItemId, equippedRingId) then
                return true
            end
        end
    end

    return false
end

-- Equipment Swap independente do Healing
-- Processa amulets e rings baseado em HP/MP percent
function checkEquipmentSwap()
    if not hotkeyHelperStatus then
        return false
    end

    if not helperConfig or not helperConfig.equipmentSwapEnabled then
        return false
    end

    local player = g_game.getLocalPlayer()
    if not player or not g_game.isOnline() then
        return false
    end

    local health, maxHealth = player:getHealth(), player:getMaxHealth()
    local mana, maxMana = player:getMana(), player:getMaxMana()
    local healthPercent = (health / maxHealth) * 100
    local manaPercent = maxMana > 0 and (mana / maxMana) * 100 or 0

    ensureEquipmentSwapConfig()

    -- Process amulets
    for _, amulet in ipairs(helperConfig.amulets or {}) do
        if amulet.enabled and amulet.id > 0 then
            if not isEquipmentRuleComplete(amulet) then
                goto continue_amulet
            end
            if not player then
                goto continue_amulet
            end

            local slotAmulet = player:getInventoryItem(InventorySlotNeck)
            local slotRing = player:getInventoryItem(InventorySlotFinger)
            local isEquipped = false
            local equippedId = 0
            if slotAmulet then
                equippedId = slotAmulet:getId()
                isEquipped = (equippedId == amulet.id or isDynamicMatch(amulet.id, equippedId))
            end

            if amulet.actionType == "Unequip" then
                if not isEquipped then
                    goto continue_amulet
                end

                if not evaluateEquipmentRuleStatusConditions(amulet, player) then
                    goto continue_amulet
                end

                if isEquipmentRuleBlockedByEquippedItem(amulet, slotAmulet, slotRing) then
                    goto continue_amulet
                end

                if evaluateEquipmentRuleTrigger(amulet, healthPercent, manaPercent) then
                    popAmulet()
                end

                goto continue_amulet
            end

            local alwaysEquipIfNone = amulet.alwaysEquipIfNone == true
            local excludeAmuletIds = amulet.excludeAmuletIds or { 0, 0 }
            local excludeRingIds = amulet.excludeRingIds or { 0, 0 }

            if isEquipped then
                -- Item esta equipado, nao fazer nada
            else
                -- Verificar se esta equipado com algum amuleto excluido
                local shouldSkip = false
                if slotAmulet then
                    local equippedAmuletId = slotAmulet:getId()
                    for _, excludeId in ipairs(excludeAmuletIds) do
                        if excludeId > 0 and (equippedAmuletId == excludeId or isDynamicMatch(excludeId, equippedAmuletId)) then
                            shouldSkip = true
                            break
                        end
                    end
                end

                if shouldSkip then
                    goto continue_amulet
                end

                -- Verificar se esta equipado com algum ring excluido
                if slotRing then
                    local equippedRingId = slotRing:getId()
                    for _, excludeId in ipairs(excludeRingIds) do
                        if excludeId > 0 and (equippedRingId == excludeId or isDynamicMatch(excludeId, equippedRingId)) then
                            shouldSkip = true
                            break
                        end
                    end
                end

                if shouldSkip then
                    goto continue_amulet
                end

                if isEquipmentRuleBlockedByEquippedItem(amulet, slotAmulet, slotRing) then
                    goto continue_amulet
                end

                if not evaluateEquipmentRuleStatusConditions(amulet, player) then
                    goto continue_amulet
                end

                -- Item nao esta equipado, verificar se deve equipar
                local shouldEquip = false

                -- Verificar condicoes de equipar
                if alwaysEquipIfNone and not slotAmulet then
                    shouldEquip = true
                elseif evaluateEquipmentRuleTrigger(amulet, healthPercent, manaPercent) then
                    shouldEquip = true
                end

                if shouldEquip then
                    pushAmulet(amulet.id)
                end
            end

            ::continue_amulet::
        end
    end

    -- Process rings (respeitando Energy Ring do healing se estiver ativo)
    local skipRingSwap = false

    -- Verificar se Energy Ring esta ativo e deve ser respeitado
    if isEnergyRingHelperActive() then
        local config = helperConfig.energyRing or {}
        local ringSlot = player:getInventoryItem(9)
        local ringId = ringSlot and ringSlot:getId() or 0
        local hasEnergyRing = ringId == ENERGY_RING_EQUIPPED_ID or
            ringId == ENERGY_RING_UNEQUIPPED_ID or
            isDynamicMatch(ENERGY_RING_EQUIPPED_ID, ringId)
        if hasEnergyRing then
            skipRingSwap = true
        end
    end

    if not skipRingSwap then
        for _, ring in ipairs(helperConfig.rings or {}) do
            if ring.enabled and ring.id > 0 then
                if not isEquipmentRuleComplete(ring) then
                    goto continue_ring
                end
                if not player then
                    goto continue_ring
                end

                local slotRing = player:getInventoryItem(InventorySlotFinger)
                local slotAmulet = player:getInventoryItem(InventorySlotNeck)
                local isEquipped = false
                local equippedId = 0
                if slotRing then
                    equippedId = slotRing:getId()
                    isEquipped = (equippedId == ring.id or isDynamicMatch(ring.id, equippedId))
                end

                if ring.actionType == "Unequip" then
                    if not isEquipped then
                        goto continue_ring
                    end

                    if not evaluateEquipmentRuleStatusConditions(ring, player) then
                        goto continue_ring
                    end

                    if isEquipmentRuleBlockedByEquippedItem(ring, slotAmulet, slotRing) then
                        goto continue_ring
                    end

                    if evaluateEquipmentRuleTrigger(ring, healthPercent, manaPercent) then
                        popRing()
                    end

                    goto continue_ring
                end

                local alwaysEquipIfNone = ring.alwaysEquipIfNone == true
                local excludeAmuletIds = ring.excludeAmuletIds or { 0, 0 }
                local excludeRingIds = ring.excludeRingIds or { 0, 0 }
                local respectEnergyRing = ring.respectEnergyRing == true

                if isEquipped then
                    -- Item esta equipado, nao fazer nada
                else
                    -- Verificar se esta equipado com Energy Ring (se respectEnergyRing estiver ativo)
                    if respectEnergyRing and slotRing then
                        local equippedRingId = slotRing:getId()
                        if equippedRingId == ENERGY_RING_EQUIPPED_ID or
                            equippedRingId == ENERGY_RING_UNEQUIPPED_ID or
                            isDynamicMatch(ENERGY_RING_EQUIPPED_ID, equippedRingId) then
                            goto continue_ring
                        end
                    end

                    -- Verificar se esta equipado com algum amuleto excluido
                    if slotAmulet then
                        local equippedAmuletId = slotAmulet:getId()
                        for _, excludeId in ipairs(excludeAmuletIds) do
                            if excludeId > 0 and (equippedAmuletId == excludeId or isDynamicMatch(excludeId, equippedAmuletId)) then
                                goto continue_ring
                            end
                        end
                    end

                    -- Verificar se esta equipado com algum ring excluido
                    if slotRing then
                        local equippedRingId = slotRing:getId()
                        for _, excludeId in ipairs(excludeRingIds) do
                            if excludeId > 0 and (equippedRingId == excludeId or isDynamicMatch(excludeId, equippedRingId)) then
                                goto continue_ring
                            end
                        end
                    end

                    if isEquipmentRuleBlockedByEquippedItem(ring, slotAmulet, slotRing) then
                        goto continue_ring
                    end

                    if not evaluateEquipmentRuleStatusConditions(ring, player) then
                        goto continue_ring
                    end

                    -- Item nao esta equipado, verificar se deve equipar
                    local shouldEquip = false

                    -- Verificar condicoes de equipar
                    if alwaysEquipIfNone and not slotRing then
                        shouldEquip = true
                    elseif evaluateEquipmentRuleTrigger(ring, healthPercent, manaPercent) then
                        shouldEquip = true
                    end

                    if shouldEquip then
                        pushRing(ring.id)
                    end
                end

                ::continue_ring::
            end
        end
    end
end

eventTable.checkEquipmentSwap.action = checkEquipmentSwap

-- New function to find items in ANY container (open or closed)
-- Works like action bar - doesn't require containers to be open
function findItemAnywhere(itemId)
    local player = g_game.getLocalPlayer()
    if not player then
        return nil
    end

    -- First, try to find in inventory slots
    for slot = InventorySlotFirst, InventorySlotLast do
        local item = player:getInventoryItem(slot)
        if item and item:getId() == itemId then
            return item
        end
    end

    -- Then try findItemInContainers (only iterates OPEN containers in m_containers)
    local item = g_game.findItemInContainers(itemId, -1)
    if item then
        return item
    end

    -- Fallback: server-cached inventory count enxerga containers fechados.
    -- Sem ref direta, devolve `true` para o caller usar Item.create + equipItem
    -- (o packet sendEquipItemWithCountOrSubType só precisa do itemId).
    if player.getInventoryCount and type(player.getInventoryCount) == "function" then
        local success, count = pcall(player.getInventoryCount, player, itemId, 0)
        if success and count and count > 0 then
            return true
        end
    end

    if player.getItemsCount and type(player.getItemsCount) == "function" then
        local success, count = pcall(player.getItemsCount, player, itemId)
        if success and count and count > 0 then
            return true
        end
    end

    return nil
end

-- Get count of items anywhere (open or closed containers)
function getItemCountAnywhere(itemId)
    if not itemId or itemId == 0 then
        return 0
    end

    local player = g_game.getLocalPlayer()
    if not player then
        return 0
    end

    local count = 0

    -- Method 1: getInventoryCount with tier 0 - uses server cache (works with closed containers)
    if player.getInventoryCount and type(player.getInventoryCount) == "function" then
        local success, result = pcall(player.getInventoryCount, player, itemId, 0)
        if success and result and type(result) == "number" and result > 0 then
            count = result
        end
    end

    -- Method 2: getItemsCount - searches open containers (fallback if cache miss)
    if count == 0 then
        if player.getItemsCount and type(player.getItemsCount) == "function" then
            local success, result = pcall(player.getItemsCount, player, itemId)
            if success and result and type(result) == "number" and result > 0 then
                count = result
            end
        end
    end

    -- Method 3: Use g_game.findItemInContainers to check all containers (including closed)
    if count == 0 then
        local item = g_game.findItemInContainers(itemId, -1)
        if item then
            -- If we found at least one item, try to count all
            if player.getItems and type(player.getItems) == "function" then
                local success, items = pcall(player.getItems, player, itemId)
                if success and type(items) == "table" and #items > 0 then
                    -- Sum all item counts for stackable items
                    for i = 1, #items do
                        count = count + (items[i]:getCount() or 1)
                    end
                else
                    count = item:getCount() or 1
                end
            else
                count = item:getCount() or 1
            end
        end
    end

    return count
end

function hasItemInBackpack(potionId)
    local player = g_game.getLocalPlayer()
    if not player then
        return 0
    end

    local count = 0

    -- Try getItemsCount first
    if player.getItemsCount and type(player.getItemsCount) == "function" then
        local success, result = pcall(player.getItemsCount, player, potionId)
        if success and result and result > 0 then
            count = result
        end
    end

    -- Fallback to getInventoryCount if getItemsCount failed
    if count == 0 and player.getInventoryCount and type(player.getInventoryCount) == "function" then
        local success, result = pcall(player.getInventoryCount, player, potionId, 0)
        if success and result and result > 0 then
            count = result
        end
    end

    return count
end

-- Sets an equipment rule's count label to the total owned (bag + worn variant).
