-- Atualiza contagem de todos os itens selecionados
function updateAllItemCounts()
    if not helper then
        return
    end

    -- Atualizar contagens de potions
    if helperConfig.potions then
        for i = 0, 3 do
            local potionId = helperConfig.potions[i + 1] and helperConfig.potions[i + 1].id
            local countLabel = helper:recursiveGetChildById("potionItemCount" .. i)
            if potionId and potionId > 0 then
                if countLabel then
                    local count = getItemCountAnywhere(potionId)
                    countLabel:setText(tostring(count))
                    countLabel:setVisible(true)
                end
            else
                if countLabel then
                    countLabel:setVisible(false)
                end
            end
        end
    end

    ensureEquipmentSwapConfig()

    -- Atualizar contagens de amulets
    for i, amulet in ipairs(helperConfig.amulets or {}) do
        local amuletId = amulet and amulet.id or 0
        local countLabel = helper:recursiveGetChildById("amuletItemCount" .. (i - 1))
        if amuletId and amuletId > 0 then
            setEquipmentRuleCountLabel(countLabel, amuletId)
        elseif countLabel then
            countLabel:setVisible(false)
        end
    end

    -- Atualizar contagens de rings
    for i, ring in ipairs(helperConfig.rings or {}) do
        local ringId = ring and ring.id or 0
        local countLabel = helper:recursiveGetChildById("ringItemCount" .. (i - 1))
        if ringId and ringId > 0 then
            setEquipmentRuleCountLabel(countLabel, ringId)
        elseif countLabel then
            countLabel:setVisible(false)
        end
    end

    -- Atualizar contagens de Tank Mode Amulet
    local tankModeAmuletId = helperConfig.tankModeAmuletId
    local tankAmuletCountLabel = helper:recursiveGetChildById("tankModeAmuletItemCount")
    if tankModeAmuletId and tankModeAmuletId > 0 then
        if tankAmuletCountLabel then
            local count = getItemCountAnywhere(tankModeAmuletId)
            tankAmuletCountLabel:setText(tostring(count))
            tankAmuletCountLabel:setVisible(true)
        end
    else
        if tankAmuletCountLabel then
            tankAmuletCountLabel:setVisible(false)
        end
    end

    -- Atualizar contagens de Tank Mode Ring
    local tankModeRingId = helperConfig.tankModeRingId
    local tankRingCountLabel = helper:recursiveGetChildById("tankModeRingItemCount")
    if tankModeRingId and tankModeRingId > 0 then
        if tankRingCountLabel then
            local count = getItemCountAnywhere(tankModeRingId)
            tankRingCountLabel:setText(tostring(count))
            tankRingCountLabel:setVisible(true)
        end
    else
        if tankRingCountLabel then
            tankRingCountLabel:setVisible(false)
        end
    end

    -- Atualizar contagens de runas do shooter
    local shooterProfile = getShooterProfile()
    if shooterProfile and shooterProfile.runes then
        for i = 0, 1 do
            local runeId = shooterProfile.runes[i + 1] and shooterProfile.runes[i + 1].id
            local countLabel = helper:recursiveGetChildById("runeShooterButton" .. i .. "Count")
            if runeId and runeId > 0 then
                if countLabel then
                    local count = getItemCountAnywhere(runeId)
                    countLabel:setText(tostring(count))
                    countLabel:setVisible(true)
                end
            else
                if countLabel then
                    countLabel:setVisible(false)
                end
            end
        end
    end

    -- Atualizar estado dos portables (desabilitar se nao tiver)
    updatePortableToolsState()
end

function updatePortableToolsState()
    if not helper then
        return
    end

    local player = g_game.getLocalPlayer()
    if not player or not g_game.isOnline() then
        return
    end

    -- Portable Trader (auto Loot Seller): VIP/premium only. isPremium() reflects the
    -- server's basic-data byte, which KoliseuOT sends as isPremium||isVip, so it is
    -- true for VIP players. Guard for old builds without the binding (-> not VIP).
    local isVip = false
    if player.isPremium then
        isVip = player:isPremium() and true or false
    end

    local portableTraderCheck = helper:recursiveGetChildById("portableTrader")
    if portableTraderCheck then
        portableTraderCheck:setEnabled(isVip)
        -- Non-VIP: also clear the toggle so a greyed-out box isn't left checked.
        if not isVip and portableTraderCheck:isChecked() then
            portableTraderCheck:setChecked(false)
        end
    end

    local portableTraderCapInput = helper:recursiveGetChildById("portableTraderCapInput")
    if portableTraderCapInput then
        portableTraderCapInput:setEnabled(isVip)
    end
end

function checkManaHealing(mana, maxMana)
    local player = g_game.getLocalPlayer()
    if not player or not g_game.isOnline() then
        return
    end

    local manaPercent = (mana / maxMana) * 100

    -- Debug: Show configured potions (only once to avoid spam)
    if not helperConfig.debugPotionsShown then
        for i, potion in ipairs(helperConfig.potions) do
            if isManaPotion(potion.id) then

            elseif isHealthPotion(potion.id) then

            else

            end
        end
        helperConfig.debugPotionsShown = true
    end

    local prioritizedManaPotions = {}
    for _, potion in ipairs(helperConfig.potions) do
        -- Passa o config para considerar o priority
        if isManaPotion(potion.id, potion) then
            if potion.id > 0 then
                table.insert(prioritizedManaPotions, potion)
            end
        end
    end

    table.sort(
        prioritizedManaPotions,
        function(a, b)
            if a.percent == b.percent then
                local aOrder = a.orderPriority or 999
                local bOrder = b.orderPriority or 999
                return aOrder < bOrder
            else
                return a.percent < b.percent
            end
        end
    )

    for _, potion in ipairs(prioritizedManaPotions) do
        if manaPercent <= potion.percent then
            local success = usePotion(potion.id)
            return
        end
    end
end

function useAutoSio(target)
    local spellId = (helperConfig and helperConfig.friendhealingSioSpellId) or 84
    local spell = Spells.getSpellByClientId(tonumber(spellId))
    if not spell or spell.id == 0 then
        return false
    end

    if not checkHealthPriority() then
        return
    end

    if (isSpellOnCooldown(spell)) then
        return false
    end

    g_game.talk(string.format('%s "%s"', spell.words, target:getName()), true)
    CastTiming.noteSpellCastSent(spell)
end

function useAutoGranSio(target)
    local spellId = (helperConfig and helperConfig.gransiohealingSioSpellId) or 242
    local spell = Spells.getSpellByClientId(tonumber(spellId))
    if not spell or spell.id == 0 then
        return false
    end

    if not checkHealthPriority() then
        return false
    end

    if (isSpellOnCooldown(spell)) then
        return false
    end

    g_game.talk(string.format('%s "%s"', spell.words, target:getName()), true)
    CastTiming.noteSpellCastSent(spell)
    return true
end

function useAutoTioSio(target)
    local spellId = 297
    local spell = Spells.getSpellByClientId(spellId)
    if not spell or spell.id == 0 then
        return false
    end

    if not checkHealthPriority() then
        return
    end

    if (isSpellOnCooldown(spell)) then
