function modules.game_helper.toggleHoldAttack(checked)
    helperConfig.holdAttack = checked
    if not checked then
        clearHoldAttackTarget()
        holdAttackWasAttacking = false
    else
        -- If enabling and already attacking something, set it as hold target
        local attackingCreature = g_game.getAttackingCreature()
        if attackingCreature then
            setHoldAttackTarget(attackingCreature)
        end
    end
    saveSettings()
end

function updateHoldAttackLabel()
    local panel = helper and helper.contentPanel and helper.contentPanel:recursiveGetChildById("toolsPanel")
    if not panel then
        return
    end
    local label = panel:recursiveGetChildById("holdAttackTargetLabel")
    if label then
        if helperConfig.holdAttackTargetId and helperConfig.holdAttackTargetId > 0 and helperConfig.holdAttackTargetName then
            label:setText("Target: " .. helperConfig.holdAttackTargetName)
        else
            label:setText("")
        end
    end
end

function setHoldAttackTarget(creature)
    if not creature or not helperConfig.holdAttack then
        return
    end
    helperConfig.holdAttackTargetId = creature:getId()
    helperConfig.holdAttackTargetName = creature:getName()
    updateHoldAttackLabel()
end

function clearHoldAttackTarget()
    helperConfig.holdAttackTargetId = 0
    helperConfig.holdAttackTargetName = nil
    updateHoldAttackLabel()
end

function getHoldAttackTargetId()
    return helperConfig.holdAttackTargetId or 0
end

-- Validate creature is reachable (sight, and path for melee) from current player pos.
-- Avoids "fake target" state: red square shown but server rejects attack.
local function isHoldAttackReachable(creature)
    if not creature then
        return false
    end
    local player = g_game.getLocalPlayer()
    if not player then
        return false
    end
    local playerPos = player:getPosition()
    local targetPos = creature:getPosition()
    if not playerPos or not targetPos or playerPos.z ~= targetPos.z then
        return false
    end
    if not g_map.isSightClear(playerPos, targetPos, false) then
        return false
    end
    local voc = translateVocation(player:getVocation())
    local isMelee = voc == VOCATION_KNIGHT or voc == VOCATION_MONK
    if isMelee then
        local dx = math.abs(playerPos.x - targetPos.x)
        local dy = math.abs(playerPos.y - targetPos.y)
        if dx > 1 or dy > 1 then
            if g_map.findPathJPS then
                local path = g_map.findPathJPS(playerPos, targetPos, 50, 0)
                if not (path and #path > 0) then
                    return false
                end
            end
        end
    end
    return true
end

function checkHoldAttackOnCreatureAppear(creature)
    if not creature or not helperConfig or not helperConfig.holdAttack or helperConfig.autoTargetEnabled then
        return
    end

    local lockedId = tonumber(helperConfig.holdAttackTargetId) or 0
    if lockedId <= 0 or creature:getId() ~= lockedId then
        return
    end

    local targetId = lockedId

    -- Force a fresh attack packet when the locked target reappears.
    -- This avoids stale "square selected" state where client looks targeted but no hits happen.
    g_game.cancelAttack()
    scheduleEvent(function()
        if not helperConfig or not helperConfig.holdAttack or helperConfig.autoTargetEnabled then
            return
        end

        if (tonumber(helperConfig.holdAttackTargetId) or 0) ~= targetId then
            return
        end

        local freshTarget = g_map.getCreatureById(targetId)
        if freshTarget and freshTarget:getHealthPercent() > 0 and isHoldAttackReachable(freshTarget) then
            g_game.attack(freshTarget)
            holdAttackWasAttacking = true
        end
    end, 30)
end

function handleHoldAttackEscapeKey()
    if not helperConfig or not helperConfig.holdAttack then
        return false
    end

    local hasLockedTarget = (tonumber(helperConfig.holdAttackTargetId) or 0) > 0
    local hasCurrentAttack = g_game.getAttackingCreature() ~= nil

    if hasLockedTarget or hasCurrentAttack then
        clearHoldAttackTarget()
        holdAttackWasAttacking = false
        if hasCurrentAttack then
            g_game.cancelAttack()
        end
        return true
    end

    return false
end

function checkHoldAttack()
    if not helperConfig.holdAttack then
        holdAttackWasAttacking = false
        return
    end
    if helperConfig.autoTargetEnabled then
        holdAttackWasAttacking = false
        return
    end
    -- Check if we are currently attacking something
    local attackingCreature = g_game.getAttackingCreature()

    if attackingCreature then
        local currentId = attackingCreature:getId()
        if (tonumber(helperConfig.holdAttackTargetId) or 0) ~= currentId or
            helperConfig.holdAttackTargetName ~= attackingCreature:getName() then
            helperConfig.holdAttackTargetId = currentId
            helperConfig.holdAttackTargetName = attackingCreature:getName()
            updateHoldAttackLabel()
        end
        holdAttackWasAttacking = true
        return
    end

    -- Not attacking anything now
    -- Check if we WERE attacking before
    if holdAttackWasAttacking and helperConfig.holdAttackTargetId and helperConfig.holdAttackTargetId > 0 then
        -- We were attacking, now we're not. Why?
        -- Check if the OLD target is still visible on screen
        local oldTarget = g_map.getCreatureById(helperConfig.holdAttackTargetId)
        local targetStillVisible = oldTarget and oldTarget:getHealthPercent() > 0

        if targetStillVisible then
            -- Target IS visible but we stopped attacking
            -- Re-attack immediately - only ESC key can cancel hold target
            if isHoldAttackReachable(oldTarget) then
                g_game.attack(oldTarget)
                holdAttackWasAttacking = true
            end
            return
        else
            -- Target is NOT visible anymore
            -- Creature left the screen → KEEP the hold, don't clear
            holdAttackWasAttacking = false
            -- Don't clear, continue to try to re-attack below
        end
    end

    -- If target ID is 0 or nil, hold was cancelled, don't re-attack
    if not helperConfig.holdAttackTargetId or helperConfig.holdAttackTargetId == 0 then
        return
    end

    -- Try to find target by ID only
    local targetCreature = g_map.getCreatureById(helperConfig.holdAttackTargetId)

    if targetCreature and targetCreature:getHealthPercent() > 0 and isHoldAttackReachable(targetCreature) then
        -- Target is visible AND reachable, attack it
        g_game.attack(targetCreature)
        holdAttackWasAttacking = true
    end
end

eventTable.checkHoldAttack.action = checkHoldAttack

-- ============================================================================
-- PAUSE CAVEBOT ON MOB
-- ============================================================================

local pauseCavebotOnMobActive = false

function modules.game_helper.togglePauseCavebotOnMob(widget)
    if not helperConfig then helperConfig = {} end
    helperConfig.pauseCavebotOnMobEnabled = widget and widget:isChecked() or false
    if not helperConfig.pauseCavebotOnMobEnabled and pauseCavebotOnMobActive then
        pauseCavebotOnMobActive = false
        if helperConfig.cavebotHelperEnabled and cavebotWalker and cavebotWalker.resume then
            pcall(cavebotWalker.resume)
        end
    end
end

function modules.game_helper.updatePauseCavebotOnMobs(text)
    if not helperConfig then helperConfig = {} end
    local list = {}
    if text and text ~= "" then
        for mob in string.gmatch(text, "([^,]+)") do
            local trimmed = mob:match("^%s*(.-)%s*$")
            if trimmed and trimmed ~= "" then
                table.insert(list, trimmed:lower())
            end
        end
    end
    helperConfig.pauseCavebotOnMobs = list
end

function checkPauseCavebotOnMob()
    if not helperConfig or not helperConfig.pauseCavebotOnMobEnabled then
        if pauseCavebotOnMobActive then
            pauseCavebotOnMobActive = false
            if helperConfig and helperConfig.cavebotHelperEnabled and cavebotWalker and cavebotWalker.resume then
                pcall(cavebotWalker.resume)
            end
        end
        return
    end

    if not helperConfig.cavebotHelperEnabled then
        return
    end

    local mobs = helperConfig.pauseCavebotOnMobs
    if not mobs or #mobs == 0 then
        return
    end

    local player = g_game.getLocalPlayer()
    if not player then return end

    local maxDist = tonumber(helperConfig.maxTargetDistance) or 7
    local found = false
    local foundName = nil

    local list = CreatureCache.getMonsters()
    for _, entry in ipairs(list) do
        if entry.dx <= maxDist and entry.dy <= maxDist then
            local creature = entry.creature
            if creature and not creature:isDead() then
                local name = creature:getName()
                if name then
                    local lname = name:lower()
                    for _, target in ipairs(mobs) do
                        if lname == target then
                            found = true
                            foundName = name
                            break
                        end
                    end
                end
            end
        end
        if found then break end
    end

    if found and not pauseCavebotOnMobActive then
        pauseCavebotOnMobActive = true
        if cavebotWalker and cavebotWalker.pause then
            pcall(cavebotWalker.pause)
        end
        if modules.game_textmessage and modules.game_textmessage.displayGameMessage then
            pcall(modules.game_textmessage.displayGameMessage,
                string.format("[Cavebot] Paused - %s detected", foundName or "mob"))
        end
    elseif not found and pauseCavebotOnMobActive then
        pauseCavebotOnMobActive = false
        if cavebotWalker and cavebotWalker.resume then
            pcall(cavebotWalker.resume)
        end
        if modules.game_textmessage and modules.game_textmessage.displayGameMessage then
            pcall(modules.game_textmessage.displayGameMessage, "[Cavebot] Resumed")
        end
    end
end

eventTable.checkPauseCavebotOnMob.action = checkPauseCavebotOnMob

-- ============================================================================
-- AUTO FOLLOW MODULE
-- ============================================================================

function modules.game_helper.initAutoFollow()
    if not _G.AutoFollowModule then
        local success, result = pcall(dofile, "/game_helper/auto_follow.lua")
        if success then
            _G.AutoFollowModule = result
            g_logger.info("[AutoFollow] initAutoFollow: created NEW module instance " .. tostring(result))
        else
            print("[AutoFollow] Failed to load module: " .. tostring(result))
        end
    end
end

function modules.game_helper.setAutoFollowTarget(creature)
    modules.game_helper.initAutoFollow()
    if _G.AutoFollowModule then
        _G.AutoFollowModule.setTarget(creature)
        if creature and modules.game_textmessage then
            modules.game_textmessage.displayGameMessage("Auto Follow target set to: " .. creature:getName())
        end
    end
end

function modules.game_helper.clearAutoFollowTarget()
    if _G.AutoFollowModule then
        _G.AutoFollowModule.clearTarget()
        if modules.game_textmessage then
            modules.game_textmessage.displayGameMessage(htr("Auto Follow target cleared"))
        end
    end
end

function modules.game_helper.toggleAutoFollow(checked)
    modules.game_helper.initAutoFollow()
    if _G.AutoFollowModule then
        -- Skip if this is a programmatic UI update (prevents cascade messages)
        if _G.AutoFollowModule.isUpdatingUI and _G.AutoFollowModule.isUpdatingUI() then
            return
        end
        _G.AutoFollowModule.toggle(checked)
        -- Check if toggle was actually accepted (may be blocked by expedition/PVP)
        local actuallyEnabled = _G.AutoFollowModule.isEnabled()
        if checked and not actuallyEnabled then
            -- Toggle was blocked, uncheck the UI
            _G.AutoFollowModule.updateUI()
            return
        end
        if _G.AutoFollowModule.updateUI then
            _G.AutoFollowModule.updateUI()
        end
        if actuallyEnabled then
            local targetName = _G.AutoFollowModule.getTargetName()
            if targetName and modules.game_textmessage then
                modules.game_textmessage.displayGameMessage("Auto Follow enabled for: " .. targetName)
            elseif modules.game_textmessage then
                modules.game_textmessage.displayGameMessage(htr(
                "Auto Follow enabled - use Ctrl + Left Click to set target"))
            end
        else
            if modules.game_textmessage then
                modules.game_textmessage.displayGameMessage(htr("Auto Follow disabled"))
            end
        end
    end
end

function modules.game_helper.toggleAutoFollowHotkey()
    modules.game_helper.initAutoFollow()
    if not _G.AutoFollowModule or not _G.AutoFollowModule.isEnabled then
        return
    end

    local nextState = not _G.AutoFollowModule.isEnabled()
    modules.game_helper.toggleAutoFollow(nextState)
end

-- Positioning settings (driven by the Distance/Style comboboxes). The module
-- persists them to g_settings, so they take effect immediately and survive relog.
function modules.game_helper.setAutoFollowDistance(distance)
    modules.game_helper.initAutoFollow()
    if _G.AutoFollowModule and _G.AutoFollowModule.setDistance then
        _G.AutoFollowModule.setDistance(distance)
    end
end

function modules.game_helper.setAutoFollowStyle(style)
    modules.game_helper.initAutoFollow()
    if _G.AutoFollowModule and _G.AutoFollowModule.setStyle then
        _G.AutoFollowModule.setStyle(style)
    end
end

function modules.game_helper.getAutoFollowDistance()
    modules.game_helper.initAutoFollow()
    if _G.AutoFollowModule and _G.AutoFollowModule.getDistance then
        return _G.AutoFollowModule.getDistance()
    end
    return 1
end

function modules.game_helper.getAutoFollowStyle()
    modules.game_helper.initAutoFollow()
    if _G.AutoFollowModule and _G.AutoFollowModule.getStyle then
        return _G.AutoFollowModule.getStyle()
    end
    return "Normal"
end

function modules.game_helper.getToolsPanel()
    return toolsPanel
end

function modules.game_helper.terminateAutoFollow()
    if _G.AutoFollowModule then
        _G.AutoFollowModule.terminate()
        _G.AutoFollowModule = nil
    end
end

