function modules.game_helper.onInvitePartyToggle(filterType, checked)
    if not helperConfig.partyManagement then
        helperConfig.partyManagement = {
            inviteParty = { all = false, vip = false, guild = false, friend = false, friendList = "" },
            autoAcceptParty = { all = false, vip = false, guild = false, friend = false, friendList = "" }
        }
    end
    if not helperConfig.partyManagement.inviteParty then
        helperConfig.partyManagement.inviteParty = { all = false, vip = false, guild = false, friend = false, friendList =
        "" }
    end
    helperConfig.partyManagement.inviteParty[filterType] = checked
    saveSettings()
end

function modules.game_helper.onAutoAcceptPartyToggle(filterType, checked)
    if not helperConfig.partyManagement then
        helperConfig.partyManagement = {
            inviteParty = { all = false, vip = false, guild = false, friend = false, friendList = "" },
            autoAcceptParty = { all = false, vip = false, guild = false, friend = false, friendList = "" }
        }
    end
    if not helperConfig.partyManagement.autoAcceptParty then
        helperConfig.partyManagement.autoAcceptParty = { all = false, vip = false, guild = false, friend = false, friendList =
        "" }
    end
    helperConfig.partyManagement.autoAcceptParty[filterType] = checked
    saveSettings()
end

modules.game_helper.partyFriendListUiState = modules.game_helper.partyFriendListUiState or {
    isUpdating = false,
    pendingSaveEvents = {}
}

function modules.game_helper.normalizePartyFriendListInput(friendListStr)
    if not friendListStr or friendListStr == "" then
        return ""
    end

    local normalized = tostring(friendListStr)
    normalized = normalized:gsub("\r\n", "\n")
    normalized = normalized:gsub("[;\n]+", ",")

    local names = {}
    for name in string.gmatch(normalized, "[^,]+") do
        local trimmed = name:match("^%s*(.-)%s*$")
        if trimmed and trimmed ~= "" then
            names[#names + 1] = trimmed
        end
    end

    return table.concat(names, ", ")
end

function modules.game_helper.formatPartyFriendListForDisplay(friendListStr)
    if not friendListStr or friendListStr == "" then
        return ""
    end

    local names = {}
    for name in string.gmatch(friendListStr, "[^,]+") do
        local trimmed = name:match("^%s*(.-)%s*$")
        if trimmed and trimmed ~= "" then
            names[#names + 1] = trimmed
        end
    end

    return table.concat(names, "\n")
end

function modules.game_helper.onPartyManagementFriendListChange(listType, friendText)
    local uiState = modules.game_helper.partyFriendListUiState
    if uiState.isUpdating then
        return
    end

    if listType ~= "invite" and listType ~= "accept" then
        return
    end

    if not helperConfig.partyManagement then
        helperConfig.partyManagement = {
            inviteParty = { all = false, vip = false, guild = false, friend = false, friendList = "" },
            autoAcceptParty = { all = false, vip = false, guild = false, friend = false, friendList = "" }
        }
    end

    local configKey = listType == "invite" and "inviteParty" or "autoAcceptParty"
    if not helperConfig.partyManagement[configKey] then
        helperConfig.partyManagement[configKey] = { all = false, vip = false, guild = false, friend = false, friendList =
        "" }
    end

    local normalizedList = modules.game_helper.normalizePartyFriendListInput(friendText)
    local currentList = helperConfig.partyManagement[configKey].friendList or ""
    if currentList == normalizedList then
        return
    end

    helperConfig.partyManagement[configKey].friendList = normalizedList

    if uiState.pendingSaveEvents[listType] then
        removeEvent(uiState.pendingSaveEvents[listType])
        uiState.pendingSaveEvents[listType] = nil
    end

    uiState.pendingSaveEvents[listType] = scheduleEvent(function()
        uiState.pendingSaveEvents[listType] = nil
        saveSettings()
    end, 250)
end

function modules.game_helper.refreshPartyManagementFriendLists()
    if not helper or not helper.contentPanel then
        return
    end

    local partyManagementContent = helper.contentPanel:recursiveGetChildById("partyManagementContent")
    if not partyManagementContent then
        return
    end

    local inviteListWidget = partyManagementContent:recursiveGetChildById("invitePartyFriendsList")
    local acceptListWidget = partyManagementContent:recursiveGetChildById("autoAcceptPartyFriendsList")

    local inviteText = ""
    local acceptText = ""
    if helperConfig and helperConfig.partyManagement then
        if helperConfig.partyManagement.inviteParty then
            inviteText = modules.game_helper.formatPartyFriendListForDisplay(helperConfig.partyManagement.inviteParty
            .friendList or "")
        end
        if helperConfig.partyManagement.autoAcceptParty then
            acceptText = modules.game_helper.formatPartyFriendListForDisplay(helperConfig.partyManagement
            .autoAcceptParty.friendList or "")
        end
    end

    local uiState = modules.game_helper.partyFriendListUiState
    uiState.isUpdating = true
    if inviteListWidget and inviteListWidget:getText() ~= inviteText then
        inviteListWidget:setText(inviteText)
    end
    if acceptListWidget and acceptListWidget:getText() ~= acceptText then
        acceptListWidget:setText(acceptText)
    end
    uiState.isUpdating = false
end

-- Open friend list popup for party management
function modules.game_helper.openFriendListPopup(listType)
    if not helperConfig.partyManagement then
        helperConfig.partyManagement = {
            inviteParty = { all = false, vip = false, guild = false, friend = false, friendList = "" },
            autoAcceptParty = { all = false, vip = false, guild = false, friend = false, friendList = "" }
        }
    end

    local configKey = listType == 'invite' and 'inviteParty' or 'autoAcceptParty'
    local titleText = listType == 'invite' and 'Invite Party - Friends' or 'Auto Accept Party - Friends'

    if not helperConfig.partyManagement[configKey] then
        helperConfig.partyManagement[configKey] = { all = false, vip = false, guild = false, friend = false, friendList =
        "" }
    end

    local currentList = helperConfig.partyManagement[configKey].friendList or ""

    local inputBox = HelperUIInputBox.create(titleText, function(friendText)
        helperConfig.partyManagement[configKey].friendList = friendText
        saveSettings()
        modules.game_helper.refreshPartyManagementFriendLists()
    end, function()
        -- Cancel callback - do nothing
    end)

    inputBox:addLabel('Enter friend names separated by comma:')
    inputBox:addLineEdit(nil, currentList, 500)
    inputBox:display('Save', 'Cancel')
end

-- Parse friend list string into table of names
function modules.game_helper.parseFriendList(friendListStr)
    local friends = {}
    if not friendListStr or friendListStr == "" then
        return friends
    end

    for name in string.gmatch(friendListStr, "[^,]+") do
        local trimmed = name:match("^%s*(.-)%s*$")
        if trimmed and trimmed ~= "" then
            table.insert(friends, trimmed:lower())
        end
    end

    return friends
end

-- Check if a creature matches the party invite/accept filters
function modules.game_helper.matchesPartyFilter(creature, filterConfig)
    if not creature or not filterConfig then return false end
    if not creature:isPlayer() then return false end

    local player = g_game.getLocalPlayer()
    if not player then return false end

    local creatureName = creature:getName()

    -- All filter - accept anyone
    if filterConfig.all then
        return true
    end

    -- VIP filter
    if filterConfig.vip then
        if player:hasVip(creatureName) then
            return true
        end
    end

    -- Guild filter
    if filterConfig.guild then
        local localEmblem = player:getEmblem()
        local memberEmblem = creature:getEmblem()
        if memberEmblem ~= EmblemNone and memberEmblem == localEmblem then
            return true
        end
    end

    -- Friend list filter (only if checkbox is enabled)
    if filterConfig.friend and filterConfig.friendList and filterConfig.friendList ~= "" then
        local friends = modules.game_helper.parseFriendList(filterConfig.friendList)
        local lowerCreatureName = creatureName:lower()
        for _, friendName in ipairs(friends) do
            if lowerCreatureName == friendName then
                return true
            end
        end
    end

    return false
end

-- Auto invite nearby players to party
function modules.game_helper.processPartyInvites()
    if not g_game.isOnline() then return end

    local player = g_game.getLocalPlayer()
    if not player then return end

    if not helperConfig.partyManagement then return end
    local inviteConfig = helperConfig.partyManagement.inviteParty
    if not inviteConfig then return end

    -- Check if any filter is enabled
    if not inviteConfig.all and not inviteConfig.vip and not inviteConfig.guild and not inviteConfig.friend then
        return
    end

    -- Check if player can invite (not in party or is party leader)
    local localShield = player:getShield()
    local canInvite = (localShield == ShieldNone or
        localShield == ShieldWhiteYellow or
        localShield == ShieldYellow or
        localShield == ShieldYellowSharedExp or
        localShield == ShieldYellowNoSharedExpBlink or
        localShield == ShieldYellowNoSharedExp)

    if not canInvite then return end

    local playerPos = player:getPosition()
    -- OPTIMIZATION: Use CreatureCache instead of getSpectators
    local cachedPlayers = CreatureCache.getPlayers()

    for _, entry in ipairs(cachedPlayers) do
        local creature = entry.creature
        if creature ~= player then
            local creatureShield = creature:getShield()
            -- Only invite if they're not already in a party or invited
            if creatureShield == ShieldNone then
                if modules.game_helper.matchesPartyFilter(creature, inviteConfig) then
                    g_game.partyInvite(creature:getId())
                end
            end
        end
    end
end

-- Auto accept party invitations from nearby players
function modules.game_helper.processPartyAccepts()
    if not g_game.isOnline() then return end

    local player = g_game.getLocalPlayer()
    if not player then return end

    if not helperConfig.partyManagement then return end
    local acceptConfig = helperConfig.partyManagement.autoAcceptParty
    if not acceptConfig then return end

    -- Check if any filter is enabled
    if not acceptConfig.all and not acceptConfig.vip and not acceptConfig.guild and not acceptConfig.friend then
        return
    end

    -- Check if we're not already in a party
    local localShield = player:getShield()
    -- If we're already in a party (have any party shield), don't try to join another
    if localShield ~= ShieldNone and localShield ~= ShieldWhiteBlue then
        return
    end

    local playerPos = player:getPosition()
    -- OPTIMIZATION: Use CreatureCache instead of getSpectators
    local cachedPlayers = CreatureCache.getPlayers()

    for _, entry in ipairs(cachedPlayers) do
        local creature = entry.creature
        if creature ~= player then
            local creatureShield = creature:getShield()
            -- Check if this player invited someone (WhiteYellow = they sent an invite)
            -- We try to join - server will accept if we were invited, reject otherwise
            if creatureShield == ShieldWhiteYellow then
                if modules.game_helper.matchesPartyFilter(creature, acceptConfig) then
                    g_game.partyJoin(creature:getId())
                    return -- Only try to join one party per cycle
                end
            end
        end
    end
end

-- Called from helper cycle event
function modules.game_helper.partyManagementCycle()
    modules.game_helper.processPartyInvites()
    modules.game_helper.processPartyAccepts()
end

-- Global wrapper for eventTable (to avoid local variable limit)
function checkPartyManagement()
    modules.game_helper.partyManagementCycle()
end

eventTable.checkPartyManagement.action = checkPartyManagement

function autoEatFood()
    if not g_game.isOnline() or not player or not helperConfig.autoEatFood then
        return
    end

    local cooldown = getSpellCooldown(foodConfig.id)
    if cooldown >= g_clock.millis() then
        return true
    end

    for _, id in pairs(foodIds) do
        if getItemCountAnywhere(id) > 0 then
            local realItem = findItemAnywhere(id)
            if type(realItem) == "userdata" then
                g_game.use(realItem)
            else
                g_game.useInventoryItem(id)
            end

            spellsCooldown[foodConfig.id] = g_clock.millis() + foodConfig.exhaustion
            break
        end
    end
end

function autoPortableTrader()
    if not g_game.isOnline() or not player or not helperConfig.autoPortableTrader then
        return
    end

    -- VIP/premium only. The Loot Seller is a VIP feature server-side; the client's
    -- isPremium() reflects the server's basic-data byte (sent as isPremium||isVip on
    -- KoliseuOT), so it is true for both premium and VIP. Guard the call for old
    -- builds that don't bind isPremium (treat as "not VIP" -> never fire).
    if not player.isPremium or not player:isPremium() then
        return
    end

    -- Only sell when free capacity drops below the configured "cap <=" threshold.
    local threshold = tonumber(helperConfig.portableTraderCapThreshold) or 1000
    local freeCap = player:getFreeCapacity()
    if not freeCap or freeCap >= threshold then
        return
    end

    -- Loot Seller (id 60257) lives locked inside the Store Inbox (server slot 11),
    -- so the use-by-id reaches it even with every container closed - no need to find
    -- or open anything. 20s anti-flood cooldown between uses (server also exhausts).
    local lootSellerId = 60257
    local cooldown = getSpellCooldown(lootSellerId)
    if cooldown > g_clock.millis() then
        return
    end

    g_game.useInventoryItem(lootSellerId)
    spellsCooldown[lootSellerId] = g_clock.millis() + 20000
end

function autoIncreaseForgeLimit()
    if not g_game.isOnline() or not player or not helperConfig.autoIncreaseForgeLimit then
        return
    end

    local ACTION_INCREASE_DUST_LIMIT = 4

    -- Add cooldown to avoid spamming
    local forgeLimitCooldownId = 99999
    local cooldown = getSpellCooldown(forgeLimitCooldownId)
    if cooldown > g_clock.millis() then
        return
    end

    -- Estado vivo da forge: a global ForgeSystem do modulo game_forge. O server envia os dados
    -- (0x86 sendForgingData: dustCost/maxPlayerDust/maxDust) automaticamente no login
    -- (sendAddCreature) e re-envia apos cada increase -- para TODOS, sem gate de VIP.
    -- game_forge roda SANDBOXED (forge.otmod): ForgeSystem NAO esta no _G global, vive no
    -- ambiente do modulo -> acessivel via modules.game_forge (modules == package.loaded, e o
    -- sandbox registra package.loaded[nome]=env). Ler _G.ForgeSystem dava nil e a funcao
    -- nunca agia.
    local forgeModule = modules and modules.game_forge
    local Forge = forgeModule and forgeModule.ForgeSystem
    if not Forge then
        return
    end

    -- Exige que os dados reais tenham chegado do server (0x86 popula maxDust/maxPlayerDust).
    -- Sem isso ForgeSystem esta nos defaults e nao devemos agir com valores espurios.
    local maxDust = tonumber(Forge.maxDust) or 0
    local dustLimit = tonumber(Forge.maxPlayerDust) or 0
    if maxDust <= 0 or dustLimit <= 0 then
        return
    end

    -- Ja no teto do server: nada a subir.
    if dustLimit >= maxDust then
        return
    end

    -- Custo do proximo nivel = (100 - increaseBase) + (limite - 100). increaseBase (dustCost)
    -- vem do server (0x86); padrao 75 se ausente. Mesma formula da UI (Forge.lua).
    local increaseBase = tonumber(Forge.dustCost)
    if not increaseBase or increaseBase <= 0 then
        increaseBase = 75
    end
    local requiredDust = (100 - increaseBase) + (dustLimit - 100)

    -- Dust disponivel (resource 70 = ResourceForgeDust); floor por seguranca (pode vir float).
    local dustBalance = math.floor(player:getResourceValue(70) or 0)
    if dustBalance < requiredDust then
        return
    end

    -- Enviar a acao real. sendForgeConverter monta 0xBF (ForgeClient.Enter) + action=4,
    -- exatamente como o botao "Increase Dust Limit" da UI (conversion.otui). sendForgeAction
    -- NAO existe (nem C++ nem Lua): astra_compat.lua instalava um stub no-op vazio, entao a
    -- chamada antiga nao enviava nada.
    g_game.sendForgeConverter(ACTION_INCREASE_DUST_LIMIT)

    -- O server re-envia 0x86 (sendForgingData) apos o increase, entao ForgeSystem.maxPlayerDust
    -- atualiza sozinho para a proxima iteracao -- sem cache especulativo nem re-request.

    -- Notificar o jogador
    modules.game_textmessage.displayGameMessage("Forge dust limit increased: " .. dustLimit .. " -> " .. (dustLimit + 1))

    -- Cooldown de 5 segundos
    spellsCooldown[forgeLimitCooldownId] = g_clock.millis() + 5000
end

-- Auto Convert Dust to Slivers: enquanto ligado, converte dust em slivers assim que houver
-- dust suficiente para 1 conversao (ForgeAction.DustToSlivers = 2, o botao "Convert Dust" da
-- conversion.otui). NAO espera o dust limit maxar -- se marcado, escoa dust obrigatoriamente.
-- E mutuamente exclusivo com o auto-increase (radio nos toggles), entao os dois nunca competem.
function autoConvertDustToSlivers()
    if not g_game.isOnline() or not player or not helperConfig.autoConvertDustToSlivers then
        return
    end

    -- Cooldown proprio (id != 99999 do auto-increase). 5s entre conversoes: enquanto houver
    -- dust suficiente, converte 1x a cada tick de cooldown.
    local convertCooldownId = 99998
    if getSpellCooldown(convertCooldownId) > g_clock.millis() then
        return
    end

    -- Estado vivo da forge (mesma fonte do auto-increase): a global ForgeSystem do modulo
    -- game_forge (sandboxed -> via modules.game_forge; ver autoIncreaseForgeLimit). Populada
    -- pelo 0x86 (sendForgingData) que o server envia no login para TODOS (sem gate de VIP).
    local forgeModule = modules and modules.game_forge
    local Forge = forgeModule and forgeModule.ForgeSystem
    if not Forge then
        return
    end

    -- Custo em dust de UMA conversao = slivers_produzidos * dust_por_sliver (mesma formula do
    -- botao "Convert Dust" da UI: Forge.updateConversion -> slivers * baseMultipier). Se ainda
    -- 0, os dados da forge (0x86) nao chegaram ao client -> nada a fazer.
    local slivers = tonumber(Forge.slivers) or 0
    local convertCost = slivers * (tonumber(Forge.baseMultipier) or 0)
    if convertCost <= 0 then
        return
    end

    -- Enquanto ligado, converte assim que houver dust para pelo menos 1 conversao -- SEM
    -- esperar o limite maxar. Se marcado, escoa dust em slivers obrigatoriamente.
    local dustBalance = math.floor(player:getResourceValue(70) or 0)
    if dustBalance < convertCost then
        return
    end

    -- Acao real: 0xBF ForgeClient.Enter + action=2 (DustToSlivers), identica ao botao
    -- "Convert Dust". O server re-envia 0x86 depois, entao saldos/limites atualizam sozinhos.
    g_game.sendForgeConverter(2)

    modules.game_textmessage.displayGameMessage("Forge dust converted to slivers (+" .. slivers .. ")")

    -- Cooldown de 5 segundos entre conversoes.
    spellsCooldown[convertCooldownId] = g_clock.millis() + 5000
end

