function updateMagicShooterPriority(index, priority)
    local profile = getShooterProfile()
    if not profile then
        return
    end
    local slot = (tonumber(index) or 0) + 1
    if not profile.spells[slot] then
        profile.spells[slot] = ensureShooterSpellRule({}, slot)
    end
    profile.spells[slot].priority = tonumber(priority)
end

-- Funcao auxiliar para formatar o valor de creatures para exibicao
local function formatCreaturesValue(creatures)
    if creatures == 0 then
        -- Zero significa nenhum monstro necessario
        return "0"
    elseif creatures < 0 then
        -- Valor negativo significa exato
        return tostring(math.abs(creatures))
    else
        -- Valor positivo significa ou mais
        return tostring(creatures) .. "+"
    end
end

SHOOTER_ROW_DOUBLE_CLICK_MS = 500

function parseShooterCreaturesOptionText(optionText)
    local text = tostring(optionText or "1+")
    if text == "0" then
        return 0
    end
    if text == "1" then
        return -1
    end
    local parsed = tonumber(text:match("%d+")) or 1
    if parsed < 0 then
        parsed = 0
    end
    return parsed
end

function isShooterSpellConfigured(rule)
    if type(rule) ~= "table" then
        return false
    end
    if (tonumber(rule.id) or 0) > 0 then
        return true
    end
    if (tonumber(rule.id) or 0) == -1 and tostring(rule.customText or "") ~= "" then
        return true
    end
    return false
end

function isShooterRuneConfigured(rule)
    if type(rule) ~= "table" then
        return false
    end
    return (tonumber(rule.id) or 0) > 0
end

function ensureShooterSpellRule(rule, orderPriority)
    if type(rule) ~= "table" then
        rule = {}
    end

    rule.id = tonumber(rule.id) or 0
    rule.percent = tonumber(rule.percent) or 100
    rule.creatures = tonumber(rule.creatures)
    if rule.creatures == nil then
        rule.creatures = 1
    end
    rule.priority = tonumber(rule.priority) or tonumber(orderPriority) or 1
    rule.forceCast = rule.forceCast == true
    rule.selfCast = rule.selfCast == true
    rule.enabled = rule.enabled ~= false
    rule.customText = tostring(rule.customText or "")
    rule.cooldown = tonumber(rule.cooldown) or 2000
    if rule.cooldown < 100 then
        rule.cooldown = 100
    end
    rule.minHarmony = tonumber(rule.minHarmony) or 0
    if rule.minHarmony < 0 then
        rule.minHarmony = 0
    end
    if rule.minHarmony > 5 then
        rule.minHarmony = 5
    end
    rule.needTarget = rule.needTarget == true
    return rule
end

function ensureShooterRuneRule(rule, orderPriority)
    if type(rule) ~= "table" then
        rule = {}
    end

    rule.id = tonumber(rule.id) or 0
    rule.creatures = tonumber(rule.creatures)
    if rule.creatures == nil then
        rule.creatures = 1
    end
    rule.priority = tonumber(rule.priority) or tonumber(orderPriority) or 1
    rule.forceCast = rule.forceCast == true
    rule.enabled = rule.enabled ~= false
    rule.needTarget = rule.needTarget == true
    rule.prioritizeOverPotion = rule.prioritizeOverPotion ~= false
    return rule
end

function ensureShooterProfileConfig(profile, compact)
    if type(profile) ~= "table" then
        return nil
    end

    if type(profile.spells) ~= "table" then
        profile.spells = {}
    end
    if type(profile.runes) ~= "table" then
        profile.runes = {}
    end

    local normalizedSpells = {}
    for i = 1, #profile.spells do
        local spellRule = ensureShooterSpellRule(profile.spells[i], i)
        if not compact or isShooterSpellConfigured(spellRule) then
            normalizedSpells[#normalizedSpells + 1] = spellRule
        end
    end

    local normalizedRunes = {}
    for i = 1, #profile.runes do
        local runeRule = ensureShooterRuneRule(profile.runes[i], #normalizedSpells + i)
        if not compact or isShooterRuneConfigured(runeRule) then
            normalizedRunes[#normalizedRunes + 1] = runeRule
        end
    end

    profile.spells = normalizedSpells
    profile.runes = normalizedRunes
    return profile
end

function getShooterRulesListWidget()
    if not shooterPanel or shooterPanel:isDestroyed() then
        return nil
    end
    local rulesPanel = shooterPanel:recursiveGetChildById("shooterRulesPanel")
    if not rulesPanel then
        return nil
    end
    return rulesPanel:recursiveGetChildById("shooterRulesList")
end

function getShooterCurrentVocationId()
    local localPlayer = g_game.getLocalPlayer()
    if not localPlayer then
        return 0
    end
    return translateVocation(localPlayer:getVocation())
end

function isShooterSpellMonk(spellId)
    local parsedId = tonumber(spellId) or 0
    if parsedId <= 0 then
        return false
    end
    local spellData = Spells.getSpellByClientId(parsedId)
    if not spellData or type(spellData.vocations) ~= "table" then
        return false
    end
    for _, vocId in ipairs(spellData.vocations) do
        -- 9 = Monk, 10 = Exalted Monk (gamelib/const.lua Vocation table)
        if vocId == 9 or vocId == 10 then
            return true
        end
    end
    return false
end

function isShooterHarmonyVisible(spellId)
    return isShooterSpellMonk(spellId)
end

function getShooterRuneDataById(runeId)
    local parsedId = tonumber(runeId) or 0
    if parsedId <= 0 then
        return nil
    end
    if Spells.getRuneSpellByItem then
        local runeData = Spells.getRuneSpellByItem(parsedId)
        if runeData then
            return runeData
        end
    end
    if Spells.getSpellByClientId then
        return Spells.getSpellByClientId(parsedId)
    end
    return nil
end

function buildShooterUnifiedRuleRefs(profile)
    local refs = {}
    if type(profile) ~= "table" then
        return refs
    end

    ensureShooterProfileConfig(profile, true)

    for i = 1, #profile.spells do
        local spellRule = ensureShooterSpellRule(profile.spells[i], i)
        if isShooterSpellConfigured(spellRule) then
            refs[#refs + 1] = {
                kind = "spell",
                sourceIndex = i,
                priority = tonumber(spellRule.priority) or i,
                config = spellRule
            }
        end
    end

    for i = 1, #profile.runes do
        local runeRule = ensureShooterRuneRule(profile.runes[i], #profile.spells + i)
        if isShooterRuneConfigured(runeRule) then
            refs[#refs + 1] = {
                kind = "rune",
                sourceIndex = i,
                priority = tonumber(runeRule.priority) or (#profile.spells + i),
                config = runeRule
            }
        end
    end

    table.sort(refs, function(a, b)
        local pa = tonumber(a.priority) or 99999
        local pb = tonumber(b.priority) or 99999
        if pa ~= pb then
            return pa < pb
        end
        if a.kind ~= b.kind then
            return a.kind < b.kind
        end
        return (tonumber(a.sourceIndex) or 0) < (tonumber(b.sourceIndex) or 0)
    end)

    return refs
end

function applyShooterRuleRefOrder(profile, orderedRefs)
    if type(profile) ~= "table" then
        return
    end
    if type(orderedRefs) ~= "table" then
        return
    end

    for i = 1, #orderedRefs do
        local ref = orderedRefs[i]
        if ref and ref.kind == "spell" then
            local cfg = profile.spells and profile.spells[ref.sourceIndex]
            if cfg then
                cfg.priority = i
            end
        elseif ref and ref.kind == "rune" then
            local cfg = profile.runes and profile.runes[ref.sourceIndex]
            if cfg then
                cfg.priority = i
            end
        end
    end
end

function getShooterRuleNameAndType(ruleRef)
    if type(ruleRef) ~= "table" or type(ruleRef.config) ~= "table" then
        return "Unknown", "Unknown"
    end

    if ruleRef.kind == "spell" then
        local cfg = ruleRef.config
        if (tonumber(cfg.id) or 0) == -1 and tostring(cfg.customText or "") ~= "" then
            return tostring(cfg.customText), "Text"
        end
        local spellData = Spells.getSpellByClientId(tonumber(cfg.id) or 0)
        if spellData then
            local spellName = tostring(spellData.name or "")
            if spellName == "" then
                spellName = tostring(spellData.words or "")
            end
            if spellName == "" then
                spellName = "Unknown Spell"
            end
            return spellName, "Spell"
        end
        return string.format("Spell %d", tonumber(cfg.id) or 0), "Spell"
    end

    local cfg = ruleRef.config
    local runeId = tonumber(cfg.id) or 0
    local runeData = getShooterRuneDataById(runeId)
    if runeData and tostring(runeData.name or "") ~= "" then
        return tostring(runeData.name), "Rune"
    end
    return resolveHelperItemNameById(runeId), "Rune"
end

function buildShooterRuleSummaryText(ruleRef)
    if type(ruleRef) ~= "table" or type(ruleRef.config) ~= "table" then
        return ""
    end

    local cfg = ruleRef.config
    local parts = { formatCreaturesValue(tonumber(cfg.creatures) or 1) }
    if ruleRef.kind == "spell" then
        if cfg.needTarget == true then
            parts[#parts + 1] = "target"
        end
        if isShooterHarmonyVisible(cfg.id) and (tonumber(cfg.minHarmony) or 0) > 0 then
            parts[#parts + 1] = "harmony " .. tostring(tonumber(cfg.minHarmony) or 0)
        end
    elseif ruleRef.kind == "rune" then
        if cfg.needTarget == true then
            parts[#parts + 1] = "target"
        end
        if cfg.prioritizeOverPotion == false then
            parts[#parts + 1] = "no pot prio"
        end
    end
    return table.concat(parts, " | ")
end

function setShooterRuleItemVisual(row, ruleRef)
    if not row or row:isDestroyed() then
        return
    end
    local itemButton = row:recursiveGetChildById("itemButton")
    if not itemButton then
        return
    end

    local itemWidget = itemButton:getChildById("shooterRuleItem")
    if itemWidget then
        itemWidget:destroy()
        itemWidget = nil
    end

    if type(ruleRef) ~= "table" or type(ruleRef.config) ~= "table" then
        itemButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
        itemButton:setImageClip("0 0 34 34")
        itemButton:setTooltip("")
        return
    end

    local cfg = ruleRef.config
    if ruleRef.kind == "spell" then
        if (tonumber(cfg.id) or 0) == -1 and tostring(cfg.customText or "") ~= "" then
            itemButton:setImageSource("customspells.png")
            itemButton:setImageClip("0 0 32 32")
            itemButton:setTooltip("Text: " .. tostring(cfg.customText))
            return
        end

        local spellData, spellDataProfile = Spells.getSpellByClientId(tonumber(cfg.id) or 0)
        local spellProfile = spellDataProfile or "Default"
        if spellData and spellData.icon and SpellIcons and SpellIcons[spellData.icon] and SpelllistSettings and SpelllistSettings[spellProfile] then
            local spellIconId = SpellIcons[spellData.icon][1]
            local source = SpelllistSettings[spellProfile].iconsFolder
            local clip = Spells.getImageClip and Spells.getImageClipNormal(spellIconId, spellProfile) or nil
            if source and clip then
                itemButton:setImageSource(source)
                itemButton:setImageClip(clip)
                local spellName = tostring(spellData.name or spellData.words or "Spell")
                itemButton:setTooltip(spellName)
                return
            end
        end

        itemButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
        itemButton:setImageClip("0 0 34 34")
        itemButton:setTooltip("")
        return
    end

    local runeId = tonumber(cfg.id) or 0
    if runeId > 0 then
        itemButton:setImageSource("/images/ui/item")
        itemWidget = g_ui.createWidget("RuneItem", itemButton)
        if itemWidget then
            itemWidget:setId("shooterRuleItem")
            itemWidget:setItemId(runeId)
        end
        itemButton:setTooltip(resolveHelperItemNameById(runeId))
    else
        itemButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
        itemButton:setImageClip("0 0 34 34")
        itemButton:setTooltip("")
    end
end

function getShooterRuleCooldownSpellId(ruleRef)
    if type(ruleRef) ~= "table" or type(ruleRef.config) ~= "table" then
        return 0
    end

    local cfg = ruleRef.config
    if ruleRef.kind == "spell" then
        local spellId = tonumber(cfg.id) or 0
        if spellId > 0 then
            return spellId
        end
        return 0
    end

    local runeId = tonumber(cfg.id) or 0
    if runeId > 0 then
        return runeId
    end
    return 0
end

function ensureShooterRuleCooldownOverlay(row)
    if not row or row:isDestroyed() then
        return nil
    end

    local itemButton = row:recursiveGetChildById("itemButton")
    if not itemButton then
        return nil
    end

    local overlay = itemButton:getChildById("shooterRuleCooldownOverlay")
    if not overlay then
        overlay = g_ui.createWidget("SpellProgressRect", itemButton)
        if not overlay then
            overlay = g_ui.createWidget("UIProgressRect", itemButton)
        end
        if not overlay then
            return nil
        end
        overlay:setId("shooterRuleCooldownOverlay")
        overlay:fill("parent")
        overlay:setText("")
        overlay:setPhantom(true)
        overlay:setFocusable(false)
    end

    return overlay
end

function hideShooterRuleCooldownOverlay(row)
    if not row or row:isDestroyed() then
        return
    end

    local itemButton = row:recursiveGetChildById("itemButton")
    if not itemButton then
        return
    end

    local overlay = itemButton:getChildById("shooterRuleCooldownOverlay")
    if overlay then
        overlay:setPercent(100)
        overlay:setText("")
        overlay:hide()
    end
end

function updateShooterRuleCooldownOverlay(row, ruleRef, nowMs)
    if not row or row:isDestroyed() then
        return
    end

    local timing = nil
    if type(ruleRef) == "table" and ruleRef.kind == "rune" then
        timing = getItemCooldownTiming(nowMs)
    end

    if not timing then
        local spellId = getShooterRuleCooldownSpellId(ruleRef)
        if spellId > 0 then
            timing = getRuleSpellCooldownTiming(spellId, nowMs)
        end
    end

    if not timing then
        hideShooterRuleCooldownOverlay(row)
        return
    end

    local overlay = ensureShooterRuleCooldownOverlay(row)
    if not overlay then
        return
    end

    overlay:setPercent(timing.percent or 0)
    overlay:setText("")
    overlay:show()
end

function refreshAllShooterRuleCooldownOverlays()
    local rulesList = getShooterRulesListWidget()
    if not rulesList then
        return
    end

    local profile = getShooterProfile()
    if not profile then
        return
    end

    ensureShooterProfileConfig(profile, true)
    local refs = buildShooterUnifiedRuleRefs(profile)
    local now = g_clock.millis()
    for i = 1, #refs do
        local row = rulesList:recursiveGetChildById("shooterRuleRow" .. tostring(i))
        if row then
            updateShooterRuleCooldownOverlay(row, refs[i], now)
        end
    end
end

function clearShooterRuleSelection()
    if not helperEvents then
        return
    end
    local previous = helperEvents.selectedShooterRuleRow
    if previous and not previous:isDestroyed() then
        previous._isSelected = false
        previous:setBackgroundColor(previous._baseBackgroundColor or "#0a0a0a")
    end
    helperEvents.selectedShooterRuleRow = nil
end

function selectShooterRuleRow(row)
    if not row or row:isDestroyed() then
        return
    end

    if helperEvents then
        local previous = helperEvents.selectedShooterRuleRow
        if previous and not previous:isDestroyed() and previous ~= row then
            previous._isSelected = false
            previous:setBackgroundColor(previous._baseBackgroundColor or "#0a0a0a")
        end
        helperEvents.selectedShooterRuleRow = row
    end

    row._isSelected = true
    row:setBackgroundColor("#ffffff18")
end

function refreshShooterRuleRowColors()
    local rulesList = getShooterRulesListWidget()
    if not rulesList then
        return
    end

    local rowOrder = 0
    local children = rulesList:getChildren() or {}
    for _, child in ipairs(children) do
        local childId = child and child:getId() or ""
        if type(childId) == "string" and childId:find("shooterRuleRow", 1, true) then
            rowOrder = rowOrder + 1
            applyRuleRowBaseColor(child, rowOrder)
        end
    end

    if helperEvents then
        local selected = helperEvents.selectedShooterRuleRow
        if selected and not selected:isDestroyed() and selected:getParent() == rulesList then
            selected._isSelected = true
            selected:setBackgroundColor("#ffffff18")
        else
            helperEvents.selectedShooterRuleRow = nil
        end
    end
end

local function formatRemainingMs(untilMs, nowMs)
    local remain = (tonumber(untilMs) or 0) - nowMs
    if remain <= 0 then
        return "0ms"
    end
    if remain >= 1000 then
        return string.format("%.1fs", remain / 1000)
    end
    return tostring(remain) .. "ms"
end

function buildShooterRuleDiagnostics(ruleRef, zeroIndex)
    if type(ruleRef) ~= "table" then
        return "No rule ref"
    end

    local lines = {}
    local function add(fmt, ...)
        lines[#lines + 1] = string.format(fmt, ...)
    end

    local cfg = ruleRef.config or {}
    local kind = ruleRef.kind or "?"
    local displayIndex = (tonumber(zeroIndex) or 0) + 1

    add("=== Shooter Rule Diagnostics ===")
    add("Row index: %d", displayIndex)
    add("Kind: %s", kind)
    add("Source index: %s", tostring(ruleRef.sourceIndex or "?"))
    add("Priority: %s", tostring(cfg.priority or "?"))
    add("Enabled: %s", tostring(cfg.enabled == true))
    add("Need target: %s", tostring(cfg.needTarget == true))
    if kind == "rune" then
        add("Prioritize rune over potion: %s", tostring(cfg.prioritizeOverPotion ~= false))
    end
    add("Min creatures: %s", tostring(cfg.creatures or "?"))
    add("Force cast: %s", tostring(cfg.forceCast == true))
    add("Self cast: %s", tostring(cfg.selfCast == true))
    add("Client id: %s", tostring(cfg.id or "?"))

    local now = g_clock.millis()

    local player = g_game.getLocalPlayer()
    if player then
        local inPz = bit.band(player:getStates(), PlayerStates.Pz) > 0
        add("--- Player ---")
        add("In PZ: %s", tostring(inPz))
        add("Following: %s", tostring(g_game.getFollowingCreature() ~= nil))
        add("Walking: %s", tostring(player:isWalking() or player:isAutoWalking()))
        add("Mana: %d", player:getMana() or 0)
    else
        add("Player: <offline>")
    end

    local target = g_game.getAttackingCreature()
    if target then
        local tp = target:getPosition()
        local pp = player and player:getPosition()
        local dist = "?"
        if pp and tp then
            dist = tostring(math.max(math.abs(tp.x - pp.x), math.abs(tp.y - pp.y)))
        end
        add("--- Target ---")
        add("Name: %s", target:getName() or "?")
        add("Distance: %s", dist)
        add("Dead: %s", tostring(target:isDead()))
        if pp and tp then
            add("Same floor: %s", tostring(tp.z == pp.z))
            add("Sight clear: %s", tostring(g_map.isSightClear(pp, tp, false)))
        end
    else
        add("Target: <none>")
    end

    local creaturesAround = 0
    if CreatureCache and CreatureCache.getCreaturesAroundCount then
        creaturesAround = CreatureCache.getCreaturesAroundCount(6) or 0
    end
    add("Creatures around (r=6): %d", creaturesAround)

    if kind == "spell" then
        local spell = nil
        if cfg.id == -1 then
            add("--- Custom spell ---")
            add("Text: %s", tostring(cfg.customText or ""))
            local lastCastKey = "customSpell_" .. (cfg.customText or "")
            local last = (lastCastTimes and lastCastTimes[lastCastKey]) or 0
            add("Custom cd: %sms", tostring(cfg.cooldown or 2000))
            add("Last cast: %s", tostring(last))
        elseif cfg.id and cfg.id ~= 0 and Spells and Spells.getSpellByClientId then
            spell = Spells.getSpellByClientId(cfg.id)
        end

        if spell then
            add("--- Spell ---")
            add("Name: %s", tostring(spell.name or spell.words or "?"))
            add("Words: %s", tostring(spell.words or "?"))
            add("Server id: %s", tostring(spell.id or "?"))
            add("Mana cost: %s", tostring(spell.mana or "?"))
            if player then
                local hasMana = spell.mana and player:getMana() >= spell.mana
                add("Has mana: %s", tostring(hasMana == true))
            end
            if spell.vocations and translateVocation and player then
                local voc = translateVocation(player:getVocation())
                add("Voc match: %s (player=%s)", tostring(table.contains(spell.vocations, voc)), tostring(voc))
            end

            local spellCdRemain = (getSpellCooldown(spell.id) or 0) - now
            add("Spell in cd: %s (%s)", tostring(spellCdRemain > 0), formatRemainingMs(getSpellCooldown(spell.id), now))

            if type(spell.group) == "table" then
                for group, _ in pairs(spell.group) do
                    local gcd = getGroupSpellCooldown(group) or 0
                    add("Group[%s] in cd: %s (%s)", tostring(group), tostring(gcd > now), formatRemainingMs(gcd, now))
                end
            else
                local gcd = getGroupSpellCooldown(spell.group) or 0
                add("Group[%s] in cd: %s (%s)", tostring(spell.group), tostring(gcd > now), formatRemainingMs(gcd, now))
            end

            add("isSpellOnCooldown(): %s", tostring(isSpellOnCooldown(spell)))

            if spell.id and getSpellAreaType then
                local areaType = getSpellAreaType(spell.id)
                add("Area type: %s", tostring(areaType))
            end

            if spellNeedLearnBackoff then
                local sb = spellNeedLearnBackoff[spell.id] or 0
                local wb = spellNeedLearnBackoff[spell.words or ""] or 0
                local maxB = math.max(sb, wb)
                if maxB > now then
                    add("NeedLearn backoff: %s", formatRemainingMs(maxB, now))
                end
            end

            if noAreaSpellAttempts and spell.id then
                local b = noAreaSpellAttempts[spell.id] or 0
                if b > now then
                    add("NoArea backoff: %s", formatRemainingMs(b, now))
                end
            end
        elseif cfg.id ~= -1 then
            add("Spell: <unresolved id=%s>", tostring(cfg.id))
        end
    elseif kind == "rune" then
        add("--- Rune ---")
        add("Item id: %s", tostring(cfg.id or "?"))
        if player then
            local count = (g_game.findPlayerItem and g_game.findPlayerItem(cfg.id, -1)) or nil
            add("In backpack: %s", tostring(count ~= nil))
        end
    end

    add("--- Flags ---")
    add("hotkeyHelperStatus: %s", tostring(hotkeyHelperStatus == true))
    add("magicShooterEnabled: %s", tostring(helperConfig and helperConfig.magicShooterEnabled == true))
    add("autoTargetOnHold: %s", tostring(autoTargetOnHold == true))

    return table.concat(lines, "\n")
end

function createShooterRuleRow(zeroIndex, ruleRef, parentRulesList)
    local rulesList = parentRulesList or getShooterRulesListWidget()
    if not rulesList then
        return nil
    end

    local row = g_ui.createWidget("ShooterRuleRow", rulesList)
    if not row then
        return nil
    end

    local index = (tonumber(zeroIndex) or 0) + 1
    row:setId("shooterRuleRow" .. tostring(index))
    row._isSelected = false
    row._lastLeftClickMs = 0

    local rulesListWidth = rulesList:getWidth() or 0
    if rulesListWidth > 0 then
        row:setWidth(math.max(1, rulesListWidth - 2))
    end

    local idLabel = row:recursiveGetChildById("idLabel")
    local nameLabel = row:recursiveGetChildById("nameLabel")
    local ruleLabel = row:recursiveGetChildById("ruleLabel")
    local targetLabel = row:recursiveGetChildById("targetLabel")
    local settingsButton = row:recursiveGetChildById("settingsButton")
    local removeButton = row:recursiveGetChildById("removeButton")
    local itemButton = row:recursiveGetChildById("itemButton")
    local statusIcon = row:recursiveGetChildById("statusIcon")

    local cfg = ruleRef and ruleRef.config or {}
    local nameText = select(1, getShooterRuleNameAndType(ruleRef))
    local summaryText = buildShooterRuleSummaryText(ruleRef)

    row.ruleEnabledState = cfg and cfg.enabled == true

    if idLabel then
        idLabel:setText(tostring(index))
        idLabel:setTooltip("ID " .. tostring(index))
    end
    if nameLabel then
        nameLabel:setText(nameText)
        nameLabel:setTooltip(nameText)
    end
    if ruleLabel then
        ruleLabel:setText(summaryText)
        ruleLabel:setTooltip(summaryText)
    end
    if targetLabel then
        local needsTarget = cfg and cfg.needTarget == true
        targetLabel:setText(needsTarget and "Yes" or "No")
        targetLabel:setColor(needsTarget and "#7CB342" or "#808080")
        targetLabel:setTooltip(needsTarget and "Cast on attacked target" or "Area / best position")
    end

    setRuleRowEnabledIcon(row, row.ruleEnabledState)
    setShooterRuleItemVisual(row, ruleRef)
    updateShooterRuleCooldownOverlay(row, ruleRef)

    local function onRowMouseRelease(self, mousePos, mouseButton)
        local now = g_clock.millis()
        if shouldIgnoreDuplicatedRowMouseRelease(row, mouseButton, now) then
            return true
        end

        selectShooterRuleRow(row)
        if mouseButton == MouseRightButton then
            modules.game_helper.openShooterRuleContextMenu(zeroIndex, mousePos)
            return true
        end
        if mouseButton == MouseLeftButton then
            if row._lastLeftClickMs > 0 and (now - row._lastLeftClickMs) <= SHOOTER_ROW_DOUBLE_CLICK_MS then
                row._lastLeftClickMs = 0
                modules.game_helper.toggleShooterRuleEnabled(zeroIndex)
                return true
            end
            row._lastLeftClickMs = now
        end
        return false
    end

    local function refreshDiagnosticsTooltip()
        local ok, text = pcall(buildShooterRuleDiagnostics, ruleRef, zeroIndex)
        if ok and type(text) == "string" then
            row:setTooltip(text)
            if nameLabel then nameLabel:setTooltip(text) end
            if ruleLabel then ruleLabel:setTooltip(text) end
            if targetLabel then targetLabel:setTooltip(text) end
            if idLabel then idLabel:setTooltip(text) end
            if statusIcon then statusIcon:setTooltip(text) end
            if itemButton then itemButton:setTooltip(text) end
        end
    end

    row.onHoverChange = function(self, hovered)
        if hovered then
            refreshDiagnosticsTooltip()
        end
    end
    refreshDiagnosticsTooltip()

    row.onMouseRelease = onRowMouseRelease
    if idLabel then idLabel.onMouseRelease = onRowMouseRelease end
    if statusIcon then statusIcon.onMouseRelease = onRowMouseRelease end
    if nameLabel then nameLabel.onMouseRelease = onRowMouseRelease end
    if ruleLabel then ruleLabel.onMouseRelease = onRowMouseRelease end
    if itemButton then
        itemButton.onMouseRelease = function(self, mousePos, mouseButton)
            if mouseButton == MouseRightButton then
                modules.game_helper.openShooterRuleContextMenu(zeroIndex, mousePos)
                return true
            end
            return onRowMouseRelease(self, mousePos, mouseButton)
        end
        itemButton.onClick = function()
            modules.game_helper.editShooterRule(zeroIndex)
        end
    end
    if settingsButton then
        settingsButton.onMouseRelease = function(self, mousePos, mouseButton)
            selectShooterRuleRow(row)
            if mouseButton == MouseRightButton then
                modules.game_helper.openShooterRuleContextMenu(zeroIndex, mousePos)
            end
            return true
        end
        settingsButton.onClick = function()
            modules.game_helper.editShooterRule(zeroIndex)
        end
    end
    if removeButton then
        removeButton.onMouseRelease = function(self, mousePos, mouseButton)
            selectShooterRuleRow(row)
            if mouseButton == MouseRightButton then
                modules.game_helper.openShooterRuleContextMenu(zeroIndex, mousePos)
            end
            return true
        end
        removeButton.onClick = function()
            confirmDeleteRule(tr("shooter"), function()
                modules.game_helper.removeShooterRule(zeroIndex)
            end)
        end
    end

    return row
end

function rebuildAllShooterRules()
    local rulesList = getShooterRulesListWidget()
    if not rulesList then
        return
    end

    local profile = getShooterProfile()
    if not profile then
        return
    end

    ensureShooterProfileConfig(profile, true)
    local refs = buildShooterUnifiedRuleRefs(profile)

    clearShooterRuleSelection()
    rulesList:destroyChildren()

    for i = 1, #refs do
        createShooterRuleRow(i - 1, refs[i], rulesList)
    end

    refreshShooterRuleRowColors()
    refreshAllShooterRuleCooldownOverlays()
    startSpellRuleCooldownOverlayLoop()
end

function modules.game_helper.toggleShooterRuleEnabled(zeroIndex, explicitState)
    local profile = getShooterProfile()
    if not profile then
        return
    end
    ensureShooterProfileConfig(profile, true)

    local refs = buildShooterUnifiedRuleRefs(profile)
    local index = (tonumber(zeroIndex) or -1) + 1
    local ref = refs[index]
    if not ref or type(ref.config) ~= "table" then
        return
    end

    local newState = explicitState
    if newState == nil then
        newState = not (ref.config.enabled == true)
    end
    ref.config.enabled = newState == true

    saveSettings()
    rebuildAllShooterRules()
end

function modules.game_helper.moveShooterRule(zeroIndex, direction)
    local profile = getShooterProfile()
    if not profile then
        return
    end
    ensureShooterProfileConfig(profile, true)

    local refs = buildShooterUnifiedRuleRefs(profile)
    local fromIndex = (tonumber(zeroIndex) or -1) + 1
    local toIndex = fromIndex + (tonumber(direction) or 0)
    if fromIndex < 1 or fromIndex > #refs or toIndex < 1 or toIndex > #refs then
        return
    end

    local moved = table.remove(refs, fromIndex)
    table.insert(refs, toIndex, moved)
    applyShooterRuleRefOrder(profile, refs)

    saveSettings()
    rebuildAllShooterRules()
end

function modules.game_helper.removeShooterRule(zeroIndex)
    local profile = getShooterProfile()
    if not profile then
        return
    end
    ensureShooterProfileConfig(profile, true)

    local refs = buildShooterUnifiedRuleRefs(profile)
    local index = (tonumber(zeroIndex) or -1) + 1
    local ref = refs[index]
    if not ref then
        return
    end

    if ref.kind == "spell" then
        table.remove(profile.spells, ref.sourceIndex)
    else
        table.remove(profile.runes, ref.sourceIndex)
    end

    local updatedRefs = buildShooterUnifiedRuleRefs(profile)
    applyShooterRuleRefOrder(profile, updatedRefs)

    saveSettings()
    rebuildAllShooterRules()
end

function modules.game_helper.duplicateShooterRule(zeroIndex)
    local profile = getShooterProfile()
    if not profile then
        return
    end
    ensureShooterProfileConfig(profile, true)

    local refs = buildShooterUnifiedRuleRefs(profile)
    local index = (tonumber(zeroIndex) or -1) + 1
    local ref = refs[index]
    if not ref or type(ref.config) ~= "table" then
        return
    end

    if ref.kind == "spell" then
        local clonedSpell = ensureShooterSpellRule(deepCopy(ref.config), index + 1)
        clonedSpell.priority = (tonumber(ref.config.priority) or index) + 0.1
        table.insert(profile.spells, (tonumber(ref.sourceIndex) or 0) + 1, clonedSpell)
    else
        local clonedRune = ensureShooterRuneRule(deepCopy(ref.config), index + 1)
        clonedRune.priority = (tonumber(ref.config.priority) or index) + 0.1
        table.insert(profile.runes, (tonumber(ref.sourceIndex) or 0) + 1, clonedRune)
    end

    local updatedRefs = buildShooterUnifiedRuleRefs(profile)
    applyShooterRuleRefOrder(profile, updatedRefs)

    saveSettings()
    rebuildAllShooterRules()
end

function modules.game_helper.editShooterRule(zeroIndex)
    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    modules.game_helper.openShooterSettingsPopup(index, nil, false)
end

function modules.game_helper.openShooterRuleContextMenu(zeroIndex, mousePos)
    local profile = getShooterProfile()
    if not profile then
        return
    end
    ensureShooterProfileConfig(profile, true)

    local refs = buildShooterUnifiedRuleRefs(profile)
    local index = (tonumber(zeroIndex) or -1) + 1
    local ref = refs[index]
    if not ref then
        return
    end

    local menu = g_ui.createWidget("HelperPopupMenu")
    menu:setGameMenu(true)
    if index > 1 then
        menu:addOption(tr("Move Up"), function()
            modules.game_helper.moveShooterRule(index - 1, -1)
        end)
    end
    if index < #refs then
        menu:addOption(tr("Move Down"), function()
            modules.game_helper.moveShooterRule(index - 1, 1)
        end)
    end
    menu:addOption(tr("Edit"), function()
        modules.game_helper.editShooterRule(index - 1)
    end)
    menu:addOption(tr("Duplicate"), function()
        modules.game_helper.duplicateShooterRule(index - 1)
    end)
    menu:addOption(tr("Delete"), function()
        confirmDeleteRule(tr("shooter"), function()
            modules.game_helper.removeShooterRule(index - 1)
        end)
    end)
    menu:addOption(ref.config.enabled and tr("Disable") or tr("Enable"), function()
        modules.game_helper.toggleShooterRuleEnabled(index - 1, not (ref.config.enabled == true))
    end)
    menu:display(mousePos or g_window.getMousePosition())
end

function modules.game_helper.addShooterRule(initialRule)
    modules.game_helper.openShooterSettingsPopup(nil, initialRule, true)
end

function modules.game_helper.openAddShooterRulePopup()
    local profile = getShooterProfile()
    local nextPriority = 1
    if profile then
        ensureShooterProfileConfig(profile, true)
        nextPriority = #buildShooterUnifiedRuleRefs(profile) + 1
    end
    modules.game_helper.addShooterRule({
        actionType = "Spell",
        id = 0,
        creatures = 1,
        minHarmony = 0,
        needTarget = false,
        prioritizeOverPotion = true,
        enabled = true,
        priority = nextPriority
    })
end

function getShooterSettingsPopupWidget()
    if shooterSettingsPopup and shooterSettingsPopup:isDestroyed() then
        shooterSettingsPopup = nil
    end
    if shooterSettingsPopup then
        return shooterSettingsPopup
    end

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return nil
    end

    local popup = rootWidget:recursiveGetChildById("shooterSettingsPopup")
    if popup and not popup:isDestroyed() then
        shooterSettingsPopup = popup
    end
    return shooterSettingsPopup
end

function getShooterRuleRefByZeroIndex(zeroIndex)
    local profile = getShooterProfile()
    if not profile then
        return nil
    end
    ensureShooterProfileConfig(profile, true)
    local refs = buildShooterUnifiedRuleRefs(profile)
    local index = (tonumber(zeroIndex) or -1) + 1
    return refs[index]
end

function refreshShooterPopupSpellVisual()
    local popup = getShooterSettingsPopupWidget()
    if not popup then
        return
    end
    local spellButton = popup:recursiveGetChildById("spellSelectButton")
    local spellPreviewButton = popup:recursiveGetChildById("spellPreviewButton")
    if not spellButton then
        return
    end

    local function resetPreview()
        if spellPreviewButton then
            spellPreviewButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
            spellPreviewButton:setImageClip("0 0 34 34")
            spellPreviewButton:setTooltip("")
        end
    end

    if type(popup._draftRule) ~= "table" then
        spellButton:setText("Select Spell")
        spellButton:setTooltip("")
        resetPreview()
        return
    end

    local draft = popup._draftRule
    local spellId = tonumber(draft.id) or 0
    if spellId == -1 and tostring(draft.customText or "") ~= "" then
        local label = tostring(draft.customText)
        if #label > 24 then
            label = string.sub(label, 1, 21) .. "..."
        end
        spellButton:setText(label)
        spellButton:setTooltip("Text: " .. tostring(draft.customText))
        resetPreview()
        return
    end

    if spellId <= 0 then
        spellButton:setText("Select Spell")
        spellButton:setTooltip("")
        resetPreview()
        return
    end

    local spellData = Spells.getSpellByClientId(spellId)
    if not spellData then
        spellButton:setText("Spell " .. tostring(spellId))
        spellButton:setTooltip("Spell ID: " .. tostring(spellId))
        resetPreview()
        return
    end

    local spellName = tostring(spellData.name or spellData.words or ("Spell " .. tostring(spellId)))
    local words = tostring(spellData.words or "")
    local buttonText = spellName
    if #buttonText > 20 then
        buttonText = string.sub(buttonText, 1, 17) .. "..."
    end
    spellButton:setText(buttonText)
    spellButton:setTooltip("Spell: " .. spellName .. "\nWords: " .. words)

    if spellPreviewButton then
        local iconSource, iconClip = getHealingSpellIconData(words)
        if iconSource and iconClip then
            spellPreviewButton:setImageSource(iconSource)
            spellPreviewButton:setImageClip(iconClip)
        else
            spellPreviewButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
            spellPreviewButton:setImageClip("0 0 34 34")
        end
        spellPreviewButton:setTooltip("Spell: " .. spellName .. "\nWords: " .. words)
    end
end

function refreshShooterPopupRuneVisual()
    local popup = getShooterSettingsPopupWidget()
    if not popup then
        return
    end

    if type(popup._draftRule) ~= "table" then
        popup._draftRule = {}
    end

    local runeId = tonumber(popup._draftRule.id) or 0
    local runeInput = popup:recursiveGetChildById("runeIdInput")
    local runeButton = popup:recursiveGetChildById("runePreviewButton")
    local runeNameLabel = popup:recursiveGetChildById("runeNameLabel")

    if runeInput then
        local targetText = runeId > 0 and tostring(runeId) or ""
        local currentText = runeInput:getText() or ""
        if currentText ~= targetText then
            local oldOnTextChange = runeInput.onTextChange
            runeInput.onTextChange = nil
            runeInput:setText(targetText)
            runeInput.onTextChange = oldOnTextChange
        end
    end

    if not runeButton then
        return
    end

    local itemWidget = runeButton:getChildById("shooterPopupRuneItem")
    if runeId > 0 then
        runeButton:setImageSource("/images/ui/item")
        if not itemWidget then
            itemWidget = g_ui.createWidget("RuneItem", runeButton)
            if itemWidget then
                itemWidget:setId("shooterPopupRuneItem")
            end
        end
        if itemWidget then
            itemWidget:setItemId(runeId)
        end

        local runeData = getShooterRuneDataById(runeId)
        local runeName = runeData and tostring(runeData.name or "") or resolveHelperItemNameById(runeId)
        runeButton:setTooltip(runeName)
        if runeNameLabel then
            runeNameLabel:setText(runeName)
        end
    else
        if itemWidget then
            itemWidget:destroy()
        end
        runeButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
        runeButton:setImageClip("0 0 34 34")
        runeButton:setTooltip("")
        if runeNameLabel then
            runeNameLabel:setText("")
        end
    end
end

function modules.game_helper.setShooterPopupRuneId(itemId)
    local popup = getShooterSettingsPopupWidget()
    if not popup then
        return
    end
    if type(popup._draftRule) ~= "table" then
        popup._draftRule = {}
    end

    local parsedId = tonumber(itemId) or 0
    if parsedId < 0 then
        parsedId = 0
    end
    popup._draftRule.id = parsedId
    refreshShooterPopupRuneVisual()
end

function modules.game_helper.removeShooterPopupRune()
    modules.game_helper.setShooterPopupRuneId(0)
end

function modules.game_helper.onShooterPopupRuneDrop(targetWidget, draggedWidget, mousePos)
    local popup = getShooterSettingsPopupWidget()
    if not popup then
        return false
    end

    local draggedItemId = getEquipmentPopupDraggedItemId(draggedWidget, mousePos)
    if draggedItemId <= 0 then
        return false
    end

    modules.game_helper.setShooterPopupRuneId(draggedItemId)
    return true
end

function modules.game_helper.startShooterPopupRuneSelection()
    if not mouseGrabberWidget then
        return
    end

    local popup = getShooterSettingsPopupWidget()
    mouseGrabberWidget:grabMouse()
    if popup then
        popup:hide()
    end
    g_mouse.pushCursor("target")

    mouseGrabberWidget.onMouseRelease = function(self, mousePosition, mouseButton)
        if mouseGrabberWidget then
            mouseGrabberWidget:ungrabMouse()
            mouseGrabberWidget.onMouseRelease = nil
        end
        if popup and not popup:isDestroyed() then
            popup:show()
        end
        g_mouse.popCursor("target")

        if mouseButton ~= MouseLeftButton then
            return true
        end

        local rootWidget = g_ui.getRootWidget()
        if not rootWidget then
            return true
        end

        local clickedWidget = rootWidget:recursiveGetChildByPos(mousePosition, false)
        if not clickedWidget then
            return true
        end

        local item = nil
        if clickedWidget:getClassName() == "UIItem" and not clickedWidget:isVirtual() then
            item = clickedWidget:getItem()
        elseif clickedWidget:getClassName() == "UIGameMap" then
            local tile = clickedWidget:getTile(mousePosition)
            if tile then
                local topUseThing = tile:getTopUseThing()
                if topUseThing and topUseThing:isItem() then
                    item = topUseThing
                end
            end
        end

        if not item then
            modules.game_textmessage.displayFailureMessage(tr("Invalid rune!"))
            return true
        end

        modules.game_helper.setShooterPopupRuneId(item:getId())
        return true
    end
end

function modules.game_helper.openShooterPopupRuneMenu(button, mousePos)
    local popup = getShooterSettingsPopupWidget()
    if not popup then
        return
    end
    local runeId = 0
    if type(popup._draftRule) == "table" then
        runeId = tonumber(popup._draftRule.id) or 0
    end

    local menu = g_ui.createWidget("HelperPopupMenu")
    menu:setGameMenu(true)
    menu:addOption(tr("Select Rune"), function()
        modules.game_helper.startShooterPopupRuneSelection()
    end)
    menu:addOption(tr("Assign ID"), function()
        openAssignItemIdWindow(button, "shooterPopupRune")
    end)
    menu:addOption(tr("Assign List"), function()
        openAssignItemListWindow(button, "shooterPopupRune")
    end)
    if runeId > 0 then
        menu:addOption(tr("Remove"), function()
            modules.game_helper.removeShooterPopupRune()
        end)
    end
    menu:display(mousePos or g_window.getMousePosition())
end

function updateShooterSettingsPopupActionState()
    local popup = getShooterSettingsPopupWidget()
    if not popup then
        return
    end
    if type(popup._draftRule) ~= "table" then
        popup._draftRule = {}
    end

    local actionCombo = popup:recursiveGetChildById("actionTypeCombo")
    local actionType = "Spell"
    if actionCombo then
        local current = actionCombo:getCurrentOption()
        if current and current.text then
            actionType = tostring(current.text)
        end
    end

    local spellRow = popup:recursiveGetChildById("spellRow")
    local runeRow = popup:recursiveGetChildById("runeRow")
    local needTargetCheck = popup:recursiveGetChildById("needTargetCheck")
    local runePotionPriorityRow = popup:recursiveGetChildById("runePotionPriorityRow")
    local prioritizeRuneOverPotionCheck = popup:recursiveGetChildById("prioritizeRuneOverPotionCheck")
    if spellRow then
        spellRow:setVisible(actionType ~= "Rune")
    end
    if runeRow then
        runeRow:setVisible(actionType == "Rune")
    end
    if needTargetCheck then
        needTargetCheck:setVisible(true)
    end
    if runePotionPriorityRow then
        runePotionPriorityRow:setVisible(actionType == "Rune")
    end
    if prioritizeRuneOverPotionCheck and actionType == "Rune" then
        if type(popup._draftRule) == "table" and popup._draftRule.prioritizeOverPotion == nil then
            popup._draftRule.prioritizeOverPotion = true
        end
        if type(popup._draftRule) == "table" then
            prioritizeRuneOverPotionCheck:setChecked(popup._draftRule.prioritizeOverPotion ~= false)
        end
    end

    popup._draftRule.actionType = actionType == "Rune" and "Rune" or "Spell"

    updateShooterSettingsPopupHarmonyState()
end

function updateShooterSettingsPopupHarmonyState()
    local popup = getShooterSettingsPopupWidget()
    if not popup then
        return
    end

    local draft = type(popup._draftRule) == "table" and popup._draftRule or {}
    local showHarmony = isShooterHarmonyVisible(draft.id)
    if tostring(draft.actionType or "Spell") == "Rune" then
        showHarmony = false
    end

    local harmonyRow = popup:recursiveGetChildById("harmonyRow")
    if harmonyRow then
        harmonyRow:setVisible(showHarmony)
    end
    if not showHarmony and type(popup._draftRule) == "table" then
        popup._draftRule.minHarmony = 0
    end
end

function modules.game_helper.openShooterPopupSpellSelector()
    local popup = getShooterSettingsPopupWidget()
    if not popup then
        return
    end

    if toggleAssignSpellWindow() then
        return
    end

    local playerObj = g_game.getLocalPlayer()
    if not playerObj then
        modules.game_textmessage.displayFailureMessage(tr("Player not found."))
        return
    end

    if not SpellInfo then
        modules.game_textmessage.displayFailureMessage(tr("Spell list unavailable."))
        return
    end

    local window = g_ui.loadUI("styles/spell", g_ui.getRootWidget())
    if not window then
        modules.game_textmessage.displayFailureMessage(tr("Failed to open spell list."))
        return
    end
    applyOpacityToWindow(window)

    local playerVocation = translateVocation(playerObj:getVocation())
    local currentSpellId = type(popup._draftRule) == "table" and (tonumber(popup._draftRule.id) or 0) or 0
    local radio = UIRadioGroup.create()
    local preselectedWidget = nil
    local spellCount = 0

    window:show(true)
    window:raise()
    window:focus()
    window:setText("Assign Shooter Spell")
    safeSetInputLockWidget(window)
    popup:hide()

    local tickCheck = window:recursiveGetChildById("tick")
    if tickCheck then
        tickCheck:setChecked(true)
        tickCheck:setEnabled(false)
    end

    local applyButton = window:recursiveGetChildById("buttonApply")
    if applyButton then
        applyButton:setVisible(false)
    end

    for profileName, spells in pairs(SpellInfo) do
        if type(spells) ~= "table" then goto continue_shooter_profile end
        for spellName, spellData in pairs(spells) do
            if type(spellData) ~= 'table' or not spellData.id then goto continue_shooter_popup_spell end
            local spellVocations = spellData and spellData.vocations or {}
            if not table.contains(spellVocations, playerVocation) then
                goto continue_shooter_popup_spell
            end

            local groupIds = Spells.getGroupIds(spellData)
            local isAttackSpell = table.contains(groupIds, 1) or table.contains(groupIds, 4) or
            table.contains(groupIds, 8)
            if not isAttackSpell then
                goto continue_shooter_popup_spell
            end
            if ignoredSpellsIds[spellData.id] then
                goto continue_shooter_popup_spell
            end

            local widget = g_ui.createWidget("SpellPreview", window.contentPanel.spellList)
            if not widget then
                goto continue_shooter_popup_spell
            end

            local spellIconId = nil
            if SpellIcons and spellData.icon and SpellIcons[spellData.icon] then
                spellIconId = SpellIcons[spellData.icon][1]
            end

            local words = tostring(spellData.words or "")
            local displayName = tostring(spellData.name or spellName or words)
            if displayName == "" then
                displayName = words
            end

            radio:addWidget(widget)
            widget:setId(tonumber(spellData.id) or 0)
            widget:setText(displayName .. "\n" .. words)
            widget.spellName = displayName
            widget.spellWords = words
            widget.source = SpelllistSettings and SpelllistSettings[profileName] and
            SpelllistSettings[profileName].iconsFolder or ""
            widget.clip = spellIconId and Spells.getImageClip and Spells.getImageClipNormal(spellIconId, profileName) or
            nil
            if widget.source and widget.source ~= "" then
                widget.image:setImageSource(widget.source)
            end
            if widget.clip then
                widget.image:setImageClip(widget.clip)
            end

            if spellData.level then
                widget.levelLabel:setVisible(true)
                widget.levelLabel:setText(string.format("Level: %d", tonumber(spellData.level) or 0))
            end

            spellCount = spellCount + 1
            if currentSpellId > 0 and (tonumber(spellData.id) or 0) == currentSpellId then
                preselectedWidget = widget
            end

            ::continue_shooter_popup_spell::
        end
        ::continue_shooter_profile::
    end

    if spellCount == 0 then
        modules.game_textmessage.displayFailureMessage(tr("No attack spells found for your vocation."))
        safeSetInputLockWidget(nil)
        popup:show()
        window:destroy()
        return
    end

    local widgets = window.contentPanel.spellList:getChildren()
    table.sort(widgets, function(a, b)
        return a:getText() < b:getText()
    end)
    for i, widget in ipairs(widgets) do
        window.contentPanel.spellList:moveChildToIndex(widget, i)
    end

    radio.onSelectionChange = function(widget, selected)
        if selected then
            window.contentPanel.preview:setText(selected:getText())
            window.contentPanel.preview.image:setImageSource(selected.source or "")
            if selected.clip then
                window.contentPanel.preview.image:setImageClip(selected.clip)
            end
            window.contentPanel.paramLabel:setOn(false)
            window.contentPanel.paramText:setEnabled(false)
            window.contentPanel.paramText:clearText()
            window.contentPanel.spellList:ensureChildVisible(widget)
        end
    end

    if preselectedWidget then
        radio:selectWidget(preselectedWidget)
    elseif widgets and #widgets > 0 then
        radio:selectWidget(widgets[1])
    end

    local function closeSelector()
        safeSetInputLockWidget(nil)
        if popup and not popup:isDestroyed() then
            popup:show()
            popup:raise()
            popup:focus()
        end
        if window and not window:isDestroyed() then
            window:destroy()
        end
    end

    local function confirmSelection(closeAfter)
        local selected = radio:getSelectedWidget()
        if not selected then
            modules.game_textmessage.displayFailureMessage(tr("Select a spell."))
            return
        end

        local currentPopup = getShooterSettingsPopupWidget()
        if currentPopup and not currentPopup:isDestroyed() then
            if type(currentPopup._draftRule) ~= "table" then
                currentPopup._draftRule = {}
            end
            currentPopup._draftRule.actionType = "Spell"
            currentPopup._draftRule.id = tonumber(selected:getId()) or 0
            currentPopup._draftRule.customText = ""
            refreshShooterPopupSpellVisual()

            local actionTypeCombo = currentPopup:recursiveGetChildById("actionTypeCombo")
            if actionTypeCombo then
                actionTypeCombo:setCurrentOption("Spell")
            end
            updateShooterSettingsPopupActionState()
            updateShooterSettingsPopupHarmonyState()
        end

        if closeAfter then
            closeSelector()
        end
    end

    local cancelButton = window:recursiveGetChildById("buttonClose")
    local okButton = window:recursiveGetChildById("buttonOk")

    if okButton then
        okButton.onClick = function()
            confirmSelection(true)
        end
    end
    if cancelButton then
        cancelButton.onClick = closeSelector
    end
    window.contentPanel.onEnter = function()
        confirmSelection(true)
    end
    window.onEscape = closeSelector
end

function bindShooterSettingsPopupHandlers(window)
    if not window or window:isDestroyed() then
        return
    end
    if window._shooterPopupHandlersBound then
        return
    end

    local actionTypeCombo = window:recursiveGetChildById("actionTypeCombo")
    if actionTypeCombo then
        actionTypeCombo:clearOptions()
        actionTypeCombo:addOption("Spell")
        actionTypeCombo:addOption("Rune")
        actionTypeCombo.onOptionChange = function()
            updateShooterSettingsPopupActionState()
        end
    end

    local creaturesCombo = window:recursiveGetChildById("creaturesCombo")
    if creaturesCombo then
        creaturesCombo:clearOptions()
        creaturesCombo:addOption("0")
        creaturesCombo:addOption("1")
        creaturesCombo:addOption("1+")
        creaturesCombo:addOption("2+")
        creaturesCombo:addOption("3+")
        creaturesCombo:addOption("4+")
        creaturesCombo:addOption("5+")
        creaturesCombo:addOption("6+")
        creaturesCombo:addOption("7+")
        creaturesCombo:addOption("8+")
        creaturesCombo:addOption("9+")
        creaturesCombo:addOption("10+")
    end

    local minHarmonyCombo = window:recursiveGetChildById("minHarmonyCombo")
    if minHarmonyCombo then
        minHarmonyCombo:clearOptions()
        minHarmonyCombo:addOption("0")
        minHarmonyCombo:addOption("1")
        minHarmonyCombo:addOption("2")
        minHarmonyCombo:addOption("3")
        minHarmonyCombo:addOption("4")
        minHarmonyCombo:addOption("5")
    end

    local prioritizeRuneOverPotionCheck = window:recursiveGetChildById("prioritizeRuneOverPotionCheck")
    if prioritizeRuneOverPotionCheck then
        prioritizeRuneOverPotionCheck.onCheckChange = function()
            local currentPopup = getShooterSettingsPopupWidget()
            if currentPopup and type(currentPopup._draftRule) == "table" then
                currentPopup._draftRule.prioritizeOverPotion = prioritizeRuneOverPotionCheck:isChecked()
            end
        end
    end

    local spellSelectButton = window:recursiveGetChildById("spellSelectButton")
    if spellSelectButton then
        spellSelectButton.onMouseRelease = function(self, mousePos, mouseButton)
            if mouseButton ~= MouseLeftButton and mouseButton ~= MouseRightButton then
                return false
            end
            modules.game_helper.openShooterPopupSpellSelector()
            return true
        end
    end

    local spellPreviewButton = window:recursiveGetChildById("spellPreviewButton")
    if spellPreviewButton then
        spellPreviewButton.onMouseRelease = function(self, mousePos, mouseButton)
            if mouseButton ~= MouseLeftButton and mouseButton ~= MouseRightButton then
                return false
            end
            modules.game_helper.openShooterPopupSpellSelector()
            return true
        end
    end

    local runeIdInput = window:recursiveGetChildById("runeIdInput")
    if runeIdInput then
        runeIdInput.onTextChange = function(self)
            local text = self:getText() or ""
            local sanitized = text:gsub("[^0-9]", "")
            if sanitized ~= text then
                self:setText(sanitized)
                if self.setCursorPos then self:setCursorPos(-1) end
            end
            scheduleNumericInputClamp(self, 0, 99999, nil, nil)
            local itemId = tonumber(self:getText() or "") or 0
            modules.game_helper.setShooterPopupRuneId(itemId)
        end
        runeIdInput.onDrop = function(self, draggedWidget, mousePos)
            return modules.game_helper.onShooterPopupRuneDrop(self, draggedWidget, mousePos)
        end
    end

    local runeButton = window:recursiveGetChildById("runePreviewButton")
    if runeButton then
        runeButton.onDrop = function(self, draggedWidget, mousePos)
            return modules.game_helper.onShooterPopupRuneDrop(self, draggedWidget, mousePos)
        end
        runeButton.onMouseRelease = function(self, mousePos, mouseButton)
            if mouseButton ~= MouseLeftButton and mouseButton ~= MouseRightButton then
                return false
            end
            local draggingWidget = g_ui.getDraggingWidget()
            if mouseButton == MouseLeftButton and draggingWidget and modules.game_helper.onShooterPopupRuneDrop(self, draggingWidget, mousePos) then
                return true
            end
            modules.game_helper.openShooterPopupRuneMenu(self, mousePos)
            return true
        end
    end

    window._shooterPopupHandlersBound = true
end

function refreshShooterSettingsPopup()
    local popup = getShooterSettingsPopupWidget()
    if not popup then
        return
    end

    local popupTitleLabel = popup:recursiveGetChildById("popupTitleLabel")
    if popupTitleLabel then
        popupTitleLabel:setText(popup.isNewRule and "Add Shooter Rule" or "Edit Shooter Rule")
    end

    local saveButton = popup:recursiveGetChildById("saveButton")
    if saveButton then
        saveButton:setText(popup.isNewRule and "Add" or "Save")
    end

    if type(popup._draftRule) ~= "table" then
        popup._draftRule = {
            actionType = "Spell",
            id = 0,
            creatures = 1,
            minHarmony = 0,
            needTarget = false,
            prioritizeOverPotion = true,
            enabled = true
        }
    end

    local draft = popup._draftRule
    local actionType = tostring(draft.actionType or "Spell")
    if actionType ~= "Rune" then
        actionType = "Spell"
    end
    draft.actionType = actionType

    local actionTypeCombo = popup:recursiveGetChildById("actionTypeCombo")
    if actionTypeCombo then
        actionTypeCombo:setCurrentOption(actionType)
    end

    local creaturesCombo = popup:recursiveGetChildById("creaturesCombo")
    if creaturesCombo then
        creaturesCombo:setCurrentOption(formatCreaturesValue(tonumber(draft.creatures) or 1))
    end

    local needTargetCheck = popup:recursiveGetChildById("needTargetCheck")
    if needTargetCheck then
        needTargetCheck:setChecked(draft.needTarget == true)
    end

    local prioritizeRuneOverPotionCheck = popup:recursiveGetChildById("prioritizeRuneOverPotionCheck")
    if prioritizeRuneOverPotionCheck then
        prioritizeRuneOverPotionCheck:setChecked(draft.prioritizeOverPotion ~= false)
    end

    local minHarmonyCombo = popup:recursiveGetChildById("minHarmonyCombo")
    if minHarmonyCombo then
        minHarmonyCombo:setCurrentOption(tostring(tonumber(draft.minHarmony) or 0))
    end

    refreshShooterPopupSpellVisual()
    refreshShooterPopupRuneVisual()
    updateShooterSettingsPopupActionState()
end

function modules.game_helper.closeShooterSettingsPopup()
    if shooterSettingsPopup and not shooterSettingsPopup:isDestroyed() then
        shooterSettingsPopup:destroy()
        shooterSettingsPopup = nil
    end
end

function modules.game_helper.saveShooterSettingsPopup()
    local popup = getShooterSettingsPopupWidget()
    if not popup then
        return
    end

    local profile = getShooterProfile()
    if not profile then
        modules.game_textmessage.displayFailureMessage(tr("Invalid shooter profile."))
        return
    end
    ensureShooterProfileConfig(profile, true)

    if type(popup._draftRule) ~= "table" then
        modules.game_textmessage.displayFailureMessage(tr("Invalid shooter rule."))
        return
    end

    local actionTypeCombo = popup:recursiveGetChildById("actionTypeCombo")
    local creaturesCombo = popup:recursiveGetChildById("creaturesCombo")
    local needTargetCheck = popup:recursiveGetChildById("needTargetCheck")
    local prioritizeRuneOverPotionCheck = popup:recursiveGetChildById("prioritizeRuneOverPotionCheck")
    local minHarmonyCombo = popup:recursiveGetChildById("minHarmonyCombo")

    local actionType = "Spell"
    if actionTypeCombo then
        local current = actionTypeCombo:getCurrentOption()
        if current and current.text then
            actionType = tostring(current.text)
        end
    end
    if actionType ~= "Rune" then
        actionType = "Spell"
    end

    local draft = popup._draftRule
    local creaturesText = creaturesCombo and
    (creaturesCombo:getCurrentOption() and creaturesCombo:getCurrentOption().text) or "1+"
    local creaturesValue = parseShooterCreaturesOptionText(creaturesText)
    local minHarmonyValue = minHarmonyCombo and
    tonumber((minHarmonyCombo:getCurrentOption() and minHarmonyCombo:getCurrentOption().text) or "0") or 0
    local needTarget = needTargetCheck and needTargetCheck:isChecked() or false
    local prioritizeOverPotion = true
    if actionType == "Rune" and prioritizeRuneOverPotionCheck then
        prioritizeOverPotion = prioritizeRuneOverPotionCheck:isChecked()
    end

    if actionType == "Rune" then
        local runeId = tonumber(draft.id) or 0
        if runeId <= 0 then
            modules.game_textmessage.displayFailureMessage(tr("Select a rune."))
            return
        end
    else
        local spellId = tonumber(draft.id) or 0
        local hasCustom = spellId == -1 and tostring(draft.customText or "") ~= ""
        if spellId <= 0 and not hasCustom then
            modules.game_textmessage.displayFailureMessage(tr("Select a spell."))
            return
        end
        if spellId > 0 then
            local spellData = Spells.getSpellByClientId(spellId)
            if not spellData then
                modules.game_textmessage.displayFailureMessage(tr("Invalid spell."))
                return
            end
            local groupIds = Spells.getGroupIds(spellData) or {}
            local isAttackSpell = table.contains(groupIds, 1) or table.contains(groupIds, 4) or
            table.contains(groupIds, 8)
            if not isAttackSpell then
                modules.game_textmessage.displayFailureMessage(tr("Select an attack spell."))
                return
            end
        end
    end

    local priorityValue = tonumber(draft.priority) or (#buildShooterUnifiedRuleRefs(profile) + 1)
    local enabledState = draft.enabled ~= false

    local oldKind = popup._editKind
    local oldIndex = tonumber(popup._editSourceIndex)
    if oldKind and oldIndex then
        local oldCfg = (oldKind == "spell" and profile.spells[oldIndex]) or
        (oldKind == "rune" and profile.runes[oldIndex])
        if oldCfg then
            priorityValue = tonumber(oldCfg.priority) or priorityValue
            enabledState = oldCfg.enabled ~= false
        end
    end

    if actionType == "Rune" then
        local newCfg = ensureShooterRuneRule({
            id = tonumber(draft.id) or 0,
            creatures = creaturesValue,
            priority = priorityValue,
            forceCast = draft.forceCast == true,
            enabled = enabledState,
            needTarget = needTarget == true,
            prioritizeOverPotion = prioritizeOverPotion == true
        }, priorityValue)

        if oldKind == "rune" and oldIndex and profile.runes[oldIndex] then
            profile.runes[oldIndex] = newCfg
        else
            if oldKind == "spell" and oldIndex and profile.spells[oldIndex] then
                table.remove(profile.spells, oldIndex)
            end
            profile.runes[#profile.runes + 1] = newCfg
        end
    else
        local newCfg = ensureShooterSpellRule({
            id = tonumber(draft.id) or 0,
            percent = 100,
            creatures = creaturesValue,
            priority = priorityValue,
            forceCast = draft.forceCast == true,
            selfCast = draft.selfCast == true,
            enabled = enabledState,
            customText = tostring(draft.customText or ""),
            cooldown = tonumber(draft.cooldown) or 2000,
            minHarmony = isShooterHarmonyVisible(draft.id) and minHarmonyValue or 0,
            needTarget = needTarget == true
        }, priorityValue)

        if oldKind == "spell" and oldIndex and profile.spells[oldIndex] then
            profile.spells[oldIndex] = newCfg
        else
            if oldKind == "rune" and oldIndex and profile.runes[oldIndex] then
                table.remove(profile.runes, oldIndex)
            end
            profile.spells[#profile.spells + 1] = newCfg
        end
    end

    ensureShooterProfileConfig(profile, true)
    local refs = buildShooterUnifiedRuleRefs(profile)
    applyShooterRuleRefOrder(profile, refs)

    saveSettings()
    modules.game_helper.closeShooterSettingsPopup()
    rebuildAllShooterRules()
    updateAllItemCounts()
end

function modules.game_helper.openShooterSettingsPopup(zeroIndex, initialRule, isNew)
    if shooterSettingsPopup and not shooterSettingsPopup:isDestroyed() then
        shooterSettingsPopup:destroy()
        shooterSettingsPopup = nil
    end

    local window = g_ui.loadUI("styles/shooter_settings_popup", g_ui.getRootWidget())
    if not window then
        modules.game_textmessage.displayFailureMessage(htr("Failed to open shooter settings."))
        return
    end

    shooterSettingsPopup = window
    applyOpacityToWindow(window)
    window.isNewRule = isNew == true
    window._editKind = nil
    window._editSourceIndex = nil

    local profile = getShooterProfile()
    ensureShooterProfileConfig(profile, true)

    if isNew == true then
        local defaultRule = initialRule or {
            actionType = "Spell",
            id = 0,
            creatures = 1,
            minHarmony = 0,
            needTarget = false,
            prioritizeOverPotion = true,
            enabled = true,
            priority = #buildShooterUnifiedRuleRefs(profile) + 1
        }
        window._draftRule = deepCopy(defaultRule)
    else
        local ref = getShooterRuleRefByZeroIndex(zeroIndex)
        if not ref or type(ref.config) ~= "table" then
            window:destroy()
            shooterSettingsPopup = nil
            return
        end

        window._editKind = ref.kind
        window._editSourceIndex = ref.sourceIndex
        window._draftRule = deepCopy(ref.config)
        window._draftRule.actionType = ref.kind == "rune" and "Rune" or "Spell"
    end

    bindShooterSettingsPopupHandlers(window)
    refreshShooterSettingsPopup()

    window:show(true)
    window:raise()
    window:focus()

    window.onDestroy = function()
        if shooterSettingsPopup == window then
            shooterSettingsPopup = nil
        end
    end
    modalEnter(window)
end

function updateMagicShooterCreatures(name, index, creatures)
    local profile = getShooterProfile()
    if not profile then
        return
    end
    local slot = (tonumber(index) or 0) + 1
    if not profile.spells[slot] then
        profile.spells[slot] = ensureShooterSpellRule({}, slot)
    end
    -- creatures ja vem como texto completo da opcao ("0", "1", "1+", "2+", etc)
    local optionText = creatures or "1+"

    -- Se for "0", salvar como 0 (nenhum monstro necessario)
    -- Se for "1" (sem +), salvar como -1 (exato)
    -- Se for "1+" ou outro numero com +, salvar como numero positivo (ou mais)
    if optionText == "0" then
        profile.spells[slot].creatures = 0
    elseif optionText == "1" then
        profile.spells[slot].creatures = -1
    else
        local num = tonumber(optionText:match("%d+"))
        profile.spells[slot].creatures = num or 1
    end
end

