function toggleMagicShooter(widget, message)
    if not widget then
        -- Try to get from shooterPanel or enableButtons
        widget = (shooterPanel and shooterPanel:recursiveGetChildById("enableMagicShooter")) or
            (enableButtons and enableButtons:recursiveGetChildById("enableMagicShooter"))
        if widget then
            widget:setChecked(not widget:isChecked())
        end
    end

    if widget then
        helperConfig.magicShooterEnabled = widget:isChecked()
        modules.game_textmessage.displayGameMessage(
            message and message or
            string.format("OTCaster is %s.", (helperConfig.magicShooterEnabled and "enabled" or "disabled"))
        )
    end

    -- Update tracker window
    if HelperTrackerModule and HelperTrackerModule.updateShooterStatus then
        HelperTrackerModule.updateShooterStatus(helperConfig.magicShooterEnabled)
    end

    -- Update icon stats window
    if IconStatsModule and IconStatsModule.updateShooterIcon then
        IconStatsModule.updateShooterIcon(helperConfig.magicShooterEnabled)
    end

    -- Start/Stop custom spell timer
    if helperConfig.magicShooterEnabled then
        startCustomSpellTimer()
    else
        stopCustomSpellTimer()
    end
end

function isAutoTargetActive()
    return helperConfig.autoTargetEnabled
end

function toggleAutoTarget(widget)
    if not widget then
        widget = targetingPanel:recursiveGetChildById("enableAutoTarget")
        if widget then
            widget:setChecked(not widget:isChecked())
        end
    end
    if widget then
        helperConfig.autoTargetEnabled = widget:isChecked()
    end
    if not helperConfig.autoTargetEnabled then
        if helperConfig.currentLockedTargetId > 0 then
            helperConfig.currentLockedTargetId = 0
        end
        -- Remove target se estiver atacando
        if g_game.getAttackingCreature() then
            g_game.cancelAttack()
        end
    end
    modules.game_textmessage.displayGameMessage(
        string.format("Auto Target is %s.", (helperConfig.autoTargetEnabled and "enabled" or "disabled"))
    )

    -- Update tracker window
    if HelperTrackerModule and HelperTrackerModule.updateTargetStatus then
        HelperTrackerModule.updateTargetStatus(helperConfig.autoTargetEnabled)
    end

    -- Update icon stats window
    if IconStatsModule and IconStatsModule.updateTargetingIcon then
        IconStatsModule.updateTargetingIcon(helperConfig.autoTargetEnabled)
    end
end

