function modules.game_helper.onModulePresetNavigationToggle(moduleType, checked)
    local meta = modulePresetMeta[moduleType]
    if not meta then
        return
    end

    ensureModulePresetConfig(moduleType)
    local selectedName = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
    if selectedName == "" then
        return
    end

    local changed = setModulePresetNavigationEnabled(moduleType, selectedName, checked == true)
    if not changed then
        return
    end

    saveSettings()
    updateModulePresetNavigationToggle(moduleType)
end

function copyModulePresetConfigToCurrent(moduleType, sourcePresetName)
    local meta = modulePresetMeta[moduleType]
    if not meta then
        return
    end

    ensureModulePresetConfig(moduleType)
    local profiles = helperConfig[meta.profilesKey]
    if type(profiles) ~= "table" then
        return
    end

    local sourceName = tostring(sourcePresetName or "")
    local targetName = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
    if sourceName == "" or sourceName == targetName or type(profiles[sourceName]) ~= "table" then
        return
    end

    local targetNavigationEnabled = true
    if type(profiles[targetName]) == "table" then
        targetNavigationEnabled = ensureModulePresetNavigationFlag(profiles[targetName])
    end

    profiles[targetName] = deepCopy(profiles[sourceName])
    setModulePresetNavigationEnabled(moduleType, targetName, targetNavigationEnabled)
    local copiedPreset = profiles[targetName]
    local sourceDisplayName = getModulePresetUiName(moduleType, sourceName)
    local targetDisplayName = getModulePresetUiName(moduleType, targetName)

    if moduleType == "shooter" then
        helperConfig[meta.selectedKey] = targetName
        loadShooterProfileByName(targetName)
        saveSettings()
        if IconStatsModule and IconStatsModule.updateModulePresetTooltip then
            IconStatsModule.updateModulePresetTooltip("shooter")
        end
    else
        modulePresetApplyDepth = (modulePresetApplyDepth or 0) + 1
        local ok, err = pcall(function()
            helperConfig[meta.selectedKey] = targetName
            applyModulePresetData(moduleType, copiedPreset)
            local refreshed = refreshModulePresetUi(moduleType)
            if moduleType == "healing" or not refreshed then
                onLoadHelperData()
            end
            saveSettings()
            if IconStatsModule and IconStatsModule.updateModulePresetTooltip then
                IconStatsModule.updateModulePresetTooltip(moduleType)
            end
        end)
        modulePresetApplyDepth = math.max((modulePresetApplyDepth or 1) - 1, 0)
        if not ok then
            error(err)
        end
    end

    modules.game_textmessage.displayGameMessage(
        string.format("%s preset %s copied to %s.", meta.title, sourceDisplayName, targetDisplayName)
    )
end

function openCopyPresetToCurrentMenu(moduleType, buttonWidget)
    local meta = modulePresetMeta[moduleType]
    if not meta then
        return
    end

    ensureModulePresetConfig(moduleType)
    local currentName = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
    local presetNames = getSortedModulePresetNames(moduleType)
    local menu = g_ui.createWidget('HelperPopupMenu')
    local hasOptions = false

    if buttonWidget and buttonWidget.setImageClip then
        buttonWidget:setImageClip("20 0 20 20")
    end

    menu:addOption(tr("Copy from which preset?"), function()
    end)

    for _, presetName in ipairs(presetNames) do
        if presetName ~= currentName then
            local sourceName = presetName
            menu:addOption(getModulePresetUiName(moduleType, sourceName), function()
                copyModulePresetConfigToCurrent(moduleType, sourceName)
            end)
            hasOptions = true
        end
    end

    if not hasOptions then
        if buttonWidget and buttonWidget.setImageClip then
            buttonWidget:setImageClip("0 0 20 20")
        end
        modules.game_textmessage.displayGameMessage(htr("No other preset available to copy."))
        return
    end

    if buttonWidget and buttonWidget.setImageClip then
        connect(menu, {
            onDestroy = function()
                if buttonWidget and not buttonWidget:isDestroyed() then
                    buttonWidget:setImageClip("0 0 20 20")
                end
            end
        })
    end

    menu:display()
end

