function removeProfile()
    local confirmWindow = nil
    local selectedName = tostring(helperConfig.selectedShooterProfile or getModulePresetSlotName(1))
    local selectedDisplayName = getModulePresetUiName("shooter", selectedName)

    local cancel = function()
        if confirmWindow then
            confirmWindow:destroy()
        end
    end

    local confirm = function()
        if confirmWindow then
            confirmWindow:destroy()
        end

        if type(helperConfig.shooterProfiles) ~= "table" then
            helperConfig.shooterProfiles = {}
        end

        local navigationEnabled = true
        if type(helperConfig.shooterProfiles[selectedName]) == "table" then
            navigationEnabled = ensureModulePresetNavigationFlag(helperConfig.shooterProfiles[selectedName])
        end

        helperConfig.shooterProfiles[selectedName] = createEmptyModulePresetData("shooter")
        setModulePresetNavigationEnabled("shooter", selectedName, navigationEnabled)
        loadShooterProfileByName(selectedName)
        saveSettings()
        modules.game_textmessage.displayGameMessage(string.format("Preset %s cleared.", selectedDisplayName))
    end

    confirmWindow =
        helperDisplayGeneralBox(
            "Clear Preset",
            string.format("Are you sure you want to clear preset %s?", selectedDisplayName),
            {
                { text = tr("No"),  callback = cancel },
                { text = tr("Yes"), callback = confirm },
            },
            yesFunction,
            noFunction
        )
end

function removeModulePresetByType(moduleType)
    local meta = modulePresetMeta[moduleType]
    if not meta then
        return
    end
    ensureModulePresetConfig(moduleType)

    local confirmWindow = nil
    local selectedName = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
    local selectedDisplayName = getModulePresetUiName(moduleType, selectedName)

    local cancel = function()
        if confirmWindow then
            confirmWindow:destroy()
        end
    end

    local confirm = function()
        if confirmWindow then
            confirmWindow:destroy()
        end

        if type(helperConfig[meta.profilesKey]) ~= "table" then
            helperConfig[meta.profilesKey] = {}
        end

        local navigationEnabled = true
        if type(helperConfig[meta.profilesKey][selectedName]) == "table" then
            navigationEnabled = ensureModulePresetNavigationFlag(helperConfig[meta.profilesKey][selectedName])
        end

        helperConfig[meta.profilesKey][selectedName] = createEmptyModulePresetData(moduleType)
        setModulePresetNavigationEnabled(moduleType, selectedName, navigationEnabled)
        loadModulePresetByName(moduleType, selectedName, true)
        saveSettings()
        modules.game_textmessage.displayGameMessage(
            string.format("%s preset %s cleared.", meta.title, selectedDisplayName)
        )
    end

    confirmWindow =
        helperDisplayGeneralBox(
            "Clear Preset",
            string.format("Are you sure you want to clear preset %s?", selectedDisplayName),
            {
                { text = tr("No"),  callback = cancel },
                { text = tr("Yes"), callback = confirm },
            },
            yesFunction,
            noFunction
        )
end

