        return
    end

    local modeDisplay = targetingPanel:recursiveGetChildById("autoTargetModeDisplay")
    if not modeDisplay then
        return
    end

    local modeDescriptions = {
        A = "Mode A - Prioritize closest target",
        B = "Mode B - Prioritize farthest target",
        C = "Mode C - Prioritize target with lowest health",
        D = "Mode D - Prioritize target with highest health",
        E = "Mode E - Prioritize best target for runes (diamond arrows for paladins)",
        F = "Mode F - Attack closest target, prioritizing lowest health",
        G = "Mode G - Prioritize closest target with highest health",
        H = "Mode H - Prioritize farthest target with lowest health",
        I = "Mode I - Prioritize farthest target with highest health",
        J = "Mode J - Chain Mode for Mages",
        K = "Mode K - Chain Mode for Monks"
    }

    modeDisplay:setText(modeDescriptions[mode] or "Mode A - Closest target")
end

function updateTargetModeButtonStates()
    if not targetModeSelector then
        return
    end

    -- Get current mode
    local currentMode = nil
    for k, v in pairs(autoTargetModes) do
        if v == helperConfig.autoTargetMode then
            currentMode = k
            break
        end
    end

    -- Uncheck all buttons first
    local modes = { "A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K" }
    for _, mode in ipairs(modes) do
        local button = targetModeSelector:recursiveGetChildById("mode" .. mode)
        if button then
            button:setChecked(false)
        end
    end

    -- Check the current mode button
    if currentMode then
        local button = targetModeSelector:recursiveGetChildById("mode" .. currentMode)
        if button then
            button:setChecked(true)
        end
    end
end

function openTargetModeSelector()
    if not targetModeSelector then
        local rootWidget = g_ui.getRootWidget()
        if rootWidget then
            targetModeSelector = g_ui.createWidget('TargetModeSelector', rootWidget)
        end
    end

    if targetModeSelector then
        updateTargetModeButtonStates()
        targetModeSelector:show()
        targetModeSelector:raise()
        targetModeSelector:focus()
        modalEnter(targetModeSelector, { inputLock = false })
    end
end

function closeTargetModeSelector()
    if targetModeSelector then
        targetModeSelector:hide()
        modalExit(targetModeSelector)
    end
end

