function updateIgnoredMobs(text)
    if not helperConfig then
        helperConfig = {}
    end

    -- Split the text by comma and trim whitespace
    local ignoredMobs = {}
    if text and text ~= "" then
        for mob in string.gmatch(text, "([^,]+)") do
            local trimmedMob = mob:match("^%s*(.-)%s*$")
            if trimmedMob and trimmedMob ~= "" then
                table.insert(ignoredMobs, trimmedMob:lower())
            end
        end
    end

    helperConfig.ignoredMobs = ignoredMobs
end

function isMobIgnored(mobName)
    if not helperConfig or not helperConfig.ignoredMobs then
        return false
    end

    local lowerMobName = mobName:lower()
    for _, ignoredMob in ipairs(helperConfig.ignoredMobs) do
        if lowerMobName:find(ignoredMob, 1, true) then
            return true
        end
    end

    return false
end

function updatePriorityMobs(text)
    if not helperConfig then
        helperConfig = {}
    end

    -- Split the text by comma and trim whitespace
    local priorityMobs = {}
    if text and text ~= "" then
        for mob in string.gmatch(text, "([^,]+)") do
            local trimmedMob = mob:match("^%s*(.-)%s*$")
            if trimmedMob and trimmedMob ~= "" then
                table.insert(priorityMobs, trimmedMob:lower())
            end
        end
    end

    helperConfig.priorityMobs = priorityMobs
end

function isMobPriority(mobName)
    if not helperConfig or not helperConfig.priorityMobs then
        return false
    end

    local lowerMobName = mobName:lower()
    for _, priorityMob in ipairs(helperConfig.priorityMobs) do
        if lowerMobName:find(priorityMob, 1, true) then
            return true
        end
    end

    return false
end

function modules.game_helper.isPrioritizedTargetCreature(creature)
    if not creature or not helperConfig or helperConfig.autoTargetEnabled ~= true then
        return false
    end

    if creature.isDead and creature:isDead() then
        return false
    end

    local creatureName = creature:getName()
    if not creatureName or creatureName == "" then
        return false
    end

    if helperConfig.prioritizeBoss and isBossName and isBossName(creatureName) then
        return true
    end

    return isMobPriority(creatureName)
end

