-- Attack Position: 1=Do nothing, 2=Chase, 3=Distance, 4=Diagonal
-- Global (não-local) para não estourar o limite de 200 locals do Lua nesse arquivo.
AttackPos = {}
AttackPos.DIR_DELTAS = {
    [Directions.North]     = { dx = 0, dy = -1 },
    [Directions.East]      = { dx = 1, dy = 0 },
    [Directions.South]     = { dx = 0, dy = 1 },
    [Directions.West]      = { dx = -1, dy = 0 },
    [Directions.NorthEast] = { dx = 1, dy = -1 },
    [Directions.SouthEast] = { dx = 1, dy = 1 },
    [Directions.SouthWest] = { dx = -1, dy = 1 },
    [Directions.NorthWest] = { dx = -1, dy = -1 },
}

function AttackPos.tileHasFloorChange(pos)
    if not pos then return false end
    if not CaveBot or not CaveBot.FLOOR_CHANGE_IDS then return false end
    local tile = g_map.getTile(pos)
    if not tile then return false end
    local things = tile:getThings() or {}
    for _, thing in ipairs(things) do
        if thing and thing:isItem() and CaveBot.FLOOR_CHANGE_IDS[thing:getId()] then
            return true
        end
    end
    return false
end

function AttackPos.pathIsSafe(path, startPos, allowLastCreature)
    if not path or #path == 0 or not startPos then return false end
    local cur = { x = startPos.x, y = startPos.y, z = startPos.z }
    local lastIdx = #path
    for i, dir in ipairs(path) do
        local d = AttackPos.DIR_DELTAS[dir]
        if not d then return false end
        cur = { x = cur.x + d.dx, y = cur.y + d.dy, z = cur.z }
        if AttackPos.tileHasFloorChange(cur) then return false end
        -- Bloqueia criaturas no caminho. Tile final permitido só se
        -- allowLastCreature (alvo do attack).
        local tile = g_map.getTile(cur)
        if not tile then return false end
        local creatureBlocks = not tile:isWalkable(false) and tile:isWalkable(true)
        if creatureBlocks then
            local isFinal = (i == lastIdx)
            if not (isFinal and allowLastCreature) then
                return false
            end
        end
    end
    return true
end

-- Tile próximo é fisicamente caminhável agora? (Verifica criaturas, blocking
-- items, etc. — coisas que o pathfinder pode não ter visto antes.)
function AttackPos.tileIsWalkable(pos, allowLastCreature)
    if not pos then return false end
    local tile = g_map.getTile(pos)
    if not tile then return false end
    if tile.isWalkable and not tile:isWalkable(false) then
        if not allowLastCreature then return false end
        -- Se permite criatura no destino, ignora bloqueio causado só por ela
        if tile.isWalkable and not tile:isWalkable(true) then return false end
    end
    return true
end

-- ignoreLastCreature: permite que o tile final do path tenha criatura (alvo).
function AttackPos.tryWalkTo(playerPos, destPos, ignoreLastCreature)
    if not destPos then return false end
    if playerPos.x == destPos.x and playerPos.y == destPos.y and playerPos.z == destPos.z then
        return true
    end
    if not CaveBot or not CaveBot.Map or not CaveBot.Map.findPath then return false end

    local path = CaveBot.Map.findPath(playerPos, destPos, 30, {
        ignoreLastCreature = ignoreLastCreature and true or false,
        precision          = 1,
    })
    if not path or #path == 0 then return false end
    if not AttackPos.pathIsSafe(path, playerPos, ignoreLastCreature) then return false end

    -- Verifica fisicamente o tile do próximo passo (criaturas/blockers que o
    -- pathfinder pode não ter levado em conta) pra evitar "not enough room".
    local d = AttackPos.DIR_DELTAS[path[1]]
    if not d then return false end
    local nextPos = { x = playerPos.x + d.dx, y = playerPos.y + d.dy, z = playerPos.z }
    -- Se for o último passo do path E ignoreLastCreature, permite criatura no destino
    local allowCreature = ignoreLastCreature and #path == 1
    if not AttackPos.tileIsWalkable(nextPos, allowCreature) then return false end

    -- Dead-end avoidance: nenhum passo do path (exceto o destino requisitado)
    -- pode ser dead-end. Como o helper escolhe sozinho onde posicionar, isso
    -- vale também pro destino — não queremos parar num beco.
    if CaveBot and CaveBot.Map and CaveBot.Map.isDeadEnd then
        local cur = { x = playerPos.x, y = playerPos.y, z = playerPos.z }
        for _, sd in ipairs(path) do
            local dd = AttackPos.DIR_DELTAS[sd]
            if not dd then return false end
            local np = { x = cur.x + dd.dx, y = cur.y + dd.dy, z = cur.z }
            if CaveBot.Map.isDeadEnd(np, cur, 2) then return false end
            cur = np
        end
    end

    g_game.walk(path[1], false)
    return true
end

function checkAttackPosition()
    -- Only use attack position if helper is enabled and targeting is enabled
    if not hotkeyHelperStatus then return end
    if not helperConfig or not helperConfig.autoTargetEnabled then return end

    local player = g_game.getLocalPlayer()
    if not player then return end

    local mode = helperConfig.attackPosition or 1
    if mode == 1 then return end -- Do nothing

    -- Cede prioridade ao cavebot enquanto ele está conduzindo o personagem
    if CaveBot and CaveBot.isWalking and CaveBot.isWalking() then return end

    -- Must be attacking something
    local target = g_game.getAttackingCreature()
    if not target then return end
    if target:isDead() then return end

    local playerPos = player:getPosition()
    local targetPos = target:getPosition()
    if not playerPos or not targetPos then return end
    if playerPos.z ~= targetPos.z then return end

    -- Don't move while walking
    if player:isWalking() then return end

    local dx = targetPos.x - playerPos.x
    local dy = targetPos.y - playerPos.y
    local dist = math.max(math.abs(dx), math.abs(dy))

    -- Fallback: walk cru (usado quando cavebot/pathfinder indisponível).
    -- Bloqueia step direto em floor-change/teleport.
    local function walkTowardRaw(tox, toy)
        local sdx = tox - playerPos.x
        local sdy = toy - playerPos.y
        if sdx > 0 then sdx = 1 elseif sdx < 0 then sdx = -1 end
        if sdy > 0 then sdy = 1 elseif sdy < 0 then sdy = -1 end
        local dir = nil
        if sdx == 0 and sdy == -1 then
            dir = Directions.North
        elseif sdx == 1 and sdy == -1 then
            dir = Directions.NorthEast
        elseif sdx == 1 and sdy == 0 then
            dir = Directions.East
        elseif sdx == 1 and sdy == 1 then
            dir = Directions.SouthEast
        elseif sdx == 0 and sdy == 1 then
            dir = Directions.South
        elseif sdx == -1 and sdy == 1 then
            dir = Directions.SouthWest
        elseif sdx == -1 and sdy == 0 then
            dir = Directions.West
        elseif sdx == -1 and sdy == -1 then
            dir = Directions.NorthWest
        end
        if dir then
            local nextPos = { x = playerPos.x + sdx, y = playerPos.y + sdy, z = playerPos.z }
            if AttackPos.tileHasFloorChange(nextPos) then return end
            if not AttackPos.tileIsWalkable(nextPos, false) then return end
            g_game.walk(dir, false)
        end
    end

    -- Tenta uma lista ordenada de tiles candidatos via pathfinding; se nenhum
    -- passar, cai no walk cru em direção ao fallbackTarget.
    local function tryCandidates(candidates, fallbackTarget, ignoreLastCreature)
        for _, c in ipairs(candidates) do
            if AttackPos.tryWalkTo(playerPos, c, ignoreLastCreature) then return true end
        end
        if fallbackTarget then
            walkTowardRaw(fallbackTarget.x, fallbackTarget.y)
        end
        return false
    end

    -- Mode 2: Chase (follow target, get adjacent)
    if mode == 2 then
        if dist > 1 then
            -- Tenta a tile do monstro primeiro (com ignoreLastCreature) e, se
            -- não houver path (parede no meio, monstro do outro lado), tenta o
            -- anel de tiles adjacentes ao alvo, ordenados por proximidade.
            local cand = { targetPos }
            local ring = {}
            for ox = -1, 1 do
                for oy = -1, 1 do
                    if not (ox == 0 and oy == 0) then
                        local p = { x = targetPos.x + ox, y = targetPos.y + oy, z = targetPos.z }
                        local d = math.max(math.abs(p.x - playerPos.x), math.abs(p.y - playerPos.y))
                        table.insert(ring, { pos = p, d = d })
                    end
                end
            end
            table.sort(ring, function(a, b) return a.d < b.d end)
            for _, e in ipairs(ring) do table.insert(cand, e.pos) end
            tryCandidates(cand, targetPos, true)
        end

        -- Mode 3: Distance (keep X sqms from creature)
    elseif mode == 3 then
        local desiredDist = helperConfig.attackDistance or 1
        if dist == desiredDist then return end

        if dist > desiredDist then
            -- Aproxima: anel de tiles a `desiredDist` do alvo, ordenado por
            -- proximidade do player.
            local cand = {}
            for ox = -desiredDist, desiredDist do
                for oy = -desiredDist, desiredDist do
                    if math.max(math.abs(ox), math.abs(oy)) == desiredDist then
                        local p = { x = targetPos.x + ox, y = targetPos.y + oy, z = targetPos.z }
                        local d = math.max(math.abs(p.x - playerPos.x), math.abs(p.y - playerPos.y))
                        table.insert(cand, { pos = p, d = d })
                    end
                end
            end
            table.sort(cand, function(a, b) return a.d < b.d end)
            local list = {}
            for _, e in ipairs(cand) do table.insert(list, e.pos) end
            tryCandidates(list, targetPos)
        else
            -- Recua: vizinhos do player que aumentem a distância para o alvo.
            local cand = {}
            for ddx = -1, 1 do
                for ddy = -1, 1 do
                    if not (ddx == 0 and ddy == 0) then
                        local p = { x = playerPos.x + ddx, y = playerPos.y + ddy, z = playerPos.z }
                        local nd = math.max(math.abs(p.x - targetPos.x), math.abs(p.y - targetPos.y))
                        if nd > dist then
                            table.insert(cand, { pos = p, d = -nd })
                        end
                    end
                end
            end
            table.sort(cand, function(a, b) return a.d < b.d end)
            local list = {}
            for _, e in ipairs(cand) do table.insert(list, e.pos) end
            local awayX = playerPos.x + (playerPos.x - targetPos.x)
            local awayY = playerPos.y + (playerPos.y - targetPos.y)
            tryCandidates(list, { x = awayX, y = awayY })
        end

        -- Mode 4: Diagonal (stay on creature diagonal at configured distance)
    elseif mode == 4 then
        local desiredDist = helperConfig.attackDistance or 1
        local isDiag = math.abs(dx) == math.abs(dy) and math.abs(dx) == desiredDist
        if not isDiag then
            local diags = {
                { x = targetPos.x - desiredDist, y = targetPos.y - desiredDist, z = targetPos.z },
                { x = targetPos.x + desiredDist, y = targetPos.y - desiredDist, z = targetPos.z },
                { x = targetPos.x - desiredDist, y = targetPos.y + desiredDist, z = targetPos.z },
                { x = targetPos.x + desiredDist, y = targetPos.y + desiredDist, z = targetPos.z },
            }
            table.sort(diags, function(a, b)
                local da = math.abs(playerPos.x - a.x) + math.abs(playerPos.y - a.y)
                local db = math.abs(playerPos.x - b.x) + math.abs(playerPos.y - b.y)
                return da < db
            end)
            tryCandidates(diags, diags[1])
        end
    end
end

eventTable.checkAttackPosition.action = checkAttackPosition

local function printArea(area)
    for _, row in ipairs(area) do
        local line = ""
        for _, value in ipairs(row) do
            line = line .. tostring(value) .. " "
        end
    end
end

-- Weak-keyed cache of rotated areas. Each spell's area grid is hashed by
-- table identity; rotations are computed once per (area, direction) and
-- reused across all subsequent shooter ticks. Weak keys let unreferenced
-- areas (e.g., after spell reload) be GC'd naturally.
_G._areaRotationCache = _G._areaRotationCache or setmetatable({}, { __mode = "k" })

local function rotateArea(area, direction)
    local rotatedArea = {}

    if not area or type(area) ~= "table" or #area == 0 then
        return {}
    end

    -- Cache hit?
    local perArea = _G._areaRotationCache[area]
    if perArea and perArea[direction] then
        return perArea[direction]
    end

    local rows = #area
    local cols = area[1] and #area[1] or 0

    if direction == Directions.North then
        rotatedArea = area
    elseif direction == Directions.South then
        for y = 1, rows do
            rotatedArea[y] = {}
            for x = 1, cols do
                rotatedArea[y][x] = area[rows - y + 1][cols - x + 1]
            end
        end
    elseif direction == Directions.East then
        for x = 1, cols do
            rotatedArea[x] = {}
            for y = 1, rows do
                rotatedArea[x][y] = area[rows - y + 1][x]
            end
        end
    elseif direction == Directions.West then
        for x = 1, cols do
            rotatedArea[x] = {}
            for y = 1, rows do
                rotatedArea[x][y] = area[y][cols - x + 1]
            end
        end
    end

    -- Store in cache for subsequent ticks.
    if not perArea then
        perArea = {}
        _G._areaRotationCache[area] = perArea
    end
    perArea[direction] = rotatedArea

    return rotatedArea
end

local function findPlayerPosition(area)
    for y, row in ipairs(area) do
        for x, value in ipairs(row) do
            if value == 3 or value == 2 then
                return x, y
            end
        end
    end
    return nil, nil
end

local function isFirstTileWaveAnchor(grid, anchorX, anchorY, castDirection)
    if not grid or not anchorX or not anchorY then
        return false
    end
    if not (grid[anchorY] and grid[anchorY][anchorX] == 3) then
        return false
    end

    local behindDx, behindDy = 0, 0
    if castDirection == Directions.North then
        behindDy = 1
    elseif castDirection == Directions.South then
        behindDy = -1
    elseif castDirection == Directions.East then
        behindDx = -1
    elseif castDirection == Directions.West then
        behindDx = 1
    end

    local behindRow = grid[anchorY + behindDy]
    local behindValue = behindRow and behindRow[anchorX + behindDx] or nil

    -- Case 1: Nothing behind (nil) → '3' is first spell tile, apply offset
    if behindValue == nil then
        return true
    end

    -- Case 2: 1 behind → '3' is in the middle of effect (like Berserk), no offset
    if behindValue == 1 then
        return false
    end

    -- Case 3: 0 behind → check if '3' is surrounded by 0s
    -- If surrounded by 0s → '3' is player position, no offset
    -- If has adjacent 1s → '3' is first spell tile, apply offset
    if behindValue == 0 then
        local hasAdjacentOne = false
        for dy = -1, 1 do
            for dx = -1, 1 do
                if not (dx == 0 and dy == 0) then
                    local checkRow = grid[anchorY + dy]
                    local checkValue = checkRow and checkRow[anchorX + dx] or nil
                    if checkValue == 1 then
                        hasAdjacentOne = true
                        break
                    end
                end
            end
            if hasAdjacentOne then break end
        end
        -- Has adjacent 1s → first spell tile, apply offset
        -- Surrounded by 0s/nil → player position, no offset
        return hasAdjacentOne
    end

    return false
end

local function isWaveLikeGrid(area)
    if not area or type(area) ~= "table" or #area == 0 then
        return false
    end
    local cols = area[1] and #area[1] or 0
    if cols == 0 then
        return false
    end

    local anchorX, anchorY = findPlayerPosition(area)
    if not anchorX or not anchorY then
        return false
    end
    if not (area[anchorY] and area[anchorY][anchorX] == 3) then
        return false
    end

    local adjacentOnes = 0
    for dy = -1, 1 do
        for dx = -1, 1 do
            if not (dx == 0 and dy == 0) then
                local row = area[anchorY + dy]
                local v = row and row[anchorX + dx] or nil
                if v == 1 then
                    adjacentOnes = adjacentOnes + 1
                end
            end
        end
    end

    -- Only consider it "not wave" when the anchor is fully surrounded (8 adjacent tiles marked as 1).
    -- Everything else is treated as wave-like for auto-turning decisions.
    return adjacentOnes ~= 8
end

function getRelativePosition(targetPos)
    local player = g_game.getLocalPlayer()
    if not player then
        return targetPos
    end
    local playerPos = player:getPosition()

    local relativePos = { x = targetPos.x, y = targetPos.y, z = targetPos.z }
    if playerPos.x < targetPos.x and playerPos.y < targetPos.y then
        relativePos.x = relativePos.x - 1
        relativePos.y = relativePos.y - 1
    elseif (playerPos.x < targetPos.x and playerPos.y > targetPos.y) or playerPos.x < targetPos.x then
        relativePos.x = relativePos.x - 1
    elseif (playerPos.x > targetPos.x and playerPos.y < targetPos.y) or playerPos.y < targetPos.y then
        relativePos.y = relativePos.y - 1
    end
    return relativePos
end

local function countAttackableCreatures(casterPos, direction, area, creatureList, ranged, drawDebug)
    if direction == Directions.SouthEast or direction == Directions.NorthEast then
        direction = Directions.East
    elseif direction == Directions.SouthWest or direction == Directions.NorthWest then
        direction = Directions.West
    end
    area = rotateArea(area, direction)
    local playerX, playerY = findPlayerPosition(area)
    if not playerX or not playerY then
        return 0
    end

    local waveLike = (not ranged) and isFirstTileWaveAnchor(area, playerX, playerY, direction)
    local offsetX, offsetY = 0, 0
    if waveLike then
        if direction == Directions.North then
            offsetY = -1
        elseif direction == Directions.South then
            offsetY = 1
        elseif direction == Directions.East then
            offsetX = 1
        elseif direction == Directions.West then
            offsetX = -1
        end
    end

    -- Build the absolute world-pos list of tiles the spell covers in this
    -- rotation. The native counts creatures + checks line-of-sight in one
    -- pass, eliminating the per-tile Lua↔C++ isSightClear round-trips that
    -- dominated the shooter hot path.
    --
    -- Pooled allocations: shooter runs at ~10 Hz × 4 dirs × N spells, so each
    -- raw `{}` here was ~16 outer arrays/sec + ~480 position tables/sec
    -- becoming GC fodder. Pulling them from TablePool keeps the same backing
    -- storage alive across cycles → cuts GC pressure in active hunt by a lot.
    local areaTiles = TablePool.getArray()
    for yOffset, row in ipairs(area) do
        for xOffset, value in ipairs(row) do
            if value == 1 or (waveLike and value == 3) or (ranged and (value == 3 or value == 2)) then
                local position = TablePool.getPosition()
                position.x = casterPos.x + (xOffset - playerX) + offsetX
                position.y = casterPos.y + (yOffset - playerY) + offsetY
                position.z = casterPos.z
                areaTiles[#areaTiles + 1] = position

                if SHOOTER_DEBUG and drawDebug then
                    local foundCreature = false
                    if creatureList then
                        for _, creature in ipairs(creatureList) do
                            if positionCompare(creature.position, position) then
                                foundCreature = true
                                break
                            end
                        end
                    end
                    createShooterDebugWidget(position, foundCreature, drawDebug)
                end
            end
        end
    end

    if #areaTiles == 0 or not creatureList or #creatureList == 0 then
        -- Release pooled positions + outer array before bailing.
        for i = 1, #areaTiles do TablePool.releasePosition(areaTiles[i]) end
        TablePool.releaseArray(areaTiles)
        return 0
    end

    local result
    if g_map.countCreaturesInSpellArea then
        -- creaturePositions is just an array of REFS to existing CreatureCache
        -- entry positions — pool only the outer array; the positions themselves
        -- belong to someone else and must not be released here.
        local creaturePositions = TablePool.getArray()
        for i = 1, #creatureList do
            local c = creatureList[i]
            if c and c.position then
                creaturePositions[#creaturePositions + 1] = c.position
            end
        end
        result = g_map.countCreaturesInSpellArea(casterPos, areaTiles, creaturePositions)
        TablePool.releaseArray(creaturePositions)
    else
        -- Fallback for clients that predate the native binding.
        result = 0
        for _, position in ipairs(areaTiles) do
            for _, creature in ipairs(creatureList) do
                if positionCompare(creature.position, position) then
                    if g_map.isSightClear(casterPos, creature.position) then
                        result = result + 1
                    end
                    break
                end
            end
        end
    end

    -- Release the position tables we built (these were freshly allocated above,
    -- so we own them and must give them back).
    for i = 1, #areaTiles do TablePool.releasePosition(areaTiles[i]) end
    TablePool.releaseArray(areaTiles)
    return result
end

-- Count creatures with separate tracking for ranged monsters (>3 tiles away)
local function countAttackableCreaturesWithRangedPriority(casterPos, direction, area, creatureList, ranged,
                                                          prioritizeRanged)
    local origDir = direction
    if direction == Directions.SouthEast or direction == Directions.NorthEast then
        direction = Directions.East
    elseif direction == Directions.SouthWest or direction == Directions.NorthWest then
        direction = Directions.West
    end
    local area = rotateArea(area, direction)
    local totalCreatures = 0
    local rangedCreaturesCount = 0
    local playerX, playerY = findPlayerPosition(area)
    if not playerX or not playerY then
        return 0, 0
    end

    local waveLike = (not ranged) and isFirstTileWaveAnchor(area, playerX, playerY, direction)

    local offsetX, offsetY = 0, 0
    if waveLike then
        if direction == Directions.North then
            offsetY = -1
        elseif direction == Directions.South then
            offsetY = 1
        elseif direction == Directions.East then
            offsetX = 1
        elseif direction == Directions.West then
            offsetX = -1
        end
    end

    for yOffset, row in ipairs(area) do
        for xOffset, value in ipairs(row) do
            if value == 1 or (waveLike and value == 3) or (ranged and (value == 3 or value == 2)) then
                local position = {
                    x = casterPos.x + (xOffset - playerX) + offsetX,
                    y = casterPos.y + (yOffset - playerY) + offsetY,
                    z = casterPos.z
                }
                for _, creature in ipairs(creatureList) do
                    if positionCompare(creature.position, position) then
                        local hasSight = g_map.isSightClear(casterPos, creature.position)
                        if hasSight then
                            totalCreatures = totalCreatures + 1
                            -- Check if this creature is marked as ranged
                            local creatureId = creature.creature:getId()
                            if rangedCreatures[creatureId] then
                                rangedCreaturesCount = rangedCreaturesCount + 1
                            end
                        end
                        break
                    end
                end
            end
        end
    end

    -- If prioritizing ranged and we have ranged creatures, weight them heavily
    if prioritizeRanged and rangedCreaturesCount > 0 then
        return rangedCreaturesCount * 10 + totalCreatures, rangedCreaturesCount
    end

    return totalCreatures, rangedCreaturesCount
end

local function sortMagicShooterByPriority(list)
    table.sort(
        list,
        function(a, b)
            if a.config.priority and b.config.priority then
                return a.config.priority < b.config.priority
            else
                return false
            end
        end
    )

    local player = g_game.getLocalPlayer()
    if not player then
        return list
    end

    local harmonyCount = 0
    if player and player.getHarmony then
        harmonyCount = player:getHarmony() or 0
    end
    if harmonyCount >= 5 then
        local spenderIndex = nil
        for i, item in ipairs(list) do
            if item.spell and item.spell.spender then
                spenderIndex = i
                break
            end
        end

        if spenderIndex then
            local spenderSpell = table.remove(list, spenderIndex)
            table.insert(list, 1, spenderSpell)
        end
    end
    return list
end

local function findBestTarget(position, direction, area, creatureList, minCreatures)
    if not area or type(area) ~= "table" or #area == 0
        or not creatureList or #creatureList == 0 then
        return nil, 0
    end

    -- Normalize direction the same way countAttackableCreatures does so the
    -- rotated area cache hits are shared between both code paths.
    local dir = direction
    if dir == Directions.SouthEast or dir == Directions.NorthEast then
        dir = Directions.East
    elseif dir == Directions.SouthWest or dir == Directions.NorthWest then
        dir = Directions.West
    end
    local rotated = rotateArea(area, dir)
    local playerX, playerY = findPlayerPosition(rotated)
    if not playerX or not playerY then
        return nil, 0
    end

    -- Ranged mode: cells with value 1, 2 or 3 all count; waveLike disabled.
    -- areaOffsets contains fresh position deltas — pool everything.
    local areaOffsets = TablePool.getArray()
    for yOffset, row in ipairs(rotated) do
        for xOffset, value in ipairs(row) do
            if value == 1 or value == 2 or value == 3 then
                local off = TablePool.getPosition()
                off.x = xOffset - playerX
                off.y = yOffset - playerY
                off.z = 0
                areaOffsets[#areaOffsets + 1] = off
            end
        end
    end
    if #areaOffsets == 0 then
        for i = 1, #areaOffsets do TablePool.releasePosition(areaOffsets[i]) end
        TablePool.releaseArray(areaOffsets)
        return nil, 0
    end

    -- Numeric iteration: deterministic order, indices stay aligned for both
    -- candidate lists. All three arrays are pooled (outer only — the Position
    -- refs inside come from CreatureCache and must not be released here).
    local candidatePositions = TablePool.getArray()
    local candidateCreatures = TablePool.getArray()
    local creaturePositions = TablePool.getArray()
    for i = 1, #creatureList do
        local creatureInfo = creatureList[i]
        if creatureInfo and creatureInfo.creature and creatureInfo.position then
            candidatePositions[#candidatePositions + 1] = creatureInfo.position
            candidateCreatures[#candidateCreatures + 1] = creatureInfo.creature
            creaturePositions[#creaturePositions + 1] = creatureInfo.position
        end
    end
    if #candidatePositions == 0 then
        for i = 1, #areaOffsets do TablePool.releasePosition(areaOffsets[i]) end
        TablePool.releaseArray(areaOffsets)
        TablePool.releaseArray(candidatePositions)
        TablePool.releaseArray(candidateCreatures)
        TablePool.releaseArray(creaturePositions)
        return nil, 0
    end

    if g_map.findBestSpellTarget then
        -- Native: builds the creature hash-set ONCE and tests every candidate
        -- caster against it. Eliminates the O(N²) Lua loop when scoring N
        -- potential targets against N creatures.
        local bestIdx, bestCount = g_map.findBestSpellTarget(
            candidatePositions, areaOffsets, creaturePositions, minCreatures)
        local target = nil
        if bestIdx and bestIdx >= 0 then
            target = candidateCreatures[bestIdx + 1]
        end
        for i = 1, #areaOffsets do TablePool.releasePosition(areaOffsets[i]) end
        TablePool.releaseArray(areaOffsets)
        TablePool.releaseArray(candidatePositions)
        TablePool.releaseArray(candidateCreatures)
        TablePool.releaseArray(creaturePositions)
        return target, bestCount or 0
    end

    -- Fallback for clients that predate the native binding.
    local bestTarget = nil
    local maxCreaturesHit = 0
    for i = 1, #creatureList do
        local creatureInfo = creatureList[i]
        if creatureInfo and creatureInfo.creature and creatureInfo.position then
            local creaturesHit = countAttackableCreatures(creatureInfo.position, direction, area, creatureList, true)
            if creaturesHit >= minCreatures and creaturesHit > maxCreaturesHit then
                maxCreaturesHit = creaturesHit
                bestTarget = creatureInfo.creature
            end
        end
    end
    -- Release pooled arrays from the build phase before returning via fallback.
    for i = 1, #areaOffsets do TablePool.releasePosition(areaOffsets[i]) end
    TablePool.releaseArray(areaOffsets)
    TablePool.releaseArray(candidatePositions)
    TablePool.releaseArray(candidateCreatures)
    TablePool.releaseArray(creaturePositions)
    return bestTarget, maxCreaturesHit
end

-- Helper functions for spell area analysis
local function isDiagonalDirection(direction)
    return direction == Directions.NorthEast or direction == Directions.SouthEast or
        direction == Directions.SouthWest or direction == Directions.NorthWest
end

local function getSpellAreaType(spellId)
    -- exori gran (Fierce Berserk, id 105): on KoliseuOT the Titan Knight hits a 5x5
    -- (AREA_SQUARE2X2) while base/elite knights hit a 3x3. The wire only carries the
    -- client-id vocation (Elite == Titan == 11), so use the real vocation id learned
    -- via extended opcode 206 to upgrade the cached 3x3 to a 5x5 for Titans.
    if spellId == 105 and helperRealVocationId == TITAN_KNIGHT_VOCATION_ID then
        return "simple", SpellAreas.AREA_SQUARE2X2
    end

    local areas = loadSpellAreas()
    local areaData = areas[spellId]

    if not areaData then
        return "none", nil -- Single-target spell
    end

    -- Check if multi-directional (array of objects with name/grid)
    if type(areaData) == "table" and areaData[1] and type(areaData[1]) == "table" then
        if areaData[1].name and areaData[1].grid then
            return "directional", areaData -- Wave/beam spell
        else
            return "simple", areaData      -- Simple area spell
        end
    end

    return "none", nil
end

local function selectAreaForDirection(areaData, direction)
    -- areaData: [1] = diagonal areas, [2] = cardinal areas
    if isDiagonalDirection(direction) then
        return areaData[1] and areaData[1].grid or nil
    else
        return areaData[2] and areaData[2].grid or nil
    end
end

local function findBestDirectionForSpell(playerPos, areaData, creatureList, minCreatures)
    local bestDirection = nil
    local bestCount = 0

    -- Only test cardinal directions (N, E, S, W) - no spell uses diagonal directions
    local directionsToTest = {
        Directions.North, Directions.East, Directions.South, Directions.West
    }

    local dirNames = {
        [Directions.North] = "North",
        [Directions.East] = "East",
        [Directions.South] = "South",
        [Directions.West] = "West"
    }

    if SHOOTER_DEBUG then
        -- Clear previous debug widgets before testing new directions
        clearShooterDebugWidgets()
        print("[SHOOTER DEBUG] === Testing directions for best spell cast ===")
        print(string.format("[SHOOTER DEBUG] Player pos: (%d, %d, %d)", playerPos.x, playerPos.y, playerPos.z))
        print(string.format("[SHOOTER DEBUG] Creatures in list: %d", creatureList and #creatureList or 0))
    end

    -- Test all directions and draw debug widgets for ALL directions (with different colors)
    for _, dir in ipairs(directionsToTest) do
        local area = selectAreaForDirection(areaData, dir)

        if SHOOTER_DEBUG then
            print(string.format("[SHOOTER DEBUG]   %s: area=%s",
                dirNames[dir] or "Unknown",
                area and "VALID" or "NIL"))
        end

        if area then
            -- Count creatures AND draw debug widgets (pass direction for color-coding)
            local success, count = pcall(function()
                return countAttackableCreatures(playerPos, dir, area, creatureList, false, dir)
            end)

            if not success then
                if SHOOTER_DEBUG then
                    print(string.format("[SHOOTER DEBUG]     -> ERROR: %s", tostring(count)))
                end
                count = 0
            else
                if SHOOTER_DEBUG then
                    print(string.format("[SHOOTER DEBUG]     -> Found %d monsters", count))
                end
            end

            if count > bestCount then
                bestCount = count
                bestDirection = dir
            end
        end
    end

    if SHOOTER_DEBUG then
        print(string.format("[SHOOTER DEBUG] RESULT: %s with %d monsters (min: %d)",
            bestDirection and dirNames[bestDirection] or "NONE", bestCount, minCreatures))
        print("[SHOOTER DEBUG] ========================================")
        -- Schedule auto-clear of debug widgets after 1 second
        scheduleDebugWidgetsClear()
    elseif SHOOTER_DEBUG then
        print(string.format("[SHOOTER DEBUG] RESULT: NONE with %d monsters (min: %d)", bestCount, minCreatures))
        print("[SHOOTER DEBUG] ========================================")
    end

    return bestDirection, bestCount
end

-- Find best direction prioritizing ranged creatures (monsters >3 tiles away)
local function findBestDirectionWithRangedPriority(playerPos, areaData, creatureList, minCreatures, prioritizeRanged)
    local bestDirection = nil
    local bestScore = 0
    local bestRangedCount = 0

    -- Only test cardinal directions (N, E, S, W)
    local directionsToTest = {
        Directions.North, Directions.East, Directions.South, Directions.West
    }

    for _, dir in ipairs(directionsToTest) do
        local area = selectAreaForDirection(areaData, dir)
        if area then
            -- Count creatures with ranged priority
            local score, rangedCount = countAttackableCreaturesWithRangedPriority(playerPos, dir, area, creatureList,
                false, prioritizeRanged)
            if score > bestScore then
                bestScore = score
                bestDirection = dir
                bestRangedCount = rangedCount
            end
        end
    end

    -- Convert weighted score back to actual creature count
    local actualCount = bestScore
    if prioritizeRanged and bestRangedCount > 0 then
        actualCount = (bestScore - bestRangedCount * 10) + bestRangedCount
    end

    return bestDirection, actualCount, bestRangedCount
end

function isSpellOnCooldown(spell)
    -- Reactive mode: gate on the server-authoritative registry with ping
    -- prediction and inflight locks (see cast_timing.lua). The legacy tables
    -- below keep being fed either way (UI overlays read them).
    if CastTiming.isActive() then
        return CastTiming.isSpellBlocked(spell)
    end

    if getSpellCooldown(spell.id) >= g_clock.millis() then
        return true
    end

    if type(spell.group) == "table" then
        for group, _ in pairs(spell.group) do
            if getGroupSpellCooldown(group) >= g_clock.millis() then
                return true
            end
        end
    else
        if getGroupSpellCooldown(spell.group) >= g_clock.millis() then
            return true
        end
    end

    return false
end

