    end

    local function getHealPercent(memberVoc, memberName)
        if not memberVoc or memberVoc == 0 then
            return 90
        end

        local vocationPercents = helperConfig.uhhealingVocationPercent or {}
        local percent = vocationPercents[tostring(memberVoc)]

        if percent and percent > 0 then
            return percent
        end

        return 90
    end

    -- OPTIMIZATION: Use pre-indexed hashmap for O(1) friend lookup
    local friendsMap = getUhFriendHealMap()
    local hasFriends = next(friendsMap) ~= nil

    -- OPTIMIZATION: Use CreatureCache instead of getSpectators
    local candidates = {}
    local cachedPlayers = CreatureCache.getPlayers()
    for _, entry in ipairs(cachedPlayers) do
        if entry.creature:getId() ~= localPlayer:getId() then
            local shouldHeal = false

            -- Verificar se está na lista de amigos (O(1) hashmap lookup)
            if hasFriends then
                shouldHeal = friendsMap[entry.creature:getName():lower()] or false
            else
                shouldHeal = shouldHealPlayer(entry.creature)
            end

            if shouldHeal then
                local health = entry.creature:getHealthPercent()
                if health > 0 and health < 100 then
                    local memberVoc = getMemberVocation(entry.creature)
                    local healPercent = getHealPercent(memberVoc, entry.creature:getName())

                    if health <= healPercent then
                        local priority = 1
                        if helperConfig.uhhealingVocationPriority then
                            priority = helperConfig.uhhealingVocationPriority[tostring(memberVoc)] or 1
                        end

                        table.insert(candidates, {
                            creature = entry.creature,
                            health = health,
                            priority = priority,
                            vocation = memberVoc
                        })
                    end
                end
            end
        end
    end

    -- Ordenar por prioridade e HP
    if #candidates > 0 then
        table.sort(candidates, function(a, b)
            if a.priority ~= b.priority then
                return a.priority < b.priority
            end
            return a.health < b.health
        end)

        -- Usar UH no primeiro candidato
        local target = candidates[1].creature
        if target then
            g_game.useInventoryItemWith(uhRuneId, target)
            CastTiming.noteRuneCastSent(Spells.getRuneSpellByItem and Spells.getRuneSpellByItem(uhRuneId) or nil)
        end
    end
end

local lastHaste = 0
local lastCureParalyze = 0
function checkAutoHaste()
    if not hotkeyHelperStatus then
        return
    end
    local localPlayer = g_game.getLocalPlayer()
    if not localPlayer then
        return true
    end

    local isParalyzed = bit.band(localPlayer:getStates(), PlayerStates.Paralyze) > 0
    if isParalyzed then
        local cureConfig = helperConfig.cureParalyze and helperConfig.cureParalyze[1]
        if cureConfig and cureConfig.enabled and cureConfig.id > 0 then
            local cureSpell = Spells.getSpellByClientId(cureConfig.id)
            if cureSpell and cureSpell.id ~= 0 and cureSpell.words then
                local currentMillis = g_clock.millis()
                local cooldown = cureSpell.exhaustion or 1000
                if currentMillis - lastCureParalyze >= cooldown then
                    g_game.talk(cureSpell.words, true)
                    CastTiming.noteSpellCastSent(cureSpell)
                    lastCureParalyze = currentMillis
                end
            end
        end
        return true
    end

    local hasteConfig = helperConfig.haste and helperConfig.haste[1]
    if not hasteConfig then
        return true
    end

    local spellId = hasteConfig.id
    if spellId == 0 then
        return true
    end

    local spell = Spells.getSpellByClientId(spellId)
    if not spell or spell.id == 0 then
        return true
    end

    if not hasteConfig.enabled then
        return true
    end

    -- Check PZ: if safecast is false (unchecked), don't cast in PZ
    -- if safecast is true (checked), allow casting in PZ
    if not hasteConfig.safecast and bit.band(localPlayer:getStates(), PlayerStates.Pz) > 0 then
        return true
    end

    if not checkHealthPriority() then
        return
    end

    -- Verificar se o player tem o efeito de haste ativo
    local hasHaste = bit.band(localPlayer:getStates(), PlayerStates.Haste) > 0

    -- Se mudou a spell configurada, lançar imediatamente
    if spellId ~= lastSpellId then
        lastSpellId = spellId
        g_game.talk(spell.words, true)
        CastTiming.noteSpellCastSent(spell)
        lastHaste = g_clock.millis()
        return
    end

    -- Se já tem haste ativo, não precisa renovar
    if hasHaste then
        return
    end

    -- Se não tem haste ativo, verificar cooldown antes de lançar
    local currentMillis = g_clock.millis()
    local cooldown = spell.exhaustion or 1000
    local nextTime = lastHaste + cooldown

    -- Se ainda está em cooldown, aguardar
    if currentMillis < nextTime then
        return
    end

    -- Lançar a spell de haste
    g_game.talk(spell.words, true)
    CastTiming.noteSpellCastSent(spell)

    lastHaste = currentMillis
end

eventTable.checkAutoHaste.action = checkAutoHaste

local lastBlessDialogData = nil

function onUpdateBlessDialog(data)
    -- Armazenar dados do BlessDialog para uso no icone de blessings
    lastBlessDialogData = data

    -- A funcao original do modulo game_blessing sera chamada automaticamente
    -- pelo sistema de eventos, entao nao precisamos chamar manualmente

    -- Atualizar icone de blessings no inventario (com protecao)
    pcall(updateBlessingsIcon)
end

function onBlessingsChange(blessings, oldBlessings)
    -- Atualizar icone de blessings quando mudar (com protecao)
    pcall(updateBlessingsIcon)
end

function updateBlessingsIcon()
    local success, err = pcall(function()
        local localPlayer = g_game.getLocalPlayer()
        if not localPlayer then
            return
        end

        local blessingCount = 0

        -- Usar dados do BlessDialogData se disponivel (mais preciso)
        if lastBlessDialogData and lastBlessDialogData.blesses then
            -- Contar todas as 8 blessings
            for i = 1, 8 do
                local blessData = lastBlessDialogData.blesses[i]
                if blessData then
                    local totalCount = (blessData.playerBlessCount or 0) + (blessData.store or 0)
                    if totalCount >= 1 then
                        blessingCount = blessingCount + 1
                    end
                end
            end
        else
            -- Fallback: usar valor bitwise
            local blessings = localPlayer:getBlessings()
            if blessings then
                local blessingList = {
                    { bit = 1,   name = "Adventurer" },
                    { bit = 2,   name = "Spiritual Shielding" },
                    { bit = 4,   name = "Embrace of Tibia" },
                    { bit = 8,   name = "Fire of Suns" },
                    { bit = 16,  name = "Wisdom of Solitude" },
                    { bit = 32,  name = "Spark of Phoenix" },
                    { bit = 64,  name = "Blessing 7" },
                    { bit = 128, name = "Blessing 8" }
                }

                for _, bless in ipairs(blessingList) do
                    if bit and bit.band and bit.band(blessings, bless.bit) > 0 then
                        blessingCount = blessingCount + 1
                    end
                end
            end
        end

        -- Determinar qual imagem usar baseado no numero de blessings
        local imagePath = "/images/inventory/button_blessings_grey"
        if blessingCount >= 5 then
            -- Verde para 5+ blessings
            imagePath = "/images/inventory/button_blessings_green"
        elseif blessingCount >= 1 then
            -- Amarelo para 1-4 blessings (ou cinza se nao tiver imagem amarela)
            local yellowPath = "/images/inventory/button_blessings_yellow"
            if g_resources and g_resources.fileExists then
                local exists = pcall(function() return g_resources.fileExists(yellowPath) end)
                if exists then
                    imagePath = yellowPath
                end
            end
        end

        -- Atualizar ambos os botoes (onPanel e offPanel)
        local buttonsToUpdate = {}

        -- Tentar pelo inventoryController primeiro
        if modules and modules.game_inventory and modules.game_inventory.inventoryController then
            local ui = modules.game_inventory.inventoryController.ui
            if ui then
                if ui.onPanel then
                    local onButton = ui.onPanel:recursiveGetChildById("blessings")
                    if onButton then
                        table.insert(buttonsToUpdate, onButton)
                    end
                end
                if ui.offPanel then
                    local offButton = ui.offPanel:recursiveGetChildById("blessings")
                    if offButton then
                        table.insert(buttonsToUpdate, offButton)
                    end
                end
            end
        end

        -- Fallback: procurar em toda a UI
        if #buttonsToUpdate == 0 and g_ui then
            local rootWidget = g_ui.getRootWidget()
            if rootWidget then
                local inventoryWindow = rootWidget:recursiveGetChildById("inventoryWindow")
                if inventoryWindow then
                    local fallbackButton = inventoryWindow:recursiveGetChildById("blessings")
                    if fallbackButton then
                        table.insert(buttonsToUpdate, fallbackButton)
                    end
                end
            end
        end

        -- Atualizar todos os botoes encontrados
        for _, button in ipairs(buttonsToUpdate) do
            button:setImageSource(imagePath)
        end
    end)

    if not success then
        -- Silenciosamente ignorar erros para nao quebrar o jogo
        return
    end
end

-- Exportar funcao para outros modulos
function modules.game_helper.updateBlessingsIcon()
    updateBlessingsIcon()
end

function checkHealthPriority()
    if not hotkeyHelperStatus then
        return
    end
    if not player then return true end
    for _, spell in ipairs(helperConfig.spells) do
        local healthPercent = (player:getHealth() / player:getMaxHealth()) * 100
        if spell.id ~= 0 and healthPercent <= tonumber(spell.percent) then
            return false
        end
    end
    return true
end

function getPlayerByName(pos, name, multifloor)
    if not name then
        return nil
    end
    name = name:lower()
    -- OPTIMIZATION: Use CreatureCache for same-floor lookups (most common case)
    if not multifloor then
        for _, entry in ipairs(CreatureCache.getPlayers()) do
            if entry.creature:getName():lower() == name then
                return entry.creature
            end
        end
        return nil
    end
    -- Multifloor fallback: must use raw getSpectators
    for i, spec in ipairs(g_map.getSpectators(pos, true)) do
        if spec:getName():lower() == name then
            return spec
        end
    end
    return nil
end

-- Lazy cache for the friend-healing "enableSio0" master checkboxes. These are
-- static widgets; resolving them every 100ms tick walked the whole widget tree
-- twice. We key the cache on the panel widget identity so it self-invalidates
-- when the helper UI is rebuilt (friendHealingPanel/granSioPanel are re-set by
-- the init flow on every rebuild).
-- File-scope globals (no `local`) on purpose: see the auto-target note above --
-- helper.lua's main chunk is at Lua's 200-local-per-function limit.
friendHealCheckboxCache = { sioPanel = nil, granPanel = nil, sioCb = nil, granCb = nil }

function getFriendHealCheckboxes()
    local sioPanel = friendHealingPanel
    local granPanel = granSioPanel
    if friendHealCheckboxCache.sioPanel ~= sioPanel then
        friendHealCheckboxCache.sioPanel = sioPanel
        friendHealCheckboxCache.sioCb = sioPanel and sioPanel:recursiveGetChildById("enableSio0") or nil
    end
    if friendHealCheckboxCache.granPanel ~= granPanel then
        friendHealCheckboxCache.granPanel = granPanel
        friendHealCheckboxCache.granCb = granPanel and granPanel:recursiveGetChildById("enableSio0") or nil
    end
    return friendHealCheckboxCache.sioCb, friendHealCheckboxCache.granCb
end

-- Hoisted from onFriendHealing (was re-created as a closure every 100ms tick).
-- State that varied per call is passed in (localPlayer, localEmblem).
function friendHealShouldHealPlayer(member, isGranSio, localPlayer, localEmblem)
    if not member or member:getId() == localPlayer:getId() then
        return false
    end

    local memberShield = member:getShield()
    local memberEmblem = member:getEmblem()
    local isPartyMember = memberShield and (
        memberShield == ShieldYellow or
        memberShield == ShieldYellowSharedExp or
        memberShield == ShieldYellowNoSharedExp or
        memberShield == ShieldBlue or
        memberShield == ShieldBlueNoSharedExpBlink or
        memberShield == ShieldBlueSharedExp
    )
    local isGuildMember = memberEmblem ~= EmblemNone and memberEmblem == localEmblem

    local config = helperConfig
    local partyEnabled = isGranSio and config.gransiohealingParty or config.friendhealingParty
    local guildEnabled = isGranSio and config.gransiohealingGuild or config.friendhealingGuild
    local screenEnabled = isGranSio and config.gransiohealingScreen or config.friendhealingScreen

    if partyEnabled and isPartyMember then
        return true
    end

    if guildEnabled and isGuildMember then
        return true
    end

    if screenEnabled then
        return true
    end

    return false
end

-- Hoisted from onFriendHealing. Heal percent based on vocation.
function friendHealGetHealPercent(memberVoc, isGranSio, memberName)
    if not memberVoc or memberVoc == 0 then
        return 90
    end

    local vocationPercents = isGranSio and helperConfig.gransiohealingVocationPercent or
    helperConfig.friendhealingVocationPercent

    if not vocationPercents then
        return 90
    end

    -- Always use vocation-specific percent, default to 90 if not set
    local percent = vocationPercents[tostring(memberVoc)]

    if percent and percent > 0 then
        return percent
    end

    return 90 -- Default to 90% if vocation not found
end

function onFriendHealing(localPlayer)
    if not localPlayer then
        return
    end

    if not hotkeyHelperStatus then
        return
    end

    if not healingPanel or not friendHealPanel then
        return
    end

    local position = localPlayer:getPosition()
    if not position then
        return
    end
    local selfVoc = translateVocation(localPlayer:getVocation())
    local localEmblem = localPlayer:getEmblem()
    local sioCb, granCb = getFriendHealCheckboxes()
    local globalSioEnabled = sioCb and sioCb:isChecked()
    local globalGranEnabled = granCb and granCb:isChecked()

    -- Gran Sio tem prioridade sobre Sio quando seu cooldown está livre.
    -- Se Gran Sio não castar (cooldown ocupado, sem alvo, fora de sight), cai no Sio como fallback.
    local gransioSpellId = (helperConfig and helperConfig.gransiohealingSioSpellId) or 242
    local gransioSpell = Spells.getSpellByClientId(tonumber(gransioSpellId))
    local gransioReady = globalGranEnabled and gransioSpell and gransioSpell.id ~= 0 and
    not isSpellOnCooldown(gransioSpell)

    if gransioReady then
        -- Heal friends from gran sio list
        for _, friend in ipairs(helperConfig.gransiohealing) do
            if friend.name:len() > 0 and friend.enabled then
                local member = getPlayerByName(position, friend.name, false)
                local memberPos = member and member:getPosition()
                if memberPos then
                    local memberVoc = getMemberVocation(member)
                    local memberHealth = member:getHealthPercent()
                    local isInSight =
                        g_map.isSightClear(position, memberPos) and
                        isWithinReach(position, memberPos)
                    local healPercent = friendHealGetHealPercent(memberVoc, true, friend.name)

                    if isInSight and memberHealth <= healPercent then
                        if useAutoGranSio(member) then
                            return
                        end
                    end
                end
            end
        end

        -- Heal party/guild/screen members with gran sio if enabled
        if helperConfig.gransiohealingParty or helperConfig.gransiohealingGuild or helperConfig.gransiohealingScreen then
            local playersToHeal = {}

            for _, entry in ipairs(CreatureCache.getPlayers()) do
                local spec = entry.creature
                if spec:isPlayer() and friendHealShouldHealPlayer(spec, true, localPlayer, localEmblem) then
                    local memberVoc = getMemberVocation(spec)
                    local memberHealth = spec:getHealthPercent()
                    local isInSight = entry:hasSightClear() and isWithinReach(position, spec:getPosition())
                    local healPercent = friendHealGetHealPercent(memberVoc, true, spec:getName())

                    if isInSight and memberHealth <= healPercent then
                        local priority = (helperConfig.gransiohealingVocationPriority and helperConfig.gransiohealingVocationPriority[tostring(memberVoc)]) or
                        99
                        table.insert(playersToHeal,
                            { player = spec, voc = memberVoc, priority = priority, health = memberHealth })
                    end
                end
            end

            if #playersToHeal > 0 then
                table.sort(playersToHeal, function(a, b)
                    if a.priority ~= b.priority then
                        return a.priority < b.priority
                    else
                        return a.health < b.health
                    end
                end)

                local target = playersToHeal[1]
                if useAutoGranSio(target.player) then
                    return
                end
            end
        end
    end

    if globalSioEnabled then
        -- Heal friends from list
        for _, friend in ipairs(helperConfig.friendhealing) do
            if friend.name:len() > 0 and friend.enabled then
                local member = getPlayerByName(position, friend.name, false)
                local memberPos = member and member:getPosition()
                if memberPos then
                    local memberVoc = getMemberVocation(member)
                    local memberHealth = member:getHealthPercent()
                    local isInSight =
                        g_map.isSightClear(position, memberPos) and
                        isWithinReach(position, memberPos)
                    local healPercent = friendHealGetHealPercent(memberVoc, false, friend.name)

                    if isInSight and memberHealth <= healPercent then
                        if selfVoc == 5 then
                            useAutoUH(member)
                        elseif selfVoc == 10 then
                            useAutoTioSio(member)
                        else
                            useAutoSio(member)
                        end
                        return
                    end
                end
            end
        end

        -- Heal party/guild/screen members if enabled
        if helperConfig.friendhealingParty or helperConfig.friendhealingGuild or helperConfig.friendhealingScreen then
            local playersToHeal = {}

            for _, entry in ipairs(CreatureCache.getPlayers()) do
                local spec = entry.creature
                if spec:isPlayer() and friendHealShouldHealPlayer(spec, false, localPlayer, localEmblem) then
                    local memberVoc = getMemberVocation(spec)
                    local memberHealth = spec:getHealthPercent()
                    local isInSight = entry:hasSightClear() and isWithinReach(position, spec:getPosition())
                    local healPercent = friendHealGetHealPercent(memberVoc, false, spec:getName())

                    if isInSight and memberHealth <= healPercent then
                        local priority = (helperConfig.friendhealingVocationPriority and helperConfig.friendhealingVocationPriority[tostring(memberVoc)]) or
                        99
                        table.insert(playersToHeal,
                            { player = spec, voc = memberVoc, priority = priority, health = memberHealth })
                    end
                end
            end

            if #playersToHeal > 0 then
                table.sort(playersToHeal, function(a, b)
                    if a.priority ~= b.priority then
                        return a.priority < b.priority
                    else
                        return a.health < b.health
                    end
                end)

                local target = playersToHeal[1]
                if selfVoc == 5 then
                    useAutoUH(target.player)
                elseif selfVoc == 10 then
                    useAutoTioSio(target.player)
                else
                    useAutoSio(target.player)
                end
                return
            end
        end
    end
end

function reset()
    -- Check if panels are initialized before trying to access them
    if not healingPanel or not shooterPanel or not runePanel or not toolsPanel then
        return
    end

    for i = 0, 2 do
        local spellButton = healingPanel:recursiveGetChildById("spellButton" .. i)
        if spellButton then
            removeAction("spell", spellButton)
        end

        local potionButton = healingPanel:recursiveGetChildById("potionButton" .. i)
        if potionButton then
            removeAction("potion", potionButton)
        end

        local attackSpellButton = shooterPanel:recursiveGetChildById("attackSpellButton" .. i)
        if attackSpellButton then
            removeAction("shooter", attackSpellButton)
        end

        if i < 2 then
            local runeButton = runePanel:recursiveGetChildById("runeShooterButton" .. i)
            if runeButton then
                removeAction("rune", runeButton)
            end
            -- Hide rune shooter count labels
            local runeCountLabel = runePanel:recursiveGetChildById("runeShooterButton" .. i .. "Count")
