function removeAction(type, button, keepInfo)
    local slotIndex = tonumber(button:getId():match("%d+"))
    if type == "spell" then
        helperConfig.spells[slotIndex + 1].id = 0
        helperConfig.spells[slotIndex + 1].percent = 80
        helperConfig.spells[slotIndex + 1].priority = 1
        helperConfig.spells[slotIndex + 1].orderPriority = slotIndex + 1
        local button = healingPanel:recursiveGetChildById("spellButton" .. slotIndex)
        local percentInput = healingPanel:recursiveGetChildById("spellPercentInput" .. slotIndex)
        local priorityButton = healingPanel:recursiveGetChildById("spellPriority" .. slotIndex)
        local orderPriorityCombo = healingPanel:recursiveGetChildById("spellOrderPriority" .. slotIndex)
        local infoButton = helper:recursiveGetChildById("spellInfoButton" .. slotIndex)
        button:setImageSource("/images/game/actionbar/slot-actionbar.png")
        button:setImageClip("0 0 34 34")
        button:setBorderWidth(0)
        button:setText("")
        button:setTooltip("")
        if percentInput then
            percentInput:setText("80")
        end
        if priorityButton then
            priorityButton:setImageSource("/images/ui/show-gui-help-orange.png")
            priorityButton:setTooltip("This spell is healing health...")
            priorityButton.actionId = 1
        end
        if orderPriorityCombo then
            local priorityText = ""
            if slotIndex + 1 == 1 then
                priorityText = "1st"
            elseif slotIndex + 1 == 2 then
                priorityText = "2nd"
            elseif slotIndex + 1 == 3 then
                priorityText = "3rd"
            elseif slotIndex + 1 == 4 then
                priorityText = "4th"
            else
                priorityText = "1st"
            end
            orderPriorityCombo:setCurrentOption(priorityText)
        end
        if infoButton then
            infoButton:setVisible(false)
            infoButton:setTooltip("")
        end
    elseif type == "shooter" then
        local profile = getShooterProfile()
        local slot = slotIndex + 1
        if profile and not profile.spells[slot] then
            profile.spells[slot] = ensureShooterSpellRule({}, slot)
        end
        if not keepInfo then
            if profile and profile.spells[slot] then
                profile.spells[slot].id = 0
                profile.spells[slot].percent = 80
                profile.spells[slot].creatures = 1
                profile.spells[slot].forceCast = false
                profile.spells[slot].selfCast = false
                profile.spells[slot].customText = ""    -- Clear custom text
                profile.spells[slot].cooldown = 2000    -- Reset cooldown
                profile.spells[slot].needTarget = false -- Clear needTarget
            end
        end
        local button = shooterPanel:recursiveGetChildById("attackSpellButton" .. slotIndex)
        if button then
            button:setImageSource("/images/game/actionbar/slot-actionbar.png")
            button:setImageClip("0 0 34 34")
            button:setBorderWidth(0)
            button:setText("")
            button:setTooltip("")
        end
        local forceCast = shooterPanel:recursiveGetChildById("conditionSetting" .. slotIndex)
        if forceCast then
            forceCast:setChecked(false)
            forceCast:setVisible(false)
        end
        local needTarget = shooterPanel:recursiveGetChildById("needTarget" .. slotIndex)
        if needTarget then
            needTarget:setChecked(false)
        end
        local creaturesMin = shooterPanel:recursiveGetChildById("countMinCreature" .. slotIndex)
        if creaturesMin then
            creaturesMin:setCurrentOption("1+")
            creaturesMin:enable()
        end
        local selfCast = shooterPanel:recursiveGetChildById("selfCast" .. slotIndex)
        if selfCast then
            selfCast:destroy()
        end
    elseif type == "potion" then
        if not helperConfig.potions[slotIndex + 1] then
            helperConfig.potions[slotIndex + 1] = {}
        end

        -- Resetar priority para 1 (HP) ao remover potion
        helperConfig.potions[slotIndex + 1].priority = 1
        helperConfig.potions[slotIndex + 1].orderPriority = slotIndex + 1
        local priorityButton = healingPanel:recursiveGetChildById("priority" .. slotIndex)
        if priorityButton then
            priorityButton:setImageSource("/images/ui/show-gui-help-orange.png")
            priorityButton:setTooltip("This potion is healing health...")
            priorityButton.actionId = 1
        end
        local orderPriorityCombo = healingPanel:recursiveGetChildById("potionOrderPriority" .. slotIndex)
        if orderPriorityCombo then
            local priorityText = ""
            if slotIndex + 1 == 1 then
                priorityText = "1st"
            elseif slotIndex + 1 == 2 then
                priorityText = "2nd"
            elseif slotIndex + 1 == 3 then
                priorityText = "3rd"
            elseif slotIndex + 1 == 4 then
                priorityText = "4th"
            else
                priorityText = "1st"
            end
            orderPriorityCombo:setCurrentOption(priorityText)
        end

        helperConfig.potions[slotIndex + 1].id = 0
        helperConfig.potions[slotIndex + 1].percent = 80
        local button = healingPanel:recursiveGetChildById("potionButton" .. slotIndex)
        button:setImageSource("/images/game/actionbar/slot-actionbar.png")
        local percentInput = healingPanel:recursiveGetChildById("potionPercentInput" .. slotIndex)
        if button.potionItem then
            button.potionItem:destroy()
        end
        if percentInput then
            percentInput:setText("80")
        end
        local countLabel = healingPanel:recursiveGetChildById("potionItemCount" .. slotIndex)
        if countLabel then
            countLabel:setVisible(false)
        end
    elseif type == "rune" then
        local profile = getShooterProfile()
        local slot = slotIndex + 1
        if profile and not profile.runes[slot] then
            profile.runes[slot] = ensureShooterRuneRule({}, slot)
        end
        if not keepInfo then
            if profile and not profile.runes[slot] then
                profile.runes[slot] = {}
            end

            if profile and profile.runes[slot] then
                profile.runes[slot].id = 0
                profile.runes[slot].creatures = 1
                profile.runes[slot].forceCast = false
            end
        end
        local button = runePanel:recursiveGetChildById("runeShooterButton" .. slotIndex)
        if button then
            button:setImageSource("/images/game/actionbar/slot-actionbar.png")
        end
        local creaturesMin = runePanel:recursiveGetChildById("countMinCreature" .. slotIndex)
        if creaturesMin then
            creaturesMin:setCurrentOption("1+")
            creaturesMin:enable()
        end
        local forceCast = runePanel:recursiveGetChildById("conditionSetting" .. slotIndex)
        if forceCast then
            forceCast:setVisible(false)
            forceCast:setChecked(false)
        end
        if button and button.runeItem then
            button.runeItem:destroy()
        end
        -- Hide rune count label
        local countLabel = runePanel:recursiveGetChildById("runeShooterButton" .. slotIndex .. "Count")
        if countLabel then
            countLabel:setVisible(false)
        end
    elseif type == "training" then
        helperConfig.training[slotIndex + 1].id = 0
        helperConfig.training[slotIndex + 1].percent = 0
        helperConfig.training[slotIndex + 1].enabled = false
        local button = toolsPanel:recursiveGetChildById("spellTrainingButton" .. slotIndex)
        local percentOption = toolsPanel:recursiveGetChildById("spellTrainingPercent" .. slotIndex)
        button:setImageSource("/images/game/actionbar/slot-actionbar.png")
        button:setImageClip("0 0 34 34")
        button:setBorderWidth(0)
        button:setTooltip("")
        if percentOption then
            percentOption:setCurrentOption("100%")
        end
        toolsPanel:recursiveGetChildById("enableTraining" .. slotIndex):setChecked(false)
    elseif type == "haste" then
        helperConfig.haste[slotIndex + 1].id = 0
        helperConfig.haste[slotIndex + 1].enabled = false
        helperConfig.haste[slotIndex + 1].safecast = false
        local button = toolsPanel:recursiveGetChildById("hasteButton" .. slotIndex)
        button:setImageSource("/images/game/actionbar/slot-actionbar.png")
        button:setImageClip("0 0 34 34")
        button:setBorderWidth(0)
        button:setTooltip("")
        toolsPanel:recursiveGetChildById("enableHaste" .. slotIndex):setChecked(false)
        toolsPanel:recursiveGetChildById("castOnPz"):setChecked(false)
    elseif type == "cureParalyze" then
        helperConfig.cureParalyze[slotIndex + 1].id = 0
        helperConfig.cureParalyze[slotIndex + 1].enabled = false
        local button = toolsPanel:recursiveGetChildById("cureParalyzeButton" .. slotIndex)
        if button then
            button:setImageSource("/images/game/actionbar/slot-actionbar.png")
            button:setImageClip("0 0 34 34")
            button:setBorderWidth(0)
            button:setTooltip("")
        end
        local enable = toolsPanel:recursiveGetChildById("enableCureParalyze" .. slotIndex)
        if enable then
            enable:setChecked(false)
        end
    elseif type == "exercise" then
        helperConfig.exerciseWeaponId = 0
        helperConfig.exerciseWeaponIdsText = ""
        local exerciseEdit = toolsPanel and toolsPanel:recursiveGetChildById("exerciseTrainingIdsEdit")
        if exerciseEdit then
            exerciseEdit:setText("")
        end
        saveSettings()
    elseif type == "dummy" then
        helperConfig.trainingDummyIds = { 0, 0, 0 }
        helperConfig.trainingDummyIdsText = ""
        local dummyEdit = toolsPanel and toolsPanel:recursiveGetChildById("dummyTrainingIdsEdit")
        if dummyEdit then
            dummyEdit:setText("")
        end
        saveSettings()
    elseif type == "amulet" then
        -- Update config
        if helperConfig.amulets and helperConfig.amulets[slotIndex + 1] then
            helperConfig.amulets[slotIndex + 1].id = 0
        end

        -- Update button visual
        button:setImageSource("/images/game/actionbar/slot-actionbar.png")
        button:setTooltip("")
        local amuletItem = button:getChildById("amuletItem") or button.amuletItem
        if amuletItem then
            amuletItem:destroy()
        end
        button.amuletItem = nil
        local countLabel = helper:recursiveGetChildById("amuletItemCount" .. slotIndex)
        if countLabel then
            countLabel:setVisible(false)
        end
        rebuildAllEquipmentSwapRules()
        updateAllItemCounts()
        saveSettings()
    elseif type == "ring" then
        -- Update config
        if helperConfig.rings and helperConfig.rings[slotIndex + 1] then
            helperConfig.rings[slotIndex + 1].id = 0
        end

        -- Update button visual
        button:setImageSource("/images/game/actionbar/slot-actionbar.png")
        button:setTooltip("")
        local ringItem = button:getChildById("ringItem") or button.ringItem
        if ringItem then
            ringItem:destroy()
        end
        button.ringItem = nil
        local countLabel = helper:recursiveGetChildById("ringItemCount" .. slotIndex)
        if countLabel then
            countLabel:setVisible(false)
        end
        rebuildAllEquipmentSwapRules()
        updateAllItemCounts()
        saveSettings()
    end
end

function loadProfileOptions(forceRefresh)
    loadModulePresetOptions("shooter", forceRefresh)
end

function loadShooterProfileByName(profileName)
    helperConfig.selectedShooterProfile = profileName
    local profile = getShooterProfile()
    if not profile then
        return
    end

    -- Atualizar tooltip do shooter com o novo preset
    if IconStatsModule and IconStatsModule.updateModulePresetTooltip then
        IconStatsModule.updateModulePresetTooltip("shooter")
    elseif IconStatsModule and IconStatsModule.updateShooterTooltip then
        IconStatsModule.updateShooterTooltip()
    end

    ensureShooterProfileConfig(profile, true)
    local refs = buildShooterUnifiedRuleRefs(profile)
    applyShooterRuleRefOrder(profile, refs)
    rebuildAllShooterRules()
    updateAllItemCounts()
    updateModulePresetNavigationToggle("shooter")
end

function onLoadHelperData()
    local startTime = _G.profileHelperModule and g_clock.millis() or 0
    if not healingPanel then
        -- Resetar flag caso tenha sido setado antes da chamada
        isLoadingAlarmData = false
        return
    end

    local function setCheckboxState(widget, checked)
        if not widget or widget:isChecked() == checked then
            return
        end
        local oldCallback = widget.onCheckChange
        widget.onCheckChange = nil
        widget:setChecked(checked)
        widget.onCheckChange = oldCallback
    end

    setCheckboxState(healingPanel:recursiveGetChildById("enableAutoHealing"), helperConfig.autoHealingEnabled == true)
    if friendHealPanel then
        setCheckboxState(friendHealPanel:recursiveGetChildById("enableAllFriendHealing"),
            helperConfig.healFriendEnabled == true)

        -- Load friend healing Party, Guild, Screen checkboxes
        local friendHealingPanel = friendHealPanel:recursiveGetChildById("friendHealingPanel")
        if friendHealingPanel then
            local enablePartyHeal = friendHealingPanel:recursiveGetChildById("enablePartyHeal")
            if enablePartyHeal then
                setCheckboxState(enablePartyHeal, helperConfig.friendhealingParty == true)
            end
            local enableGuildHeal = friendHealingPanel:recursiveGetChildById("enableGuildHeal")
            if enableGuildHeal then
                setCheckboxState(enableGuildHeal, helperConfig.friendhealingGuild == true)
            end
            local enableScreenHeal = friendHealingPanel:recursiveGetChildById("enableScreenHeal")
            if enableScreenHeal then
                setCheckboxState(enableScreenHeal, helperConfig.friendhealingScreen == true)
            end
        end
        -- Load sio spell button icon
        loadSioSpellButton(false)

        -- Load gran sio Party, Guild, Screen checkboxes
        local granSioPanel = friendHealPanel:recursiveGetChildById("granSioPanel")
        if granSioPanel then
            local enablePartyGranHeal = granSioPanel:recursiveGetChildById("enablePartyGranHeal")
            if enablePartyGranHeal then
                setCheckboxState(enablePartyGranHeal, helperConfig.gransiohealingParty == true)
            end
            local enableGuildGranHeal = granSioPanel:recursiveGetChildById("enableGuildGranHeal")
            if enableGuildGranHeal then
                setCheckboxState(enableGuildGranHeal, helperConfig.gransiohealingGuild == true)
            end
            local enableScreenGranHeal = granSioPanel:recursiveGetChildById("enableScreenGranHeal")
            if enableScreenGranHeal then
                setCheckboxState(enableScreenGranHeal, helperConfig.gransiohealingScreen == true)
            end
        end
        -- Load gran sio spell button icon
        loadSioSpellButton(true)

        -- Load tio sio Party, Guild, Screen checkboxes
        local tioSioPanel = friendHealPanel:recursiveGetChildById("tioSioPanel")
        if tioSioPanel then
            local enablePartyTioSioHeal = tioSioPanel:recursiveGetChildById("enablePartyTioSioHeal")
            if enablePartyTioSioHeal then
                setCheckboxState(enablePartyTioSioHeal, helperConfig.tiosiohealingParty == true)
            end
            local enableGuildTioSioHeal = tioSioPanel:recursiveGetChildById("enableGuildTioSioHeal")
            if enableGuildTioSioHeal then
                setCheckboxState(enableGuildTioSioHeal, helperConfig.tiosiohealingGuild == true)
            end
            local enableScreenTioSioHeal = tioSioPanel:recursiveGetChildById("enableScreenTioSioHeal")
            if enableScreenTioSioHeal then
                setCheckboxState(enableScreenTioSioHeal, helperConfig.tiosiohealingScreen == true)
            end
        end

        -- Load UH Party, Guild, Screen checkboxes
        local uhRunePanel = friendHealPanel:recursiveGetChildById("uhRunePanel")
        if uhRunePanel then
            local enablePartyUHHeal = uhRunePanel:recursiveGetChildById("enablePartyUHHeal")
            if enablePartyUHHeal then
                setCheckboxState(enablePartyUHHeal, helperConfig.uhhealingParty == true)
            end
            local enableGuildUHHeal = uhRunePanel:recursiveGetChildById("enableGuildUHHeal")
            if enableGuildUHHeal then
                setCheckboxState(enableGuildUHHeal, helperConfig.uhhealingGuild == true)
            end
            local enableScreenUHHeal = uhRunePanel:recursiveGetChildById("enableScreenUHHeal")
            if enableScreenUHHeal then
                setCheckboxState(enableScreenUHHeal, helperConfig.uhhealingScreen == true)
            end
            -- Load UH enable checkbox
            if helperConfig.uhhealing and helperConfig.uhhealing[1] then
                local enableUH = uhRunePanel:recursiveGetChildById("enableUH0")
                if enableUH then
                    setCheckboxState(enableUH, helperConfig.uhhealing[1].enabled == true)
                end
            end
        end

        -- Load TioSio enable checkbox
        if tioSioPanel then
            if helperConfig.tiosiohealing and helperConfig.tiosiohealing[1] then
                local enableTioSio = tioSioPanel:recursiveGetChildById("enableTioSio0")
                if enableTioSio then
                    setCheckboxState(enableTioSio, helperConfig.tiosiohealing[1].enabled == true)
                end
            end
            -- Load TioSio vocation HP percent and priority combos
            if helperConfig.tiosiohealingVocationPercent then
                local vocationCombos = {
                    { percentId = "tioSioKnightPercent",   priorityId = "tioSioKnightPriority",   vocId = "8" },
                    { percentId = "tioSioPaladinPercent",  priorityId = "tioSioPaladinPriority",  vocId = "7" },
                    { percentId = "tioSioSorcererPercent", priorityId = "tioSioSorcererPriority", vocId = "5" },
                    { percentId = "tioSioDruidPercent",    priorityId = "tioSioDruidPriority",    vocId = "6" }
                }
                for _, combo in ipairs(vocationCombos) do
                    local percentCombo = tioSioPanel:recursiveGetChildById(combo.percentId)
                    if percentCombo then
                        local percent = helperConfig.tiosiohealingVocationPercent[combo.vocId] or 90
                        percentCombo:setText(tostring(percent))
                    end
                    local priorityCombo = tioSioPanel:recursiveGetChildById(combo.priorityId)
                    if priorityCombo and helperConfig.tiosiohealingVocationPriority then
                        local priority = helperConfig.tiosiohealingVocationPriority[combo.vocId] or 1
                        priorityCombo:setCurrentOption(tostring(priority))
                    end
                end
            end
        end

        -- Load UH vocation HP percent and priority combos
        if uhRunePanel and helperConfig.uhhealingVocationPercent then
            local vocationCombos = {
                { percentId = "uhKnightPercent",   priorityId = "uhKnightPriority",   vocId = "8" },
                { percentId = "uhPaladinPercent",  priorityId = "uhPaladinPriority",  vocId = "7" },
                { percentId = "uhSorcererPercent", priorityId = "uhSorcererPriority", vocId = "5" },
                { percentId = "uhDruidPercent",    priorityId = "uhDruidPriority",    vocId = "6" }
            }
            for _, combo in ipairs(vocationCombos) do
                local percentCombo = uhRunePanel:recursiveGetChildById(combo.percentId)
                if percentCombo then
                    local percent = helperConfig.uhhealingVocationPercent[combo.vocId] or 90
                    percentCombo:setText(tostring(percent))
                end
                local priorityCombo = uhRunePanel:recursiveGetChildById(combo.priorityId)
                if priorityCombo and helperConfig.uhhealingVocationPriority then
                    local priority = helperConfig.uhhealingVocationPriority[combo.vocId] or 1
                    priorityCombo:setCurrentOption(tostring(priority))
                end
            end
        end

        -- Load individual friend healing enable checkboxes (Sio)
        if friendHealingPanel and helperConfig.friendhealing then
            for i, friend in ipairs(helperConfig.friendhealing) do
                local enableSio = friendHealingPanel:recursiveGetChildById("enableSio" .. (i - 1))
                if enableSio then
                    setCheckboxState(enableSio, friend.enabled == true)
                end
            end
        end

        -- Load individual gran sio healing enable checkboxes
        if granSioPanel and helperConfig.gransiohealing then
            for i, friend in ipairs(helperConfig.gransiohealing) do
                local enableSio = granSioPanel:recursiveGetChildById("enableSio" .. (i - 1))
                if enableSio then
                    setCheckboxState(enableSio, friend.enabled == true)
                end
            end
        end

        -- Load vocation HP percent and priority combos for Sio
        if friendHealingPanel and helperConfig.friendhealingVocationPercent then
            local vocationCombos = {
                { percentId = "knightPercent",   priorityId = "knightPriority",   vocId = "8" },
                { percentId = "paladinPercent",  priorityId = "paladinPriority",  vocId = "7" },
                { percentId = "sorcererPercent", priorityId = "sorcererPriority", vocId = "5" },
                { percentId = "druidPercent",    priorityId = "druidPriority",    vocId = "6" }
            }
            for _, combo in ipairs(vocationCombos) do
                local percentCombo = friendHealingPanel:recursiveGetChildById(combo.percentId)
                if percentCombo then
                    local percent = helperConfig.friendhealingVocationPercent[combo.vocId] or 90
                    percentCombo:setText(tostring(percent))
                end
                local priorityCombo = friendHealingPanel:recursiveGetChildById(combo.priorityId)
                if priorityCombo and helperConfig.friendhealingVocationPriority then
                    local priority = helperConfig.friendhealingVocationPriority[combo.vocId] or 1
                    priorityCombo:setCurrentOption(tostring(priority))
                end
            end
        end

        -- Load vocation HP percent and priority combos for Gran Sio
        if granSioPanel and helperConfig.gransiohealingVocationPercent then
            local vocationCombos = {
                { percentId = "granKnightPercent",   priorityId = "granKnightPriority",   vocId = "8" },
                { percentId = "granPaladinPercent",  priorityId = "granPaladinPriority",  vocId = "7" },
                { percentId = "granSorcererPercent", priorityId = "granSorcererPriority", vocId = "5" },
                { percentId = "granDruidPercent",    priorityId = "granDruidPriority",    vocId = "6" }
            }
            for _, combo in ipairs(vocationCombos) do
                local percentCombo = granSioPanel:recursiveGetChildById(combo.percentId)
                if percentCombo then
                    local percent = helperConfig.gransiohealingVocationPercent[combo.vocId] or 90
                    percentCombo:setText(tostring(percent))
                end
                local priorityCombo = granSioPanel:recursiveGetChildById(combo.priorityId)
                if priorityCombo and helperConfig.gransiohealingVocationPriority then
                    local priority = helperConfig.gransiohealingVocationPriority[combo.vocId] or 1
                    priorityCombo:setCurrentOption(tostring(priority))
                end
            end
        end
    end

    rebuildAllHealingRules()

    for k, v in pairs(helperConfig.spells) do
        if v.id ~= 0 then
            local button = healingPanel:recursiveGetChildById("spellButton" .. k - 1)
            local spell, spellProfile = Spells.getSpellByClientId(v.id)
            spellProfile = spellProfile or "Default"
            if spell and SpelllistSettings[spellProfile] then
                local spellId = SpellIcons[spell.icon][1]
                local source = SpelllistSettings[spellProfile].iconsFolder
                local clip = Spells.getImageClipNormal(spellId, spellProfile)
                button:setImageSource(source)
                button:setImageClip(clip)
                button:setBorderColorTop("#1b1b1b")
                button:setBorderColorLeft("#1b1b1b")
                button:setBorderColorRight("#757575")
                button:setBorderColorBottom("#757575")
                button:setBorderWidth(1)
                local spellName = spell.name or spell.words or "Unknown"
                button:setTooltip("Spell: " .. spellName .. "\nWords: " .. spell.words)
            end
        end
        local percentInput = healingPanel:recursiveGetChildById("spellPercentInput" .. k - 1)
        if percentInput then
            percentInput:setText(tostring(v.percent))
        end

        -- Configurar botao de prioridade do spell
        if v.id ~= 0 then
            local priorityButton = healingPanel:recursiveGetChildById("spellPriority" .. k - 1)
            if priorityButton then
                if v.priority == 2 then
                    priorityButton:setImageSource("/images/skin/show-gui-help-blue")
                    priorityButton:setTooltip("This spell is healing mana...")
                    priorityButton.actionId = 2
                else
                    priorityButton:setImageSource("/images/ui/show-gui-help-orange.png")
                    priorityButton:setTooltip("This spell is healing health...")
                    priorityButton.actionId = 1
                    if not v.priority then
                        v.priority = 1
                    end
                end
            end
        end

        -- Configurar ComboBox de prioridade numérica do spell
        local orderPriorityCombo = healingPanel:recursiveGetChildById("spellOrderPriority" .. k - 1)
        if orderPriorityCombo then
            local orderPriority = v.orderPriority or k
            local priorityText = ""
            if orderPriority == 1 then
                priorityText = "1st"
            elseif orderPriority == 2 then
                priorityText = "2nd"
            elseif orderPriority == 3 then
                priorityText = "3rd"
            elseif orderPriority == 4 then
                priorityText = "4th"
            else
                priorityText = "1st"
            end
            orderPriorityCombo:setCurrentOption(priorityText)
        end

        -- Configurar ComboBox de Type do spell
        local typeCombo = healingPanel:recursiveGetChildById("spellType" .. k - 1)
        if typeCombo then
            local typeText = (v.priority == 2) and "MP" or "HP"
            typeCombo:setCurrentOption(typeText)
        end
    end

    for k, v in pairs(helperConfig.potions) do
        if v.id ~= 0 then
            local button = healingPanel:recursiveGetChildById("potionButton" .. k - 1)
            local itemWidget = g_ui.createWidget("PotionItem", button)
            itemWidget:setItemId(v.id)
            itemWidget:setId("potionItem")
        end

        -- Configurar botao de prioridade para todas as potions
        local priorityButton = healingPanel:recursiveGetChildById("priority" .. k - 1)
        if priorityButton then
            if not v.priority then
                v.priority = 1
            end

            if v.priority == 2 then
                priorityButton:setImageSource("/images/skin/show-gui-help-blue")
                priorityButton:setTooltip("This potion is healing mana...")
                priorityButton.actionId = 2
            else
                priorityButton:setImageSource("/images/ui/show-gui-help-orange.png")
                priorityButton:setTooltip("This potion is healing health...")
                priorityButton.actionId = 1
            end
        end

        -- Configurar ComboBox de prioridade numérica da potion
        local orderPriorityCombo = healingPanel:recursiveGetChildById("potionOrderPriority" .. k - 1)
        if orderPriorityCombo then
            local orderPriority = v.orderPriority or k
            local priorityText = ""
            if orderPriority == 1 then
                priorityText = "1st"
            elseif orderPriority == 2 then
                priorityText = "2nd"
            elseif orderPriority == 3 then
                priorityText = "3rd"
            elseif orderPriority == 4 then
                priorityText = "4th"
            else
                priorityText = "1st"
            end
            orderPriorityCombo:setCurrentOption(priorityText)
        end

        -- Configurar ComboBox de Type da potion
        local typeCombo = healingPanel:recursiveGetChildById("potionType" .. k - 1)
        if typeCombo then
            local typeText = (v.priority == 2) and "MP" or "HP"
            typeCombo:setCurrentOption(typeText)
        end

        local percentInput = healingPanel:recursiveGetChildById("potionPercentInput" .. k - 1)
        if percentInput then
            percentInput:setText(tostring(v.percent))
        end
    end

    if not toolsPanel then
        return
    end

    for k, v in pairs(helperConfig.training) do
        if v.id ~= 0 then
            local button = toolsPanel:recursiveGetChildById("spellTrainingButton" .. k - 1)
            local spell, spellProfile = Spells.getSpellByClientId(v.id)
            spellProfile = spellProfile or "Default"
            if spell and SpelllistSettings[spellProfile] then
                local spellId = SpellIcons[spell.icon][1]
                local source = SpelllistSettings[spellProfile].iconsFolder
                local clip = Spells.getImageClipNormal(spellId, spellProfile)
                button:setImageSource(source)
                button:setImageClip(clip)
                button:setBorderColorTop("#1b1b1b")
                button:setBorderColorLeft("#1b1b1b")
                button:setBorderColorRight("#757575")
                button:setBorderColorBottom("#757575")
                button:setBorderWidth(1)
                local spellName = spell.name or spell.words or "Unknown"
                button:setTooltip("Spell: " .. spellName .. "\nWords: " .. spell.words)
            end
            local percentOption = toolsPanel:recursiveGetChildById("spellTrainingPercent" .. k - 1)
            if percentOption then
                percentOption:setCurrentOption(tostring(v.percent) .. "%")
            end
            toolsPanel:recursiveGetChildById("enableTraining" .. k - 1):setChecked(v.enabled)
        end
    end

    if toolsPanel then
        local exerciseEdit = toolsPanel:recursiveGetChildById("exerciseTrainingIdsEdit")
        if exerciseEdit then
            exerciseEdit:setText(helperConfig.exerciseWeaponIdsText or "")
        end
        local dummyEdit = toolsPanel:recursiveGetChildById("dummyTrainingIdsEdit")
        if dummyEdit then
            dummyEdit:setText(helperConfig.trainingDummyIdsText or "")
        end
        local useDefaultDummiesCheck = toolsPanel:recursiveGetChildById("useDefaultDummiesCheck")
        if useDefaultDummiesCheck then
            setCheckboxState(useDefaultDummiesCheck, helperConfig.useDefaultDummies ~= false)
        end
    end

    -- Load auto training checkbox
    if toolsPanel then
        local autoTrainingCheck = toolsPanel:recursiveGetChildById("autoTrainingCheck")
        if autoTrainingCheck then
            setCheckboxState(autoTrainingCheck, helperConfig.autoTrainingEnabled == true)
        end
    end

    ensureTimerConfig(TIMER_DEFAULT_RULE_COUNT)
    if equipmentPanel then
        ensureEquipmentSwapConfig(EQUIPMENT_SWAP_DEFAULT_SLOT_COUNT)
        rebuildAllEquipmentSwapRules()
        updateAllItemCounts()
    end

    for k, v in pairs(helperConfig.haste) do
        if v.id ~= 0 then
            local button = toolsPanel:recursiveGetChildById("hasteButton" .. k - 1)
            local spell, spellProfile = Spells.getSpellByClientId(v.id)
            spellProfile = spellProfile or "Default"
            if spell and SpelllistSettings[spellProfile] then
                local spellId = SpellIcons[spell.icon][1]
                local source = SpelllistSettings[spellProfile].iconsFolder
                local clip = Spells.getImageClipNormal(spellId, spellProfile)

                button:setImageSource(source)
                button:setImageClip(clip)
                button:setBorderColorTop("#1b1b1b")
                button:setBorderColorLeft("#1b1b1b")
                button:setBorderColorRight("#757575")
                button:setBorderColorBottom("#757575")
                button:setBorderWidth(1)
                local spellName = spell.name or spell.words or "Unknown"
                button:setTooltip("Spell: " .. spellName .. "\nWords: " .. spell.words)
            end
            toolsPanel:recursiveGetChildById("enableHaste" .. k - 1):setChecked(v.enabled)
            toolsPanel:recursiveGetChildById("castOnPz"):setChecked(v.safecast)
        end
    end
    for k, v in pairs(helperConfig.cureParalyze) do
        local button = toolsPanel:recursiveGetChildById("cureParalyzeButton" .. k - 1)
        if v.id ~= 0 and button then
            local spell, spellProfile = Spells.getSpellByClientId(v.id)
            spellProfile = spellProfile or "Default"
            if spell and SpelllistSettings[spellProfile] then
                local spellId = SpellIcons[spell.icon][1]
                local source = SpelllistSettings[spellProfile].iconsFolder
                local clip = Spells.getImageClipNormal(spellId, spellProfile)

                button:setImageSource(source)
                button:setImageClip(clip)
                button:setBorderColorTop("#1b1b1b")
                button:setBorderColorLeft("#1b1b1b")
                button:setBorderColorRight("#757575")
                button:setBorderColorBottom("#757575")
                button:setBorderWidth(1)
                local spellName = spell.name or spell.words or "Unknown"
                button:setTooltip("Spell: " .. spellName .. "\nWords: " .. spell.words)
            end
        end
        local enable = toolsPanel:recursiveGetChildById("enableCureParalyze" .. k - 1)
        if enable then
            enable:setChecked(v.enabled)
        end
    end
    -- Refresh shooter presets dropdown before loading the selected profile
    ensureModulePresetConfig("healing")
    ensureModulePresetConfig("equipment")
    ensureModulePresetConfig("targeting")
    loadHealingPresetOptions(true)
    loadEquipmentPresetOptions(true)
    loadTargetingPresetOptions(true)
    loadProfileOptions(true)
    loadShooterProfileByName(helperConfig.selectedShooterProfile)
    refreshPresetHotkeyLabelsDeferred()
    toolsPanel:recursiveGetChildById("eatFood"):setChecked(helperConfig.autoEatFood)
    toolsPanel:recursiveGetChildById("portableTrader"):setChecked(helperConfig.autoPortableTrader)
    local portableTraderCapInput = toolsPanel:recursiveGetChildById("portableTraderCapInput")
    if portableTraderCapInput then
        portableTraderCapInput:setText(tostring(helperConfig.portableTraderCapThreshold or 1000))
    end
    toolsPanel:recursiveGetChildById("autoIncreaseForgeLimit"):setChecked(helperConfig.autoIncreaseForgeLimit)
    toolsPanel:recursiveGetChildById("autoConvertDustToSlivers"):setChecked(helperConfig.autoConvertDustToSlivers)
    toolsPanel:recursiveGetChildById("holdAttack"):setChecked(helperConfig.holdAttack)
    -- Auto Reconnect state lives in the entergame reconnect engine's per-character
    -- node (see modules.game_helper.toggleAutoReconnect), not in helperConfig, so
    -- source it from there. setCheckboxState avoids re-firing toggleAutoReconnect.
    local autoReconnectCheckbox = toolsPanel:recursiveGetChildById("autoReconnect")
    if autoReconnectCheckbox then
        local autoReconnectEnabled = false
        local charName = g_game.getCharacterName and g_game.getCharacterName()
        if charName and charName ~= "" and type(getAutoReconnect) == "function" then
            autoReconnectEnabled = getAutoReconnect(charName) == true
        end
        -- Realign the global flag with the active character: onLogout writes the
        -- per-character node from this flag, so a stale value left by a previously
        -- active character must not clobber this one on a clean logout.
        g_settings.set('autoReconnect', autoReconnectEnabled)
        setCheckboxState(autoReconnectCheckbox, autoReconnectEnabled)
    end
    if enableButtons then
        enableButtons:recursiveGetChildById("enableMagicShooter"):setChecked(helperConfig.magicShooterEnabled)
    end

    -- Load ignored mobs if targetingPanel exists
    if targetingPanel then
        local ignoredMobsInput = targetingPanel:recursiveGetChildById("ignoredMobsInput")
        if ignoredMobsInput and helperConfig.ignoredMobs then
            local mobsText = table.concat(helperConfig.ignoredMobs, ", ")
            ignoredMobsInput:setText(mobsText)
        end

        -- Load priority mobs
        local priorityMobsInput = targetingPanel:recursiveGetChildById("priorityMobsInput")
        if priorityMobsInput and helperConfig.priorityMobs then
            local mobsText = table.concat(helperConfig.priorityMobs, ", ")
            priorityMobsInput:setText(mobsText)
        end

        -- Load pause cavebot on mob
        local pauseCavebotOnMobCheck = targetingPanel:recursiveGetChildById("pauseCavebotOnMobCheck")
        if pauseCavebotOnMobCheck then
            pauseCavebotOnMobCheck:setChecked(helperConfig.pauseCavebotOnMobEnabled == true)
        end
        local pauseCavebotOnMobInput = targetingPanel:recursiveGetChildById("pauseCavebotOnMobInput")
        if pauseCavebotOnMobInput and helperConfig.pauseCavebotOnMobs then
            pauseCavebotOnMobInput:setText(table.concat(helperConfig.pauseCavebotOnMobs, ", "))
        end

        -- Load prioritize boss checkbox
        local prioritizeBossCheckBox = targetingPanel:recursiveGetChildById("prioritizeBossCheckBox")
        if prioritizeBossCheckBox then
            prioritizeBossCheckBox:setChecked(helperConfig.prioritizeBoss ~= false)
        end

        -- Load targeting panel settings
        local enableAutoTargetTargeting = targetingPanel:recursiveGetChildById("enableAutoTarget")
        if enableAutoTargetTargeting then
            enableAutoTargetTargeting:setChecked(helperConfig.autoTargetEnabled)
        end

        -- Load attack position combobox
        local attackPositionCombo = targetingPanel:recursiveGetChildById("attackPositionCombo")
        if attackPositionCombo then
            local mode = helperConfig.attackPosition or 1
            attackPositionCombo:setCurrentIndex(mode)
        end

        -- Load attack distance input
        local attackDistanceInput = targetingPanel:recursiveGetChildById("attackDistanceInput")
        if attackDistanceInput then
            attackDistanceInput:setText(tostring(helperConfig.attackDistance or 1))
        end

        -- Show/hide distance input based on mode
        local attackDistanceLabel = targetingPanel:recursiveGetChildById("attackDistanceLabel")
        if attackDistanceLabel and attackDistanceInput then
            local mode = helperConfig.attackPosition or 1
            local showDist = (mode == 3 or mode == 4)
            attackDistanceLabel:setVisible(showDist)
            attackDistanceInput:setVisible(showDist)
        end
    end

    if targetingPanel then
        -- Load and display current target mode
        for k, v in pairs(autoTargetModes) do
            if v == helperConfig.autoTargetMode then
                updateAutoTargetModeDisplay(k)
                break
            end
        end
    end

    healingPanel.shieldHelperPanel.utamoVita:setChecked(helperConfig.utamoVitaEnabled)

    for k, v in pairs(helperConfig.utamo) do
        local percentInput = healingPanel.shieldHelperPanel:recursiveGetChildById("utamoPercentInput" .. (k - 1))
        if percentInput then
            percentInput:setText(tostring(v.percent))
        end
    end

    healingPanel.shieldHelperPanel.exanaVita:setChecked(helperConfig.exanaVitaEnabled)

    local exanaVitaWaitUtamoCDWidget = healingPanel.shieldHelperPanel:recursiveGetChildById("exanaVitaWaitUtamoCD")
    if exanaVitaWaitUtamoCDWidget then
        exanaVitaWaitUtamoCDWidget:setChecked(helperConfig.exanaVitaWaitUtamoCD or false)
    end

    for k, v in pairs(helperConfig.exana) do
        local percentInput = healingPanel.shieldHelperPanel:recursiveGetChildById("exanaPercentInput" .. (k - 1))
        if percentInput then
            percentInput:setText(tostring(v.percent))
        end
    end

    healingPanel.shieldHelperPanel.magicPotion:setChecked(helperConfig.magicPotionEnabled)

    refreshEnergyRingUI()

    knightHelperPanel:recursiveGetChildById("utitotempo"):setChecked(helperConfig.utitotempoEnabled)
    knightHelperPanel:recursiveGetChildById("utamotempo"):setChecked(helperConfig.utamotempoEnabled)
    knightHelperPanel:recursiveGetChildById("exetares"):setChecked(helperConfig.exetaresEnabled)
    knightHelperPanel:recursiveGetChildById("exetaampres"):setChecked(helperConfig.exetaampresEnabled)
    mageHelperPanel:recursiveGetChildById("exorimoe"):setChecked(helperConfig.exorimoeEnabled)
    mageHelperPanel:recursiveGetChildById("exorikor"):setChecked(helperConfig.exorikorEnabled)
    paladinHelperPanel:recursiveGetChildById("utitotemposan"):setChecked(helperConfig.utitotemposanEnabled)
    paladinHelperPanel:recursiveGetChildById("exanaampres"):setChecked(helperConfig.exanaampresEnabled)
    paladinHelperPanel:recursiveGetChildById("utevogravsan"):setChecked(helperConfig.utevogravsanEnabled)
    monkHelperPanel:recursiveGetChildById("utamotio"):setChecked(helperConfig.utamotioEnabled)
    monkHelperPanel:recursiveGetChildById("exorimasres"):setChecked(helperConfig.exorimasresEnabled)
    monkHelperPanel:recursiveGetChildById("utevonia"):setChecked(helperConfig.utevoniaEnabled)
    monkHelperPanel:recursiveGetChildById("autoVirtues"):setChecked(helperConfig.autoVirtuesEnabled)
    monkHelperPanel:recursiveGetChildById("utevospiritus"):setChecked(helperConfig.utevospiritusEnabled)
    monkHelperPanel:recursiveGetChildById("utitopugnus"):setChecked(helperConfig.utitopugnusEnabled)

    -- Load Tank Mode configuration
    if equipmentPanel then
        local enableEquipmentSwap = equipmentPanel:recursiveGetChildById("enableEquipmentSwap")
        if enableEquipmentSwap then
            enableEquipmentSwap:setChecked(helperConfig.equipmentSwapEnabled or false)
        end

        local enableTankMode = equipmentPanel:recursiveGetChildById("enableTankMode")
        if enableTankMode then
            enableTankMode:setChecked(helperConfig.tankModeEnabled or false)
        end

        local enableTankModeAmulet = equipmentPanel:recursiveGetChildById("enableTankModeAmulet")
        if enableTankModeAmulet then
            enableTankModeAmulet:setChecked(helperConfig.tankModeAmuletEnabled ~= false)
        end

        local enableTankModeRing = equipmentPanel:recursiveGetChildById("enableTankModeRing")
        if enableTankModeRing then
            enableTankModeRing:setChecked(helperConfig.tankModeRingEnabled ~= false)
        end

        local respectEnergyRing = equipmentPanel:recursiveGetChildById("respectEnergyRing")
        if respectEnergyRing then
            respectEnergyRing:setChecked(helperConfig.respectEnergyRing or false)
        end

        local enableSSATank = equipmentPanel:recursiveGetChildById("enableSSATank")
        if enableSSATank then
            setCheckboxState(enableSSATank, helperConfig.ssaTankEnabled or false)
        end

        local enableMightRing = equipmentPanel:recursiveGetChildById("enableMightRing")
        if enableMightRing then
            setCheckboxState(enableMightRing, helperConfig.mightRingEnabled or false)
        end

        -- Carregar slot de amuleto do tank mode
        local tankModeAmuletButton = equipmentPanel:recursiveGetChildById("tankModeAmuletButton")
        if tankModeAmuletButton then
            local selectedAmuletId = helperConfig.tankModeAmuletId or 3081
            if selectedAmuletId and selectedAmuletId > 0 then
                updateTankModeAmuletButton(tankModeAmuletButton, selectedAmuletId)
            end
        end

        -- Carregar slot de anel do tank mode
        local tankModeRingButton = equipmentPanel:recursiveGetChildById("tankModeRingButton")
        if tankModeRingButton then
            local selectedRingId = helperConfig.tankModeRingId or 3048
            if selectedRingId and selectedRingId > 0 then
                updateTankModeRingButton(tankModeRingButton, selectedRingId)
            end
        end
    end

    -- Load profiles panel configuration
    if profilesPanel then
        -- Recarregar configs de auto-load do disco para garantir valores atualizados
        loadAutoLoadSettings()

        local enableAutoLoad = profilesPanel:recursiveGetChildById("enableAutoLoadProfile")
        if enableAutoLoad then
            enableAutoLoad:setChecked(helperConfig.autoLoadProfileEnabled == true)
        end

        local enableAutoSave = profilesPanel:recursiveGetChildById("enableAutoSaveProfile")
        if enableAutoSave then
            enableAutoSave:setChecked(helperConfig.autoSaveProfileEnabled ~= false)
        end

        local autoLoadByName = profilesPanel:recursiveGetChildById("autoLoadByName")
        if autoLoadByName then
            -- Vocation profiles removed: only "By Character Name" remains.
            if not autoLoadRadioGroup then
                autoLoadRadioGroup = UIRadioGroup.create()
                autoLoadRadioGroup:addWidget(autoLoadByName)
            end

            autoLoadByName:setVisible(true)
            autoLoadRadioGroup:selectWidget(autoLoadByName)
        end

        -- Update current profile label
        updateCurrentProfileLabel()
    end

    -- Carregar configuracoes de alarmes
    -- Garantir que helperConfig.alarms existe
    if not helperConfig.alarms then
        helperConfig.alarms = {
            alarmDamageTaken = false,
            alarmLowHealth = false,
            alarmLowHealthThreshold = 50,
            alarmMonsterOnScreen = false,
            alarmPlayerOnScreen = false,
            alarmPlayerSkullOnScreen = false,
            alarmPlayerAttack = false,
            alarmEnemyOnScreen = false,
            alarmSoundAlert = false,
            alarmWindowsBarFlash = false
        }
    end

    if alarmsPanel then
        local alarmCheckboxes = {
            "alarmDamageTaken",
            "alarmLowHealth",
            "alarmMonsterOnScreen",
            "alarmPlayerOnScreen",
            "alarmPlayerSkullOnScreen",
            "alarmPlayerAttack",
            "alarmEnemyOnScreen",
            "alarmSoundAlert",
            "alarmWindowsBarFlash"
        }

        for _, checkboxId in ipairs(alarmCheckboxes) do
            local checkbox = getAlarmCheckbox(checkboxId)
            if checkbox then
                local checked = helperConfig.alarms[checkboxId] == true
                setCheckboxState(checkbox, checked)
            end
        end

        -- Carregar threshold de low health
        local lowHealthInput = getAlarmCheckbox("alarmLowHealthInput")
        if lowHealthInput then
            local threshold = helperConfig.alarms.alarmLowHealthThreshold or 50
            lowHealthInput:setText(tostring(threshold))
        end
    end

    -- Desabilitar flag apos aplicar todos os valores (no final da funcao)
    isLoadingAlarmData = false

    -- Atualizar contagens de itens apos carregar dados
    scheduleEvent(function()
        pcall(updateAllItemCounts)
    end, 100)

    -- SYNC PARTY MANAGEMENT
    if helper and helper.contentPanel then
        local partyManagementContent = helper.contentPanel:recursiveGetChildById("partyManagementContent")
        if partyManagementContent and helperConfig.partyManagement then
            -- Invite Party checkboxes
            if helperConfig.partyManagement.inviteParty then
                setCheckboxState(partyManagementContent:recursiveGetChildById("invitePartyAll"),
                    helperConfig.partyManagement.inviteParty.all == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("invitePartyVip"),
                    helperConfig.partyManagement.inviteParty.vip == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("invitePartyGuild"),
                    helperConfig.partyManagement.inviteParty.guild == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("invitePartyFriend"),
                    helperConfig.partyManagement.inviteParty.friend == true)
            end
            -- Auto Accept Party checkboxes
            if helperConfig.partyManagement.autoAcceptParty then
                setCheckboxState(partyManagementContent:recursiveGetChildById("autoAcceptPartyAll"),
                    helperConfig.partyManagement.autoAcceptParty.all == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("autoAcceptPartyVip"),
                    helperConfig.partyManagement.autoAcceptParty.vip == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("autoAcceptPartyGuild"),
                    helperConfig.partyManagement.autoAcceptParty.guild == true)
                setCheckboxState(partyManagementContent:recursiveGetChildById("autoAcceptPartyFriend"),
                    helperConfig.partyManagement.autoAcceptParty.friend == true)
            end
        end
    end
    modules.game_helper.refreshPartyManagementFriendLists()

    if _G.profileHelperModule then
        local elapsed = g_clock.millis() - startTime
        if elapsed > (_G.profileThresholdMs or 50) then
            g_logger.warning(string.format("[HELPER PROFILE] onLoadHelperData: %dms", elapsed))
        end
    end
end

function refreshProfilesList()
    if not profilesPanel then
        -- Tentar obter o profilesPanel novamente
        if helper and helper.contentPanel then
            profilesPanel = helper.contentPanel:recursiveGetChildById("profilesPanel")
        end
        if not profilesPanel then
            return
        end
    end

    local profilesListBox = profilesPanel:recursiveGetChildById("profilesListBox")
    if not profilesListBox then
        return
    end

    -- Limpar lista
    profilesListBox:destroyChildren()

    if not helperConfig.profiles then
        helperConfig.profiles = {}
    end

    -- Carregar lista de profiles do config.json (per-char com fallback no legacy)
    local configFile = getHelperConfigReadFile()
    local profilesDir = "/helper/profiles"
    local loadedFromConfig = false

    if g_resources.fileExists(configFile) then
        local status, result = pcall(
            function()
                return json.decode(g_resources.readFileContents(configFile))
            end
        )

        if status and result and result.profilesList and #result.profilesList > 0 then
            loadedFromConfig = true
            -- Carregar profiles dos arquivos
            for _, profileName in ipairs(result.profilesList) do
                -- IMPORTANTE: Não recarregar o profile que está atualmente selecionado
                -- porque ele pode ter alterações não salvas em memória
                if profileName ~= helperConfig.selectedProfile then
                    -- Sempre recarregar do arquivo para garantir que esta atualizado
                    local profileData = loadProfileFromFile(profileName)
                    if profileData then
                        helperConfig.profiles[profileName] = profileData
                    else
                        -- Se falhou ao carregar, remover da lista se existir
                        if helperConfig.profiles[profileName] then
                            helperConfig.profiles[profileName] = nil
                        end
                    end
                end
            end
        end
    end

    -- Sempre listar arquivos do diretorio profiles para incluir todos os profiles disponíveis
    local files = g_resources.listDirectoryFiles(profilesDir, false, false, false)
    if files then
        local foundProfiles = {}

        for _, fileName in pairs(files) do
            if fileName and fileName:match("%.json$") then
                local profileName = fileName:gsub("%.json$", "")
                if profileName and profileName ~= "" then
                    table.insert(foundProfiles, profileName)
                end
            end
        end

        -- Carregar cada profile encontrado (inclusive os que nao estao no config.json)
        for _, profileName in ipairs(foundProfiles) do
            -- IMPORTANTE: Não recarregar o profile que está atualmente selecionado
            -- porque ele pode ter alterações não salvas em memória
            if profileName ~= helperConfig.selectedProfile then
                local profileData = loadProfileFromFile(profileName)
                if profileData then
                    helperConfig.profiles[profileName] = profileData
                else
                    if helperConfig.profiles[profileName] then
                        helperConfig.profiles[profileName] = nil
                    end
                end
            end
        end
    end

    -- Atualizar o config.json com a lista completa
    if helperConfig.profiles and next(helperConfig.profiles) then
        saveSettings()
    end

    local characterProfiles = {}

    for profileName, profileData in pairs(helperConfig.profiles) do
        if profileName and profileName ~= "" and profileData then
            table.insert(characterProfiles, profileName)
        end
    end

    table.sort(characterProfiles)

    -- Helper function to add profile items to a list
    local function addProfileToList(listBox, profileName, visibleIndex)
        local currentProfileName = profileName
        local label = g_ui.createWidget('ProfileListLabel', listBox)
        label:setText(profileName)
        label:setId(profileName)

        -- Aplicar cores alternadas (zebra striping)
        label.baseBackgroundColor = visibleIndex % 2 == 0 and "#0a0a0a" or "#12121200"
        label:setBackgroundColor(label.baseBackgroundColor)
        if label.updateOnStates then
            label:updateOnStates()
        end
        label.onMouseRelease = function(widget, mousePos, mouseButton)
            if mouseButton == MouseRightButton then
                local parentList = widget:getParent()
                if parentList and parentList.focusChild then
                    parentList:focusChild(widget)
                end
                local targetProfileName = helperConfig.selectedProfile or ""
                local menu = g_ui.createWidget("HelperPopupMenu")
                menu:setGameMenu(true)
                menu:addOption(tr("Load"), function()
                    helperConfig.selectedProfile = currentProfileName
                    loadSelectedProfile()
                end)
                menu:addOption(tr("Clone"), function()
                    helperConfig.selectedProfile = currentProfileName
                    cloneSelectedProfile()
                end)
                menu:addOption(tr("Import into Current Profile"), function()
                    importProfileIntoCurrent(currentProfileName, targetProfileName)
                end)
                menu:addOption(tr("Delete"), function()
                    deleteProfileByName(currentProfileName)
                end)
                menu:display(mousePos)
            end
        end
    end

    -- Populate character profiles list
    for i, profileName in ipairs(characterProfiles) do
        addProfileToList(profilesListBox, profileName, i)
    end

    -- Selecionar o profile atual se houver
    if helperConfig.selectedProfile and helperConfig.selectedProfile ~= "" then
        for _, item in ipairs(profilesListBox:getChildren()) do
            if item:getText() == helperConfig.selectedProfile then
                profilesListBox:focusChild(item)
                break
            end
        end
    end

    profilesListBox:updateLayout()
end

-- Called from ProfileListLabel @onFocusChange when an item gains focus.
-- Handles exclusive selection: clears the other list's focus so only one item is selected.
function onProfileItemFocused(item)
    if not item then return end

    local profileName = item:getText()
    if profileName and profileName ~= "" then
        helperConfig.selectedProfile = profileName
        updateSelectedProfileLabel()
    end

end

function reloadProfilesList()
    g_logger.info("[Helper][Reload] === RELOAD PROFILES START ===")

    -- Limpar profiles da memoria
    if helperConfig.profiles then
        helperConfig.profiles = {}
    end
    g_logger.info("[Helper][Reload] Profiles limpos da memoria")

    -- Recarregar do config.json e arquivos (per-char com fallback no legacy)
    local configFile = getHelperConfigReadFile()
    if g_resources.fileExists(configFile) then
        g_logger.info("[Helper][Reload] config.json encontrado, lendo...")
        local status, result = pcall(
            function()
                return json.decode(g_resources.readFileContents(configFile))
            end
        )

        if status and result and result.profilesList then
            g_logger.info("[Helper][Reload] config.json profilesList tem " ..
            #result.profilesList .. " entradas: " .. table.concat(result.profilesList, ", "))
            for _, profileName in ipairs(result.profilesList) do
                local profileData = loadProfileFromFile(profileName)
                if profileData then
                    helperConfig.profiles[profileName] = profileData
                    g_logger.info("[Helper][Reload] config.json -> Carregado: " .. profileName)
                else
                    g_logger.warning("[Helper][Reload] config.json -> FALHOU ao carregar: " .. profileName)
                end
            end
        else
            if not status then
                g_logger.error("[Helper][Reload] config.json -> Erro ao decodificar: " .. tostring(result))
            elseif not result then
                g_logger.warning("[Helper][Reload] config.json -> resultado nil")
            elseif not result.profilesList then
                g_logger.warning("[Helper][Reload] config.json -> sem profilesList")
            end
        end
    else
        g_logger.warning("[Helper][Reload] config.json NAO encontrado")
    end

    -- Descobrir profiles diretamente da pasta
    local profilesDir = "/helper/profiles"
    g_logger.info("[Helper][Reload] Escaneando diretorio: " .. profilesDir)

    local dirExists = g_resources.directoryExists(profilesDir)
    g_logger.info("[Helper][Reload] Diretorio existe? " .. tostring(dirExists))

    local files = g_resources.listDirectoryFiles(profilesDir, false, false, false)
    if files then
        local fileCount = 0
        for _ in pairs(files) do fileCount = fileCount + 1 end
        g_logger.info("[Helper][Reload] listDirectoryFiles retornou " .. fileCount .. " arquivo(s)")

        for _, fileName in pairs(files) do
            g_logger.info("[Helper][Reload] Arquivo encontrado: '" .. tostring(fileName) .. "'")
            if fileName and fileName:match("%.json$") then
                local profileName = fileName:gsub("%.json$", "")
                if profileName and profileName ~= "" then
                    if helperConfig.profiles[profileName] then
                        g_logger.info("[Helper][Reload] Scan -> Ja carregado (skip): " .. profileName)
                    else
                        local profileData = loadProfileFromFile(profileName)
                        if profileData then
                            helperConfig.profiles[profileName] = profileData
                            g_logger.info("[Helper][Reload] Scan -> Carregado com sucesso: " .. profileName)
                        else
                            g_logger.warning("[Helper][Reload] Scan -> FALHOU ao carregar: " .. profileName)
                        end
                    end
                end
            else
                g_logger.info("[Helper][Reload] Scan -> Ignorado (nao e .json): " .. tostring(fileName))
            end
        end
    else
        g_logger.error("[Helper][Reload] listDirectoryFiles retornou nil/false para: " .. profilesDir)
    end

    -- Contar total de profiles carregados
    local totalLoaded = 0
    local loadedNames = {}
    if helperConfig.profiles then
        for name, _ in pairs(helperConfig.profiles) do
            totalLoaded = totalLoaded + 1
            table.insert(loadedNames, name)
        end
    end
    table.sort(loadedNames)
    g_logger.info("[Helper][Reload] === TOTAL: " ..
    totalLoaded .. " profile(s) carregado(s): " .. table.concat(loadedNames, ", ") .. " ===")

    -- Atualizar config.json com lista atualizada
    saveSettings()

    -- Atualizar UI
    refreshProfilesList()

    g_logger.info("[Helper][Reload] === RELOAD PROFILES END ===")
    modules.game_textmessage.displayGameMessage(htr("Profiles list reloaded."))
end

local function isProfileExcludedKey(key)
    return key == "profiles" or
        key == "selectedProfile" or
        key == "autoLoadProfileEnabled" or
        key == "autoLoadProfileType" or
        key == "holdAttackTargetId" or
        key == "holdAttackTargetName" or
        key == "iconStats"
end

local function isCavebotKey(key)
    if type(key) ~= "string" then
        return false
    end

    -- These match the "cave" substring below but MUST persist in the profile:
    -- - loadedCavebotName: the preloaded cavebot script-name pointer (the cavebot data
    --   itself stays in /helper/cavebots/<name>.json).
    -- - pauseCavebotOnMob*: these are TARGETING settings ("pause the cavebot when a
    --   dangerous mob is on screen"), not cavebot data, so they belong in the profile.
    if key == "loadedCavebotName"
        or key == "pauseCavebotOnMobEnabled"
        or key == "pauseCavebotOnMobs" then
        return false
    end

    local lowerKey = key:lower()
    return lowerKey:find("cavebot") or lowerKey:find("cave")
end

local function buildProfileDataFromConfig()
    -- Atualizar configuracoes de alarmes antes de construir o profile
    updateAlarmSettings()
    persistCurrentModulePreset("healing")
    persistCurrentModulePreset("equipment")
    persistCurrentModulePreset("targeting")

    local profileData = {}
    for k, v in pairs(helperConfig) do
        if not isProfileExcludedKey(k) and not isCavebotKey(k) then
            profileData[k] = deepCopy(v)
        end
    end

    -- Garantir que alarms sempre seja incluido no profile (mesmo se nao existir em helperConfig)
    -- Filtrar apenas os campos validos (checkboxes da UI)
    local validAlarmFields = {
        alarmDamageTaken = true,
        alarmLowHealth = true,
        alarmLowHealthThreshold = true,
        alarmMonsterOnScreen = true,
        alarmPlayerOnScreen = true,
        alarmPlayerSkullOnScreen = true,
        alarmPlayerAttack = true,
        alarmEnemyOnScreen = true,
        alarmSoundAlert = true,
        alarmWindowsBarFlash = true
    }

    if not profileData.alarms and helperConfig.alarms then
        -- Filtrar apenas campos validos
        profileData.alarms = {}
        for field, value in pairs(helperConfig.alarms) do
            if validAlarmFields[field] then
                profileData.alarms[field] = value
            end
        end
    elseif not profileData.alarms then
        -- Se nao existe, criar com valores padrao
        profileData.alarms = {
            alarmDamageTaken = false,
            alarmLowHealth = false,
            alarmLowHealthThreshold = 50,
            alarmMonsterOnScreen = false,
            alarmPlayerOnScreen = false,
            alarmPlayerSkullOnScreen = false,
            alarmPlayerAttack = false,
            alarmEnemyOnScreen = false,
            alarmSoundAlert = false,
            alarmWindowsBarFlash = false
        }
    else
        -- Filtrar campos invalidos do alarms existente
        local filteredAlarms = {}
        for field, value in pairs(profileData.alarms) do
            if validAlarmFields[field] then
                filteredAlarms[field] = value
            end
        end
        profileData.alarms = filteredAlarms
    end

    return profileData
end

local function buildProfileDataFromProfile(profile)
    local profileData = {}
    for k, v in pairs(profile) do
        if not isProfileExcludedKey(k) and not isCavebotKey(k) then
            profileData[k] = deepCopy(v)
        end
    end
    return profileData
end

local function setLineEditPlaceholder(lineEdit, text)
    if not lineEdit or not text or text == "" then
        return
    end

    if lineEdit.setPlaceholderText then
        lineEdit:setPlaceholderText(text)
    elseif lineEdit.setPlaceholder then
        lineEdit:setPlaceholder(text)
    else
        lineEdit:setText(text)
        if lineEdit.selectAll then
            lineEdit:selectAll()
        end
    end
end

function confirmNewProfile()
    local messageBox
    local cancel = function()
        if messageBox then
            messageBox:ok()
        end
    end

    local confirm = function()
        if messageBox then
            messageBox:ok()
        end
        createNewProfile()
    end

    messageBox = helperDisplayGeneralBox(
        "New Profile",
        "You will lose all current configuration. Do you want to continue?",
        {
            { text = "No",  callback = cancel },
            { text = "Yes", callback = confirm }
        }
    )
end

function createNewProfile()
    resetConfigToDefaults()
    reset()
    -- Limpar profile selecionado e carregado para indicar novo profile
    helperConfig.selectedProfile = ""
    helperSessionState.loadedProfile = nil
    helperSessionState.loadedProfileReadOnly = false
    helperConfig.profiles = helperConfig.profiles or {}
    saveSettings()
    scheduleEvent(function()
        isLoadingAlarmData = true
        onLoadHelperData()
        refreshProfilesList()
        updateCurrentProfileLabel()
    end, 50)

    modules.game_textmessage.displayGameMessage(htr("Helper reset. Start a new profile from scratch."))
end

function updateLoadedProfileLabel()
    local profileName = helperSessionState.loadedProfile or ""
    local readOnly = helperSessionState.loadedProfileReadOnly == true
    local text, color
    local dirtyMark = (_profileSaveInfo.dirty and profileName ~= "" and not readOnly) and " *" or ""

    if profileName == "" then
        text = "Profile: None"
        color = "#808080"
    elseif readOnly then
        text = "Profile: " .. profileName .. " (read-only)"
        color = "#4FC3F7" -- azul: lido para inspecao/clonagem, nao auto-salva
    elseif _profileSaveInfo.dirty then
        text = "Profile: " .. profileName .. dirtyMark
        color = "#FFB74D" -- laranja: ha mudancas nao salvas
    else
        text = "Profile: " .. profileName
        color = "#4CAF50"
    end

    -- Tooltip com timestamp do ultimo save (F2.2)
    local tooltip
    if profileName == "" then
        tooltip = "No profile loaded"
    elseif readOnly then
        tooltip = "Read-only: loaded for viewing/cloning.\nEdits are NOT auto-saved. Use Save or Clone to keep them."
    elseif _profileSaveInfo.dirty then
        tooltip = "Unsaved changes" ..
            (_profileSaveInfo.lastSaveLabel ~= "" and (" (last save: " .. _profileSaveInfo.lastSaveLabel .. ")") or "")
    elseif _profileSaveInfo.lastSaveLabel ~= "" then
        tooltip = "Saved at " .. _profileSaveInfo.lastSaveLabel
    else
        tooltip = "Profile loaded (not saved this session)"
    end

    -- Update label in header (main window top-left)
    if helper then
        local headerProfileLabel = helper:recursiveGetChildById("currentProfileLabel")
        if headerProfileLabel then
            headerProfileLabel:setText(text)
            headerProfileLabel:setColor(color)
            if headerProfileLabel.setTooltip then
                headerProfileLabel:setTooltip(tooltip)
            end
        end
    end

    -- Update "Loaded" label in profiles panel
    if profilesPanel then
        local loadedLabel = profilesPanel:recursiveGetChildById("loadedProfileLabel")
        if loadedLabel then
            local loadedText
            if profileName == "" then
                loadedText = "Loaded: None"
            elseif readOnly then
                loadedText = "Loaded: " .. profileName .. " (read-only)"
            else
                loadedText = "Loaded: " .. profileName .. dirtyMark
            end
            loadedLabel:setText(loadedText)
            loadedLabel:setColor(color)
            if loadedLabel.setTooltip then
                loadedLabel:setTooltip(tooltip)
            end
        end

        local lastSaveLabel = profilesPanel:recursiveGetChildById("lastSaveInfoLabel")
        if lastSaveLabel then
            local saveText, saveColor
            if profileName == "" then
                saveText  = "Last save: -"
                saveColor = "#808080"
            elseif readOnly then
                saveText  = "Read-only\n(use Save or Clone to keep edits)"
                saveColor = "#4FC3F7"
            elseif _profileSaveInfo.lastSaveLabel == "" then
                saveText  = "Last save: never this session"
                saveColor = "#808080"
            elseif _profileSaveInfo.dirty then
                saveText  = "Last save: " .. _profileSaveInfo.lastSaveLabel .. " (unsaved changes)"
                saveColor = "#FFB74D"
            else
                saveText  = "Last save: " .. _profileSaveInfo.lastSaveLabel
                saveColor = "#4CAF50"
            end
            lastSaveLabel:setText(saveText)
            lastSaveLabel:setColor(saveColor)
        end
    end
end

function updateSelectedProfileLabel()
    local profileName = helperConfig.selectedProfile or ""

    if profilesPanel then
        local selectedLabel = profilesPanel:recursiveGetChildById("selectedProfileLabel")
        if selectedLabel then
            if profileName == "" then
                selectedLabel:setText("Selected: None")
                selectedLabel:setColor("#808080")
            else
                selectedLabel:setText("Selected: " .. profileName)
                selectedLabel:setColor("#c0c0c0")
            end
        end
    end
end

-- Backward-compatible wrapper: updates both labels
function updateCurrentProfileLabel()
    updateLoadedProfileLabel()
    updateSelectedProfileLabel()
end

function resetConfigToDefaults()
    -- Manter configuracoes globais que nao devem ser resetadas
    local preservedConfig = {
        profiles = helperConfig.profiles,
        selectedProfile = helperConfig.selectedProfile or "", -- Preservar profile selecionado
        autoLoadProfileEnabled = helperConfig.autoLoadProfileEnabled,
        autoLoadProfileType = helperConfig.autoLoadProfileType,
        lastProfileLoadedByCharacter = helperConfig.lastProfileLoadedByCharacter,
        iconStats = helperConfig.iconStats -- Preservar iconStats (global, igual para todos chars)
    }

    -- Wipe completo: apaga TODA chave do helperConfig antes de aplicar defaults.
    -- Necessário porque profiles diferentes podem ter chaves diferentes — sem o wipe,
    -- chaves do profile anterior ausentes no novo profile vazam para o novo.
    for k in pairs(helperConfig) do
        helperConfig[k] = nil
    end

    -- Reaplica TODOS os defaults a partir do snapshot mestre (helperConfigDefaults),
    -- que é a única fonte de verdade. Mantém a função em sincronia automaticamente
    -- com qualquer novo campo adicionado em helperConfig.
    if type(helperConfigDefaults) == "table" then
        for k, v in pairs(helperConfigDefaults) do
            helperConfig[k] = deepCopy(v)
        end
    end

    -- Restaurar configuracoes que devem ser preservadas
    helperConfig.profiles = preservedConfig.profiles or {}
    helperConfig.selectedProfile = preservedConfig.selectedProfile
    helperConfig.autoLoadProfileEnabled = preservedConfig.autoLoadProfileEnabled
    helperConfig.autoLoadProfileType = preservedConfig.autoLoadProfileType
    helperConfig.lastProfileLoadedByCharacter = preservedConfig.lastProfileLoadedByCharacter
    if preservedConfig.iconStats then
        helperConfig.iconStats = preservedConfig.iconStats
    end
end

function getSelectedProfileFromLists()
    if not profilesPanel then return nil end
    local lists = { "profilesListBox" }
    for _, listId in ipairs(lists) do
        local listBox = profilesPanel:recursiveGetChildById(listId)
        if listBox then
            local selectedItem = listBox:getFocusedChild()
            if selectedItem then
                local name = selectedItem:getText()
                if name and name ~= "" then return name end
            end
        end
    end
    return nil
end

-- F1.3: separa a logica de troca propriamente dita para podermos
-- intercalar uma confirmacao quando ha mudancas nao salvas.
function performLoadSelectedProfile()
    -- Flush any pending auto-save on the CURRENT profile before swapping,
    -- so unwritten edits aren't lost when helperConfig is overwritten below.
    if flushProfileNow then
        flushProfileNow("profile-switch")
    end

    -- Verificar se ha um item selecionado em qualquer lista
    local selected = getSelectedProfileFromLists()
    if selected then
        helperConfig.selectedProfile = selected
    end

    if not helperConfig.selectedProfile or helperConfig.selectedProfile == "" then
        modules.game_textmessage.displayFailureMessage(htr("No profile selected. Select a profile in the list first."))
        return
    end

    local profileName = helperConfig.selectedProfile

    -- SEMPRE carregar do arquivo para garantir que temos os valores mais recentes
    -- Isso evita problemas de valores antigos em memoria
    local profile = loadProfileFromFile(profileName)
    if not profile then
        modules.game_textmessage.displayFailureMessage("Profile not found: " .. profileName)
        return
    end

    -- Atualizar na memoria apos carregar do arquivo
    helperConfig.profiles[profileName] = profile

    -- Removido: não salvar automaticamente o profile anterior ao trocar de profile
    -- local previousProfile = helperConfig.selectedProfile
    -- if previousProfile and previousProfile ~= "" and previousProfile ~= profileName then
    --     local profileData = {}
    --     for k, v in pairs(helperConfig) do
    --         if k ~= "profiles" and k ~= "selectedProfile" and k ~= "autoLoadProfileEnabled" and k ~= "autoLoadProfileType" then
    --             local isCavebot = false
    --             if type(k) == "string" then
    --                 local lowerK = k:lower()
    --                 if lowerK:find("cavebot") or lowerK:find("cave") then
    --                     isCavebot = true
    --                 end
    --             end
    --             if not isCavebot then
    --                 profileData[k] = deepCopy(v)
    --             end
    --         end
    --     end
    --     helperConfig.profiles[previousProfile] = profileData
    --     saveProfileToFile(previousProfile, profileData)
    -- end

    -- Resetar TODAS as configuracoes para valores padrao antes de carregar o profile
    resetConfigToDefaults()

    -- Resetar UI para limpar imagens das spells/potions/etc
    reset()

    -- Carregar profile (sobrepor TODAS as configs exceto cavebot e configuracoes globais)
    for k, v in pairs(profile) do
        if not isProfileExcludedKey(k) and not isCavebotKey(k) then
            helperConfig[k] = deepCopy(v)
        end
    end

    -- Garantir que helperConfig.alarms existe e tem todos os campos necessarios
    if not helperConfig.alarms or type(helperConfig.alarms) ~= "table" then
        helperConfig.alarms = {
            alarmDamageTaken = false,
            alarmLowHealth = false,
            alarmLowHealthThreshold = 50,
            alarmMonsterOnScreen = false,
            alarmPlayerOnScreen = false,
            alarmPlayerSkullOnScreen = false,
            alarmPlayerAttack = false,
            alarmEnemyOnScreen = false,
            alarmSoundAlert = false,
            alarmWindowsBarFlash = false
        }
    else
        -- Normalizar valores do profile
        helperConfig.alarms.alarmDamageTaken = helperConfig.alarms.alarmDamageTaken == true
        helperConfig.alarms.alarmLowHealth = helperConfig.alarms.alarmLowHealth == true
        helperConfig.alarms.alarmLowHealthThreshold = tonumber(helperConfig.alarms.alarmLowHealthThreshold) or 50
        helperConfig.alarms.alarmMonsterOnScreen = helperConfig.alarms.alarmMonsterOnScreen == true
        helperConfig.alarms.alarmPlayerOnScreen = helperConfig.alarms.alarmPlayerOnScreen == true
        helperConfig.alarms.alarmPlayerSkullOnScreen = helperConfig.alarms.alarmPlayerSkullOnScreen == true
        helperConfig.alarms.alarmPlayerAttack = helperConfig.alarms.alarmPlayerAttack == true
        helperConfig.alarms.alarmEnemyOnScreen = helperConfig.alarms.alarmEnemyOnScreen == true
        helperConfig.alarms.alarmSoundAlert = helperConfig.alarms.alarmSoundAlert == true
        helperConfig.alarms.alarmWindowsBarFlash = helperConfig.alarms.alarmWindowsBarFlash == true
    end

    ensureHealingSlots(helperConfig)
    ensureEquipmentSwapConfig(EQUIPMENT_SWAP_DEFAULT_SLOT_COUNT)
    ensureTimerConfig(TIMER_DEFAULT_RULE_COUNT)

    if helperConfig.magicHelperEnabled == nil and helperConfig.enableMagicHelper ~= nil then
        helperConfig.magicHelperEnabled = helperConfig.enableMagicHelper
    end
    helperConfig.enableMagicHelper = nil

    -- Atualizar selectedProfile
    helperConfig.selectedProfile = profileName

    -- Guardar nome do personagem que carregou este profile
    local player = g_game.getLocalPlayer()
    if player then
        helperConfig.lastProfileLoadedByCharacter = player:getName()

        -- Registrar sessão ativa
        helperSessionState.currentCharacter = player:getName()
        helperSessionState.loadedProfile = profileName
        helperSessionState.isSessionActive = true
    end

    -- LEITURA SEGURA (read-only): o Load apenas LE o profile para a tela
    -- (visualizar / clonar). NAO arma o autosave, para que editar ou fechar
    -- nunca grave por cima do profile lido. Para persistir, o usuario usa
    -- Save ou Clone (que armam o autosave explicitamente). Mantemos o
    -- startProfileAutosave so para semear o baseline; como nada esta armado,
    -- nenhum flush vai para o disco.
    helperSessionState.loadedProfileReadOnly = true
    -- Disarma qualquer autosave de um profile anterior (ex.: o profile proprio
    -- carregado no login) e re-semeia o baseline a partir do profile lido. Em
    -- read-only fica DESarmado, para o flag e o estado armado nunca divergirem.
    if resetProfileAutosaveState then
        resetProfileAutosaveState()
    end
    if startProfileAutosave then
        startProfileAutosave()
    end
    -- F1.2: profile recem carregado === sem mudancas pendentes.
    if markProfileLoadedClean then
        markProfileLoadedClean()
    end
    pcall(function()
        g_logger.info(_profileSaveInfo.prefix ..
            " loaded trigger=manual-readonly profile=" .. tostring(profileName))
    end)

    -- Recarregar interface com delay para garantir que UI foi resetada
    scheduleEvent(function()
        isLoadingAlarmData = true
        onLoadHelperData()
        refreshProfilesList()
        updateCurrentProfileLabel()

        -- Pré-carregar o cavebot que estava ativo quando o profile foi salvo.
        -- Não liga o Enable Cavebot — só deixa o script carregado na memória/UI.
        local preloadName = helperConfig.loadedCavebotName
        if type(preloadName) == "string" and preloadName ~= "" then
            local recorder = hunting_recorderModule or
                (_G and _G.hunting_recorderModule) or
                (modules and modules.game_helper and modules.game_helper.hunting_recorderModule)
            local cavebotFile = "/helper/cavebots/" .. preloadName .. ".json"
            if recorder and recorder.loadCavebotByName and g_resources.fileExists(cavebotFile) then
                pcall(function() recorder.loadCavebotByName(preloadName) end)
            end
        end
    end, 50)

    applyEngineIntervalsFromConfig()
    if refreshEngineSettingsUI then refreshEngineSettingsUI() end

    modules.game_textmessage.displayGameMessage("Profile loaded: " .. profileName)
end

-- F1.3: wrapper publico. Intercepta o Load para perguntar antes se ha
-- mudancas nao salvas no profile ativo. Sem dirty -> Load direto.
function loadSelectedProfile()
    -- Forca o calculo do dirty mais atual antes de decidir.
    if recomputeProfileDirty then
        pcall(function() recomputeProfileDirty(true) end)
    end

    local activeProfile = (helperSessionState and helperSessionState.loadedProfile) or ""
    local hasUnsaved = isProfileDirty and isProfileDirty() or false

    if not hasUnsaved or activeProfile == "" then
        performLoadSelectedProfile()
        return
    end

    local selected = getSelectedProfileFromLists() or ""
    if selected == activeProfile then
        -- Recarregar o mesmo profile descarta as mudancas locais
        -- por design -- ainda assim pede confirmacao.
    end

    local messageBox
    messageBox = helperDisplayGeneralBox(
        "Unsaved Changes",
        "Profile '" .. activeProfile .. "' has unsaved changes.\n" ..
        "Save before loading '" .. (selected ~= "" and selected or "another profile") .. "'?",
        {
            {
                text = "Save & Load",
                callback = function()
                    messageBox:ok()
                    pcall(function()
                        if saveCurrentProfileQuick then
                            saveCurrentProfileQuick()
                        elseif flushProfileNow then
                            flushProfileNow("pre-load-confirm")
                        end
                    end)
                    scheduleEvent(performLoadSelectedProfile, 50)
                end
            },
            {
                text = "Discard & Load",
                callback = function()
                    messageBox:ok()
                    performLoadSelectedProfile()
                end
            },
            {
                text = "Cancel",
                callback = function()
                    messageBox:ok()
                end
            }
        },
        function() end,
        function() end
    )
end

function deleteProfileByName(profileName)
    if not profileName or profileName == "" then
        return
    end

    local messageBox
    messageBox = helperDisplayGeneralBox(
        "Delete Profile",
        "Are you sure you want to delete the profile '" .. profileName .. "'?",
        {
            {
                text = "Cancel",
                callback = function()
                    messageBox:ok()
                end
            },
            {
                text = "Delete",
                callback = function()
                    local wasActive = helperConfig.selectedProfile == profileName

                    -- If the active profile is being deleted, drop pending flush
                    -- and reset the auto-save baseline so the next profile
                    -- doesn't inherit a stale hash.
                    if wasActive and resetProfileAutosaveState then
                        resetProfileAutosaveState()
                    end

                    local profilesDir = "/helper/profiles"
                    local profileFile = profilesDir .. "/" .. profileName .. ".json"

                    -- F3.4: nao apaga direto. Move .json + todos os .bak.N para
                    -- /helper/profiles/.trash/{profileName}-{timestamp}/ pra que
                    -- o usuario possa recuperar via "Restore" depois.
                    local deleted = false
                    pcall(function()
                        local trashRoot = profilesDir .. "/.trash"
                        if not g_resources.directoryExists(trashRoot) then
                            g_resources.makeDir(trashRoot)
                        end
                        local stamp = os.date("%Y%m%d-%H%M%S")
                        local trashDir = trashRoot .. "/" .. profileName .. "-" .. tostring(stamp)
                        if not g_resources.directoryExists(trashDir) then
                            g_resources.makeDir(trashDir)
                        end

                        local function moveTo(src, dstName)
                            if not g_resources.fileExists(src) then return end
                            local ok, contents = pcall(function()
                                return g_resources.readFileContents(src)
                            end)
                            if not ok or type(contents) ~= "string" then return end
                            pcall(function()
                                g_resources.writeFileContents(trashDir .. "/" .. dstName, contents)
                            end)
                            pcall(function() g_resources.deleteFile(src) end)
                        end

                        moveTo(profileFile, profileName .. ".json")
                        for i = 1, 3 do
                            moveTo(profileFile .. ".bak." .. tostring(i),
                                profileName .. ".json.bak." .. tostring(i))
                        end
                        moveTo(profileFile .. ".bak", profileName .. ".json.bak")
                        moveTo(profileFile .. ".new", profileName .. ".json.new")

                        deleted = not g_resources.fileExists(profileFile)
                        g_logger.info(_profileSaveInfo.prefix ..
                            " deleted profile=" .. tostring(profileName) ..
                            " trashed=" .. tostring(trashDir))
                    end)

                    -- Limpeza retroativa: descarta lixeiras com mais de 7 dias.
                    pcall(function()
                        purgeProfileTrashOlderThan(7 * 24 * 60 * 60)
                    end)

                    if helperConfig.profiles then
                        helperConfig.profiles[profileName] = nil
                    end

                    if wasActive then
                        helperConfig.selectedProfile = ""
                    end
                    if helperSessionState.loadedProfile == profileName then
                        helperSessionState.loadedProfile = nil
                        helperSessionState.loadedProfileReadOnly = false
                        resetConfigToDefaults()
                        reset()
                    end

                    saveSettings()
                    scheduleEvent(function()
                        isLoadingAlarmData = true
                        refreshProfilesList()
                        updateCurrentProfileLabel()
                        onLoadHelperData()
                    end, 100)

                    modules.game_textmessage.displayGameMessage("Profile '" .. profileName .. "' deleted successfully.")
                    messageBox:ok()
                end
            }
        }
    )
end

-- ==================== CLONE PROFILE ====================
-- "Ler para duplicar": cria uma copia do profile selecionado com um novo nome,
-- SEM tocar no original e SEM depender do Load (que agora e leitura read-only).
-- Por decisao do usuario, o clone ja vira o profile ATIVO (armado para autosave),
-- pois e uma criacao explicita.
function validateProfileName(name)
    name = name and tostring(name):trim() or ""
    if name == "" then
        return false, nil, htr("Profile name cannot be empty.")
    end
    if #name > 64 then
        return false, nil, htr("Profile name is too long (max 64 characters).")
    end
    if name == "Default" then
        return false, nil, htr("'Default' is a reserved profile name.")
    end
    -- O nome vira "<name>.json" direto no VFS, sem sanitizacao. Barra qualquer
    -- caractere que possa quebrar o caminho do arquivo.
    if name:match('[/\\:%*%?"<>|%c]') then
        return false, nil, htr("Profile name has invalid characters.")
    end
    return true, name, nil
end

function performCloneProfile(source, newName, sourceProfile)
    if type(sourceProfile) ~= "table" then
        sourceProfile = loadProfileFromFile(source)
    end
    if type(sourceProfile) ~= "table" then
        modules.game_textmessage.displayFailureMessage("Profile not found: " .. tostring(source))
        return
    end

    -- Dados do clone a partir da FONTE (ja exclui chaves globais e de cavebot).
    local cloneData = buildProfileDataFromProfile(sourceProfile)

    -- Se havia um profile proprio armado com edicoes pendentes, persiste antes
    -- de trocar. Num read-only nada esta armado, entao isso e no-op seguro.
    if flushProfileNow then
        pcall(function() flushProfileNow("pre-clone") end)
    end

    -- Se o destino ja existe (clone por cima de um profile existente, confirmado
    -- pelo dialogo de Overwrite), rotaciona um backup recuperavel ANTES de
    -- sobrescrever -- saveProfileToFile nao faz backup proprio. Assim o Restore
    -- consegue recuperar a versao anterior via .bak.1.
    local clonePath = "/helper/profiles/" .. newName .. ".json"
    if g_resources.fileExists(clonePath) then
        pcall(function()
            rotateProfileBackups(clonePath)
            copyFileIfExists(clonePath, clonePath .. ".bak.1")
            copyFileIfExists(clonePath, clonePath .. ".bak")
        end)
    end

    -- Grava o arquivo do clone no disco.
    local saved = saveProfileToFile(newName, cloneData)
    if not saved then
        modules.game_textmessage.displayFailureMessage("Failed to save profile: " .. tostring(newName))
        return
    end

    helperConfig.profiles = helperConfig.profiles or {}
    helperConfig.profiles[newName] = cloneData

    -- Q2: carrega o clone como profile ATIVO. Adota a config e ARMA o autosave
    -- (clone = profile novo, criado por acao explicita do usuario).
    resetConfigToDefaults()
    reset()
    for k, v in pairs(cloneData) do
        if not isProfileExcludedKey(k) and not isCavebotKey(k) then
            helperConfig[k] = deepCopy(v)
        end
    end
    ensureHealingSlots(helperConfig)
    ensureEquipmentSwapConfig(EQUIPMENT_SWAP_DEFAULT_SLOT_COUNT)
    ensureTimerConfig(TIMER_DEFAULT_RULE_COUNT)

    helperConfig.selectedProfile = newName
    helperSessionState.loadedProfile = newName
    helperSessionState.loadedProfileReadOnly = false
    local player = g_game.getLocalPlayer()
    if player then
        helperConfig.lastProfileLoadedByCharacter = player:getName()
        helperSessionState.currentCharacter = player:getName()
        helperSessionState.isSessionActive = true
    end

    saveConfigOnly()
    if startProfileAutosave then startProfileAutosave() end
    if armProfileAutosave then armProfileAutosave() end
    if markProfileSavedNow then markProfileSavedNow(newName) end
    pcall(function()
        g_logger.info(_profileSaveInfo.prefix ..
            " cloned source=" .. tostring(source) ..
            " new=" .. tostring(newName) .. " loaded=active")
    end)

    scheduleEvent(function()
        isLoadingAlarmData = true
        onLoadHelperData()
        refreshProfilesList()
        updateCurrentProfileLabel()
    end, 50)

    modules.game_textmessage.displayGameMessage(htr("Profile cloned: %s -> %s", source, newName))
end

function cloneSelectedProfile()
    local source = getSelectedProfileFromLists()
    if not source or source == "" then
        modules.game_textmessage.displayFailureMessage(
            htr("No profile selected. Select a profile in the list first."))
        return
    end

    -- Carrega a fonte do disco (clona o profile salvo, nao a config atual em memoria).
    local sourceProfile = loadProfileFromFile(source)
    if type(sourceProfile) ~= "table" and helperConfig.profiles then
        sourceProfile = helperConfig.profiles[source]
    end
    if type(sourceProfile) ~= "table" then
        modules.game_textmessage.displayFailureMessage("Profile not found: " .. tostring(source))
        return
    end

    local suggested = source .. " copy"

    local inputBox = HelperUIInputBox.create(htr("Clone Profile"), function(text)
        local trimmed = text and tostring(text):trim() or ""
        if trimmed == "" then
            trimmed = suggested
        end
        local ok, cleanName, err = validateProfileName(trimmed)
        if not ok then
            modules.game_textmessage.displayFailureMessage(err or htr("Invalid profile name."))
            return
        end
        if cleanName == source then
            modules.game_textmessage.displayFailureMessage(
                htr("The clone must use a different name than the source."))
            return
        end

        local function doClone()
            performCloneProfile(source, cleanName, sourceProfile)
        end

        if (helperConfig.profiles and helperConfig.profiles[cleanName]) or
            g_resources.fileExists("/helper/profiles/" .. cleanName .. ".json") then
            local messageBox
            messageBox = helperDisplayGeneralBox(
                htr("Overwrite Profile?"),
                htr("A profile named '%s' already exists. Overwrite it?", cleanName),
                {
                    {
                        text = htr("Overwrite"),
                        callback = function()
                            messageBox:ok()
                            doClone()
                        end
                    },
                    {
                        text = htr("Cancel"),
                        callback = function()
                            messageBox:ok()
                        end
                    }
                },
                function() end,
                function() end
            )
        else
            doClone()
        end
    end, function() end)

    local nameEdit = inputBox:addLineEdit(htr("New profile name:"), "")
    setLineEditPlaceholder(nameEdit, suggested)
    inputBox:display(htr("Clone"), htr("Cancel"))
end

-- ==================== END CLONE PROFILE ====================

function importProfileIntoCurrent(sourceProfileName, targetProfileName)
    if not sourceProfileName or sourceProfileName == "" then
        return
    end

    local targetProfileName = targetProfileName or helperConfig.selectedProfile or ""
    if targetProfileName == "" then
        modules.game_textmessage.displayFailureMessage(htr("No current profile selected. Load or save a profile first."))
        return
    end

    helperConfig.profiles = helperConfig.profiles or {}

    if sourceProfileName == targetProfileName then
        modules.game_textmessage.displayFailureMessage(htr("Source profile is already the current profile."))
        return
    end

    local sourceProfile = helperConfig.profiles and helperConfig.profiles[sourceProfileName]
    if not sourceProfile then
        sourceProfile = loadProfileFromFile(sourceProfileName)
        if sourceProfile then
            helperConfig.profiles[sourceProfileName] = sourceProfile
        end
    end

    if not sourceProfile then
        modules.game_textmessage.displayFailureMessage("Profile not found: " .. sourceProfileName)
        return
    end

    local importedData = buildProfileDataFromProfile(sourceProfile)

    resetConfigToDefaults()
    reset()

    for k, v in pairs(importedData) do
        helperConfig[k] = deepCopy(v)
    end

    ensureHealingSlots(helperConfig)
    ensureEquipmentSwapConfig(EQUIPMENT_SWAP_DEFAULT_SLOT_COUNT)
    ensureTimerConfig(TIMER_DEFAULT_RULE_COUNT)

    helperConfig.selectedProfile = targetProfileName
    helperSessionState.loadedProfile = targetProfileName
    helperSessionState.loadedProfileReadOnly = false
    helperConfig.profiles[targetProfileName] = importedData

    local saved = saveProfileToFile(targetProfileName, importedData)
    if saved then
        saveSettings()
        if startProfileAutosave then
            startProfileAutosave()
        end
        if armProfileAutosave then
            armProfileAutosave()
        end
    else
        modules.game_textmessage.displayFailureMessage("Failed to save profile: " .. targetProfileName)
    end

    scheduleEvent(function()
        isLoadingAlarmData = true
        onLoadHelperData()
        refreshProfilesList()
        updateCurrentProfileLabel()
    end, 50)

    modules.game_textmessage.displayGameMessage("Imported settings from " ..
    sourceProfileName .. " into " .. targetProfileName)
end

function saveCurrentProfile()
    helperConfig.profiles = helperConfig.profiles or {}

    local player = g_game.getLocalPlayer()
    local characterName = ""
    if player then
        characterName = player:getName() or ""
    end

    local function saveProfile(profileName)
        if profileName == "" then
            modules.game_textmessage.displayFailureMessage(htr("Profile name cannot be empty."))
            return
        end

        -- Atualizar configuracoes de alarmes dos checkboxes antes de salvar
        updateAlarmSettings()

        local profileData = buildProfileDataFromConfig()
        helperConfig.profiles[profileName] = profileData
        helperConfig.selectedProfile = profileName
        helperSessionState.loadedProfile = profileName
        helperSessionState.loadedProfileReadOnly = false

        local saved = saveProfileToFile(profileName, profileData)
        if saved then
            saveConfigOnly() -- Salva apenas metadados, nao todos os profiles
            -- Re-seed the auto-save baseline from the freshly written file
            -- and arm the auto-saver so follow-up edits trigger real saves.
            if startProfileAutosave then
                startProfileAutosave()
            end
            if armProfileAutosave then
                armProfileAutosave()
            end
            -- F1.2/F2.2/F2.4: marcar limpo + timestamp + log.
            if markProfileSavedNow then
                markProfileSavedNow(profileName)
            end
            pcall(function()
                g_logger.info(_profileSaveInfo.prefix ..
                    " saved trigger=manual profile=" .. tostring(profileName))
            end)
            scheduleEvent(function()
                refreshProfilesList()
                updateCurrentProfileLabel()
            end, 100)
            modules.game_textmessage.displayGameMessage("Profile saved: " .. profileName)
        else
            modules.game_textmessage.displayFailureMessage("Failed to save profile: " .. profileName)
        end
    end

    local function confirmOverwrite(profileName)
        if helperConfig.profiles[profileName] or g_resources.fileExists("/helper/profiles/" .. profileName .. ".json") then
            local messageBox
            messageBox = helperDisplayGeneralBox(
                "Overwrite Profile?",
                "The profile '" .. profileName .. "' already exists. Overwrite it?",
                {
                    {
                        text = "Overwrite",
                        callback = function()
                            messageBox:ok()
                            saveProfile(profileName)
                        end
                    },
                    {
                        text = "Cancel",
                        callback = function()
                            messageBox:ok()
                        end
                    }
                },
                function() end,
                function() end
            )
        else
            saveProfile(profileName)
        end
    end

    -- Vocation profiles were removed; Save asks for a profile name directly.
    local inputBox = HelperUIInputBox.create("Save Profile", function(text)
        local profileName = text and text:trim() or ""
        if profileName == "" then
            if characterName ~= "" then
                profileName = characterName
            else
                modules.game_textmessage.displayFailureMessage(htr("Profile name cannot be empty."))
                return
            end
        end

        confirmOverwrite(profileName)
    end, function() end)

    local nameEdit = inputBox:addLineEdit("Profile Name:", "")
    setLineEditPlaceholder(nameEdit, characterName)
    inputBox:display(tr("Save"), tr("Cancel"))
end

function saveCurrentProfileQuick()
    helperConfig.profiles = helperConfig.profiles or {}

    -- Se o profile atual foi apenas LIDO (read-only), o quick-save NAO sobrescreve
    -- a fonte silenciosamente: encaminha para o Save normal (com escolha de nome),
    -- para o usuario decidir conscientemente onde gravar.
    if helperSessionState.loadedProfileReadOnly == true then
        saveCurrentProfile()
        return
    end

    local currentProfile = helperSessionState.loadedProfile or ""
    local profileExists = false

    if currentProfile ~= "" then
        if helperConfig.profiles[currentProfile] or g_resources.fileExists("/helper/profiles/" .. currentProfile .. ".json") then
            profileExists = true
        end
    end

    local function saveProfile(profileName)
        if profileName == "" then
            modules.game_textmessage.displayFailureMessage(htr("Profile name cannot be empty."))
            return
        end

        -- Atualizar configuracoes de alarmes dos checkboxes antes de salvar
        updateAlarmSettings()

        local profileData = buildProfileDataFromConfig()
        helperConfig.profiles[profileName] = profileData
        helperConfig.selectedProfile = profileName
        helperSessionState.loadedProfile = profileName
        helperSessionState.loadedProfileReadOnly = false

        local saved = saveProfileToFile(profileName, profileData)
        if saved then
            saveConfigOnly() -- Salva apenas metadados, nao todos os profiles
            -- Re-seed the auto-save baseline from the freshly written file
            -- and arm the auto-saver so follow-up edits trigger real saves.
            if startProfileAutosave then
                startProfileAutosave()
            end
            if armProfileAutosave then
                armProfileAutosave()
            end
            -- F1.2/F2.2/F2.4
            if markProfileSavedNow then
                markProfileSavedNow(profileName)
            end
            pcall(function()
                g_logger.info(_profileSaveInfo.prefix ..
                    " saved trigger=quick profile=" .. tostring(profileName))
            end)
            scheduleEvent(function()
                refreshProfilesList()
                updateCurrentProfileLabel()
            end, 100)
            modules.game_textmessage.displayGameMessage("Profile saved: " .. profileName)
        else
            modules.game_textmessage.displayFailureMessage("Failed to save profile: " .. profileName)
        end
    end

    if profileExists then
        saveProfile(currentProfile)
    else
        local player = g_game.getLocalPlayer()
        local characterName = ""
        if player then
            characterName = player:getName() or ""
        end

        if characterName ~= "" then
            saveProfile(characterName)
        else
            modules.game_textmessage.displayFailureMessage(htr("Profile name cannot be empty."))
        end
    end
end

function deleteSelectedProfile()
    -- Verificar se ha um item selecionado em qualquer lista
    local selected = getSelectedProfileFromLists()
    if selected then
        helperConfig.selectedProfile = selected
    end

    if not helperConfig.selectedProfile or helperConfig.selectedProfile == "" then
        modules.game_textmessage.displayFailureMessage(htr("No profile selected. Select a profile in the list first."))
        return
    end

    deleteProfileByName(helperConfig.selectedProfile)
end

-- Salva apenas as configuracoes globais de auto-load (pode ser chamado sem player logado)
function saveAutoLoadSettings()
    local readFile = getHelperConfigReadFile()
    local writeFile = getHelperConfigWriteFile()
    local configToSave = {}

    -- Tentar carregar config existente para preservar outras configuracoes.
    -- Lê do read file (per-char se existir; senão legacy) para que o write
    -- per-char herde os dados da legacy na primeira gravação.
    if g_resources.fileExists(readFile) then
        local status, result = pcall(
            function()
                return json.decode(g_resources.readFileContents(readFile))
            end
        )
        if status and result then
            configToSave = result
        end
    end

    -- Atualizar apenas as configuracoes de auto-load
    configToSave.autoLoadProfileEnabled = helperConfig.autoLoadProfileEnabled or false
    configToSave.autoLoadProfileType = helperConfig.autoLoadProfileType or "name"
    configToSave.autoSaveProfileEnabled = helperConfig.autoSaveProfileEnabled ~= false

    -- Garantir que profilesList existe
    if not configToSave.profilesList then
        configToSave.profilesList = {}
    end

    -- Garantir que selectedProfile existe
    if not configToSave.selectedProfile then
        configToSave.selectedProfile = helperConfig.selectedProfile or ""
    end

    -- Garantir que lastProfileLoadedByCharacter existe
    if not configToSave.lastProfileLoadedByCharacter then
        configToSave.lastProfileLoadedByCharacter = helperConfig.lastProfileLoadedByCharacter or ""
    end

    -- Salvar no arquivo
    local status, result = pcall(
        function()
            return json.encode(configToSave, 2)
        end
    )

    if not status then
        return false
    end

    if result:len() > 100 * 1024 * 1024 then
        return false
    end

    local writeStatus = g_resources.writeFileContents(writeFile, result)
    return writeStatus
end

function onEnableAutoLoadProfile(checked)
    helperConfig.autoLoadProfileEnabled = checked
    saveAutoLoadSettings()
    -- Tambem tentar salvar settings completas se player estiver logado
    local player = g_game.getLocalPlayer()
    if player then
        saveSettings()
    end
end

function onEnableAutoSaveProfile(checked)
    local enabling = checked and true or false
    local previous = helperConfig.autoSaveProfileEnabled

    -- F2.1: ao DESLIGAR, garantir um flush sincrono pra nao perder edicoes
    -- que dependiam do autosave em logout/close. Faz o flush ANTES de
    -- atualizar a flag (flushProfileNow checa autoSaveProfileEnabled e
    -- aborta se ja estiver false).
    if previous == true and enabling == false then
        if flushProfileNow then
            pcall(function() flushProfileNow("autosave-toggle-off") end)
        end
    end

    helperConfig.autoSaveProfileEnabled = enabling

    -- F2.1: ao LIGAR, se ja ha um profile carregado, armar o autosave
    -- (caso contrario, primeiro toggle nao "pega" ate proximo load/save).
    -- Excecao: profile aberto em modo read-only (so leitura/clonagem) NAO arma,
    -- para nao comecar a gravar por cima dele. So persiste via Save/Clone.
    if enabling and not previous then
        local activeProfile = (helperSessionState and helperSessionState.loadedProfile) or ""
        if activeProfile ~= "" and armProfileAutosave and not helperSessionState.loadedProfileReadOnly then
            if startProfileAutosave then
                pcall(startProfileAutosave)
            end
            armProfileAutosave()
        end
    end

    saveAutoLoadSettings()
    local player = g_game.getLocalPlayer()
    if player then
        saveSettings()
    end

    pcall(function()
        g_logger.info(_profileSaveInfo.prefix ..
            " autoSave toggle=" .. tostring(enabling) ..
            " armed=" .. tostring(isProfileAutosaveArmed and isProfileAutosaveArmed() or false))
    end)
end

function onAutoLoadByNameChange(checked)
    if checked then
        helperConfig.autoLoadProfileType = "name"
        saveAutoLoadSettings()
        -- Tambem tentar salvar settings completas se player estiver logado
        local player = g_game.getLocalPlayer()
        if player then
            saveSettings()
        end
    end
end

function onAutoLoadTypeChange(type)
    -- Vocation profiles were removed: "name" is the only valid auto-load type.
    helperConfig.autoLoadProfileType = "name"
    if profilesPanel and autoLoadRadioGroup then
        local autoLoadByName = profilesPanel:recursiveGetChildById("autoLoadByName")
        if autoLoadByName then
            autoLoadRadioGroup:selectWidget(autoLoadByName)
        end
    end
    saveAutoLoadSettings()
    local player = g_game.getLocalPlayer()
    if player then
        saveSettings()
    end
end

function ensureProfilesDirectory()
    local helperDir = "/helper"
    local profilesDir = helperDir .. "/profiles"

    -- Criar diretorios se nao existirem
    if not g_resources.directoryExists(helperDir) then
        g_resources.makeDir(helperDir)
    end

    if not g_resources.directoryExists(profilesDir) then
        g_resources.makeDir(profilesDir)
    end

    return profilesDir
end

function listProfileFiles()
    local profilesDir = "/helper/profiles"
    local configFile = getHelperConfigReadFile()

    local profiles = {}

    if g_resources.fileExists(configFile) then
        local status, result = pcall(
            function()
                return json.decode(g_resources.readFileContents(configFile))
            end
        )

        if status and result and result.profilesList then
            for _, profileName in ipairs(result.profilesList) do
                local profileFile = profilesDir .. "/" .. profileName .. ".json"
                if g_resources.fileExists(profileFile) then
                    table.insert(profiles, profileName)
                end
            end
        end
    end

    return profiles
end

function openProfilesFolder()
    local writeDir = g_resources.getWriteDir()
    if not writeDir then
        modules.game_textmessage.displayFailureMessage(htr("Unable to determine the write directory."))
        return
    end

    -- Converter caminho virtual para caminho real do sistema
    local profilesDir = writeDir:gsub("[/\\]+", "\\") .. "helper\\profiles"

    local success = g_platform.openDir(profilesDir)
    if success then
        modules.game_textmessage.displayGameMessage("Folder opened: " .. profilesDir)
    else
        modules.game_textmessage.displayFailureMessage("Failed to open folder: " .. profilesDir)
    end
end

-- ==================== PROFILE AUTO-SAVE ====================
-- Event-driven auto-save of the active profile. Triggers on explicit
-- events only: helper window close, profile switch, manual save, logout,
-- client shutdown. No debounce, no background ticks, no per-keystroke
-- dirty tracking. A hash gate ensures we skip the write if the content
-- is identical to what's on disk. Writes use .new + .bak so a crash
-- mid-write leaves at least one intact copy on disk.

local _lastSavedProfileHash  = nil
local _lastSavedProfileName  = nil
local _lastSavedProfileBytes = nil
local _isFlushingProfile     = false
-- Only true after a profile has been explicitly loaded into helperConfig
-- (or saved manually by the user). Prevents the first flush after login
-- from overwriting an existing profile file with default/empty state when
-- the profile has not actually been loaded yet (e.g. autoLoad disabled).
local _profileAutosaveArmed  = false

-- F1.2 / F2.2 / F2.3 / F2.4: dirty + timestamp + log + backup infra.
-- GLOBAL (sem `local`) porque o main chunk ja esta no limite de 200 locals do Lua.
-- `prefix` e `backupSlots` sao constantes; campos restantes mutam em runtime.
_profileSaveInfo             = {
    dirty         = false,
    dirtyCheckMs  = 0,
    lastSaveMs    = 0,  -- g_clock.millis() do ultimo save bem sucedido
    lastSaveLabel = "", -- "HH:MM:SS" do ultimo save (humanizado)
    prefix        = "[Profile]",
    backupSlots   = 3,  -- F2.3: manter .bak.1 .. .bak.3 rotativos
}

local PROFILE_MAX_BYTES      = 100 * 1024 * 1024

local function djb2Hash(str)
    if type(str) ~= "string" or str == "" then
        return 0
    end
    local h = 5381
    for i = 1, #str do
        h = (h * 33 + str:byte(i)) % 4294967296
    end
    return h
end

-- Deterministic fingerprint for change detection.
-- json.encode uses pairs() for string-keyed tables, so the same data can
-- produce different byte strings across calls. Hashing that would make
-- the safety-net tick falsely detect "changes" on every run. This walks
-- the profile table with sorted keys and stable primitive encoding, so
-- equal data → equal fingerprint, every time.
local function canonicalFingerprint(val)
    local t = type(val)
    if t == "nil" then return "N" end
    if t == "boolean" then return val and "T" or "F" end
    if t == "number" then return "#" .. string.format("%.14g", val) end
    if t == "string" then return "$" .. val end
    if t == "table" then
        local maxIdx = 0
        local isArray = true
        for k in pairs(val) do
            if type(k) == "number" and k == math.floor(k) and k > 0 then
                if k > maxIdx then maxIdx = k end
            else
                isArray = false
                break
            end
        end
        if isArray and maxIdx > 0 then
            local parts = {}
            for i = 1, maxIdx do
                parts[i] = canonicalFingerprint(val[i])
            end
            return "[" .. table.concat(parts, ",") .. "]"
        end
        local keys = {}
        for k in pairs(val) do
            keys[#keys + 1] = tostring(k)
        end
        table.sort(keys)
        local parts = {}
        for i, k in ipairs(keys) do
            parts[i] = k .. "=" .. canonicalFingerprint(val[k])
        end
        return "{" .. table.concat(parts, ";") .. "}"
    end
    return "?"
end

-- Mirror the exact post-build mutations that saveProfileToFile performs
-- before writing, so auto-save produces byte-identical output and the
-- hash comparisons stay stable across manual saves and auto saves.
local function prepareProfileDataForDisk(profileData)
    if type(profileData) ~= "table" then
        return
    end
    profileData.autoLoadProfileEnabled = nil
    profileData.autoLoadProfileType = nil
    profileData.profiles = nil
    profileData.selectedProfile = nil
    profileData.holdAttackTargetId = nil
    profileData.holdAttackTargetName = nil
    profileData.iconStats = nil
    profileData._schemaVersion = nil
    if modules.game_healthcircle and modules.game_healthcircle.exportConditionSettings then
        local ok, cond = pcall(modules.game_healthcircle.exportConditionSettings)
        if ok and type(cond) == "table" then
            profileData.conditionSettings = cond
        end
    end
end

local function isAutosaveProfileName(name)
    return type(name) == "string" and name ~= "" and name ~= "Default"
end

local function encodeProfileForAutosave(profileData)
    local ok, encoded = pcall(function()
        return json.encode(profileData, 2)
    end)
    if not ok or type(encoded) ~= "string" then
        return nil
    end
    if #encoded > PROFILE_MAX_BYTES then
        return nil
    end
    return encoded
end

local function profileFilePath(profileName)
    return "/helper/profiles/" .. profileName .. ".json"
end

-- F2.3: helpers globais (chunk no limite de 200 locals).
function copyFileIfExists(srcPath, dstPath)
    if not g_resources.fileExists(srcPath) then
        return false
    end
    local ok, contents = pcall(function()
        return g_resources.readFileContents(srcPath)
    end)
    if not ok or type(contents) ~= "string" or contents == "" then
        return false
    end
    local writeOk = pcall(function()
        g_resources.writeFileContents(dstPath, contents)
    end)
    return writeOk
end

-- F2.3: rotaciona .bak.{N-1} -> .bak.N, .bak.{N-2} -> .bak.{N-1}, ..., desce
-- ate .bak.1 ficar livre. O caller grava o conteudo novo em .bak.1 depois.
function rotateProfileBackups(finalPath)
    -- Apaga slot mais antigo
    local oldest = finalPath .. ".bak." .. tostring(_profileSaveInfo.backupSlots)
    if g_resources.fileExists(oldest) then
        pcall(function() g_resources.deleteFile(oldest) end)
    end
    -- Sobe N-1 -> N, N-2 -> N-1, ... 1 -> 2
    for i = _profileSaveInfo.backupSlots - 1, 1, -1 do
        local src = finalPath .. ".bak." .. tostring(i)
        local dst = finalPath .. ".bak." .. tostring(i + 1)
        if g_resources.fileExists(src) then
            copyFileIfExists(src, dst)
            pcall(function() g_resources.deleteFile(src) end)
        end
    end
end

local function writeProfileAtomic(profileName, encoded)
    -- VFS has no rename; sequence is: write .new, verify, rotate backups,
    -- copy previous .json into .bak.1, overwrite .json, delete .new. A crash
    -- at any step leaves either the previous good copy in .json or in .bak.N.
    if not ensureProfilesDirectory() then
        return false
    end

    local finalPath = profileFilePath(profileName)
    local newPath   = finalPath .. ".new"
    local bakPath   = finalPath .. ".bak"   -- legado (compat com loader antigo)
    local bak1Path  = finalPath .. ".bak.1" -- F2.3: slot mais recente

    local writeOk   = pcall(function()
        g_resources.writeFileContents(newPath, encoded)
    end)
    if not writeOk then
        return false
    end

    local readOk, verifyBytes = pcall(function()
        return g_resources.readFileContents(newPath)
    end)
    if not readOk or type(verifyBytes) ~= "string" or #verifyBytes ~= #encoded then
        pcall(function() g_resources.deleteFile(newPath) end)
        return false
    end

    if g_resources.fileExists(finalPath) then
        local prevBytes = _lastSavedProfileBytes
        if type(prevBytes) ~= "string" or #prevBytes == 0 then
            local ok, disk = pcall(function()
                return g_resources.readFileContents(finalPath)
            end)
            if ok then prevBytes = disk end
        end
        if type(prevBytes) == "string" and #prevBytes > 0 then
            -- Rotaciona slots numerados ANTES de gravar o novo .bak.1.
            rotateProfileBackups(finalPath)
            pcall(function()
                g_resources.writeFileContents(bak1Path, prevBytes)
                -- Alias legado: mantem .bak apontando para a versao anterior,
                -- caso algum codigo externo ou loader antigo ainda leia.
                g_resources.writeFileContents(bakPath, prevBytes)
            end)
        end
    end

    local finalOk = pcall(function()
        g_resources.writeFileContents(finalPath, encoded)
    end)
    if not finalOk then
        pcall(function() g_resources.deleteFile(newPath) end)
        return false
    end

    pcall(function() g_resources.deleteFile(newPath) end)

    return true
end

-- F2.3: API publica para a UI (ou console) listar e restaurar backups.
function listProfileBackups(profileName)
    if type(profileName) ~= "string" or profileName == "" then
        return {}
    end
    local result = {}
    local finalPath = profileFilePath(profileName)
    for i = 1, _profileSaveInfo.backupSlots do
        local path = finalPath .. ".bak." .. tostring(i)
        if g_resources.fileExists(path) then
            local sizeOk, sz = pcall(function()
                local b = g_resources.readFileContents(path)
                return (type(b) == "string") and #b or 0
            end)
            table.insert(result, {
                slot  = i,
                path  = path,
                bytes = (sizeOk and sz) or 0,
            })
        end
    end
    -- Fallback para .bak legado se nenhum slot numerado existe
    if #result == 0 and g_resources.fileExists(finalPath .. ".bak") then
        table.insert(result, {
            slot  = 0,
            path  = finalPath .. ".bak",
            bytes = 0,
        })
    end
    return result
end

function restoreProfileBackup(profileName, slot)
    if type(profileName) ~= "string" or profileName == "" then return false end
    slot = tonumber(slot) or 1
    local finalPath = profileFilePath(profileName)
    local srcPath
    if slot == 0 then
        srcPath = finalPath .. ".bak"
    else
        srcPath = finalPath .. ".bak." .. tostring(slot)
    end
    if not g_resources.fileExists(srcPath) then
        return false
    end
    local ok, contents = pcall(function()
        return g_resources.readFileContents(srcPath)
    end)
    if not ok or type(contents) ~= "string" or contents == "" then
        return false
    end
    -- Reusa writeProfileAtomic para rotacionar a versao atual pra .bak.1
    -- antes de sobrescrever com o conteudo restaurado.
    local wrote = writeProfileAtomic(profileName, contents)
    if wrote then
        pcall(function()
            g_logger.warning(_profileSaveInfo.prefix ..
                " restored profile=" .. tostring(profileName) ..
                " from slot=" .. tostring(slot))
        end)
    end
    return wrote
end

_G.listProfileBackups   = listProfileBackups
_G.restoreProfileBackup = restoreProfileBackup

-- F3.5: modal pra escolher qual slot restaurar do profile selecionado.
function openRestoreProfileDialog()
    local selected = getSelectedProfileFromLists()
    if not selected or selected == "" then
        modules.game_textmessage.displayFailureMessage(
            htr("No profile selected. Select a profile in the list first."))
        return
    end

    local backups = listProfileBackups(selected)
    if #backups == 0 then
        modules.game_textmessage.displayFailureMessage(
            "No backups available for '" .. selected .. "'.")
        return
    end

    -- Constroi lista de botoes: 1 por slot disponivel + Cancel
    local buttons = {}
    local messageBox
    for _, b in ipairs(backups) do
        local label
        if b.slot == 0 then
            label = ".bak (legacy)"
        else
            label = ".bak." .. tostring(b.slot)
        end
        if b.bytes > 0 then
            label = label .. " (" .. tostring(b.bytes) .. " B)"
        end
        local slot = b.slot
        table.insert(buttons, {
            text = label,
            callback = function()
                messageBox:ok()
                local ok = restoreProfileBackup(selected, slot)
                if ok then
                    modules.game_textmessage.displayGameMessage(
                        "Profile '" .. selected .. "' restored from slot " .. tostring(slot))
                    -- Se o profile ativo foi restaurado, recarregar.
                    if helperConfig.selectedProfile == selected then
                        if performLoadSelectedProfile then
                            performLoadSelectedProfile()
                        end
                    end
                    refreshProfilesList()
                else
                    modules.game_textmessage.displayFailureMessage(
                        "Failed to restore profile from slot " .. tostring(slot))
                end
            end
        })
    end
    table.insert(buttons, {
        text = "Cancel",
        callback = function() messageBox:ok() end
    })

    messageBox = helperDisplayGeneralBox(
        "Restore Profile",
        "Select which backup of '" .. selected .. "' to restore.\n" ..
        ".bak.1 = most recent saved version.",
        buttons
    )
end

_G.openRestoreProfileDialog = openRestoreProfileDialog

-- F3.4: limpeza retroativa da .trash. Apaga subdiretorios cujo timestamp do
-- nome (sufixo "YYYYMMDD-HHMMSS") esteja alem de `maxAgeSeconds` atras.
function purgeProfileTrashOlderThan(maxAgeSeconds)
    local trashRoot = "/helper/profiles/.trash"
    if not g_resources.directoryExists(trashRoot) then
        return 0
    end
    maxAgeSeconds = tonumber(maxAgeSeconds) or (7 * 24 * 60 * 60)
    local cutoff = os.time() - maxAgeSeconds

    local removed = 0
    local ok, dirs = pcall(function()
        -- listDirectoryFiles(path, fullpath, recursive, includeDirs)
        return g_resources.listDirectoryFiles(trashRoot, false, false, true)
    end)
    if not ok or type(dirs) ~= "table" then
        return 0
    end

    for _, entry in ipairs(dirs) do
        -- entry no formato "ProfileName-YYYYMMDD-HHMMSS"
        local y, mo, d, h, mi, s = string.match(entry,
            "%-(%d%d%d%d)(%d%d)(%d%d)%-(%d%d)(%d%d)(%d%d)$")
        if y then
            local ts = os.time({
                year = tonumber(y),
                month = tonumber(mo),
                day = tonumber(d),
                hour = tonumber(h),
                min = tonumber(mi),
                sec = tonumber(s)
            })
            if ts and ts < cutoff then
                local fullDir = trashRoot .. "/" .. entry
                pcall(function()
                    -- Apaga conteudo
                    local files = g_resources.listDirectoryFiles(fullDir, false, false, false)
                    if type(files) == "table" then
                        for _, f in ipairs(files) do
                            pcall(function()
                                g_resources.deleteFile(fullDir .. "/" .. f)
                            end)
                        end
                    end
                    -- VFS pode ou nao suportar remove dir, fica como esta se falhar
                    if g_resources.removeDir then
                        pcall(function() g_resources.removeDir(fullDir) end)
                    end
                end)
                removed = removed + 1
            end
        end
    end
    return removed
end

_G.purgeProfileTrashOlderThan = purgeProfileTrashOlderThan

local function cleanupProfileNewOrphans()
    local profilesDir = "/helper/profiles"
    if not g_resources.directoryExists(profilesDir) then
        return
    end
    local files = g_resources.listDirectoryFiles(profilesDir, false, false, false)
    if type(files) ~= "table" then
        return
    end
    for _, fileName in pairs(files) do
        if type(fileName) == "string" and fileName:match("%.json%.new$") then
            pcall(function()
                g_resources.deleteFile(profilesDir .. "/" .. fileName)
            end)
        end
    end
end

function flushProfileNow(trigger)
    if _isFlushingProfile then
        return false
    end

    if type(helperConfig) ~= "table" then
        return false
    end

    -- LEITURA SEGURA: um profile aberto so para leitura/clonagem NUNCA e gravado
    -- de forma automatica (helper-close, logout/shutdown, profile-switch, autosave,
    -- pre-clone). Este e o unico ponto de escrita em disco, entao o gate fica aqui,
    -- independente do estado armado. So persiste via Save/Clone (que limpam o flag).
    if helperSessionState.loadedProfileReadOnly then
        return false
    end

    if not _profileAutosaveArmed then
        -- No profile has been explicitly loaded/saved yet in this session;
        -- never touch disk to avoid overwriting an existing profile with
        -- default state.
        return false
    end

    if helperConfig.autoSaveProfileEnabled == false then
        return false
    end

    local profileName = helperConfig.selectedProfile
    if not isAutosaveProfileName(profileName) then
        return false
    end

    local player = g_game.getLocalPlayer()
    if not player then
        return false
    end

    -- F3.2: se o profile ativo nao bate com quem carregou ele, alguem trocou
    -- selectedProfile sem trocar baseline. Recusa flush ate sync explicito
    -- via load/save. Evita gravar dados do char A em arquivo do char B.
    if _lastSavedProfileName and _lastSavedProfileName ~= "" and
        _lastSavedProfileName ~= profileName then
        pcall(function()
            g_logger.warning(_profileSaveInfo.prefix ..
                " skipped trigger=" .. tostring(trigger or "?") ..
                " current=" .. tostring(profileName) ..
                " baseline=" .. tostring(_lastSavedProfileName) ..
                " reason=baseline-mismatch")
        end)
        return false
    end

    -- F1.4: sem baseline hash MAS um arquivo desse profile ja existe no disco:
    -- NAO da pra provar que a config em memoria pertence a ESTE profile (ex.:
    -- selectedProfile mudou no foco da lista antes do flush). Semeia o baseline
    -- a partir do disco e NUNCA grava nesta rodada -- senao a config atual
    -- sobrescreveria um profile alheio/lido (bug do "Load limpou o profile").
    -- A proxima edicao real ja compara contra o baseline correto.
    if _lastSavedProfileHash == nil and isAutosaveProfileName(profileName) then
        local path = profileFilePath(profileName)
        if g_resources.fileExists(path) then
            pcall(function()
                if startProfileAutosave then
                    startProfileAutosave()
                end
            end)
            pcall(function()
                g_logger.warning(_profileSaveInfo.prefix ..
                    " skipped trigger=" .. tostring(trigger or "?") ..
                    " profile=" .. tostring(profileName) ..
                    " reason=no-baseline-reseed-only")
            end)
            return false
        end
    end

    _isFlushingProfile = true
    local wroteFile = false
    local ok, err = pcall(function()
        local profileData = buildProfileDataFromConfig()
        if type(profileData) ~= "table" then
            return
        end

        -- Apply the same field mutations that saveProfileToFile does, so
        -- auto-save output matches what the manual save button writes.
        prepareProfileDataForDisk(profileData)

        -- Fingerprint is order-independent; raw JSON bytes are NOT (the
        -- json encoder uses pairs()). Comparing raw bytes would trigger
        -- false "changes" on identical content.
        local hash = djb2Hash(canonicalFingerprint(profileData))
        if hash == _lastSavedProfileHash and _lastSavedProfileName == profileName then
            return
        end

        local encoded = encodeProfileForAutosave(profileData)
        if not encoded then
            return
        end

        if writeProfileAtomic(profileName, encoded) then
            _lastSavedProfileHash  = hash
            _lastSavedProfileName  = profileName
            _lastSavedProfileBytes = encoded
            wroteFile              = true
            if helperConfig.profiles then
                helperConfig.profiles[profileName] = profileData
            end
        end
    end)
    _isFlushingProfile = false

    if not ok then
        pcall(function()
            g_logger.warning(_profileSaveInfo.prefix .. " flushProfileNow(" .. tostring(trigger) ..
                ") failed: " .. tostring(err))
        end)
        return false
    end

    if wroteFile then
        -- F1.2/F2.2/F2.4: marca limpo + timestamp + log dedicado.
        pcall(function()
            markProfileSavedNow(profileName)
            local bytes = (_lastSavedProfileBytes and #_lastSavedProfileBytes) or 0
            g_logger.info(_profileSaveInfo.prefix ..
                " saved trigger=" .. tostring(trigger or "?") ..
                " profile=" .. tostring(profileName) ..
                " bytes=" .. tostring(bytes))
            if modules.game_textmessage and modules.game_textmessage.displayFailureMessage then
                modules.game_textmessage.displayFailureMessage("Profile '" .. profileName .. "' saved")
            end
        end)
    end

    return true
end

function startProfileAutosave()
    cleanupProfileNewOrphans()

    -- Do NOT arm here — arming is the caller's responsibility and only
    -- happens after a profile is explicitly loaded or saved. Seeding the
    -- hash from disk alone is not enough: helperConfig may not actually
    -- hold the profile's data yet (autoLoad off, fresh session, etc.).
    _lastSavedProfileHash  = nil
    _lastSavedProfileName  = nil
    _lastSavedProfileBytes = nil

    if type(helperConfig) == "table" and isAutosaveProfileName(helperConfig.selectedProfile) then
        local path = profileFilePath(helperConfig.selectedProfile)
        if g_resources.fileExists(path) then
            local ok, bytes = pcall(function()
                return g_resources.readFileContents(path)
            end)
            if ok and type(bytes) == "string" and #bytes > 0 then
                -- Seed baseline hash from the DECODED file using the same
                -- canonical fingerprint + prepareForDisk pipeline the
                -- flush path uses. Otherwise the first flush would always
                -- mismatch (raw bytes vs canonical fingerprint).
                local decodeOk, decoded = pcall(function()
                    return json.decode(bytes)
                end)
                if decodeOk and type(decoded) == "table" then
                    prepareProfileDataForDisk(decoded)
                    _lastSavedProfileHash  = djb2Hash(canonicalFingerprint(decoded))
                    _lastSavedProfileName  = helperConfig.selectedProfile
                    _lastSavedProfileBytes = bytes
                end
            end
        end
    end
end

function stopProfileAutosave(opts)
    opts = opts or {}
    if opts.flush then
        flushProfileNow("shutdown")
    end
end

function resetProfileAutosaveState()
    _lastSavedProfileHash          = nil
    _lastSavedProfileName          = nil
    _lastSavedProfileBytes         = nil
    _profileAutosaveArmed          = false
    _profileSaveInfo.dirty         = false
    _profileSaveInfo.dirtyCheckMs  = 0
    _profileSaveInfo.lastSaveMs    = 0
    _profileSaveInfo.lastSaveLabel = ""
end

-- F1.2: dirty tracking. Compara fingerprint atual do helperConfig vs
-- _lastSavedProfileHash. Throttled a no maximo 1 chamada/segundo via
-- _profileSaveInfo.dirtyCheckMs. Force=true ignora throttle. Retorna o estado dirty.
function recomputeProfileDirty(force)
    if type(helperConfig) ~= "table" then
        _profileSaveInfo.dirty = false
        return false
    end

    if not _profileAutosaveArmed or not _lastSavedProfileHash then
        -- Sem baseline => nada pra comparar. Conservador: nao marca dirty
        -- (o que pintaria * em profile recem aberto sem mudancas reais).
        _profileSaveInfo.dirty = false
        return false
    end

    local now = g_clock.millis()
    if not force and (now - _profileSaveInfo.dirtyCheckMs) < 1000 then
        return _profileSaveInfo.dirty
    end
    _profileSaveInfo.dirtyCheckMs = now

    local ok, hash = pcall(function()
        local snapshot = buildProfileDataFromConfig()
        if type(snapshot) ~= "table" then return nil end
        prepareProfileDataForDisk(snapshot)
        return djb2Hash(canonicalFingerprint(snapshot))
    end)

    if not ok or not hash then
        return _profileSaveInfo.dirty
    end

    local newDirty = (hash ~= _lastSavedProfileHash)
    if newDirty ~= _profileSaveInfo.dirty then
        _profileSaveInfo.dirty = newDirty
        if updateLoadedProfileLabel then
            updateLoadedProfileLabel()
        end
    end
    return _profileSaveInfo.dirty
end

function isProfileDirty()
    return _profileSaveInfo.dirty == true
end

-- Chamado quando carregamos um profile do disco (baseline ja casa com disco,
-- entao nao ha mudancas pendentes). NAO seta timestamp de save -- nao salvamos,
-- so carregamos.
function markProfileLoadedClean()
    _profileSaveInfo.dirty = false
    if updateLoadedProfileLabel then
        updateLoadedProfileLabel()
    end
end

function markProfileSavedNow(profileName)
    _profileSaveInfo.dirty         = false
    _profileSaveInfo.lastSaveMs    = g_clock.millis()
    local hh, mm, ss               = os.date("%H"), os.date("%M"), os.date("%S")
    _profileSaveInfo.lastSaveLabel = tostring(hh) .. ":" .. tostring(mm) .. ":" .. tostring(ss)
    if updateLoadedProfileLabel then
        updateLoadedProfileLabel()
    end
end

function getLastProfileSaveLabel()
    return _profileSaveInfo.lastSaveLabel
end

function getLastProfileSaveMs()
    return _profileSaveInfo.lastSaveMs
end

_G.recomputeProfileDirty   = recomputeProfileDirty
_G.isProfileDirty          = isProfileDirty
_G.markProfileLoadedClean  = markProfileLoadedClean
_G.markProfileSavedNow     = markProfileSavedNow
_G.getLastProfileSaveLabel = getLastProfileSaveLabel
_G.getLastProfileSaveMs    = getLastProfileSaveMs

-- Arm the auto-saver. Must be called after a profile has been explicitly
-- loaded into helperConfig (loadSelectedProfile, autoLoad path) or after a
-- manual save (saveCurrentProfile / saveCurrentProfileQuick / import).
function armProfileAutosave()
    _profileAutosaveArmed = true
end

function isProfileAutosaveArmed()
    return _profileAutosaveArmed
end

_G.flushProfileNow        = flushProfileNow
_G.armProfileAutosave     = armProfileAutosave
_G.isProfileAutosaveArmed = isProfileAutosaveArmed

-- ==================== END PROFILE AUTO-SAVE ====================

function saveProfileToFile(profileName, profileData)
    -- Garantir que configuracoes globais nao sejam salvas no profile
    if profileData then
        profileData.autoLoadProfileEnabled = nil
        profileData.autoLoadProfileType = nil
        profileData.profiles = nil
        profileData.selectedProfile = nil
        profileData.holdAttackTargetId = nil
        profileData.holdAttackTargetName = nil
        profileData.iconStats = nil -- Icon Stats mora em g_settings (global do client), nunca no profile

        -- Save condition settings from game_healthcircle
        if modules.game_healthcircle and modules.game_healthcircle.exportConditionSettings then
            profileData.conditionSettings = modules.game_healthcircle.exportConditionSettings()
        end
    end

    -- Garantir que o diretorio existe
    local profilesDir = ensureProfilesDirectory()
    if not profilesDir then
        return false
    end

    local profileFile = profilesDir .. "/" .. profileName .. ".json"

    local status, result = pcall(
        function()
            return json.encode(profileData, 2)
        end
    )

    if not status then
        return false
    end

    local jsonSize = result:len()

    if jsonSize > 100 * 1024 * 1024 then
        return false
    end

    local writeStatus = g_resources.writeFileContents(profileFile, result)

    return writeStatus
end

function loadProfileFromFile(profileName)
    if profileName == "Default" then
        return nil
    end

    local profilesDir = "/helper/profiles"
    local profileFile = profilesDir .. "/" .. profileName .. ".json"
    local backupFile  = profileFile .. ".bak"

    local function tryDecode(path)
        if not g_resources.fileExists(path) then
            return nil
        end
        local readOk, contents = pcall(function()
            return g_resources.readFileContents(path)
        end)
        if not readOk or type(contents) ~= "string" or contents == "" then
            return nil
        end
        local decodeOk, decoded = pcall(function()
            return json.decode(contents)
        end)
        if not decodeOk or type(decoded) ~= "table" then
            return nil
        end
        return decoded
    end

    local result = tryDecode(profileFile)
    if not result then
        -- F2.3: tenta backups numerados primeiro (.bak.1 = mais recente).
        local recoveredFrom
        for i = 1, _profileSaveInfo.backupSlots do
            local slotPath = profileFile .. ".bak." .. tostring(i)
            result = tryDecode(slotPath)
            if result then
                recoveredFrom = ".bak." .. tostring(i)
                break
            end
        end
        -- Fallback final: arquivo .bak legado (sem numero).
        if not result then
            result = tryDecode(backupFile)
            if result then
                recoveredFrom = ".bak"
            end
        end
        if result then
            pcall(function()
                g_logger.warning("[Helper] Profile '" .. tostring(profileName) ..
                    "' recovered from backup (" .. tostring(recoveredFrom) ..
                    "). The main .json was missing or corrupt.")
            end)
        else
            return nil
        end
    end

    ensureHealingSlots(result)

    return result
end

-- Icon Stats config is persisted via g_settings (client global config),
-- NOT in /helper/config.json or profile files. Same value for every character.
local ICON_STATS_SETTINGS_KEY = 'iconstats_config'
local ICON_STATS_DEFAULT_ICONS = {
    healingIcon = true,
    healFriendIcon = true,
    equipmentIcon = true,
    tankModeIcon = true,
    targetingIcon = true,
    shooterIcon = true,
    cavebotIcon = true,
    timerIcon = true,
    helperIcon = true
}

local function normalizeIconStatsConfig(cfg)
    cfg = (type(cfg) == "table") and cfg or {}
    if type(cfg.visible) ~= "boolean" then cfg.visible = false end
    if type(cfg.x) ~= "number" then cfg.x = 100 end
    if type(cfg.y) ~= "number" then cfg.y = 100 end
    if type(cfg.locked) ~= "boolean" then cfg.locked = false end
    if type(cfg.horizontal) ~= "boolean" then cfg.horizontal = false end
    if type(cfg.visibleIcons) ~= "table" then
        cfg.visibleIcons = {}
    end
    for iconId, defaultVisible in pairs(ICON_STATS_DEFAULT_ICONS) do
        if cfg.visibleIcons[iconId] == nil then
            cfg.visibleIcons[iconId] = defaultVisible
        end
    end
    return cfg
end

function saveIconStatsToClientConfig()
    if not helperConfig then
        return
    end
    helperConfig.iconStats = normalizeIconStatsConfig(helperConfig.iconStats)
    if g_settings and g_settings.setNode then
        g_settings.setNode(ICON_STATS_SETTINGS_KEY, helperConfig.iconStats)
    end
end

function loadIconStatsFromClientConfig(legacyFallback)
    local stored = nil
    if g_settings and g_settings.getNode then
        stored = g_settings.getNode(ICON_STATS_SETTINGS_KEY)
    end

    local migrated = false
    if not stored and type(legacyFallback) == "table" then
        -- Migrate from the old /helper/config.json iconStats block (one-time)
        stored = legacyFallback
        migrated = true
    end

    helperConfig.iconStats = normalizeIconStatsConfig(stored)

    if migrated then
        saveIconStatsToClientConfig()
    end
end

-- Per-character config path resolution.
-- Reads prefer the per-char file and fall back to the legacy global file for
-- retrocompat. Writes always go to the per-char file when a char is known.
-- Once the per-char file exists, the legacy global stops being read or written
-- for this char, isolating multi-client setups (each char gets its own file).
HELPER_CONFIG_LEGACY_FILE = "/helper/config.json"

-- Per-session caches. Avoid recomputing the sanitized name and re-stat'ing the
-- per-char path on every save/load (helper triggers these on each UI toggle).
-- Invalidated by invalidateHelperConfigPathCache() on logout/char change.
helperConfigCachedCharName = nil
helperConfigCachedPerCharFile = nil
helperConfigCachedReadFile = nil

function invalidateHelperConfigPathCache()
    helperConfigCachedCharName = nil
    helperConfigCachedPerCharFile = nil
    helperConfigCachedReadFile = nil
end

function getHelperConfigCharName()
    if helperConfigCachedCharName ~= nil then
        return helperConfigCachedCharName or nil
    end
    if not g_game or not g_game.getCharacterName then return nil end
    local name = g_game.getCharacterName()
    if not name or name == "" then return nil end
    local sanitized = string.lower(name):gsub("[^%w]", "_"):gsub("_+", "_")
    sanitized = sanitized:gsub("^_+", ""):gsub("_+$", "")
    if sanitized == "" then
        helperConfigCachedCharName = false
        return nil
    end
    helperConfigCachedCharName = sanitized
    return sanitized
end

function getHelperConfigPerCharFile()
    if helperConfigCachedPerCharFile ~= nil then
        return helperConfigCachedPerCharFile or nil
    end
    local name = getHelperConfigCharName()
    if not name then
        helperConfigCachedPerCharFile = false
        return nil
    end
    helperConfigCachedPerCharFile = "/helper/config_" .. name .. ".json"
    return helperConfigCachedPerCharFile
end

function getHelperConfigReadFile()
    if helperConfigCachedReadFile then return helperConfigCachedReadFile end
    local perChar = getHelperConfigPerCharFile()
    if perChar and g_resources.fileExists(perChar) then
        helperConfigCachedReadFile = perChar
        return perChar
    end
    -- Don't cache the legacy path: the per-char file may appear later in this
    -- session (first saveSettings creates it), and subsequent reads must pick
    -- it up automatically.
    return HELPER_CONFIG_LEGACY_FILE
end

function getHelperConfigWriteFile()
    return getHelperConfigPerCharFile() or HELPER_CONFIG_LEGACY_FILE
end

function saveSettings()
    -- IMPORTANTE: Esta funcao NAO salva profiles!
    -- Profiles so sao salvos pelo botao Save (saveCurrentProfile/saveCurrentProfileQuick)
    -- Esta funcao salva apenas metadados no config.json

    local player = g_game.getLocalPlayer()
    if not player then
        return
    end

    -- Construir lista de profiles existentes (sem salvar os arquivos)
    local profilesList = {}
    if helperConfig.profiles then
        for profileName, _ in pairs(helperConfig.profiles) do
            if profileName and profileName ~= "" then
                table.insert(profilesList, profileName)
            end
        end
    end

    local configToSave = {
        profilesList = profilesList,
        selectedProfile = helperConfig.selectedProfile or "",
        autoLoadProfileEnabled = helperConfig.autoLoadProfileEnabled or false,
        autoLoadProfileType = helperConfig.autoLoadProfileType or "name",
        autoSaveProfileEnabled = helperConfig.autoSaveProfileEnabled ~= false,
        lastProfileLoadedByCharacter = helperConfig.lastProfileLoadedByCharacter or "",
        partyManagement = {
            inviteParty = {
                all = (helperConfig.partyManagement and helperConfig.partyManagement.inviteParty and helperConfig.partyManagement.inviteParty.all) or
                false,
                vip = (helperConfig.partyManagement and helperConfig.partyManagement.inviteParty and helperConfig.partyManagement.inviteParty.vip) or
                false,
                guild = (helperConfig.partyManagement and helperConfig.partyManagement.inviteParty and helperConfig.partyManagement.inviteParty.guild) or
                false,
                friend = (helperConfig.partyManagement and helperConfig.partyManagement.inviteParty and helperConfig.partyManagement.inviteParty.friend) or
                false,
                friendList = (helperConfig.partyManagement and helperConfig.partyManagement.inviteParty and helperConfig.partyManagement.inviteParty.friendList) or
                ""
            },
            autoAcceptParty = {
                all = (helperConfig.partyManagement and helperConfig.partyManagement.autoAcceptParty and helperConfig.partyManagement.autoAcceptParty.all) or
                false,
                vip = (helperConfig.partyManagement and helperConfig.partyManagement.autoAcceptParty and helperConfig.partyManagement.autoAcceptParty.vip) or
                false,
                guild = (helperConfig.partyManagement and helperConfig.partyManagement.autoAcceptParty and helperConfig.partyManagement.autoAcceptParty.guild) or
                false,
                friend = (helperConfig.partyManagement and helperConfig.partyManagement.autoAcceptParty and helperConfig.partyManagement.autoAcceptParty.friend) or
                false,
                friendList = (helperConfig.partyManagement and helperConfig.partyManagement.autoAcceptParty and helperConfig.partyManagement.autoAcceptParty.friendList) or
                ""
            }
        }
    }

    local configFile = getHelperConfigWriteFile()

    local status, result = pcall(
        function()
            return json.encode(configToSave, 2)
        end
    )

    if not status then
        return onError("Error while saving config. Details: " .. result)
    end

    if result:len() > 100 * 1024 * 1024 then
        return onError("Something went wrong, file is above 100MB, won't be saved")
    end

    g_resources.writeFileContents(configFile, result)
end

-- Alias para compatibilidade
function saveConfigOnly()
    saveSettings()
end

-- Carrega apenas as configuracoes globais de auto-load (pode ser chamado sem player logado)
function loadAutoLoadSettings()
    local configFile = getHelperConfigReadFile()

    if not g_resources.fileExists(configFile) then
        return false
    end

    local status, result = pcall(
        function()
            return json.decode(g_resources.readFileContents(configFile))
        end
    )

    if not status or not result then
        return false
    end

    -- Carregar apenas as configuracoes de auto-load
    if result.autoLoadProfileEnabled ~= nil then
        helperConfig.autoLoadProfileEnabled = result.autoLoadProfileEnabled
    end
    if result.autoLoadProfileType then
        helperConfig.autoLoadProfileType = result.autoLoadProfileType
    end
    if result.autoSaveProfileEnabled ~= nil then
        helperConfig.autoSaveProfileEnabled = result.autoSaveProfileEnabled
    end

    return true
end

-- Carrega apenas configurações do arquivo sem resetar helperConfig completo
-- Usado em relogs do mesmo personagem para preservar estado em memória
function loadSettingsMinimal()
    local configFile = getHelperConfigReadFile()

    -- Tentar carregar config.json se existir
    if g_resources.fileExists(configFile) then
        local status, result = pcall(
            function()
                return json.decode(g_resources.readFileContents(configFile))
            end
        )

        if status and result then
            -- Carregar APENAS metadados globais, preservando toggles e estado
            if result.selectedProfile then
                helperConfig.selectedProfile = result.selectedProfile
            end
            if result.autoLoadProfileEnabled ~= nil then
                helperConfig.autoLoadProfileEnabled = result.autoLoadProfileEnabled
            end
            if result.autoLoadProfileType then
                helperConfig.autoLoadProfileType = result.autoLoadProfileType
            end
            if result.autoSaveProfileEnabled ~= nil then
                helperConfig.autoSaveProfileEnabled = result.autoSaveProfileEnabled
            end
            if result.lastProfileLoadedByCharacter then
                helperConfig.lastProfileLoadedByCharacter = result.lastProfileLoadedByCharacter
            end

            -- Icon Stats agora mora em g_settings (config global do client);
            -- passar result.iconStats apenas para migracao do config.json antigo.
            loadIconStatsFromClientConfig(result.iconStats)

            -- lastMenu removido: agora funciona apenas na sessao atual
            helperSessionState.lastMenu = "healingMenu"

            -- Carregar profiles da profilesList
            helperConfig.profiles = {}
            if result.profilesList and type(result.profilesList) == "table" then
                for _, profileName in ipairs(result.profilesList) do
                    local profileData = loadProfileFromFile(profileName)
                    if profileData then
                        helperConfig.profiles[profileName] = profileData
                    end
                end
            end
        end
    end

    -- SEMPRE escanear diretorio de profiles, independente do config.json
    if not helperConfig.profiles then
        helperConfig.profiles = {}
    end
    local profilesDir = "/helper/profiles"
    local diskFiles = g_resources.listDirectoryFiles(profilesDir, false, false, false)
    if diskFiles then
        for _, fileName in pairs(diskFiles) do
            if fileName and fileName:match("%.json$") then
                local diskProfileName = fileName:gsub("%.json$", "")
                if diskProfileName and diskProfileName ~= "" and not helperConfig.profiles[diskProfileName] then
                    local profileData = loadProfileFromFile(diskProfileName)
                    if profileData then
                        helperConfig.profiles[diskProfileName] = profileData
                    end
                end
            end
        end
    end

    return true
end

