            autoAcceptParty = { all = false, vip = false, guild = false, friend = false, friendList = "" }
        },
    }

    if g_resources.fileExists(configFile) then
        local status, result =
            pcall(
                function()
                    return json.decode(g_resources.readFileContents(configFile))
                end
            )

        if not status then
            g_logger.error("[Helper] Erro ao decodificar config.json: " .. tostring(result))
            -- Continuar com defaults em vez de abortar - o scan de diretorio ainda vai carregar profiles
            result = {}
        end

        -- Carregar configuracoes gerais
        helperConfig.selectedProfile = result.selectedProfile or ""
        helperConfig.autoLoadProfileEnabled = result.autoLoadProfileEnabled or false
        helperConfig.autoLoadProfileType = result.autoLoadProfileType or "name"
        -- Default true: only honor an explicit false in the config.
        if result.autoSaveProfileEnabled ~= nil then
            helperConfig.autoSaveProfileEnabled = result.autoSaveProfileEnabled
        else
            helperConfig.autoSaveProfileEnabled = true
        end
        helperConfig.lastProfileLoadedByCharacter = result.lastProfileLoadedByCharacter or ""
        -- lastMenu removido: agora funciona apenas na sessao atual
        -- Ao iniciar o cliente, sempre comeca na aba healing
        helperSessionState.lastMenu = "healingMenu"
        -- Icon Stats mora em g_settings (config global do client). Carregar de la,
        -- migrando do config.json apenas uma vez se ainda nao houver no g_settings.
        loadIconStatsFromClientConfig(result.iconStats)

        -- Carregar partyManagement
        if result.partyManagement then
            if not helperConfig.partyManagement then
                helperConfig.partyManagement = {
                    inviteParty = { all = false, vip = false, guild = false, friend = false, friendList = "" },
                    autoAcceptParty = { all = false, vip = false, guild = false, friend = false, friendList = "" }
                }
            end
            if result.partyManagement.inviteParty then
                helperConfig.partyManagement.inviteParty = helperConfig.partyManagement.inviteParty or {}
                helperConfig.partyManagement.inviteParty.all = result.partyManagement.inviteParty.all or false
                helperConfig.partyManagement.inviteParty.vip = result.partyManagement.inviteParty.vip or false
                helperConfig.partyManagement.inviteParty.guild = result.partyManagement.inviteParty.guild or false
                helperConfig.partyManagement.inviteParty.friend = result.partyManagement.inviteParty.friend or false
                helperConfig.partyManagement.inviteParty.friendList = result.partyManagement.inviteParty.friendList or ""
            end
            if result.partyManagement.autoAcceptParty then
                helperConfig.partyManagement.autoAcceptParty = helperConfig.partyManagement.autoAcceptParty or {}
                helperConfig.partyManagement.autoAcceptParty.all = result.partyManagement.autoAcceptParty.all or false
                helperConfig.partyManagement.autoAcceptParty.vip = result.partyManagement.autoAcceptParty.vip or false
                helperConfig.partyManagement.autoAcceptParty.guild = result.partyManagement.autoAcceptParty.guild or
                false
                helperConfig.partyManagement.autoAcceptParty.friend = result.partyManagement.autoAcceptParty.friend or
                false
                helperConfig.partyManagement.autoAcceptParty.friendList = result.partyManagement.autoAcceptParty
                .friendList or ""
            end
        end

        -- Atualizar referencia global
        _G.helperConfig = helperConfig

        -- Garantir que timers existam
        if not helperConfig.timerEnabled then
            helperConfig.timerEnabled = result.timerEnabled or false
        end
        if type(helperConfig.timers) ~= "table" then
            helperConfig.timers = type(result.timers) == "table" and deepCopy(result.timers) or {}
        end
        ensureTimerConfig(TIMER_DEFAULT_RULE_COUNT)

        -- Carregar configuracoes de alarmes
        if result.alarms and type(result.alarms) == "table" then
            helperConfig.alarms = result.alarms
        end
        -- Garantir que todos os campos de alarme existam
        if not helperConfig.alarms then
            helperConfig.alarms = {}
        end
        helperConfig.alarms.alarmDamageTaken = helperConfig.alarms.alarmDamageTaken or false
        helperConfig.alarms.alarmLowHealth = helperConfig.alarms.alarmLowHealth or false
        helperConfig.alarms.alarmLowHealthThreshold = helperConfig.alarms.alarmLowHealthThreshold or 50
        helperConfig.alarms.alarmMonsterOnScreen = helperConfig.alarms.alarmMonsterOnScreen or false
        helperConfig.alarms.alarmPlayerOnScreen = helperConfig.alarms.alarmPlayerOnScreen or false
        helperConfig.alarms.alarmPlayerSkullOnScreen = helperConfig.alarms.alarmPlayerSkullOnScreen or false
        helperConfig.alarms.alarmPlayerAttack = helperConfig.alarms.alarmPlayerAttack or false
        helperConfig.alarms.alarmEnemyOnScreen = helperConfig.alarms.alarmEnemyOnScreen or false
        helperConfig.alarms.alarmSoundAlert = helperConfig.alarms.alarmSoundAlert or false
        helperConfig.alarms.alarmWindowsBarFlash = helperConfig.alarms.alarmWindowsBarFlash or false

        -- Atualizar UI das configuracoes globais
        scheduleEvent(function()
            if profilesPanel then
                local enableAutoLoad = profilesPanel:recursiveGetChildById("enableAutoLoadProfile")
                if enableAutoLoad then
                    enableAutoLoad:setChecked(helperConfig.autoLoadProfileEnabled == true)
                end

                local autoLoadByName = profilesPanel:recursiveGetChildById("autoLoadByName")
                if autoLoadByName then
                    if not autoLoadRadioGroup then
                        autoLoadRadioGroup = UIRadioGroup.create()
                        autoLoadRadioGroup:addWidget(autoLoadByName)
                    end

                    autoLoadRadioGroup:selectWidget(autoLoadByName)
                end
            end
        end, 100)

        -- Carregar profiles de arquivos separados
        helperConfig.profiles = {}

        if result.profilesList and type(result.profilesList) == "table" then
            for _, profileName in ipairs(result.profilesList) do
                local profileData = loadProfileFromFile(profileName)
                if profileData then
                    helperConfig.profiles[profileName] = profileData
                else
                    g_logger.warning("[Helper] Falha ao carregar profile: " .. profileName)
                end
            end
        elseif result.profiles and type(result.profiles) == "table" then
            -- Migrar sistema antigo (profiles dentro do helper.json)
            for profileName, profileData in pairs(result.profiles) do
                if profileName and profileName ~= "" then
                    -- Salvar profile antigo em arquivo separado
                    local saved = saveProfileToFile(profileName, profileData)
                    if saved then
                        helperConfig.profiles[profileName] = profileData
                    end
                end
            end
        else
            -- Migrar helper.json antigo completo para sistema de profiles
            helperConfig.profiles = {}

            -- Criar profile "Default" com as configuracoes atuais (exceto cavebot)
            local defaultProfile = {}
            for k, v in pairs(result) do
                if k ~= "profiles" and k ~= "selectedProfile" and k ~= "autoLoadProfileEnabled" and k ~= "autoLoadProfileType" and k ~= "profilesList" then
                    local isCavebot = false
                    if type(k) == "string" then
                        local lowerK = k:lower()
                        if lowerK:find("cavebot") or lowerK:find("cave") then
                            isCavebot = true
                        end
                    end
                    if not isCavebot then
                        defaultProfile[k] = deepCopy(v)
                    end
                end
            end
            helperConfig.profiles["Default"] = defaultProfile
            helperConfig.selectedProfile = "Default"

            -- Salvar profile Default em arquivo separado
            saveProfileToFile("Default", defaultProfile)
        end

        local profileCount = 0
        if helperConfig.profiles then
            for _ in pairs(helperConfig.profiles) do
                profileCount = profileCount + 1
            end
        end

        if not result.spells then
            helperConfig.spells = {
                { id = 0, percent = 80, priority = 1 },
                { id = 0, percent = 80, priority = 1 },
                { id = 0, percent = 80, priority = 1 },
                { id = 0, percent = 80, priority = 1 }
            }
        end
        if not result.rings then
            helperConfig.rings = {}
        else
            for i, ring in ipairs(helperConfig.rings) do
                if ring.alwaysEquipIfNone == nil then ring.alwaysEquipIfNone = false end
                if ring.equipIfHPBelowEnabled == nil then ring.equipIfHPBelowEnabled = false end
                if ring.equipIfHPBelow == nil then ring.equipIfHPBelow = 0 end
                if ring.equipIfHPAboveEnabled == nil then ring.equipIfHPAboveEnabled = false end
                if ring.equipIfHPAbove == nil then ring.equipIfHPAbove = 0 end
                if ring.equipIfMPBelowEnabled == nil then ring.equipIfMPBelowEnabled = false end
                if ring.equipIfMPBelow == nil then ring.equipIfMPBelow = 0 end
                if ring.equipIfMPAboveEnabled == nil then ring.equipIfMPAboveEnabled = false end
                if ring.equipIfMPAbove == nil then ring.equipIfMPAbove = 0 end
                if ring.excludeAmuletIds == nil then ring.excludeAmuletIds = { 0, 0 } end
                if ring.excludeRingIds == nil then ring.excludeRingIds = { 0, 0 } end
                if ring.respectEnergyRing == nil then ring.respectEnergyRing = false end
            end
        end
        if not result.amulets then
            helperConfig.amulets = {}
        else
            for i, amulet in ipairs(helperConfig.amulets) do
                if amulet.alwaysEquipIfNone == nil then amulet.alwaysEquipIfNone = false end
                if amulet.equipIfHPBelowEnabled == nil then amulet.equipIfHPBelowEnabled = false end
                if amulet.equipIfHPBelow == nil then amulet.equipIfHPBelow = 0 end
                if amulet.equipIfHPAboveEnabled == nil then amulet.equipIfHPAboveEnabled = false end
                if amulet.equipIfHPAbove == nil then amulet.equipIfHPAbove = 0 end
                if amulet.equipIfMPBelowEnabled == nil then amulet.equipIfMPBelowEnabled = false end
                if amulet.equipIfMPBelow == nil then amulet.equipIfMPBelow = 0 end
                if amulet.equipIfMPAboveEnabled == nil then amulet.equipIfMPAboveEnabled = false end
                if amulet.equipIfMPAbove == nil then amulet.equipIfMPAbove = 0 end
                if amulet.excludeAmuletIds == nil then amulet.excludeAmuletIds = { 0, 0 } end
                if amulet.excludeRingIds == nil then amulet.excludeRingIds = { 0, 0 } end
                if amulet.respectEnergyRing == nil then amulet.respectEnergyRing = false end
            end
        end

        ensureEquipmentSwapConfig(EQUIPMENT_SWAP_DEFAULT_SLOT_COUNT)
        ensureTimerConfig(TIMER_DEFAULT_RULE_COUNT)

        if not result.energyRing then
            helperConfig.energyRing = {
                healthToEquip = 50,
                healthToDeequip = 80,
                minManaToEquip = 40,
                manaToEquip = 10
            }
        end
        if result.energyRingEnabled == nil then
            helperConfig.energyRingEnabled = false
        end
        if not result.utamo then
            helperConfig.utamo = {
                { id = 0, percent = 80, enabled = false }
            }
        end
        if not result.exana then
            helperConfig.exana = {
                { id = 0, percent = 80, enabled = false }
            }
        end
        if #helperConfig.spells < 4 then
            table.insert(helperConfig.spells, { id = 0, percent = 0 })
        end
        for _, k in pairs(helperConfig.spells) do
            if k.percent == 0 then
                k.percent = 80
            end
            if not k.priority then
                k.priority = 1
            end
        end
        if not result.potions then
            helperConfig.potions = {
                { id = 0, percent = 50, priority = 1 },
                { id = 0, percent = 50, priority = 1 },
                { id = 0, percent = 50, priority = 1 },
                { id = 0, percent = 50, priority = 1 }
            }
        end
        if #helperConfig.potions < 4 then
            while #helperConfig.potions < 4 do
                table.insert(helperConfig.potions, { id = 0, percent = 0, priority = 1 })
            end
        end
        for _, k in pairs(helperConfig.potions) do
            if k.percent == 0 then
                k.percent = 50
            end
            if not k.priority then
                k.priority = 1
            end

            if not k.priority then
                k.priority = 0
            end
        end
        if not result.training then
            helperConfig.training = {
                { id = 0, percent = 0, enabled = false }
            }
        end
        if not result.trainingDummyIds then
            helperConfig.trainingDummyIds = { 0, 0, 0 }
        end
        if not result.exerciseWeaponId then
            helperConfig.exerciseWeaponId = 0
        end
        if result.exerciseWeaponIdsText == nil then
            helperConfig.exerciseWeaponIdsText = ""
            if helperConfig.exerciseWeaponId and helperConfig.exerciseWeaponId > 0 then
                helperConfig.exerciseWeaponIdsText = tostring(helperConfig.exerciseWeaponId)
            end
        end
        if result.trainingDummyIdsText == nil then
            helperConfig.trainingDummyIdsText = ""
            local parts = {}
            if helperConfig.trainingDummyIds then
                for _, did in ipairs(helperConfig.trainingDummyIds) do
                    if did and did > 0 then
                        table.insert(parts, tostring(did))
                    end
                end
            end
            if #parts > 0 then
                helperConfig.trainingDummyIdsText = table.concat(parts, ", ")
            end
        end
        if result.useDefaultDummies == nil then
            helperConfig.useDefaultDummies = true
        end
        if result.exerciseMinStaminaHours == nil then
            helperConfig.exerciseMinStaminaHours = 0
        end
        if result.exerciseMaxStaminaHours == nil then
            helperConfig.exerciseMaxStaminaHours = 0
        end
        if not result.autoTrainingEnabled then
            helperConfig.autoTrainingEnabled = false
        end
        if not result.haste then
            helperConfig.haste = {
                { id = 0, enabled = false, safecast = false }
            }
        end
        if not result.cureParalyze then
            helperConfig.cureParalyze = {
                { id = 0, enabled = false }
            }
        end
