            helperConfig.friendhealing = {
                { name = "", percent = 0, enabled = false },
                { name = "", percent = 0, enabled = false },
                { name = "", percent = 0, enabled = false },
                { name = "", percent = 0, enabled = false },
                { name = "", percent = 0, enabled = false }
