                { name = "", percent = 0, enabled = false },
                { name = "", percent = 0, enabled = false },
                { name = "", percent = 0, enabled = false }
            }
        end
        if not result.uhhealing then
            helperConfig.uhhealing = {
                { enabled = false, percent = 90 }
            }
        end
        if not result.uhfriendList then
            helperConfig.uhfriendList = {}
        end
        if not result.uhhealingParty then
            helperConfig.uhhealingParty = false
        end
        if not result.uhhealingGuild then
            helperConfig.uhhealingGuild = false
        end
        if not result.uhhealingScreen then
            helperConfig.uhhealingScreen = false
        end
        if not result.uhhealingVocationPercent then
            helperConfig.uhhealingVocationPercent = {
                ["4"] = 90,
                ["8"] = 90,
                ["3"] = 90,
                ["7"] = 90,
                ["1"] = 90,
                ["5"] = 90,
                ["2"] = 90,
                ["6"] = 90,
                ["9"] = 90,
                ["10"] = 90
            }
        end
        if not result.uhhealingVocationPriority then
            helperConfig.uhhealingVocationPriority = {
                ["8"] = 1, ["7"] = 2, ["5"] = 3, ["6"] = 4, ["10"] = 5
            }
        end
        if not result.tiosiohealing then
            helperConfig.tiosiohealing = {
                { enabled = false, percent = 90 }
            }
        end
        if not result.tiosiofriendList then
            helperConfig.tiosiofriendList = {}
        end
        if not result.tiosiohealingParty then
            helperConfig.tiosiohealingParty = false
        end
        if not result.tiosiohealingGuild then
            helperConfig.tiosiohealingGuild = false
