        -- config.json nao existe: carrega icon stats direto do g_settings (sem legacy fallback)
        loadIconStatsFromClientConfig()
    end

    -- SEMPRE escanear diretorio de profiles, independente do config.json
    -- Isso garante que profiles copiados manualmente para a pasta sejam descobertos
    if not helperConfig.profiles then
        helperConfig.profiles = {}
    end
    local profilesScanDir = "/helper/profiles"
    local diskFiles = g_resources.listDirectoryFiles(profilesScanDir, false, false, false)
    if diskFiles then
        for _, fileName in pairs(diskFiles) do
            if fileName and fileName:match("%.json$") then
                local diskProfileName = fileName:gsub("%.json$", "")
                if diskProfileName and diskProfileName ~= "" and not helperConfig.profiles[diskProfileName] then
                    local profileData = loadProfileFromFile(diskProfileName)
                    if profileData then
                        helperConfig.profiles[diskProfileName] = profileData
                    end
                end
            end
        end
    end

    _G.helperConfig = helperConfig
    return true
end

-- Custom Spell Timer System
local lastCastTimes = {}

function startCustomSpellTimer()
    if customSpellCheckEvent then
        removeEvent(customSpellCheckEvent)
    end
    customSpellCheckEvent = cycleEvent(function()
        local ok, err = pcall(checkCustomSpells)
        if not ok then
            g_logger.warning("[Helper] checkCustomSpells error: " .. tostring(err))
        end
    end, 200)
end

function stopCustomSpellTimer()
    if customSpellCheckEvent then
        removeEvent(customSpellCheckEvent)
        customSpellCheckEvent = nil
    end
end

function checkCustomSpells()
    if not hotkeyHelperStatus or not helperConfig.magicShooterEnabled then
        return
    end

    local profile = getShooterProfile()
    if not profile then
        return
    end

    for i, spell in ipairs(profile.spells) do
        if spell.enabled and spell.id == -1 and spell.customText and spell.customText ~= "" then
            local lastCastKey = "customSpell_" .. spell.customText
            local lastCastTime = customSpellTimers[lastCastKey] or 0
            local cooldown = spell.cooldown or 2000
            local currentTime = g_clock.millis()

            if currentTime - lastCastTime >= cooldown then
                g_game.talk(spell.customText)
                customSpellTimers[lastCastKey] = currentTime
                break -- Cast only one custom spell per cycle
            end
        end
    end
end

