function parseCommaSeparatedItemIds(str)
    local out = {}
    if not str or str == "" then
        return out
    end
    for part in string.gmatch(str, "[^,]+") do
        local trimmed = part:match("^%s*(.-)%s*$")
        local n = tonumber(trimmed)
        if n and n > 0 then
            table.insert(out, n)
        end
    end
    return out
end

function appendUniqueIdToCommaText(text, id)
    if not id or id <= 0 then
        return text or ""
    end
    local ids = parseCommaSeparatedItemIds(text or "")
    if table.find(ids, id) then
        return text or ""
    end
    table.insert(ids, id)
    return table.concat(ids, ", ")
end

function getExerciseWeaponIdListOrdered()
    local text = ""
    if toolsPanel then
        local edit = toolsPanel:recursiveGetChildById("exerciseTrainingIdsEdit")
        if edit then
            text = edit:getText() or ""
        end
    end
    if text == "" and helperConfig.exerciseWeaponIdsText and helperConfig.exerciseWeaponIdsText ~= "" then
        text = helperConfig.exerciseWeaponIdsText
    end
    return parseCommaSeparatedItemIds(text)
end

function refreshTrainingIdsGrid(gridId, text)
    if not toolsPanel then
        return
    end
    local grid = toolsPanel:recursiveGetChildById(gridId)
    if not grid then
        return
    end
    grid:destroyChildren()

    local seen = {}
    for _, id in ipairs(parseCommaSeparatedItemIds(text or "")) do
        if not seen[id] then
            seen[id] = true
            local item = g_ui.createWidget("HelperPreviewItem", grid)
            if item then
                item:setItemId(id)
                local name = resolveHelperItemNameById(id)
                if name and name ~= "" then
                    item:setTooltip(name .. " (" .. id .. ")")
                else
                    item:setTooltip(tostring(id))
                end
            end
        end
    end
end

