function saveExerciseStaminaSettings()
    local rootWidget = g_ui.getRootWidget()
    local window = rootWidget:recursiveGetChildById("exerciseStaminaSettingsWindow")
    if not window then
        return
    end
    local minEdit = window:recursiveGetChildById("minStaminaHours")
    local maxEdit = window:recursiveGetChildById("maxStaminaHours")
    local minH = minEdit and (tonumber(minEdit:getText()) or 0) or 0
    local maxH = maxEdit and (tonumber(maxEdit:getText()) or 0) or 0
    if minH < 0 then minH = 0 end
    if maxH < 0 then maxH = 0 end
    if minH > 42 then minH = 42 end
    if maxH > 42 then maxH = 42 end
    helperConfig.exerciseMinStaminaHours = minH
    helperConfig.exerciseMaxStaminaHours = maxH
    saveSettings()
    window:destroy()
end

function checkExerciseEvent()
    if not toolsPanel then
        return
    end

    local checkBox = toolsPanel:recursiveGetChildById("autoTrainingCheck")

    if not checkBox then
        return
    end

    -- Save the checkbox state
    onAutoTrainingCheckChange(checkBox:isChecked())

    if not checkBox:isChecked() then
        return
    end

    if not player then
        return
    end

    -- Stamina-range gate: skip if outside the configured window. 0 = ignore.
    local minH = tonumber(helperConfig.exerciseMinStaminaHours) or 0
    local maxH = tonumber(helperConfig.exerciseMaxStaminaHours) or 0
    if minH > 0 or maxH > 0 then
        local staminaH = (player:getStamina() or 0) / 60
        if minH > 0 and staminaH >= minH then
            return
        end
        if maxH > 0 and staminaH >= maxH then
            return
        end
    end

    -- Detect exercise weapon across open + closed containers (uses server-cached inventory count)
    local itemId = nil
    for _, id in ipairs(getExerciseWeaponIdListOrdered()) do
        if getItemCountAnywhere(id) > 0 then
            itemId = id
            break
        end
    end

    -- Fallback: if detection failed (e.g. server cache miss), use the first user-configured ID.
    -- useInventoryItemWith sends pos (0xFFFF,0,0) so the server searches the full inventory anyway.
    if not itemId then
        local userList = parseCommaSeparatedItemIds(helperConfig.exerciseWeaponIdsText or "")
        if #userList > 0 then
            itemId = userList[1]
        end
    end

    if not itemId then
        return
    end

    local dummyIds = getSelectedDummyIds()
    local dummy = getExerciseDummyByIds(dummyIds)

    if not dummy then
        return
    end

    g_game.useInventoryItemWith(itemId, dummy)
end

function getSelectedDummyIds()
    local text = ""
    if toolsPanel then
        local edit = toolsPanel:recursiveGetChildById("dummyTrainingIdsEdit")
        if edit then
            text = edit:getText() or ""
        end
    end
    if text == "" and helperConfig.trainingDummyIdsText and helperConfig.trainingDummyIdsText ~= "" then
        text = helperConfig.trainingDummyIdsText
    end
    local dummyIds = parseCommaSeparatedItemIds(text)
    if helperConfig.useDefaultDummies ~= false then
        for _, id in ipairs(exerciseLists.dummies) do
            if not table.find(dummyIds, id) then
                table.insert(dummyIds, id)
            end
        end
    end
    return dummyIds
end

function getExerciseDummyByIds(dummyIds)
    local playerPos = player:getPosition()
    for _, id in ipairs(dummyIds) do
        local items = g_map.findItemsById(id, 5)
        if items then
            local itemList = {}
            for pos, ptr in pairs(items) do
                if pos.z == playerPos.z then
                    itemList[#itemList + 1] = { position = pos, item = ptr }
                end
            end
            table.sort(
                itemList,
                function(a, b)
                    return getDistanceBetween(playerPos, a.position) < getDistanceBetween(playerPos, b.position)
                end
            )
            for _, data in ipairs(itemList) do
                if g_map.isSightClear(data.position, playerPos) then
                    return data.item
                end
            end
        end
    end
    return nil
end

