-- Assign Item by ID modal variables
local assignItemIdWindow = nil
local assignItemIdTargetButton = nil
local assignItemIdType = nil
local assignItemIdTimerIndex = nil

function openAssignItemIdWindow(button, itemType, timerIndex)
    -- Close previous window if exists
    if assignItemIdWindow then
        assignItemIdWindow:destroy()
        assignItemIdWindow = nil
    end

    assignItemIdTargetButton = button
    assignItemIdType = itemType
    assignItemIdTimerIndex = timerIndex

    -- Load the window from OTUI
    assignItemIdWindow = g_ui.displayUI('assign_item_id')
    applyOpacityToWindow(assignItemIdWindow)

    assignItemIdWindow.onDestroy = function()
        assignItemIdWindow = nil
    end

    -- Focus on the text field
    local textEdit = assignItemIdWindow:recursiveGetChildById('itemIdTextEdit')
    if textEdit then
        textEdit:focus()
    end
    modalEnter(assignItemIdWindow)
end

function closeAssignItemIdWindow()
    if assignItemIdWindow then
        assignItemIdWindow:hide()
        assignItemIdWindow:destroy()
        assignItemIdWindow = nil
    end
    assignItemIdTargetButton = nil
    assignItemIdType = nil
    assignItemIdTimerIndex = nil
end

function onAssignItemIdTextChange()
    if not assignItemIdWindow then
        return
    end

    local textEdit = assignItemIdWindow:recursiveGetChildById('itemIdTextEdit')
    local itemPreview = assignItemIdWindow:recursiveGetChildById('itemPreview')
    local itemNameLabel = assignItemIdWindow:recursiveGetChildById('itemNameLabel')

    if not textEdit or not itemPreview or not itemNameLabel then
        return
    end

    local idText = textEdit:getText()
    local itemId = tonumber(idText)

    if itemId and itemId > 0 then
        itemPreview:setItemId(itemId)
        -- Try to get item name from client data
        local itemType = g_things.getThingType(itemId, ThingCategoryItem)
        if itemType and itemType:getId() > 0 then
            local marketData = itemType:getMarketData()
            if marketData and marketData.name and marketData.name ~= "" then
                itemNameLabel:setText(marketData.name)
            else
                itemNameLabel:setText("ID: " .. itemId)
            end
        else
            itemNameLabel:setText("Unknown Item")
        end
    else
        itemPreview:setItemId(0)
        itemNameLabel:setText("")
    end
end

function assignItemIdAccept()
    if not assignItemIdWindow or not assignItemIdTargetButton then
        closeAssignItemIdWindow()
        return
    end

    local textEdit = assignItemIdWindow:recursiveGetChildById('itemIdTextEdit')
    if not textEdit then
        closeAssignItemIdWindow()
        return
    end

    local idText = textEdit:getText()
    local itemId = tonumber(idText)

    if not itemId or itemId <= 0 then
        modules.game_textmessage.displayFailureMessage(tr("Invalid item ID!"))
        closeAssignItemIdWindow()
        return
    end

    if assignItemIdType == "exercise" then
        if not table.find(exerciseLists.weapons, itemId) then
            modules.game_textmessage.displayFailureMessage(tr("Invalid exercise!"))
            closeAssignItemIdWindow()
            return
        end
    end

    local button = assignItemIdTargetButton
    local itemType = assignItemIdType
    local timerIndex = assignItemIdTimerIndex

    closeAssignItemIdWindow()

    -- Apply item based on type
    if itemType == "potion" then
        local index = tonumber(button:getId():match("%d+"))
        applyPotionToButton(button, itemId)
        helperConfig.potions[index + 1].id = itemId
        saveSettings()
    elseif itemType == "amulet" then
        applyAmuletToButton(button, itemId)
        saveSettings()
    elseif itemType == "ring" then
        applyRingToButton(button, itemId)
        saveSettings()
    elseif itemType == "dummy" then
        applyDummyToButton(button, itemId)
    elseif itemType == "exercise" then
        applyExerciseToButton(button, itemId)
    elseif itemType == "tankModeAmulet" then
        applyTankModeAmuletToButton(button, itemId)
    elseif itemType == "tankModeRing" then
        applyTankModeRingToButton(button, itemId)
    elseif itemType == "timer" and timerIndex then
        updateTimerItemButton(button, itemId, timerIndex, 1)
    elseif itemType == "timerPopupItem" then
        modules.game_helper.setTimerPopupItemId(itemId, 1)
    elseif itemType == "healingPopupItem" then
        modules.game_helper.setHealingPopupItemId(itemId, 1)
    elseif itemType == "shooterPopupRune" then
        modules.game_helper.setShooterPopupRuneId(itemId)
    elseif itemType == "equipmentPopupItem" then
        modules.game_helper.setEquipmentPopupMainItemId(itemId)
    elseif itemType == "equipmentPopupDontExecute" then
        setEquipmentPopupDontExecuteItemId(timerIndex or 0, itemId)
    elseif itemType == "rune" then
        local profile = getShooterProfile()
        local index = tonumber(button:getId():match("%d+"))
        applyRuneToButton(button, itemId)
        profile.runes[index + 1].id = itemId
        saveSettings()
        updateAllItemCounts()
    elseif itemType == "excludeAmulet" then
        local index = tonumber(button:getId():match("%d+"))
        applyExcludeAmuletById(button, itemId, index)
    elseif itemType == "excludeRing" then
        local index = tonumber(button:getId():match("%d+"))
        applyExcludeRingById(button, itemId, index)
    elseif itemType == "supply" then
        local index = timerIndex -- timerIndex is used to pass the supply index
        if index and modules.game_helper.hunting_recorderModule then
            modules.game_helper.hunting_recorderModule.applySupplyById(button, itemId, index)
        end
    end
end

-- Helper functions to apply items to buttons by ID
function applyPotionToButton(button, potionId)
    button:setImageSource("/images/ui/item")
    if not button:getChildById("potionItem") then
        local itemWidget = g_ui.createWidget("PotionItem", button)
        if itemWidget then
            itemWidget:setId("potionItem")
        end
    end
    local itemWidget = button:getChildById("potionItem")
    if itemWidget then
        itemWidget:setItemId(potionId)
    end
end

function applyAmuletToButton(button, amuletId)
    updateAmuletButton(button, amuletId)
end

function applyRingToButton(button, ringId)
    updateRingButton(button, ringId)
end

function applyDummyToButton(button, dummyId)
    helperConfig.trainingDummyIdsText = appendUniqueIdToCommaText(helperConfig.trainingDummyIdsText, dummyId)
    local edit = toolsPanel and toolsPanel:recursiveGetChildById("dummyTrainingIdsEdit")
    if edit then
        edit:setText(helperConfig.trainingDummyIdsText)
    end
    saveSettings()
end

function applyExerciseToButton(button, exerciseId)
    helperConfig.exerciseWeaponIdsText = appendUniqueIdToCommaText(helperConfig.exerciseWeaponIdsText, exerciseId)
    helperConfig.exerciseWeaponId = exerciseId
    local edit = toolsPanel and toolsPanel:recursiveGetChildById("exerciseTrainingIdsEdit")
    if edit then
        edit:setText(helperConfig.exerciseWeaponIdsText)
    end
    saveSettings()
end

function applyTankModeAmuletToButton(button, amuletId)
    updateTankModeAmuletButton(button, amuletId)
    helperConfig.tankModeAmuletId = amuletId
    saveSettings()
end

function applyTankModeRingToButton(button, ringId)
    updateTankModeRingButton(button, ringId)
    helperConfig.tankModeRingId = ringId
    saveSettings()
end

function applyRuneToButton(button, runeId)
    local profile = getShooterProfile()
    local index = tonumber(button:getId():match("%d+"))
    button:setImageSource("/images/ui/item")
    if not button.runeItem then
        button.runeItem = g_ui.createWidget("RuneItem", button)
    end
    if button.runeItem then
        button.runeItem:setItemId(runeId)
    end
end

function applyExcludeAmuletById(button, itemId, index)
    -- Try to get the popup from different sources
    local popup = equipmentSettingsPopup
    if not popup or popup:isDestroyed() then
        local rootWidget = g_ui.getRootWidget()
        if rootWidget then
            popup = rootWidget:recursiveGetChildById("equipmentSettingsPopup")
        end
    end

    if not popup or popup:isDestroyed() then
        return
    end

    button:setImageSource("/images/ui/item")

    if not button:getChildById("excludeAmuletItem" .. index) then
        local itemWidget = g_ui.createWidget("RuneItem", button)
        itemWidget:setId("excludeAmuletItem" .. index)
        itemWidget:setSize({ width = 32, height = 32 })
    end

    local itemWidget = button:getChildById("excludeAmuletItem" .. index)
    if itemWidget then
        itemWidget:setItemId(itemId)
    end

    local popupItemType = popup.itemType
    local popupIndex = popup.itemIndex

    if popupItemType == "amulet" then
        local config = helperConfig.amulets[popupIndex + 1]
        if config then
            if not config.excludeAmuletIds then
                config.excludeAmuletIds = { 0, 0 }
            end
            config.excludeAmuletIds[index + 1] = itemId
        end
    elseif popupItemType == "ring" then
        local config = helperConfig.rings[popupIndex + 1]
        if config then
            if not config.excludeAmuletIds then
                config.excludeAmuletIds = { 0, 0 }
            end
            config.excludeAmuletIds[index + 1] = itemId
        end
    end

    saveSettings()
end

function applyExcludeRingById(button, itemId, index)
    -- Try to get the popup from different sources
    local popup = equipmentSettingsPopup
    if not popup or popup:isDestroyed() then
        local rootWidget = g_ui.getRootWidget()
        if rootWidget then
            popup = rootWidget:recursiveGetChildById("equipmentSettingsPopup")
        end
