-- Assign Item List modal variables
local assignItemListWindow = nil
local assignItemListTargetButton = nil
local assignItemListType = nil
local assignItemListTimerIndex = nil
local assignItemListSelectedItem = nil
local assignItemListCurrentCategory = "all"

-- Get sorted category names for the combo box
local function getItemListCategories()
    local categories = { "all" }
    for category, _ in pairs(ITEM_LIST_DATA) do
        table.insert(categories, category)
    end
    table.sort(categories, function(a, b)
        if a == "all" then return true end
        if b == "all" then return false end
        return a < b
    end)
    return categories
end

-- Get items filtered by category and search text
local function getFilteredItems(category, searchText)
    local items = {}
    searchText = searchText and searchText:lower() or ""

    if category == "all" then
        for _, categoryItems in pairs(ITEM_LIST_DATA) do
            for _, item in ipairs(categoryItems) do
                if searchText == "" or item.itemName:lower():find(searchText, 1, true) then
                    table.insert(items, item)
                end
            end
        end
    else
        local categoryItems = ITEM_LIST_DATA[category]
        if categoryItems then
            for _, item in ipairs(categoryItems) do
                if searchText == "" or item.itemName:lower():find(searchText, 1, true) then
                    table.insert(items, item)
                end
            end
        end
    end

    table.sort(items, function(a, b)
        return a.itemName < b.itemName
    end)

    return items
end

function openAssignItemListWindow(button, itemType, timerIndex)
    -- Close previous window if exists
    if assignItemListWindow then
        assignItemListWindow:destroy()
        assignItemListWindow = nil
    end

    assignItemListTargetButton = button
    assignItemListType = itemType
    assignItemListTimerIndex = timerIndex
    assignItemListSelectedItem = nil
    assignItemListCurrentCategory = "all"

    -- Load the window from OTUI
    assignItemListWindow = g_ui.displayUI('assign_item_list')
    applyOpacityToWindow(assignItemListWindow)

    assignItemListWindow.onDestroy = function()
        assignItemListWindow = nil
    end

    -- Populate category combo box
    local categoryComboBox = assignItemListWindow:recursiveGetChildById('categoryComboBox')
    if categoryComboBox then
        categoryComboBox:clearOptions()
        local categories = getItemListCategories()
        for _, category in ipairs(categories) do
            local displayName = category:sub(1, 1):upper() .. category:sub(2)
            categoryComboBox:addOption(displayName, category)
        end
        categoryComboBox:setCurrentIndex(1)
    end

    -- Populate initial item list
    populateItemList()

    -- Focus on search field
    local searchEdit = assignItemListWindow:recursiveGetChildById('searchTextEdit')
    if searchEdit then
        searchEdit:focus()
    end
    modalEnter(assignItemListWindow)
end

function closeAssignItemListWindow()
    if assignItemListWindow then
        assignItemListWindow:hide()
        assignItemListWindow:destroy()
        assignItemListWindow = nil
    end
    assignItemListTargetButton = nil
    assignItemListType = nil
    assignItemListTimerIndex = nil
    assignItemListSelectedItem = nil
end

function populateItemList()
    if not assignItemListWindow then
        return
    end

    local itemListBox = assignItemListWindow:recursiveGetChildById('itemListBox')
    local searchEdit = assignItemListWindow:recursiveGetChildById('searchTextEdit')
    local categoryComboBox = assignItemListWindow:recursiveGetChildById('categoryComboBox')

    if not itemListBox then
        return
    end

    -- Clear existing items
    itemListBox:destroyChildren()

    -- Get current filter values
    local searchText = searchEdit and searchEdit:getText() or ""
    local categoryIndex = categoryComboBox and categoryComboBox:getCurrentIndex() or 1
    local categories = getItemListCategories()
    local category = categories[categoryIndex] or "all"
    assignItemListCurrentCategory = category

    -- Get filtered items
    local items = getFilteredItems(category, searchText)

    -- Populate list
    for _, item in ipairs(items) do
        local label = g_ui.createWidget('ListRowLabel', itemListBox)
        label:setText(item.itemName)
        label.itemData = item
    end

    -- Clear selection
    assignItemListSelectedItem = nil
    updateItemListPreview()
end

function onItemListCategoryChange()
    populateItemList()
end

function onItemListSearchChange()
    populateItemList()
end

function onItemListSelectionChange(listBox, focusedChild, unfocusedChild, reason)
    if not assignItemListWindow then
        return
    end

    local itemListBox = assignItemListWindow:recursiveGetChildById('itemListBox')
    if not itemListBox then
        return
    end

    local selectedChild = itemListBox:getFocusedChild()
    if selectedChild and selectedChild.itemData then
        assignItemListSelectedItem = selectedChild.itemData
    else
        assignItemListSelectedItem = nil
    end

    updateItemListPreview()
end

function updateItemListPreview()
    if not assignItemListWindow then
        return
    end

    local itemPreview = assignItemListWindow:recursiveGetChildById('itemPreview')
    local selectedItemLabel = assignItemListWindow:recursiveGetChildById('selectedItemLabel')

    if not itemPreview or not selectedItemLabel then
        return
    end

    if assignItemListSelectedItem then
        itemPreview:setItemId(assignItemListSelectedItem.clientId)
        selectedItemLabel:setText(assignItemListSelectedItem.itemName .. "\nID: " .. assignItemListSelectedItem.clientId)
    else
        itemPreview:setItemId(0)
        selectedItemLabel:setText("")
    end
end

function assignItemListAccept()
    if not assignItemListWindow or not assignItemListTargetButton or not assignItemListSelectedItem then
        closeAssignItemListWindow()
        return
    end

    local itemId = assignItemListSelectedItem.clientId
    local button = assignItemListTargetButton
    local itemType = assignItemListType
    local timerIndex = assignItemListTimerIndex

    closeAssignItemListWindow()

    -- Apply item based on type (reuse the same logic as assignItemIdAccept)
    if itemType == "potion" then
        local index = tonumber(button:getId():match("%d+"))
        applyPotionToButton(button, itemId)
        helperConfig.potions[index + 1].id = itemId
        saveSettings()
    elseif itemType == "amulet" then
        applyAmuletToButton(button, itemId)
        saveSettings()
    elseif itemType == "ring" then
        applyRingToButton(button, itemId)
        saveSettings()
    elseif itemType == "dummy" then
        applyDummyToButton(button, itemId)
    elseif itemType == "exercise" then
        applyExerciseToButton(button, itemId)
    elseif itemType == "tankModeAmulet" then
        applyTankModeAmuletToButton(button, itemId)
    elseif itemType == "tankModeRing" then
        applyTankModeRingToButton(button, itemId)
    elseif itemType == "timer" and timerIndex then
        updateTimerItemButton(button, itemId, timerIndex, 1)
    elseif itemType == "timerPopupItem" then
        modules.game_helper.setTimerPopupItemId(itemId, 1)
    elseif itemType == "healingPopupItem" then
        modules.game_helper.setHealingPopupItemId(itemId, 1)
    elseif itemType == "shooterPopupRune" then
        modules.game_helper.setShooterPopupRuneId(itemId)
    elseif itemType == "equipmentPopupItem" then
        modules.game_helper.setEquipmentPopupMainItemId(itemId)
    elseif itemType == "equipmentPopupDontExecute" then
        setEquipmentPopupDontExecuteItemId(timerIndex or 0, itemId)
    elseif itemType == "rune" then
        local profile = getShooterProfile()
        local index = tonumber(button:getId():match("%d+"))
        applyRuneToButton(button, itemId)
        profile.runes[index + 1].id = itemId
        saveSettings()
        updateAllItemCounts()
    elseif itemType == "excludeAmulet" then
        local index = tonumber(button:getId():match("%d+"))
        applyExcludeAmuletById(button, itemId, index)
    elseif itemType == "excludeRing" then
        local index = tonumber(button:getId():match("%d+"))
        applyExcludeRingById(button, itemId, index)
    elseif itemType == "supply" then
        local index = timerIndex -- timerIndex is used to pass the supply index
        if index and modules.game_helper.hunting_recorderModule then
            modules.game_helper.hunting_recorderModule.applySupplyById(button, itemId, index)
        end
    end
end

function onCheckPotionPriority(button)
    local index = tonumber(button:getId():match("%d+"))
    if not helperConfig.potions[index + 1] then
        return true
    end

    -- Inicializar priority se nao existir
    if not helperConfig.potions[index + 1].priority then
        helperConfig.potions[index + 1].priority = 1
        button.actionId = 1
    end

    if button.actionId == 1 then
        button.actionId = 2
        button:setImageSource("/images/skin/show-gui-help-blue")
        button:setTooltip("This potion is healing mana...")
        helperConfig.potions[index + 1].priority = 2
    else
        button.actionId = 1
        button:setImageSource("/images/ui/show-gui-help-orange.png")
        button:setTooltip("This potion is healing health...")
        helperConfig.potions[index + 1].priority = 1
    end
end

function onCheckSpellPriority(button)
    local index = tonumber(button:getId():match("%d+"))
    if not helperConfig.spells[index + 1] then
        return true
    end

    if not helperConfig.spells[index + 1].priority then
        helperConfig.spells[index + 1].priority = 1
        button.actionId = 1
    end

    if helperConfig.spells[index + 1].priority == 0 or helperConfig.spells[index + 1].id == 0 then
        return true
    end

    if button.actionId == 1 then
        button.actionId = 2
        button:setImageSource("/images/skin/show-gui-help-blue")
        button:setTooltip("This spell is healing mana...")
        helperConfig.spells[index + 1].priority = 2
    else
        button.actionId = 1
        button:setImageSource("/images/ui/show-gui-help-orange.png")
        button:setTooltip("This spell is healing health...")
        helperConfig.spells[index + 1].priority = 1
    end
end

