function botStatus()
    local helperStatus = helper and helper:recursiveGetChildById("helperStatus")
    local helperStatusLabel = helper and helper:recursiveGetChildById("helperStatusLabel")

    if not helperStatus or not helperStatusLabel then
        return
    end

    hotkeyHelperStatus = not hotkeyHelperStatus
    _G.hotkeyHelperStatus = hotkeyHelperStatus -- Atualizar referencia global

    if hotkeyHelperStatus then
        helperStatus:setImageSource("/images/store/icon-yes")
        helperStatusLabel:setText("Enabled")
        helperStatus:setTooltip(
            " - Helper Status: Enabled\n\nYou can Enable or Disable the helper using\nthe default hotkey (Pause Break).\n\nAlso you can change the hotkey on settings."
        )
        modules.game_textmessage.displayFailureMessage(tr("Helper Status: Enabled"))
    else
        helperStatus:setImageSource("/images/store/icon-no")
        helperStatusLabel:setText("Disabled")
        helperStatus:setTooltip(
            " - Helper Status: Disabled\n\nYou can Enable or Disable the helper using\nthe default hotkey (Pause Break).\n\nAlso you can change the hotkey on settings."
        )
        modules.game_textmessage.displayFailureMessage(tr("Helper Status: Disabled"))
    end

    applyGlobalHelperRuntimeState()

    -- Update tracker window
    if HelperTrackerModule and HelperTrackerModule.updateHelperStatus then
        HelperTrackerModule.updateHelperStatus(hotkeyHelperStatus)
    end

    -- Update icon stats window
    if IconStatsModule and IconStatsModule.updateHelperIcon then
        IconStatsModule.updateHelperIcon(hotkeyHelperStatus)
    end
end

function toggleNextWindow()
    local widgetList = {
        "healingMenu",
        "toolsMenu",
        "huntingMenu"
    }

    -- Adicionar friendMenu para: Druid, Sorcerer, Paladin e Monk
    if player then
        local vocationId = translateVocation(player:getVocation())
        if vocationId == VOCATION_DRUID or vocationId == VOCATION_SORCERER or
            vocationId == VOCATION_PALADIN or vocationId == VOCATION_MONK then
            table.insert(widgetList, "friendMenu")
        end
    end

    local selectedIndex = nil
    for i, widget in ipairs(widgetList) do
        if widget == menuId then
            selectedIndex = i
            break
        end
    end

    if not selectedIndex then
        selectedIndex = 1
    end

    local nextWidgetId = (selectedIndex == #widgetList and 1 or selectedIndex + 1)
    menuId = widgetList[nextWidgetId]
    loadMenu(menuId)
end

local function findHotkeyIndex(category, action, chatMode)
    local list = Keybind.hotkeys[chatMode] and Keybind.hotkeys[chatMode][Keybind.currentPreset]
    if not list then
        return nil
    end
    for i, hotkey in ipairs(list) do
        if hotkey.action == action then
            return i
        end
    end
    return nil
end

function manageHotkeys(typo)
    helper:hide()
    local assignWindow = g_ui.createWidget("ActionAssignWindow", rootWidget)
    applyOpacityToWindow(assignWindow)
    assignWindow:grabKeyboard()
    assignWindow:grabMouse()

    local chatMode = Keybind.chatMode
    local currentHotkey = ""

    local keys = Keybind.getKeybindKeys("Helper", typo, chatMode)
    if keys then
        currentHotkey = keys.primary or ""
    end

    -- Verificar se os campos existem antes de usar
    if assignWindow.contentPanel and assignWindow.contentPanel.instructionLabel then
        assignWindow.contentPanel.instructionLabel:setText("Press key for: " .. typo)
    end
    assignWindow:setHeight(190)
    safeSetInputLockWidget(assignWindow)

    local selectedKey = currentHotkey

    assignWindow.onKeyDown = function(assignWindow, keyCode, keyboardModifiers, keyText)
        local keyCombo = determineKeyComboDesc(keyCode, keyboardModifiers, keyText)
        local resetCombo = { "Shift", "Ctrl", "Alt" }

        -- Reseta se apertou só modificador
        if table.contains(resetCombo, keyCombo) then
            assignWindow:instructionLabel():setText(tr("Press any key to assign..."))
            assignWindow:warning():setVisible(false)
            assignWindow:buttonOk():setEnabled(false)
            return true
        end

        selectedKey = keyCombo

        -- Texto principal com quebra automática
        assignWindow:instructionLabel():setText(tr("Key: ") .. keyCombo)
        assignWindow:instructionLabel():setWordWrap(true)  -- quebra linha
        assignWindow:instructionLabel():setMultiline(true) -- permite várias linhas

        -- Verifica se a hotkey já existe
        local isUsed = Keybind.isKeyComboUsed(keyCombo, "Helper", typo, chatMode)

        if isUsed then
            assignWindow:warning():setText(tr("This hotkey is already in use\nand will be overwritten."))
            assignWindow:warning():setVisible(true)
            assignWindow:warning():setColor("#ff6666")
        else
            assignWindow:warning():setVisible(false)
        end

        assignWindow:buttonOk():setEnabled(true)
        return true
    end

    assignWindow.onMousePress = function(widget, pos, button)
        if button ~= MouseButton4 and button ~= MouseButton5 then
            return false
        end

        local modifiers = {}
        if g_keyboard.isCtrlPressed() then
            table.insert(modifiers, "Ctrl")
        end
        if g_keyboard.isShiftPressed() then
            table.insert(modifiers, "Shift")
        end
        if g_keyboard.isAltPressed() then
            table.insert(modifiers, "Alt")
        end

        if button == MouseButton4 then
            table.insert(modifiers, "MB4")
        elseif button == MouseButton5 then
            table.insert(modifiers, "MB5")
        end

        local keyCombo = table.concat(modifiers, "+")
        selectedKey = keyCombo
        if assignWindow.contentPanel and assignWindow.contentPanel.instructionLabel then
            assignWindow.contentPanel.instructionLabel:setText("Key: " .. keyCombo)
        end
        if assignWindow.warning then
            assignWindow.warning:setVisible(false)
        end
        if assignWindow.contentPanel and assignWindow.contentPanel:getChildById("buttonOk") then
            assignWindow.contentPanel:getChildById("buttonOk"):setEnabled(true)
        end

        if Keybind.isKeyComboUsed(keyCombo, "Helper", typo, chatMode) then
            if assignWindow.warning then
                assignWindow.warning:setVisible(true)
                assignWindow.warning:setText("This hotkey is already in use and will be overwritten.")
            end
        else
            if assignWindow.warning then
                assignWindow.warning:setVisible(false)
            end
        end

        return true
    end

    if assignWindow.contentPanel and assignWindow.contentPanel:getChildById("buttonOk") then
        assignWindow.contentPanel:getChildById("buttonOk").onClick = function()
            local newKey = selectedKey or ""
            local preset = Keybind.currentPreset
            if not newKey or #newKey == 0 then
                pcall(function()
                    Keybind.setPrimaryActionKey("Helper", typo, preset, "", chatMode)
                end)
            else
                pcall(function()
                    Keybind.setPrimaryActionKey("Helper", typo, preset, newKey, chatMode)
                end)
            end

            g_settings.save()
            assignWindow:destroy()
            safeSetInputLockWidget(nil)
        end
    end

    if assignWindow.contentPanel and assignWindow.contentPanel:getChildById("buttonCancel") then
        assignWindow.contentPanel:getChildById("buttonCancel").onClick = function()
            assignWindow:destroy()
            safeSetInputLockWidget(nil)
        end
    end

    assignWindow.onDestroy = function(widget)
        helper:show(true)
    end
end

function onDropSpell(widget, spellWords)
    local spellData = Spells.getSpellDataByWords(spellWords)
    if not spellData then
        return
    end

    local isHealingPanel = string.match(widget:getId(), "^spellButton%d*")
    local isTrainingPanel = string.match(widget:getId(), "^spellTrainingButton")
    local isHastePanel = string.match(widget:getId(), "^hasteButton")
    local isCureParalyzePanel = string.match(widget:getId(), "^cureParalyzeButton")
    local isAttackPanel = string.match(widget:getId(), "^attackSpellButton%d*")
    local profile = getShooterProfile()

    if isHealingPanel then
        onSetupDropSpell(widget, spellData, { 2 }, helperConfig.spells)
    elseif isTrainingPanel or isHastePanel or isCureParalyzePanel then
        local mode = "training"
        if isHastePanel then
            mode = "haste"
        elseif isCureParalyzePanel then
            mode = "cureParalyze"
        end
        onSetupDropSupport(widget, spellData, mode)
    elseif isAttackPanel then
        onSetupDropSpell(widget, spellData, { 1, 4, 8 }, profile.spells)
    end
end

function onSetupDropSpell(button, spellData, groups, tableToAssign)
    local groupIds = Spells.getGroupIds(spellData)
    local function containsAnyGroup(groups, targetGroups)
        for _, group in ipairs(targetGroups) do
            if table.contains(groups, group) then
                return true
            end
        end
        return false
    end

    local spellId = SpellIcons[spellData.icon][1]
    local spellProfile = SpellIcons[spellData.icon][3] or "Default"
    local playerVocation = translateVocation(player:getVocation())
    local profile = getShooterProfile()

    if
        containsAnyGroup(groupIds, groups) and table.contains(spellData.vocations, playerVocation) and
        not ignoredSpellsIds[spellId]
    then
        local source = SpelllistSettings[spellProfile] and SpelllistSettings[spellProfile].iconsFolder or
        SpelllistSettings["Default"].iconsFolder
        local clip = Spells.getImageClipNormal(spellId, SpelllistSettings[spellProfile] and spellProfile or "Default")
        local spell = Spells.getSpellByClientId(tonumber(spellId))

        button:setImageSource(source)
        button:setImageClip(clip)
        button:setBorderColorTop("#1b1b1b")
        button:setBorderColorLeft("#1b1b1b")
        button:setBorderColorRight("#757575")
        button:setBorderColorBottom("#757575")
        button:setBorderWidth(1)
        button:setTooltip("Spell: " .. spellData.name .. "\nWords: " .. spellData.words)

        local slotID = tonumber(button:getId():match("%d+"))
        if button:getId():find("attackSpellButton") then
            profile.spells[slotID + 1].id = tonumber(spellData.id)
        else
            tableToAssign[slotID + 1].id = tonumber(spellData.id)
        end

        if button:getId():find("attackSpellButton") then
            local creaturesMin = shooterPanel:recursiveGetChildById("countMinCreature" .. slotID)
            local forceCast = shooterPanel:recursiveGetChildById("conditionSetting" .. slotID)
            local selfCast = shooterPanel:recursiveGetChildById("selfCast" .. slotID)
            if table.contains(bothCastTypeSpells, spell.id) then -- divine grenade self cast
                if not selfCast then
                    selfCast = g_ui.createWidget("CheckBox", creaturesMin:getParent())
                    local style = {
                        ["width"] = 12,
                        ["anchors.top"] = "countMinCreature" .. slotID .. ".top",
                        ["anchors.left"] = "countMinCreature" .. slotID .. ".right",
                        ["margin-top"] = 6,
                        ["margin-left"] = 5
                    }
                    selfCast:mergeStyle(style)
                    selfCast:setId("selfCast" .. slotID)
                    selfCast:setTooltip("Cast on yourself")
                    selfCast:setVisible(true)
                    selfCast.onCheckChange = function()
                        toggleSelfCast(selfCast:getId():match("%d+"), selfCast:isChecked())
                    end
                end
            end

            if selfCast and not table.contains(bothCastTypeSpells, spell.id) then
                profile.spells[slotID + 1].selfCast = false
                selfCast:destroy()
            end

            if (spell.range > 0 and not spell.area) and not table.contains(bothCastTypeSpells, spell.id) then
                profile.spells[slotID + 1].creatures = 1
                creaturesMin:setCurrentOption("1+")
                creaturesMin:disable()
                if forceCast then
                    forceCast:setChecked(profile.spells[slotID + 1].forceCast)
                    forceCast:setVisible(true)
                end
            else
                creaturesMin:enable()
                if forceCast then
                    forceCast:setChecked(false)
                    forceCast:setVisible(false)
                    profile.spells[slotID + 1].forceCast = false
                end
            end
        end
    end
end

function onSetupDropSupport(widget, spellData, mode)
    local playerVocation = translateVocation(player:getVocation())
    local isHaste = mode == "haste"
    local isCureParalyze = mode == "cureParalyze"

    if isHaste and (not hasteWhiteList[playerVocation] or not table.contains(hasteWhiteList[playerVocation], spellData.id)) then
        return
    end

    if isCureParalyze then
        local groups = Spells.getGroupIds(spellData)
        local isValidSpell = table.contains(groups, 2) or spellData.category == "Healing"
        if not isValidSpell and hasteWhiteList[playerVocation] and table.contains(hasteWhiteList[playerVocation], spellData.id) then
            isValidSpell = true
        end
        if not isValidSpell then
            return
        end
    end

    if
        not isHaste and not isCureParalyze and
        not (table.contains(Spells.getGroupIds(spellData), 3) or table.contains(Spells.getGroupIds(spellData), 2))
    then
        return
    end

    if not isHaste and not isCureParalyze and hasteWhiteList[playerVocation] and table.contains(hasteWhiteList[playerVocation], spellData.id) then
        return
    end

    local spellId = SpellIcons[spellData.icon][1]
    local spellProfile = SpellIcons[spellData.icon][3] or "Default"
    if table.contains(spellData.vocations, playerVocation) and not ignoredTrainingSpells[spellData.id] then
        local source = SpelllistSettings[spellProfile] and SpelllistSettings[spellProfile].iconsFolder or
        SpelllistSettings["Default"].iconsFolder
        local clip = Spells.getImageClipNormal(spellId, SpelllistSettings[spellProfile] and spellProfile or "Default")

        widget:setImageSource(source)
        widget:setImageClip(clip)
        widget:setBorderColorTop("#1b1b1b")
        widget:setBorderColorLeft("#1b1b1b")
        widget:setBorderColorRight("#757575")
        widget:setBorderColorBottom("#757575")
        widget:setBorderWidth(1)
        widget:setTooltip("Spell: " .. spellData.name .. "\nWords: " .. spellData.words)

        local slotID = tonumber(widget:getId():match("%d+"))
        if isHaste then
            helperConfig.haste[1].id = tonumber(spellData.id)
        elseif isCureParalyze then
            helperConfig.cureParalyze[1].id = tonumber(spellData.id)
        else
            helperConfig.training[1].id = tonumber(spellData.id)
            if helperConfig.training[1].percent == 0 then
                helperConfig.training[1].percent = 100
                updateTrainingPercent("spellTrainingButton0", helperConfig.training[1].percent)
            end
        end
    end
end

function onSearchTextChange(text)
    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return
    end

    local window = rootWidget:recursiveGetChildById("assignSpellWindow")
    if not window then
        return
    end

    local spellList = window:recursiveGetChildById("spellList")
    if not spellList then
        return
    end

    for _, child in pairs(spellList:getChildren()) do
        local name = child:getText():lower()
        if name:find(text:lower()) or text == "" or #text < 3 then
            child:setVisible(true)
        else
            child:setVisible(false)
        end
    end
end

function onClearSearchText()
    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return
    end

    local window = rootWidget:recursiveGetChildById("assignSpellWindow")
    if not window then
        return
    end

    local search = window:recursiveGetChildById("searchText")
    if not search then
        return
    end

    search:setText("")
end

