function canSio()
    local vocationId = translateVocation(g_game.getLocalPlayer():getVocation())

    if vocationId == VOCATION_KNIGHT or vocationId == VOCATION_PALADIN then
        return false
    end
    return true
end

function canGranSio()
    local vocationId = translateVocation(g_game.getLocalPlayer():getVocation())

    if vocationId == VOCATION_DRUID then
        return true
    end

    return false
end

function isInFriendList(playerName, isGran)
    local list = isGran and helperConfig.gransiohealing or helperConfig.friendhealing
    for i = 1, #list do
        if list[i].name == playerName then
            return true
        end
    end
    return false
end

function addToFriendList(playerName, isGran)
    local list = isGran and helperConfig.gransiohealing or helperConfig.friendhealing
    local count = 0

    -- Conta quantos já estão preenchidos
    for i = 1, #list do
        if list[i] and list[i].name ~= "" then
            count = count + 1
        end
    end

    if count >= MAX_FRIENDS then
        modules.game_textmessage.displayFailureMessage(
            string.format("You can only add up to %d players to the list.", MAX_FRIENDS)
        )
        return
    end

    -- Procura slot vazio
    local emptySlot = 0
    for i = 1, #list do
        if not list[i] or list[i].name == "" then
            emptySlot = i
            break
        end
    end

    if emptySlot == 0 then
        emptySlot = #list + 1
    end

    -- Garante que todos os índices até emptySlot existem
    for i = 1, emptySlot do
        if not list[i] then
            list[i] = { name = "", percent = 0, enabled = false }
        end
    end

    -- Finalmente preenche o slot vazio
    list[emptySlot].name = playerName
    list[emptySlot].percent = 0
    list[emptySlot].enabled = true

    onFriendMembersChange()
end

function removeFromFriendList(playerName, isGran)
    local slot = 0
    if isGran then
        for i = 1, #helperConfig.gransiohealing do
            if helperConfig.gransiohealing[i].name == playerName then
                slot = i
                break
            end
        end
    else
        for i = 1, #helperConfig.friendhealing do
            if helperConfig.friendhealing[i].name == playerName then
                slot = i
                break
            end
        end
    end

    if isGran then
        helperConfig.gransiohealing[slot] = { name = "", percent = 0, enabled = false }
    else
        helperConfig.friendhealing[slot] = { name = "", percent = 0, enabled = false }
    end
    onFriendMembersChange()
end

local function moveFriend(index, direction, isGran)
    local list = isGran and helperConfig.gransiohealing or helperConfig.friendhealing
    local newIndex = index + direction

    if newIndex < 1 or newIndex > #list then
        return
    end

    list[index], list[newIndex] = list[newIndex], list[index]
    onFriendMembersChange()
end

function onFriendMembersChange()
    local friendListWidget = healingPanel:recursiveGetChildById("friendList")
    friendListWidget:destroyChildren()

    for i = 1, math.min(#helperConfig.friendhealing, MAX_FRIENDS) do
        local member = helperConfig.friendhealing[i]
        if member.name:len() > 0 then
            local widget_1 = g_ui.createWidget("PlayerName", friendListWidget)
            widget_1:setText(string.format("[%d] %s", i, member.name))

            widget_1.slot = i
            widget_1.onMouseRelease = function(self, mousePos, mouseButton)
                if mouseButton == MouseRightButton then
                    local menu = g_ui.createWidget("HelperPopupMenu")
                    menu:setGameMenu(true)
                    menu:addOption(
                        tr("Remove"),
                        function()
                            modules.game_helper.removeFromFriendList(member.name)
                        end
                    )
                    menu:addOption(
                        tr("Move Up"),
                        function()
                            moveFriend(i, -1, false)
                        end
                    )
                    menu:addOption(
                        tr("Move Down"),
                        function()
                            moveFriend(i, 1, false)
                        end
                    )
                    menu:display(mousePos)
                end
            end
        end
    end
    local granListWidget = granSioPanel:recursiveGetChildById("friendList2")
    granListWidget:destroyChildren()

    for i = 1, math.min(#helperConfig.gransiohealing, MAX_FRIENDS) do
        local member = helperConfig.gransiohealing[i]
        if member.name:len() > 0 then
            local widget_1 = g_ui.createWidget("PlayerName", granListWidget)
            widget_1:setText(string.format("[%d] %s", i, member.name))

            widget_1.slot = i
            widget_1.onMouseRelease = function(self, mousePos, mouseButton)
                if mouseButton == MouseRightButton then
                    local menu = g_ui.createWidget("HelperPopupMenu")
                    menu:setGameMenu(true)
                    menu:addOption(
                        tr("Remove"),
                        function()
                            modules.game_helper.removeFromFriendList(member.name, true)
                        end
                    )
                    menu:addOption(
                        tr("Move Up"),
                        function()
                            moveFriend(i, -1, true)
                        end
                    )
                    menu:addOption(
                        tr("Move Down"),
                        function()
                            moveFriend(i, 1, true)
                        end
                    )
                    menu:display(mousePos)
                end
            end
        end
    end
end

function onFriendListTextChange(text, isGran)
    if not text then
        return
    end

    -- Split text by newlines
    local names = {}
    for line in text:gmatch("[^\r\n]+") do
        local trimmed = line:match("^%s*(.-)%s*$") -- trim whitespace
        if trimmed and trimmed:len() > 0 then
            table.insert(names, trimmed)
        end
    end

    -- Update config
    local list = isGran and helperConfig.gransiohealing or helperConfig.friendhealing

    -- Clear existing list
    for i = 1, #list do
        list[i] = { name = "", percent = 0, enabled = false }
    end

    -- Add new names
    for i, name in ipairs(names) do
        if i > MAX_FRIENDS then
            break
        end
        list[i] = { name = name, percent = 90, enabled = true }
    end
end

