function loadSioSpellButton(isGranSio)
    if not friendHealPanel then return end

    local buttonId = isGranSio and "granSioSpellButton" or "sioSpellButton"
    local labelId = isGranSio and "granSioSpellName" or "sioSpellName"
    local spellId = isGranSio and (helperConfig.gransiohealingSioSpellId or 242) or
    (helperConfig.friendhealingSioSpellId or 84)

    local button = friendHealPanel:recursiveGetChildById(buttonId)
    local label = friendHealPanel:recursiveGetChildById(labelId)
    if not button then return end

    local spell, spellProfile = Spells.getSpellByClientId(tonumber(spellId))
    spellProfile = spellProfile or "Default"
    if spell and SpelllistSettings[spellProfile] and SpellIcons[spell.icon] then
        local iconId = SpellIcons[spell.icon][1]
        local source = SpelllistSettings[spellProfile].iconsFolder
        local clip = Spells.getImageClipNormal(iconId, spellProfile)

        button:setImageSource(source)
        button:setImageClip(clip)
        button:setBorderColorTop("#1b1b1b")
        button:setBorderColorLeft("#1b1b1b")
        button:setBorderColorRight("#757575")
        button:setBorderColorBottom("#757575")
        button:setBorderWidth(1)
        button:setTooltip("Spell: " .. (spell.name or "") .. "\nWords: " .. (spell.words or ""))

        if label then
            label:setText(spell.words or "")
        end
    end
end

function modules.game_helper.assignSioSpell(button, isGranSio)
    if toggleAssignSpellWindow() then
        return true
    end

    local radio = UIRadioGroup.create()
    local window = g_ui.loadUI("styles/spell", g_ui.getRootWidget())
    if not window then
        return true
    end
    applyOpacityToWindow(window)

    window:show(true)
    window:raise()
    window:focus()
    safeSetInputLockWidget(window)
    helper:hide()

    window:setText(isGranSio and "Assign Gran Sio Spell" or "Assign Sio Spell")

    local playerVocation = player and translateVocation(player:getVocation()) or 0
    local currentSpellId = isGranSio and (helperConfig.gransiohealingSioSpellId or 242) or
    (helperConfig.friendhealingSioSpellId or 84)
    local preselectedWidget = nil

    for profileName, spells in pairs(SpellInfo) do
        if type(spells) ~= "table" then goto continue_sio_profile end
        for spellName, spellData in pairs(spells) do
            if type(spellData) ~= 'table' or not spellData.id then goto continue_sio_spell end

            -- Only show healing spells (group 2)
            local groupIds = Spells.getGroupIds(spellData)
            local isHealingSpell = table.contains(groupIds, 2)
            if not isHealingSpell then
                local category = string.lower(tostring(spellData.category or ""))
                isHealingSpell = category == "healing"
            end
            if not isHealingSpell then
                goto continue_sio_spell
            end

            -- Must be available for this vocation
            if not table.contains(spellData.vocations, playerVocation) then
                goto continue_sio_spell
            end

            local spellIconId = nil
            if SpellIcons and spellData.icon and SpellIcons[spellData.icon] then
                spellIconId = SpellIcons[spellData.icon][1]
            end
            if not spellIconId then goto continue_sio_spell end

            local widget = g_ui.createWidget("SpellPreview", window.contentPanel.spellList)
            if not widget then goto continue_sio_spell end

            local displayName = tostring(spellData.name or spellName or spellData.words)
            radio:addWidget(widget)
            widget:setId(spellData.id)
            widget:setText(displayName .. "\n" .. spellData.words)
            widget.source = SpelllistSettings[profileName] and SpelllistSettings[profileName].iconsFolder or
            SpelllistSettings["Default"].iconsFolder
            widget.clip = Spells.getImageClipNormal(spellIconId, profileName)
            widget.image:setImageSource(widget.source)
            widget.image:setImageClip(widget.clip)

            if spellData.level then
                widget.levelLabel:setVisible(true)
                widget.levelLabel:setText(string.format("Level: %d", tonumber(spellData.level) or 0))
            end

            if groupIds and #groupIds > 0 then
                local primaryGroup = groupIds[1]
                local offSet = 1
                if primaryGroup == 2 then
                    offSet = 23
                elseif primaryGroup == 3 then
                    offSet = 45
                end
                widget.imageGroup:setImageClip(offSet .. " 25 20 20")
                widget.imageGroup:setVisible(true)
            end

            if spellData.id == currentSpellId then
                preselectedWidget = widget
            end

            ::continue_sio_spell::
        end
        ::continue_sio_profile::
    end

    local widgets = window.contentPanel.spellList:getChildren()
    table.sort(widgets, function(a, b) return a:getText() < b:getText() end)
    for i, widget in ipairs(widgets) do
        window.contentPanel.spellList:moveChildToIndex(widget, i)
    end

    radio.onSelectionChange = function(widget, selected)
        if selected then
            window.contentPanel.preview:setText(selected:getText())
            window.contentPanel.preview.image:setImageSource(selected.source)
            window.contentPanel.preview.image:setImageClip(selected.clip)
            window.contentPanel.paramLabel:setOn(false)
            window.contentPanel.paramText:setEnabled(false)
            window.contentPanel.paramText:clearText()
            window.contentPanel.spellList:ensureChildVisible(widget)
        end
    end

    if preselectedWidget then
        radio:selectWidget(preselectedWidget)
    elseif widgets and #widgets > 0 then
        radio:selectWidget(widgets[1])
    end

    local applyButton = window:recursiveGetChildById("buttonApply")
    if applyButton then
        applyButton:setVisible(false)
    end

    local function confirmSelection()
        local selected = radio:getSelectedWidget()
        if not selected then return end

        local spellIcon = selected.source
        local spellClip = selected.clip
        local spellId = tonumber(selected:getId())
        local spellName = selected:getText():match("^(.-)\n")
        local spellWords = selected:getText():match("\n(.+)")

        if isGranSio then
            helperConfig.gransiohealingSioSpellId = spellId
        else
            helperConfig.friendhealingSioSpellId = spellId
        end

        button:setImageSource(spellIcon)
        button:setImageClip(spellClip)
        button:setBorderColorTop("#1b1b1b")
        button:setBorderColorLeft("#1b1b1b")
        button:setBorderColorRight("#757575")
        button:setBorderColorBottom("#757575")
        button:setBorderWidth(1)
        button:setTooltip("Spell: " .. (spellName or "") .. "\nWords: " .. (spellWords or ""))

        -- Update spell name label
        local nameLabel = isGranSio and friendHealPanel:recursiveGetChildById("granSioSpellName") or
        friendHealPanel:recursiveGetChildById("sioSpellName")
        if nameLabel then
            nameLabel:setText(spellWords or spellName or "")
        end

        saveSettings()
        safeSetInputLockWidget(nil)
        helper:show(true)
        window:destroy()
    end

    local function cancelSelection()
        safeSetInputLockWidget(nil)
        helper:show(true)
        window:destroy()
    end

    window.contentPanel.buttonOk.onClick = confirmSelection
    window.contentPanel.buttonClose.onClick = cancelSelection
    window.contentPanel.onEnter = confirmSelection
    window.onEscape = cancelSelection
end

