function onVocationPercentChange(vocationId, percent, isGran)
    if not helperConfig then
        return
    end

    -- Initialize if needed
    if not helperConfig.friendhealingVocationPercent then
        helperConfig.friendhealingVocationPercent = {
            ["4"] = 90,
            ["8"] = 90,             -- Knight + Elite Knight
            ["3"] = 90,
            ["7"] = 90,             -- Paladin + Royal Paladin
            ["1"] = 90,
            ["5"] = 90,             -- Sorcerer + Master Sorcerer
            ["2"] = 90,
            ["6"] = 90,             -- Druid + Elder Druid
            ["9"] = 90,
            ["10"] = 90             -- Monk + Exalted Monk
        }
    end
    if not helperConfig.gransiohealingVocationPercent then
        helperConfig.gransiohealingVocationPercent = {
            ["4"] = 90,
            ["8"] = 90,             -- Knight + Elite Knight
            ["3"] = 90,
            ["7"] = 90,             -- Paladin + Royal Paladin
            ["1"] = 90,
            ["5"] = 90,             -- Sorcerer + Master Sorcerer
            ["2"] = 90,
            ["6"] = 90,             -- Druid + Elder Druid
            ["9"] = 90,
            ["10"] = 90             -- Exalted Monk
        }
    end

    local vocationPercents = isGran and helperConfig.gransiohealingVocationPercent or
    helperConfig.friendhealingVocationPercent
    local percentValue = tonumber(percent) or 90

    -- Map promoted vocation ID to base vocation ID and vice versa
    local vocationPairs = {
        [8] = 4,  -- Elite Knight -> Knight
        [4] = 8,  -- Knight -> Elite Knight
        [7] = 3,  -- Royal Paladin -> Paladin
        [3] = 7,  -- Paladin -> Royal Paladin
        [5] = 1,  -- Master Sorcerer -> Sorcerer
        [1] = 5,  -- Sorcerer -> Master Sorcerer
        [6] = 2,  -- Elder Druid -> Druid
        [2] = 6,  -- Druid -> Elder Druid
        [9] = 10, -- Monk -> Exalted Monk
        [10] = 9  -- Exalted Monk -> Monk
    }

    -- Set the percentage for the given vocation (convert to string key)
    vocationPercents[tostring(vocationId)] = percentValue

    -- Also set the percentage for the paired vocation (base/promoted)
    local pairedVocationId = vocationPairs[vocationId]
    if pairedVocationId then
        vocationPercents[tostring(pairedVocationId)] = percentValue
    end

    -- Save the settings to persist the change
    saveSettings()
end

