-- Utility Settings Window
local utilitySettingsWindow = nil
local currentUtilitySpell = nil

-- "Rodeado" = todos os 8 tiles adjacentes (±1 em x e y) têm criatura
function isSurroundedByCreatures(position)
    if not position then
        local player = g_game.getLocalPlayer()
        if not player then return false end
        position = player:getPosition()
    end
    local occupied = {}
    for _, entry in ipairs(CreatureCache.getMonsters()) do
        if entry.dx <= 1 and entry.dy <= 1 and (entry.dx > 0 or entry.dy > 0) and entry.position then
            local sdx = entry.position.x - position.x
            local sdy = entry.position.y - position.y
            occupied[sdx .. "," .. sdy] = true
        end
    end
    for sdx = -1, 1 do
        for sdy = -1, 1 do
            if not (sdx == 0 and sdy == 0) and not occupied[sdx .. "," .. sdy] then
                return false
            end
        end
    end
    return true
end

-- Função auxiliar para verificar se as condições de utilitário são atendidas
-- TODAS as condições devem ser atendidas para retornar true:
-- Para utevogravsan: apenas min/max creatures
-- Para outros: min/max mobs, min/max health, min/max mana e box rule
function checkUtilityConditions(spellId, position)
    local settings = helperConfig.utilitySettings[spellId]
    if not settings then
        return true -- Se não há configurações, permite a execução
    end

    -- OPTIMIZATION: Use CreatureCache instead of getSpectators (monsters already filtered: alive, non-summon)
    local mobCount = 0
    for _, entry in ipairs(CreatureCache.getMonsters()) do
        if entry.dx <= 7 and entry.dy <= 5 then
            mobCount = mobCount + 1
        end
    end

    -- Para utevogravsan, verificar minCreatures/maxCreatures + boxRule + idleSeconds
    if spellId == "utevogravsan" then
        local minCreatures = settings.minCreatures or 1
        local maxCreatures = settings.maxCreatures or 99
        if mobCount < minCreatures or mobCount > maxCreatures then
            return false -- Não atende a condição de creatures
        end
        local boxRule = settings.boxRule or "any"
        if boxRule ~= "any" then
            local surrounded = isSurroundedByCreatures(position)
            if boxRule == "in_box" and not surrounded then
                return false
            end
            if boxRule == "out_box" and surrounded then
                return false
            end
        end
        local idleSeconds = tonumber(settings.idleSeconds) or 0
        if idleSeconds > 0 then
            if lastPlayerMoveTimeMs <= 0 then
                return false
            end
            local idleMs = g_clock.millis() - lastPlayerMoveTimeMs
            if idleMs < idleSeconds * 1000 then
                return false
            end
        end
        return true
    end

    -- CONDIÇÃO 1: Verificar se o número de mobs está dentro do range configurado
    if mobCount < settings.minMobs or mobCount > settings.maxMobs then
        return false -- Não atende a condição de mobs
    end

    -- CONDIÇÃO BOX: Verificar regra de "rodeado" (in_box / out_box / any)
    local boxRule = settings.boxRule or "any"
    if boxRule ~= "any" then
        local surrounded = isSurroundedByCreatures(position)
        if boxRule == "in_box" and not surrounded then
            return false
        end
        if boxRule == "out_box" and surrounded then
            return false
        end
    end

    -- CONDIÇÃO 2: Verificar health percent do jogador
    local player = g_game.getLocalPlayer()
    if player then
        local healthPercent = (player:getHealth() / player:getMaxHealth()) * 100
        if healthPercent < settings.minHealth or healthPercent > settings.maxHealth then
            return false -- Não atende a condição de HP%
        end

        -- CONDIÇÃO 3: Verificar mana percent
        local maxMana = player:getMaxMana()
        if maxMana and maxMana > 0 then
            local minManaP = settings.minMana or 0
            local maxManaP = settings.maxMana or 100
            local manaPercent = (player:getMana() / maxMana) * 100
            if manaPercent < minManaP or manaPercent > maxManaP then
                return false
            end
        end
    end

    return true
end

function openUtilitySettings(spellId)
    if utilitySettingsWindow then
        utilitySettingsWindow:destroy()
    end

    -- Inicializar utilitySettings se não existir
    if not helperConfig.utilitySettings then
        helperConfig.utilitySettings = {
            utitotempo = { minMobs = 1, maxMobs = 99, minHealth = 0, maxHealth = 100, minMana = 0, maxMana = 100, boxRule = "out_box" },
            utamotempo = { minMobs = 0, maxMobs = 99, minHealth = 0, maxHealth = 100, minMana = 0, maxMana = 100, boxRule = "in_box" },
            utitotemposan = { minMobs = 1, maxMobs = 99, minHealth = 0, maxHealth = 100, minMana = 0, maxMana = 100, boxRule = "out_box" },
            utevogravsan = { minCreatures = 1, maxCreatures = 99, boxRule = "any" }
        }
    end
    -- Backfill de boxRule em profiles antigos
    local boxDefaults = { utitotempo = "out_box", utamotempo = "in_box", utitotemposan = "out_box", utevogravsan = "any" }
    for sid, def in pairs(boxDefaults) do
        if helperConfig.utilitySettings[sid] and helperConfig.utilitySettings[sid].boxRule == nil then
            helperConfig.utilitySettings[sid].boxRule = def
        end
    end

    currentUtilitySpell = spellId

    local rootWidget = g_ui.getRootWidget()
    utilitySettingsWindow = g_ui.createWidget('UtilitySettingsWindow', rootWidget)
    applyOpacityToWindow(utilitySettingsWindow)

    -- Mapear spellId para nome da magia
    local spellNames = {
        utitotempo = "Utito Tempo",
        utamotempo = "Utamo Tempo",
        utitotemposan = "Utito Tempo San",
    }

    -- Atualizar título da janela com o nome da magia
    local spellName = spellNames[spellId] or "Unknown Spell"
    utilitySettingsWindow:setText(spellName .. " - Settings")

    utilitySettingsWindow.onDestroy = function()
        utilitySettingsWindow = nil
        currentUtilitySpell = nil
    end

    -- Popular combo de Box rule
    local boxCombo = utilitySettingsWindow:recursiveGetChildById("boxRule")
    if boxCombo then
        if boxCombo.clearOptions then
            boxCombo:clearOptions()
        end
        boxCombo:addOption(tr("Any"), "any")
        boxCombo:addOption(tr("Only when in box"), "in_box")
        boxCombo:addOption(tr("Only when NOT in box"), "out_box")
    end

    -- Carregar configurações atuais
    local settings = helperConfig.utilitySettings[spellId]
    if settings then
        utilitySettingsWindow:recursiveGetChildById("minMobs"):setText(tostring(settings.minMobs))
        utilitySettingsWindow:recursiveGetChildById("maxMobs"):setText(tostring(settings.maxMobs))
        utilitySettingsWindow:recursiveGetChildById("minHealth"):setText(tostring(settings.minHealth))
        utilitySettingsWindow:recursiveGetChildById("maxHealth"):setText(tostring(settings.maxHealth))
        utilitySettingsWindow:recursiveGetChildById("minMana"):setText(tostring(settings.minMana or 0))
        utilitySettingsWindow:recursiveGetChildById("maxMana"):setText(tostring(settings.maxMana or 100))
        if boxCombo and boxCombo.setCurrentOptionByData then
            boxCombo:setCurrentOptionByData(settings.boxRule or "any", true)
        end
    end
    modalEnter(utilitySettingsWindow)
end

function saveUtilitySettings()
    if not utilitySettingsWindow or not currentUtilitySpell then
        return
    end

    local minMobs = tonumber(utilitySettingsWindow:recursiveGetChildById("minMobs"):getText()) or 0
    local maxMobs = tonumber(utilitySettingsWindow:recursiveGetChildById("maxMobs"):getText()) or 99
    local minHealth = tonumber(utilitySettingsWindow:recursiveGetChildById("minHealth"):getText()) or 0
    local maxHealth = tonumber(utilitySettingsWindow:recursiveGetChildById("maxHealth"):getText()) or 100
    local minMana = tonumber(utilitySettingsWindow:recursiveGetChildById("minMana"):getText()) or 0
    local maxMana = tonumber(utilitySettingsWindow:recursiveGetChildById("maxMana"):getText()) or 100

    -- Validar valores
    minMobs = math.max(0, math.min(99, minMobs))
    maxMobs = math.max(0, math.min(99, maxMobs))
    minHealth = math.max(0, math.min(100, minHealth))
    maxHealth = math.max(0, math.min(100, maxHealth))
    minMana = math.max(0, math.min(100, minMana))
    maxMana = math.max(0, math.min(100, maxMana))

    -- Salvar configurações
    if not helperConfig.utilitySettings[currentUtilitySpell] then
        helperConfig.utilitySettings[currentUtilitySpell] = {}
    end

    helperConfig.utilitySettings[currentUtilitySpell].minMobs = minMobs
    helperConfig.utilitySettings[currentUtilitySpell].maxMobs = maxMobs
    helperConfig.utilitySettings[currentUtilitySpell].minHealth = minHealth
    helperConfig.utilitySettings[currentUtilitySpell].maxHealth = maxHealth
    helperConfig.utilitySettings[currentUtilitySpell].minMana = minMana
    helperConfig.utilitySettings[currentUtilitySpell].maxMana = maxMana

    local boxCombo = utilitySettingsWindow:recursiveGetChildById("boxRule")
    if boxCombo and boxCombo.getCurrentOption then
        local opt = boxCombo:getCurrentOption()
        local data = opt and (opt.data or opt.text)
        if data ~= "any" and data ~= "in_box" and data ~= "out_box" then
            data = "any"
        end
        helperConfig.utilitySettings[currentUtilitySpell].boxRule = data
    end

    modules.game_textmessage.displayGameMessage(htr("Utility settings saved!"))
    utilitySettingsWindow:destroy()
    utilitySettingsWindow = nil
    currentUtilitySpell = nil
    saveSettings()
end

