            utamotempo = { minMobs = 0, maxMobs = 99, minHealth = 0, maxHealth = 100, minMana = 0, maxMana = 100 },
            utitotemposan = { minMobs = 1, maxMobs = 99, minHealth = 0, maxHealth = 100, minMana = 0, maxMana = 100 },
            utevogravsan = { minCreatures = 1, maxCreatures = 99, boxRule = "any" }
        }
