local function clampPercentValue(value, fallback)
    local number = tonumber(value)
    if not number then
        return fallback or 0
    end
    if number < 0 then
        return 0
    end
    if number > 100 then
        return 100
    end
    return number
end

local function ensureEnergyRingConfig()
    helperConfig.energyRing = helperConfig.energyRing or {}
    local config = helperConfig.energyRing
    config.healthToEquip = clampPercentValue(config.healthToEquip, 80)
    config.healthToDeequip = clampPercentValue(config.healthToDeequip, 90)
    config.minManaToEquip = clampPercentValue(config.minManaToEquip, 50)
    config.manaToEquip = clampPercentValue(config.manaToEquip, 30)
    if config.manaToEquip >= config.minManaToEquip then
        config.manaToEquip = math.max(0, config.minManaToEquip - 1)
    end
    helperConfig.energyRingEnabled = helperConfig.energyRingEnabled or false
end

function refreshEnergyRingUI()
    if not healingPanel then
        return
    end

    local energyRingPanel = healingPanel:recursiveGetChildById("energyRingPanel")
    if not energyRingPanel then
        return
    end

    ensureEnergyRingConfig()
    local config = helperConfig.energyRing

    local enableCheck = energyRingPanel:recursiveGetChildById("enableEnergyRing")
    if enableCheck then
        local desired = helperConfig.energyRingEnabled == true
        if enableCheck:isChecked() ~= desired then
            local oldCallback = enableCheck.onCheckChange
            enableCheck.onCheckChange = nil
            enableCheck:setChecked(desired)
            enableCheck.onCheckChange = oldCallback
        end
    end

    local function setFieldText(fieldId, value)
        local field = energyRingPanel:recursiveGetChildById(fieldId)
        if field then
            field:setText(tostring(value))
        end
    end

    setFieldText("energyRingHealthEquip", config.healthToEquip)
    setFieldText("energyRingHealthDeequip", config.healthToDeequip)
    setFieldText("energyRingMinMana", config.minManaToEquip)
    setFieldText("energyRingMana", config.manaToEquip)
end

function isEnergyRingHelperActive()
    return helperConfig.energyRingEnabled == true
end

function toggleEnergyRing(widget, message)
    if not widget and healingPanel then
        local panel = healingPanel:recursiveGetChildById("energyRingPanel")
        if panel then
            widget = panel:recursiveGetChildById("enableEnergyRing")
            if widget then
                widget:setChecked(not widget:isChecked())
            end
        end
    end

    if widget then
        helperConfig.energyRingEnabled = widget:isChecked()
    end
end

function updateEnergyRingField(fieldId, newValue)
    ensureEnergyRingConfig()
    local config = helperConfig.energyRing
    local parsedValue = clampPercentValue(newValue, 0)

    if fieldId == "energyRingHealthEquip" then
        config.healthToEquip = parsedValue
    elseif fieldId == "energyRingHealthDeequip" then
        config.healthToDeequip = parsedValue
    elseif fieldId == "energyRingMinMana" then
        config.minManaToEquip = parsedValue
    elseif fieldId == "energyRingMana" then
        config.manaToEquip = parsedValue
    end

    if config.manaToEquip >= config.minManaToEquip then
        config.manaToEquip = math.max(0, config.minManaToEquip - 1)
    end

    refreshEnergyRingUI()
end

