function updateUtamoPercent(buttonId, newPercent)
    local buttonIndex = string.match(buttonId, "%d+")
    buttonIndex = tonumber(buttonIndex)

    local config = helperConfig.utamo[buttonIndex + 1]
    local step = getPercentStep()
    local minValue = 1
    local maxValue = 100

    if string.find(buttonId, "add") then
        local newValue = math.min(config.percent + step, maxValue)
        if newValue == config.percent then
            healingPanel.shieldHelperPanel:recursiveGetChildById("addPercentUButton" .. buttonIndex):setEnabled(false)
            return
        end

        healingPanel.shieldHelperPanel:recursiveGetChildById("rmvPercentUButton" .. buttonIndex):setEnabled(true)
        config.percent = newValue
        local label = healingPanel.shieldHelperPanel:recursiveGetChildById("utamoPercentLabel" .. buttonIndex)
        label:setText(config.percent .. "%")

        if config.percent >= maxValue then
            healingPanel.shieldHelperPanel:recursiveGetChildById("addPercentUButton" .. buttonIndex):setEnabled(false)
        end
    elseif string.find(buttonId, "rmv") then
        local newValue = math.max(config.percent - step, minValue)
        if newValue == config.percent then
            healingPanel.shieldHelperPanel:recursiveGetChildById("rmvPercentUButton" .. buttonIndex):setEnabled(false)
            return
        end

        healingPanel.shieldHelperPanel:recursiveGetChildById("addPercentUButton" .. buttonIndex):setEnabled(true)
        config.percent = newValue
        local label = healingPanel.shieldHelperPanel:recursiveGetChildById("utamoPercentLabel" .. buttonIndex)
        label:setText(config.percent .. "%")

        if config.percent <= minValue then
            healingPanel.shieldHelperPanel:recursiveGetChildById("rmvPercentUButton" .. buttonIndex):setEnabled(false)
        end
    end
end

