-- Função para atualizar ícones de informação dos slots
function updateSpellInfoIcon(spellButton, spellName, spellWords)
    if not spellButton then return end

    local buttonId = spellButton:getId()
    local slotNumber = buttonId:match("spellButton(%d+)")
    if not slotNumber then return end

    local infoButton = helper:recursiveGetChildById("spellInfoButton" .. slotNumber)
    if infoButton then
        if spellName and spellName ~= "" then
            infoButton:setVisible(true)
            local tooltip = "Spell: " .. spellName
            if spellWords and spellWords ~= "" then
                tooltip = tooltip .. "\nWords: " .. spellWords
            end
            infoButton:setTooltip(tooltip)
        else
            infoButton:setVisible(false)
        end
    end
end

do
    local _oldHelperCycleEvent = helperCycleEvent
    function helperCycleEvent(...)
        if helperEvents then
            helperEvents.__lastTick = g_clock.millis()
        end
        return _oldHelperCycleEvent(...)
    end
end

-- Cavebot System
-- Cavebot state consolidated into a single table local to stay under Lua's
-- 200 main-chunk local limit (was 8 separate top-level locals).
local cavebotState = {
    window = nil,
    waypoints = {},
    currentIndex = 1,
    recording = false,
    playing = false,
    paused = false,
    sessions = {},
    currentSession = "Default",
}

-- Cavebot functions
function modules.game_helper.toggleCavebot()
