function modules.game_helper.onEnableTimerModule(isChecked)
    ensureTimerConfig()
    helperConfig.timerEnabled = isChecked

    if isChecked then
        -- Ativar módulo: iniciar timers que estão habilitados individualmente
        if helperConfig.timers then
            for i, timerData in ipairs(helperConfig.timers) do
                if timerData.enabled then
                    startTimer(i)
                end
            end
        end
        startTimerRuleCooldownOverlayLoop()
    else
        -- Desativar módulo: parar todos os timers
        stopAllTimers()
        refreshAllTimerRuleCooldownOverlays()
    end

    -- Update icon stats window
    if IconStatsModule and IconStatsModule.updateTimerIcon then
        IconStatsModule.updateTimerIcon(isChecked)
    end

    -- Update the checkbox in the helper window (without triggering onCheckChange)
    if helper then
        local timerPanel = helper:recursiveGetChildById("timerPanel")
        if timerPanel then
            local timerContentPanel = timerPanel:recursiveGetChildById("timerContentPanel")
            if timerContentPanel then
                local enableCheckbox = timerContentPanel:recursiveGetChildById("enableTimerModule")
                if enableCheckbox and enableCheckbox:isChecked() ~= isChecked then
                    -- Temporarily remove the callback to prevent recursion
                    local oldCallback = enableCheckbox.onCheckChange
                    enableCheckbox.onCheckChange = nil
                    enableCheckbox:setChecked(isChecked)
                    enableCheckbox.onCheckChange = oldCallback
                end
            end
        end
    end

    if not isChecked then
        stopTimerRuleCooldownOverlayLoop()
    end
end

function modules.game_helper.onTimerEnableChange(timerId, isChecked)
    ensureTimerConfig()

    local timerIndex = tonumber(timerId)
    if not timerIndex and timerId then
        timerIndex = tonumber(tostring(timerId):match("timerEntry(%d+)"))
    end
    if not timerIndex or not helperConfig.timers or not helperConfig.timers[timerIndex] then
        return
    end

    helperConfig.timers[timerIndex].enabled = isChecked == true

    if isChecked then
        if helperConfig.timerEnabled then
            startTimer(timerIndex)
        end
    else
        stopTimer(timerIndex)
    end

    refreshAllTimerRuleCooldownOverlays()
    saveSettings()
end

function applyOpacityToWindow(window)
    if not window then return end
    if window.isDestroyed and window:isDestroyed() then return end
    window:setBackgroundColor('#00000000')
end

function modules.game_helper.onTimerActionTypeChange(timerId, actionType)
    ensureTimerConfig()

    local timerIndex = tonumber(timerId)
    if not timerIndex and timerId then
        timerIndex = tonumber(tostring(timerId):match("timerEntry(%d+)"))
    end
    if not timerIndex or not helperConfig.timers or not helperConfig.timers[timerIndex] then
        return
    end

    helperConfig.timers[timerIndex].actionType = normalizeTimerActionType(actionType)

    local timerEntry = timerPanel and timerPanel:recursiveGetChildById("timerEntry" .. timerIndex)
    if not timerEntry then
        return
    end

    local itemButton = timerEntry:recursiveGetChildById("timerItemButton" .. timerIndex)
    if not itemButton then
        itemButton = timerEntry:recursiveGetChildById("timerItemButton")
    end
    local chatWidget = timerEntry:recursiveGetChildById("timerChatText")

    if helperConfig.timers[timerIndex].actionType == "Item" then
        if itemButton then
            itemButton:setVisible(true)
        end
        if chatWidget then
            chatWidget:setVisible(false)
            chatWidget:setText("")
        end
        helperConfig.timers[timerIndex].chatText = ""
    else
        if itemButton then
            itemButton:setVisible(false)
            local itemWidget = itemButton:getChildById("timerItem")
            if itemWidget then
                itemWidget:setItemId(0)
                itemWidget:setItemCount(0)
            end
            itemButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
            itemButton:setTooltip("")
        end
        if chatWidget then
            chatWidget:setVisible(true)
        end
        helperConfig.timers[timerIndex].itemId = 0
        helperConfig.timers[timerIndex].itemCount = 0
    end

    saveSettings()
end

