function trimTimerText(text)
    local result = tostring(text or "")
    result = result:gsub("%s+", " ")
    result = result:gsub("^%s+", "")
    result = result:gsub("%s+$", "")
    return result
end

function isTimerRuleComplete(ruleConfig)
    if type(ruleConfig) ~= "table" then
        return false
    end

    local normalized = ensureTimerRule(ruleConfig, 1)
    if normalized.actionType == "Item" then
        return (tonumber(normalized.itemId) or 0) > 0
    end

    return trimTimerText(normalized.chatText) ~= ""
end

function pruneIncompleteTimerRules()
    if type(helperConfig) ~= "table" then
        return false
    end

    local rules = helperConfig.timers or {}
    local changed = false
    for idx = #rules, 1, -1 do
        rules[idx] = ensureTimerRule(rules[idx], idx)
        if not isTimerRuleComplete(rules[idx]) then
            table.remove(rules, idx)
            changed = true
        end
    end

    helperConfig.timers = rules
    return changed
end

function formatTimerIntervalSummary(intervalSeconds)
    local seconds = tonumber(intervalSeconds) or 60
    if seconds < 1 then
        seconds = 1
    end

    if seconds < 60 then
        return tostring(seconds) .. "s"
    end

    local minutes = math.floor(seconds / 60)
    local remainder = seconds % 60
    if remainder == 0 then
        return tostring(minutes) .. "m"
    end

    return tostring(minutes) .. "m " .. tostring(remainder) .. "s"
end

function buildTimerRuleSummary(ruleConfig)
    local rule = ensureTimerRule(ruleConfig, 1)
    local parts = {}

    if rule.actionType == "Item" then
        local itemId = tonumber(rule.itemId) or 0
        if itemId > 0 then
            table.insert(parts, resolveTimerItemName(itemId))
        else
            table.insert(parts, "Item")
        end
    else
        local text = trimTimerText(rule.chatText)
        if text == "" then
            text = "(empty text)"
        end
        if #text > 40 then
            text = string.sub(text, 1, 37) .. "..."
        end
        table.insert(parts, "[W] " .. text)
    end

    local cooldownValue, cooldownUnit = timerIntervalToUnitValue(rule.interval, rule.cooldownUnit)
    table.insert(parts, "every " .. tostring(cooldownValue) .. " " .. cooldownUnit)

    local runInPz = rule.runInPz == true
    local runOutPz = rule.runOutPz == true
    if runInPz and runOutPz then
        table.insert(parts, "PZ + OUT PZ")
    elseif runInPz then
        table.insert(parts, "PZ")
    elseif runOutPz then
        table.insert(parts, "OUT PZ")
    else
        table.insert(parts, "No zone")
    end

    return table.concat(parts, " | ")
end

function resolveTimerItemName(itemId)
    local parsedItemId = tonumber(itemId) or 0
    if parsedItemId <= 0 then
        return ""
    end

    return resolveHelperItemNameById(parsedItemId)
end

function buildTimerRuleRowData(ruleConfig)
    local rule = ensureTimerRule(ruleConfig, 1)
    local itemWordsText = ""
    if rule.actionType == "Item" then
        local itemName = resolveTimerItemName(rule.itemId)
        if itemName == "" then
            itemName = "ITEM"
        end
        itemWordsText = itemName
    else
        local words = trimTimerText(rule.chatText)
        if words == "" then
            words = "TEXTO"
        end
        itemWordsText = words
    end
    if #itemWordsText > 40 then
        itemWordsText = string.sub(itemWordsText, 1, 37) .. "..."
    end

    local actionText = rule.actionType == "Texto" and "Say" or "Use"
    local cooldownValue, cooldownUnit = timerIntervalToUnitValue(rule.interval, rule.cooldownUnit)
    local cooldownText = tostring(cooldownValue) .. " " .. cooldownUnit
    return itemWordsText, actionText, cooldownText
end

function setTimerRuleItemVisual(itemButton, itemCountLabel, ruleConfig)
    if not itemButton then
        return
    end

    local rule = ensureTimerRule(ruleConfig, 1)
    local itemId = tonumber(rule.itemId) or 0
    local itemCount = tonumber(rule.itemCount) or 0
    local itemWidget = itemButton:getChildById("timerRuleItem")
    local itemCell = itemButton:getParent()
    local textCooldownBox = itemCell and itemCell:getChildById("textCooldownBox") or nil

    if textCooldownBox then
        textCooldownBox:setVisible(rule.actionType == "Texto")
    end

    if rule.actionType == "Item" then
        if itemId > 0 then
            itemButton:setImageSource("/images/ui/item")
            if not itemWidget then
                itemWidget = g_ui.createWidget("PotionItem", itemButton)
                if itemWidget then
                    itemWidget:setId("timerRuleItem")
                end
            end
            if itemWidget then
                itemWidget:setItemCount(0)
                itemWidget:setItemId(itemId)
                if itemCount > 1 then
                    itemWidget:setItemCount(itemCount)
                end
            end

            local itemName = resolveTimerItemName(itemId)
            itemButton:setTooltip(itemName)
        else
            if itemWidget then
                itemWidget:destroy()
            end
            itemButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
            itemButton:setTooltip("")
        end
    else
        if itemWidget then
            itemWidget:destroy()
        end
        itemButton:setImageSource("")
        local text = trimTimerText(rule.chatText)
        itemButton:setTooltip(text)
    end

    if itemCountLabel then
        itemCountLabel:setVisible(false)
    end
end

function updateTimerRuleRowLayout(timerEntry, ruleConfig)
    if not timerEntry or timerEntry:isDestroyed() then
        return
    end

    local rule = ensureTimerRule(ruleConfig, 1)
    local itemCell = timerEntry:recursiveGetChildById("itemCell")
    local itemWordsLabel = timerEntry:recursiveGetChildById("itemWordsLabel")

    if itemCell then
        itemCell:setVisible(true)
    end

    if itemWordsLabel then
        itemWordsLabel:removeAnchor(AnchorLeft)
        if itemCell then
            itemWordsLabel:addAnchor(AnchorLeft, itemCell:getId(), AnchorRight)
            itemWordsLabel:setMarginLeft(8)
        else
            itemWordsLabel:addAnchor(AnchorLeft, "parent", AnchorLeft)
            itemWordsLabel:setMarginLeft(4)
        end
    end
end

function ensureTimerRuleCooldownOverlay(timerEntry, ruleConfig)
    if not timerEntry or timerEntry:isDestroyed() then
        return nil
    end

    local overlayHost = timerEntry:recursiveGetChildById("itemButton")
    if not overlayHost then
        return nil
    end

    local overlay = overlayHost:getChildById("timerCooldownOverlay")
    if not overlay then
        overlay = g_ui.createWidget("UIProgressRect", overlayHost)
        if not overlay then
            return nil
        end
        overlay:setId("timerCooldownOverlay")
        overlay:fill("parent")
        overlay:setBackgroundColor("#ffffff10")
        overlay:setFont("verdana-11px-rounded")
        overlay:setPhantom(true)
        overlay:setFocusable(false)
        overlay:setText("")
    end

    return overlay
end

function hideTimerRuleCooldownOverlay(timerEntry)
    if not timerEntry or timerEntry:isDestroyed() then
        return
    end

    local itemButton = timerEntry:recursiveGetChildById("itemButton")
    if itemButton then
        local itemOverlay = itemButton:getChildById("timerCooldownOverlay")
        if itemOverlay then
            itemOverlay:hide()
            itemOverlay:setPercent(100)
            itemOverlay:setText("")
        end
    end
end

function updateTimerRuleCooldownOverlay(timerEntry, timerIndex, nowMs)
    if not timerEntry or timerEntry:isDestroyed() then
        return
    end
    if not helperConfig or not helperConfig.timers or not helperConfig.timers[timerIndex] then
        hideTimerRuleCooldownOverlay(timerEntry)
        return
    end

    local rule = ensureTimerRule(helperConfig.timers[timerIndex], timerIndex)

    local intervalSeconds = tonumber(rule.interval) or 0
    local intervalMs = intervalSeconds * 1000
    local isWaiting = helperConfig.timerEnabled == true and rule.enabled == true and timerEvents[timerIndex] ~= nil and
    intervalMs > 0
    if not isWaiting then
        hideTimerRuleCooldownOverlay(timerEntry)
        return
    end

    local overlay = ensureTimerRuleCooldownOverlay(timerEntry, rule)
    if not overlay then
        return
    end

    local now = tonumber(nowMs) or g_clock.millis()
    local lastExecution = tonumber(rule.lastExecution) or 0
    if lastExecution <= 0 then
        lastExecution = now
        rule.lastExecution = lastExecution
    end

    local elapsed = now - lastExecution
    if elapsed < 0 then
        elapsed = 0
    end

    local percent = (elapsed * 100) / intervalMs
    if percent < 0 then
        percent = 0
    elseif percent > 100 then
        percent = 100
    end

    overlay:setPercent(percent)
    overlay:setText("")
    overlay:show()
end

function refreshAllTimerRuleCooldownOverlays()
    if not timerPanel or timerPanel:isDestroyed() then
        return
    end

    local timerContentPanel = timerPanel:recursiveGetChildById("timerContentPanel")
    if not timerContentPanel then
        return
    end

    local timerList = timerContentPanel:recursiveGetChildById("timerList")
    if not timerList then
        return
    end

    local now = g_clock.millis()
    local rules = helperConfig and helperConfig.timers or {}
    for i = 1, #rules do
        local row = timerList:recursiveGetChildById("timerRuleRow" .. i)
        if row then
            updateTimerRuleCooldownOverlay(row, i, now)
        end
    end
end

function stopTimerRuleCooldownOverlayLoop()
    if helperEvents and helperEvents.timerCooldownUiEvent then
        removeEvent(helperEvents.timerCooldownUiEvent)
        helperEvents.timerCooldownUiEvent = nil
    end
end

function startTimerRuleCooldownOverlayLoop()
    stopTimerRuleCooldownOverlayLoop()

    local function tick()
        helperEvents.timerCooldownUiEvent = nil
        if not timerPanel or timerPanel:isDestroyed() then
            return
        end
        local ok, err = pcall(refreshAllTimerRuleCooldownOverlays)
        if not ok then
            g_logger.warning("[Helper] refreshAllTimerRuleCooldownOverlays error: " .. tostring(err))
        end
        helperEvents.timerCooldownUiEvent = scheduleEvent(tick, 100)
    end

    tick()
end

function stopSpellRuleCooldownOverlayLoop()
    if helperEvents and helperEvents.spellRuleCooldownUiEvent then
        removeEvent(helperEvents.spellRuleCooldownUiEvent)
        helperEvents.spellRuleCooldownUiEvent = nil
    end
end

function startSpellRuleCooldownOverlayLoop()
    if not helperEvents then
        return
    end
    if helperEvents.spellRuleCooldownUiEvent then
        return
    end

    local function tick()
        helperEvents.spellRuleCooldownUiEvent = nil
        if not helper or (helper.isDestroyed and helper:isDestroyed()) then
            return
        end

        local ok, err = pcall(refreshAllHealingRuleCooldownOverlays)
        if not ok then
            g_logger.warning("[Helper] refreshAllHealingRuleCooldownOverlays error: " .. tostring(err))
        end
        local ok2, err2 = pcall(refreshAllShooterRuleCooldownOverlays)
        if not ok2 then
            g_logger.warning("[Helper] refreshAllShooterRuleCooldownOverlays error: " .. tostring(err2))
        end
        helperEvents.spellRuleCooldownUiEvent = scheduleEvent(tick, 100)
    end

    tick()
end

function clearTimerRuleSelection()
    if not helperEvents then
        return
    end
    local previous = helperEvents.selectedTimerRuleRow
    if previous and not previous:isDestroyed() then
        previous._isSelected = false
        previous:setBackgroundColor(previous._baseBackgroundColor or "#0a0a0a")
    end
    helperEvents.selectedTimerRuleRow = nil
end

function selectTimerRuleRow(row)
    if not row or row:isDestroyed() then
        return
    end

    if helperEvents then
        local previous = helperEvents.selectedTimerRuleRow
        if previous and not previous:isDestroyed() and previous ~= row then
            previous._isSelected = false
            previous:setBackgroundColor(previous._baseBackgroundColor or "#0a0a0a")
        end
        helperEvents.selectedTimerRuleRow = row
    end

    row._isSelected = true
    row:setBackgroundColor("#ffffff18")
end

function refreshTimerRuleRowColors()
    if not timerPanel or timerPanel:isDestroyed() then
        return
    end

    local timerContentPanel = timerPanel:recursiveGetChildById("timerContentPanel")
    if not timerContentPanel then
        return
    end
    local timerList = timerContentPanel:recursiveGetChildById("timerList")
    if not timerList then
        return
    end

    local rowOrder = 0
    local children = timerList:getChildren() or {}
    for _, child in ipairs(children) do
        local childId = child and child:getId() or ""
        if type(childId) == "string" and childId:find("timerRuleRow", 1, true) then
            rowOrder = rowOrder + 1
            applyRuleRowBaseColor(child, rowOrder)
        end
    end

    if helperEvents then
        local selected = helperEvents.selectedTimerRuleRow
        if selected and not selected:isDestroyed() and selected:getParent() == timerList then
            selected._isSelected = true
            selected:setBackgroundColor("#ffffff18")
        else
            helperEvents.selectedTimerRuleRow = nil
        end
    end
end

function createTimerRuleRow(zeroIndex, ruleConfig, parentRulesList)
    local rulesList = parentRulesList
    if not rulesList then
        local timerContentPanel = timerPanel and timerPanel:recursiveGetChildById("timerContentPanel")
        rulesList = timerContentPanel and timerContentPanel:recursiveGetChildById("timerList")
    end
    if not rulesList then
        return nil
    end

    local row = g_ui.createWidget("TimerRuleRow", rulesList)
    if not row then
        return nil
    end

    row:setId("timerRuleRow" .. tostring((tonumber(zeroIndex) or 0) + 1))
    local rulesListWidth = rulesList:getWidth() or 0
    if rulesListWidth > 0 then
        row:setWidth(math.max(1, rulesListWidth - 2))
    end
    row._isSelected = false

    local normalizedRule = ensureTimerRule(ruleConfig, (tonumber(zeroIndex) or 0) + 1)
    local idLabel = row:recursiveGetChildById("idLabel")
    local itemButton = row:recursiveGetChildById("itemButton")
    local itemCountLabel = row:recursiveGetChildById("itemCount")
    local itemWordsLabel = row:recursiveGetChildById("itemWordsLabel")
    local actionLabel = row:recursiveGetChildById("actionLabel")
    local cooldownLabel = row:recursiveGetChildById("cooldownLabel")

    row.ruleIdText = tostring((tonumber(zeroIndex) or 0) + 1)
    row.ruleSummaryText = buildTimerRuleSummary(normalizedRule)
    row.ruleItemWordsText, row.ruleActionText, row.ruleCooldownText = buildTimerRuleRowData(normalizedRule)
    row.ruleEnabledState = normalizedRule.enabled == true

    setTimerRuleItemVisual(itemButton, itemCountLabel, normalizedRule)
    updateTimerRuleRowLayout(row, normalizedRule)

    if idLabel then
        idLabel:setText(row.ruleIdText)
        idLabel:setTooltip("ID " .. row.ruleIdText)
    end
    if itemWordsLabel then
        itemWordsLabel:setText(row.ruleItemWordsText)
        itemWordsLabel:setTooltip(row.ruleSummaryText)
    end
    if actionLabel then
        actionLabel:setText(row.ruleActionText)
        actionLabel:setTooltip(row.ruleSummaryText)
    end
    if cooldownLabel then
        cooldownLabel:setText(row.ruleCooldownText)
        cooldownLabel:setTooltip(row.ruleSummaryText)
    end

    setRuleRowEnabledIcon(row, normalizedRule.enabled == true)

    updateTimerRuleCooldownOverlay(row, (tonumber(zeroIndex) or 0) + 1)
    attachTimerEntryRowInteractions(row, (tonumber(zeroIndex) or 0) + 1)
    return row
end

function attachTimerEntryRowInteractions(timerEntry, timerIndex)
    if not timerEntry then
        return
    end

    timerEntry._lastLeftClickMs = 0
    local zeroIndex = timerIndex - 1
    local function onRowMouseRelease(self, mousePos, mouseButton)
        local now = g_clock.millis()
        if shouldIgnoreDuplicatedRowMouseRelease(timerEntry, mouseButton, now) then
            return true
        end

        selectTimerRuleRow(timerEntry)
        if mouseButton == MouseRightButton then
            modules.game_helper.openTimerRuleContextMenu(zeroIndex, mousePos)
            return true
        end
        if mouseButton == MouseLeftButton then
            if timerEntry._lastLeftClickMs > 0 and (now - timerEntry._lastLeftClickMs) <= TIMER_ROW_DOUBLE_CLICK_MS then
                timerEntry._lastLeftClickMs = 0
                modules.game_helper.toggleTimerRuleEnabled(zeroIndex)
                return true
            end
            timerEntry._lastLeftClickMs = now
        end
        return false
    end

    timerEntry.onMouseRelease = onRowMouseRelease
    local itemWordsLabel = timerEntry:recursiveGetChildById("itemWordsLabel")
    local actionLabel = timerEntry:recursiveGetChildById("actionLabel")
    local cooldownLabel = timerEntry:recursiveGetChildById("cooldownLabel")
    local idLabel = timerEntry:recursiveGetChildById("idLabel")
    local statusIcon = timerEntry:recursiveGetChildById("statusIcon")
    local itemButton = timerEntry:recursiveGetChildById("itemButton")
    local settingsButton = timerEntry:recursiveGetChildById("settingsButton")
    local removeButton = timerEntry:recursiveGetChildById("removeButton")

    if idLabel then
        idLabel.onMouseRelease = onRowMouseRelease
    end
    if statusIcon then
        statusIcon.onMouseRelease = onRowMouseRelease
    end
    if itemWordsLabel then
        itemWordsLabel.onMouseRelease = onRowMouseRelease
    end
    if actionLabel then
        actionLabel.onMouseRelease = onRowMouseRelease
    end
    if cooldownLabel then
        cooldownLabel.onMouseRelease = onRowMouseRelease
    end
    if itemButton then
        itemButton.onMouseRelease = function(self, mousePos, mouseButton)
            if mouseButton == MouseRightButton then
                modules.game_helper.openTimerRuleContextMenu(zeroIndex, mousePos)
                return true
            end
            return onRowMouseRelease(self, mousePos, mouseButton)
        end
        itemButton.onClick = function()
            modules.game_helper.editTimerRule(zeroIndex)
        end
    end
    if settingsButton then
        settingsButton.onMouseRelease = function(self, mousePos, mouseButton)
            selectTimerRuleRow(timerEntry)
            if mouseButton == MouseRightButton then
                modules.game_helper.openTimerRuleContextMenu(zeroIndex, mousePos)
            end
            return true
        end
        settingsButton.onClick = function()
            modules.game_helper.editTimerRule(zeroIndex)
        end
    end
    if removeButton then
        removeButton.onMouseRelease = function(self, mousePos, mouseButton)
            selectTimerRuleRow(timerEntry)
            if mouseButton == MouseRightButton then
                modules.game_helper.openTimerRuleContextMenu(zeroIndex, mousePos)
            end
            return true
        end
        removeButton.onClick = function()
            confirmDeleteRule(tr("timer"), function()
                modules.game_helper.removeTimerRule(zeroIndex)
            end)
        end
    end
end

function modules.game_helper.toggleTimerRuleEnabled(zeroIndex, explicitState)
    ensureTimerConfig()

    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1
    if not helperConfig.timers or not helperConfig.timers[index] then
        return
    end

    local newState = explicitState
    if newState == nil then
        newState = not (helperConfig.timers[index].enabled == true)
    end
    modules.game_helper.onTimerEnableChange(index, newState == true)

    local timerEntry = timerPanel and timerPanel:recursiveGetChildById("timerRuleRow" .. index)
    if timerEntry then
        timerEntry.ruleEnabledState = newState == true
        setRuleRowEnabledIcon(timerEntry, newState == true)
        updateTimerEntryFieldStates(timerEntry)
    end
end

function modules.game_helper.moveTimerRule(zeroIndex, direction)
    ensureTimerConfig()

    local fromIndex = tonumber(zeroIndex)
    local offset = tonumber(direction)
    if not fromIndex or not offset or offset == 0 then
        return
    end
    fromIndex = fromIndex + 1

    local rules = helperConfig.timers or {}
    local toIndex = fromIndex + offset
    if fromIndex < 1 or fromIndex > #rules or toIndex < 1 or toIndex > #rules then
        return
    end

    stopAllTimers()
    local moved = table.remove(rules, fromIndex)
    table.insert(rules, toIndex, moved)
    helperConfig.timers = rules

    initializeTimers()
    saveSettings()
end

function modules.game_helper.removeTimerRule(zeroIndex)
    ensureTimerConfig()

    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1

    local rules = helperConfig.timers or {}
    if index < 1 or index > #rules then
        return
    end

    stopAllTimers()
    table.remove(rules, index)
    helperConfig.timers = rules

    initializeTimers()
    saveSettings()
end

function modules.game_helper.duplicateTimerRule(zeroIndex)
    ensureTimerConfig()

    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1

    local rules = helperConfig.timers or {}
    local sourceRule = rules[index]
    if type(sourceRule) ~= "table" then
        return
    end

    local clonedRule = ensureTimerRule(deepCopy(sourceRule), index + 1)
    clonedRule.lastExecution = 0

    stopAllTimers()
    table.insert(rules, index + 1, clonedRule)
    helperConfig.timers = rules
    initializeTimers()
    saveSettings()
end

function modules.game_helper.editTimerRule(zeroIndex)
    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    modules.game_helper.openTimerSettingsPopup(index, nil, false)
end

function modules.game_helper.openTimerRuleContextMenu(zeroIndex, mousePos)
    ensureTimerConfig()

    local index = tonumber(zeroIndex)
    if not index then
        return
    end
    index = index + 1

    local rules = helperConfig.timers or {}
    local rule = rules[index]
    if type(rule) ~= "table" then
        return
    end

    local menu = g_ui.createWidget("HelperPopupMenu")
    menu:setGameMenu(true)

    if index > 1 then
        menu:addOption(tr("Move Up"), function()
            modules.game_helper.moveTimerRule(index - 1, -1)
        end)
    end
    if index < #rules then
        menu:addOption(tr("Move Down"), function()
            modules.game_helper.moveTimerRule(index - 1, 1)
        end)
    end

    menu:addOption(tr("Edit"), function()
        modules.game_helper.editTimerRule(index - 1)
    end)
    menu:addOption(tr("Duplicate"), function()
        modules.game_helper.duplicateTimerRule(index - 1)
    end)
    menu:addOption(tr("Delete"), function()
        confirmDeleteRule(tr("timer"), function()
            modules.game_helper.removeTimerRule(index - 1)
        end)
    end)
    menu:addOption(rule.enabled and tr("Disable") or tr("Enable"), function()
        modules.game_helper.toggleTimerRuleEnabled(index - 1, not (rule.enabled == true))
    end)

    menu:display(mousePos or g_window.getMousePosition())
end

function modules.game_helper.addTimerRule(initialActionType, initialInterval)
    ensureTimerConfig()

    local nextIndex = #((helperConfig and helperConfig.timers) or {}) + 1
    local newRule = createDefaultTimerRule(nextIndex)
    newRule.enabled = true
    if initialActionType == "Texto" then
        newRule.actionType = "Texto"
    else
        newRule.actionType = "Item"
    end
    if initialInterval and tonumber(initialInterval) then
        local parsed = tonumber(initialInterval)
        if parsed >= 1 and parsed <= 360 then
            newRule.interval = parsed
        end
    end

    modules.game_helper.openTimerSettingsPopup(nil, newRule, true)
end

function modules.game_helper.openAddTimerRulePopup()
    modules.game_helper.addTimerRule("Item", 60)
end

function getTimerSettingsPopupWidget()
    if timerSettingsPopup and timerSettingsPopup:isDestroyed() then
        timerSettingsPopup = nil
    end
    if timerSettingsPopup then
        return timerSettingsPopup
    end

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return nil
    end

    local popup = rootWidget:recursiveGetChildById("timerSettingsPopup")
    if popup and not popup:isDestroyed() then
        timerSettingsPopup = popup
    end
    return timerSettingsPopup
end

function updateTimerSettingsPopupActionState()
    local popup = getTimerSettingsPopupWidget()
    if not popup then
        return
    end

    local actionTypeCombo = popup:recursiveGetChildById("actionTypeCombo")
    local currentAction = "Item"
    if actionTypeCombo then
        local currentOption = actionTypeCombo:getCurrentOption()
        if currentOption and currentOption.text then
            currentAction = tostring(currentOption.text)
        end
    end
    currentAction = normalizeTimerActionType(currentAction)

    local itemRow = popup:recursiveGetChildById("itemRow")
    local textRow = popup:recursiveGetChildById("textRow")
    if itemRow then
        itemRow:setVisible(currentAction == "Item")
    end
    if textRow then
        textRow:setVisible(currentAction == "Texto")
    end

    if type(popup._draftRule) ~= "table" then
        popup._draftRule = createDefaultTimerRule(1)
    end
    popup._draftRule.actionType = currentAction
end

function refreshTimerPopupItemButtonVisual()
    local popup = getTimerSettingsPopupWidget()
    if not popup then
        return
    end

    local itemButton = popup:recursiveGetChildById("itemPreviewButton")
    local itemNameLabel = popup:recursiveGetChildById("itemNameLabel")
    if not itemButton then
        return
    end

    local parsedItemId = tonumber(popup._itemId) or 0
    local parsedItemCount = tonumber(popup._itemCount) or 0
    local itemWidget = itemButton:getChildById("timerPopupItem")

    if parsedItemId > 0 then
        itemButton:setImageSource("/images/ui/item")
        if not itemWidget then
            itemWidget = g_ui.createWidget("PotionItem", itemButton)
            if itemWidget then
                itemWidget:setId("timerPopupItem")
            end
        end

        if itemWidget then
            itemWidget:setItemCount(0)
            itemWidget:setItemId(parsedItemId)
            if parsedItemCount > 1 then
                itemWidget:setItemCount(parsedItemCount)
            end
        end

        local itemName = resolveHelperItemNameById(parsedItemId)
        local itemDisplayText = formatHelperItemIdAndName(parsedItemId, itemName)
        itemButton:setTooltip(itemDisplayText)
        if itemNameLabel then
            itemNameLabel:setText(itemDisplayText)
        end
    else
        if itemWidget then
            itemWidget:destroy()
        end
        itemButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
        itemButton:setTooltip("")
        if itemNameLabel then
            itemNameLabel:setText("")
        end
    end
end

function modules.game_helper.setTimerPopupItemId(itemId, itemCount)
    local popup = getTimerSettingsPopupWidget()
    if not popup then
        return
    end

    local parsedItemId = tonumber(itemId) or 0
    if parsedItemId < 0 then
        parsedItemId = 0
    end
    popup._itemId = parsedItemId

    local parsedCount = tonumber(itemCount) or tonumber(popup._itemCount) or 1
    if parsedItemId <= 0 then
        parsedCount = 0
    elseif parsedCount < 1 then
        parsedCount = 1
    end
    popup._itemCount = parsedCount

    if type(popup._draftRule) ~= "table" then
        popup._draftRule = createDefaultTimerRule(1)
    end
    popup._draftRule.itemId = parsedItemId
    popup._draftRule.itemCount = parsedCount

    refreshTimerPopupItemButtonVisual()
end

function modules.game_helper.removeTimerPopupItem()
    modules.game_helper.setTimerPopupItemId(0, 0)
end

function modules.game_helper.onTimerPopupItemDrop(targetWidget, draggedWidget, mousePos)
    local popup = getTimerSettingsPopupWidget()
    if not popup then
        return false
    end

    local draggedItemId = getEquipmentPopupDraggedItemId(draggedWidget, mousePos)
    if draggedItemId <= 0 then
        return false
    end

    modules.game_helper.setTimerPopupItemId(draggedItemId, 1)
    return true
end

function modules.game_helper.startTimerPopupItemSelection()
    if not mouseGrabberWidget then
        return
    end

    local popup = getTimerSettingsPopupWidget()

    mouseGrabberWidget:grabMouse()
    if popup then
        popup:hide()
    end
    g_mouse.pushCursor("target")

    mouseGrabberWidget.onMouseRelease = function(self, mousePosition, mouseButton)
        if mouseGrabberWidget then
            mouseGrabberWidget:ungrabMouse()
            mouseGrabberWidget.onMouseRelease = nil
        end
        if popup and not popup:isDestroyed() then
            popup:show()
        end
        g_mouse.popCursor("target")

        if mouseButton ~= MouseLeftButton then
            return true
        end

        local rootWidget = g_ui.getRootWidget()
        if not rootWidget then
            return true
        end

        local clickedWidget = rootWidget:recursiveGetChildByPos(mousePosition, false)
        if not clickedWidget then
            return true
        end

        local item = nil
        if clickedWidget:getClassName() == "UIItem" and not clickedWidget:isVirtual() then
            item = clickedWidget:getItem()
        elseif clickedWidget:getClassName() == "UIGameMap" then
            local tile = clickedWidget:getTile(mousePosition)
            if tile then
                local topUseThing = tile:getTopUseThing()
                if topUseThing and topUseThing:isItem() then
                    item = topUseThing
                end
            end
        end

        if not item then
            modules.game_textmessage.displayFailureMessage(tr("Invalid item!"))
            return true
        end

        modules.game_helper.setTimerPopupItemId(item:getId(), item:getCount())
        return true
    end
end

function modules.game_helper.openTimerPopupItemMenu(button, mousePos)
    local popup = getTimerSettingsPopupWidget()
    if not popup then
        return
    end

    local currentItemId = tonumber(popup._itemId) or 0

    local menu = g_ui.createWidget("HelperPopupMenu")
    menu:setGameMenu(true)
    menu:addOption(tr("Select Item"), function()
        modules.game_helper.startTimerPopupItemSelection()
    end)
    menu:addOption(tr("Assign ID"), function()
        openAssignItemIdWindow(button, "timerPopupItem")
    end)
    menu:addOption(tr("Assign List"), function()
        openAssignItemListWindow(button, "timerPopupItem")
    end)
    if currentItemId > 0 then
        menu:addOption(tr("Remove"), function()
            modules.game_helper.removeTimerPopupItem()
        end)
    end
    menu:display(mousePos or g_window.getMousePosition())
end

function bindTimerSettingsPopupHandlers(window)
    if not window or window:isDestroyed() then
        return
    end
    if window._timerPopupHandlersBound then
        return
    end

    local actionTypeCombo = window:recursiveGetChildById("actionTypeCombo")
    if actionTypeCombo then
        actionTypeCombo:clearOptions()
        actionTypeCombo:addOption("Item")
        actionTypeCombo:addOption("Texto")
        actionTypeCombo.onOptionChange = function()
            modules.game_helper.onTimerPopupActionTypeChange()
        end
    end

    local intervalInput = window:recursiveGetChildById("intervalInput")
    local intervalUnitCombo = window:recursiveGetChildById("intervalUnitCombo")
    if intervalInput then
        local function getTimerIntervalLimits()
            local minVal, maxVal = 1, 60
            if intervalUnitCombo then
                local opt = intervalUnitCombo:getCurrentOption()
                local unitLabel = (opt and opt.text and tostring(opt.text)) or "Minutes"
                if unitLabel == "Hours" then
                    maxVal = 24
                end
            end
            return minVal, maxVal
        end
        intervalInput.onTextChange = function(self)
            local currentText = self:getText() or ""
            local sanitized = currentText:gsub("[^0-9]", "")
            if sanitized ~= currentText then
                self:setText(sanitized)
                self:setCursorPos(-1)
            end
            local minVal, maxVal = getTimerIntervalLimits()
            scheduleNumericInputClamp(self, minVal, maxVal, nil, nil)
        end
        intervalInput.onFocusChange = function(self)
            if self:isFocused() then
                return
            end
            local minVal, maxVal = getTimerIntervalLimits()
            local value = tonumber(self:getText() or "")
            if not value or value < minVal then
                value = minVal
            elseif value > maxVal then
                value = maxVal
            end
            self:setText(tostring(value))
        end
    end

    if intervalUnitCombo then
        intervalUnitCombo:clearOptions()
        intervalUnitCombo:addOption("Seconds")
        intervalUnitCombo:addOption("Minutes")
        intervalUnitCombo:addOption("Hours")
    end

    local itemButton = window:recursiveGetChildById("itemPreviewButton")
    if itemButton then
        itemButton.onDrop = function(self, draggedWidget, mousePos)
            return modules.game_helper.onTimerPopupItemDrop(self, draggedWidget, mousePos)
        end
        itemButton.onMouseRelease = function(self, mousePos, mouseButton)
            if mouseButton ~= MouseLeftButton and mouseButton ~= MouseRightButton then
                return false
            end

            local draggingWidget = g_ui.getDraggingWidget()
            if mouseButton == MouseLeftButton and draggingWidget and modules.game_helper.onTimerPopupItemDrop(self, draggingWidget, mousePos) then
                return true
            end

            modules.game_helper.openTimerPopupItemMenu(self, mousePos)
            return true
        end
    end

    window._timerPopupHandlersBound = true
end

function modules.game_helper.onTimerPopupActionTypeChange()
    updateTimerSettingsPopupActionState()
end

function refreshTimerSettingsPopup()
    local popup = getTimerSettingsPopupWidget()
    if not popup then
        return
    end

    if type(popup._draftRule) ~= "table" then
        popup._draftRule = createDefaultTimerRule(1)
    end
    popup._draftRule = ensureTimerRule(popup._draftRule, 1)

    local popupTitleLabel = popup:recursiveGetChildById("popupTitleLabel")
    if popupTitleLabel then
        popupTitleLabel:setText(popup.isNewRule and "Add Timer" or "Edit Timer")
    end

    local saveButton = popup:recursiveGetChildById("saveButton")
    if saveButton then
        saveButton:setText(popup.isNewRule and "Add" or "Save")
    end

    local actionTypeCombo = popup:recursiveGetChildById("actionTypeCombo")
    if actionTypeCombo then
        actionTypeCombo:setCurrentOption(popup._draftRule.actionType or "Item")
    end

    local cooldownValue, cooldownUnit = timerIntervalToUnitValue(popup._draftRule.interval or 60,
        popup._draftRule.cooldownUnit)
    local intervalInput = popup:recursiveGetChildById("intervalInput")
    if intervalInput then
        intervalInput:setText(tostring(cooldownValue))
    end
    local intervalUnitCombo = popup:recursiveGetChildById("intervalUnitCombo")
    if intervalUnitCombo then
        local unitLabel = (cooldownUnit == "Hours" and "Hours") or (cooldownUnit == "Minutes" and "Minutes") or "Seconds"
        intervalUnitCombo:setCurrentOption(unitLabel)
    end

    local textInput = popup:recursiveGetChildById("wordsInput")
    if textInput then
        textInput:setText(popup._draftRule.chatText or "")
    end

    local runInPzCheck = popup:recursiveGetChildById("runInPzCheck")
    local runOutPzCheck = popup:recursiveGetChildById("runOutPzCheck")
    if runInPzCheck then
        runInPzCheck:setChecked(popup._draftRule.runInPz == true)
    end
    if runOutPzCheck then
        runOutPzCheck:setChecked(popup._draftRule.runOutPz == true)
    end

    popup._itemId = tonumber(popup._draftRule.itemId) or 0
    popup._itemCount = tonumber(popup._draftRule.itemCount) or 0
    refreshTimerPopupItemButtonVisual()
    updateTimerSettingsPopupActionState()
end

function modules.game_helper.closeTimerSettingsPopup()
    if timerSettingsPopup and not timerSettingsPopup:isDestroyed() then
        timerSettingsPopup:destroy()
        timerSettingsPopup = nil
    end
end

function modules.game_helper.saveTimerSettingsPopup()
    ensureTimerConfig()

    local popup = getTimerSettingsPopupWidget()
    if not popup then
        return
    end

    local actionTypeCombo = popup:recursiveGetChildById("actionTypeCombo")
    local intervalInput = popup:recursiveGetChildById("intervalInput")
    local wordsInput = popup:recursiveGetChildById("wordsInput")
    local runInPzCheck = popup:recursiveGetChildById("runInPzCheck")
    local runOutPzCheck = popup:recursiveGetChildById("runOutPzCheck")

    local actionType = "Item"
    if actionTypeCombo then
        local currentOption = actionTypeCombo:getCurrentOption()
        if currentOption and currentOption.text then
            actionType = tostring(currentOption.text)
        end
    end
    actionType = normalizeTimerActionType(actionType)

    local unitLabel = "Minutes"
    local intervalUnitCombo = popup:recursiveGetChildById("intervalUnitCombo")
    if intervalUnitCombo then
        local opt = intervalUnitCombo:getCurrentOption()
        if opt and opt.text then
            unitLabel = tostring(opt.text)
        end
    end
    local cooldownUnit = (unitLabel == "Hours" and "Hours") or (unitLabel == "Minutes" and "Minutes") or "Seconds"
    local intervalValue = tonumber(intervalInput and intervalInput:getText() or "") or 0
    local minVal, maxVal = 1, 60
    if cooldownUnit == "Hours" then
        maxVal = 24
    end
    if intervalValue < minVal or intervalValue > maxVal then
        modules.game_textmessage.displayFailureMessage(tr("Intervalo: ") ..
        minVal .. "-" .. maxVal .. " " .. unitLabel:lower() .. ".")
        return
    end
    local intervalSeconds = timerUnitValueToInterval(intervalValue, cooldownUnit)

    local targetIndex = nil
    if popup.timerIndex ~= nil then
        targetIndex = tonumber(popup.timerIndex) + 1
    end

    local slotIndex = targetIndex or (#(helperConfig.timers or {}) + 1)
    local rule = ensureTimerRule(deepCopy(popup._draftRule or createDefaultTimerRule(slotIndex)), slotIndex)
    rule.actionType = actionType
    rule.interval = intervalSeconds
    rule.cooldownUnit = cooldownUnit
    rule.runInPz = runInPzCheck and runInPzCheck:isChecked() or false
    rule.runOutPz = runOutPzCheck and runOutPzCheck:isChecked() or false

    if actionType == "Item" then
        rule.itemId = tonumber(popup._itemId) or 0
        rule.itemCount = tonumber(popup._itemCount) or 0
        if rule.itemId <= 0 then
            modules.game_textmessage.displayFailureMessage(tr("Select an item for timer action."))
            return
        end
        if rule.itemCount < 1 then
            rule.itemCount = 1
        end
        rule.chatText = ""
    else
        rule.chatText = trimTimerText(wordsInput and wordsInput:getText() or "")
        if rule.chatText == "" then
            modules.game_textmessage.displayFailureMessage(tr("Type the words for timer action."))
            return
        end
        rule.itemId = 0
        rule.itemCount = 0
    end

    local rules = helperConfig.timers or {}
    if targetIndex and rules[targetIndex] then
        local previousEnabled = popup._previousEnabledState
        if previousEnabled == nil then
            previousEnabled = rules[targetIndex].enabled == true
        end
        rule.enabled = previousEnabled == true
        rules[targetIndex] = ensureTimerRule(rule, targetIndex)
    else
        rule.enabled = true
        table.insert(rules, ensureTimerRule(rule, #rules + 1))
    end
    helperConfig.timers = rules

    saveSettings()
    initializeTimers()
    modules.game_helper.closeTimerSettingsPopup()
end

function modules.game_helper.openTimerSettingsPopup(zeroIndex, initialRule, isNewRule)
    if timerSettingsPopup and not timerSettingsPopup:isDestroyed() then
        timerSettingsPopup:destroy()
        timerSettingsPopup = nil
    end

    ensureTimerConfig()

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        modules.game_textmessage.displayFailureMessage(htr("Failed to get root widget."))
        return
    end

    local window = g_ui.loadUI("/mods/game_helper/styles/timer_settings_popup.otui", rootWidget)
    if not window then
        modules.game_textmessage.displayFailureMessage(htr("Failed to load timer settings popup."))
        return
    end

    timerSettingsPopup = window
    applyOpacityToWindow(timerSettingsPopup)
    window.timerIndex = nil
    window.isNewRule = isNewRule == true
    window._previousEnabledState = true

    local parsedZeroIndex = tonumber(zeroIndex)
    if parsedZeroIndex ~= nil then
        local idx = parsedZeroIndex + 1
        if helperConfig.timers and helperConfig.timers[idx] then
            window.timerIndex = parsedZeroIndex
            window._draftRule = deepCopy(ensureTimerRule(helperConfig.timers[idx], idx))
            window._previousEnabledState = helperConfig.timers[idx].enabled == true
            window.isNewRule = false
        end
    end

    if type(window._draftRule) ~= "table" then
        local rules = helperConfig.timers or {}
        local slotIndex = #rules + 1
        window._draftRule = deepCopy(ensureTimerRule(initialRule or createDefaultTimerRule(slotIndex), slotIndex))
        window._draftRule.enabled = true
        window._previousEnabledState = true
        window.isNewRule = true
    end

    bindTimerSettingsPopupHandlers(window)

    window.onDestroy = function()
        timerSettingsPopup = nil
    end

    refreshTimerSettingsPopup()

    local screenSize = rootWidget:getSize()
    local popupSize = window:getSize()
    local centerX = (screenSize.width - popupSize.width) / 2
    local centerY = (screenSize.height - popupSize.height) / 2
    window:setPosition({ x = math.max(0, centerX), y = math.max(0, centerY) })

    window:show()
    window:raise()
    window:focus()
    modalEnter(window)
end

function initializeTimers()
    if not timerPanel then
        return
    end

    if not helperConfig then
        helperConfig = {}
    end
    ensureTimerConfig(TIMER_DEFAULT_RULE_COUNT)
    local removedInvalidRules = pruneIncompleteTimerRules()

    local timerContentPanel = timerPanel:recursiveGetChildById("timerContentPanel")
    if not timerContentPanel then
        return
    end

    local timerList = timerContentPanel:recursiveGetChildById("timerList")
    if not timerList then
        return
    end

    clearTimerRuleSelection()
    timerList:destroyChildren()

    for i = 1, #helperConfig.timers do
        helperConfig.timers[i] = ensureTimerRule(helperConfig.timers[i], i)
        createTimerRuleRow(i - 1, helperConfig.timers[i], timerList)
    end

    if #helperConfig.timers == 0 then
        local emptyLabel = g_ui.createWidget("Label", timerList)
        if emptyLabel then
            emptyLabel:setId("timerRulesEmpty")
            emptyLabel:setText("No timer rules. Click add timer")
            emptyLabel:setColor("#808080")
            emptyLabel:setFont("verdana-11px-monochrome")
            emptyLabel:setMarginTop(4)
            emptyLabel:setMarginLeft(2)
        end
    end
    timerList:updateLayout()
    refreshTimerRuleRowColors()

    local enableModuleCheckbox = timerContentPanel:recursiveGetChildById("enableTimerModule")
    if enableModuleCheckbox then
        enableModuleCheckbox:setChecked(helperConfig.timerEnabled or false)
    end

    stopAllTimers()
    if helperConfig.timerEnabled and helperConfig.timers then
        for i = 1, #helperConfig.timers do
            if helperConfig.timers[i] and helperConfig.timers[i].enabled then
                startTimer(i)
            end
        end
        startTimerRuleCooldownOverlayLoop()
    else
        stopTimerRuleCooldownOverlayLoop()
        refreshAllTimerRuleCooldownOverlays()
    end

    if removedInvalidRules then
        saveSettings()
    end
end

function useTimerItem(itemId, itemCount)
    if not itemId or itemId == 0 then
        return
    end

    if not g_game.isOnline() then
        return
    end

    local player = g_game.getLocalPlayer()
    if not player then
        return
    end

    -- Verificar se tem o item usando hasItemInBackpack (mesma lógica do shooter)
    -- Funciona com backpack fechada, tem fallback para getInventoryCount
    local itemCountInBackpack = hasItemInBackpack(itemId)

    if itemCountInBackpack == 0 then
        return
    end

    -- Usar g_game.useInventoryItem (igual food e portable trader)
    -- Funciona mesmo com containers fechados, procura automaticamente
    helperConfig.magicShooterOnHold = true

    local success = pcall(function()
        g_game.useInventoryItem(itemId)
    end)

    helperConfig.magicShooterOnHold = false
end

function sendTimerChat(text)
    if not text or text == "" then
        g_logger.warning("[Timer] Tentativa de enviar texto vazio")
        return
    end

    if not g_game.isOnline() then
        g_logger.warning("[Timer] Jogo nao esta online, nao pode enviar mensagem")
        return
    end

    -- Enviar como mensagem no local chat (say)
    g_game.talk(text)
end

function updateTimerButton(button)
    if not button then
        return
    end

    local timerIndex = nil
    local buttonId = button:getId()

    -- Tentar extrair do ID do botao
    if buttonId then
        timerIndex = tonumber(buttonId:match("timerItemButton(%d+)"))
    end

    -- Se nao encontrou, tentar extrair do parent
    if not timerIndex then
        local parent = button:getParent()
        if parent then
            local parentId = parent:getId()
            if parentId then
                timerIndex = tonumber(parentId:match("timerEntry(%d+)"))
            end
        end
    end

    if not timerIndex or not helperConfig.timers or not helperConfig.timers[timerIndex] then
        return
    end

    button.onClick = function(self)
        -- Verificar se o timer está enabled, se estiver, não permitir edição
        if helperConfig.timers[timerIndex] and helperConfig.timers[timerIndex].enabled then
            return
        end
        assignTimerItemEvent(button, timerIndex)
    end

    button.onMouseRelease = function(self, mousePos, mouseButton)
        -- Verificar se o timer está enabled, se estiver, não permitir edição
        if helperConfig.timers[timerIndex] and helperConfig.timers[timerIndex].enabled then
            return
        end
        if mouseButton == MouseRightButton then
            local menu = g_ui.createWidget("HelperPopupMenu")
            menu:setGameMenu(true)

            if helperConfig.timers[timerIndex].itemId and helperConfig.timers[timerIndex].itemId > 0 then
                menu:addOption(
                    tr("Edit Item"),
                    function()
                        assignTimerItemEvent(button, timerIndex)
                    end
                )
                menu:addOption(
                    tr("Assign ID"),
                    function()
                        openAssignItemIdWindow(button, "timer", timerIndex)
                    end
                )
                menu:addOption(
                    tr("Assign List"),
                    function()
                        openAssignItemListWindow(button, "timer", timerIndex)
                    end
                )
                menu:addOption(
                    tr("Remove"),
                    function()
                        removeTimerItem(button, timerIndex)
                    end
                )
            else
                menu:addOption(
                    tr("Select Item"),
                    function()
                        assignTimerItemEvent(button, timerIndex)
                    end
                )
                menu:addOption(
                    tr("Assign ID"),
                    function()
                        openAssignItemIdWindow(button, "timer", timerIndex)
                    end
                )
                menu:addOption(
                    tr("Assign List"),
                    function()
                        openAssignItemListWindow(button, "timer", timerIndex)
                    end
                )
            end
            menu:display(mousePos)
            return true
        end
    end
end

function assignTimerItemEvent(button, timerIndex)
    mouseGrabberWidget:grabMouse()
    helper:hide()
    g_mouse.pushCursor("target")
    mouseGrabberWidget.onMouseRelease = function(self, mousePosition, mouseButton)
        onAssignTimerItem(self, mousePosition, mouseButton, button, timerIndex)
    end
end

function onAssignTimerItem(self, mousePosition, mouseButton, button, timerIndex)
    mouseGrabberWidget:ungrabMouse()
    helper:show()
    g_mouse.popCursor("target")
    mouseGrabberWidget.onMouseRelease = nil

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return true
    end

    local clickedWidget = rootWidget:recursiveGetChildByPos(mousePosition, false)
    if not clickedWidget then
        return true
    end

    local itemId = 0
    local itemCount = 1

    if clickedWidget:getClassName() == "UIItem" and not clickedWidget:isVirtual() then
        local item = clickedWidget:getItem()
        if item then
            itemId = item:getId()
            itemCount = item:getCount()
        end
    elseif clickedWidget:getClassName() == "UIGameMap" then
        local tile = clickedWidget:getTile(mousePosition)
        if tile then
            local topUseThing = tile:getTopUseThing()
            if topUseThing and topUseThing:isItem() then
                itemId = topUseThing:getId()
                itemCount = topUseThing:getCount()
            end
        end
    end

    if itemId > 0 then
        updateTimerItemButton(button, itemId, timerIndex, itemCount)
    else
        modules.game_textmessage.displayFailureMessage(tr("Invalid item!"))
    end

    return true
end

function updateTimerItemButton(button, itemId, timerIndex, itemCount)
    if not button or not timerIndex or not helperConfig.timers or not helperConfig.timers[timerIndex] then
        return
    end

    button:setImageSource("/images/ui/item")

    if not button:getChildById("timerItem") then
        local itemWidget = g_ui.createWidget("PotionItem", button)
        itemWidget:setId("timerItem")
    end

    local itemWidget = button:getChildById("timerItem")
    if itemWidget then
        -- Reset count first to avoid keeping old values
        itemWidget:setItemCount(0)
        itemWidget:setItemId(itemId)
        if itemCount and itemCount > 1 then
            itemWidget:setItemCount(itemCount)
        end
    end

    helperConfig.timers[timerIndex].itemId = itemId
    helperConfig.timers[timerIndex].itemCount = itemCount or 1

    local itemName = resolveHelperItemNameById(itemId)
    button:setTooltip(formatHelperItemIdAndName(itemId, itemName))
end

function removeTimerItem(button, timerIndex)
    if not button or not timerIndex or not helperConfig.timers or not helperConfig.timers[timerIndex] then
        return
    end

    button:setImageSource("/images/game/actionbar/slot-actionbar.png")

    local itemWidget = button:getChildById("timerItem")
    if itemWidget then
        itemWidget:setItemId(0)
        itemWidget:setItemCount(0)
    end

    helperConfig.timers[timerIndex].itemId = 0
    helperConfig.timers[timerIndex].itemCount = 0
    button:setTooltip("")
end

function hasActiveTimerRules()
    for _, _ in pairs(timerEvents) do
        return true
    end
    return false
end

function stopTimerExecutionLoop()
    if helperEvents and helperEvents.timerExecutionEvent then
        removeEvent(helperEvents.timerExecutionEvent)
        helperEvents.timerExecutionEvent = nil
    end
end

function runTimerRuleAction(timerIndex, timerData)
    if type(timerData) ~= "table" then
        return
    end

    local actionType = normalizeTimerActionType(timerData.actionType)
    if actionType == "Item" then
        if timerData.itemId and timerData.itemId > 0 then
            useTimerItem(timerData.itemId, timerData.itemCount or 1)
        else
            g_logger.warning("[Timer " .. timerIndex .. "] Configurado para Item mas itemId invalido")
        end
    elseif actionType == "Texto" then
        if timerData.chatText and timerData.chatText ~= "" then
            sendTimerChat(timerData.chatText)
        else
            g_logger.warning("[Timer " .. timerIndex .. "] Configurado para Texto mas chatText vazio")
        end
    else
        g_logger.warning("[Timer " .. timerIndex .. "] ActionType invalido: " .. tostring(actionType))
    end
end

function processTimerRulesInOrder()
    ensureTimerConfig()
    if not helperConfig or not helperConfig.timerEnabled or not hotkeyHelperStatus then
        return
    end
    if not helperConfig.timers then
        return
    end

    local now = g_clock.millis()
    local isOnlineNow = g_game.isOnline()
    local player = isOnlineNow and g_game.getLocalPlayer() or nil
    local inPz = isInPZ
    if player and player.getStates and type(player.getStates) == "function" then
        inPz = bit.band(player:getStates(), PlayerStates.Pz) > 0
    end

    local refreshCooldownUi = false
    for timerIndex = 1, #helperConfig.timers do
        if timerEvents[timerIndex] ~= nil then
            local rule = ensureTimerRule(helperConfig.timers[timerIndex], timerIndex)
            helperConfig.timers[timerIndex] = rule

            if rule.enabled ~= true then
                timerEvents[timerIndex] = nil
            else
                local intervalMs = (tonumber(rule.interval) or 0) * 1000
                if intervalMs <= 0 then
                    timerEvents[timerIndex] = nil
                else
                    local lastExecution = tonumber(rule.lastExecution) or 0
                    local shouldRun = false
                    if lastExecution <= 0 then
                        shouldRun = true
                    elseif (now - lastExecution) >= intervalMs then
                        shouldRun = true
                    end
                    if shouldRun and isOnlineNow and player then
                        local allowInPz = rule.runInPz ~= false
                        local allowOutPz = rule.runOutPz ~= false
                        if (inPz and allowInPz) or ((not inPz) and allowOutPz) then
                            rule.lastExecution = now
                            refreshCooldownUi = true
                            local ok, err = pcall(runTimerRuleAction, timerIndex, rule)
                            if not ok then
                                g_logger.warning("[Timer " .. timerIndex .. "] Error: " .. tostring(err))
                            end
                        end
                    end
                end
            end
        end
    end

    if not hasActiveTimerRules() then
        stopTimerExecutionLoop()
    end

    if refreshCooldownUi then
        refreshAllTimerRuleCooldownOverlays()
    end
end

function startTimerExecutionLoop()
    stopTimerExecutionLoop()

    local function tick()
        if not helperEvents then
            return
        end

        helperEvents.timerExecutionEvent = nil
        if not helperConfig or not helperConfig.timerEnabled then
            return
        end
        if not hasActiveTimerRules() then
            return
        end

        local ok, err = pcall(processTimerRulesInOrder)
        if not ok then
            g_logger.warning("[Timer] Error in processTimerRulesInOrder: " .. tostring(err))
        end

        if helperConfig and helperConfig.timerEnabled and hasActiveTimerRules() then
            helperEvents.timerExecutionEvent = scheduleEvent(tick, 100)
        end
    end

    tick()
end

function startTimer(timerIndex)
    ensureTimerConfig()

    if not helperConfig.timers or not helperConfig.timers[timerIndex] then
        return
    end

    stopTimer(timerIndex)
    local timerData = ensureTimerRule(helperConfig.timers[timerIndex], timerIndex)
    helperConfig.timers[timerIndex] = timerData

    if not helperConfig.timerEnabled then
        return
    end

    if not timerData.enabled or (tonumber(timerData.interval) or 0) <= 0 then
        return
    end

    timerData.lastExecution = 0
    timerEvents[timerIndex] = true

    -- Executar acao na primeira vez logo ao iniciar o timer
    if g_game.isOnline() then
        local player = g_game.getLocalPlayer()
        if player then
            local inPz = isInPZ
            if player.getStates and type(player.getStates) == "function" then
                inPz = bit.band(player:getStates(), PlayerStates.Pz) > 0
            end
            local allowInPz = timerData.runInPz ~= false
            local allowOutPz = timerData.runOutPz ~= false
            if (inPz and allowInPz) or ((not inPz) and allowOutPz) then
                runTimerRuleAction(timerIndex, timerData)
            end
        end
    end
    timerData.lastExecution = g_clock.millis()

    refreshAllTimerRuleCooldownOverlays()
    startTimerExecutionLoop()
end

function stopTimer(timerIndex)
    if timerEvents[timerIndex] then
        timerEvents[timerIndex] = nil
    end
    if not hasActiveTimerRules() then
        stopTimerExecutionLoop()
    end
    refreshAllTimerRuleCooldownOverlays()
end

function stopAllTimers()
    for timerIndex, _ in pairs(timerEvents) do
        timerEvents[timerIndex] = nil
    end
    stopTimerExecutionLoop()
    refreshAllTimerRuleCooldownOverlays()
end

function restartTimer(timerIndex)
    if helperConfig.timers and helperConfig.timers[timerIndex] then
        stopTimer(timerIndex)
        startTimer(timerIndex)
    end
end

