function getItemSlot(slotId)
    if not player then return nil end
    return player:getInventoryItem(slotId)
end

function equipItemFromInventory(itemId)
    if not player then
        return false
    end

    -- Equip item directly using Item.create - works like action bar
    local item = Item.create(itemId)
    if item then
        g_game.equipItem(item)
        return true
    else
        return false
    end
end

function checkTankMode()
    if not helperConfig then
        return
    end

    if not helperConfig.tankModeEnabled then
        return
    end

    -- Atualizar player reference
    player = player or g_game.getLocalPlayer()
    if not player then
        return
    end

    local now = g_clock.millis()

    local function equipAccessory(itemId, cooldownKey)
        -- Server-side resolution (playerEquipItem) already searches bag +
        -- ring/amulet/reward pouches, so no client-side findItemAnywhere or
        -- move-by-coord fallback is needed here. Debounce de 1 tick do
        -- engine de tank mode evita reenviar enquanto o slot atualiza.
        spellsCooldown[cooldownKey] = now + getEngineIntervalValue("tankMode")
        if g_game.equipItemId then
            g_game.equipItemId(itemId, 0)
        else
            local item = Item.create(itemId)
            if item then
                g_game.equipItem(item)
            end
        end
    end

    -- Helper: jogador possui esse id em qualquer lugar (inclui bp fechada via cache do server)?
    local function playerHasItem(itemId)
        if not itemId or itemId == 0 then return false end
        if getItemCountAnywhere then
            return (getItemCountAnywhere(itemId) or 0) > 0
        end
        -- Fallback conservador: assume que tem (preserva comportamento legado)
        return true
    end

    -- Verificar amuleto selecionado
    if helperConfig.tankModeAmuletEnabled ~= false then
        local selectedAmuletId = helperConfig.tankModeAmuletId or 3081
        if selectedAmuletId and selectedAmuletId > 0 then
            local neckSlot = getItemSlot(2) -- Slot do amuleto
            local currentId = neckSlot and neckSlot:getId() or 0

            -- isDynamicMatch cobre o caso em que o id selecionado e o id
            -- equipado pertencem ao mesmo par dynamic (ex.: SSA 3081 vs 3082)
            -- Sem isto, o tick de 100ms reequipa eternamente.
            local alreadyEquipped = currentId == selectedAmuletId
                or isDynamicMatch(selectedAmuletId, currentId)

            local cdActive = (spellsCooldown["amulet"] or 0) > now

            -- Se o player NÃO tem o amuleto preferido (ex.: sem SSA), pula sem
            -- setar cooldown para que o checkEquipmentSwap consiga subir o
            -- amuleto secundário no mesmo tick.
            if not alreadyEquipped and not cdActive and playerHasItem(selectedAmuletId) then
                equipAccessory(selectedAmuletId, "amulet")
            end
        end
    end

    -- Verificar anel selecionado
    if helperConfig.tankModeRingEnabled ~= false then
        local selectedRingId = helperConfig.tankModeRingId or 3048
        if selectedRingId and selectedRingId > 0 then
            local ringSlot = getItemSlot(9) -- Slot do anel
            local currentId = ringSlot and ringSlot:getId() or 0

            -- "Keep Energy Ring" (respectEnergyRing): com a opcao LIGADA, o Energy
            -- Ring (regra HP/MP da aba Healing) tem prioridade sobre o tank mode e
            -- NUNCA e substituido se ja estiver equipado. DESLIGADA (default), o tank
            -- ring pode sobrepor o energy ring normalmente. Antes isso era hardcoded
            -- (sempre mantinha o energy ring), entao o checkbox nao tinha efeito.
            local keepEnergyRing = helperConfig.respectEnergyRing == true
                and (currentId == ENERGY_RING_EQUIPPED_ID
                    or currentId == ENERGY_RING_UNEQUIPPED_ID
                    or isDynamicMatch(ENERGY_RING_EQUIPPED_ID, currentId))

            local alreadyEquipped = currentId == selectedRingId
                or isDynamicMatch(selectedRingId, currentId)

            local cdActive = (spellsCooldown["ring"] or 0) > now

            -- Mesma regra do amuleto: sem o anel preferido (ex.: sem Might Ring),
            -- não bloqueia o slot para que o checkEquipmentSwap suba o anel secundário.
            if not keepEnergyRing and not alreadyEquipped and not cdActive
                and playerHasItem(selectedRingId) then
                equipAccessory(selectedRingId, "ring")
            end
        end
    end
end

-- Register checkTankMode in eventTable (must be after function definition)
eventTable.checkTankMode.action = checkTankMode

