})

function onIconStatsVisibilityChange(iconId, isVisible)
    if not helperConfig or not helperConfig.iconStats then
        return
    end

    if not helperConfig.iconStats.visibleIcons then
        helperConfig.iconStats.visibleIcons = {}
    end

    helperConfig.iconStats.visibleIcons[iconId] = isVisible

    applyIconStatsVisibility(iconId, isVisible)

    saveIconStatsToClientConfig()
end

function applyIconStatsVisibility(iconId, isVisible)
    if not IconStatsModule or not IconStatsModule.window then
        return
    end

    local icon = IconStatsModule.window:recursiveGetChildById(iconId)
    if icon then
        icon:setVisible(isVisible)
    end

    resizeIconStatsWindow()
end

function resizeIconStatsWindow()
    if not IconStatsModule or not IconStatsModule.window then
        return
    end

    if not helperConfig or not helperConfig.iconStats or not helperConfig.iconStats.visibleIcons then
        return
    end

    if helperConfig.iconStats.horizontal then
        resizeIconStatsWindowHorizontal()
        return
    end

    local window = IconStatsModule.window
    local vSeparator1 = window:recursiveGetChildById("vSeparator1")
    local vSeparator2 = window:recursiveGetChildById("vSeparator2")
    local vSeparator3 = window:recursiveGetChildById("vSeparator3")
    if vSeparator1 then
        vSeparator1:setVisible(false)
    end
    if vSeparator2 then
        vSeparator2:setVisible(false)
    end
    if vSeparator3 then
        vSeparator3:setVisible(false)
    end
    local iconOrder = {
        "healingIcon",
        "healFriendIcon",
        "equipmentIcon",
        "tankModeIcon",
        "targetingIcon",
        "shooterIcon",
        "cavebotIcon",
        "timerIcon",
        "helperIcon"
    }

    local visibleCount = 0
    local hasIconsBeforeSeparator = false
    local hasHelperIcon = false
    local visibleIconsList = {}

    for i, iconId in ipairs(iconOrder) do
        local isVisible = helperConfig.iconStats.visibleIcons[iconId]
        if isVisible == nil then
            isVisible = true
        end

        if isVisible then
            visibleCount = visibleCount + 1
            table.insert(visibleIconsList, iconId)
            if i <= 7 then
                hasIconsBeforeSeparator = true
            end
            if iconId == "helperIcon" then
                hasHelperIcon = true
            end
        end
    end

    if visibleCount == 0 then
        window:setSize({ width = 44, height = 10 })
        -- Hide all separators when no icons are visible
        for i = 1, 3 do
            local separator = window:recursiveGetChildById("separator" .. i)
            if separator then
                separator:setVisible(false)
            end
        end
        return
    end

    -- Top separators (separator1 and separator2) are always visible
    local separator1 = window:recursiveGetChildById("separator1")
    if separator1 then
        separator1:setVisible(true)
    end
    local separator2 = window:recursiveGetChildById("separator2")
    if separator2 then
        separator2:setVisible(true)
    end

    -- Separator3 (before helper icon) only visible if there are icons before it AND helper icon is visible
    local separator3 = window:recursiveGetChildById("separator3")
    if separator3 then
        separator3:setVisible(hasIconsBeforeSeparator and hasHelperIcon)
    end

    local iconHeight = 34
    local iconSpacing = 2
    local firstIconTopMargin = 5
    local separatorHeight = 2 -- HorizontalSeparator default height
    local separatorMargin = 4
    local helperIconTopMargin = 4
    local bottomMargin = 1
    local topSeparatorsHeight = (separatorMargin + separatorHeight) * 2 -- Two separators at the top

    local totalHeight = topSeparatorsHeight + firstIconTopMargin

    local iconsBeforeSeparator = 0
    for i = 1, 8 do -- Changed from 7 to 8 to include timerIcon
        local iconId = iconOrder[i]
        local isVisible = helperConfig.iconStats.visibleIcons[iconId]
        if isVisible == nil then
            isVisible = true
        end
        if isVisible then
            iconsBeforeSeparator = iconsBeforeSeparator + 1
        end
    end

    if iconsBeforeSeparator > 0 then
        totalHeight = totalHeight + (iconsBeforeSeparator * iconHeight) + ((iconsBeforeSeparator - 1) * iconSpacing)
    end

    if hasIconsBeforeSeparator and hasHelperIcon then
        totalHeight = totalHeight + separatorMargin + separatorHeight + helperIconTopMargin + iconHeight + bottomMargin
    elseif hasHelperIcon and not hasIconsBeforeSeparator then
        totalHeight = totalHeight + helperIconTopMargin + iconHeight + bottomMargin
    else
        -- No helper icon, but we might still need bottom margin if there are other icons
        if iconsBeforeSeparator > 0 then
            totalHeight = totalHeight + bottomMargin
        end
    end

    window:setSize({ width = 44, height = totalHeight })

    scheduleEvent(function()
        reorganizeIconStatsIcons()
    end, 50)
end

function resizeIconStatsWindowHorizontal()
    if not IconStatsModule or not IconStatsModule.window then
        return
    end

    local window = IconStatsModule.window
    local iconOrder = {
        "healingIcon",
        "healFriendIcon",
        "equipmentIcon",
        "tankModeIcon",
        "targetingIcon",
        "shooterIcon",
        "cavebotIcon",
        "timerIcon",
        "helperIcon"
    }

    local visibleCount = 0
    local iconsBeforeSeparator = 0
    local hasHelperIcon = false

    for i, iconId in ipairs(iconOrder) do
        local isVisible = helperConfig.iconStats.visibleIcons[iconId]
        if isVisible == nil then
            isVisible = true
        end
        if isVisible then
            visibleCount = visibleCount + 1
            if i <= 8 then
                iconsBeforeSeparator = iconsBeforeSeparator + 1
            elseif iconId == "helperIcon" then
                hasHelperIcon = true
            end
        end
    end

    local separator1 = window:recursiveGetChildById("separator1")
    local separator2 = window:recursiveGetChildById("separator2")
    local separator3 = window:recursiveGetChildById("separator3")
    local vSeparator1 = window:recursiveGetChildById("vSeparator1")
    local vSeparator2 = window:recursiveGetChildById("vSeparator2")
    local vSeparator3 = window:recursiveGetChildById("vSeparator3")
    if separator1 then separator1:setVisible(false) end
    if separator2 then separator2:setVisible(false) end
    if separator3 then separator3:setVisible(false) end

    if visibleCount == 0 then
        if vSeparator1 then vSeparator1:setVisible(false) end
        if vSeparator2 then vSeparator2:setVisible(false) end
        if vSeparator3 then vSeparator3:setVisible(false) end
        window:setSize({ width = 10, height = 10 })
        return
    end

    if vSeparator1 then vSeparator1:setVisible(true) end
    if vSeparator2 then vSeparator2:setVisible(true) end
    if vSeparator3 then vSeparator3:setVisible(iconsBeforeSeparator > 0 and hasHelperIcon) end

    local iconSize = 34
    local iconSpacing = 2
    local separatorWidth = 2
    local separatorMargin = 4
    local firstIconLeftMargin = 5
    local helperIconLeftMargin = 4
    local rightMargin = 1
    local leftSeparatorsWidth = (separatorMargin + separatorWidth) * 2
    local totalWidth = leftSeparatorsWidth + firstIconLeftMargin

    if iconsBeforeSeparator > 0 then
        totalWidth = totalWidth + (iconsBeforeSeparator * iconSize) + ((iconsBeforeSeparator - 1) * iconSpacing)
    end

    if iconsBeforeSeparator > 0 and hasHelperIcon then
        totalWidth = totalWidth + separatorMargin + separatorWidth + helperIconLeftMargin + iconSize + rightMargin
    elseif hasHelperIcon and iconsBeforeSeparator == 0 then
        totalWidth = totalWidth + helperIconLeftMargin + iconSize + rightMargin
    elseif iconsBeforeSeparator > 0 then
        totalWidth = totalWidth + rightMargin
    end

    local totalHeight = 44

    window:setSize({ width = totalWidth, height = totalHeight })

    scheduleEvent(function()
        reorganizeIconStatsIconsHorizontal()
    end, 50)
end

function reorganizeIconStatsIcons()
    if not IconStatsModule or not IconStatsModule.window then
        return
    end

    if not helperConfig or not helperConfig.iconStats or not helperConfig.iconStats.visibleIcons then
        return
    end

    if helperConfig.iconStats.horizontal then
        reorganizeIconStatsIconsHorizontal()
        return
    end

    local window = IconStatsModule.window
    local iconOrder = {
        "healingIcon",
        "healFriendIcon",
        "equipmentIcon",
        "tankModeIcon",
        "targetingIcon",
        "shooterIcon",
        "cavebotIcon",
        "timerIcon",
        "helperIcon"
    }

    local visibleIconsBeforeSeparator = {}
    local hasHelperIcon = false

    for i, iconId in ipairs(iconOrder) do
        local icon = window:recursiveGetChildById(iconId)
        if icon then
            local isVisible = helperConfig.iconStats.visibleIcons[iconId]
            if isVisible == nil then
                isVisible = true
            end

            if isVisible then
                if i <= 8 then -- Changed from 7 to 8 to include timerIcon
                    table.insert(visibleIconsBeforeSeparator, { icon = icon, id = iconId })
                elseif iconId == "helperIcon" then
                    hasHelperIcon = true
                end
            else
                icon:setVisible(false)
            end
        end
    end

    local separator2 = window:recursiveGetChildById("separator2")
    local separator3 = window:recursiveGetChildById("separator3")
    local helperIcon = window:recursiveGetChildById("helperIcon")

    local iconHeight = 34
    local iconSpacing = 2
    local firstIconTopMargin = 5
    local windowWidth = window:getWidth() or 44
    local centerX = math.floor(windowWidth / 2)

    for i, iconData in ipairs(visibleIconsBeforeSeparator) do
        local icon = iconData.icon
        icon:setVisible(true)

        if i == 1 then
            -- Anchor first icon to separator2 instead of parent.top
            icon:removeAnchor(AnchorTop)
            icon:removeAnchor(AnchorLeft)
            icon:removeAnchor(AnchorRight)
            icon:removeAnchor(AnchorBottom)
            icon:removeAnchor(AnchorHorizontalCenter)
            icon:removeAnchor(AnchorVerticalCenter)
            icon:addAnchor(AnchorTop, "separator2", AnchorBottom)
            icon:setMarginTop(firstIconTopMargin)
            icon:setMarginLeft(0)
        else
            local prevIcon = visibleIconsBeforeSeparator[i - 1].icon
            icon:removeAnchor(AnchorTop)
            icon:removeAnchor(AnchorLeft)
            icon:removeAnchor(AnchorRight)
            icon:removeAnchor(AnchorBottom)
            icon:removeAnchor(AnchorHorizontalCenter)
            icon:removeAnchor(AnchorVerticalCenter)
            icon:addAnchor(AnchorTop, prevIcon:getId(), AnchorBottom)
            icon:setMarginTop(iconSpacing)
            icon:setMarginLeft(0)
        end
    end

    if separator3 then
        local shouldShowSeparator = #visibleIconsBeforeSeparator > 0 and hasHelperIcon
        separator3:setVisible(shouldShowSeparator)

        if shouldShowSeparator then
            local lastIcon = visibleIconsBeforeSeparator[#visibleIconsBeforeSeparator].icon
            separator3:removeAnchor(AnchorTop)
            separator3:addAnchor(AnchorTop, lastIcon:getId(), AnchorBottom)
            separator3:setMarginTop(4)

            if helperIcon and hasHelperIcon then
                helperIcon:setVisible(true)
                helperIcon:removeAnchor(AnchorTop)
                helperIcon:removeAnchor(AnchorLeft)
                helperIcon:removeAnchor(AnchorRight)
                helperIcon:removeAnchor(AnchorBottom)
                helperIcon:removeAnchor(AnchorHorizontalCenter)
                helperIcon:removeAnchor(AnchorVerticalCenter)
                helperIcon:addAnchor(AnchorTop, separator3:getId(), AnchorBottom)
                helperIcon:setMarginTop(4)
                helperIcon:setMarginLeft(0)
            end
        elseif hasHelperIcon and helperIcon then
            helperIcon:setVisible(true)
            helperIcon:removeAnchor(AnchorTop)
            helperIcon:removeAnchor(AnchorLeft)
            helperIcon:removeAnchor(AnchorRight)
            helperIcon:removeAnchor(AnchorBottom)
            helperIcon:removeAnchor(AnchorHorizontalCenter)
            helperIcon:removeAnchor(AnchorVerticalCenter)
            if #visibleIconsBeforeSeparator > 0 then
                local lastIcon = visibleIconsBeforeSeparator[#visibleIconsBeforeSeparator].icon
                helperIcon:addAnchor(AnchorTop, lastIcon:getId(), AnchorBottom)
                helperIcon:setMarginTop(iconSpacing)
                helperIcon:setMarginLeft(0)
            else
                -- No icons before separator, anchor to separator2
                helperIcon:addAnchor(AnchorTop, "separator2", AnchorBottom)
                helperIcon:setMarginTop(firstIconTopMargin)
                helperIcon:setMarginLeft(0)
            end
        else
            if helperIcon then
                helperIcon:setVisible(false)
            end
        end
    end
end

function reorganizeIconStatsIconsHorizontal()
    if not IconStatsModule or not IconStatsModule.window then
        return
    end

    if not helperConfig or not helperConfig.iconStats or not helperConfig.iconStats.visibleIcons then
        return
    end

    local window = IconStatsModule.window
    local iconOrder = {
        "healingIcon",
        "healFriendIcon",
        "equipmentIcon",
        "tankModeIcon",
        "targetingIcon",
        "shooterIcon",
        "cavebotIcon",
        "timerIcon",
        "helperIcon"
    }

    local visibleIconsBeforeSeparator = {}
    local helperIcon = window:recursiveGetChildById("helperIcon")
    local hasHelperIcon = false
    for _, iconId in ipairs(iconOrder) do
        local icon = window:recursiveGetChildById(iconId)
        if icon then
            local isVisible = helperConfig.iconStats.visibleIcons[iconId]
            if isVisible == nil then
                isVisible = true
            end
            if isVisible then
                if iconId == "helperIcon" then
                    hasHelperIcon = true
                else
                    table.insert(visibleIconsBeforeSeparator, icon)
                end
            else
                icon:setVisible(false)
            end
        end
    end

    local vSeparator1 = window:recursiveGetChildById("vSeparator1")
    local vSeparator2 = window:recursiveGetChildById("vSeparator2")
    local vSeparator3 = window:recursiveGetChildById("vSeparator3")

    local iconSpacing = 2
    local separatorMargin = 4
    local firstIconLeftMargin = 5
    local helperIconLeftMargin = 4
    local hasAnyIcons = (#visibleIconsBeforeSeparator > 0) or hasHelperIcon
    local shouldShowSeparator = (#visibleIconsBeforeSeparator > 0) and hasHelperIcon

    if vSeparator1 then
        vSeparator1:setVisible(hasAnyIcons)
        vSeparator1:removeAnchor(AnchorTop)
        vSeparator1:removeAnchor(AnchorLeft)
        vSeparator1:removeAnchor(AnchorRight)
        vSeparator1:removeAnchor(AnchorBottom)
        vSeparator1:removeAnchor(AnchorHorizontalCenter)
        vSeparator1:removeAnchor(AnchorVerticalCenter)
        vSeparator1:addAnchor(AnchorLeft, "parent", AnchorLeft)
        vSeparator1:addAnchor(AnchorVerticalCenter, "parent", AnchorVerticalCenter)
        vSeparator1:setMarginLeft(separatorMargin)
        vSeparator1:setMarginTop(0)
    end

    if vSeparator2 then
        vSeparator2:setVisible(hasAnyIcons)
        vSeparator2:removeAnchor(AnchorTop)
        vSeparator2:removeAnchor(AnchorLeft)
        vSeparator2:removeAnchor(AnchorRight)
        vSeparator2:removeAnchor(AnchorBottom)
        vSeparator2:removeAnchor(AnchorHorizontalCenter)
        vSeparator2:removeAnchor(AnchorVerticalCenter)
        if vSeparator1 then
            vSeparator2:addAnchor(AnchorLeft, vSeparator1:getId(), AnchorRight)
        else
            vSeparator2:addAnchor(AnchorLeft, "parent", AnchorLeft)
        end
        vSeparator2:addAnchor(AnchorVerticalCenter, "parent", AnchorVerticalCenter)
        vSeparator2:setMarginLeft(separatorMargin)
        vSeparator2:setMarginTop(0)
    end

    for i, icon in ipairs(visibleIconsBeforeSeparator) do
        icon:setVisible(true)
        icon:removeAnchor(AnchorTop)
        icon:removeAnchor(AnchorLeft)
        icon:removeAnchor(AnchorRight)
        icon:removeAnchor(AnchorBottom)
        icon:removeAnchor(AnchorHorizontalCenter)
        icon:removeAnchor(AnchorVerticalCenter)
        icon:setMarginTop(0)

        if i == 1 then
            if vSeparator2 then
                icon:addAnchor(AnchorLeft, vSeparator2:getId(), AnchorRight)
            else
                icon:addAnchor(AnchorLeft, "parent", AnchorLeft)
            end
            icon:setMarginLeft(firstIconLeftMargin)
        else
            local prevIcon = visibleIconsBeforeSeparator[i - 1]
            icon:addAnchor(AnchorLeft, prevIcon:getId(), AnchorRight)
            icon:setMarginLeft(iconSpacing)
        end

        icon:addAnchor(AnchorVerticalCenter, "parent", AnchorVerticalCenter)
    end

    if vSeparator3 then
        vSeparator3:setVisible(shouldShowSeparator)
        if shouldShowSeparator then
            local lastIcon = visibleIconsBeforeSeparator[#visibleIconsBeforeSeparator]
            vSeparator3:removeAnchor(AnchorTop)
            vSeparator3:removeAnchor(AnchorLeft)
            vSeparator3:removeAnchor(AnchorRight)
            vSeparator3:removeAnchor(AnchorBottom)
            vSeparator3:removeAnchor(AnchorHorizontalCenter)
            vSeparator3:removeAnchor(AnchorVerticalCenter)
            vSeparator3:addAnchor(AnchorLeft, lastIcon:getId(), AnchorRight)
            vSeparator3:addAnchor(AnchorVerticalCenter, "parent", AnchorVerticalCenter)
            vSeparator3:setMarginLeft(separatorMargin)
            vSeparator3:setMarginTop(0)
        end
    end

    if helperIcon then
        if hasHelperIcon then
            helperIcon:setVisible(true)
            helperIcon:removeAnchor(AnchorTop)
            helperIcon:removeAnchor(AnchorLeft)
            helperIcon:removeAnchor(AnchorRight)
            helperIcon:removeAnchor(AnchorBottom)
            helperIcon:removeAnchor(AnchorHorizontalCenter)
            helperIcon:removeAnchor(AnchorVerticalCenter)
            helperIcon:setMarginTop(0)

            if #visibleIconsBeforeSeparator > 0 then
                if shouldShowSeparator and vSeparator3 then
                    helperIcon:addAnchor(AnchorLeft, vSeparator3:getId(), AnchorRight)
                    helperIcon:setMarginLeft(helperIconLeftMargin)
                else
                    local lastIcon = visibleIconsBeforeSeparator[#visibleIconsBeforeSeparator]
                    helperIcon:addAnchor(AnchorLeft, lastIcon:getId(), AnchorRight)
                    helperIcon:setMarginLeft(iconSpacing)
                end
            else
                if vSeparator2 then
                    helperIcon:addAnchor(AnchorLeft, vSeparator2:getId(), AnchorRight)
                else
                    helperIcon:addAnchor(AnchorLeft, "parent", AnchorLeft)
                end
                helperIcon:setMarginLeft(firstIconLeftMargin)
            end

            helperIcon:addAnchor(AnchorVerticalCenter, "parent", AnchorVerticalCenter)
        else
            helperIcon:setVisible(false)
        end
    end
end

function applyAllIconStatsVisibility()
    if not helperConfig or not helperConfig.iconStats or not helperConfig.iconStats.visibleIcons then
        return
    end

    if not IconStatsModule or not IconStatsModule.window then
        return
    end

    for iconId, isVisible in pairs(helperConfig.iconStats.visibleIcons) do
        local icon = IconStatsModule.window:recursiveGetChildById(iconId)
        if icon then
            if isVisible == nil then
