function refreshIconStatsKeyLabels()
    local category = "Helper"
    local preset = Keybind.currentPreset
    local chatMode = Keybind.chatMode

    local function normalizePrimaryKey(keys)
        if type(keys) ~= "table" then
            return ""
        end
        local keyText = tostring(keys.primary or "")
        keyText = keyText:gsub("^%s+", ""):gsub("%s+$", "")
        return keyText
    end

    local function getPreferredPrimaryKey(action)
        local keysOn = Keybind.getKeybindKeys(category, action, CHAT_MODE.ON, preset)
        local keysOff = Keybind.getKeybindKeys(category, action, CHAT_MODE.OFF, preset)

        local preferred = ""
        local fallback = ""
        if chatMode == CHAT_MODE.ON then
            preferred = normalizePrimaryKey(keysOn)
            fallback = normalizePrimaryKey(keysOff)
        else
            preferred = normalizePrimaryKey(keysOff)
            fallback = normalizePrimaryKey(keysOn)
        end

        if preferred ~= "" then
            return preferred
        end
        return fallback
    end

    if settingsPanel then
        local keyLabelMap = {
            ["Open Helper"] = "helperWindowKeyLabel",
            ["Toggle Healing"] = "iconStatsHealingKeyLabel",
            ["Toggle Heal Friend"] = "iconStatsHealFriendKeyLabel",
            ["Toggle Equipment"] = "iconStatsEquipmentKeyLabel",
            ["Toggle Tank Mode"] = "iconStatsTankModeKeyLabel",
            ["Toggle Targeting"] = "iconStatsTargetingKeyLabel",
            ["Toggle Shooter"] = "iconStatsShooterKeyLabel",
            ["Toggle Cavebot"] = "iconStatsCavebotKeyLabel",
            ["Toggle Timer"] = "iconStatsTimerKeyLabel",
            ["Toggle Helper Status"] = "iconStatsHelperKeyLabel"
        }

        for action, labelId in pairs(keyLabelMap) do
            local label = settingsPanel:recursiveGetChildById(labelId)
            if label then
                local keyText = getPreferredPrimaryKey(action)
                if keyText == "" then
                    keyText = tr("None")
                end
                label:setText(keyText)
            end
        end
    end

    if helper and not helper:isDestroyed() then
        local autoFollowKeyLabel = helper:recursiveGetChildById("autoFollowKeyLabel")
        if autoFollowKeyLabel then
            local keyText = getPreferredPrimaryKey("Toggle Auto Follow")
            if keyText == "" then
                keyText = tr("None")
            end
            autoFollowKeyLabel:setText(keyText)
        end
    end

    -- Update shooter preset hotkey labels in presets panel
    local presetsPanelRef = presetsPanel or (shooterPanel and shooterPanel:recursiveGetChildById("presetsPanel"))
    if presetsPanelRef then
        local shooterKeyLabelMap = {
            ["Next Shooter Preset"] = "nextPresetKeyLabel",
            ["Previous Shooter Preset"] = "prevPresetKeyLabel"
        }

        for action, labelId in pairs(shooterKeyLabelMap) do
            local label = presetsPanelRef:recursiveGetChildById(labelId)
            if label then
                local keyText = getPreferredPrimaryKey(action)
                if keyText == "" then
                    keyText = tr("None")
                end
                label:setText(keyText)
            end
        end
    end

    local healingPresetsPanelRef = healingPresetsPanel or
    (helper and helper:recursiveGetChildById("healingPresetsPanel"))
    if healingPresetsPanelRef then
        local healingKeyLabelMap = {
            ["Next Healing Preset"] = "healingNextPresetKeyLabel",
            ["Previous Healing Preset"] = "healingPrevPresetKeyLabel"
        }
        for action, labelId in pairs(healingKeyLabelMap) do
            local label = healingPresetsPanelRef:recursiveGetChildById(labelId)
            if label then
                local keyText = getPreferredPrimaryKey(action)
                if keyText == "" then
                    keyText = tr("None")
                end
                label:setText(keyText)
            end
        end
    end

    local equipmentPresetsPanelRef = equipmentPresetsPanel or
    (helper and helper:recursiveGetChildById("equipmentPresetsPanel"))
    if equipmentPresetsPanelRef then
        local equipmentKeyLabelMap = {
            ["Next Equipment Preset"] = "equipmentNextPresetKeyLabel",
            ["Previous Equipment Preset"] = "equipmentPrevPresetKeyLabel"
        }
        for action, labelId in pairs(equipmentKeyLabelMap) do
            local label = equipmentPresetsPanelRef:recursiveGetChildById(labelId)
            if label then
                local keyText = getPreferredPrimaryKey(action)
                if keyText == "" then
                    keyText = tr("None")
                end
                label:setText(keyText)
            end
        end
    end

    local targetingPresetsPanelRef = targetingPresetsPanel or
    (helper and helper:recursiveGetChildById("targetingPresetsPanel"))
    if targetingPresetsPanelRef then
        local targetingKeyLabelMap = {
            ["Next Targeting Preset"] = "targetingNextPresetKeyLabel",
            ["Previous Targeting Preset"] = "targetingPrevPresetKeyLabel"
        }
        for action, labelId in pairs(targetingKeyLabelMap) do
            local label = targetingPresetsPanelRef:recursiveGetChildById(labelId)
            if label then
                local keyText = getPreferredPrimaryKey(action)
                if keyText == "" then
                    keyText = tr("None")
                end
                label:setText(keyText)
            end
        end
    end

    -- Update activate preset hotkey labels for all modules
    local activateModulePanelMap = {
        shooter = { panelRef = presetsPanelRef or (shooterPanel and shooterPanel:recursiveGetChildById("presetsPanel")), labelId = "activatePresetKeyLabel" },
        healing = { panelRef = healingPresetsPanelRef or (helper and helper:recursiveGetChildById("healingPresetsPanel")), labelId = "healingActivatePresetKeyLabel" },
        equipment = { panelRef = equipmentPresetsPanelRef or (helper and helper:recursiveGetChildById("equipmentPresetsPanel")), labelId = "equipmentActivatePresetKeyLabel" },
        targeting = { panelRef = targetingPresetsPanelRef or (helper and helper:recursiveGetChildById("targetingPresetsPanel")), labelId = "targetingActivatePresetKeyLabel" }
    }

    for modType, info in pairs(activateModulePanelMap) do
        local panelRef = info.panelRef
        if panelRef then
            local meta = modulePresetMeta[modType]
            if meta and type(helperConfig) == "table" then
                local selectedName = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
                local actionName = getModulePresetActivationActionName(modType, selectedName)
                if actionName then
                    local label = panelRef:recursiveGetChildById(info.labelId)
                    if label then
                        local keyText = getPreferredPrimaryKey(actionName)
                        if keyText == "" then
                            keyText = tr("None")
                        end
                        label:setText(keyText)
                    end
                end
            end
        end
    end
end

function refreshPresetHotkeyLabelsDeferred()
    if not Keybind or not Keybind.getKeybindKeys then
        return
    end

    refreshIconStatsKeyLabels()

    if presetHotkeyLabelsRefreshEvent then
        removeEvent(presetHotkeyLabelsRefreshEvent)
        presetHotkeyLabelsRefreshEvent = nil
    end
    if presetHotkeyLabelsRefreshRetryEvent then
        removeEvent(presetHotkeyLabelsRefreshRetryEvent)
        presetHotkeyLabelsRefreshRetryEvent = nil
    end

    presetHotkeyLabelsRefreshEvent = scheduleEvent(function()
        presetHotkeyLabelsRefreshEvent = nil
        if helper and not helper:isDestroyed() then
            refreshIconStatsKeyLabels()
        end
    end, 200)

    presetHotkeyLabelsRefreshRetryEvent = scheduleEvent(function()
        presetHotkeyLabelsRefreshRetryEvent = nil
        if helper and not helper:isDestroyed() then
            refreshIconStatsKeyLabels()
        end
    end, 900)
end

