function editIconStatsKeybind(actionName)
    local category = "Helper"
    local action = actionName
    local preset = Keybind.currentPreset
    local chatMode = Keybind.chatMode

    local keybind = Keybind.getAction(category, action)
    if not keybind then
        return
    end

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        return
    end

    local keyEditWindow = g_ui.loadUI("/mods/game_helper/styles/key_edit_new.otui", rootWidget)
    if not keyEditWindow then
        return
    end
    applyOpacityToWindow(keyEditWindow)

    keyEditWindow.keybind = {
        category = category,
        action = action
    }

    -- Set popup title
    local titleLabel = keyEditWindow:recursiveGetChildById('popupTitleLabel')
    if titleLabel then
        titleLabel:setText(tr('Edit Primary Key for \'%s\'', string.format('%s: %s', category, action)))
    end

    -- Update mode label
    local modeLabel = keyEditWindow:recursiveGetChildById('mode')
    if modeLabel then
        local modeText = chatMode == CHAT_MODE.ON and "Chat On" or "Chat Off"
        modeLabel:setText(tr('Mode: "%s"', modeText))
    end

    local keyComboWidget = keyEditWindow:recursiveGetChildById('keyCombo')
    local infoLabel = keyEditWindow:recursiveGetChildById('info')
    local aloneLabel = keyEditWindow:recursiveGetChildById('alone')
    local usedLabel = keyEditWindow:recursiveGetChildById('used')
    local okButton = keyEditWindow:recursiveGetChildById('ok')
    local clearButton = keyEditWindow:recursiveGetChildById('clear')
    local cancelButton = keyEditWindow:recursiveGetChildById('cancel')

    local keys = Keybind.getKeybindKeys(category, action, chatMode, preset)
    keyComboWidget:setText(keys.primary or "")

    local function editKeybindKeyDown(widget, keyCode, keyboardModifiers)
        keyComboWidget:setText(determineKeyComboDesc(keyCode,
            aloneLabel:isVisible() and KeyboardNoModifier or keyboardModifiers))

        local keyCombo = keyComboWidget:getText()
        local keyUsed = Keybind.isKeyComboUsed(keyCombo, category, action, chatMode)

        -- Also check action bar for duplicates
        if not keyUsed and modules.game_actionbar and modules.game_actionbar.isActionBarHotkeyUsed then
            keyUsed = modules.game_actionbar.isActionBarHotkeyUsed(keyCombo)
        end

        -- Also check custom hotkeys
        if not keyUsed and modules.client_options then
            local customHkData = modules.client_options.customHkData
            local customHk_getKeys = modules.client_options.customHk_getKeys
            if customHkData and customHk_getKeys then
                for id = 1, #customHkData do
                    for cm = CHAT_MODE.ON, CHAT_MODE.OFF do
                        local hkKeys = customHk_getKeys(id, cm)
                        if hkKeys and (hkKeys.primary == keyCombo or hkKeys.secondary == keyCombo) then
                            keyUsed = true
                            break
                        end
                    end
                    if keyUsed then break end
                end
            end
        end

        -- Also check standard hotkeys (Keybind.hotkeys)
        if not keyUsed and Keybind.hotkeys then
            for cm = CHAT_MODE.ON, CHAT_MODE.OFF do
                local hotkeys = Keybind.hotkeys[cm] and Keybind.hotkeys[cm][Keybind.currentPreset]
                if hotkeys then
                    for _, hotkey in ipairs(hotkeys) do
                        if hotkey.primary == keyCombo or hotkey.secondary == keyCombo then
                            keyUsed = true
                            break
                        end
                    end
                end
                if keyUsed then break end
            end
        end

        -- Show warning but allow swap (keep OK enabled)
        okButton:setEnabled(true)
        usedLabel:setVisible(keyUsed)
        if keyUsed then
            usedLabel:setText(tr('This hotkey is already in use and will be reassigned.'))
        end
    end

    cancelButton.onClick = function()
        disconnect(keyEditWindow, {
            onKeyDown = editKeybindKeyDown
        })
        keyEditWindow:destroy()
    end

    infoLabel:setText(tr(
        'Click \'Ok\' to assign the keybind. Click \'Clear\' to remove the keybind from \'%s: %s\'.', category,
        action))
    aloneLabel:setVisible(keybind.alone or false)

    connect(keyEditWindow, {
        onKeyDown = editKeybindKeyDown
    })

    okButton.onClick = function()
        local keyCombo = keyComboWidget:getText()

        -- Clear this key from ALL systems before assigning
        if keyCombo ~= '' and modules.client_options and modules.client_options.customHk_resolveKeyConflicts then
            modules.client_options.customHk_resolveKeyConflicts(keyCombo, chatMode)
        end

        Keybind.setPrimaryActionKey(category, action, preset, keyCombo, chatMode)
        g_settings.save()

        disconnect(keyEditWindow, {
            onKeyDown = editKeybindKeyDown
        })
        keyEditWindow:destroy()

        refreshIconStatsKeyLabels()
    end

    clearButton.onClick = function()
        Keybind.setPrimaryActionKey(category, action, preset, "", chatMode)
        g_settings.save()

        disconnect(keyEditWindow, {
            onKeyDown = editKeybindKeyDown
        })
        keyEditWindow:destroy()

        refreshIconStatsKeyLabels()
    end

    -- Center on screen
    local screenSize = rootWidget:getSize()
    local windowSize = keyEditWindow:getSize()
    keyEditWindow:setPosition({
        x = math.floor((screenSize.width - windowSize.width) / 2),
        y = math.floor((screenSize.height - windowSize.height) / 2)
    })

    keyEditWindow:show()
    keyEditWindow:raise()
    keyEditWindow:focus()
    keyEditWindow:grabKeyboard()
    modalEnter(keyEditWindow, { inputLock = false })
end

function editPresetActivateKeybind(moduleType)
    local meta = modulePresetMeta[moduleType]
    if not meta then return end

    local selectedName = tostring(helperConfig[meta.selectedKey] or getModulePresetSlotName(1))
    local actionName = getModulePresetActivationActionName(moduleType, selectedName)
    if not actionName then return end

    editIconStatsKeybind(actionName)
end

function clearIconStatsKeybind(actionName)
    local category = "Helper"
    local action = actionName
    local preset = Keybind.currentPreset
    local chatMode = Keybind.chatMode

    local keys = Keybind.getKeybindKeys(category, action, chatMode, preset)
    local currentKey = keys.primary or ""

    if currentKey == "" then
        modules.game_textmessage.displayFailureMessage(tr("No key configured for this action."))
        return
    end

    local messageBox
    messageBox = helperDisplayGeneralBox(
        tr("Confirm Removal"),
        tr("Are you sure you want to remove hotkey '%s' from action '%s'?"):format(currentKey, action),
        {
            {
                text = tr("No"),
                callback = function()
                    if messageBox and not messageBox:isDestroyed() then
                        messageBox:destroy()
                    end
                end
            },
            {
                text = tr("Yes"),
                callback = function()
                    if messageBox and not messageBox:isDestroyed() then
                        messageBox:destroy()
                    end
                    Keybind.setPrimaryActionKey(category, action, preset, "", chatMode)
                    g_settings.save()
                    refreshIconStatsKeyLabels()
                    modules.game_textmessage.displaySuccessMessage(tr("Hotkey removed successfully."))
                end
            }
        },
        function()
            -- onEnter callback
            if messageBox and not messageBox:isDestroyed() then
                messageBox:destroy()
            end
        end,
        function()
            -- onEscape callback
            if messageBox and not messageBox:isDestroyed() then
                messageBox:destroy()
            end
        end
    )
end

equipmentSettingsPopup = nil

function getEquipmentSettingsConfig(itemType, index)
    if type(helperConfig) ~= "table" then
        return nil
    end

    ensureEquipmentSwapConfig()

    local parsedIndex = tonumber(index)
    if parsedIndex == nil then
        return nil
    end

    if itemType == "amulet" then
        return helperConfig.amulets and helperConfig.amulets[parsedIndex + 1] or nil
    end
    if itemType == "ring" then
        return helperConfig.rings and helperConfig.rings[parsedIndex + 1] or nil
    end
    return nil
end

function getEquipmentSettingsPopupConfig()
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return nil, nil, nil
    end

    local itemType = equipmentSettingsPopup.itemType
    local index = equipmentSettingsPopup.itemIndex
    if not itemType or index == nil then
        return nil, nil, nil
    end

    local config = getEquipmentSettingsConfig(itemType, index)
    return config, itemType, index
end

function resolveEquipmentRuleTypeByItemId(itemId)
    local parsedItemId = tonumber(itemId) or 0
    if parsedItemId <= 0 then
        return nil
    end

    local thingType = g_things.getThingType(parsedItemId, ThingCategoryItem)
    if not thingType or thingType:getId() <= 0 then
        return nil
    end

    local clothSlot = thingType:getClothSlot()
    if clothSlot == 2 then
        return "amulet"
    elseif clothSlot == 9 then
        return "ring"
    end
    return nil
end

function getEquipmentPopupComboText(combo, fallback)
    if not combo then
        return fallback
    end
    local opt = combo:getCurrentOption()
    if not opt or not opt.text or opt.text == "" then
        return fallback
    end
    return opt.text
end

function fillEquipmentPopupComboOptions(combo, options, defaultOption)
    if not combo then
        return
    end

    combo:clearOptions()
    for _, option in ipairs(options) do
        combo:addOption(option)
    end

    combo:setCurrentOption(defaultOption or options[1])
end

function setEquipmentPopupComboValue(combo, desired, fallback)
    if not combo then
        return
    end
    combo:setCurrentOption(desired or fallback)
    local current = combo:getCurrentOption()
    if not current and fallback then
        combo:setCurrentOption(fallback)
    end
end

function updateEquipmentPopupSecondConditionState()
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local joinModeCombo = equipmentSettingsPopup:recursiveGetChildById("conditionJoinMode")
    local condMetric2 = equipmentSettingsPopup:recursiveGetChildById("conditionMetric2")
    local condOperator2 = equipmentSettingsPopup:recursiveGetChildById("conditionOperator2")
    local condValue2 = equipmentSettingsPopup:recursiveGetChildById("conditionValue2")

    local joinMode = string.lower(tostring(getEquipmentPopupComboText(joinModeCombo, "None")))
    local enabled = joinMode ~= "none"
    if condMetric2 then
        condMetric2:setEnabled(enabled)
        condMetric2:setVisible(enabled)
    end
    if condOperator2 then
        condOperator2:setEnabled(enabled)
        condOperator2:setVisible(enabled)
    end
    if condValue2 then
        condValue2:setEnabled(enabled)
        condValue2:setVisible(enabled)
    end
end

function updateEquipmentPopupItemPreview(itemId)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local previewButton = equipmentSettingsPopup:recursiveGetChildById("itemPreviewButton")
    local itemNameLabel = equipmentSettingsPopup:recursiveGetChildById("itemNameLabel")
    local slotHintLabel = equipmentSettingsPopup:recursiveGetChildById("slotHintLabel")

    if not previewButton then
        return
    end

    local parsedItemId = tonumber(itemId) or 0
    local previewItem = previewButton:getChildById("itemPreviewItem")

    if parsedItemId > 0 then
        if not previewItem then
            previewItem = g_ui.createWidget("EquipmentItem", previewButton)
            if previewItem then
                previewItem:setId("itemPreviewItem")
            end
        end
        if previewItem then
            previewItem:setItemId(parsedItemId)
        end
        previewButton:setImageSource("/images/ui/item")
        local itemName = resolveHelperItemNameById(parsedItemId)
        previewButton:setTooltip(formatHelperItemIdAndName(parsedItemId, itemName))

        if itemNameLabel then
            itemNameLabel:setText(formatHelperItemIdAndName(parsedItemId, itemName))
        end

        if slotHintLabel then
            local ruleType = resolveEquipmentRuleTypeByItemId(parsedItemId)
            if ruleType == "amulet" then
                slotHintLabel:setText("Slot: Amulet")
                slotHintLabel:setColor("#a0a0a0")
            elseif ruleType == "ring" then
                slotHintLabel:setText("Slot: Ring")
                slotHintLabel:setColor("#a0a0a0")
            else
                slotHintLabel:setText("Slot: invalid")
                slotHintLabel:setColor("#cc6666")
            end
        end
    else
        if previewItem then
            previewItem:destroy()
        end
        previewButton:setImageSource("/images/game/actionbar/slot-actionbar.png")
        previewButton:setTooltip("")
        if itemNameLabel then itemNameLabel:setText("") end
        if slotHintLabel then
            slotHintLabel:setText("")
            slotHintLabel:setColor("#a0a0a0")
        end
    end
end

function modules.game_helper.onEquipmentPopupItemIdInputChange()
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local mainItemId = tonumber(equipmentSettingsPopup._mainItemId) or 0
    equipmentSettingsPopup._mainItemId = mainItemId
    updateEquipmentPopupItemPreview(mainItemId)
end

function getEquipmentPopupDraftMainItemId()
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return 0
    end

    equipmentSettingsPopup._mainItemId = tonumber(equipmentSettingsPopup._mainItemId) or 0
    return equipmentSettingsPopup._mainItemId
end

function getEquipmentPopupDraftDontExecuteIds()
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return { 0, 0 }
    end
    if type(equipmentSettingsPopup._dontExecuteItemIds) ~= "table" then
        equipmentSettingsPopup._dontExecuteItemIds = { 0, 0 }
    end
    equipmentSettingsPopup._dontExecuteItemIds[1] = tonumber(equipmentSettingsPopup._dontExecuteItemIds[1]) or 0
    equipmentSettingsPopup._dontExecuteItemIds[2] = tonumber(equipmentSettingsPopup._dontExecuteItemIds[2]) or 0
    return equipmentSettingsPopup._dontExecuteItemIds
end

function updateEquipmentPopupSlotButtonVisual(button, itemId, widgetId)
    if not button then
        return
    end

    local parsedItemId = tonumber(itemId) or 0
    local slotItem = button:getChildById(widgetId)

    if parsedItemId > 0 then
        if not slotItem then
            slotItem = g_ui.createWidget("EquipmentItem", button)
            if slotItem then
                slotItem:setId(widgetId)
            end
        end
        if slotItem then
            slotItem:setItemId(parsedItemId)
        end
        button:setImageSource("/images/ui/item")
        local itemName = resolveHelperItemNameById(parsedItemId)
        button:setTooltip(formatHelperItemIdAndName(parsedItemId, itemName))
    else
        if slotItem then
            slotItem:destroy()
        end
        button:setImageSource("/images/game/actionbar/slot-actionbar.png")
        button:setTooltip("")
    end
end

function updateEquipmentPopupDontExecuteSlots()
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local ids = getEquipmentPopupDraftDontExecuteIds()
    local button0 = equipmentSettingsPopup:recursiveGetChildById("dontExecuteItemButton0")
    local button1 = equipmentSettingsPopup:recursiveGetChildById("dontExecuteItemButton1")
    updateEquipmentPopupSlotButtonVisual(button0, ids[1], "dontExecuteItemSlot0")
    updateEquipmentPopupSlotButtonVisual(button1, ids[2], "dontExecuteItemSlot1")
end

function setEquipmentPopupDontExecuteItemId(slotIndex, itemId)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local ids = getEquipmentPopupDraftDontExecuteIds()
    local idx = (tonumber(slotIndex) or 0) + 1
    if idx < 1 or idx > 2 then
        return
    end

    local parsedItemId = tonumber(itemId) or 0
    if parsedItemId > 0 and not resolveEquipmentRuleTypeByItemId(parsedItemId) then
        modules.game_textmessage.displayFailureMessage(tr("Item must be amulet or ring."))
        return
    end

    ids[idx] = parsedItemId
    equipmentSettingsPopup._dontExecuteItemIds = ids
    updateEquipmentPopupDontExecuteSlots()
end

function getEquipmentPopupDraggedItemId(draggedWidget, mousePos)
    local widget = draggedWidget or g_ui.getDraggingWidget()
    local draggedItem = nil

    if widget and widget.currentDragThing and widget.currentDragThing:isItem() then
        draggedItem = widget.currentDragThing
    end

    if not draggedItem and widget and widget.getItem and type(widget.getItem) == "function" then
        local ok, item = pcall(widget.getItem, widget)
        if ok and item and item:isItem() then
            draggedItem = item
        end
    end

    if not draggedItem and mousePos then
        local rootWidget = g_ui.getRootWidget()
        if rootWidget then
            local hovered = rootWidget:recursiveGetChildByPos(mousePos, false)
            if hovered and hovered:getClassName() == "UIItem" and not hovered:isVirtual() then
                draggedItem = hovered:getItem()
            end
        end
    end

    if draggedItem then
        return draggedItem:getId()
    end
    return 0
end

function modules.game_helper.setEquipmentPopupMainItemId(itemId)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local parsedItemId = tonumber(itemId) or 0
    if parsedItemId > 0 and not resolveEquipmentRuleTypeByItemId(parsedItemId) then
        modules.game_textmessage.displayFailureMessage(tr("Item must be amulet or ring."))
        return
    end

    -- Store the unequipped/bag form for dynamic items (rings/amulets) so the rule
    -- id is consistent with what a carried copy has.
    if parsedItemId > 0 and getUnequippedItemId then
        parsedItemId = getUnequippedItemId(parsedItemId) or parsedItemId
    end

    equipmentSettingsPopup._mainItemId = parsedItemId
    modules.game_helper.onEquipmentPopupItemIdInputChange()
end

function modules.game_helper.removeEquipmentPopupSlotItem(slotKind, slotIndex)
    if slotKind == "item" then
        modules.game_helper.setEquipmentPopupMainItemId(0)
    else
        setEquipmentPopupDontExecuteItemId(slotIndex, 0)
    end
end

function modules.game_helper.startEquipmentPopupSlotSelection(slotKind, slotIndex)
    if not mouseGrabberWidget then
        return
    end

    mouseGrabberWidget:grabMouse()
    g_mouse.pushCursor("target")

    mouseGrabberWidget.onMouseRelease = function(self, mousePosition, mouseButton)
        if mouseGrabberWidget then
            mouseGrabberWidget:ungrabMouse()
            mouseGrabberWidget.onMouseRelease = nil
        end
        g_mouse.popCursor("target")

        if mouseButton ~= MouseLeftButton then
            return true
        end

        local rootWidget = g_ui.getRootWidget()
        if not rootWidget then
            return true
        end

        local clickedWidget = rootWidget:recursiveGetChildByPos(mousePosition, false)
        if not clickedWidget then
            return true
        end

        local item = nil
        if clickedWidget:getClassName() == "UIItem" and not clickedWidget:isVirtual() then
            item = clickedWidget:getItem()
        elseif clickedWidget:getClassName() == "UIGameMap" then
            local tile = clickedWidget:getTile(mousePosition)
            if tile then
                local topUseThing = tile:getTopUseThing()
                if topUseThing and topUseThing:isItem() then
                    item = topUseThing
                end
            end
        end

        if not item then
            modules.game_textmessage.displayFailureMessage(tr("Select an amulet or ring item."))
            return true
        end

        local selectedItemId = item:getId()
        if not resolveEquipmentRuleTypeByItemId(selectedItemId) then
            modules.game_textmessage.displayFailureMessage(tr("Item must be amulet or ring."))
            return true
        end

        if slotKind == "item" then
            modules.game_helper.setEquipmentPopupMainItemId(selectedItemId)
        else
            setEquipmentPopupDontExecuteItemId(slotIndex, selectedItemId)
        end
        return true
    end
end

function modules.game_helper.openEquipmentPopupSlotMenu(slotKind, slotIndex, button, mousePos)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local currentId = 0
    if slotKind == "item" then
        currentId = getEquipmentPopupDraftMainItemId()
    else
        local ids = getEquipmentPopupDraftDontExecuteIds()
        currentId = tonumber(ids[(tonumber(slotIndex) or 0) + 1]) or 0
    end

    local menu = g_ui.createWidget("HelperPopupMenu")
    menu:setGameMenu(true)
    local selectLabel = "Select Item"
    local currentType = resolveEquipmentRuleTypeByItemId(currentId)
    if currentType == "ring" then
        selectLabel = "Select Ring"
    elseif currentType == "amulet" then
        selectLabel = "Select Amulet"
    end

    menu:addOption(tr(selectLabel), function()
        modules.game_helper.startEquipmentPopupSlotSelection(slotKind, slotIndex)
    end)
    menu:addOption(tr("Assign ID"), function()
        local assignType = slotKind == "item" and "equipmentPopupItem" or "equipmentPopupDontExecute"
        openAssignItemIdWindow(button, assignType, slotIndex)
    end)
    menu:addOption(tr("Assign List"), function()
        local assignType = slotKind == "item" and "equipmentPopupItem" or "equipmentPopupDontExecute"
        openAssignItemListWindow(button, assignType, slotIndex)
    end)
    if currentId > 0 then
        menu:addOption(tr("Remove"), function()
            modules.game_helper.removeEquipmentPopupSlotItem(slotKind, slotIndex)
        end)
    end
    menu:display(mousePos or g_window.getMousePosition())
end

function modules.game_helper.onEquipmentPopupItemIdDrop(targetWidget, draggedWidget, mousePos)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return false
    end

    local draggedItemId = getEquipmentPopupDraggedItemId(draggedWidget, mousePos)
    if draggedItemId <= 0 then
        return false
    end

    if not resolveEquipmentRuleTypeByItemId(draggedItemId) then
        modules.game_textmessage.displayFailureMessage(tr("Item must be amulet or ring."))
        return false
    end

    local targetId = targetWidget and targetWidget:getId() or ""
    if targetId == "dontExecuteItemButton0" then
        setEquipmentPopupDontExecuteItemId(0, draggedItemId)
    elseif targetId == "dontExecuteItemButton1" then
        setEquipmentPopupDontExecuteItemId(1, draggedItemId)
    else
        modules.game_helper.setEquipmentPopupMainItemId(draggedItemId)
    end

    return true
end

function modules.game_helper.onEquipmentPopupConditionValueChange(widget)
    local value = validatePercentInput(widget, 0, 100, 0)
    if value ~= nil then
        widget:setText(tostring(value))
    end
end

function modules.game_helper.onEquipmentPopupTierTextChange(widget)
    if not widget then return end
    local text = widget:getText() or ""
    local sanitized = text:gsub("[^0-9]", "")
    if sanitized ~= text then
        widget:setText(sanitized)
        if widget.setCursorPos then widget:setCursorPos(-1) end
    end
    scheduleNumericInputClamp(widget, 0, 10, nil, nil)
end

function modules.game_helper.onEquipmentPopupDontExecuteIdTextChange(widget)
    if not widget then return end
    local text = widget:getText() or ""
    local sanitized = text:gsub("[^0-9]", "")
    if sanitized ~= text then
        widget:setText(sanitized)
        if widget.setCursorPos then widget:setCursorPos(-1) end
    end
    scheduleNumericInputClamp(widget, 0, 99999, nil, nil)
end

function modules.game_helper.onEquipmentPopupConditionUseSecondToggle(isChecked)
    updateEquipmentPopupSecondConditionState()
end

function modules.game_helper.onEquipmentPopupJoinModeChange()
    updateEquipmentPopupSecondConditionState()
end

function modules.game_helper.onEquipmentPopupSourceToggle(sourceType, isChecked)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end
    if equipmentSettingsPopup._exclusiveToggleLock then
        return
    end

    local hotkeyCheck = equipmentSettingsPopup:recursiveGetChildById("sourceHotkeyCheck")
    local backpackCheck = equipmentSettingsPopup:recursiveGetChildById("sourceBackpackCheck")
    if not hotkeyCheck or not backpackCheck then
        return
    end

    equipmentSettingsPopup._exclusiveToggleLock = true

    if sourceType == "Hotkey" then
        if isChecked then
            backpackCheck:setChecked(false)
        elseif not backpackCheck:isChecked() then
            hotkeyCheck:setChecked(true)
        end
    else
        if isChecked then
            hotkeyCheck:setChecked(false)
        elseif not hotkeyCheck:isChecked() then
            backpackCheck:setChecked(true)
        end
    end

    equipmentSettingsPopup._exclusiveToggleLock = false
end

function modules.game_helper.onEquipmentPopupActionToggle(actionType, isChecked)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end
    if equipmentSettingsPopup._exclusiveToggleLock then
        return
    end

    local equipCheck = equipmentSettingsPopup:recursiveGetChildById("actionEquipCheck")
    local unequipCheck = equipmentSettingsPopup:recursiveGetChildById("actionUnequipCheck")
    if not equipCheck or not unequipCheck then
        return
    end

    equipmentSettingsPopup._exclusiveToggleLock = true

    if actionType == "Equip" then
        if isChecked then
            unequipCheck:setChecked(false)
        elseif not unequipCheck:isChecked() then
            equipCheck:setChecked(true)
        end
    else
        if isChecked then
            equipCheck:setChecked(false)
        elseif not equipCheck:isChecked() then
            unequipCheck:setChecked(true)
        end
    end

    equipmentSettingsPopup._exclusiveToggleLock = false
end

function modules.game_helper.onEquipmentPopupDontExecuteToggle(isChecked)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local button0 = equipmentSettingsPopup:recursiveGetChildById("dontExecuteItemButton0")
    local button1 = equipmentSettingsPopup:recursiveGetChildById("dontExecuteItemButton1")
    if button0 then
        button0:setEnabled(isChecked)
        button0:setOpacity(isChecked and 1.0 or 0.6)
    end
    if button1 then
        button1:setEnabled(isChecked)
        button1:setOpacity(isChecked and 1.0 or 0.6)
    end
end

function getEquipmentPopupConditionsFromRule(config)
    local firstCondition = {
        metric = config.slot1Metric or "HP%",
        operator = config.slot1Operator or "<=",
        value = tonumber(config.slot1Value) or 0
    }

    local joinMode = tostring(config.conditionJoinMode or ""):lower()
    local secondCondition = nil
    if joinMode == "and" or joinMode == "or" then
        secondCondition = {
            metric = config.slot2Metric or "HP%",
            operator = config.slot2Operator or "<=",
            value = tonumber(config.slot2Value) or 0
        }
    end

    return firstCondition, secondCondition
end

function clearEquipmentPopupConditionsOnRule(config)
    config.alwaysEquipIfNone = false
    config.equipIfHPBelowEnabled = false
    config.equipIfHPAboveEnabled = false
    config.equipIfMPBelowEnabled = false
    config.equipIfMPAboveEnabled = false
end

function applyEquipmentPopupConditionOnRule(config, metric, operator, value)
    local parsedValue = tonumber(value) or 0

    local metricText = tostring(metric or "HP%")
    local operatorText = tostring(operator or "<=")

    if metricText == "MP%" then
        if operatorText == ">=" then
            config.equipIfMPAboveEnabled = true
            config.equipIfMPAbove = parsedValue
        else
            config.equipIfMPBelowEnabled = true
            config.equipIfMPBelow = parsedValue
        end
    else
        if operatorText == ">=" then
            config.equipIfHPAboveEnabled = true
            config.equipIfHPAbove = parsedValue
        else
            config.equipIfHPBelowEnabled = true
            config.equipIfHPBelow = parsedValue
        end
    end
end

function bindEquipmentSettingsPopupHandlers(window)
    if not window or window:isDestroyed() then
        return
    end
    if window._equipmentPopupHandlersBound then
        return
    end

    local metric1 = window:recursiveGetChildById("conditionMetric1")
    local metric2 = window:recursiveGetChildById("conditionMetric2")
    local joinMode = window:recursiveGetChildById("conditionJoinMode")
    local operator1 = window:recursiveGetChildById("conditionOperator1")
    local operator2 = window:recursiveGetChildById("conditionOperator2")
    fillEquipmentPopupComboOptions(metric1, { "HP%", "MP%" }, "HP%")
    fillEquipmentPopupComboOptions(metric2, { "HP%", "MP%" }, "HP%")
    fillEquipmentPopupComboOptions(joinMode, { "None", "AND", "OR" }, "None")
    fillEquipmentPopupComboOptions(operator1, { "<=", ">=" }, "<=")
    fillEquipmentPopupComboOptions(operator2, { "<=", ">=" }, "<=")
    if joinMode then
        joinMode.onOptionChange = function()
            modules.game_helper.onEquipmentPopupJoinModeChange()
        end
    end

    local previewButton = window:recursiveGetChildById("itemPreviewButton")
    local dontExecuteButton0 = window:recursiveGetChildById("dontExecuteItemButton0")
    local dontExecuteButton1 = window:recursiveGetChildById("dontExecuteItemButton1")
    local dropHandler = function(self, draggedWidget, mousePos)
        return modules.game_helper.onEquipmentPopupItemIdDrop(self, draggedWidget, mousePos)
    end
    local releaseHandler = function(self, mousePos, mouseButton, slotKind, slotIndex)
        if mouseButton ~= MouseLeftButton and mouseButton ~= MouseRightButton then
            return false
        end
        local draggingWidget = g_ui.getDraggingWidget()
        if mouseButton == MouseLeftButton and draggingWidget and modules.game_helper.onEquipmentPopupItemIdDrop(self, draggingWidget, mousePos) then
            return true
        end
        modules.game_helper.openEquipmentPopupSlotMenu(slotKind, slotIndex, self, mousePos)
        return true
    end
    if previewButton then
        previewButton.onDrop = dropHandler
        previewButton.onMouseRelease = function(self, mousePos, mouseButton)
            return releaseHandler(self, mousePos, mouseButton, "item", 0)
        end
    end
    if dontExecuteButton0 then
        dontExecuteButton0.onDrop = dropHandler
        dontExecuteButton0.onMouseRelease = function(self, mousePos, mouseButton)
            return releaseHandler(self, mousePos, mouseButton, "dontExecute", 0)
        end
    end
    if dontExecuteButton1 then
        dontExecuteButton1.onDrop = dropHandler
        dontExecuteButton1.onMouseRelease = function(self, mousePos, mouseButton)
            return releaseHandler(self, mousePos, mouseButton, "dontExecute", 1)
        end
    end

    window._equipmentPopupHandlersBound = true
end

function modules.game_helper.closeEquipmentSettingsPopup()
    if equipmentSettingsPopup and not equipmentSettingsPopup:isDestroyed() then
        equipmentSettingsPopup:destroy()
        equipmentSettingsPopup = nil
    end
end

function modules.game_helper.saveEquipmentSettingsPopup()
    local config, itemType, index = getEquipmentSettingsPopupConfig()
    if not config then
        return
    end
    local previousEnabledState = equipmentSettingsPopup and equipmentSettingsPopup._previousEnabledState
    if previousEnabledState == nil then
        previousEnabledState = coerceConfigBool(config.enabled, false)
    end

    local conditionMetric1 = equipmentSettingsPopup:recursiveGetChildById("conditionMetric1")
    local conditionJoinMode = equipmentSettingsPopup:recursiveGetChildById("conditionJoinMode")
    local conditionOperator1 = equipmentSettingsPopup:recursiveGetChildById("conditionOperator1")
    local conditionValue1 = equipmentSettingsPopup:recursiveGetChildById("conditionValue1")
    local conditionMetric2 = equipmentSettingsPopup:recursiveGetChildById("conditionMetric2")
    local conditionOperator2 = equipmentSettingsPopup:recursiveGetChildById("conditionOperator2")
    local conditionValue2 = equipmentSettingsPopup:recursiveGetChildById("conditionValue2")
    local tierInput = equipmentSettingsPopup:recursiveGetChildById("tierInput")
    local sourceBackpackCheck = equipmentSettingsPopup:recursiveGetChildById("sourceBackpackCheck")
    local actionUnequipCheck = equipmentSettingsPopup:recursiveGetChildById("actionUnequipCheck")
    local dontExecuteCheck = equipmentSettingsPopup:recursiveGetChildById("dontExecuteIfEquippedCheck")

    local itemId = getEquipmentPopupDraftMainItemId()
    if itemId <= 0 then
        modules.game_textmessage.displayFailureMessage(tr("Invalid item ID."))
        return
    end

    local resolvedItemType = resolveEquipmentRuleTypeByItemId(itemId)
    if not resolvedItemType then
        modules.game_textmessage.displayFailureMessage(tr("Item must be ring or amulet."))
        return
    end

    clearEquipmentPopupConditionsOnRule(config)

    local metric1 = getEquipmentPopupComboText(conditionMetric1, "HP%")
    local operator1 = getEquipmentPopupComboText(conditionOperator1, "<=")
    local value1 = tonumber(conditionValue1 and conditionValue1:getText() or "") or 0
    local metric2 = getEquipmentPopupComboText(conditionMetric2, "HP%")
    local operator2 = getEquipmentPopupComboText(conditionOperator2, "<=")
    local value2 = tonumber(conditionValue2 and conditionValue2:getText() or "") or 0

    config.slot1Metric = metric1
    config.slot1Operator = operator1
    config.slot1Value = value1
    config.slot2Metric = metric2
    config.slot2Operator = operator2
    config.slot2Value = value2

    applyEquipmentPopupConditionOnRule(config, metric1, operator1, value1)

    local joinModeText = string.lower(tostring(getEquipmentPopupComboText(conditionJoinMode, "None")))
    local useSecond = joinModeText ~= "none"
    if useSecond then
        applyEquipmentPopupConditionOnRule(config, metric2, operator2, value2)
    end

    if not equipmentRuleHasTriggerCondition(config) then
        modules.game_textmessage.displayFailureMessage(tr("Configure at least one condition."))
        return
    end

    config.id = itemId
    config.conditionJoinMode = "none"
    if useSecond then
        if joinModeText == "and" then
            config.conditionJoinMode = "and"
        else
            config.conditionJoinMode = "or"
        end
    end
    config.conditionUseAnd = config.conditionJoinMode == "and"
    config.tier = tonumber(tierInput and tierInput:getText() or "") or 0
    if config.tier < 0 then
        config.tier = 0
    end

    config.sourceType = (sourceBackpackCheck and sourceBackpackCheck:isChecked()) and "Backpack" or "Hotkey"
    config.actionType = (actionUnequipCheck and actionUnequipCheck:isChecked()) and "Unequip" or "Equip"
    config.dontExecuteIfEquipped = dontExecuteCheck and dontExecuteCheck:isChecked() or false
    local dontExecuteIds = getEquipmentPopupDraftDontExecuteIds()
    config.dontExecuteItemIds = { tonumber(dontExecuteIds[1]) or 0, tonumber(dontExecuteIds[2]) or 0 }
    config.dontExecuteItemId = config.dontExecuteItemIds[1] or 0

    local conditionDrunkCheck = equipmentSettingsPopup:recursiveGetChildById("conditionDrunkCheck")
    local conditionRootedCheck = equipmentSettingsPopup:recursiveGetChildById("conditionRootedCheck")
    local conditionFearedCheck = equipmentSettingsPopup:recursiveGetChildById("conditionFearedCheck")
    local conditionParalyzedCheck = equipmentSettingsPopup:recursiveGetChildById("conditionParalyzedCheck")
    local conditionPzCheck = equipmentSettingsPopup:recursiveGetChildById("conditionPzCheck")
    local conditionNonPzCheck = equipmentSettingsPopup:recursiveGetChildById("conditionNonPzCheck")
    local conditionDrowningCheck = equipmentSettingsPopup:recursiveGetChildById("conditionDrowningCheck")
    local conditionUtamoVitaCheck = equipmentSettingsPopup:recursiveGetChildById("conditionUtamoVitaCheck")
    config.conditionDrunk = conditionDrunkCheck and conditionDrunkCheck:isChecked() or false
    config.conditionRooted = conditionRootedCheck and conditionRootedCheck:isChecked() or false
    config.conditionFeared = conditionFearedCheck and conditionFearedCheck:isChecked() or false
    config.conditionParalyzed = conditionParalyzedCheck and conditionParalyzedCheck:isChecked() or false
    config.conditionPz = conditionPzCheck and conditionPzCheck:isChecked() or false
    config.conditionNonPz = conditionNonPzCheck and conditionNonPzCheck:isChecked() or false
    config.conditionDrowning = conditionDrowningCheck and conditionDrowningCheck:isChecked() or false
    config.conditionUtamoVita = conditionUtamoVitaCheck and conditionUtamoVitaCheck:isChecked() or false
    config.enabled = previousEnabledState == true

    if resolvedItemType ~= itemType then
        local sourceKey = itemType == "amulet" and "amulets" or "rings"
        local targetKey = resolvedItemType == "amulet" and "amulets" or "rings"
        local sourceRules = helperConfig[sourceKey] or {}
        local targetRules = helperConfig[targetKey] or {}
        local sourceIndex = tonumber(index) + 1
        local movedRule = sourceRules[sourceIndex]

        if movedRule then
            table.remove(sourceRules, sourceIndex)
            table.insert(targetRules, movedRule)
            helperConfig[sourceKey] = sourceRules
            helperConfig[targetKey] = targetRules
            equipmentSettingsPopup.itemType = resolvedItemType
            equipmentSettingsPopup.itemIndex = #targetRules - 1
        end
    end

    saveSettings()
    modules.game_helper.closeEquipmentSettingsPopup()
end

function openEquipmentSettingsPopup(itemType, index, isNewRule)
    if equipmentSettingsPopup and not equipmentSettingsPopup:isDestroyed() then
        equipmentSettingsPopup:destroy()
        equipmentSettingsPopup = nil
    end

    local rootWidget = g_ui.getRootWidget()
    if not rootWidget then
        modules.game_textmessage.displayFailureMessage(htr("Failed to get root widget."))
        return
    end

    local window = g_ui.loadUI("/mods/game_helper/styles/equipment_settings_popup.otui", rootWidget)
    if not window then
        modules.game_textmessage.displayFailureMessage(htr("Failed to load equipment settings popup."))
        return
    end

    equipmentSettingsPopup = window
    applyOpacityToWindow(equipmentSettingsPopup)
    window.itemType = itemType
    window.itemIndex = index
    window.isNewRule = isNewRule == true
    bindEquipmentSettingsPopupHandlers(window)

    window.onDestroy = function()
        equipmentSettingsPopup = nil
        rebuildAllEquipmentSwapRules()
        updateAllItemCounts()
    end

    refreshEquipmentSettingsPopup()

    local screenSize = rootWidget:getSize()
    local popupSize = window:getSize()
    local centerX = (screenSize.width - popupSize.width) / 2
    local centerY = (screenSize.height - popupSize.height) / 2
    window:setPosition({ x = math.max(0, centerX), y = math.max(0, centerY) })

    window:show()
    window:raise()
    window:focus()
    modalEnter(window)
end

function refreshEquipmentSettingsPopup()
    local config, itemType, index = getEquipmentSettingsPopupConfig()
    if not config then
        return
    end

    config = ensureEquipmentSwapRule(config, itemType, index + 1)
    equipmentSettingsPopup._previousEnabledState = coerceConfigBool(config.enabled, false)

    local popupTitleLabel = equipmentSettingsPopup:recursiveGetChildById("popupTitleLabel")
    if popupTitleLabel then
        popupTitleLabel:setText(equipmentSettingsPopup.isNewRule and "Add Equipment" or "Edit Equipment")
    end

    local saveButton = equipmentSettingsPopup:recursiveGetChildById("saveButton")
    if saveButton then
        saveButton:setText(equipmentSettingsPopup.isNewRule and "Add" or "Save")
    end

    equipmentSettingsPopup._mainItemId = tonumber(config.id) or 0
    modules.game_helper.onEquipmentPopupItemIdInputChange()

    local slot1Metric = config.slot1Metric or "HP%"
    local slot1Operator = config.slot1Operator or "<="
    local slot1Value = tonumber(config.slot1Value) or 0
    local slot2Metric = config.slot2Metric or "HP%"
    local slot2Operator = config.slot2Operator or "<="
    local slot2Value = tonumber(config.slot2Value) or 0

    setEquipmentPopupComboValue(equipmentSettingsPopup:recursiveGetChildById("conditionMetric1"), slot1Metric, "HP%")
    setEquipmentPopupComboValue(equipmentSettingsPopup:recursiveGetChildById("conditionOperator1"), slot1Operator, "<=")

    local conditionValue1 = equipmentSettingsPopup:recursiveGetChildById("conditionValue1")
    if conditionValue1 then
        conditionValue1:setText(tostring(slot1Value))
    end

    local joinModeCombo = equipmentSettingsPopup:recursiveGetChildById("conditionJoinMode")
    local currentJoinMode = tostring(config.conditionJoinMode or ""):lower()
    if currentJoinMode ~= "and" and currentJoinMode ~= "or" and currentJoinMode ~= "none" then
        currentJoinMode = "none"
    end
    if joinModeCombo then
        if currentJoinMode == "and" then
            joinModeCombo:setCurrentOption("AND")
        elseif currentJoinMode == "or" then
            joinModeCombo:setCurrentOption("OR")
        else
            joinModeCombo:setCurrentOption("None")
        end
    end

    setEquipmentPopupComboValue(equipmentSettingsPopup:recursiveGetChildById("conditionMetric2"), slot2Metric, "HP%")
    setEquipmentPopupComboValue(equipmentSettingsPopup:recursiveGetChildById("conditionOperator2"), slot2Operator, "<=")

    local conditionValue2 = equipmentSettingsPopup:recursiveGetChildById("conditionValue2")
    if conditionValue2 then
        conditionValue2:setText(tostring(slot2Value))
    end

    local tierInput = equipmentSettingsPopup:recursiveGetChildById("tierInput")
    if tierInput then
        tierInput:setText(tostring(config.tier or 0))
    end

    -- Redraw the preview so it reflects the loaded rule.
    updateEquipmentPopupItemPreview(tonumber(config.id) or 0)

    equipmentSettingsPopup._exclusiveToggleLock = true

    local sourceHotkeyCheck = equipmentSettingsPopup:recursiveGetChildById("sourceHotkeyCheck")
    local sourceBackpackCheck = equipmentSettingsPopup:recursiveGetChildById("sourceBackpackCheck")
    if sourceHotkeyCheck and sourceBackpackCheck then
        local sourceType = config.sourceType or "Hotkey"
        sourceHotkeyCheck:setChecked(sourceType ~= "Backpack")
        sourceBackpackCheck:setChecked(sourceType == "Backpack")
    end

    local actionEquipCheck = equipmentSettingsPopup:recursiveGetChildById("actionEquipCheck")
    local actionUnequipCheck = equipmentSettingsPopup:recursiveGetChildById("actionUnequipCheck")
    if actionEquipCheck and actionUnequipCheck then
        local actionType = config.actionType or "Equip"
        actionEquipCheck:setChecked(actionType ~= "Unequip")
        actionUnequipCheck:setChecked(actionType == "Unequip")
    end

    equipmentSettingsPopup._exclusiveToggleLock = false

    local dontExecuteCheck = equipmentSettingsPopup:recursiveGetChildById("dontExecuteIfEquippedCheck")
    if dontExecuteCheck then
        dontExecuteCheck:setChecked(config.dontExecuteIfEquipped == true)
    end
    local configuredDontExecuteIds = config.dontExecuteItemIds
    if type(configuredDontExecuteIds) ~= "table" then
        configuredDontExecuteIds = { tonumber(config.dontExecuteItemId) or 0, 0 }
    end
    equipmentSettingsPopup._dontExecuteItemIds = {
        tonumber(configuredDontExecuteIds[1]) or 0,
        tonumber(configuredDontExecuteIds[2]) or 0
    }
    updateEquipmentPopupDontExecuteSlots()
    modules.game_helper.onEquipmentPopupDontExecuteToggle(config.dontExecuteIfEquipped == true)

    local conditionMap = {
        conditionDrunkCheck = config.conditionDrunk == true,
        conditionRootedCheck = config.conditionRooted == true,
        conditionFearedCheck = config.conditionFeared == true,
        conditionParalyzedCheck = config.conditionParalyzed == true,
        conditionPzCheck = config.conditionPz == true,
        conditionNonPzCheck = config.conditionNonPz == true,
        conditionDrowningCheck = config.conditionDrowning == true,
        conditionUtamoVitaCheck = config.conditionUtamoVita == true
    }

    for widgetId, checked in pairs(conditionMap) do
        local checkWidget = equipmentSettingsPopup:recursiveGetChildById(widgetId)
        if checkWidget then
            checkWidget:setChecked(checked)
        end
    end

    updateEquipmentPopupSecondConditionState()
end

function clearAllEquipmentCheckboxes(config)
    if not config then return end

    config.alwaysEquipIfNone = false
    config.equipIfHPBelowEnabled = false
    config.equipIfHPAboveEnabled = false
    config.equipIfMPBelowEnabled = false
    config.equipIfMPAboveEnabled = false

    if equipmentSettingsPopup and not equipmentSettingsPopup:isDestroyed() then
        local equipIfHPBelowInput = equipmentSettingsPopup:recursiveGetChildById("equipIfHPBelowInput")
        if equipIfHPBelowInput then equipIfHPBelowInput:setEnabled(false) end

        local equipIfHPAboveInput = equipmentSettingsPopup:recursiveGetChildById("equipIfHPAboveInput")
        if equipIfHPAboveInput then equipIfHPAboveInput:setEnabled(false) end

        local equipIfMPBelowInput = equipmentSettingsPopup:recursiveGetChildById("equipIfMPBelowInput")
        if equipIfMPBelowInput then equipIfMPBelowInput:setEnabled(false) end

        local equipIfMPAboveInput = equipmentSettingsPopup:recursiveGetChildById("equipIfMPAboveInput")
        if equipIfMPAboveInput then equipIfMPAboveInput:setEnabled(false) end
    end
end

function onEquipmentRadioChange(settingName, checked)
    if not equipmentSettingsPopup or equipmentSettingsPopup:isDestroyed() then
        return
    end

    local itemType = equipmentSettingsPopup.itemType
    local index = equipmentSettingsPopup.itemIndex

    if not itemType or index == nil then
        return
    end

    local config = nil
    if itemType == "amulet" then
        config = helperConfig.amulets[index + 1]
    elseif itemType == "ring" then
        config = helperConfig.rings[index + 1]
    end

    if not config then
        return
    end

    if checked then
        -- Marcar a opcao selecionada
        if settingName == "alwaysEquipIfNone" then
            config.alwaysEquipIfNone = true
        elseif settingName == "equipIfHPBelow" then
            config.equipIfHPBelowEnabled = true
            local equipIfHPBelowInput = equipmentSettingsPopup:recursiveGetChildById("equipIfHPBelowInput")
            if equipIfHPBelowInput then equipIfHPBelowInput:setEnabled(true) end
        elseif settingName == "equipIfHPAbove" then
            config.equipIfHPAboveEnabled = true
            local equipIfHPAboveInput = equipmentSettingsPopup:recursiveGetChildById("equipIfHPAboveInput")
            if equipIfHPAboveInput then equipIfHPAboveInput:setEnabled(true) end
        elseif settingName == "equipIfMPBelow" then
            config.equipIfMPBelowEnabled = true
            local equipIfMPBelowInput = equipmentSettingsPopup:recursiveGetChildById("equipIfMPBelowInput")
            if equipIfMPBelowInput then equipIfMPBelowInput:setEnabled(true) end
        elseif settingName == "equipIfMPAbove" then
            config.equipIfMPAboveEnabled = true
            local equipIfMPAboveInput = equipmentSettingsPopup:recursiveGetChildById("equipIfMPAboveInput")
            if equipIfMPAboveInput then equipIfMPAboveInput:setEnabled(true) end
        end
    else
        -- Se desmarcar, apenas desmarcar essa opcao
        if settingName == "alwaysEquipIfNone" then
            config.alwaysEquipIfNone = false
        elseif settingName == "equipIfHPBelow" then
            config.equipIfHPBelowEnabled = false
            local equipIfHPBelowInput = equipmentSettingsPopup:recursiveGetChildById("equipIfHPBelowInput")
            if equipIfHPBelowInput then equipIfHPBelowInput:setEnabled(false) end
        elseif settingName == "equipIfHPAbove" then
            config.equipIfHPAboveEnabled = false
            local equipIfHPAboveInput = equipmentSettingsPopup:recursiveGetChildById("equipIfHPAboveInput")
            if equipIfHPAboveInput then equipIfHPAboveInput:setEnabled(false) end
        elseif settingName == "equipIfMPBelow" then
            config.equipIfMPBelowEnabled = false
            local equipIfMPBelowInput = equipmentSettingsPopup:recursiveGetChildById("equipIfMPBelowInput")
            if equipIfMPBelowInput then equipIfMPBelowInput:setEnabled(false) end
        elseif settingName == "equipIfMPAbove" then
            config.equipIfMPAboveEnabled = false
            local equipIfMPAboveInput = equipmentSettingsPopup:recursiveGetChildById("equipIfMPAboveInput")
            if equipIfMPAboveInput then equipIfMPAboveInput:setEnabled(false) end
        end
    end

    saveSettings()
end

