-- ==================== DEBUG COMMANDS ====================
-- Comandos de debug para testar o sistema de snapshot

function debugPrintSnapshot()
    if not helperSessionSnapshot then
        print("[Debug] Nenhum snapshot disponível")
        return
    end

    print("[Debug] Snapshot para: " .. tostring(helperSessionSnapshot.characterName))
    print("[Debug] Healing: " .. tostring(helperSessionSnapshot.healingEnabled))
    print("[Debug] Cavebot: " .. tostring(helperSessionSnapshot.cavebotHelperEnabled))
end

function debugForceSnapshot()
    if captureSessionSnapshot() then
        print("[Debug] Snapshot capturado manualmente")
    else
        g_logger.warning("[Debug] Falha ao capturar snapshot manualmente")
        print("[Debug] Falha ao capturar snapshot")
    end
end

function debugForceRestore()
    if restoreSessionSnapshot() then
        print("[Debug] Snapshot restaurado manualmente")
    else
        g_logger.warning("[Debug] Falha ao restaurar snapshot manualmente")
        print("[Debug] Falha ao restaurar snapshot")
    end
end

function debugClearSnapshot()
    clearSessionSnapshot()
    print("[Debug] Snapshot limpo")
end

-- Exportar funções de debug para acesso global
modules.game_helper.debugPrintSnapshot = debugPrintSnapshot
modules.game_helper.debugForceSnapshot = debugForceSnapshot
modules.game_helper.debugForceRestore = debugForceRestore
modules.game_helper.debugClearSnapshot = debugClearSnapshot

